--
-- TOC entry 640 (class 1255 OID 18648)
-- Name: accept_alliance_application(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_alliance_application(p_application_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_alliance_id uuid;
v_applicant_id uuid;
v_user_id uuid;
v_membership record;
v_member_count int;
v_max_members int := 3;
v_existing_member boolean;
v_app_status text;
BEGIN
v_user_id := auth.uid();

IF v_user_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
END IF;

SELECT alliance_id, user_id, status INTO v_alliance_id, v_applicant_id, v_app_status
FROM alliance_applications
WHERE id = p_application_id;

IF v_alliance_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Solicitud no encontrada');
END IF;

IF v_app_status != 'pending' THEN
RETURN jsonb_build_object('success', false, 'error', 'La solicitud ya fue procesada');
END IF;

SELECT * INTO v_membership
FROM alliance_members
WHERE alliance_id = v_alliance_id AND user_id = v_user_id;

IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'No eres miembro de esta alianza');
END IF;

IF NOT COALESCE(v_membership.can_invite, false) THEN
RETURN jsonb_build_object('success', false, 'error', 'No tienes permiso para aceptar solicitudes');
END IF;

SELECT EXISTS(
SELECT 1 FROM alliance_members WHERE user_id = v_applicant_id
) INTO v_existing_member;

IF v_existing_member THEN
UPDATE alliance_applications SET status = 'rejected' WHERE id = p_application_id;
RETURN jsonb_build_object('success', false, 'error', 'El jugador ya pertenece a una alianza');
END IF;

SELECT COUNT(*) INTO v_member_count FROM alliance_members WHERE alliance_id = v_alliance_id;

IF v_member_count >= v_max_members THEN
RETURN jsonb_build_object(
'success', false,
'error', 'La alianza ha alcanzado el limite maximo de ' || v_max_members || ' miembros'
);
END IF;

INSERT INTO alliance_members (alliance_id, user_id)
VALUES (v_alliance_id, v_applicant_id);

UPDATE alliance_applications SET status = 'accepted' WHERE id = p_application_id;

DELETE FROM alliance_applications
WHERE user_id = v_applicant_id
AND status = 'pending'
AND id != p_application_id;

UPDATE alliances SET member_count = v_member_count + 1 WHERE id = v_alliance_id;

RETURN jsonb_build_object('success', true);
END;
$$;


--
-- TOC entry 1089 (class 1255 OID 21549)
-- Name: accept_hero_duel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_hero_duel(p_duel_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_duel record;
  v_balance numeric;
  v_ship record;
  v_creator_ship record;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_duel FROM hero_duels WHERE id = p_duel_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Duelo no encontrado');
  END IF;

  IF v_duel.status != 'waiting' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Este duelo ya no esta disponible');
  END IF;

  IF v_duel.creator_id = v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes aceptar tu propio duelo');
  END IF;

  PERFORM create_hero_ship(v_user_id);
  SELECT * INTO v_ship FROM user_hero_ships WHERE user_id = v_user_id;
  IF v_ship.hp <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tu nave esta daniada. Reparala antes de aceptar un duelo');
  END IF;

  IF v_ship.repair_until IS NOT NULL AND now() < v_ship.repair_until THEN
    RETURN jsonb_build_object('success', false, 'error', 'La nave esta siendo reparada. Espera a que termine');
  END IF;

  IF EXISTS (SELECT 1 FROM hero_duels WHERE (creator_id = v_user_id OR opponent_id = v_user_id) AND status IN ('waiting', 'accepted')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya tienes un duelo activo');
  END IF;

  SELECT * INTO v_creator_ship FROM user_hero_ships WHERE user_id = v_duel.creator_id;
  IF ABS(v_ship.level - v_creator_ship.level) > 5 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Diferencia de nivel maxima: 5. Tu nivel: ' || v_ship.level || ', Rival: ' || v_creator_ship.level);
  END IF;

  SELECT fxu_balance INTO v_balance FROM profiles WHERE id = v_user_id;
  IF v_balance < v_duel.stake THEN
    RETURN jsonb_build_object('success', false, 'error', 'FXU insuficiente. Necesitas: ' || v_duel.stake || ', tienes: ' || FLOOR(v_balance));
  END IF;

  PERFORM _internal_set_fxu_context();
  UPDATE profiles SET fxu_balance = fxu_balance - v_duel.stake WHERE id = v_user_id;

  UPDATE hero_duels SET
    opponent_id = v_user_id,
    status = 'accepted',
    accepted_at = now(),
    resolves_at = now() + interval '10 minutes',
    opponent_hp_before = v_ship.hp,
    opponent_level_before = v_ship.level,
    updated_at = now()
  WHERE id = p_duel_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Duelo aceptado. La batalla comenzara en 10 minutos',
    'resolves_at', (now() + interval '10 minutes')::text
  );
END;
$$;


--
-- TOC entry 1170 (class 1255 OID 22670)
-- Name: activate_daily_streak(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_daily_streak() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_streak record;
  v_cost integer := 10;
  v_balance numeric;
  v_new_streak integer;
  v_best_streak integer;
  v_now timestamptz := now();
  v_expires timestamptz;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RETURN jsonb_build_object('success',false,'error','No autenticado'); END IF;

  SELECT fxu_balance INTO v_balance FROM profiles WHERE id = v_user_id;
  IF v_balance IS NULL OR v_balance < v_cost THEN
    RETURN jsonb_build_object('success',false,'error','FXU insuficiente. Necesitas '||v_cost||' FXU.');
  END IF;

  SELECT streak_count, best_streak, expires_at INTO v_streak FROM user_daily_streaks WHERE user_id = v_user_id;
  v_expires := v_now + interval '24 hours';
  
  IF NOT FOUND OR v_streak.expires_at IS NULL OR v_streak.expires_at < v_now THEN
    v_new_streak := 1;
    v_best_streak := GREATEST(COALESCE(v_streak.best_streak,0), 1);
  ELSE
    v_new_streak := COALESCE(v_streak.streak_count,0) + 1;
    v_best_streak := GREATEST(COALESCE(v_streak.best_streak,0), v_new_streak);
  END IF;

  -- Deduct cost (bypass fxu protection trigger)
  ALTER TABLE profiles DISABLE TRIGGER protect_fxu_balance_trigger;
  UPDATE profiles SET fxu_balance = fxu_balance - v_cost WHERE id = v_user_id;
  ALTER TABLE profiles ENABLE TRIGGER protect_fxu_balance_trigger;

  INSERT INTO user_daily_streaks (user_id, streak_count, best_streak, expires_at, activated_at)
  VALUES (v_user_id, v_new_streak, v_best_streak, v_expires, v_now)
  ON CONFLICT (user_id) DO UPDATE SET
    streak_count = v_new_streak,
    best_streak = GREATEST(user_daily_streaks.best_streak, v_best_streak),
    expires_at = v_expires,
    activated_at = v_now;

  RETURN jsonb_build_object(
    'success',true,
    'streak',v_new_streak,
    'best_streak',v_best_streak,
    'expires_at',v_expires,
    'cost',v_cost,
    'balance',v_balance - v_cost
  );
END;
$$;


