--
-- TOC entry 796 (class 1255 OID 19395)
-- Name: admin_add_to_jackpot(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_add_to_jackpot(p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_is_admin boolean;
  v_available_balance numeric;
  v_new_jackpot_balance numeric;
BEGIN
  v_admin_id := auth.uid();
  
  SELECT is_admin INTO v_is_admin 
  FROM profiles 
  WHERE id = v_admin_id;

  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Amount must be positive';
  END IF;

  -- Check available balance
  v_available_balance := get_admin_available_balance();

  IF v_available_balance < p_amount THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Saldo insuficiente. Disponible: ' || floor(v_available_balance)::text || ' FXU'
    );
  END IF;

  -- Record expense
  INSERT INTO admin_expenses (expense_type, amount, description, related_user_id)
  VALUES ('jackpot_donation', p_amount, 'Donacion al jackpot', v_admin_id);

  -- Add to jackpot
  SELECT contribute_to_jackpot(p_amount, 'admin_deposit', v_admin_id) INTO v_new_jackpot_balance;

  RETURN jsonb_build_object(
    'success', true,
    'new_balance', v_new_jackpot_balance,
    'admin_available_after', v_available_balance - p_amount
  );
END;
$$;


--
-- TOC entry 960 (class 1255 OID 20564)
-- Name: admin_approve_twitter_action(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_approve_twitter_action(p_action_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_action RECORD;
BEGIN
  -- Check if caller is admin
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- Get the action
  SELECT ta.id, ta.user_id, ta.points_awarded, ta.validated, ta.action_type, p.username
  INTO v_action
  FROM twitter_actions ta
  JOIN profiles p ON p.id = ta.user_id
  WHERE ta.id = p_action_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Action not found');
  END IF;

  IF v_action.validated THEN
    RETURN jsonb_build_object('success', true, 'message', 'Already validated');
  END IF;

  -- Mark as validated
  UPDATE twitter_actions SET validated = true WHERE id = p_action_id;

  RETURN jsonb_build_object(
    'success', true,
    'validated', true,
    'username', v_action.username,
    'action_type', v_action.action_type,
    'points', v_action.points_awarded
  );
END;
$$;


--
-- TOC entry 880 (class 1255 OID 20070)
-- Name: admin_audit_suspicious_ships(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_audit_suspicious_ships() RETURNS TABLE(username text, user_id uuid, ship_name text, ship_type_id integer, current_quantity bigint, built_quantity bigint, can_find_in_expedition boolean, suspicious_quantity bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH built_ships AS (
    -- Sum all ships ever built by each user
    SELECT 
      pl.user_id,
      sq.ship_type_id,
      COALESCE(SUM(sq.quantity), 0) as total_built
    FROM shipyard_queue sq
    JOIN planets pl ON sq.planet_id = pl.id
    GROUP BY pl.user_id, sq.ship_type_id
  ),
  current_ships AS (
    -- Sum all ships currently owned by each user (across all planets)
    SELECT 
      pl.user_id,
      ps.ship_type_id,
      COALESCE(SUM(ps.quantity), 0) as total_current
    FROM planet_ships ps
    JOIN planets pl ON ps.planet_id = pl.id
    GROUP BY pl.user_id, ps.ship_type_id
  ),
  expedition_types AS (
    -- Ships that CAN be found in expeditions
    SELECT unnest(ARRAY[7, 8, 9]) as ship_type_id -- light_fighter, heavy_fighter, cruiser
  )
  SELECT 
    p.username,
    cs.user_id,
    st.name as ship_name,
    cs.ship_type_id,
    cs.total_current as current_quantity,
    COALESCE(bs.total_built, 0) as built_quantity,
    EXISTS(SELECT 1 FROM expedition_types et WHERE et.ship_type_id = cs.ship_type_id) as can_find_in_expedition,
    CASE 
      -- For expedition-findable ships, allow some tolerance (up to 100 extra)
      WHEN EXISTS(SELECT 1 FROM expedition_types et WHERE et.ship_type_id = cs.ship_type_id) THEN
        GREATEST(0, cs.total_current - COALESCE(bs.total_built, 0) - 100)
      -- For other ships, any excess is suspicious
      ELSE
        GREATEST(0, cs.total_current - COALESCE(bs.total_built, 0))
    END as suspicious_quantity
  FROM current_ships cs
  JOIN profiles p ON cs.user_id = p.id
  JOIN ship_types st ON cs.ship_type_id = st.id
  LEFT JOIN built_ships bs ON cs.user_id = bs.user_id AND cs.ship_type_id = bs.ship_type_id
  WHERE cs.total_current > COALESCE(bs.total_built, 0)
    AND NOT EXISTS(SELECT 1 FROM expedition_types et WHERE et.ship_type_id = cs.ship_type_id)
  ORDER BY (cs.total_current - COALESCE(bs.total_built, 0)) DESC;
END;
$$;


--
-- TOC entry 962 (class 1255 OID 20566)
-- Name: admin_batch_approve_twitter_actions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_batch_approve_twitter_actions() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  -- Check if caller is admin
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- Approve all pending actions
  WITH updated AS (
    UPDATE twitter_actions 
    SET validated = true 
    WHERE validated = false
    RETURNING id
  )
  SELECT count(*) INTO v_count FROM updated;

  RETURN jsonb_build_object(
    'success', true,
    'validated_count', v_count,
    'message', v_count || ' acciones aprobadas'
  );
END;
$$;


--
-- TOC entry 863 (class 1255 OID 20026)
-- Name: admin_bulk_delete_inactive_accounts(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_bulk_delete_inactive_accounts(p_user_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_is_admin boolean;
  v_deleted_count int := 0;
  v_failed_count int := 0;
  v_user_id uuid;
  v_result jsonb;
BEGIN
  v_admin_id := auth.uid();
  
  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_admin_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Acceso denegado');
  END IF;
  
  FOREACH v_user_id IN ARRAY p_user_ids
  LOOP
    v_result := admin_delete_inactive_account(v_user_id);
    IF (v_result->>'success')::boolean THEN
      v_deleted_count := v_deleted_count + 1;
    ELSE
      v_failed_count := v_failed_count + 1;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count,
    'failed_count', v_failed_count,
    'message', v_deleted_count || ' cuentas eliminadas, ' || v_failed_count || ' fallaron'
  );
END;
$$;


--
-- TOC entry 885 (class 1255 OID 20096)
-- Name: admin_bulk_purge_inactive_accounts(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_bulk_purge_inactive_accounts(p_category text DEFAULT 'never_played'::text, p_days_inactive integer DEFAULT 7, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_is_admin boolean;
  v_deleted_count int := 0;
  v_failed_count int := 0;
  v_user_record record;
  v_result jsonb;
  v_deleted_users jsonb[] := ARRAY[]::jsonb[];
BEGIN
  v_admin_id := auth.uid();
  
  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_admin_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Acceso denegado');
  END IF;

  IF p_category NOT IN ('never_played', 'first_day_only', 'abandoned', 'all') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Categoria invalida. Use: never_played, first_day_only, abandoned, all');
  END IF;

  FOR v_user_record IN 
    SELECT user_id, username 
    FROM admin_get_inactive_accounts_detailed(p_days_inactive, p_category)
    LIMIT p_limit
  LOOP
    v_result := admin_purge_inactive_account(v_user_record.user_id);
    
    IF (v_result->>'success')::boolean THEN
      v_deleted_count := v_deleted_count + 1;
      v_deleted_users := array_append(v_deleted_users, jsonb_build_object(
        'user_id', v_user_record.user_id,
        'username', v_user_record.username
      ));
    ELSE
      v_failed_count := v_failed_count + 1;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'category', p_category,
    'days_inactive_threshold', p_days_inactive,
    'deleted_count', v_deleted_count,
    'failed_count', v_failed_count,
    'deleted_users', v_deleted_users,
    'message', v_deleted_count || ' cuentas eliminadas de categoria "' || p_category || '", ' || v_failed_count || ' fallaron'
  );
END;
$$;


--
-- TOC entry 753 (class 1255 OID 19082)
-- Name: admin_bulk_update_officer_pricing(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_bulk_update_officer_pricing(p_pricing jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_item jsonb;
  v_updated_count integer := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;

  -- Loop through each pricing update
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_pricing)
  LOOP
    UPDATE officer_types
    SET
      dark_matter_cost_7d = (v_item->>'dark_matter_cost_7d')::integer,
      dark_matter_cost_30d = (v_item->>'dark_matter_cost_30d')::integer,
      dark_matter_cost_90d = (v_item->>'dark_matter_cost_90d')::integer,
      fxu_cost_7d = (v_item->>'fxu_cost_7d')::integer,
      fxu_cost_30d = (v_item->>'fxu_cost_30d')::integer,
      fxu_cost_90d = (v_item->>'fxu_cost_90d')::integer
    WHERE id = (v_item->>'id')::uuid;

    v_updated_count := v_updated_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'updated_count', v_updated_count
  );
END;
$$;


--
-- TOC entry 732 (class 1255 OID 19011)
-- Name: admin_cancel_withdrawal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_cancel_withdrawal(p_withdrawal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_withdrawal_id uuid;
  v_withdrawal_status text;
  v_withdrawal_amount numeric;
  v_withdrawal_admin_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  SELECT is_admin INTO v_is_admin
  FROM profiles
  WHERE id = v_user_id;

  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'Solo administradores pueden usar esta funcion';
  END IF;

  SELECT id, status, amount, admin_id 
  INTO v_withdrawal_id, v_withdrawal_status, v_withdrawal_amount, v_withdrawal_admin_id
  FROM admin_withdrawals
  WHERE id = p_withdrawal_id;

  IF v_withdrawal_id IS NULL THEN
    RAISE EXCEPTION 'Retiro no encontrado';
  END IF;

  IF v_withdrawal_admin_id != v_user_id THEN
    RAISE EXCEPTION 'No tienes permiso para cancelar este retiro';
  END IF;

  IF v_withdrawal_status NOT IN ('pending', 'processing', 'failed') THEN
    RAISE EXCEPTION 'Solo se pueden cancelar retiros pendientes, en proceso o fallidos. Estado actual: %', v_withdrawal_status;
  END IF;

  UPDATE admin_withdrawals
  SET status = 'cancelled',
      error_message = 'Cancelado por admin',
      updated_at = now()
  WHERE id = p_withdrawal_id;

  RETURN jsonb_build_object(
    'success', true,
    'cancelled_amount', v_withdrawal_amount,
    'message', 'Retiro cancelado exitosamente'
  );
END;
$$;


--
-- TOC entry 881 (class 1255 OID 20071)
-- Name: admin_clean_fraudulent_ships(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_clean_fraudulent_ships(p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_cleaned_count int := 0;
  v_cleaned_details jsonb := '[]'::jsonb;
  v_record record;
  v_remove_quantity bigint;
BEGIN
  -- Verify admin
  v_admin_id := auth.uid();
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RAISE EXCEPTION 'Access denied: Admin only';
  END IF;

  -- Find and clean fraudulent ships
  FOR v_record IN 
    WITH built_ships AS (
      SELECT 
        pl.user_id,
        sq.ship_type_id,
        COALESCE(SUM(sq.quantity), 0) as total_built
      FROM shipyard_queue sq
      JOIN planets pl ON sq.planet_id = pl.id
      GROUP BY pl.user_id, sq.ship_type_id
    ),
    expedition_types AS (
      SELECT unnest(ARRAY[7, 8, 9]) as ship_type_id
    )
    SELECT 
      ps.id as planet_ship_id,
      ps.planet_id,
      ps.ship_type_id,
      ps.quantity as current_qty,
      COALESCE(bs.total_built, 0) as built_qty,
      pl.user_id,
      p.username,
      st.name as ship_name,
      -- Calculate how many to remove
      CASE 
        WHEN NOT EXISTS(SELECT 1 FROM expedition_types et WHERE et.ship_type_id = ps.ship_type_id) THEN
          -- Non-expedition ships: remove all that weren't built
          ps.quantity - COALESCE(bs.total_built, 0)
        ELSE
          0 -- Don't touch expedition-findable ships
      END as to_remove
    FROM planet_ships ps
    JOIN planets pl ON ps.planet_id = pl.id
    JOIN profiles p ON pl.user_id = p.id
    JOIN ship_types st ON ps.ship_type_id = st.id
    LEFT JOIN built_ships bs ON pl.user_id = bs.user_id AND ps.ship_type_id = bs.ship_type_id
    WHERE ps.quantity > COALESCE(bs.total_built, 0)
      AND NOT EXISTS(SELECT 1 FROM expedition_types et WHERE et.ship_type_id = ps.ship_type_id)
  LOOP
    IF v_record.to_remove > 0 THEN
      v_remove_quantity := LEAST(v_record.to_remove, v_record.current_qty);
      
      IF NOT p_dry_run THEN
        -- Actually remove the fraudulent ships
        UPDATE planet_ships 
        SET quantity = GREATEST(0, quantity - v_remove_quantity)
        WHERE id = v_record.planet_ship_id;
        
        -- Send notification to the user
        INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
        VALUES (NULL, v_record.user_id, 
          'Correccion de Datos',
          format('Se han detectado y corregido %s %s que no tenian registro de construccion valido.', 
            v_remove_quantity, v_record.ship_name),
          'system');
      END IF;
      
      v_cleaned_count := v_cleaned_count + 1;
      v_cleaned_details := v_cleaned_details || jsonb_build_object(
        'username', v_record.username,
        'ship_name', v_record.ship_name,
        'removed', v_remove_quantity,
        'had', v_record.current_qty,
        'should_have', v_record.built_qty
      );
    END IF;
  END LOOP;

  -- Recalculate points for affected users if not dry run
  IF NOT p_dry_run THEN
    PERFORM update_user_points(DISTINCT (detail->>'user_id')::uuid)
    FROM jsonb_array_elements(v_cleaned_details) detail
    WHERE detail->>'user_id' IS NOT NULL;
  END IF;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'items_cleaned', v_cleaned_count,
    'details', v_cleaned_details
  );
END;
$$;


--
-- TOC entry 811 (class 1255 OID 19604)
-- Name: admin_close_round(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_close_round(p_round_name text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_round_id uuid;
  v_round_number integer;
  v_total_players integer;
  v_total_alliances integer;
  v_result jsonb;
BEGIN
  v_admin_id := auth.uid();
  
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores pueden cerrar rondas');
  END IF;
  
  SELECT COALESCE(MAX(round_number), 0) + 1 INTO v_round_number FROM game_rounds;
  
  SELECT COUNT(*) INTO v_total_players FROM profiles;
  SELECT COUNT(*) INTO v_total_alliances FROM alliances;
  
  INSERT INTO game_rounds (round_number, name, ended_at, is_active, total_players, total_alliances, notes)
  VALUES (
    v_round_number,
    COALESCE(p_round_name, 'Ronda ' || v_round_number),
    now(),
    false,
    v_total_players,
    v_total_alliances,
    p_notes
  )
  RETURNING id INTO v_round_id;
  
  -- Save top 10 players for each category
  -- General ranking (by points_total)
  INSERT INTO hall_of_fame_players (round_id, rank, category, username, alliance_tag, points, extra_stats)
  SELECT 
    v_round_id,
    ROW_NUMBER() OVER (ORDER BY p.points_total DESC),
    'general',
    p.username,
    a.tag,
    p.points_total,
    jsonb_build_object(
      'building_points', p.points_buildings,
      'research_points', p.points_research,
      'fleet_points', p.points_fleet,
      'defense_points', p.points_defense
    )
  FROM profiles p
  LEFT JOIN alliance_members am ON am.user_id = p.id
  LEFT JOIN alliances a ON am.alliance_id = a.id
  WHERE p.points_total > 0
  ORDER BY p.points_total DESC
  LIMIT 10;
  
  -- Fleet ranking (by points_fleet)
  INSERT INTO hall_of_fame_players (round_id, rank, category, username, alliance_tag, points)
  SELECT 
    v_round_id,
    ROW_NUMBER() OVER (ORDER BY p.points_fleet DESC),
    'fleet',
    p.username,
    a.tag,
    p.points_fleet
  FROM profiles p
  LEFT JOIN alliance_members am ON am.user_id = p.id
  LEFT JOIN alliances a ON am.alliance_id = a.id
  WHERE p.points_fleet > 0
  ORDER BY p.points_fleet DESC
  LIMIT 10;
  
  -- Research ranking (by points_research)
  INSERT INTO hall_of_fame_players (round_id, rank, category, username, alliance_tag, points)
  SELECT 
    v_round_id,
    ROW_NUMBER() OVER (ORDER BY p.points_research DESC),
    'research',
    p.username,
    a.tag,
    p.points_research
  FROM profiles p
  LEFT JOIN alliance_members am ON am.user_id = p.id
  LEFT JOIN alliances a ON am.alliance_id = a.id
  WHERE p.points_research > 0
  ORDER BY p.points_research DESC
  LIMIT 10;
  
  -- Buildings ranking (by points_buildings)
  INSERT INTO hall_of_fame_players (round_id, rank, category, username, alliance_tag, points)
  SELECT 
    v_round_id,
    ROW_NUMBER() OVER (ORDER BY p.points_buildings DESC),
    'buildings',
    p.username,
    a.tag,
    p.points_buildings
  FROM profiles p
  LEFT JOIN alliance_members am ON am.user_id = p.id
  LEFT JOIN alliances a ON am.alliance_id = a.id
  WHERE p.points_buildings > 0
  ORDER BY p.points_buildings DESC
  LIMIT 10;
  
  -- Battles ranking (by battles_won from profiles)
  INSERT INTO hall_of_fame_players (round_id, rank, category, username, alliance_tag, points, extra_stats)
  SELECT 
    v_round_id,
    ROW_NUMBER() OVER (ORDER BY p.battles_won DESC),
    'battles',
    p.username,
    a.tag,
    p.battles_won,
    jsonb_build_object(
      'battles_total', COALESCE(p.battles_won, 0) + COALESCE(p.battles_lost, 0) + COALESCE(p.battles_draw, 0),
      'battles_lost', p.battles_lost,
      'units_destroyed', p.units_destroyed,
      'units_lost', p.units_lost
    )
  FROM profiles p
  LEFT JOIN alliance_members am ON am.user_id = p.id
  LEFT JOIN alliances a ON am.alliance_id = a.id
  WHERE p.battles_won > 0
  ORDER BY p.battles_won DESC
  LIMIT 10;
  
  -- Expeditions ranking (by points_expedition)
  INSERT INTO hall_of_fame_players (round_id, rank, category, username, alliance_tag, points)
  SELECT 
    v_round_id,
    ROW_NUMBER() OVER (ORDER BY p.points_expedition DESC),
    'expeditions',
    p.username,
    a.tag,
    p.points_expedition
  FROM profiles p
  LEFT JOIN alliance_members am ON am.user_id = p.id
  LEFT JOIN alliances a ON am.alliance_id = a.id
  WHERE p.points_expedition > 0
  ORDER BY p.points_expedition DESC
  LIMIT 10;
  
  -- Save top 10 alliances
  INSERT INTO hall_of_fame_alliances (round_id, rank, alliance_name, alliance_tag, founder_username, member_count, total_points)
  SELECT 
    v_round_id,
    ROW_NUMBER() OVER (ORDER BY COALESCE(SUM(p.points_total), 0) DESC),
    a.name,
    a.tag,
    founder.username,
    COUNT(DISTINCT am.user_id),
    COALESCE(SUM(p.points_total), 0)
  FROM alliances a
  LEFT JOIN alliance_members am ON am.alliance_id = a.id
  LEFT JOIN profiles p ON p.id = am.user_id
  LEFT JOIN profiles founder ON a.founder_id = founder.id
  GROUP BY a.id, a.name, a.tag, founder.username
  HAVING COUNT(DISTINCT am.user_id) > 0
  ORDER BY COALESCE(SUM(p.points_total), 0) DESC
  LIMIT 10;
  
  -- Save special records
  -- Most battles won
  INSERT INTO hall_of_fame_records (round_id, record_type, username, value, description)
  SELECT 
    v_round_id,
    'most_battles_won',
    p.username,
    p.battles_won,
    'Victorias en combate'
  FROM profiles p
  WHERE p.battles_won > 0
  ORDER BY p.battles_won DESC
  LIMIT 1;
  
  -- Most ships destroyed
  INSERT INTO hall_of_fame_records (round_id, record_type, username, value, description)
  SELECT 
    v_round_id,
    'most_ships_destroyed',
    p.username,
    p.units_destroyed,
    'Naves destruidas'
  FROM profiles p
  WHERE p.units_destroyed > 0
  ORDER BY p.units_destroyed DESC
  LIMIT 1;
  
  -- Most debris collected
  INSERT INTO hall_of_fame_records (round_id, record_type, username, value, description)
  SELECT 
    v_round_id,
    'most_debris_collected',
    p.username,
    COALESCE(p.debris_metal_total, 0) + COALESCE(p.debris_crystal_total, 0),
    'Escombros recolectados (metal + cristal)'
  FROM profiles p
  WHERE COALESCE(p.debris_metal_total, 0) + COALESCE(p.debris_crystal_total, 0) > 0
  ORDER BY COALESCE(p.debris_metal_total, 0) + COALESCE(p.debris_crystal_total, 0) DESC
  LIMIT 1;
  
  -- Largest fleet (by fleet points)
  INSERT INTO hall_of_fame_records (round_id, record_type, username, value, description)
  SELECT 
    v_round_id,
    'largest_fleet',
    username,
    points_fleet,
    'Puntos de flota'
  FROM profiles
  WHERE points_fleet > 0
  ORDER BY points_fleet DESC
  LIMIT 1;
  
  -- Most expeditions
  INSERT INTO hall_of_fame_records (round_id, record_type, username, value, description)
  SELECT 
    v_round_id,
    'most_expeditions',
    username,
    points_expedition,
    'Puntos de expedicion'
  FROM profiles
  WHERE points_expedition > 0
  ORDER BY points_expedition DESC
  LIMIT 1;
  
  -- Most colonies (FIXED: use user_id instead of owner_id)
  INSERT INTO hall_of_fame_records (round_id, record_type, username, value, description)
  SELECT 
    v_round_id,
    'most_colonies',
    p.username,
    COUNT(pl.id),
    'Colonias establecidas'
  FROM profiles p
  JOIN planets pl ON pl.user_id = p.id
  GROUP BY p.id, p.username
  HAVING COUNT(pl.id) > 1
  ORDER BY COUNT(pl.id) DESC
  LIMIT 1;
  
  v_result := jsonb_build_object(
    'success', true,
    'round_id', v_round_id,
    'round_number', v_round_number,
    'round_name', COALESCE(p_round_name, 'Ronda ' || v_round_number),
    'total_players', v_total_players,
    'total_alliances', v_total_alliances
  );
  
  RETURN v_result;
END;
$$;


--
-- TOC entry 862 (class 1255 OID 20025)
-- Name: admin_delete_inactive_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_delete_inactive_account(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_is_admin boolean;
  v_target_profile record;
  v_days_inactive int;
BEGIN
  v_admin_id := auth.uid();
  
  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_admin_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Acceso denegado');
  END IF;
  
  SELECT * INTO v_target_profile FROM profiles WHERE id = p_user_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Usuario no encontrado');
  END IF;
  
  IF COALESCE(v_target_profile.is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No se puede eliminar una cuenta de administrador');
  END IF;
  
  v_days_inactive := EXTRACT(DAY FROM (now() - COALESCE(v_target_profile.last_activity, v_target_profile.created_at)))::int;
  
  IF COALESCE(v_target_profile.points_buildings, 0) > 0 THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Esta cuenta tiene edificios construidos (' || v_target_profile.points_buildings || ' puntos)'
    );
  END IF;
  
  DELETE FROM alliance_members WHERE user_id = p_user_id;
  
  DELETE FROM alliance_applications WHERE user_id = p_user_id;
  
  UPDATE fleets 
  SET status = 'cancelled'
  WHERE user_id = p_user_id AND status IN ('traveling', 'returning');
  
  UPDATE fleets 
  SET status = 'returning', arrival_time = now() + ((now() - departure_time) * 0.5)
  WHERE target_user_id = p_user_id AND status = 'traveling';
  
  DELETE FROM messages WHERE sender_id = p_user_id OR recipient_id = p_user_id;
  
  DELETE FROM user_officers WHERE user_id = p_user_id;
  
  DELETE FROM market_listings WHERE seller_id = p_user_id;
  
  DELETE FROM planets WHERE user_id = p_user_id;
  
  DELETE FROM user_technologies WHERE user_id = p_user_id;
  
  DELETE FROM wallet_transactions WHERE user_id = p_user_id;
  
  DELETE FROM profiles WHERE id = p_user_id;
  
  DELETE FROM auth.users WHERE id = p_user_id;
  
  RETURN jsonb_build_object(
    'success', true, 
    'message', 'Cuenta eliminada: ' || v_target_profile.username,
    'days_inactive', v_days_inactive
  );
END;
$$;


--
-- TOC entry 1178 (class 1255 OID 22808)
-- Name: admin_distribute_destruction_pool(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_distribute_destruction_pool() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_pool_balance numeric;
  v_distribution_id uuid;
  v_distributed_count int := 0;
  v_player RECORD;
  v_rank int := 0;
  v_weight numeric;
  v_total_weight numeric := 0;
  v_num_participants int;
  v_reward_percent numeric;
  v_reward_amount numeric;
  v_total_distributed numeric := 0;
  v_distribution_month date;
  v_rewards jsonb := '[]'::jsonb;
  v_first_player_id uuid;
  v_total_calculated numeric := 0;
  v_remainder numeric;
  v_base numeric := 1.3;
  v_i int;
BEGIN
  v_admin_id := auth.uid();

  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  SELECT destruction_balance INTO v_pool_balance FROM jackpot_pools WHERE id = 1;

  IF v_pool_balance IS NULL OR v_pool_balance <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pool de destruccion vacio o sin fondos');
  END IF;

  v_distribution_month := date_trunc('month', now())::date;

  -- Get destruction ranking data into a temp table for processing (TOP 10 only)
  -- NOTE: get_destruction_ranking() already filters by current period via destruction_ranking_reset_at
  CREATE TEMP TABLE temp_dest_dist (
    rank_num int,
    uid uuid,
    uname text,
    dpoints bigint
  ) ON COMMIT DROP;

  INSERT INTO temp_dest_dist (rank_num, uid, uname, dpoints)
  SELECT
    ROW_NUMBER() OVER (ORDER BY dr.destruction_points DESC)::int,
    dr.user_id,
    dr.username,
    dr.destruction_points
  FROM get_destruction_ranking() dr
  LIMIT 10;

  SELECT COUNT(*) INTO v_num_participants FROM temp_dest_dist;

  IF v_num_participants = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No hay jugadores con puntos de destruccion');
  END IF;

  -- Calcular peso total con factor 1.3 para los participantes reales
  FOR v_i IN 1..v_num_participants LOOP
    v_total_weight := v_total_weight + power(v_base, v_num_participants - v_i);
  END LOOP;

  INSERT INTO destruction_ranking_distributions (distribution_month, total_pool_amount, distributed_by)
  VALUES (v_distribution_month, v_pool_balance, v_admin_id)
  ON CONFLICT (distribution_month) DO UPDATE SET
    total_pool_amount = EXCLUDED.total_pool_amount,
    distributed_by = EXCLUDED.distributed_by,
    distributed_at = now()
  RETURNING id INTO v_distribution_id;

  FOR v_player IN
    SELECT rank_num, uid, uname, dpoints FROM temp_dest_dist ORDER BY rank_num
  LOOP
    v_rank := v_player.rank_num;

    IF v_rank = 1 THEN
      v_first_player_id := v_player.uid;
    END IF;

    v_weight := power(v_base, v_num_participants - v_rank);
    v_reward_percent := ROUND((v_weight / v_total_weight) * 100, 2);
    v_reward_amount := FLOOR(v_pool_balance * v_weight / v_total_weight);

    v_rewards := v_rewards || jsonb_build_object(
      'user_id', v_player.uid,
      'username', v_player.uname,
      'rank', v_rank,
      'points', v_player.dpoints,
      'amount', v_reward_amount,
      'percent', v_reward_percent
    );

    v_total_calculated := v_total_calculated + v_reward_amount;
  END LOOP;

  -- Give remainder to #1
  v_remainder := v_pool_balance - v_total_calculated;
  IF v_remainder > 0 AND v_first_player_id IS NOT NULL THEN
    SELECT jsonb_agg(
      CASE
        WHEN (elem->>'user_id')::uuid = v_first_player_id
        THEN jsonb_set(elem, '{amount}', to_jsonb((elem->>'amount')::numeric + v_remainder))
        ELSE elem
      END
    ) INTO v_rewards
    FROM jsonb_array_elements(v_rewards) elem;

    v_total_calculated := v_pool_balance;
  END IF;

  -- Set FXU context to allow balance updates
  PERFORM _internal_set_fxu_context();

  -- Distribute rewards
  FOR v_player IN
    SELECT
      (elem->>'user_id')::uuid as user_id,
      (elem->>'username')::text as username,
      (elem->>'rank')::int as rank,
      (elem->>'points')::bigint as points,
      (elem->>'amount')::numeric as amount,
      (elem->>'percent')::numeric as percent
    FROM jsonb_array_elements(v_rewards) elem
  LOOP
    IF v_player.amount > 0 THEN
      UPDATE profiles SET fxu_balance = fxu_balance + v_player.amount WHERE id = v_player.user_id;

      INSERT INTO destruction_ranking_rewards (distribution_id, user_id, rank_position, destruction_points, reward_amount, reward_percent)
      VALUES (v_distribution_id, v_player.user_id, v_player.rank, v_player.points, v_player.amount, v_player.percent);

      INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
      VALUES (
        v_player.user_id,
        NULL,
        'Recompensa Ranking Destruccion TOP 10',
        'Felicidades Destructor! Puesto #' || v_player.rank || ' - Has recibido ' || v_player.amount || ' FXU (' || v_player.percent || '% del pool de destruccion).',
        'system'
      );

      v_distributed_count := v_distributed_count + 1;
    END IF;
  END LOOP;

  -- Telegram broadcast
  DECLARE
    v_rewards_list_text text := '';
    v_rewards_elem jsonb;
    v_emoji text;
    v_anon_key text;
    v_request_id bigint;
  BEGIN
    FOR v_rewards_elem IN SELECT * FROM jsonb_array_elements(v_rewards)
    LOOP
      IF (v_rewards_elem->>'rank')::int = 1 THEN
        v_emoji := '🏆';
      ELSIF (v_rewards_elem->>'rank')::int <= 3 THEN
        v_emoji := '🥇';
      ELSE
        v_emoji := '🔥';
      END IF;
      v_rewards_list_text := v_rewards_list_text || v_emoji || ' #' || (v_rewards_elem->>'rank') || ' ' || (v_rewards_elem->>'username') || ' - ' || (v_rewards_elem->>'amount') || ' FXU (' || (v_rewards_elem->>'percent') || '%)' || chr(10);
    END LOOP;

    v_rewards_list_text := '🔥 RANKING DESTRUCCION TOP 10 - REPARTO 🔥' || chr(10) || chr(10)
      || '💰 Pool total: ' || v_pool_balance || ' FXU' || chr(10) || chr(10)
      || v_rewards_list_text || chr(10)
      || '¡Felicidades a todos los destructores!' || chr(10)
      || '¿Quieres ganar FXU? ¡Destruye y conquista!' || chr(10)
      || 'Únete: https://t.me/TrungTungMeme';

    INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
    SELECT p.id, NULL, 'Ranking Destruccion - Reparto TOP 10', v_rewards_list_text, 'system'
    FROM profiles p
    WHERE p.id NOT IN (SELECT (elem->>'user_id')::uuid FROM jsonb_array_elements(v_rewards) elem) AND p.is_admin = false;

    BEGIN
      SELECT anon_key INTO v_anon_key FROM market_notification_config WHERE id = 1;

      IF v_anon_key IS NOT NULL THEN
        SELECT net.http_post(
          url := 'https://lvqagudwifvytsptqjxp.supabase.co/functions/v1/send-telegram-broadcast',
          body := jsonb_build_object(
            'subject', 'Ranking Destruccion TOP 10 - Reparto',
            'body', v_rewards_list_text
          ),
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || v_anon_key,
            'apikey', v_anon_key
          )
        ) INTO v_request_id;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        RAISE NOTICE 'Telegram broadcast error: %', SQLERRM;
    END;
  END;

  -- Update distribution record
  UPDATE destruction_ranking_distributions
  SET total_participants = v_distributed_count,
      total_distributed = v_total_calculated
  WHERE id = v_distribution_id;

  -- Reset destruction pool balance to 0
  -- AND set the reset timestamp so get_destruction_ranking() starts a fresh period
  UPDATE jackpot_pools
  SET destruction_balance = 0,
      destruction_ranking_reset_at = NOW(),
      updated_at = now()
  WHERE id = 1;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Pool de destruccion distribuido y ranking reiniciado. Nuevo periodo comienza ahora.',
    'pool_original', v_pool_balance,
    'total_distributed', v_total_calculated,
    'players_rewarded', v_distributed_count,
    'distribution_id', v_distribution_id
  );
END;
$$;


--
-- TOC entry 1168 (class 1255 OID 22625)
-- Name: admin_distribute_fortress_pool(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_distribute_fortress_pool() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pool_balance numeric;
  v_alliance_ids uuid[];
  v_ally_id uuid;
  v_ally_tag text;
  v_num_alliances int;
  v_amount_per_alliance numeric;
  v_member_ids uuid[];
  v_num_members int;
  v_amount_per_member numeric;
  v_total_distributed numeric := 0;
  v_total_recipients int := 0;
  v_distribution_id uuid;
  v_member_id uuid;
  v_is_admin boolean;
  v_existing_date date;
BEGIN
  -- Admin check: allow Supabase admin users AND direct DB connections  
  BEGIN
    -- Try to get the authenticated user
    IF auth.uid() IS NULL THEN
      -- No auth context = direct DB connection (allow)
      v_is_admin := true;
    ELSE
      -- Check if this user is an admin
      SELECT is_admin INTO STRICT v_is_admin FROM profiles WHERE id = auth.uid();
    END IF;
  EXCEPTION 
    WHEN NO_DATA_FOUND THEN v_is_admin := false;
    WHEN OTHERS THEN v_is_admin := true; -- direct DB connection fallback
  END;
  
  IF v_is_admin IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores pueden ejecutar esta accion');
  END IF;

  -- Guard: one distribution per day
  SELECT distribution_date INTO v_existing_date
  FROM fortress_pool_distributions
  WHERE distribution_date = CURRENT_DATE;
  
  IF v_existing_date IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya se distribuyo el pool de fortaleza hoy (' || CURRENT_DATE || ')');
  END IF;

  -- Read pool balance
  SELECT plus_balance INTO v_pool_balance FROM jackpot_pools WHERE id = 1;
  
  IF v_pool_balance IS NULL OR v_pool_balance <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No hay balance en el pool de fortaleza (plus_balance = ' || COALESCE(v_pool_balance, 0) || ')');
  END IF;

  -- Get alliances that own at least one fortress
  SELECT array_agg(DISTINCT owner_alliance_id ORDER BY owner_alliance_id)
  INTO v_alliance_ids
  FROM alliance_fortresses
  WHERE owner_alliance_id IS NOT NULL;

  IF v_alliance_ids IS NULL OR array_length(v_alliance_ids, 1) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No hay alianzas con fortalezas capturadas');
  END IF;

  v_num_alliances := array_length(v_alliance_ids, 1);
  v_amount_per_alliance := FLOOR(v_pool_balance / v_num_alliances);

  -- Bypass the fxu_balance protection trigger for distribution
  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);

  -- Create distribution record
  INSERT INTO fortress_pool_distributions (
    distribution_date, total_pool_amount, total_alliances, distributed_by
  ) VALUES (
    CURRENT_DATE, v_pool_balance, v_num_alliances, COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid)
  )
  RETURNING id INTO v_distribution_id;

  -- Distribute to each alliance
  FOREACH v_ally_id IN ARRAY v_alliance_ids
  LOOP
    -- Get alliance tag
    SELECT tag INTO v_ally_tag FROM alliances WHERE id = v_ally_id;

    -- Get alliance members
    SELECT array_agg(user_id ORDER BY user_id)
    INTO v_member_ids
    FROM alliance_members
    WHERE alliance_id = v_ally_id;

    IF v_member_ids IS NULL OR array_length(v_member_ids, 1) = 0 THEN
      CONTINUE; -- skip empty alliances
    END IF;

    v_num_members := array_length(v_member_ids, 1);
    v_amount_per_member := FLOOR(v_amount_per_alliance / v_num_members);

    -- Credit each member
    FOREACH v_member_id IN ARRAY v_member_ids
    LOOP
      -- Add FXU to wallet
      UPDATE profiles 
      SET fxu_balance = fxu_balance + v_amount_per_member
      WHERE id = v_member_id;

      -- Record reward
      INSERT INTO fortress_pool_rewards (
        distribution_id, user_id, alliance_id, alliance_tag, reward_amount
      ) VALUES (
        v_distribution_id, v_member_id, v_ally_id, v_ally_tag, v_amount_per_member
      );

      -- Notify player
      INSERT INTO messages (recipient_id, sender_id, subject, body, message_type, created_at)
      VALUES (
        v_member_id, NULL,
        'Recompensa de Fortaleza',
        '🏰 ¡Tu alianza ' || COALESCE(v_ally_tag, 'Desconocida') || ' controla una fortaleza!' || E'

' ||
        'Has recibido ' || v_amount_per_member || ' FXU como recompensa diaria.' || E'

' ||
        'Mantengan el control de la fortaleza para seguir recibiendo recompensas.',
        'system', now()
      );

      v_total_distributed := v_total_distributed + v_amount_per_member;
      v_total_recipients := v_total_recipients + 1;
    END LOOP;
  END LOOP;

  -- Update distribution record with final counts
  UPDATE fortress_pool_distributions
  SET total_recipients = v_total_recipients,
      total_distributed = v_total_distributed
  WHERE id = v_distribution_id;

  -- Deduct from pool (only what was actually distributed, remainder stays)
  UPDATE jackpot_pools
  SET plus_balance = plus_balance - v_total_distributed,
      updated_at = now()
  WHERE id = 1;

  RETURN jsonb_build_object(
    'success', true,
    'distribution_date', CURRENT_DATE,
    'pool_balance_before', v_pool_balance,
    'total_distributed', v_total_distributed,
    'remainder', v_pool_balance - v_total_distributed,
    'total_alliances', v_num_alliances,
    'total_recipients', v_total_recipients,
    'amount_per_alliance', v_amount_per_alliance
  );
END;
$$;


--
-- TOC entry 1114 (class 1255 OID 21761)
-- Name: admin_distribute_npc_roles(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_distribute_npc_roles(p_strategy text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
  v_total integer;
  v_counts jsonb := '{}'::jsonb;
  v_role text;
  v_weights jsonb;
BEGIN
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = auth.uid();
  IF v_is_admin IS NOT TRUE THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  IF p_strategy LIKE 'all_%' THEN
    v_role := substring(p_strategy FROM 5);
    IF v_role NOT IN ('balanced','miner','military','research','colonizer') THEN
      RAISE EXCEPTION 'Invalid role in all_%% strategy: %', v_role;
    END IF;
    UPDATE planets pl
    SET autopilot_role = v_role,
        last_update = now()
    FROM profiles p
    WHERE p.id = pl.user_id AND p.is_bot = true;
    GET DIAGNOSTICS v_total = ROW_COUNT;
    RETURN jsonb_build_object(
      'success', true,
      'strategy', p_strategy,
      'planets_updated', v_total,
      'distribution', jsonb_build_object(v_role, v_total)
    );
  END IF;

  CASE p_strategy
    WHEN 'strategic' THEN
      v_weights := jsonb_build_object('military', 40, 'miner', 30, 'balanced', 15, 'research', 10, 'colonizer', 5);
    WHEN 'aggressive' THEN
      v_weights := jsonb_build_object('military', 60, 'miner', 20, 'balanced', 10, 'research', 5, 'colonizer', 5);
    WHEN 'economic' THEN
      v_weights := jsonb_build_object('military', 20, 'miner', 50, 'balanced', 15, 'research', 10, 'colonizer', 5);
    WHEN 'even' THEN
      v_weights := jsonb_build_object('military', 20, 'miner', 20, 'balanced', 20, 'research', 20, 'colonizer', 20);
    ELSE
      RAISE EXCEPTION 'Unknown strategy: %. Use strategic|aggressive|economic|even|all_<role>', p_strategy;
  END CASE;

  WITH npc_planets AS (
    SELECT pl.id, random()*100 AS roll
    FROM planets pl
    JOIN profiles p ON p.id = pl.user_id
    WHERE p.is_bot = true
  ),
  assigned AS (
    SELECT id,
      CASE
        WHEN roll <  (v_weights->>'military')::numeric THEN 'military'
        WHEN roll <  (v_weights->>'military')::numeric + (v_weights->>'miner')::numeric THEN 'miner'
        WHEN roll <  (v_weights->>'military')::numeric + (v_weights->>'miner')::numeric + (v_weights->>'balanced')::numeric THEN 'balanced'
        WHEN roll <  (v_weights->>'military')::numeric + (v_weights->>'miner')::numeric + (v_weights->>'balanced')::numeric + (v_weights->>'research')::numeric THEN 'research'
        ELSE 'colonizer'
      END AS new_role
    FROM npc_planets
  )
  UPDATE planets pl
  SET autopilot_role = a.new_role,
      last_update = now()
  FROM assigned a
  WHERE pl.id = a.id;

  GET DIAGNOSTICS v_total = ROW_COUNT;

  SELECT jsonb_object_agg(autopilot_role, cnt) INTO v_counts
  FROM (
    SELECT pl.autopilot_role, COUNT(*) AS cnt
    FROM planets pl
    JOIN profiles p ON p.id = pl.user_id
    WHERE p.is_bot = true
    GROUP BY pl.autopilot_role
  ) t;

  RETURN jsonb_build_object(
    'success', true,
    'strategy', p_strategy,
    'planets_updated', v_total,
    'weights', v_weights,
    'distribution', v_counts
  );
END;
$$;


--
-- TOC entry 1115 (class 1255 OID 21762)
-- Name: admin_distribute_npc_roles_smart(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_distribute_npc_roles_smart() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
  v_npc RECORD;
  v_planet RECORD;
  v_planet_count integer;
  v_idx integer;
  v_role text;
  v_total integer := 0;
  v_counts jsonb;
  v_npcs_processed integer := 0;
BEGIN
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = auth.uid();
  IF v_is_admin IS NOT TRUE THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  -- Loop each NPC
  FOR v_npc IN
    SELECT id, username FROM profiles WHERE is_bot = true
  LOOP
    SELECT COUNT(*) INTO v_planet_count FROM planets WHERE user_id = v_npc.id;
    IF v_planet_count = 0 THEN
      CONTINUE;
    END IF;

    v_idx := 0;
    v_npcs_processed := v_npcs_processed + 1;

    -- Walk planets ordered: main first, then by created_at
    FOR v_planet IN
      SELECT id, is_main_planet
      FROM planets
      WHERE user_id = v_npc.id
      ORDER BY is_main_planet DESC NULLS LAST, created_at ASC, id
    LOOP
      v_idx := v_idx + 1;

      -- ==========================================================
      -- DECISION TREE BY NPC PLANET COUNT
      -- ==========================================================
      IF v_planet_count <= 2 THEN
        -- Small empire: priorize expansion
        -- Slot 1 (main) = colonizer, Slot 2 = miner
        IF v_idx = 1 THEN
          v_role := 'colonizer';
        ELSE
          v_role := 'miner';
        END IF;

      ELSIF v_planet_count = 3 THEN
        -- Medium empire: main military + one colonizer + one miner
        IF v_idx = 1 THEN
          v_role := 'military';
        ELSIF v_idx = 2 THEN
          v_role := 'colonizer';
        ELSE
          v_role := 'miner';
        END IF;

      ELSE
        -- Large empire (4+): main military + research + colonizer + miners
        IF v_idx = 1 THEN
          v_role := 'military';
        ELSIF v_idx = 2 THEN
          v_role := 'research';
        ELSIF v_idx = 3 THEN
          v_role := 'colonizer';
        ELSE
          v_role := 'miner';
        END IF;
      END IF;

      UPDATE planets
      SET autopilot_role = v_role,
          last_update = now()
      WHERE id = v_planet.id;

      v_total := v_total + 1;
    END LOOP;
  END LOOP;

  -- Final distribution summary
  SELECT jsonb_object_agg(autopilot_role, cnt) INTO v_counts
  FROM (
    SELECT pl.autopilot_role, COUNT(*) AS cnt
    FROM planets pl
    JOIN profiles p ON p.id = pl.user_id
    WHERE p.is_bot = true
    GROUP BY pl.autopilot_role
  ) t;

  RETURN jsonb_build_object(
    'success', true,
    'strategy', 'empire_v2',
    'npcs_processed', v_npcs_processed,
    'planets_updated', v_total,
    'distribution', v_counts,
    'rules', jsonb_build_object(
      'size_1',  'colonizer',
      'size_2',  'colonizer + miner',
      'size_3',  'military + colonizer + miner',
      'size_4',  'military + research + colonizer + miner',
      'size_5+', 'military + research + colonizer + miner(rest)'
    )
  );
END;
$$;


--
-- TOC entry 836 (class 1255 OID 19859)
-- Name: admin_distribute_plus_commissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_distribute_plus_commissions() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_pool_balance numeric;
  v_distribution_id uuid;
  v_pending RECORD;
  v_total_distributed numeric := 0;
  v_count int := 0;
  v_distribution_month date;
  v_active_sub RECORD;
  v_active_count int;
  v_share_amount numeric;
BEGIN
  v_admin_id := auth.uid();
  
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  -- First, calculate any pending rewards for expired subscriptions
  PERFORM calculate_expired_plus_rewards();

  -- Determine distribution month
  IF EXTRACT(DAY FROM now()) <= 5 THEN
    v_distribution_month := (date_trunc('month', now()) - interval '1 month')::date;
  ELSE
    v_distribution_month := date_trunc('month', now())::date;
  END IF;

  -- Create distribution record
  INSERT INTO plus_commission_distributions (distribution_month, total_pool_amount, total_subscribers, distributed_by)
  VALUES (v_distribution_month, 0, 0, v_admin_id)
  RETURNING id INTO v_distribution_id;

  -- Pay out all pending rewards (from expired subscriptions)
  FOR v_pending IN 
    SELECT ppr.id, ppr.user_id, ppr.subscription_id, ppr.reward_amount, p.username
    FROM plus_pending_rewards ppr
    JOIN profiles p ON p.id = ppr.user_id
    WHERE ppr.paid_out = false
  LOOP
    -- Add FXU to user
    UPDATE profiles SET fxu_balance = fxu_balance + v_pending.reward_amount WHERE id = v_pending.user_id;
    
    -- Update subscription total received
    UPDATE plus_subscriptions 
    SET total_commissions_received = total_commissions_received + v_pending.reward_amount 
    WHERE id = v_pending.subscription_id;
    
    -- Mark as paid
    UPDATE plus_pending_rewards 
    SET paid_out = true, 
        paid_out_at = now(),
        distribution_id = v_distribution_id
    WHERE id = v_pending.id;
    
    -- Record reward
    INSERT INTO plus_commission_rewards (distribution_id, user_id, subscription_id, share_percent, reward_amount)
    VALUES (v_distribution_id, v_pending.user_id, v_pending.subscription_id, 0, v_pending.reward_amount);
    
    -- Send notification
    INSERT INTO messages (recipient_id, sender_name, subject, body, message_type)
    VALUES (
      v_pending.user_id,
      'Sistema',
      'Comision Plus Entregada',
      'Has recibido ' || v_pending.reward_amount || ' FXU de tu suscripcion Plus. Esta recompensa estaba pendiente de entrega.',
      'system'
    );
    
    v_total_distributed := v_total_distributed + v_pending.reward_amount;
    v_count := v_count + 1;
  END LOOP;

  -- Now also calculate and pay active subscribers their share of remaining pool
  SELECT plus_balance INTO v_pool_balance FROM jackpot_pools WHERE id = 1;
  
  IF v_pool_balance > 0 THEN
    -- Count active subscribers
    SELECT COUNT(DISTINCT user_id) INTO v_active_count
    FROM plus_subscriptions
    WHERE is_active = true AND expires_at > now();
    
    IF v_active_count > 0 THEN
      v_share_amount := FLOOR(v_pool_balance / v_active_count);
      
      IF v_share_amount > 0 THEN
        FOR v_active_sub IN 
          SELECT DISTINCT ON (ps.user_id) ps.id, ps.user_id, p.username
          FROM plus_subscriptions ps
          JOIN profiles p ON p.id = ps.user_id
          WHERE ps.is_active = true AND ps.expires_at > now()
          ORDER BY ps.user_id, ps.expires_at DESC
        LOOP
          -- Add FXU to user
          UPDATE profiles SET fxu_balance = fxu_balance + v_share_amount WHERE id = v_active_sub.user_id;
          
          -- Update subscription
          UPDATE plus_subscriptions 
          SET total_commissions_received = total_commissions_received + v_share_amount 
          WHERE id = v_active_sub.id;
          
          -- Record reward
          INSERT INTO plus_commission_rewards (distribution_id, user_id, subscription_id, share_percent, reward_amount)
          VALUES (v_distribution_id, v_active_sub.user_id, v_active_sub.id, 100.0 / v_active_count, v_share_amount);
          
          -- Send notification
          INSERT INTO messages (recipient_id, sender_name, subject, body, message_type)
          VALUES (
            v_active_sub.user_id,
            'Sistema',
            'Comision Plus Mensual',
            'Has recibido ' || v_share_amount || ' FXU como comision mensual de tu suscripcion Plus activa.',
            'system'
          );
          
          v_total_distributed := v_total_distributed + v_share_amount;
          v_count := v_count + 1;
        END LOOP;
        
        -- Deduct from pool
        UPDATE jackpot_pools 
        SET plus_balance = plus_balance - (v_share_amount * v_active_count),
            updated_at = now()
        WHERE id = 1;
        
        UPDATE jackpot SET balance = balance - (v_share_amount * v_active_count) WHERE id = 1;
      END IF;
    END IF;
  END IF;

  -- Update distribution record with totals
  UPDATE plus_commission_distributions 
  SET total_pool_amount = v_total_distributed,
      total_subscribers = v_count
  WHERE id = v_distribution_id;

  IF v_count = 0 THEN
    -- Delete empty distribution
    DELETE FROM plus_commission_distributions WHERE id = v_distribution_id;
    RETURN jsonb_build_object('success', false, 'error', 'No hay suscriptores Plus para distribuir');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Comisiones Plus distribuidas',
    'total_distributed', v_total_distributed,
    'subscribers_paid', v_count,
    'distribution_id', v_distribution_id
  );
END;
$$;


--
-- TOC entry 1177 (class 1255 OID 22806)
-- Name: admin_distribute_social_ranking_pool(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_distribute_social_ranking_pool() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_admin_id uuid;
  v_pool_balance numeric;
  v_distribution_id uuid;
  v_total_points bigint := 0;
  v_participant RECORD;
  v_reward_amount numeric;
  v_reward_percent numeric;
  v_total_distributed numeric := 0;
  v_participant_count int := 0;
  v_distribution_month date;
  v_rank int := 0;
  v_weight numeric;
  v_total_weight numeric := 0;
  v_num_participants int := 0;
  v_rewards jsonb := '[]'::jsonb;
  v_first_user_id uuid;
  v_total_calculated numeric := 0;
  v_remainder numeric;
  v_reset_at timestamptz;
  i int;
BEGIN
  v_admin_id := auth.uid();

  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  -- Get current social ranking pool balance
  SELECT plus_balance INTO v_pool_balance FROM jackpot_pools WHERE id = 1;

  IF v_pool_balance <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pool de ranking social vacio');
  END IF;

  v_distribution_month := date_trunc('month', now())::date;

  -- Obtener fecha del último reinicio
  SELECT ranking_reset_at INTO v_reset_at FROM twitter_social_config LIMIT 1;
  IF v_reset_at IS NULL THEN
    v_reset_at := '1970-01-01'::timestamptz;
  END IF;

  -- Calculate total points from validated actions del período actual
  SELECT COALESCE(SUM(ta.points_awarded), 0)
  INTO v_total_points
  FROM twitter_actions ta
  WHERE ta.validated = true 
    AND ta.points_awarded > 0
    AND ta.created_at >= v_reset_at;

  IF v_total_points <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No hay participantes con puntos de tareas sociales en este periodo');
  END IF;

  -- Count participants
  SELECT COUNT(*) INTO v_num_participants
  FROM (
    SELECT ta.user_id
    FROM twitter_actions ta
    WHERE ta.validated = true 
      AND ta.points_awarded > 0
      AND ta.created_at >= v_reset_at
    GROUP BY ta.user_id
    HAVING SUM(ta.points_awarded) > 0
  ) sub;

  -- Pre-calculate total exponential weight (base 1.03)
  FOR i IN 1..v_num_participants LOOP
    v_total_weight := v_total_weight + POWER(1.03, v_num_participants - i);
  END LOOP;

  -- Create distribution record
  INSERT INTO social_ranking_distributions (distribution_month, total_pool_amount, distributed_by)
  VALUES (v_distribution_month, v_pool_balance, v_admin_id)
  RETURNING id INTO v_distribution_id;

  -- First pass: calculate all rewards
  v_rank := 0;
  FOR v_participant IN
    SELECT
      ta.user_id,
      p.username,
      SUM(ta.points_awarded) as user_points
    FROM twitter_actions ta
    JOIN profiles p ON p.id = ta.user_id
    WHERE ta.validated = true 
      AND ta.points_awarded > 0
      AND ta.created_at >= v_reset_at
    GROUP BY ta.user_id, p.username
    HAVING SUM(ta.points_awarded) > 0
    ORDER BY SUM(ta.points_awarded) DESC
  LOOP
    v_rank := v_rank + 1;

    IF v_rank = 1 THEN
      v_first_user_id := v_participant.user_id;
    END IF;

    v_weight := POWER(1.03, v_num_participants - v_rank);
    v_reward_percent := ROUND((v_weight / v_total_weight) * 100, 2);
    v_reward_amount := FLOOR(v_pool_balance * v_weight / v_total_weight);

    v_rewards := v_rewards || jsonb_build_object(
      'user_id', v_participant.user_id,
      'username', v_participant.username,
      'rank', v_rank,
      'points', v_participant.user_points,
      'amount', v_reward_amount,
      'percent', v_reward_percent
    );

    v_total_calculated := v_total_calculated + v_reward_amount;
  END LOOP;

  -- Give remainder to #1
  v_remainder := v_pool_balance - v_total_calculated;
  IF v_remainder > 0 AND v_first_user_id IS NOT NULL THEN
    SELECT jsonb_agg(
      CASE
        WHEN (elem->>'user_id')::uuid = v_first_user_id
        THEN jsonb_set(elem, '{amount}', to_jsonb((elem->>'amount')::numeric + v_remainder))
        ELSE elem
      END
    ) INTO v_rewards
    FROM jsonb_array_elements(v_rewards) elem;

    v_total_calculated := v_pool_balance;
  END IF;

  -- Set FXU context
  PERFORM _internal_set_fxu_context();

  -- Second pass: distribute rewards
  FOR v_participant IN
    SELECT
      (elem->>'user_id')::uuid as user_id,
      (elem->>'username')::text as username,
      (elem->>'rank')::int as rank,
      (elem->>'points')::bigint as points,
      (elem->>'amount')::numeric as amount,
      (elem->>'percent')::numeric as percent
    FROM jsonb_array_elements(v_rewards) elem
  LOOP
    IF v_participant.amount > 0 THEN
      UPDATE profiles SET fxu_balance = fxu_balance + v_participant.amount WHERE id = v_participant.user_id;

      INSERT INTO social_ranking_rewards (distribution_id, user_id, points_at_distribution, reward_amount, reward_percent)
      VALUES (v_distribution_id, v_participant.user_id, v_participant.points, v_participant.amount, v_participant.percent);

      INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
      VALUES (
        v_participant.user_id,
        NULL,
        '🏆 Recompensa Ranking Social',
        'Felicidades! Puesto #' || v_participant.rank || ' - Has recibido ' || v_participant.amount || ' FXU (' || v_participant.percent || '% del pool) por tus ' || v_participant.points || ' puntos en el ranking social. Los puntos se han reiniciado.',
        'system'
      );

      v_participant_count := v_participant_count + 1;
      v_total_distributed := v_total_distributed + v_participant.amount;
    END IF;
  END LOOP;

  -- Telegram broadcast
  DECLARE
    v_rewards_list_text text := '';
    v_rewards_elem jsonb;
    v_emoji text;
    v_anon_key text;
    v_request_id bigint;
  BEGIN
    FOR v_rewards_elem IN SELECT * FROM jsonb_array_elements(v_rewards)
    LOOP
      IF (v_rewards_elem->>'rank')::int = 1 THEN
        v_emoji := '🏆';
      ELSIF (v_rewards_elem->>'rank')::int <= 3 THEN
        v_emoji := '🥇';
      ELSIF (v_rewards_elem->>'rank')::int <= 10 THEN
        v_emoji := '🎖️';
      ELSE
        v_emoji := '⭐';
      END IF;
      v_rewards_list_text := v_rewards_list_text || v_emoji || ' #' || (v_rewards_elem->>'rank') || ' ' || (v_rewards_elem->>'username') || ' - ' || (v_rewards_elem->>'amount') || ' FXU (' || (v_rewards_elem->>'percent') || '%)' || chr(10);
    END LOOP;

    v_rewards_list_text := '📱 RANKING SOCIAL (Twitter) - REPARTO 📱' || chr(10) || chr(10)
      || '💰 Pool total: ' || v_pool_balance || ' FXU' || chr(10) || chr(10)
      || v_rewards_list_text || chr(10)
      || '¡Felicidades a los mas activos en redes sociales!' || chr(10)
      || '¿Quieres ganar FXU? ¡Completa las tareas de Twitter!' || chr(10)
      || 'Unete: https://t.me/TrungTungMeme';

    INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
    SELECT p.id, NULL, 'Ranking Social - Reparto', v_rewards_list_text, 'system'
    FROM profiles p
    WHERE p.id NOT IN (SELECT (elem->>'user_id')::uuid FROM jsonb_array_elements(v_rewards) elem) AND p.is_admin = false;

    BEGIN
      SELECT anon_key INTO v_anon_key FROM market_notification_config WHERE id = 1;

      IF v_anon_key IS NOT NULL THEN
        SELECT net.http_post(
          url := 'https://lvqagudwifvytsptqjxp.supabase.co/functions/v1/send-telegram-broadcast',
          body := jsonb_build_object(
            'subject', 'Ranking Social (Twitter) - Reparto',
            'body', v_rewards_list_text
          ),
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || v_anon_key,
            'apikey', v_anon_key
          )
        ) INTO v_request_id;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        RAISE NOTICE 'Telegram broadcast error: %', SQLERRM;
    END;
  END;

  -- Update distribution record
  UPDATE social_ranking_distributions
  SET total_participants = v_participant_count,
      total_distributed = v_total_distributed
  WHERE id = v_distribution_id;

  -- Deduct from pool
  UPDATE jackpot_pools
  SET plus_balance = plus_balance - v_total_distributed,
      updated_at = now()
  WHERE id = 1;

  UPDATE jackpot SET balance = balance - v_total_distributed WHERE id = 1;

  -- Reset points to 0 (for audit trail) — WHERE clause required by pg_safeupdate
  UPDATE twitter_actions
  SET points_awarded = 0
  WHERE validated = true AND points_awarded > 0;

  -- *** FIX: Added WHERE clause — pg_safeupdate blocks UPDATEs without WHERE ***
  UPDATE twitter_social_config SET ranking_reset_at = NOW() WHERE id IS NOT NULL;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Ranking social distribuido y puntos reiniciados. Las tareas antiguas ya no apareceran.',
    'total_distributed', v_total_distributed,
    'participants_rewarded', v_participant_count,
    'total_points_reset', v_total_points,
    'distribution_id', v_distribution_id
  );
END;
$$;


