    AS $$
BEGIN
  IF NOT is_current_user_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  RETURN regenerate_depleted_planets();
END;
$$;


--
-- TOC entry 1157 (class 1255 OID 22409)
-- Name: admin_get_depleted_planets(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_depleted_planets(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_current_user_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  RETURN jsonb_build_object('success', true, 'planets', (
    SELECT jsonb_agg(row_to_json(t)) FROM (
      SELECT p.id, p.galaxy, p.solar_system, p.position, p.planet_status,
             p.fields_max, p.fields_used, p.metal_deposit, p.crystal_deposit,
             p.deuterium_deposit, p.depleted_at, p.regenerates_at,
             pr.username as owner_name
      FROM planets p LEFT JOIN profiles pr ON pr.id = p.user_id
      WHERE (p_status IS NULL OR p.planet_status = p_status)
        AND p.planet_status IN ('depleted', 'regenerating')
      ORDER BY p.depleted_at DESC NULLS LAST, p.regenerates_at ASC NULLS LAST
      LIMIT p_limit OFFSET p_offset
    ) t
  ), 'total', (
    SELECT COUNT(*) FROM planets
    WHERE (p_status IS NULL OR planet_status = p_status)
      AND planet_status IN ('depleted', 'regenerating')
  ));
END;
$$;


--
-- TOC entry 1154 (class 1255 OID 22406)
-- Name: admin_get_depletion_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_depletion_settings() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_depleted_count integer; v_regenerating_count integer;
BEGIN
  SELECT COUNT(*) INTO v_depleted_count FROM planets WHERE planet_status = 'depleted';
  SELECT COUNT(*) INTO v_regenerating_count FROM planets WHERE planet_status = 'regenerating';
  RETURN jsonb_build_object('success', true,
    'depleted_planets', v_depleted_count,
    'regenerating_planets', v_regenerating_count,
    'settings', (SELECT jsonb_object_agg(key, value) FROM game_settings WHERE key LIKE 'depletion_%')
  );
END;
$$;


--
-- TOC entry 891 (class 1255 OID 20107)
-- Name: admin_get_inactive_accounts(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_inactive_accounts(p_days_inactive integer DEFAULT 7) RETURNS TABLE(user_id uuid, username text, email text, created_at timestamp with time zone, last_activity timestamp with time zone, days_inactive integer, hours_played numeric, category text, points_total integer, fxu_balance numeric, planet_count bigint, has_alliance boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_is_admin boolean;
BEGIN
  v_admin_id := auth.uid();

  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  SELECT p.is_admin INTO v_is_admin FROM profiles p WHERE p.id = v_admin_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'Acceso denegado: se requieren permisos de administrador';
  END IF;

  RETURN QUERY
  SELECT 
    p.id as user_id,
    p.username,
    p.email,
    p.created_at,
    p.last_activity,
    EXTRACT(DAY FROM (now() - COALESCE(p.last_activity, p.created_at)))::int as days_inactive,
    ROUND(EXTRACT(EPOCH FROM (COALESCE(p.last_activity, p.created_at) - p.created_at)) / 3600.0, 2)::numeric as hours_played,
    CASE
      WHEN p.last_activity IS NULL 
           OR p.last_activity = p.created_at
           OR EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 3600 
      THEN 'never_played'
      WHEN EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 86400 
      THEN 'first_day_only'
      ELSE 'abandoned'
    END as category,
    COALESCE(p.points_total, 0)::int as points_total,
    COALESCE(p.fxu_balance, 0)::numeric as fxu_balance,
    (SELECT COUNT(*) FROM planets pl WHERE pl.user_id = p.id) as planet_count,
    EXISTS (SELECT 1 FROM alliance_members am WHERE am.user_id = p.id) as has_alliance
  FROM profiles p
  WHERE 
    COALESCE(p.is_admin, false) = false
    AND COALESCE(p.is_banned, false) = false
    AND (now() - COALESCE(p.last_activity, p.created_at)) > (p_days_inactive || ' days')::interval
  ORDER BY 
    (now() - COALESCE(p.last_activity, p.created_at)) DESC;
END;
$$;


--
-- TOC entry 890 (class 1255 OID 20106)
-- Name: admin_get_inactive_accounts_detailed(integer, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_inactive_accounts_detailed(p_days_inactive integer DEFAULT 7, p_category text DEFAULT 'all'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, username text, email text, created_at timestamp with time zone, last_activity timestamp with time zone, days_inactive integer, hours_played numeric, category text, points_buildings integer, points_total integer, planet_count bigint, has_alliance boolean, fxu_balance numeric, usdt_balance numeric, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '15s'
    AS $$
DECLARE
  v_admin_id uuid;
  v_is_admin boolean;
  v_total_count bigint;
BEGIN
  v_admin_id := auth.uid();
  
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  
  SELECT p.is_admin INTO v_is_admin FROM profiles p WHERE p.id = v_admin_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'Acceso denegado: se requieren permisos de administrador';
  END IF;

  SELECT COUNT(*) INTO v_total_count
  FROM profiles p
  WHERE 
    COALESCE(p.is_admin, false) = false
    AND COALESCE(p.is_banned, false) = false
    AND (now() - COALESCE(p.last_activity, p.created_at)) > (p_days_inactive || ' days')::interval
    AND (
      p_category = 'all'
      OR (
        p_category = 'never_played' 
        AND (
          p.last_activity IS NULL 
          OR p.last_activity = p.created_at
          OR EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 3600
        )
      )
      OR (
        p_category = 'first_day_only'
        AND p.last_activity IS NOT NULL
        AND EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) >= 3600
        AND EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 86400
      )
      OR (
        p_category = 'abandoned'
        AND p.last_activity IS NOT NULL
        AND EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) >= 86400
      )
    );
  
  RETURN QUERY
  SELECT 
    p.id as user_id,
    p.username,
    p.email,
    p.created_at,
    p.last_activity,
    EXTRACT(DAY FROM (now() - COALESCE(p.last_activity, p.created_at)))::int as days_inactive,
    ROUND(EXTRACT(EPOCH FROM (COALESCE(p.last_activity, p.created_at) - p.created_at)) / 3600.0, 2) as hours_played,
    CASE
      WHEN p.last_activity IS NULL 
           OR p.last_activity = p.created_at
           OR EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 3600 
      THEN 'never_played'
      WHEN EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 86400 
      THEN 'first_day_only'
      ELSE 'abandoned'
    END as category,
    COALESCE(p.points_buildings, 0)::int as points_buildings,
    COALESCE(p.points_total, 0)::int as points_total,
    (SELECT COUNT(*) FROM planets pl WHERE pl.user_id = p.id) as planet_count,
    EXISTS (SELECT 1 FROM alliance_members am WHERE am.user_id = p.id) as has_alliance,
    COALESCE(p.fxu_balance, 0) as fxu_balance,
    COALESCE(p.usdt_balance, 0) as usdt_balance,
    v_total_count as total_count
  FROM profiles p
  WHERE 
    COALESCE(p.is_admin, false) = false
    AND COALESCE(p.is_banned, false) = false
    AND (now() - COALESCE(p.last_activity, p.created_at)) > (p_days_inactive || ' days')::interval
    AND (
      p_category = 'all'
      OR (
        p_category = 'never_played' 
        AND (
          p.last_activity IS NULL 
          OR p.last_activity = p.created_at
          OR EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 3600
        )
      )
      OR (
        p_category = 'first_day_only'
        AND p.last_activity IS NOT NULL
        AND EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) >= 3600
        AND EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 86400
      )
      OR (
        p_category = 'abandoned'
        AND p.last_activity IS NOT NULL
        AND EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) >= 86400
      )
    )
  ORDER BY 
    CASE 
      WHEN p.last_activity IS NULL 
           OR p.last_activity = p.created_at
           OR EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 3600 
      THEN 1
      WHEN EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 86400 
      THEN 2
      ELSE 3
    END,
    (now() - COALESCE(p.last_activity, p.created_at)) DESC
  OFFSET p_offset
  LIMIT p_limit;
END;
$$;


--
-- TOC entry 950 (class 1255 OID 20449)
-- Name: admin_get_inactive_accounts_detailed(integer, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_inactive_accounts_detailed(p_days_inactive integer DEFAULT 7, p_category text DEFAULT 'all'::text, p_sort_by text DEFAULT 'days_inactive'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, username text, email text, created_at timestamp with time zone, last_activity timestamp with time zone, days_inactive integer, hours_played numeric, category text, points_buildings integer, points_total integer, ranking_position bigint, planet_count bigint, has_alliance boolean, fxu_balance numeric, usdt_balance numeric, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_is_admin boolean;
  v_total bigint;
BEGIN
  v_admin_id := auth.uid();
  
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;
  
  SELECT p.is_admin INTO v_is_admin FROM profiles p WHERE p.id = v_admin_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'Acceso denegado: se requieren permisos de administrador';
  END IF;

  SELECT COUNT(*) INTO v_total
  FROM profiles p
  WHERE 
    COALESCE(p.is_admin, false) = false
    AND COALESCE(p.is_banned, false) = false
    AND (now() - COALESCE(p.last_activity, p.created_at)) > (p_days_inactive || ' days')::interval
    AND (
      p_category = 'all'
      OR (
        p_category = 'never_played' 
        AND (
          p.last_activity IS NULL 
          OR p.last_activity = p.created_at
          OR EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 3600
        )
      )
      OR (
        p_category = 'first_day_only'
        AND p.last_activity IS NOT NULL
        AND EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) >= 3600
        AND EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) < 86400
      )
      OR (
        p_category = 'abandoned'
        AND p.last_activity IS NOT NULL
        AND EXTRACT(EPOCH FROM (p.last_activity - p.created_at)) >= 86400
      )
    );
  
  RETURN QUERY
  WITH ranked_profiles AS (
    SELECT 
      pr.id,
      pr.username,
      pr.email,
      pr.created_at as profile_created_at,
      pr.last_activity,
      pr.points_buildings,
      pr.points_total,
      pr.fxu_balance,
      pr.usdt_balance,
      ROW_NUMBER() OVER (ORDER BY COALESCE(pr.points_total, 0) DESC, pr.created_at ASC) as rank_pos
    FROM profiles pr
    WHERE COALESCE(pr.is_admin, false) = false
      AND COALESCE(pr.is_banned, false) = false
  )
  SELECT 
    rp.id as user_id,
    rp.username,
    rp.email,
    rp.profile_created_at as created_at,
    rp.last_activity,
    EXTRACT(DAY FROM (now() - COALESCE(rp.last_activity, rp.profile_created_at)))::int as days_inactive,
    ROUND(EXTRACT(EPOCH FROM (COALESCE(rp.last_activity, rp.profile_created_at) - rp.profile_created_at)) / 3600.0, 2) as hours_played,
    CASE
      WHEN rp.last_activity IS NULL 
           OR rp.last_activity = rp.profile_created_at
           OR EXTRACT(EPOCH FROM (rp.last_activity - rp.profile_created_at)) < 3600 
      THEN 'never_played'
      WHEN EXTRACT(EPOCH FROM (rp.last_activity - rp.profile_created_at)) < 86400 
      THEN 'first_day_only'
      ELSE 'abandoned'
    END as category,
    COALESCE(rp.points_buildings, 0)::int as points_buildings,
    COALESCE(rp.points_total, 0)::int as points_total,
    rp.rank_pos as ranking_position,
    (SELECT COUNT(*) FROM planets pl WHERE pl.user_id = rp.id) as planet_count,
    EXISTS (SELECT 1 FROM alliance_members am WHERE am.user_id = rp.id) as has_alliance,
    COALESCE(rp.fxu_balance, 0) as fxu_balance,
    COALESCE(rp.usdt_balance, 0) as usdt_balance,
    v_total as total_count
  FROM ranked_profiles rp
  WHERE 
    (now() - COALESCE(rp.last_activity, rp.profile_created_at)) > (p_days_inactive || ' days')::interval
    AND (
      p_category = 'all'
      OR (
        p_category = 'never_played' 
        AND (
          rp.last_activity IS NULL 
          OR rp.last_activity = rp.profile_created_at
          OR EXTRACT(EPOCH FROM (rp.last_activity - rp.profile_created_at)) < 3600
        )
      )
      OR (
        p_category = 'first_day_only'
        AND rp.last_activity IS NOT NULL
        AND EXTRACT(EPOCH FROM (rp.last_activity - rp.profile_created_at)) >= 3600
        AND EXTRACT(EPOCH FROM (rp.last_activity - rp.profile_created_at)) < 86400
      )
      OR (
        p_category = 'abandoned'
        AND rp.last_activity IS NOT NULL
        AND EXTRACT(EPOCH FROM (rp.last_activity - rp.profile_created_at)) >= 86400
      )
    )
  ORDER BY 
    CASE 
      WHEN p_sort_by = 'ranking_position' AND p_sort_order = 'asc' THEN rp.rank_pos 
    END ASC NULLS LAST,
    CASE 
      WHEN p_sort_by = 'ranking_position' AND p_sort_order = 'desc' THEN rp.rank_pos 
    END DESC NULLS LAST,
    CASE 
      WHEN p_sort_by = 'points_total' AND p_sort_order = 'asc' THEN COALESCE(rp.points_total, 0) 
    END ASC,
    CASE 
      WHEN p_sort_by = 'points_total' AND p_sort_order = 'desc' THEN COALESCE(rp.points_total, 0) 
    END DESC,
    CASE 
      WHEN p_sort_by = 'days_inactive' AND p_sort_order = 'asc' THEN EXTRACT(DAY FROM (now() - COALESCE(rp.last_activity, rp.profile_created_at)))
    END ASC,
    CASE 
      WHEN p_sort_by = 'days_inactive' AND p_sort_order = 'desc' THEN EXTRACT(DAY FROM (now() - COALESCE(rp.last_activity, rp.profile_created_at)))
    END DESC,
    CASE 
      WHEN p_sort_by NOT IN ('ranking_position', 'points_total', 'days_inactive') THEN EXTRACT(DAY FROM (now() - COALESCE(rp.last_activity, rp.profile_created_at)))
    END DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


--
-- TOC entry 883 (class 1255 OID 20093)
-- Name: admin_get_inactive_accounts_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_inactive_accounts_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '10s'
    AS $$
DECLARE
  v_admin_id uuid;
  v_is_admin boolean;
  v_result record;
BEGIN
  v_admin_id := auth.uid();
  
  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_admin_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Acceso denegado');
  END IF;

  SELECT
    COUNT(*) FILTER (
      WHERE (
        last_activity IS NULL 
        OR last_activity = created_at
        OR EXTRACT(EPOCH FROM (last_activity - created_at)) < 3600
      )
      AND (now() - created_at) > interval '1 day'
    ) as never_played,
    COUNT(*) FILTER (
      WHERE last_activity IS NOT NULL
      AND EXTRACT(EPOCH FROM (last_activity - created_at)) >= 3600
      AND EXTRACT(EPOCH FROM (last_activity - created_at)) < 86400
      AND (now() - last_activity) > interval '7 days'
    ) as first_day_only_7d_inactive,
    COUNT(*) FILTER (
      WHERE last_activity IS NOT NULL
      AND EXTRACT(EPOCH FROM (last_activity - created_at)) >= 86400
      AND (now() - last_activity) > interval '7 days'
    ) as abandoned_7d,
    COUNT(*) FILTER (
      WHERE last_activity IS NOT NULL
      AND EXTRACT(EPOCH FROM (last_activity - created_at)) >= 86400
      AND (now() - last_activity) > interval '14 days'
    ) as abandoned_14d,
    COUNT(*) FILTER (
      WHERE last_activity IS NOT NULL
      AND EXTRACT(EPOCH FROM (last_activity - created_at)) >= 86400
      AND (now() - last_activity) > interval '30 days'
    ) as abandoned_30d
  INTO v_result
  FROM profiles p
  WHERE COALESCE(p.is_admin, false) = false
    AND COALESCE(p.is_banned, false) = false;

  RETURN jsonb_build_object(
    'success', true,
    'summary', jsonb_build_object(
      'never_played', COALESCE(v_result.never_played, 0),
      'first_day_only_7d_inactive', COALESCE(v_result.first_day_only_7d_inactive, 0),
      'abandoned_7d', COALESCE(v_result.abandoned_7d, 0),
      'abandoned_14d', COALESCE(v_result.abandoned_14d, 0),
      'abandoned_30d', COALESCE(v_result.abandoned_30d, 0)
    ),
    'description', jsonb_build_object(
      'never_played', 'Cuentas que nunca jugaron (menos de 1 hora de actividad)',
      'first_day_only_7d_inactive', 'Jugaron solo el primer dia (1-24h) y llevan 7+ dias inactivos',
      'abandoned_7d', 'Jugaron mas de 24h pero llevan 7+ dias sin actividad',
      'abandoned_14d', 'Jugaron mas de 24h pero llevan 14+ dias sin actividad',
      'abandoned_30d', 'Jugaron mas de 24h pero llevan 30+ dias sin actividad'
    )
  );
END;
$$;


--
-- TOC entry 1144 (class 1255 OID 22346)
-- Name: admin_get_officer_pricing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_officer_pricing() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_officers jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', sub.id, 'code', sub.code, 'name', sub.name,
    'dark_matter_cost_7d', sub.dark_matter_cost_7d,
    'dark_matter_cost_30d', sub.dark_matter_cost_30d,
    'dark_matter_cost_90d', sub.dark_matter_cost_90d,
    'fxu_cost_7d', sub.fxu_cost_7d,
    'fxu_cost_30d', sub.fxu_cost_30d,
    'fxu_cost_90d', sub.fxu_cost_90d,
    'sort_order', sub.sort_order
  ) ORDER BY sub.sort_order), '[]'::jsonb) INTO v_officers
  FROM (SELECT * FROM officer_types) sub;

  RETURN jsonb_build_object('success', true, 'officers', v_officers);
