$$;


--
-- TOC entry 959 (class 1255 OID 20563)
-- Name: admin_get_pending_twitter_actions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_pending_twitter_actions() RETURNS TABLE(action_id uuid, user_id uuid, username text, twitter_username text, mission_id uuid, mission_tweet_url text, action_type text, user_tweet_url text, points_awarded integer, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if caller is admin
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  RETURN QUERY
  SELECT 
    ta.id AS action_id,
    ta.user_id,
    p.username,
    tl.twitter_username,
    ta.mission_id,
    tm.tweet_url AS mission_tweet_url,
    ta.action_type,
    ta.user_tweet_url,
    ta.points_awarded,
    ta.created_at
  FROM twitter_actions ta
  JOIN profiles p ON p.id = ta.user_id
  LEFT JOIN twitter_links tl ON tl.user_id = ta.user_id
  JOIN twitter_missions tm ON tm.id = ta.mission_id
  WHERE ta.validated = false
  ORDER BY ta.created_at ASC;
END;
$$;


--
-- TOC entry 1045 (class 1255 OID 21255)
-- Name: admin_get_planet_inventory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_planet_inventory(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
  v_planet RECORD;
  v_ships jsonb;
  v_buildings jsonb;
BEGIN
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = auth.uid();
  IF v_is_admin IS NOT TRUE THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  SELECT p.id, p.name, p.user_id, p.galaxy, p.solar_system, p."position",
         p.planet_type, p.is_main_planet, pr.username
    INTO v_planet
  FROM planets p
  LEFT JOIN profiles pr ON pr.id = p.user_id
  WHERE p.id = p_planet_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Planet not found';
  END IF;

  -- Naves: TODOS los ship_types con la cantidad actual (0 si no existe)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'ship_type_id', st.id,
    'code',         st.code,
    'name',         st.name,
    'quantity',     COALESCE(ps.quantity, 0)
  ) ORDER BY st.id), '[]'::jsonb)
  INTO v_ships
  FROM ship_types st
  LEFT JOIN planet_ships ps ON ps.ship_type_id = st.id AND ps.planet_id = p_planet_id;

  -- Edificios: TODOS los building_types con su nivel actual (0 si no existe)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'building_type_id', bt.id,
    'code',             bt.code,
    'name',             bt.name,
    'level',            COALESCE(pb.level, 0),
    'is_upgrading',     COALESCE(pb.is_upgrading, false)
  ) ORDER BY bt.id), '[]'::jsonb)
  INTO v_buildings
  FROM building_types bt
  LEFT JOIN planet_buildings pb ON pb.building_type_id = bt.id AND pb.planet_id = p_planet_id;

  RETURN jsonb_build_object(
    'planet', jsonb_build_object(
      'id',             v_planet.id,
      'name',           v_planet.name,
      'user_id',        v_planet.user_id,
      'username',       v_planet.username,
      'coords',         format('[%s:%s:%s]', v_planet.galaxy, v_planet.solar_system, v_planet."position"),
      'planet_type',    v_planet.planet_type,
      'is_main_planet', v_planet.is_main_planet
    ),
    'ships',     v_ships,
    'buildings', v_buildings
  );
END;
$$;


--
-- TOC entry 917 (class 1255 OID 20339)
-- Name: admin_get_recaptcha_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_recaptcha_settings() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_site_key text;
  v_secret_key text;
  v_enabled text;
  v_min_score numeric;
BEGIN
  IF NOT is_current_user_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  SELECT value INTO v_site_key FROM game_settings WHERE key = 'recaptcha_site_key';
  SELECT value INTO v_secret_key FROM game_settings WHERE key = 'recaptcha_secret_key';
  SELECT value INTO v_enabled FROM game_settings WHERE key = 'recaptcha_enabled';
  SELECT value::numeric INTO v_min_score FROM game_settings WHERE key = 'recaptcha_min_score';

  v_site_key := trim(both '"' from COALESCE(v_site_key, ''));
  v_secret_key := trim(both '"' from COALESCE(v_secret_key, ''));

  RETURN jsonb_build_object(
    'success', true,
    'site_key', v_site_key,
    'secret_key', v_secret_key,
    'enabled', (COALESCE(v_enabled, 'false') = 'true'),
    'min_score', COALESCE(v_min_score, 0.5)
  );
END;
$$;


