--
-- TOC entry 985 (class 1255 OID 20668)
-- Name: admin_manual_approve_twitter_action(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_manual_approve_twitter_action(p_action_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_action record;
  v_user_id uuid;
  v_points int;
BEGIN
  -- Check admin
  v_admin_id := auth.uid();
  IF NOT EXISTS (SELECT 1 FROM admin_users WHERE user_id = v_admin_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  -- Get action
  SELECT * INTO v_action
  FROM twitter_user_actions
  WHERE id = p_action_id;

  IF v_action IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Accion no encontrada');
  END IF;

  IF v_action.is_validated THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya estaba aprobada', 'already_validated', true);
  END IF;

  v_user_id := v_action.user_id;
  v_points := v_action.points_awarded;

  -- Mark as validated
  UPDATE twitter_user_actions
  SET is_validated = true,
      validated_at = now()
  WHERE id = p_action_id;

  -- Award points to social_statistics
  INSERT INTO social_statistics (user_id, twitter_points, total_actions, validated_actions)
  VALUES (v_user_id, v_points, 0, 1)
  ON CONFLICT (user_id) DO UPDATE
  SET twitter_points = social_statistics.twitter_points + v_points,
      validated_actions = social_statistics.validated_actions + 1,
      updated_at = now();

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Aprobado manualmente',
    'username', (SELECT username FROM profiles WHERE id = v_user_id),
    'points', v_points
  );
END;
$$;


--
-- TOC entry 871 (class 1255 OID 20046)
-- Name: admin_process_stuck_building_queues(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_process_stuck_building_queues() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_user_id uuid;
v_is_admin boolean;
v_queue_item RECORD;
v_completed_count integer := 0;
v_error_count integer := 0;
v_building_record RECORD;
v_planet RECORD;
v_lunar_base_id integer;
BEGIN
SELECT auth.uid() INTO v_user_id;

IF v_user_id IS NOT NULL THEN
SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
IF NOT COALESCE(v_is_admin, false) THEN
RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
END IF;
END IF;

SELECT id INTO v_lunar_base_id FROM building_types WHERE code = 'lunar_base' LIMIT 1;

FOR v_queue_item IN 
SELECT bq.*, bt.code as building_code
FROM building_queue bq
JOIN building_types bt ON bq.building_type_id = bt.id
WHERE bq.end_time IS NOT NULL 
AND bq.end_time <= NOW()
ORDER BY bq.end_time ASC
LOOP
BEGIN
SELECT * INTO v_planet FROM planets WHERE id = v_queue_item.planet_id;

SELECT * INTO v_building_record 
FROM planet_buildings 
WHERE planet_id = v_queue_item.planet_id 
AND building_type_id = v_queue_item.building_type_id;

IF v_building_record IS NOT NULL THEN
UPDATE planet_buildings
SET level = v_queue_item.target_level,
is_upgrading = false,
upgrade_end_time = NULL
WHERE id = v_building_record.id;
ELSE
INSERT INTO planet_buildings (planet_id, building_type_id, level, is_upgrading)
VALUES (v_queue_item.planet_id, v_queue_item.building_type_id, v_queue_item.target_level, false);
END IF;

UPDATE planets
SET fields_used = fields_used + 1
WHERE id = v_queue_item.planet_id
AND fields_used < fields_max;

-- [FIX 2026-05-06] Lunar base on moon: grant +3 fields per level
IF v_lunar_base_id IS NOT NULL AND v_queue_item.building_type_id = v_lunar_base_id THEN
  UPDATE planets
  SET fields_max = GREATEST(fields_max, 1 + v_queue_item.target_level * 3)
  WHERE id = v_queue_item.planet_id AND planet_type = 'moon';
END IF;

DELETE FROM building_queue WHERE id = v_queue_item.id;

UPDATE building_queue
SET queue_position = queue_position - 1
WHERE planet_id = v_queue_item.planet_id
AND queue_position > v_queue_item.queue_position;

v_completed_count := v_completed_count + 1;

EXCEPTION WHEN OTHERS THEN
v_error_count := v_error_count + 1;
END;
END LOOP;

FOR v_queue_item IN 
SELECT bq.*, bt.code as building_code, p.user_id
FROM building_queue bq
JOIN building_types bt ON bq.building_type_id = bt.id
JOIN planets p ON bq.planet_id = p.id
WHERE bq.queue_position = 1 
AND bq.end_time IS NULL
LOOP
BEGIN
PERFORM secure_activate_building_queue(v_queue_item.planet_id);
EXCEPTION WHEN OTHERS THEN
NULL;
END;
END LOOP;

RETURN jsonb_build_object(
'success', true,
'completed_count', v_completed_count,
'error_count', v_error_count
);
END;
$$;


--
-- TOC entry 873 (class 1255 OID 20048)
-- Name: admin_process_stuck_fleets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_process_stuck_fleets() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_fleet RECORD;
  v_processed_count integer := 0;
  v_error_count integer := 0;
BEGIN
  SELECT auth.uid() INTO v_user_id;
  
  IF v_user_id IS NOT NULL THEN
    SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
    IF NOT COALESCE(v_is_admin, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
    END IF;
  END IF;

  FOR v_fleet IN 
    SELECT f.*
    FROM fleets f
    WHERE f.is_completed = false
      AND (
        (NOT COALESCE(f.is_returning, false) AND f.arrival_time IS NOT NULL AND f.arrival_time <= NOW())
        OR
        (COALESCE(f.is_returning, false) AND f.return_time IS NOT NULL AND f.return_time <= NOW())
      )
    ORDER BY COALESCE(f.return_time, f.arrival_time) ASC
  LOOP
    BEGIN
      PERFORM process_fleet_arrival(v_fleet.id);
      v_processed_count := v_processed_count + 1;
    EXCEPTION WHEN OTHERS THEN
      v_error_count := v_error_count + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'processed_count', v_processed_count,
    'error_count', v_error_count
  );
END;
$$;


--
-- TOC entry 874 (class 1255 OID 20049)
-- Name: admin_process_stuck_research(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_process_stuck_research() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_tech RECORD;
  v_completed_count integer := 0;
  v_error_count integer := 0;
BEGIN
  SELECT auth.uid() INTO v_user_id;
  
  IF v_user_id IS NOT NULL THEN
    SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
    IF NOT COALESCE(v_is_admin, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
    END IF;
  END IF;

  FOR v_tech IN 
    SELECT ut.*
    FROM user_technologies ut
    WHERE ut.is_researching = true
      AND ut.research_end_time IS NOT NULL
      AND ut.research_end_time <= NOW()
    ORDER BY ut.research_end_time ASC
  LOOP
    BEGIN
      UPDATE user_technologies
      SET level = level + 1,
          is_researching = false,
          research_end_time = NULL,
          research_planet_id = NULL
      WHERE id = v_tech.id;
      
      PERFORM update_user_points(v_tech.user_id);
      
      v_completed_count := v_completed_count + 1;
      
    EXCEPTION WHEN OTHERS THEN
      v_error_count := v_error_count + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'completed_count', v_completed_count,
    'error_count', v_error_count
  );
END;
$$;


--
-- TOC entry 872 (class 1255 OID 20047)
-- Name: admin_process_stuck_shipyard_queues(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_process_stuck_shipyard_queues() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_queue_item RECORD;
  v_completed_units integer := 0;
  v_error_count integer := 0;
  v_units_to_complete integer;
  v_planet RECORD;
BEGIN
  SELECT auth.uid() INTO v_user_id;
  
  IF v_user_id IS NOT NULL THEN
    SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
    IF NOT COALESCE(v_is_admin, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
    END IF;
  END IF;

  FOR v_queue_item IN 
    SELECT sq.*, p.user_id
    FROM shipyard_queue sq
    JOIN planets p ON sq.planet_id = p.id
    WHERE sq.current_unit_end_time IS NOT NULL 
      AND sq.current_unit_end_time <= NOW()
    ORDER BY sq.current_unit_end_time ASC
  LOOP
    BEGIN
      v_units_to_complete := v_queue_item.quantity - v_queue_item.quantity_completed;
      
      IF v_queue_item.item_type = 'ship' AND v_queue_item.ship_type_id IS NOT NULL THEN
        INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
        VALUES (v_queue_item.planet_id, v_queue_item.ship_type_id, v_units_to_complete)
        ON CONFLICT (planet_id, ship_type_id)
        DO UPDATE SET quantity = planet_ships.quantity + v_units_to_complete;
      ELSIF v_queue_item.item_type = 'defense' AND v_queue_item.defense_type_id IS NOT NULL THEN
        INSERT INTO planet_defenses (planet_id, defense_type_id, quantity)
        VALUES (v_queue_item.planet_id, v_queue_item.defense_type_id, v_units_to_complete)
        ON CONFLICT (planet_id, defense_type_id)
        DO UPDATE SET quantity = planet_defenses.quantity + v_units_to_complete;
      END IF;
      
      DELETE FROM shipyard_queue WHERE id = v_queue_item.id;
      
      UPDATE shipyard_queue
      SET queue_position = queue_position - 1
      WHERE planet_id = v_queue_item.planet_id
        AND queue_position > v_queue_item.queue_position;
      
      v_completed_units := v_completed_units + v_units_to_complete;
      
    EXCEPTION WHEN OTHERS THEN
      v_error_count := v_error_count + 1;
    END;
  END LOOP;
  
  UPDATE shipyard_queue sq
  SET start_time = NOW(),
      current_unit_end_time = NOW() + (sq.build_time_per_unit * INTERVAL '1 second')
  WHERE sq.queue_position = 1
    AND sq.start_time IS NULL;

  RETURN jsonb_build_object(
    'success', true,
    'completed_units', v_completed_units,
    'error_count', v_error_count
  );
END;
$$;


--
-- TOC entry 884 (class 1255 OID 20095)
-- Name: admin_purge_inactive_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_purge_inactive_account(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_is_admin boolean;
  v_target_profile record;
  v_days_inactive int;
  v_hours_played numeric;
  v_category text;
  v_planet_count int;
  v_deleted_data jsonb;
BEGIN
  v_admin_id := auth.uid();
  
  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_admin_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Acceso denegado');
  END IF;
  
  SELECT * INTO v_target_profile FROM profiles WHERE id = p_user_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Usuario no encontrado');
  END IF;
  
  IF COALESCE(v_target_profile.is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No se puede eliminar una cuenta de administrador');
  END IF;
  
  v_days_inactive := EXTRACT(DAY FROM (now() - COALESCE(v_target_profile.last_activity, v_target_profile.created_at)))::int;
  v_hours_played := ROUND(EXTRACT(EPOCH FROM (COALESCE(v_target_profile.last_activity, v_target_profile.created_at) - v_target_profile.created_at)) / 3600.0, 2);
  
  IF v_target_profile.last_activity IS NULL 
     OR v_target_profile.last_activity = v_target_profile.created_at
     OR EXTRACT(EPOCH FROM (v_target_profile.last_activity - v_target_profile.created_at)) < 3600 THEN
    v_category := 'never_played';
  ELSIF EXTRACT(EPOCH FROM (v_target_profile.last_activity - v_target_profile.created_at)) < 86400 THEN
    v_category := 'first_day_only';
  ELSE
    v_category := 'abandoned';
  END IF;

  SELECT COUNT(*)::int INTO v_planet_count FROM planets WHERE user_id = p_user_id;

  DELETE FROM alliance_members WHERE user_id = p_user_id;
  DELETE FROM alliance_applications WHERE user_id = p_user_id;
  
  UPDATE fleets 
  SET is_completed = true
  WHERE user_id = p_user_id AND is_completed = false;
  
  DELETE FROM messages WHERE sender_id = p_user_id OR recipient_id = p_user_id;
  DELETE FROM user_officers WHERE user_id = p_user_id;
  DELETE FROM market_listings WHERE seller_id = p_user_id;
  DELETE FROM research_queue WHERE user_id = p_user_id;
  
  DELETE FROM building_queue WHERE planet_id IN (SELECT id FROM planets WHERE user_id = p_user_id);
  DELETE FROM shipyard_queue WHERE planet_id IN (SELECT id FROM planets WHERE user_id = p_user_id);
  
  DELETE FROM fleets WHERE user_id = p_user_id;
  DELETE FROM planets WHERE user_id = p_user_id;
  DELETE FROM user_technologies WHERE user_id = p_user_id;
  DELETE FROM wallet_transactions WHERE user_id = p_user_id;
  DELETE FROM login_sessions WHERE user_id = p_user_id;
  
  DELETE FROM telegram_links WHERE user_id = p_user_id;
  DELETE FROM plus_subscriptions WHERE user_id = p_user_id;
  DELETE FROM public_chat_messages WHERE user_id = p_user_id;

  v_deleted_data := jsonb_build_object(
    'planets_deleted', v_planet_count,
    'fxu_balance', COALESCE(v_target_profile.fxu_balance, 0),
    'usdt_balance', COALESCE(v_target_profile.usdt_balance, 0),
    'points_total', COALESCE(v_target_profile.points_total, 0)
  );

  INSERT INTO admin_account_deletions (
    deleted_user_id,
    deleted_username,
    deleted_email,
    deletion_category,
    days_inactive,
    points_total,
    deleted_by,
    metadata
  ) VALUES (
    p_user_id,
    v_target_profile.username,
    v_target_profile.email,
    v_category,
    v_days_inactive,
    COALESCE(v_target_profile.points_total, 0),
    v_admin_id,
    v_deleted_data
  );
  
  DELETE FROM profiles WHERE id = p_user_id;
  
  DELETE FROM auth.users WHERE id = p_user_id;
  
  RETURN jsonb_build_object(
    'success', true, 
    'message', 'Cuenta eliminada completamente: ' || v_target_profile.username,
    'details', jsonb_build_object(
      'username', v_target_profile.username,
      'email', v_target_profile.email,
      'category', v_category,
      'days_inactive', v_days_inactive,
      'hours_played', v_hours_played,
      'planets_deleted', v_planet_count,
      'fxu_balance', COALESCE(v_target_profile.fxu_balance, 0),
      'usdt_balance', COALESCE(v_target_profile.usdt_balance, 0)
    )
  );
END;
$$;


--
-- TOC entry 961 (class 1255 OID 20565)
-- Name: admin_reject_twitter_action(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reject_twitter_action(p_action_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_action RECORD;
BEGIN
  -- Check if caller is admin
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- Get the action before deleting
  SELECT ta.id, ta.user_id, ta.action_type, p.username
  INTO v_action
  FROM twitter_actions ta
  JOIN profiles p ON p.id = ta.user_id
  WHERE ta.id = p_action_id AND ta.validated = false;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pending action not found');
  END IF;

  -- Delete the action so user can resubmit
  DELETE FROM twitter_actions WHERE id = p_action_id;

  RETURN jsonb_build_object(
    'success', true,
    'rejected', true,
    'username', v_action.username,
    'action_type', v_action.action_type
  );
END;
$$;


--
-- TOC entry 730 (class 1255 OID 19009)
-- Name: admin_request_withdrawal(numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_request_withdrawal(p_amount numeric, p_wallet_address text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_available_balance numeric;
  v_withdrawal_id uuid;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT is_admin INTO v_is_admin
  FROM profiles
  WHERE id = v_user_id;
  
  IF NOT v_is_admin THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores pueden usar esta funcion');
  END IF;
  
  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Monto invalido');
  END IF;
  
  IF p_wallet_address IS NULL OR p_wallet_address = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Direccion de wallet requerida');
  END IF;
  
  v_available_balance := get_admin_available_balance();
  
  IF p_amount > v_available_balance THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Saldo insuficiente. Disponible: ' || v_available_balance::text || ' FXU'
    );
  END IF;
  
  INSERT INTO admin_withdrawals (admin_id, amount, wallet_address, status)
  VALUES (v_user_id, p_amount, p_wallet_address, 'pending')
  RETURNING id INTO v_withdrawal_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'withdrawal_id', v_withdrawal_id,
    'amount', p_amount,
    'new_available_balance', v_available_balance - p_amount
  );
END;
$$;


--
-- TOC entry 777 (class 1255 OID 19283)
-- Name: admin_reset_all_fxu_balances(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reset_all_fxu_balances() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_count integer;
BEGIN
  -- Verify admin
  v_admin_id := auth.uid();
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RAISE EXCEPTION 'Access denied: Admin only';
  END IF;

  -- Disable the trigger temporarily
  ALTER TABLE profiles DISABLE TRIGGER protect_fxu_balance_trigger;

  -- Reset all FXU balances to 0
  UPDATE profiles SET fxu_balance = 0;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Re-enable the trigger
  ALTER TABLE profiles ENABLE TRIGGER protect_fxu_balance_trigger;

  RETURN jsonb_build_object(
    'success', true,
    'accounts_reset', v_count,
    'message', 'All FXU balances have been reset to 0'
  );
END;
$$;


--
-- TOC entry 909 (class 1255 OID 20243)
-- Name: admin_reset_monthly_sales(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reset_monthly_sales() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_is_admin boolean;
v_year_week text;
v_affected int;
BEGIN
SELECT is_admin INTO v_is_admin FROM profiles WHERE id = auth.uid();
IF NOT COALESCE(v_is_admin, false) THEN
RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
END IF;

v_year_week := to_char(now(), 'IYYY-"W"IW');

UPDATE market_monthly_sales
SET metal_sold = 0,
crystal_sold = 0,
deuterium_sold = 0,
updated_at = now()
WHERE year_month = v_year_week;

GET DIAGNOSTICS v_affected = ROW_COUNT;

RETURN jsonb_build_object(
'success', true,
'message', 'Se reiniciaron los contadores de ' || v_affected || ' usuarios para la semana ' || v_year_week
);
END;
$$;


--
-- TOC entry 879 (class 1255 OID 20064)
-- Name: admin_restore_all_affected_expedition_fleets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_restore_all_affected_expedition_fleets() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_fleet RECORD;
  v_result jsonb;
  v_restored_count integer := 0;
  v_error_count integer := 0;
  v_restorations jsonb := '[]'::jsonb;
BEGIN
  SELECT auth.uid() INTO v_user_id;
  
  IF v_user_id IS NOT NULL THEN
    SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
    IF NOT COALESCE(v_is_admin, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
    END IF;
  END IF;

  FOR v_fleet IN
    SELECT f.id, p.username
    FROM fleets f
    JOIN profiles p ON p.id = f.user_id
    WHERE f.mission_type = 'expedition'
      AND f.is_completed = true
      AND f.is_returning = true
      AND f.return_time > NOW() - INTERVAL '12 hours'
      AND NOT EXISTS (
        SELECT 1 FROM fleet_restoration_log frl WHERE frl.fleet_id = f.id
      )
    ORDER BY f.return_time DESC
  LOOP
    BEGIN
      v_result := admin_restore_fleet(v_fleet.id);
      
      IF (v_result->>'success')::boolean THEN
        v_restored_count := v_restored_count + 1;
        v_restorations := v_restorations || jsonb_build_object(
          'fleet_id', v_fleet.id,
          'username', v_fleet.username,
          'status', 'restored'
        );
      ELSE
        v_error_count := v_error_count + 1;
        v_restorations := v_restorations || jsonb_build_object(
          'fleet_id', v_fleet.id,
          'username', v_fleet.username,
          'status', 'error',
          'error', v_result->>'error'
        );
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_error_count := v_error_count + 1;
      v_restorations := v_restorations || jsonb_build_object(
        'fleet_id', v_fleet.id,
        'username', v_fleet.username,
        'status', 'exception',
        'error', SQLERRM
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'restored_count', v_restored_count,
    'error_count', v_error_count,
    'restorations', v_restorations
  );
END;
$$;


--
-- TOC entry 878 (class 1255 OID 20063)
-- Name: admin_restore_fleet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_restore_fleet(p_fleet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_fleet RECORD;
  v_ship RECORD;
  v_ships_restored jsonb := '[]'::jsonb;
  v_resources_restored jsonb;
  v_username text;
BEGIN
  SELECT auth.uid() INTO v_user_id;
  
  IF v_user_id IS NOT NULL THEN
    SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
    IF NOT COALESCE(v_is_admin, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
    END IF;
  END IF;

  SELECT f.*, p.username INTO v_fleet
  FROM fleets f
  JOIN profiles p ON p.id = f.user_id
  WHERE f.id = p_fleet_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Fleet not found');
  END IF;

  v_username := v_fleet.username;

  FOR v_ship IN
    SELECT fs.ship_type_id, fs.quantity, st.name as ship_name
    FROM fleet_ships fs
    JOIN ship_types st ON st.id = fs.ship_type_id
    WHERE fs.fleet_id = p_fleet_id
  LOOP
    INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
    VALUES (v_fleet.origin_planet_id, v_ship.ship_type_id, v_ship.quantity)
    ON CONFLICT (planet_id, ship_type_id)
    DO UPDATE SET quantity = planet_ships.quantity + v_ship.quantity;

    v_ships_restored := v_ships_restored || jsonb_build_object(
      'ship_name', v_ship.ship_name,
      'quantity', v_ship.quantity
    );
  END LOOP;

  UPDATE planet_resources SET
    metal = metal + COALESCE(v_fleet.cargo_metal, 0),
    crystal = crystal + COALESCE(v_fleet.cargo_crystal, 0),
    deuterium = deuterium + COALESCE(v_fleet.cargo_deuterium, 0)
  WHERE planet_id = v_fleet.origin_planet_id;

  v_resources_restored := jsonb_build_object(
    'metal', COALESCE(v_fleet.cargo_metal, 0),
    'crystal', COALESCE(v_fleet.cargo_crystal, 0),
    'deuterium', COALESCE(v_fleet.cargo_deuterium, 0)
  );

  INSERT INTO fleet_restoration_log (
    fleet_id, user_id, username, planet_id, 
    ships_restored, resources_restored, restored_by
  ) VALUES (
    p_fleet_id, v_fleet.user_id, v_username, v_fleet.origin_planet_id,
    v_ships_restored, v_resources_restored, v_user_id
  );

  INSERT INTO messages (recipient_id, subject, body, message_type)
  VALUES (
    v_fleet.user_id,
    'Flota de Expedicion Restaurada',
    'Debido a un error tecnico, tu flota de expedicion fue procesada incorrectamente. ' ||
    'Tus naves y recursos han sido restaurados a tu planeta de origen. ' ||
    'Disculpa las molestias causadas.',
    'system'
  );

  RETURN jsonb_build_object(
    'success', true,
    'username', v_username,
    'ships_restored', v_ships_restored,
    'resources_restored', v_resources_restored
  );
END;
$$;


--
-- TOC entry 810 (class 1255 OID 19522)
-- Name: admin_restore_telegram_reward(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_restore_telegram_reward(p_telegram_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_reward telegram_task_rewards%ROWTYPE;
  v_link telegram_links%ROWTYPE;
  v_old_balance numeric;
  v_new_balance numeric;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
  
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;

  SELECT * INTO v_reward 
  FROM telegram_task_rewards 
  WHERE telegram_id = p_telegram_id AND task_type = 'join_group';

  IF v_reward IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No reward record found for this telegram ID');
  END IF;

  IF NOT v_reward.reward_revoked THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reward is not revoked');
  END IF;

  SELECT * INTO v_link FROM telegram_links WHERE telegram_id = p_telegram_id;

  IF v_link IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No linked account found');
  END IF;

  SELECT fxu_balance INTO v_old_balance FROM profiles WHERE id = v_link.user_id;
  v_new_balance := v_old_balance + v_reward.reward_amount;

  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
  UPDATE profiles 
  SET fxu_balance = v_new_balance,
      updated_at = now()
  WHERE id = v_link.user_id;
  PERFORM set_config('fxu.allow_update_9x7k2m', 'false', true);

  UPDATE telegram_task_rewards
  SET reward_revoked = false,
      is_member = true,
      updated_at = now()
  WHERE id = v_reward.id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Reward restored successfully',
    'amount', v_reward.reward_amount,
    'old_balance', v_old_balance,
    'new_balance', v_new_balance,
    'telegram_username', v_link.telegram_username
  );
END;
$$;


--
-- TOC entry 875 (class 1255 OID 20050)
-- Name: admin_run_full_maintenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_run_full_maintenance() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_buildings_result jsonb;
  v_shipyard_result jsonb;
  v_fleets_result jsonb;
  v_research_result jsonb;
BEGIN
  SELECT auth.uid() INTO v_user_id;
  
  IF v_user_id IS NOT NULL THEN
    SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
    IF NOT COALESCE(v_is_admin, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
    END IF;
  END IF;

  SELECT admin_process_stuck_building_queues() INTO v_buildings_result;
  SELECT admin_process_stuck_shipyard_queues() INTO v_shipyard_result;
  SELECT admin_process_stuck_fleets() INTO v_fleets_result;
  SELECT admin_process_stuck_research() INTO v_research_result;

  RETURN jsonb_build_object(
    'success', true,
    'buildings', v_buildings_result,
    'shipyard', v_shipyard_result,
    'fleets', v_fleets_result,
    'research', v_research_result,
    'executed_at', NOW()
  );
END;
$$;


--
-- TOC entry 1113 (class 1255 OID 21760)
-- Name: admin_set_all_npc_planets_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_all_npc_planets_role(p_npc_id uuid, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
  v_is_bot boolean;
  v_username text;
  v_count integer;
BEGIN
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = auth.uid();
  IF v_is_admin IS NOT TRUE THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  IF p_role NOT IN ('balanced','miner','military','research','colonizer') THEN
    RAISE EXCEPTION 'Invalid role: %', p_role;
  END IF;

  SELECT is_bot, username INTO v_is_bot, v_username FROM profiles WHERE id = p_npc_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NPC not found';
  END IF;
  IF v_is_bot IS NOT TRUE THEN
    RAISE EXCEPTION 'Profile is not a bot/NPC';
  END IF;

  UPDATE planets
  SET autopilot_role = p_role,
      last_update = now()
  WHERE user_id = p_npc_id;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'npc_id', p_npc_id,
    'username', v_username,
    'planets_updated', v_count,
    'new_role', p_role
  );
END;
$$;


--
-- TOC entry 1107 (class 1255 OID 21753)
-- Name: admin_set_android_ai(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_android_ai(p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
BEGIN
  v_admin_id := auth.uid();
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores');
  END IF;

  UPDATE game_settings SET value = CASE WHEN p_enabled THEN 'true' ELSE 'false' END, updated_at = now() WHERE key = 'global_android_ai_enabled';
  PERFORM sync_android_ai_global();
  
  RETURN jsonb_build_object('success', true, 'enabled', p_enabled);
END;
$$;


--
-- TOC entry 1112 (class 1255 OID 21759)
-- Name: admin_set_npc_planet_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_npc_planet_role(p_planet_id uuid, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
  v_is_bot boolean;
  v_planet_name text;
BEGIN
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = auth.uid();
  IF v_is_admin IS NOT TRUE THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  IF p_role NOT IN ('balanced','miner','military','research','colonizer') THEN
    RAISE EXCEPTION 'Invalid role: %', p_role;
  END IF;

  SELECT p.is_bot, pl.name
    INTO v_is_bot, v_planet_name
  FROM planets pl
  JOIN profiles p ON p.id = pl.user_id
  WHERE pl.id = p_planet_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Planet not found';
  END IF;

  IF v_is_bot IS NOT TRUE THEN
    RAISE EXCEPTION 'Planet does not belong to a bot/NPC';
  END IF;

  UPDATE planets
  SET autopilot_role = p_role,
      last_update = now()
  WHERE id = p_planet_id;

  RETURN jsonb_build_object(
    'success', true,
    'planet_id', p_planet_id,
    'planet_name', v_planet_name,
    'new_role', p_role
  );
END;
$$;


--
-- TOC entry 1047 (class 1255 OID 21257)
-- Name: admin_set_planet_building(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_planet_building(p_planet_id uuid, p_building_type_id integer, p_level integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
  v_old_level integer;
  v_new_level integer;
  v_bld_name text;
  v_planet_exists boolean;
BEGIN
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = auth.uid();
  IF v_is_admin IS NOT TRUE THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  IF p_level < 0 THEN
    RAISE EXCEPTION 'Level must be >= 0';
  END IF;
  IF p_level > 50 THEN
    RAISE EXCEPTION 'Level cannot exceed 50';
  END IF;

  SELECT EXISTS(SELECT 1 FROM planets WHERE id = p_planet_id) INTO v_planet_exists;
  IF NOT v_planet_exists THEN
    RAISE EXCEPTION 'Planet not found';
  END IF;

  SELECT name INTO v_bld_name FROM building_types WHERE id = p_building_type_id;
  IF v_bld_name IS NULL THEN
    RAISE EXCEPTION 'Building type not found: %', p_building_type_id;
  END IF;

  SELECT COALESCE(level, 0) INTO v_old_level
  FROM planet_buildings
  WHERE planet_id = p_planet_id AND building_type_id = p_building_type_id;
  v_old_level := COALESCE(v_old_level, 0);

  IF p_level = 0 THEN
    DELETE FROM planet_buildings
    WHERE planet_id = p_planet_id AND building_type_id = p_building_type_id;
    v_new_level := 0;
  ELSE
    INSERT INTO planet_buildings (planet_id, building_type_id, level, is_upgrading)
    VALUES (p_planet_id, p_building_type_id, p_level, false)
    ON CONFLICT (planet_id, building_type_id)
      DO UPDATE SET level = EXCLUDED.level,
                    is_upgrading = false,
                    upgrade_end_time = NULL;
    v_new_level := p_level;
  END IF;

  RETURN jsonb_build_object(
    'success',   true,
    'planet_id', p_planet_id,
    'building_type_id', p_building_type_id,
    'building_name', v_bld_name,
    'old_level', v_old_level,
    'new_level', v_new_level
  );
END;
$$;


--
-- TOC entry 1046 (class 1255 OID 21256)
-- Name: admin_set_planet_ship(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_planet_ship(p_planet_id uuid, p_ship_type_id integer, p_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
  v_old_qty integer;
  v_new_qty integer;
  v_ship_name text;
  v_planet_exists boolean;
BEGIN
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = auth.uid();
  IF v_is_admin IS NOT TRUE THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  IF p_quantity < 0 THEN
    RAISE EXCEPTION 'Quantity must be >= 0';
  END IF;

  SELECT EXISTS(SELECT 1 FROM planets WHERE id = p_planet_id) INTO v_planet_exists;
  IF NOT v_planet_exists THEN
    RAISE EXCEPTION 'Planet not found';
  END IF;

  SELECT name INTO v_ship_name FROM ship_types WHERE id = p_ship_type_id;
  IF v_ship_name IS NULL THEN
    RAISE EXCEPTION 'Ship type not found: %', p_ship_type_id;
  END IF;

  SELECT COALESCE(quantity, 0) INTO v_old_qty
  FROM planet_ships
  WHERE planet_id = p_planet_id AND ship_type_id = p_ship_type_id;
  v_old_qty := COALESCE(v_old_qty, 0);

  IF p_quantity = 0 THEN
    DELETE FROM planet_ships
    WHERE planet_id = p_planet_id AND ship_type_id = p_ship_type_id;
    v_new_qty := 0;
  ELSE
    INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
    VALUES (p_planet_id, p_ship_type_id, p_quantity)
    ON CONFLICT (planet_id, ship_type_id)
      DO UPDATE SET quantity = EXCLUDED.quantity;
    v_new_qty := p_quantity;
  END IF;

  RETURN jsonb_build_object(
    'success',   true,
    'planet_id', p_planet_id,
    'ship_type_id', p_ship_type_id,
    'ship_name', v_ship_name,
    'old_quantity', v_old_qty,
    'new_quantity', v_new_qty
  );
END;
$$;


