--
-- TOC entry 1017 (class 1255 OID 20930)
-- Name: admin_toggle_autopilot_eligible(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_toggle_autopilot_eligible(p_user_id uuid, p_eligible boolean) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_admin BOOLEAN;
BEGIN
  SELECT is_admin INTO v_admin FROM profiles WHERE id = auth.uid();
  IF NOT COALESCE(v_admin, false) THEN
    RETURN json_build_object('success', false, 'error', 'No autorizado');
  END IF;

  UPDATE profiles 
  SET autopilot_eligible = p_eligible,
      -- If disabling eligibility, also disable active
      autopilot_active = CASE WHEN p_eligible = false THEN false ELSE autopilot_active END
  WHERE id = p_user_id;

  RETURN json_build_object('success', true);
END;
$$;


