    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  IF p_multiplier < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'El multiplicador no puede ser negativo');
  END IF;

  INSERT INTO game_settings (key, value, description)
  VALUES ('monthly_limit_fxu_multiplier', p_multiplier::text, 'Multiplier for lifetime FXU spent in monthly market limit formula')
  ON CONFLICT (key) DO UPDATE SET value = p_multiplier::text;

  RETURN jsonb_build_object(
    'success', true,
    'multiplier', p_multiplier,
    'message', 'Multiplicador actualizado a x' || p_multiplier
  );
END;
$$;


