--
-- TOC entry 982 (class 1255 OID 20611)
-- Name: admin_validate_twitter_action_api(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_validate_twitter_action_api(p_action_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public'
    AS $$
DECLARE
  v_action RECORD;
  v_mission RECORD;
  v_twitter_link RECORD;
  v_bearer_token TEXT;
  v_tweet_id TEXT;
  v_response RECORD;
  v_json JSONB;
  v_tweet_text TEXT;
  v_tweet_author TEXT;
  v_referenced JSONB;
  v_hashtags TEXT[];
  v_missing TEXT[];
  v_tag TEXT;
  v_api_url TEXT;
BEGIN
  -- Check if caller is admin
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- Get Twitter Bearer Token from admin_config
  SELECT value INTO v_bearer_token FROM admin_config WHERE key = 'twitter_bearer_token';
  IF v_bearer_token IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 
      'Twitter Bearer Token not configured. Execute in SQL Editor: INSERT INTO admin_config (key, value) VALUES (''twitter_bearer_token'', ''YOUR_TOKEN_HERE'')');
  END IF;

  -- Get the action with username
  SELECT ta.id, ta.user_id, ta.mission_id, ta.user_tweet_url, ta.action_type, 
         ta.points_awarded, ta.validated, p.username
  INTO v_action
  FROM twitter_actions ta
  JOIN profiles p ON p.id = ta.user_id
  WHERE ta.id = p_action_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Action not found');
  END IF;

  IF v_action.validated THEN
    RETURN jsonb_build_object('success', true, 'already_validated', true, 'message', 'Already validated');
  END IF;

  -- Get the mission
  SELECT * INTO v_mission FROM twitter_missions WHERE id = v_action.mission_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mission not found');
  END IF;

  -- Get user's twitter link
  SELECT * INTO v_twitter_link FROM twitter_links WHERE user_id = v_action.user_id;

  -- Extract tweet ID from URL (e.g., https://x.com/user/status/1234567890)
  v_tweet_id := (regexp_match(v_action.user_tweet_url, '/status/(\d+)'))[1];
  IF v_tweet_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid tweet URL: cannot extract tweet ID');
  END IF;

  -- Build Twitter API v2 URL
  v_api_url := 'https://api.twitter.com/2/tweets/' || v_tweet_id 
    || '?tweet.fields=author_id,referenced_tweets,text&expansions=author_id&user.fields=username';

  -- Call Twitter API v2 via HTTP extension
  BEGIN
    SELECT status, content 
    INTO v_response
    FROM http((
      'GET',
      v_api_url,
      ARRAY[http_header('Authorization', 'Bearer ' || v_bearer_token)],
      NULL,
      NULL
    )::http_request);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Failed to connect to Twitter API: ' || SQLERRM);
  END;

  -- Check HTTP status
  IF v_response.status = 429 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Twitter API rate limit. Try again in a few minutes.', 'rate_limited', true);
  END IF;

  IF v_response.status != 200 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Twitter API error (HTTP ' || v_response.status || ')');
  END IF;

  -- Parse JSON response
  BEGIN
    v_json := v_response.content::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid response from Twitter API');
  END;

  -- CHECK 1: Tweet exists
  IF v_json->'data' IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tweet not found or has been deleted');
  END IF;

  v_tweet_text := lower(v_json->'data'->>'text');

  -- CHECK 2: Author matches linked Twitter account
  IF v_json->'includes'->'users' IS NOT NULL AND jsonb_array_length(v_json->'includes'->'users') > 0 AND v_twitter_link.twitter_username IS NOT NULL THEN
    v_tweet_author := lower(v_json->'includes'->'users'->0->>'username');
    IF v_tweet_author != lower(v_twitter_link.twitter_username) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Tweet author (@' || v_tweet_author || ') does not match linked account (@' || v_twitter_link.twitter_username || ')'
      );
    END IF;
  END IF;

  -- CHECK 3: Required hashtags
  v_hashtags := ARRAY['#falcox', '#xnova', '#ogames'];
  v_missing := ARRAY[]::TEXT[];
  FOREACH v_tag IN ARRAY v_hashtags LOOP
    IF position(v_tag in v_tweet_text) = 0 THEN
      v_missing := array_append(v_missing, v_tag);
    END IF;
  END LOOP;

  IF array_length(v_missing, 1) > 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Missing hashtags: ' || array_to_string(v_missing, ', ')
    );
  END IF;

  -- CHECK 4: For quote tweets, verify it references the mission tweet
  IF v_action.action_type = 'quote_tweet' THEN
    v_referenced := v_json->'data'->'referenced_tweets';
    IF v_referenced IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_referenced) elem
      WHERE elem->>'type' = 'quoted' AND elem->>'id' = v_mission.tweet_id
    ) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'This tweet does NOT quote the mission tweet (expected quote of tweet ' || v_mission.tweet_id || ')'
      );
    END IF;
  END IF;

  -- CHECK 5: For comments, verify it's a reply to the mission tweet
  IF v_action.action_type = 'comment' THEN
    v_referenced := v_json->'data'->'referenced_tweets';
    IF v_referenced IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_referenced) elem
      WHERE elem->>'type' = 'replied_to' AND elem->>'id' = v_mission.tweet_id
    ) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'This tweet is NOT a reply to the mission tweet (expected reply to tweet ' || v_mission.tweet_id || ')'
      );
    END IF;
  END IF;

  -- ALL CHECKS PASSED → Approve the action
  UPDATE twitter_actions SET validated = true WHERE id = p_action_id;

  RETURN jsonb_build_object(
    'success', true,
    'validated', true,
    'username', v_action.username,
    'action_type', v_action.action_type,
    'points', v_action.points_awarded,
    'tweet_author', COALESCE(v_tweet_author, 'unknown'),
    'message', '✅ Verified via Twitter API | @' || COALESCE(v_tweet_author, '?') || ' | ' 
      || CASE WHEN v_action.action_type = 'quote_tweet' THEN 'Quote Tweet' ELSE 'Comment' END 
      || ' | +' || v_action.points_awarded || ' pts'
  );
END;
$$;


--
-- TOC entry 1082 (class 1255 OID 21457)
-- Name: apply_hero_regen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_hero_regen(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ship record;
  v_elapsed_hours numeric;
  v_hp_per_hour numeric;
  v_shipyard_level integer;
  v_robotics_level integer;
  v_nanite_level integer;
  v_denom numeric;
  v_repair_hours numeric;
  v_active_expedition uuid;
  v_hp_gain integer;
BEGIN
  SELECT id INTO v_active_expedition FROM hero_ship_active_expedition
  WHERE user_id = p_user_id AND claimed = false LIMIT 1;

  SELECT COALESCE(MAX(CASE WHEN bt.code = 'shipyard' THEN pb.level END), 0),
         COALESCE(MAX(CASE WHEN bt.code = 'robotics_factory' THEN pb.level END), 0),
         COALESCE(MAX(CASE WHEN bt.code = 'nanite_factory' THEN pb.level END), 0)
  INTO v_shipyard_level, v_robotics_level, v_nanite_level
  FROM planets p
  JOIN planet_buildings pb ON pb.planet_id = p.id
  JOIN building_types bt ON bt.id = pb.building_type_id
  WHERE p.user_id = p_user_id AND p.is_main_planet = true;

  SELECT * INTO v_ship FROM user_hero_ships WHERE user_id = p_user_id;
  IF NOT FOUND THEN RETURN; END IF;

  IF v_active_expedition IS NOT NULL THEN
    UPDATE user_hero_ships SET last_regen_at = now() WHERE user_id = p_user_id;
    RETURN;
  END IF;

  IF v_ship.hp >= v_ship.hp_max THEN
    UPDATE user_hero_ships SET last_regen_at = now() WHERE user_id = p_user_id;
    RETURN;
  END IF;

  v_elapsed_hours := EXTRACT(EPOCH FROM (now() - v_ship.last_regen_at)) / 3600;
  IF v_elapsed_hours <= 0 THEN RETURN; END IF;

  v_denom := 1 + v_shipyard_level * 0.08 + v_robotics_level * 0.1 + v_nanite_level * 0.12;
  v_repair_hours := GREATEST(24, LEAST(240, 240 / v_denom));
  v_hp_per_hour := v_ship.hp_max / v_repair_hours;
  v_hp_gain := LEAST(FLOOR(v_elapsed_hours * v_hp_per_hour), v_ship.hp_max - v_ship.hp);

  IF v_hp_gain > 0 THEN
    UPDATE user_hero_ships SET hp = hp + v_hp_gain, last_regen_at = now(), updated_at = now()
    WHERE user_id = p_user_id;
  ELSE
    UPDATE user_hero_ships SET last_regen_at = now() WHERE user_id = p_user_id;
  END IF;
END;
$$;


--
-- TOC entry 1070 (class 1255 OID 21434)
-- Name: assign_daily_missions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_daily_missions(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE
      v_today date := current_date;
      v_count integer;
      v_missions integer[];
      v_mid integer;
    BEGIN
      SELECT COUNT(*) INTO v_count
      FROM user_daily_missions
      WHERE user_id = p_user_id AND expires_at::date = v_today AND expires_at > now();

      IF v_count >= 3 THEN
        RETURN jsonb_build_object('success', true, 'count', v_count, 'message', 'Ya tienes 3 misiones asignadas hoy');
      END IF;

      -- Exclude missions already assigned today to prevent duplicates
      SELECT ARRAY_AGG(id) INTO v_missions
      FROM (
        SELECT dm.id FROM daily_missions dm
        WHERE dm.is_active = true
          AND (dm.cost_fxu IS NULL OR dm.cost_fxu = 0)
          AND dm.id NOT IN (
            SELECT udm.mission_id FROM user_daily_missions udm
            WHERE udm.user_id = p_user_id AND udm.expires_at::date = v_today AND udm.expires_at > now()
          )
        ORDER BY random()
        LIMIT (3 - v_count)
      ) sub;

      IF v_missions IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'No hay misiones activas disponibles');
      END IF;

      FOREACH v_mid IN ARRAY v_missions
      LOOP
        INSERT INTO user_daily_missions (user_id, mission_id, progress, expires_at)
        VALUES (p_user_id, v_mid, 0, (v_today + interval '1 day')::date)
        ON CONFLICT (user_id, mission_id, expires_at) DO NOTHING;
      END LOOP;

      RETURN jsonb_build_object('success', true, 'count', v_count + array_length(v_missions, 1));
    END;
    $$;


--
-- TOC entry 914 (class 1255 OID 20303)
-- Name: attempt_expedition_pool_win(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attempt_expedition_pool_win(p_user_id uuid, p_guaranteed boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pool_balance numeric;
  v_roll numeric;
  v_win_chance numeric := 8;
  v_won boolean := false;
  v_win_amount numeric := 0;
  v_win_percent numeric;
  v_new_balance numeric;
BEGIN
  SELECT expedition_balance INTO v_pool_balance FROM jackpot_pools WHERE id = 1;

  IF v_pool_balance IS NULL OR v_pool_balance < 10 THEN
    RETURN jsonb_build_object(
      'won', false,
      'amount', 0,
      'reason', 'pool_too_small',
      'current_pool', COALESCE(v_pool_balance, 0)
    );
  END IF;

  v_roll := random() * 100;

  IF p_guaranteed OR v_roll < v_win_chance THEN
    v_won := true;

    v_win_percent := 1;
    v_win_amount := floor(v_pool_balance * (v_win_percent / 100));

    IF v_win_amount < 1 THEN
      v_win_amount := 1;
    END IF;

    UPDATE jackpot_pools
    SET
      expedition_balance = expedition_balance - v_win_amount,
      updated_at = now()
    WHERE id = 1
    RETURNING expedition_balance INTO v_new_balance;

    UPDATE jackpot
    SET
      balance = balance - v_win_amount,
      total_won = total_won + v_win_amount,
      last_winner_id = p_user_id,
      last_won_at = now(),
      last_won_amount = v_win_amount,
      updated_at = now()
    WHERE id = 1;

    PERFORM _internal_set_fxu_context();

    UPDATE profiles
    SET fxu_balance = fxu_balance + v_win_amount
    WHERE id = p_user_id;

    INSERT INTO jackpot_history (user_id, type, amount, source, jackpot_balance_after)
    VALUES (p_user_id, 'win', v_win_amount, 'expedition_pool', v_new_balance);
  END IF;

  RETURN jsonb_build_object(
    'won', v_won,
    'amount', v_win_amount,
    'current_pool', CASE WHEN v_won THEN v_new_balance ELSE v_pool_balance END
  );
END;
$$;


--
-- TOC entry 793 (class 1255 OID 19392)
-- Name: attempt_jackpot_win(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attempt_jackpot_win(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_config jackpot_config%ROWTYPE;
  v_jackpot jackpot%ROWTYPE;
  v_roll numeric;
  v_won boolean := false;
  v_win_amount numeric := 0;
  v_win_percent numeric;
  v_new_balance numeric;
BEGIN
  SELECT * INTO v_config FROM jackpot_config WHERE id = 1;
  SELECT * INTO v_jackpot FROM jackpot WHERE id = 1;
  
  IF v_jackpot.balance < v_config.min_jackpot_for_win THEN
    RETURN jsonb_build_object(
      'won', false,
      'amount', 0,
      'reason', 'jackpot_too_small',
      'current_jackpot', v_jackpot.balance
    );
  END IF;

  v_roll := random() * 100;
  
  IF v_roll < v_config.win_chance THEN
    v_won := true;
    
    v_win_percent := v_config.min_win_percent + 
      (random() * (v_config.max_win_percent - v_config.min_win_percent));
    
    v_win_amount := floor(v_jackpot.balance * (v_win_percent / 100));
    
    UPDATE jackpot
    SET 
      balance = balance - v_win_amount,
      total_won = total_won + v_win_amount,
      last_winner_id = p_user_id,
      last_won_at = now(),
      last_won_amount = v_win_amount,
      updated_at = now()
    WHERE id = 1
    RETURNING balance INTO v_new_balance;
    
    PERFORM _internal_set_fxu_context();
    
    UPDATE profiles
    SET fxu_balance = fxu_balance + v_win_amount
    WHERE id = p_user_id;
    
    INSERT INTO jackpot_history (user_id, type, amount, source, jackpot_balance_after)
    VALUES (p_user_id, 'win', v_win_amount, 'expedition', v_new_balance);
    
    INSERT INTO messages (recipient_id, sender_name, subject, content, message_type)
    VALUES (
      p_user_id,
      'Jackpot System',
      'JACKPOT WINNER!',
      'Congratulations! Your expedition discovered the legendary treasure! You won ' || 
        floor(v_win_amount)::text || ' FXU from the jackpot!',
      'system'
    );
  END IF;

  RETURN jsonb_build_object(
    'won', v_won,
    'amount', v_win_amount,
    'current_jackpot', CASE WHEN v_won THEN v_new_balance ELSE v_jackpot.balance END
  );
END;
$$;


--
-- TOC entry 815 (class 1255 OID 19631)
-- Name: auto_cancel_insufficient_listings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_cancel_insufficient_listings(p_planet_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet_owner uuid;
  v_resources RECORD;
  v_listing RECORD;
  v_ship_qty integer;
  v_total_listed bigint;
  v_cancelled_count integer := 0;
BEGIN
  -- Get planet owner
  SELECT user_id INTO v_planet_owner FROM planets WHERE id = p_planet_id;
  IF v_planet_owner IS NULL THEN
    RETURN;
  END IF;

  -- Get current resources
  SELECT metal, crystal, deuterium INTO v_resources
  FROM planet_resources WHERE planet_id = p_planet_id;
  
  IF v_resources IS NULL THEN
    RETURN;
  END IF;

  -- Check and cancel resource listings that exceed available resources
  -- We need to consider ALL active listings for this resource type and cancel from newest first
  
  -- Metal listings
  FOR v_listing IN 
    SELECT id, quantity, item_code
    FROM market_listings 
    WHERE planet_id = p_planet_id 
    AND status = 'active' 
    AND listing_type = 'resource'
    AND item_code = 'metal'
    ORDER BY created_at DESC
  LOOP
    -- Calculate total metal listed (excluding current listing)
    SELECT COALESCE(SUM(quantity), 0) INTO v_total_listed
    FROM market_listings
    WHERE planet_id = p_planet_id
    AND status = 'active'
    AND listing_type = 'resource'
    AND item_code = 'metal'
    AND id != v_listing.id;
    
    -- If this listing + others exceeds available, cancel this one
    IF (v_total_listed + v_listing.quantity) > v_resources.metal THEN
      UPDATE market_listings SET status = 'cancelled', updated_at = now() WHERE id = v_listing.id;
      v_cancelled_count := v_cancelled_count + 1;
      
      -- Send notification
      INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
      VALUES (
        v_planet_owner,
        v_planet_owner,
        'Venta cancelada automaticamente',
        'Tu venta de ' || v_listing.quantity || ' metal fue cancelada porque ya no tienes suficientes recursos.',
        'system'
      );
    END IF;
  END LOOP;

  -- Crystal listings
  FOR v_listing IN 
    SELECT id, quantity, item_code
    FROM market_listings 
    WHERE planet_id = p_planet_id 
    AND status = 'active' 
    AND listing_type = 'resource'
    AND item_code = 'crystal'
    ORDER BY created_at DESC
  LOOP
    SELECT COALESCE(SUM(quantity), 0) INTO v_total_listed
    FROM market_listings
    WHERE planet_id = p_planet_id
    AND status = 'active'
    AND listing_type = 'resource'
    AND item_code = 'crystal'
    AND id != v_listing.id;
    
    IF (v_total_listed + v_listing.quantity) > v_resources.crystal THEN
      UPDATE market_listings SET status = 'cancelled', updated_at = now() WHERE id = v_listing.id;
      v_cancelled_count := v_cancelled_count + 1;
      
      INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
      VALUES (
        v_planet_owner,
        v_planet_owner,
        'Venta cancelada automaticamente',
        'Tu venta de ' || v_listing.quantity || ' cristal fue cancelada porque ya no tienes suficientes recursos.',
        'system'
      );
    END IF;
  END LOOP;

  -- Deuterium listings
  FOR v_listing IN 
    SELECT id, quantity, item_code
    FROM market_listings 
    WHERE planet_id = p_planet_id 
    AND status = 'active' 
    AND listing_type = 'resource'
    AND item_code = 'deuterium'
    ORDER BY created_at DESC
  LOOP
    SELECT COALESCE(SUM(quantity), 0) INTO v_total_listed
    FROM market_listings
    WHERE planet_id = p_planet_id
    AND status = 'active'
    AND listing_type = 'resource'
    AND item_code = 'deuterium'
    AND id != v_listing.id;
    
    IF (v_total_listed + v_listing.quantity) > v_resources.deuterium THEN
      UPDATE market_listings SET status = 'cancelled', updated_at = now() WHERE id = v_listing.id;
      v_cancelled_count := v_cancelled_count + 1;
      
      INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
      VALUES (
        v_planet_owner,
        v_planet_owner,
        'Venta cancelada automaticamente',
        'Tu venta de ' || v_listing.quantity || ' deuterio fue cancelada porque ya no tienes suficientes recursos.',
        'system'
      );
    END IF;
  END LOOP;

  -- Ship listings
  FOR v_listing IN 
    SELECT ml.id, ml.quantity, ml.item_code, st.id as ship_type_id
    FROM market_listings ml
    JOIN ship_types st ON st.code = ml.item_code
    WHERE ml.planet_id = p_planet_id 
    AND ml.status = 'active' 
    AND ml.listing_type = 'ship'
    ORDER BY ml.created_at DESC
  LOOP
    -- Get current ship quantity
    SELECT COALESCE(quantity, 0) INTO v_ship_qty
    FROM planet_ships
    WHERE planet_id = p_planet_id AND ship_type_id = v_listing.ship_type_id;
    
    -- Calculate total ships of this type listed (excluding current)
    SELECT COALESCE(SUM(ml.quantity), 0) INTO v_total_listed
    FROM market_listings ml
    JOIN ship_types st ON st.code = ml.item_code
    WHERE ml.planet_id = p_planet_id
    AND ml.status = 'active'
    AND ml.listing_type = 'ship'
    AND st.id = v_listing.ship_type_id
    AND ml.id != v_listing.id;
    
    IF (v_total_listed + v_listing.quantity) > v_ship_qty THEN
      UPDATE market_listings SET status = 'cancelled', updated_at = now() WHERE id = v_listing.id;
      v_cancelled_count := v_cancelled_count + 1;
      
      INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
      VALUES (
        v_planet_owner,
        v_planet_owner,
        'Venta cancelada automaticamente',
        'Tu venta de ' || v_listing.quantity || ' ' || v_listing.item_code || ' fue cancelada porque ya no tienes suficientes naves.',
        'system'
      );
    END IF;
  END LOOP;
END;
$$;


--
-- TOC entry 1104 (class 1255 OID 21696)
-- Name: auto_resolve_single_war(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_resolve_single_war(p_war_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_war alliance_wars%ROWTYPE;
  v_winner record;
  v_member record;
  v_leader_fee integer;
  v_winner_share integer;
  v_admin_share integer;
  v_reserve_share integer;
  v_remainder integer;
  v_member_count integer;
  v_per_member integer;
  v_admin_id uuid;
  v_leader_id uuid;
  v_hof record;
BEGIN
  SELECT * INTO v_war FROM alliance_wars WHERE id = p_war_id AND status = 'active' AND end_time <= now();
  IF NOT FOUND THEN RETURN; END IF;

  SELECT aws.alliance_id, a.name as alliance_name, a.tag as alliance_tag, aws.total_score, aws.battle_count
  INTO v_winner
  FROM alliance_war_scores aws
  JOIN alliances a ON a.id = aws.alliance_id
  WHERE aws.war_id = p_war_id
  ORDER BY aws.total_score DESC, aws.battle_count DESC
  LIMIT 1;

  IF NOT FOUND THEN
    UPDATE alliance_wars SET status = 'cancelled', resolved_at = now() WHERE id = p_war_id;
    RETURN;
  END IF;

  v_winner_share := FLOOR(v_war.total_pool_fxu * 0.70);
  v_admin_share := FLOOR(v_war.total_pool_fxu * 0.15);
  v_reserve_share := v_war.total_pool_fxu - v_winner_share - v_admin_share;

  SELECT COALESCE(paid_fee, 0) INTO v_leader_fee
  FROM alliance_war_entries WHERE war_id = p_war_id AND alliance_id = v_winner.alliance_id;

  SELECT leader_id INTO v_leader_id FROM alliances WHERE id = v_winner.alliance_id;

  IF v_leader_id IS NOT NULL AND v_leader_fee > 0 AND v_leader_fee <= v_winner_share THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_leader_fee WHERE id = v_leader_id;
    v_remainder := v_winner_share - v_leader_fee;
  ELSE
    v_remainder := v_winner_share;
  END IF;

  SELECT COUNT(*) INTO v_member_count FROM alliance_members WHERE alliance_id = v_winner.alliance_id;
  IF v_member_count > 0 AND v_remainder > 0 THEN
    v_per_member := FLOOR(v_remainder / v_member_count);
    FOR v_member IN SELECT user_id FROM alliance_members WHERE alliance_id = v_winner.alliance_id LOOP
      UPDATE profiles SET fxu_balance = fxu_balance + v_per_member WHERE id = v_member.user_id;
    END LOOP;
  END IF;

  IF v_admin_share > 0 THEN
    SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
    IF v_admin_id IS NOT NULL THEN
      UPDATE profiles SET fxu_balance = fxu_balance + v_admin_share WHERE id = v_admin_id;
    END IF;
    PERFORM record_admin_revenue('alliance_war', v_admin_share, 'War auto-resolve: ' || v_war.title, v_winner.alliance_id, NULL);
  END IF;

  IF v_reserve_share > 0 THEN
    UPDATE alliance_war_reserve_pool SET amount_fxu = amount_fxu + v_reserve_share, updated_at = now()
    WHERE id = '00000000-0000-0000-0000-000000000001'::uuid;
  END IF;

  UPDATE alliance_wars SET status = 'completed', winner_alliance_id = v_winner.alliance_id, resolved_at = now() WHERE id = p_war_id;

  SELECT * INTO v_hof FROM alliance_war_hall_of_fame WHERE alliance_id = v_winner.alliance_id;
  IF NOT FOUND THEN
    INSERT INTO alliance_war_hall_of_fame (alliance_id, alliance_name, alliance_tag, total_wins, total_wars, total_fxu_won, last_win_at)
    VALUES (v_winner.alliance_id, v_winner.alliance_name, v_winner.alliance_tag, 1, 1, v_winner_share, now());
  ELSE
    UPDATE alliance_war_hall_of_fame
    SET total_wins = total_wins + 1, total_wars = total_wars + 1, total_fxu_won = total_fxu_won + v_winner_share,
        last_win_at = now(), alliance_name = v_winner.alliance_name, alliance_tag = v_winner.alliance_tag
    WHERE alliance_id = v_winner.alliance_id;
  END IF;

  UPDATE alliance_war_hall_of_fame SET total_wars = total_wars + 1
  FROM alliance_war_entries awe
  WHERE alliance_war_hall_of_fame.alliance_id = awe.alliance_id AND awe.war_id = p_war_id AND awe.alliance_id != v_winner.alliance_id;
END;
$$;


--
-- TOC entry 1127 (class 1255 OID 21953)
-- Name: award_expedition_blueprint_drop(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.award_expedition_blueprint_drop() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg expedition_blueprint_drop_config%ROWTYPE;
  v_roll numeric;
  v_blueprint_id bigint;
BEGIN
  IF NOT (NEW.mission_type = 'expedition' AND NEW.is_completed = true AND COALESCE(OLD.is_completed, false) = false) THEN
    RETURN NEW;
  END IF;

  IF EXISTS (SELECT 1 FROM expedition_blueprint_drops WHERE fleet_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_cfg FROM expedition_blueprint_drop_config WHERE id = 1;
  IF v_cfg IS NULL OR v_cfg.is_enabled = false THEN
    RETURN NEW;
  END IF;

  v_roll := random();
  IF v_roll > v_cfg.drop_chance THEN
    RETURN NEW;
  END IF;

  -- Para consumibles, permitimos repetidos (acumulables)
  SELECT sb.id INTO v_blueprint_id
  FROM ship_blueprints sb
  WHERE sb.is_active = true
  ORDER BY random()
  LIMIT 1;

  IF v_blueprint_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO user_ship_blueprints (user_id, blueprint_id, source, metadata)
  VALUES (
    NEW.user_id,
    v_blueprint_id,
    'expedition',
    jsonb_build_object('fleet_id', NEW.id, 'roll', v_roll, 'chance', v_cfg.drop_chance)
  );

  INSERT INTO expedition_blueprint_drops (fleet_id, user_id, blueprint_id, roll_value, chance_used)
  VALUES (NEW.id, NEW.user_id, v_blueprint_id, v_roll, v_cfg.drop_chance)
  ON CONFLICT (fleet_id) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- TOC entry 1013 (class 1255 OID 20898)
-- Name: batch_update_player_points(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.batch_update_player_points() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER := 0;
  v_user_id UUID;
  v_buildings INTEGER;
  v_research INTEGER;
  v_fleet INTEGER;
  v_defense INTEGER;
BEGIN
  -- Process all queued users in one batch
  FOR v_user_id IN
    DELETE FROM points_update_queue
    RETURNING user_id
  LOOP
    -- Calculate all 4 categories once per user
    v_buildings := calculate_building_points(v_user_id);
    v_research := calculate_research_points(v_user_id);
    v_fleet := calculate_fleet_points(v_user_id);
    v_defense := calculate_defense_points(v_user_id);

    UPDATE profiles SET
      points_buildings = v_buildings,
      points_research = v_research,
      points_fleet = v_fleet,
      points_defense = v_defense,
      points_total = v_buildings + v_research + v_fleet + v_defense
    WHERE id = v_user_id;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


