--
-- TOC entry 1109 (class 1255 OID 21755)
-- Name: bot_farm_inactive_players(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_farm_inactive_players() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bot RECORD;
  v_planet RECORD;
  v_target RECORD;
  v_combat_ships integer;
  v_small_cargo_count integer;
  v_large_cargo_count integer;
  v_light_fighter_count integer;
  v_small_cargo_type_id integer;
  v_large_cargo_type_id integer;
  v_light_fighter_type_id integer;
  v_send_lf integer;
  v_send_sc integer;
  v_send_lc integer;
  v_fleet_result jsonb;
BEGIN
  SELECT id INTO v_small_cargo_type_id FROM ship_types WHERE code = 'small_cargo' LIMIT 1;
  SELECT id INTO v_large_cargo_type_id FROM ship_types WHERE code = 'large_cargo' LIMIT 1;
  SELECT id INTO v_light_fighter_type_id FROM ship_types WHERE code = 'light_fighter' LIMIT 1;

  FOR v_bot IN SELECT id FROM profiles WHERE (is_bot = true OR autopilot_active = true) AND is_banned = false LOOP
    FOR v_planet IN
      SELECT p.*
      FROM planets p
      WHERE p.user_id = v_bot.id AND p.planet_type = 'planet'
        AND EXISTS (SELECT 1 FROM planet_ships ps WHERE ps.planet_id = p.id AND ps.ship_type_id IN (v_light_fighter_type_id, (SELECT id FROM ship_types WHERE code = 'heavy_fighter' LIMIT 1)))
      LIMIT 3
    LOOP
      -- Count combat + cargo ships
      SELECT COALESCE(SUM(ps.quantity), 0) INTO v_combat_ships
      FROM planet_ships ps
      WHERE ps.planet_id = v_planet.id
        AND ps.ship_type_id IN (SELECT id FROM ship_types WHERE code IN ('light_fighter','heavy_fighter','cruiser','battleship','battlecruiser','bomber','destroyer','nova','falco_x'));

      IF v_combat_ships < 5 THEN CONTINUE; END IF;

      -- Find inactive targets (no activity > 7 days, not in vacation, low points)
      FOR v_target IN
        SELECT p.galaxy, p.solar_system, p.position, pr.username,
               COALESCE(pr.points_total, 0) as points,
               COALESCE(pr.last_activity, pr.created_at) as last_act
        FROM planets p
        JOIN profiles pr ON pr.id = p.user_id
        WHERE p.planet_type = 'planet'
          AND pr.is_banned = false
          AND COALESCE(pr.vacation_mode, false) = false
          AND pr.is_bot = false
          AND pr.id <> v_bot.id
          AND COALESCE(pr.last_activity, pr.created_at) < NOW() - interval '7 days'
          AND COALESCE(pr.points_total, 0) < 50000
          AND p.galaxy = v_planet.galaxy
          AND ABS(p.solar_system - v_planet.solar_system) <= 10
          -- Not in our alliance
          AND NOT EXISTS (
            SELECT 1 FROM alliance_members am1
            JOIN alliance_members am2 ON am2.alliance_id = am1.alliance_id
            WHERE am1.user_id = v_bot.id AND am2.user_id = pr.id
          )
          -- Not attacked same target in last 24h (max 2x/day)
          AND (
            SELECT COUNT(*) FROM fleets f
            WHERE f.user_id = v_bot.id 
              AND f.target_galaxy = p.galaxy 
              AND f.target_system = p.solar_system 
              AND f.target_position = p.position
              AND f.mission_type = 'attack'
              AND f.departure_time > NOW() - interval '24 hours'
          ) < 2
        ORDER BY pr.last_activity ASC NULLS FIRST, pr.points_total ASC
        LIMIT 3
      LOOP
        -- Send light raiding party: 20% LF + cargo for loot
        SELECT COALESCE(ps.quantity, 0) INTO v_light_fighter_count FROM planet_ships ps WHERE ps.planet_id = v_planet.id AND ps.ship_type_id = v_light_fighter_type_id;
        SELECT COALESCE(ps.quantity, 0) INTO v_small_cargo_count FROM planet_ships ps WHERE ps.planet_id = v_planet.id AND ps.ship_type_id = v_small_cargo_type_id;
        SELECT COALESCE(ps.quantity, 0) INTO v_large_cargo_count FROM planet_ships ps WHERE ps.planet_id = v_planet.id AND ps.ship_type_id = v_large_cargo_type_id;

        v_send_lf := GREATEST(3, FLOOR(v_light_fighter_count * 0.15)::int);
        v_send_sc := FLOOR(v_small_cargo_count * 0.20)::int;
        v_send_lc := FLOOR(v_large_cargo_count * 0.20)::int;

        IF v_send_lf < 3 THEN CONTINUE; END IF;

        v_fleet_result := secure_send_fleet(
          p_origin_planet_id := v_planet.id,
          p_target_galaxy := v_target.galaxy,
          p_target_system := v_target.solar_system,
          p_target_position := v_target.position,
          p_mission_type := 'attack',
          p_fleet_ships := (
            SELECT jsonb_agg(obj) FROM (
              SELECT jsonb_build_object('ship_type_id', v_light_fighter_type_id, 'quantity', v_send_lf) AS obj WHERE v_send_lf > 0
              UNION ALL SELECT jsonb_build_object('ship_type_id', v_small_cargo_type_id, 'quantity', v_send_sc) WHERE v_send_sc > 0
              UNION ALL SELECT jsonb_build_object('ship_type_id', v_large_cargo_type_id, 'quantity', v_send_lc) WHERE v_send_lc > 0
            ) sub
          ),
          p_cargo_metal := 5000,
          p_cargo_crystal := 2500,
          p_cargo_deuterium := 1000,
          p_speed_percent := 100,
          p_target_type := 'planet',
          p_override_user_id := v_bot.id
        );

        IF COALESCE((v_fleet_result->>'success')::boolean, false) THEN
          EXIT;
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;
END;
$$;


--
-- TOC entry 1108 (class 1255 OID 21754)
-- Name: bot_launch_ipm_attacks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_launch_ipm_attacks() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bot RECORD;
  v_planet RECORD;
  v_target RECORD;
  v_ipm_count integer;
  v_ipm_type_id integer;
  v_abm_type_id integer;
  v_silo_level integer;
  v_spy RECORD;
  v_defense_power integer;
  v_missiles_to_send integer;
  v_fleet_result jsonb;
BEGIN
  SELECT id INTO v_ipm_type_id FROM defense_types WHERE code = 'interplanetary_missile' LIMIT 1;
  IF v_ipm_type_id IS NULL THEN RETURN; END IF;

  FOR v_bot IN SELECT id FROM profiles WHERE (is_bot = true OR autopilot_active = true) AND is_banned = false LOOP
    FOR v_planet IN
      SELECT p.*, COALESCE(pd.quantity, 0) as ipm_qty,
             COALESCE(pb.level, 0) as silo_level
      FROM planets p
      LEFT JOIN planet_defenses pd ON pd.planet_id = p.id AND pd.defense_type_id = v_ipm_type_id
      LEFT JOIN planet_buildings pb ON pb.planet_id = p.id AND pb.building_type_id = (SELECT id FROM building_types WHERE code = 'missile_silo' LIMIT 1)
      WHERE p.user_id = v_bot.id
        AND p.planet_type = 'planet'
        AND COALESCE(pd.quantity, 0) >= 3
        AND COALESCE(pb.level, 0) >= 2
      LIMIT 5
    LOOP
      -- Find targets with heavy defenses (from spy reports <24h)
      FOR v_target IN
        SELECT DISTINCT
          CAST(regexp_replace(split_part(m.body, 'Coordenadas: [', 2), '].*', '') AS text) as coords,
          m.recipient_id
        FROM messages m
        WHERE m.recipient_id = v_bot.id
          AND m.message_type = 'espionage'
          AND m.created_at >= NOW() - interval '24 hours'
          AND (
            m.body LIKE '%Lanzamisiles%' OR m.body LIKE '%Laser Ligero%' 
            OR m.body LIKE '%Laser Pesado%' OR m.body LIKE '%Canon Ionico%'
            OR m.body LIKE '%Canon Gauss%' OR m.body LIKE '%Torreta de Plasma%'
          )
        LIMIT 5
      LOOP
        -- Parse coordinates and launch IPMs
        BEGIN
          DECLARE
            v_galaxy integer;
            v_system integer;
            v_position integer;
            v_coords_parts text[];
          BEGIN
            -- Basic coords parsing: [g:ss:pp]
            v_coords_parts := string_to_array(REPLACE(REPLACE(v_target.coords, '[', ''), ']', ''), ':');
            IF array_length(v_coords_parts, 1) >= 3 THEN
              v_galaxy := v_coords_parts[1]::integer;
              v_system := v_coords_parts[2]::integer;
              v_position := v_coords_parts[3]::integer;
              
              -- Send up to 5 IPMs
              v_missiles_to_send := LEAST(v_planet.ipm_qty, 5);
              IF v_missiles_to_send > 0 THEN
                v_fleet_result := secure_send_fleet(
                  p_origin_planet_id := v_planet.id,
                  p_target_galaxy := v_galaxy,
                  p_target_system := v_system,
                  p_target_position := v_position,
                  p_mission_type := 'attack',
                  p_fleet_ships := jsonb_build_array(jsonb_build_object('ship_type_id', v_ipm_type_id, 'quantity', v_missiles_to_send)),
                  p_cargo_metal := 0, p_cargo_crystal := 0, p_cargo_deuterium := 0,
                  p_speed_percent := 100,
                  p_target_type := 'planet',
                  p_override_user_id := v_bot.id
                );
              END IF;
            END IF;
          END;
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
      END LOOP;
    END LOOP;
  END LOOP;
END;
$$;


--
-- TOC entry 1111 (class 1255 OID 21758)
-- Name: bot_military_pro_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_military_pro_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- 30% chance each behavior per tick (avoids spam, hits ~every 3-4 ticks)
  IF random() < 0.30 THEN PERFORM bot_launch_ipm_attacks(); END IF;
  IF random() < 0.30 THEN PERFORM bot_farm_inactive_players(); END IF;
  IF random() < 0.30 THEN PERFORM bot_use_sensor_phalanx(); END IF;
END;
$$;


--
-- TOC entry 1049 (class 1255 OID 21261)
-- Name: bot_process_queues(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_process_queues(p_bot_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bq RECORD;
  v_sq RECORD;
  v_ut RECORD;
  v_completed_qty integer;
  v_lunar_base_id integer;
BEGIN
  SELECT id INTO v_lunar_base_id FROM building_types WHERE code = 'lunar_base' LIMIT 1;

  -- 1. Process completed BUILDING queues
  FOR v_bq IN
    SELECT bq.*, p.user_id
    FROM building_queue bq
    JOIN planets p ON p.id = bq.planet_id
    WHERE p.user_id = p_bot_id
      AND bq.end_time <= now()
    ORDER BY bq.end_time ASC
  LOOP
    INSERT INTO planet_buildings (planet_id, building_type_id, level)
    VALUES (v_bq.planet_id, v_bq.building_type_id, v_bq.target_level)
    ON CONFLICT (planet_id, building_type_id)
    DO UPDATE SET level = v_bq.target_level;

    UPDATE planets SET fields_used = (
      SELECT COALESCE(SUM(level), 0) FROM planet_buildings WHERE planet_id = v_bq.planet_id
    ) WHERE id = v_bq.planet_id;

    -- [FIX 2026-05-06] Lunar base on moon: grant +3 fields per level
    IF v_lunar_base_id IS NOT NULL AND v_bq.building_type_id = v_lunar_base_id THEN
      UPDATE planets
      SET fields_max = GREATEST(fields_max, 1 + v_bq.target_level * 3)
      WHERE id = v_bq.planet_id AND planet_type = 'moon';
    END IF;

    DELETE FROM building_queue WHERE id = v_bq.id;
  END LOOP;

  -- 2. Process completed SHIPYARD queues
  FOR v_sq IN
    SELECT sq.*, p.user_id
    FROM shipyard_queue sq
    JOIN planets p ON p.id = sq.planet_id
    WHERE p.user_id = p_bot_id
    ORDER BY sq.start_time ASC
  LOOP
    IF v_sq.build_time_per_unit > 0 THEN
      v_completed_qty := LEAST(
        v_sq.quantity,
        v_sq.quantity_completed + FLOOR(EXTRACT(EPOCH FROM (now() - v_sq.start_time)) / v_sq.build_time_per_unit)::integer
      );
    ELSE
      v_completed_qty := v_sq.quantity;
    END IF;

    IF v_completed_qty > v_sq.quantity_completed THEN
      IF v_sq.item_type = 'ship' AND v_sq.ship_type_id IS NOT NULL THEN
        INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
        VALUES (v_sq.planet_id, v_sq.ship_type_id, v_completed_qty - v_sq.quantity_completed)
        ON CONFLICT (planet_id, ship_type_id)
        DO UPDATE SET quantity = planet_ships.quantity + (v_completed_qty - v_sq.quantity_completed);
      ELSIF v_sq.item_type = 'defense' AND v_sq.defense_type_id IS NOT NULL THEN
        INSERT INTO planet_defenses (planet_id, defense_type_id, quantity)
        VALUES (v_sq.planet_id, v_sq.defense_type_id, v_completed_qty - v_sq.quantity_completed)
        ON CONFLICT (planet_id, defense_type_id)
        DO UPDATE SET quantity = planet_defenses.quantity + (v_completed_qty - v_sq.quantity_completed);
      END IF;

      IF v_completed_qty >= v_sq.quantity THEN
        DELETE FROM shipyard_queue WHERE id = v_sq.id;
      ELSE
        UPDATE shipyard_queue SET
          quantity_completed = v_completed_qty,
          current_unit_end_time = v_sq.start_time + ((v_completed_qty + 1) * v_sq.build_time_per_unit || ' seconds')::interval
        WHERE id = v_sq.id;
      END IF;
    END IF;
  END LOOP;

  -- 3. Process completed RESEARCH
  FOR v_ut IN
    SELECT * FROM user_technologies
    WHERE user_id = p_bot_id
      AND is_researching = true
      AND research_end_time <= now()
  LOOP
    UPDATE user_technologies
    SET level = level + 1,
        is_researching = false,
        research_end_time = NULL,
        research_planet_id = NULL
    WHERE id = v_ut.id;
  END LOOP;
END;
$$;


--
-- TOC entry 1110 (class 1255 OID 21757)
-- Name: bot_use_sensor_phalanx(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_use_sensor_phalanx() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bot RECORD;
  v_planet RECORD;
  v_phalanx_level integer;
  v_phalanx_range integer;
  v_scan_galaxy integer;
  v_scan_system integer;
  v_fleet_count integer;
BEGIN
  FOR v_bot IN SELECT id FROM profiles WHERE (is_bot = true OR autopilot_active = true) AND is_banned = false LOOP
    FOR v_planet IN
      SELECT p.*, COALESCE(pb.level, 0) as phalanx_level
      FROM planets p
      LEFT JOIN planet_buildings pb ON pb.planet_id = p.id AND pb.building_type_id = (SELECT id FROM building_types WHERE code = 'sensor_phalanx' LIMIT 1)
      WHERE p.user_id = v_bot.id
        AND p.planet_type = 'planet'
        AND COALESCE(pb.level, 0) >= 1
      LIMIT 2
    LOOP
      v_phalanx_range := LEAST(v_planet.phalanx_level, 10);
      
      FOR v_scan_system IN GREATEST(1, v_planet.solar_system - v_phalanx_range)..LEAST(499, v_planet.solar_system + v_phalanx_range)
      LOOP
        IF v_scan_system = v_planet.solar_system THEN CONTINUE; END IF;
        
        -- Just check if there are hostile fleets in this system
        SELECT COUNT(*) INTO v_fleet_count
        FROM fleets f
        WHERE f.target_galaxy = v_planet.galaxy
          AND f.target_system = v_scan_system
          AND f.user_id <> v_bot.id
          AND f.is_completed = false
          AND f.is_returning = false
          AND f.mission_type IN ('attack', 'transport', 'deploy', 'colonize', 'harvest')
          AND f.arrival_time > NOW()
          AND f.arrival_time < NOW() + interval '2 hours';

        -- Log the scan result (stored for future reference)
        IF v_fleet_count > 0 THEN
          -- Insert a system message so the bot "remembers" this intel
          INSERT INTO messages (sender_id, recipient_id, subject, body, message_type, is_read)
          VALUES (v_bot.id, v_bot.id, 'Phalanx Scan',
                  'Phalanx detected ' || v_fleet_count || ' hostile fleet(s) in Galaxy ' || v_planet.galaxy || ' System ' || v_scan_system || '. Time: ' || NOW()::text,
                  'espionage', true)
          ON CONFLICT DO NOTHING;
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;
END;
$$;


--
-- TOC entry 1083 (class 1255 OID 21490)
-- Name: buy_hero_item_listing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.buy_hero_item_listing(p_listing_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_listing record;
  v_total_price bigint;
  v_fee bigint;
  v_admin_fee bigint;
  v_pool_fee bigint;
  v_referral_fee bigint;
  v_seller_amount bigint;
  v_admin_id uuid;
  v_item record;
  -- Configurable share percentages (same as main market)
  v_admin_share numeric;
  v_pool_share numeric;
  v_referral_share numeric;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_listing
  FROM hero_item_market_listings
  WHERE id = p_listing_id AND status = 'active'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Listado no encontrado o ya no esta activo');
  END IF;

  IF v_listing.seller_id = v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes comprar tus propios items');
  END IF;

  SELECT * INTO v_item FROM hero_ship_items WHERE id = v_listing.item_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item no encontrado');
  END IF;

  -- Read configurable shares (same keys as main market, with defaults)
  SELECT COALESCE(value::numeric, 40) INTO v_admin_share FROM game_settings WHERE key = 'market_fee_admin_share';
  SELECT COALESCE(value::numeric, 30) INTO v_pool_share FROM game_settings WHERE key = 'market_fee_pool_share';
  SELECT COALESCE(value::numeric, 30) INTO v_referral_share FROM game_settings WHERE key = 'market_fee_referral_share';

  v_total_price := v_listing.price_fxu * v_listing.quantity;
  v_fee := FLOOR(v_total_price * 10 / 100);

  -- 4-3-3 split (referral always falls back to pool since hero market has no referral tracking)
  v_admin_fee := FLOOR(v_fee * v_admin_share / 100);
  v_pool_fee := FLOOR(v_fee * v_pool_share / 100);
  v_referral_fee := FLOOR(v_fee * v_referral_share / 100);
  v_pool_fee := v_pool_fee + v_referral_fee;  -- fallback to pool
  v_seller_amount := v_total_price - v_fee;

  -- Check buyer balance
  IF (SELECT fxu_balance FROM profiles WHERE id = v_user_id) < v_total_price THEN
    RETURN jsonb_build_object('success', false, 'error', 'FXU insuficiente');
  END IF;

  -- Bypass fxu_balance protection trigger
  PERFORM _internal_set_fxu_context();

  -- Deduct FXU from buyer
  UPDATE profiles SET fxu_balance = fxu_balance - v_total_price WHERE id = v_user_id;

  -- Credit seller (net of fee)
  UPDATE profiles SET fxu_balance = fxu_balance + v_seller_amount WHERE id = v_listing.seller_id;

  -- Admin fee: credit first admin profile
  v_admin_id := get_admin_account_id();
  IF v_admin_id IS NOT NULL AND v_admin_fee > 0 THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_admin_fee WHERE id = v_admin_id;
    PERFORM record_admin_revenue('p2p_fee', v_admin_fee, 
      'Hero item market fee (' || v_admin_share || '% admin, ' || v_pool_share || '% pool, ' || v_referral_share || '% referral→pool)',
      v_listing.seller_id, p_listing_id);
  END IF;

  -- Pool contribution (includes referral fallback)
  IF v_pool_fee > 0 THEN
    UPDATE hero_market_pool SET
      balance = balance + v_pool_fee,
      total_contributed = total_contributed + v_pool_fee,
      updated_at = now()
    WHERE id = 1;
  END IF;

  -- Mark listing as sold
  UPDATE hero_item_market_listings SET status = 'sold', sold_at = now() WHERE id = p_listing_id;

  -- Add item to buyer's inventory (stack if same item_id + item_level)
  INSERT INTO user_hero_ship_inventory (user_id, item_id, item_level, quantity)
  VALUES (v_user_id, v_listing.item_id, v_listing.item_level, v_listing.quantity)
  ON CONFLICT (user_id, item_id, item_level)
    DO UPDATE SET quantity = user_hero_ship_inventory.quantity + v_listing.quantity;

  RETURN jsonb_build_object('success', true, 'message', 'Item comprado exitosamente');
END;
$$;


--
-- TOC entry 995 (class 1255 OID 20829)
-- Name: buy_lottery_ticket(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.buy_lottery_ticket(p_numbers integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_draw record;
  v_ticket_cost integer;
  v_max_tickets integer;
  v_user_ticket_count integer;
  v_user_fxu numeric;
  v_is_plus boolean;
  v_final_cost integer;
  v_prize_pct integer;
  v_admin_pct integer;
  v_pool_pct integer;
  v_prize_amount numeric;
  v_admin_amount numeric;
  v_pool_amount numeric;
  v_admin_id uuid;
  v_ticket_id uuid;
  v_num integer;
  v_sorted integer[];
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  -- Validate numbers: exactly 4, all between 1-30, no duplicates
  IF array_length(p_numbers, 1) != 4 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Debes elegir exactamente 4 números');
  END IF;

  FOREACH v_num IN ARRAY p_numbers LOOP
    IF v_num < 1 OR v_num > 30 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Los números deben estar entre 1 y 30');
    END IF;
  END LOOP;

  -- Check duplicates within the 4 numbers
  SELECT ARRAY(SELECT DISTINCT unnest(p_numbers) ORDER BY 1) INTO v_sorted;
  IF array_length(v_sorted, 1) != 4 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes repetir números');
  END IF;
  p_numbers := v_sorted;

  -- Get active draw (FOR UPDATE serializes concurrent purchases)
  SELECT * INTO v_draw FROM lottery_draws
  WHERE status = 'open' AND closes_at > now()
  ORDER BY closes_at ASC LIMIT 1
  FOR UPDATE;

  IF v_draw.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No hay sorteo activo en este momento');
  END IF;

  -- Get config
  SELECT COALESCE(value::integer, 50) INTO v_ticket_cost FROM game_settings WHERE key = 'lottery_ticket_cost';
  SELECT COALESCE(value::integer, 10) INTO v_max_tickets FROM game_settings WHERE key = 'lottery_max_tickets';
  SELECT COALESCE(value::integer, 70) INTO v_prize_pct FROM game_settings WHERE key = 'lottery_prize_pool_pct';
  SELECT COALESCE(value::integer, 20) INTO v_admin_pct FROM game_settings WHERE key = 'lottery_admin_pct';
  SELECT COALESCE(value::integer, 10) INTO v_pool_pct FROM game_settings WHERE key = 'lottery_reward_pool_pct';
  IF v_ticket_cost IS NULL THEN v_ticket_cost := 50; END IF;
  IF v_max_tickets IS NULL THEN v_max_tickets := 10; END IF;
  IF v_prize_pct IS NULL THEN v_prize_pct := 70; END IF;
  IF v_admin_pct IS NULL THEN v_admin_pct := 20; END IF;
  IF v_pool_pct IS NULL THEN v_pool_pct := 10; END IF;

  -- Check ticket limit
  SELECT COUNT(*) INTO v_user_ticket_count
  FROM lottery_tickets WHERE draw_id = v_draw.id AND user_id = v_user_id;

  IF v_user_ticket_count >= v_max_tickets THEN
    RETURN jsonb_build_object('success', false, 'error', 'Has alcanzado el límite de ' || v_max_tickets || ' tickets para este sorteo');
  END IF;

  -- ========== NEW: Check duplicate combination for same user ==========
  IF EXISTS (
    SELECT 1 FROM lottery_tickets 
    WHERE draw_id = v_draw.id AND user_id = v_user_id AND numbers = p_numbers
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya tienes un ticket con estos números en este sorteo. Elige una combinación diferente.');
  END IF;

  -- VIP discount
  v_is_plus := is_user_plus(v_user_id);
  v_final_cost := v_ticket_cost;
  IF v_is_plus THEN
    v_final_cost := CEIL(v_ticket_cost * 0.50);
  END IF;

  -- Check balance
  SELECT COALESCE(fxu_balance, 0) INTO v_user_fxu FROM profiles WHERE id = v_user_id;
  IF v_user_fxu < v_final_cost THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'FXU insuficiente. Necesitas ' || v_final_cost || ' FXU, tienes ' || FLOOR(v_user_fxu) || ' FXU'
    );
  END IF;

  -- Charge user
  PERFORM _internal_set_fxu_context();
  UPDATE profiles SET fxu_balance = fxu_balance - v_final_cost WHERE id = v_user_id;

  -- Split revenue
  v_prize_amount := FLOOR(v_final_cost * v_prize_pct / 100.0);
  v_admin_amount := FLOOR(v_final_cost * v_admin_pct / 100.0);
  v_pool_amount := v_final_cost - v_prize_amount - v_admin_amount;

  -- Admin revenue
  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_id != v_user_id AND v_admin_amount > 0 THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_admin_amount WHERE id = v_admin_id;
  END IF;
  PERFORM record_admin_revenue('lottery_fee', v_admin_amount, 'Lottery ticket #' || (v_user_ticket_count + 1) || ' draw #' || v_draw.draw_number, v_user_id, v_draw.id);

  -- Reward pools
  IF v_pool_amount > 0 THEN
    PERFORM contribute_to_jackpot(v_pool_amount, 'lottery', v_user_id);
  END IF;

  -- Create ticket
  INSERT INTO lottery_tickets (draw_id, user_id, numbers, cost)
  VALUES (v_draw.id, v_user_id, p_numbers, v_final_cost)
  RETURNING id INTO v_ticket_id;

  -- Update draw totals
  UPDATE lottery_draws SET
    total_tickets = total_tickets + 1,
    total_pool = total_pool + v_final_cost,
    prize_pool = prize_pool + v_prize_amount,
    admin_revenue = admin_revenue + v_admin_amount,
    reward_pool_share = reward_pool_share + v_pool_amount
  WHERE id = v_draw.id;

  RETURN jsonb_build_object(
    'success', true,
    'ticket_id', v_ticket_id,
    'numbers', p_numbers,
    'cost', v_final_cost,
    'draw_number', v_draw.draw_number,
    'tickets_remaining', v_max_tickets - v_user_ticket_count - 1,
    'vip_discount', v_is_plus
  );
END;
$$;


--
-- TOC entry 843 (class 1255 OID 19950)
-- Name: calculate_and_sync_resources(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_and_sync_resources() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_planet_id uuid;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;
  
  SELECT id INTO v_planet_id
  FROM planets
  WHERE user_id = v_user_id
  ORDER BY is_homeworld DESC, created_at ASC
  LIMIT 1;
  
  IF v_planet_id IS NOT NULL THEN
    PERFORM calculate_and_sync_resources(v_planet_id);
  END IF;
END;
$$;


--
-- TOC entry 780 (class 1255 OID 19289)
-- Name: calculate_and_sync_resources(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_and_sync_resources(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_calculated jsonb;
  v_user_id uuid;
BEGIN
  -- Verify ownership
  SELECT user_id INTO v_user_id FROM planets WHERE id = p_planet_id;
  IF v_user_id IS NULL OR v_user_id != auth.uid() THEN
    RETURN jsonb_build_object('error', 'Unauthorized');
  END IF;
  
  -- FIX: Lock planet_resources row BEFORE reading to prevent race condition
  -- with fleet cargo deposits (process_fleet_arrival adds cargo with relative UPDATE)
  -- Without this lock, we could read stale values and overwrite fleet deposits
  PERFORM 1 FROM planet_resources WHERE planet_id = p_planet_id FOR UPDATE;
  
  -- Calculate current resources (now safe - row is locked)
  v_calculated := calculate_planet_resources(p_planet_id);
  
  IF v_calculated ? 'error' THEN
    RETURN v_calculated;
  END IF;
  
  -- Update the database with calculated values AND new last_update
  UPDATE planet_resources
  SET 
    metal = (v_calculated->>'metal')::numeric,
    crystal = (v_calculated->>'crystal')::numeric,
    deuterium = (v_calculated->>'deuterium')::numeric,
    metal_per_hour = (v_calculated->>'metal_per_hour')::numeric,
    crystal_per_hour = (v_calculated->>'crystal_per_hour')::numeric,
    deuterium_per_hour = (v_calculated->>'deuterium_per_hour')::numeric,
    metal_storage = (v_calculated->>'metal_storage')::numeric,
    crystal_storage = (v_calculated->>'crystal_storage')::numeric,
    deuterium_storage = (v_calculated->>'deuterium_storage')::numeric,
    energy_used = (v_calculated->>'energy_used')::numeric,
    energy_max = (v_calculated->>'energy_max')::numeric,
    last_update = now()
  WHERE planet_id = p_planet_id;
  
  -- Return with current timestamp
  RETURN jsonb_build_object(
    'metal', (v_calculated->>'metal')::numeric,
    'crystal', (v_calculated->>'crystal')::numeric,
    'deuterium', (v_calculated->>'deuterium')::numeric,
    'metal_per_hour', (v_calculated->>'metal_per_hour')::numeric,
    'crystal_per_hour', (v_calculated->>'crystal_per_hour')::numeric,
    'deuterium_per_hour', (v_calculated->>'deuterium_per_hour')::numeric,
    'metal_storage', (v_calculated->>'metal_storage')::numeric,
    'crystal_storage', (v_calculated->>'crystal_storage')::numeric,
    'deuterium_storage', (v_calculated->>'deuterium_storage')::numeric,
    'energy_used', (v_calculated->>'energy_used')::numeric,
    'energy_max', (v_calculated->>'energy_max')::numeric,
    'last_update', now()
  );
END;
$$;


--
-- TOC entry 781 (class 1255 OID 19290)
-- Name: calculate_and_sync_resources_internal(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_and_sync_resources_internal(p_planet_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet planets%ROWTYPE;
  v_calculated jsonb;
BEGIN
  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id AND user_id = p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Planet not found or not owned');
  END IF;

  -- FIX: Lock planet_resources row BEFORE reading to prevent race condition
  -- with fleet cargo deposits (process_fleet_arrival adds cargo with relative UPDATE)
  PERFORM 1 FROM planet_resources WHERE planet_id = p_planet_id FOR UPDATE;

  v_calculated := calculate_planet_resources(p_planet_id);

  IF v_calculated ? 'error' THEN
    RETURN v_calculated;
  END IF;

  UPDATE planet_resources
  SET 
    metal = (v_calculated->>'metal')::numeric,
    crystal = (v_calculated->>'crystal')::numeric,
    deuterium = (v_calculated->>'deuterium')::numeric,
    metal_per_hour = (v_calculated->>'metal_per_hour')::numeric,
    crystal_per_hour = (v_calculated->>'crystal_per_hour')::numeric,
    deuterium_per_hour = (v_calculated->>'deuterium_per_hour')::numeric,
    metal_storage = (v_calculated->>'metal_storage')::numeric,
    crystal_storage = (v_calculated->>'crystal_storage')::numeric,
    deuterium_storage = (v_calculated->>'deuterium_storage')::numeric,
    energy_used = (v_calculated->>'energy_used')::numeric,
    energy_max = (v_calculated->>'energy_max')::numeric,
    last_update = now()
  WHERE planet_id = p_planet_id;

  RETURN v_calculated;
END;
$$;


--
-- TOC entry 606 (class 1255 OID 18416)
-- Name: calculate_building_points(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_building_points(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_total_cost bigint := 0;
  v_record record;
BEGIN
  FOR v_record IN
    SELECT 
      bt.base_metal,
      bt.base_crystal,
      bt.base_deuterium,
      bt.cost_factor,
      pb.level
    FROM public.planet_buildings pb
    JOIN public.planets p ON pb.planet_id = p.id
    JOIN public.building_types bt ON pb.building_type_id = bt.id
    WHERE p.user_id = p_user_id AND pb.level > 0
  LOOP
    v_total_cost := v_total_cost + public.calculate_building_total_cost(
      v_record.base_metal,
      v_record.base_crystal,
      v_record.base_deuterium,
      v_record.cost_factor::numeric,
      v_record.level
    );
  END LOOP;
  
  RETURN floor(v_total_cost / 1000)::integer;
END;
$$;


--
-- TOC entry 605 (class 1255 OID 18415)
-- Name: calculate_building_total_cost(integer, integer, integer, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_building_total_cost(p_base_metal integer, p_base_crystal integer, p_base_deuterium integer, p_cost_factor numeric, p_level integer) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_total_metal bigint := 0;
  v_total_crystal bigint := 0;
  v_total_deuterium bigint := 0;
  i integer;
BEGIN
  IF p_level <= 0 THEN
    RETURN 0;
  END IF;
  
  FOR i IN 0..(p_level - 1) LOOP
    v_total_metal := v_total_metal + floor(p_base_metal * power(p_cost_factor, i));
    v_total_crystal := v_total_crystal + floor(p_base_crystal * power(p_cost_factor, i));
    v_total_deuterium := v_total_deuterium + floor(p_base_deuterium * power(p_cost_factor, i));
  END LOOP;
  
  RETURN v_total_metal + v_total_crystal + v_total_deuterium;
END;
$$;


--
-- TOC entry 1150 (class 1255 OID 22400)
-- Name: calculate_colony_stats(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_colony_stats(p_position integer) RETURNS TABLE(temp_min integer, temp_max integer, fields_min integer, fields_max integer, metal_deposit bigint, crystal_deposit bigint, deuterium_deposit bigint)
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_fields integer;
  v_base_metal_per_field numeric;
  v_deposits RECORD;
BEGIN
  SELECT COALESCE(value::numeric, 40000) INTO v_base_metal_per_field
  FROM game_settings WHERE key = 'depletion_base_metal_per_field';

  CASE
    WHEN p_position BETWEEN 1 AND 3 THEN
      temp_min := 100 + (4 - p_position) * 20 + floor(random() * 20)::integer;
      temp_max := temp_min + 30 + floor(random() * 20)::integer;
      fields_min := 95;
      fields_max := 140;
    WHEN p_position BETWEEN 4 AND 6 THEN
      temp_min := 30 + floor(random() * 30)::integer;
      temp_max := temp_min + 30 + floor(random() * 20)::integer;
      fields_min := 140;
      fields_max := 200;
    WHEN p_position BETWEEN 7 AND 9 THEN
      temp_min := -10 + floor(random() * 40)::integer;
      temp_max := temp_min + 30 + floor(random() * 20)::integer;
      fields_min := 180;
      fields_max := 250;
    WHEN p_position BETWEEN 10 AND 12 THEN
      temp_min := -50 + floor(random() * 30)::integer;
      temp_max := temp_min + 25 + floor(random() * 15)::integer;
      fields_min := 140;
      fields_max := 200;
    WHEN p_position BETWEEN 13 AND 15 THEN
      temp_min := -120 + (p_position - 12) * (-10) + floor(random() * 20)::integer;
      temp_max := temp_min + 20 + floor(random() * 10)::integer;
      fields_min := 95;
      fields_max := 150;
    ELSE
      temp_min := 0;
      temp_max := 50;
      fields_min := 100;
      fields_max := 180;
  END CASE;
  
  -- Random field count within range
  v_fields := fields_min + floor(random() * (fields_max - fields_min + 1))::integer;
  
  -- Calculate deposits
  SELECT * INTO v_deposits FROM calculate_initial_deposits(v_fields, p_position, v_base_metal_per_field);
  metal_deposit := v_deposits.metal_deposit;
  crystal_deposit := v_deposits.crystal_deposit;
  deuterium_deposit := v_deposits.deuterium_deposit;
  
  -- Set min/max to actual field count for consistency
  fields_min := v_fields;
  fields_max := v_fields;
  
  RETURN NEXT;
END;
$$;


--
-- TOC entry 609 (class 1255 OID 18419)
-- Name: calculate_defense_points(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_defense_points(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_total_cost bigint := 0;
BEGIN
  SELECT COALESCE(SUM(
    (dt.metal_cost + dt.crystal_cost + dt.deuterium_cost)::bigint * pd.quantity
  ), 0) INTO v_total_cost
  FROM public.planet_defenses pd
  JOIN public.planets p ON pd.planet_id = p.id
  JOIN public.defense_types dt ON pd.defense_type_id = dt.id
  WHERE p.user_id = p_user_id AND pd.quantity > 0;
  
  RETURN floor(v_total_cost / 1000)::integer;
END;
$$;


--
-- TOC entry 839 (class 1255 OID 19895)
-- Name: calculate_expired_plus_rewards(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_expired_plus_rewards() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_expired_sub RECORD;
  v_pool_balance numeric;
  v_active_count int;
  v_share_amount numeric;
  v_total_calculated numeric := 0;
  v_count int := 0;
  v_subscription_month date;
BEGIN
  -- Get current pool balance
  SELECT plus_balance INTO v_pool_balance FROM jackpot_pools WHERE id = 1;
  
  IF v_pool_balance <= 0 THEN
    RETURN jsonb_build_object('success', true, 'message', 'Pool vacio, nada que calcular', 'calculated', 0);
  END IF;

  -- Process each expired subscription that hasn't had rewards calculated
  FOR v_expired_sub IN 
    SELECT ps.id, ps.user_id, ps.expires_at, ps.started_at
    FROM plus_subscriptions ps
    WHERE ps.expires_at < now()
      AND ps.reward_calculated = false
    ORDER BY ps.expires_at ASC
  LOOP
    -- Determine which month this subscription covered
    v_subscription_month := date_trunc('month', v_expired_sub.expires_at - interval '1 day')::date;
    
    -- Check if we already calculated a reward for this user for this month
    IF EXISTS (
      SELECT 1 FROM plus_pending_rewards 
      WHERE user_id = v_expired_sub.user_id 
        AND subscription_month = v_subscription_month
    ) THEN
      -- Mark as calculated but don't create duplicate
      UPDATE plus_subscriptions SET reward_calculated = true WHERE id = v_expired_sub.id;
      CONTINUE;
    END IF;
    
    -- Re-fetch current pool balance (it might have changed)
    SELECT plus_balance INTO v_pool_balance FROM jackpot_pools WHERE id = 1;
    
    IF v_pool_balance <= 0 THEN
      EXIT; -- No more balance to distribute
    END IF;
    
    -- Count total active/pending subscribers for fair share calculation
    -- Include: active subs + expired subs without calculated rewards
    SELECT COUNT(DISTINCT user_id) INTO v_active_count
    FROM plus_subscriptions
    WHERE (is_active = true OR (expires_at < now() AND reward_calculated = false));
    
    IF v_active_count <= 0 THEN
      v_active_count := 1;
    END IF;
    
    -- Calculate equal share
    v_share_amount := FLOOR(v_pool_balance / v_active_count);
    
    IF v_share_amount > 0 THEN
      -- Reserve this amount from the pool
      UPDATE jackpot_pools 
      SET plus_balance = plus_balance - v_share_amount,
          updated_at = now()
      WHERE id = 1;
      
      -- Also update main jackpot
      UPDATE jackpot SET balance = balance - v_share_amount WHERE id = 1;
      
      -- Store pending reward
      INSERT INTO plus_pending_rewards (user_id, subscription_id, reward_amount, subscription_month)
      VALUES (v_expired_sub.user_id, v_expired_sub.id, v_share_amount, v_subscription_month);
      
      -- Update subscription
      UPDATE plus_subscriptions 
      SET reward_calculated = true, 
          pending_reward_amount = v_share_amount 
      WHERE id = v_expired_sub.id;
      
      v_total_calculated := v_total_calculated + v_share_amount;
      v_count := v_count + 1;
    ELSE
      -- Mark as calculated even if no reward (pool empty)
      UPDATE plus_subscriptions SET reward_calculated = true WHERE id = v_expired_sub.id;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'subscriptions_processed', v_count,
    'total_reserved', v_total_calculated
  );
END;
$$;


--
-- TOC entry 608 (class 1255 OID 18418)
-- Name: calculate_fleet_points(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_fleet_points(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet_ships_cost bigint := 0;
  v_fleet_ships_cost bigint := 0;
BEGIN
  -- Ships stationed on planets
  SELECT COALESCE(SUM(
    (st.metal_cost + st.crystal_cost + st.deuterium_cost)::bigint * ps.quantity
  ), 0) INTO v_planet_ships_cost
  FROM planet_ships ps
  JOIN planets p ON ps.planet_id = p.id
  JOIN ship_types st ON ps.ship_type_id = st.id
  WHERE p.user_id = p_user_id AND ps.quantity > 0;
  
  -- Ships currently in flight (not completed fleets)
  SELECT COALESCE(SUM(
    (st.metal_cost + st.crystal_cost + st.deuterium_cost)::bigint * fs.quantity
  ), 0) INTO v_fleet_ships_cost
  FROM fleet_ships fs
  JOIN fleets f ON fs.fleet_id = f.id
  JOIN ship_types st ON fs.ship_type_id = st.id
  WHERE f.user_id = p_user_id 
    AND f.is_completed = false
    AND fs.quantity > 0;
  
  RETURN floor((v_planet_ships_cost + v_fleet_ships_cost) / 1000)::integer;
END;
$$;


--
-- TOC entry 632 (class 1255 OID 18592)
-- Name: calculate_fxu_cost(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_fxu_cost(p_queue_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_queue building_queue%ROWTYPE;
  v_building_type building_types%ROWTYPE;
  v_seconds_remaining integer;
  v_metal_cost numeric;
  v_crystal_cost numeric;
  v_deuterium_cost numeric;
  v_total_resource_value numeric;
  v_fxu_ratio numeric;
  v_fxu_cost integer;
BEGIN
  SELECT * INTO v_queue FROM building_queue WHERE id = p_queue_id;
  
  IF v_queue IS NULL THEN
    RETURN 0;
  END IF;
  
  v_seconds_remaining := GREATEST(0, EXTRACT(EPOCH FROM (v_queue.end_time - now()))::integer);
  
  IF v_seconds_remaining <= 0 THEN
    RETURN 0;
  END IF;
  
  SELECT * INTO v_building_type FROM building_types WHERE id = v_queue.building_type_id;
  
  -- Calculate actual resource cost for the target level
  -- Formula: base_cost * (cost_factor ^ (level - 1))
  v_metal_cost := COALESCE(v_building_type.base_metal, 0) * 
    POWER(COALESCE(v_building_type.cost_factor, 1.5), v_queue.target_level - 1);
  v_crystal_cost := COALESCE(v_building_type.base_crystal, 0) * 
    POWER(COALESCE(v_building_type.cost_factor, 1.5), v_queue.target_level - 1);
  v_deuterium_cost := COALESCE(v_building_type.base_deuterium, 0) * 
    POWER(COALESCE(v_building_type.cost_factor, 1.5), v_queue.target_level - 1);
  
  -- Calculate total resource value (crystal worth 1.5x, deuterium worth 3x)
  v_total_resource_value := v_metal_cost + (v_crystal_cost * 1.5) + (v_deuterium_cost * 3);
  
  -- Get FXU ratio from settings
  SELECT COALESCE(value::numeric, 5000) INTO v_fxu_ratio 
  FROM game_settings WHERE key = 'fxu_cost_ratio_building';
  
  IF v_fxu_ratio IS NULL OR v_fxu_ratio <= 0 THEN
    v_fxu_ratio := 5000;
  END IF;
  
  -- Calculate FXU cost
  v_fxu_cost := CEIL(v_total_resource_value / v_fxu_ratio)::integer;
  
  -- Minimum 1 FXU
  RETURN GREATEST(1, v_fxu_cost);
END;
$$;


--
-- TOC entry 1134 (class 1255 OID 22242)
-- Name: calculate_fxu_cost_building(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_fxu_cost_building(p_queue_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_queue_item building_queue%ROWTYPE;
  v_seconds_remaining integer;
  v_resource_multiplier numeric;
  v_base_cost numeric;
BEGIN
  SELECT * INTO v_queue_item FROM building_queue WHERE id = p_queue_id;
  IF v_queue_item IS NULL THEN RETURN 0; END IF;
  IF v_queue_item.queue_position = 1 AND v_queue_item.start_time IS NOT NULL THEN
    v_seconds_remaining := GREATEST(0, EXTRACT(EPOCH FROM (v_queue_item.end_time - now()))::integer);
  ELSE
    v_seconds_remaining := v_queue_item.build_time;
  END IF;
  IF v_seconds_remaining <= 0 THEN RETURN 0; END IF;
  v_resource_multiplier := (COALESCE(v_queue_item.metal_cost, 0) + COALESCE(v_queue_item.crystal_cost, 0) + COALESCE(v_queue_item.deuterium_cost, 0))::numeric / 10000;
  v_base_cost := (v_seconds_remaining::numeric / 60) * (1 + v_resource_multiplier * 0.1);
  RETURN GREATEST(1, CEIL(v_base_cost));
END;
$$;


--
-- TOC entry 866 (class 1255 OID 20033)
-- Name: calculate_fxu_cost_fleet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_fxu_cost_fleet(p_fleet_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fleet fleets%ROWTYPE;
  v_seconds_remaining numeric;
  v_minutes_remaining numeric;
  v_ratio numeric;
  v_cost numeric;
  v_user_id uuid;
  v_min_cost integer;
BEGIN
  SELECT * INTO v_fleet FROM fleets WHERE id = p_fleet_id;

  IF v_fleet IS NULL OR v_fleet.is_completed THEN
    RETURN 0;
  END IF;

  IF v_fleet.is_returning THEN
    -- RETURNING: charge for remaining return time (normal behavior)
    v_seconds_remaining := EXTRACT(EPOCH FROM (v_fleet.return_time - now()));
  ELSE
    -- OUTBOUND: charge for FULL one-way flight duration (= return trip time)
    -- because accelerate_fleet() also auto-completes the return trip for free
    v_seconds_remaining := EXTRACT(EPOCH FROM (v_fleet.arrival_time - v_fleet.departure_time));
  END IF;

  IF v_seconds_remaining <= 0 THEN
    RETURN 0;
  END IF;

  v_minutes_remaining := v_seconds_remaining / 60.0;

  SELECT COALESCE(value::numeric, 1) INTO v_ratio
  FROM game_settings WHERE key = 'fxu_cost_ratio_fleet';

  IF v_ratio <= 0 THEN
    v_ratio := 1;
  END IF;

  v_cost := v_minutes_remaining * v_ratio;

  -- VIP discount: 25% off fleet acceleration cost (NOT speed)
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL AND is_user_plus(v_user_id) THEN
    v_cost := v_cost * 0.75;
  END IF;

  -- Get minimum cost from settings
  SELECT COALESCE(value::integer, 10) INTO v_min_cost
  FROM game_settings WHERE key = 'fleet_acceleration_min_cost';

  RETURN GREATEST(COALESCE(v_min_cost, 10), CEIL(v_cost))::integer;
END;
$$;


--
-- TOC entry 630 (class 1255 OID 18584)
-- Name: calculate_fxu_cost_research(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_fxu_cost_research(p_technology_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tech user_technologies%ROWTYPE;
  v_tech_type technology_types%ROWTYPE;
  v_seconds_remaining integer;
  v_total_research_time integer;
  v_time_ratio numeric;
  v_metal_cost bigint;
  v_crystal_cost bigint;
  v_deut_cost bigint;
  v_resource_value numeric;
  v_fxu_ratio numeric;
  v_fxu_cost numeric;
  v_user_id uuid;
BEGIN
  SELECT * INTO v_tech FROM user_technologies WHERE id = p_technology_id;

  IF v_tech IS NULL OR NOT v_tech.is_researching THEN
    RETURN 0;
  END IF;

  IF v_tech.research_end_time IS NULL THEN
    RETURN 1;
  END IF;

  v_seconds_remaining := GREATEST(0, EXTRACT(EPOCH FROM (v_tech.research_end_time - now()))::integer);

  IF v_seconds_remaining <= 0 THEN
    RETURN 1;
  END IF;

  IF v_tech.research_start_time IS NOT NULL THEN
    v_total_research_time := GREATEST(1, EXTRACT(EPOCH FROM (v_tech.research_end_time - v_tech.research_start_time))::integer);
  ELSE
    v_total_research_time := v_seconds_remaining;
  END IF;

  v_time_ratio := LEAST(1, GREATEST(0.01, v_seconds_remaining::numeric / v_total_research_time::numeric));

  SELECT * INTO v_tech_type FROM technology_types WHERE id = v_tech.technology_type_id;

  IF v_tech_type IS NULL THEN
    RETURN 1;
  END IF;

  v_metal_cost := FLOOR(COALESCE(v_tech_type.base_metal, 0) * POWER(COALESCE(v_tech_type.cost_factor, 2), v_tech.level));
  v_crystal_cost := FLOOR(COALESCE(v_tech_type.base_crystal, 0) * POWER(COALESCE(v_tech_type.cost_factor, 2), v_tech.level));
  v_deut_cost := FLOOR(COALESCE(v_tech_type.base_deuterium, 0) * POWER(COALESCE(v_tech_type.cost_factor, 2), v_tech.level));

  v_resource_value := calculate_resource_value(v_metal_cost, v_crystal_cost, v_deut_cost);

  IF v_resource_value <= 0 THEN
    RETURN 1;
  END IF;

  SELECT COALESCE(value::numeric, 3000) INTO v_fxu_ratio
  FROM game_settings WHERE key = 'fxu_cost_ratio_research';

  IF v_fxu_ratio IS NULL OR v_fxu_ratio <= 0 THEN
    v_fxu_ratio := 3000;
  END IF;

  v_fxu_cost := v_resource_value / v_fxu_ratio;
  v_fxu_cost := v_fxu_cost * v_time_ratio;

  -- VIP discount: 50% off research acceleration (changed from 75%)
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL AND is_user_plus(v_user_id) THEN
    v_fxu_cost := v_fxu_cost * 0.50;
  END IF;

  RETURN GREATEST(1, CEIL(v_fxu_cost))::integer;
END;
$$;


--
-- TOC entry 631 (class 1255 OID 18585)
-- Name: calculate_fxu_cost_shipyard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_fxu_cost_shipyard(p_queue_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_queue shipyard_queue%ROWTYPE;
  v_ship_type ship_types%ROWTYPE;
  v_defense_type defense_types%ROWTYPE;
  v_current_unit_time_remaining integer;
  v_total_time_remaining integer;
  v_total_time_for_remaining_units integer;
  v_time_ratio numeric;
  v_metal_cost bigint;
  v_crystal_cost bigint;
  v_deut_cost bigint;
  v_units_remaining integer;
  v_resource_value numeric;
  v_fxu_ratio numeric;
  v_fxu_cost numeric;
  v_user_id uuid;
BEGIN
  SELECT * INTO v_queue FROM shipyard_queue WHERE id = p_queue_id;
  
  IF v_queue IS NULL THEN
    RETURN 0;
  END IF;
  
  v_current_unit_time_remaining := GREATEST(0, EXTRACT(EPOCH FROM (v_queue.current_unit_end_time - now()))::integer);
  v_units_remaining := v_queue.quantity - v_queue.quantity_completed;
  
  IF v_units_remaining <= 0 THEN
    RETURN 0;
  END IF;
  
  v_total_time_remaining := v_current_unit_time_remaining;
  IF v_units_remaining > 1 THEN
    v_total_time_remaining := v_total_time_remaining + ((v_units_remaining - 1) * v_queue.build_time_per_unit);
  END IF;
  
  IF v_total_time_remaining <= 0 THEN
    RETURN 0;
  END IF;
  
  v_total_time_for_remaining_units := v_units_remaining * v_queue.build_time_per_unit;
  v_time_ratio := v_total_time_remaining::numeric / GREATEST(1, v_total_time_for_remaining_units)::numeric;
  
  IF v_queue.item_type = 'ship' THEN
    SELECT * INTO v_ship_type FROM ship_types WHERE id = v_queue.ship_type_id;
    v_metal_cost := COALESCE(v_ship_type.metal_cost, 0);
    v_crystal_cost := COALESCE(v_ship_type.crystal_cost, 0);
    v_deut_cost := COALESCE(v_ship_type.deuterium_cost, 0);
    
    SELECT COALESCE(value::numeric, 8000) INTO v_fxu_ratio
    FROM game_settings WHERE key = 'fxu_cost_ratio_ships';
    
    IF v_fxu_ratio IS NULL OR v_fxu_ratio <= 0 THEN
      v_fxu_ratio := 8000;
    END IF;
  ELSE
    SELECT * INTO v_defense_type FROM defense_types WHERE id = v_queue.defense_type_id;
    v_metal_cost := COALESCE(v_defense_type.metal_cost, 0);
    v_crystal_cost := COALESCE(v_defense_type.crystal_cost, 0);
    v_deut_cost := COALESCE(v_defense_type.deuterium_cost, 0);
    
    SELECT COALESCE(value::numeric, 10000) INTO v_fxu_ratio
    FROM game_settings WHERE key = 'fxu_cost_ratio_defense';
    
    IF v_fxu_ratio IS NULL OR v_fxu_ratio <= 0 THEN
      v_fxu_ratio := 10000;
    END IF;
  END IF;
  
  v_resource_value := calculate_resource_value(v_metal_cost, v_crystal_cost, v_deut_cost) * v_units_remaining;
  
  v_fxu_cost := v_resource_value / v_fxu_ratio;
  v_fxu_cost := v_fxu_cost * v_time_ratio;
  
  -- VIP discount: 25% off ship/defense acceleration
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL AND is_user_plus(v_user_id) THEN
    v_fxu_cost := v_fxu_cost * 0.75;
  END IF;
  
  RETURN GREATEST(1, CEIL(v_fxu_cost))::integer;
END;
$$;


--
-- TOC entry 1005 (class 1255 OID 20860)
-- Name: calculate_fxu_weekly_limit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_fxu_weekly_limit(p_user_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fxu_credit numeric;
BEGIN
  -- Only investment recovery credit, points are separate
  v_fxu_credit := calculate_running_fxu_credit(p_user_id);

  -- Threshold: less than 1 FXU credit is effectively zero
  -- This prevents users from getting stuck with tiny residual credit
  -- that blocks sales while being too small to sell anything
  IF v_fxu_credit < 1 THEN
    RETURN 0;
  END IF;

  RETURN v_fxu_credit;
END;
$$;


--
-- TOC entry 1149 (class 1255 OID 22398)
-- Name: calculate_initial_deposits(integer, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_initial_deposits(p_fields integer, p_position integer, p_base_metal_per_field numeric DEFAULT 30000) RETURNS TABLE(metal_deposit bigint, crystal_deposit bigint, deuterium_deposit bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_factors RECORD;
  v_random numeric;
BEGIN
  SELECT * INTO v_factors FROM get_deposit_position_factors(p_position);
  
  -- Random factor 0.85-1.15 for variety
  v_random := 0.85 + random() * 0.3;
  
  -- Each resource calculated INDEPENDENTLY from fields, not as fractions of each other
  metal_deposit := GREATEST(200000, FLOOR(p_fields * p_base_metal_per_field * v_random * v_factors.metal_factor))::bigint;
  
  -- Crystal uses its own formula: fields * base * 0.6 * random * crystal_factor
  crystal_deposit := GREATEST(200000, FLOOR(p_fields * p_base_metal_per_field * 0.6 * v_random * v_factors.crystal_factor))::bigint;
  
  -- Deuterium uses its own formula: fields * base * 0.4 * random * deuterium_factor
  deuterium_deposit := GREATEST(100000, FLOOR(p_fields * p_base_metal_per_field * 0.4 * v_random * v_factors.deuterium_factor))::bigint;
  
  RETURN NEXT;
END;
$$;


--
-- TOC entry 592 (class 1255 OID 18313)
-- Name: calculate_irn_lab_level(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_irn_lab_level(p_user_id uuid, p_current_planet_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
v_irn_level integer;
v_current_lab_level integer;
v_other_labs integer[];
v_bonus_levels integer := 0;
v_lab_level integer;
v_count integer := 0;
BEGIN
SELECT COALESCE(ut.level, 0) INTO v_irn_level
FROM public.user_technologies ut
JOIN public.technology_types tt ON ut.technology_type_id = tt.id
WHERE ut.user_id = p_user_id AND tt.code = 'intergalactic_research_network';

SELECT COALESCE(pb.level, 0) INTO v_current_lab_level
FROM public.planet_buildings pb
JOIN public.building_types bt ON pb.building_type_id = bt.id
WHERE pb.planet_id = p_current_planet_id AND bt.code = 'research_lab';

IF v_irn_level = 0 THEN
RETURN v_current_lab_level;
END IF;

SELECT ARRAY_AGG(pb.level ORDER BY pb.level DESC) INTO v_other_labs
FROM public.planet_buildings pb
JOIN public.building_types bt ON pb.building_type_id = bt.id
JOIN public.planets p ON pb.planet_id = p.id
WHERE p.user_id = p_user_id
AND pb.planet_id != p_current_planet_id
AND bt.code = 'research_lab'
AND pb.level > 0;

IF v_other_labs IS NULL OR array_length(v_other_labs, 1) IS NULL THEN
RETURN v_current_lab_level;
END IF;

FOREACH v_lab_level IN ARRAY v_other_labs LOOP
IF v_count < v_irn_level THEN
v_bonus_levels := v_bonus_levels + v_lab_level;
v_count := v_count + 1;
END IF;
END LOOP;

RETURN v_current_lab_level + v_bonus_levels;
END;
$$;


--
-- TOC entry 911 (class 1255 OID 20291)
-- Name: calculate_loot(numeric, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_loot(p_planet_metal numeric, p_planet_crystal numeric, p_planet_deuterium numeric, p_total_cargo integer) RETURNS TABLE(looted_metal numeric, looted_crystal numeric, looted_deuterium numeric)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_available_metal NUMERIC;
  v_available_crystal NUMERIC;
  v_available_deuterium NUMERIC;
  v_loot_metal NUMERIC := 0;
  v_loot_crystal NUMERIC := 0;
  v_loot_deuterium NUMERIC := 0;
  v_cargo NUMERIC := p_total_cargo;
  v_third NUMERIC;
  v_remaining NUMERIC;
  v_still_available NUMERIC;
  v_count INTEGER;
BEGIN
  v_available_metal := GREATEST(0, FLOOR(p_planet_metal * 0.5));
  v_available_crystal := GREATEST(0, FLOOR(p_planet_crystal * 0.5));
  v_available_deuterium := GREATEST(0, FLOOR(p_planet_deuterium * 0.5));

  IF v_cargo <= 0 THEN
    RETURN QUERY SELECT 0::NUMERIC, 0::NUMERIC, 0::NUMERIC;
    RETURN;
  END IF;

  v_third := FLOOR(v_cargo / 3.0);

  v_loot_metal := LEAST(v_available_metal, v_third);
  v_loot_crystal := LEAST(v_available_crystal, v_third);
  v_loot_deuterium := LEAST(v_available_deuterium, v_third);

  v_remaining := v_cargo - v_loot_metal - v_loot_crystal - v_loot_deuterium;

  IF v_remaining > 0 THEN
    v_count := 0;
    IF (v_available_metal - v_loot_metal) > 0 THEN v_count := v_count + 1; END IF;
    IF (v_available_crystal - v_loot_crystal) > 0 THEN v_count := v_count + 1; END IF;
    IF (v_available_deuterium - v_loot_deuterium) > 0 THEN v_count := v_count + 1; END IF;

    IF v_count > 0 THEN
      v_third := FLOOR(v_remaining / v_count::NUMERIC);

      IF (v_available_metal - v_loot_metal) > 0 THEN
        v_still_available := LEAST(v_available_metal - v_loot_metal, v_third);
        v_loot_metal := v_loot_metal + v_still_available;
        v_remaining := v_remaining - v_still_available;
      END IF;

      IF (v_available_crystal - v_loot_crystal) > 0 THEN
        v_still_available := LEAST(v_available_crystal - v_loot_crystal, v_third);
        v_loot_crystal := v_loot_crystal + v_still_available;
        v_remaining := v_remaining - v_still_available;
      END IF;

      IF (v_available_deuterium - v_loot_deuterium) > 0 THEN
        v_still_available := LEAST(v_available_deuterium - v_loot_deuterium, v_third);
        v_loot_deuterium := v_loot_deuterium + v_still_available;
        v_remaining := v_remaining - v_still_available;
      END IF;
    END IF;
  END IF;

  IF v_remaining > 0 THEN
    IF (v_available_metal - v_loot_metal) > 0 THEN
      v_still_available := LEAST(v_available_metal - v_loot_metal, v_remaining);
      v_loot_metal := v_loot_metal + v_still_available;
      v_remaining := v_remaining - v_still_available;
    END IF;

    IF v_remaining > 0 AND (v_available_crystal - v_loot_crystal) > 0 THEN
      v_still_available := LEAST(v_available_crystal - v_loot_crystal, v_remaining);
      v_loot_crystal := v_loot_crystal + v_still_available;
      v_remaining := v_remaining - v_still_available;
    END IF;

    IF v_remaining > 0 AND (v_available_deuterium - v_loot_deuterium) > 0 THEN
      v_still_available := LEAST(v_available_deuterium - v_loot_deuterium, v_remaining);
      v_loot_deuterium := v_loot_deuterium + v_still_available;
      v_remaining := v_remaining - v_still_available;
    END IF;
  END IF;

  RETURN QUERY SELECT v_loot_metal, v_loot_crystal, v_loot_deuterium;
END;
$$;


--
-- TOC entry 739 (class 1255 OID 19062)
-- Name: calculate_missile_range(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_missile_range(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_impulse_level integer;
  v_max_range integer;
BEGIN
  SELECT COALESCE(ut.level, 0) INTO v_impulse_level
  FROM user_technologies ut
  JOIN technology_types tt ON ut.technology_type_id = tt.id
  WHERE ut.user_id = p_user_id AND tt.code = 'impulse_drive';

  v_impulse_level := COALESCE(v_impulse_level, 0);
  v_max_range := GREATEST(0, (v_impulse_level * 5) - 1);

  RETURN jsonb_build_object(
    'impulse_level', v_impulse_level,
    'range_systems', v_max_range
  );
END;
$$;


--
-- TOC entry 921 (class 1255 OID 20345)
-- Name: calculate_monthly_market_limit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_monthly_market_limit(p_user_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_points integer;
  v_fxu_spent numeric;
  v_fxu_earned numeric;
  v_fxu_credit numeric;
  v_monthly_limit bigint;
BEGIN
  SELECT COALESCE(points_total, 0) INTO v_user_points FROM profiles WHERE id = p_user_id;

  v_fxu_spent := get_user_lifetime_fxu_spent(p_user_id);
  v_fxu_earned := get_user_market_earnings(p_user_id);

  v_fxu_credit := GREATEST(0, v_fxu_spent - v_fxu_earned);

  v_monthly_limit := v_user_points + FLOOR(v_fxu_credit);

  RETURN v_monthly_limit;
END;
$$;


--
-- TOC entry 594 (class 1255 OID 18315)
-- Name: calculate_planet_max_fields(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_planet_max_fields(p_planet_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_planet record;
  v_terraformer_level integer;
  v_base_fields integer;
  v_position_bonus integer;
BEGIN
  SELECT * INTO v_planet FROM public.planets WHERE id = p_planet_id;

  IF v_planet IS NULL THEN
    RETURN 40;
  END IF;

  IF v_planet.planet_type = 'moon' THEN
    RETURN v_planet.fields_max;
  END IF;

  SELECT COALESCE(pb.level, 0) INTO v_terraformer_level
  FROM public.planet_buildings pb
  JOIN public.building_types bt ON pb.building_type_id = bt.id
  WHERE pb.planet_id = p_planet_id AND bt.code = 'terraformer';

  IF v_terraformer_level IS NULL THEN
    v_terraformer_level := 0;
  END IF;

  v_base_fields := FLOOR(POWER(v_planet.diameter / 1000.0, 2))::integer;

  v_position_bonus := CASE v_planet.position
    WHEN 1 THEN -30
    WHEN 2 THEN -20
    WHEN 3 THEN -10
    WHEN 10 THEN 5
    WHEN 11 THEN 10
    WHEN 12 THEN 15
    WHEN 13 THEN 20
    WHEN 14 THEN 15
    WHEN 15 THEN 10
    ELSE 0
  END;

  -- Use exponential formula via terraformer_field_bonus helper
  RETURN GREATEST(40, v_base_fields + v_position_bonus + public.terraformer_field_bonus(v_terraformer_level));
END;
$$;


--
-- TOC entry 673 (class 1255 OID 18780)
-- Name: calculate_planet_resources(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_planet_resources(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet RECORD;
  v_resources RECORD;
  v_user_id uuid;
  v_officer_bonuses jsonb;
  v_resource_speed integer;
  
  v_metal_mine_level int := 0;
  v_crystal_mine_level int := 0;
  v_deuterium_synth_level int := 0;
  v_solar_plant_level int := 0;
  v_fusion_reactor_level int := 0;
  v_metal_storage_level int := 0;
  v_crystal_storage_level int := 0;
  v_deuterium_tank_level int := 0;
  
  v_energy_tech_level int := 0;
  v_solar_satellites int := 0;
  
  v_metal_energy_consumption numeric;
  v_crystal_energy_consumption numeric;
  v_deuterium_energy_consumption numeric;
  v_total_energy_consumption numeric;
  v_solar_plant_energy numeric;
  v_fusion_reactor_energy numeric;
  v_solar_satellite_energy numeric;
  v_total_energy_production numeric;
  v_energy_factor numeric;
  
  v_base_metal_production numeric;
  v_base_crystal_production numeric;
  v_base_deuterium_production numeric;
  v_fusion_consumption numeric;
  v_metal_production numeric;
  v_crystal_production numeric;
  v_deuterium_production numeric;
  
  v_metal_storage numeric;
  v_crystal_storage numeric;
  v_deuterium_storage numeric;
  
  v_elapsed_hours numeric;
  v_now timestamp with time zone := now();
  
  v_new_metal numeric;
  v_new_crystal numeric;
  v_new_deuterium numeric;
  
  v_mine_bonus numeric := 0;
  v_energy_bonus numeric := 0;
  v_active_prod_bonus numeric := 0;

  v_is_main boolean;
  v_depletion_enabled boolean := true;
  v_metal_available numeric;
  v_crystal_available numeric;
  v_deuterium_available numeric;
  v_metal_would_produce numeric;
  v_crystal_would_produce numeric;
  v_deuterium_would_produce numeric;
  v_all_depleted boolean := false;
BEGIN
  v_resource_speed := COALESCE(get_resource_speed(), 10);

  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Planet not found'); END IF;
  
  v_user_id := v_planet.user_id;
  v_is_main := v_planet.is_main_planet;

  SELECT * INTO v_resources FROM planet_resources WHERE planet_id = p_planet_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Resources not found'); END IF;

  IF v_resources.last_update IS NOT NULL THEN
    v_elapsed_hours := EXTRACT(EPOCH FROM (v_now - v_resources.last_update)) / 3600.0;
  ELSE v_elapsed_hours := 0; END IF;
  IF v_elapsed_hours > 48 THEN v_elapsed_hours := 48; END IF;

  IF v_user_id IS NOT NULL THEN
    v_officer_bonuses := get_user_officer_bonuses(v_user_id);
    v_mine_bonus := COALESCE((v_officer_bonuses->>'mineProduction')::numeric, 0);
    v_energy_bonus := COALESCE((v_officer_bonuses->>'energyProduction')::numeric, 0);
    -- Daily streak: +5% production bonus if active
    IF EXISTS (SELECT 1 FROM user_daily_streaks WHERE user_id = v_user_id AND expires_at > v_now) THEN
      v_mine_bonus := v_mine_bonus + 0.05;
    END IF;
    -- Active bonuses (missions/boxes): sum all production_bonus values
    SELECT COALESCE(SUM(bonus_value), 0) * 0.01 INTO v_active_prod_bonus
    FROM user_active_bonuses
    WHERE user_id = v_user_id AND bonus_type = 'production_bonus' AND expires_at > v_now;
    v_mine_bonus := v_mine_bonus + COALESCE(v_active_prod_bonus, 0);
  END IF;

  SELECT COALESCE(MAX(pb.level), 0) INTO v_metal_mine_level FROM planet_buildings pb JOIN building_types bt ON bt.id = pb.building_type_id WHERE pb.planet_id = p_planet_id AND bt.code = 'metal_mine';
  SELECT COALESCE(MAX(pb.level), 0) INTO v_crystal_mine_level FROM planet_buildings pb JOIN building_types bt ON bt.id = pb.building_type_id WHERE pb.planet_id = p_planet_id AND bt.code = 'crystal_mine';
  SELECT COALESCE(MAX(pb.level), 0) INTO v_deuterium_synth_level FROM planet_buildings pb JOIN building_types bt ON bt.id = pb.building_type_id WHERE pb.planet_id = p_planet_id AND bt.code = 'deuterium_synthesizer';
  SELECT COALESCE(MAX(pb.level), 0) INTO v_solar_plant_level FROM planet_buildings pb JOIN building_types bt ON bt.id = pb.building_type_id WHERE pb.planet_id = p_planet_id AND bt.code = 'solar_plant';
  SELECT COALESCE(MAX(pb.level), 0) INTO v_fusion_reactor_level FROM planet_buildings pb JOIN building_types bt ON bt.id = pb.building_type_id WHERE pb.planet_id = p_planet_id AND bt.code = 'fusion_reactor';
  SELECT COALESCE(MAX(pb.level), 0) INTO v_metal_storage_level FROM planet_buildings pb JOIN building_types bt ON bt.id = pb.building_type_id WHERE pb.planet_id = p_planet_id AND bt.code = 'metal_storage';
  SELECT COALESCE(MAX(pb.level), 0) INTO v_crystal_storage_level FROM planet_buildings pb JOIN building_types bt ON bt.id = pb.building_type_id WHERE pb.planet_id = p_planet_id AND bt.code = 'crystal_storage';
  SELECT COALESCE(MAX(pb.level), 0) INTO v_deuterium_tank_level FROM planet_buildings pb JOIN building_types bt ON bt.id = pb.building_type_id WHERE pb.planet_id = p_planet_id AND bt.code = 'deuterium_tank';

  SELECT COALESCE(SUM(ps.quantity), 0) INTO v_solar_satellites FROM planet_ships ps JOIN ship_types st ON st.id = ps.ship_type_id WHERE ps.planet_id = p_planet_id AND st.code = 'solar_satellite';

  IF v_user_id IS NOT NULL THEN
    SELECT COALESCE(MAX(ut.level), 0) INTO v_energy_tech_level FROM user_technologies ut JOIN technology_types tt ON tt.id = ut.technology_type_id WHERE ut.user_id = v_user_id AND tt.code = 'energy_technology';
  END IF;

  v_base_metal_production := 30 * v_metal_mine_level * POWER(1.1, v_metal_mine_level);
  v_base_crystal_production := 20 * v_crystal_mine_level * POWER(1.1, v_crystal_mine_level);
  v_base_deuterium_production := 10 * v_deuterium_synth_level * POWER(1.1, v_deuterium_synth_level) * (1.36 - 0.004 * COALESCE(v_planet.temp_max, 40));

  v_metal_energy_consumption := 10 * v_metal_mine_level * POWER(1.1, v_metal_mine_level);
  v_crystal_energy_consumption := 10 * v_crystal_mine_level * POWER(1.1, v_crystal_mine_level);
  v_deuterium_energy_consumption := 10 * v_deuterium_synth_level * POWER(1.1, v_deuterium_synth_level);
  v_total_energy_consumption := v_metal_energy_consumption + v_crystal_energy_consumption + v_deuterium_energy_consumption;

  v_solar_plant_energy := 20 * v_solar_plant_level * POWER(1.1, v_solar_plant_level);
  v_fusion_reactor_energy := 30 * v_fusion_reactor_level * POWER(1.1, v_fusion_reactor_level);
  v_solar_satellite_energy := 20 * v_solar_satellites * (1 + v_energy_tech_level * 0.05);
  v_total_energy_production := v_solar_plant_energy + v_fusion_reactor_energy + v_solar_satellite_energy;
  IF v_energy_bonus > 0 THEN v_total_energy_production := v_total_energy_production * (1 + v_energy_bonus); END IF;

  IF v_total_energy_consumption > 0 THEN v_energy_factor := LEAST(1.0, v_total_energy_production / v_total_energy_consumption); ELSE v_energy_factor := 1.0; END IF;

  v_metal_production := v_base_metal_production * v_energy_factor;
  v_crystal_production := v_base_crystal_production * v_energy_factor;
  v_deuterium_production := v_base_deuterium_production * v_energy_factor;

  IF v_mine_bonus > 0 THEN
    v_metal_production := v_metal_production * (1 + v_mine_bonus);
    v_crystal_production := v_crystal_production * (1 + v_mine_bonus);
    v_deuterium_production := v_deuterium_production * (1 + v_mine_bonus);
  END IF;

  v_metal_production := v_metal_production * v_resource_speed;
  v_crystal_production := v_crystal_production * v_resource_speed;
  v_deuterium_production := v_deuterium_production * v_resource_speed;

  BEGIN
    v_depletion_enabled := COALESCE((SELECT value::boolean FROM game_settings WHERE key = 'depletion_enabled'), true);
  EXCEPTION WHEN OTHERS THEN v_depletion_enabled := true; END;

  IF NOT v_is_main AND v_depletion_enabled THEN
    v_metal_available := COALESCE(v_planet.metal_deposit, 0);
    v_crystal_available := COALESCE(v_planet.crystal_deposit, 0);
    v_deuterium_available := COALESCE(v_planet.deuterium_deposit, 0);
    v_metal_would_produce := v_metal_production * v_elapsed_hours;
    v_crystal_would_produce := v_crystal_production * v_elapsed_hours;
    v_deuterium_would_produce := v_deuterium_production * v_elapsed_hours;
    
    IF v_metal_available <= 0 THEN v_metal_production := 0; v_metal_would_produce := 0;
    ELSIF v_metal_would_produce > v_metal_available THEN v_metal_would_produce := v_metal_available; v_metal_production := v_metal_available / GREATEST(v_elapsed_hours, 0.0001); END IF;
    IF v_crystal_available <= 0 THEN v_crystal_production := 0; v_crystal_would_produce := 0;
    ELSIF v_crystal_would_produce > v_crystal_available THEN v_crystal_would_produce := v_crystal_available; v_crystal_production := v_crystal_available / GREATEST(v_elapsed_hours, 0.0001); END IF;
    IF v_deuterium_available <= 0 THEN v_deuterium_production := 0; v_deuterium_would_produce := 0;
    ELSIF v_deuterium_would_produce > v_deuterium_available THEN v_deuterium_would_produce := v_deuterium_available; v_deuterium_production := v_deuterium_available / GREATEST(v_elapsed_hours, 0.0001); END IF;
    
    v_metal_available := v_metal_available - v_metal_would_produce;
    v_crystal_available := v_crystal_available - v_crystal_would_produce;
    v_deuterium_available := v_deuterium_available - v_deuterium_would_produce;
    IF v_metal_available < 0 THEN v_metal_available := 0; END IF;
    IF v_crystal_available < 0 THEN v_crystal_available := 0; END IF;
    IF v_deuterium_available < 0 THEN v_deuterium_available := 0; END IF;
    
    UPDATE planets SET metal_deposit = CASE WHEN metal_deposit IS NULL THEN NULL ELSE v_metal_available::bigint END, crystal_deposit = CASE WHEN crystal_deposit IS NULL THEN NULL ELSE v_crystal_available::bigint END, deuterium_deposit = CASE WHEN deuterium_deposit IS NULL THEN NULL ELSE v_deuterium_available::bigint END WHERE id = p_planet_id;
    
    IF v_metal_available <= 0 AND v_crystal_available <= 0 AND v_deuterium_available <= 0 THEN
      IF v_planet.planet_status != 'depleted' THEN UPDATE planets SET planet_status = 'depleted', depleted_at = now() WHERE id = p_planet_id; END IF;
    END IF;
  END IF;

  v_new_metal := v_resources.metal + (v_metal_production * v_elapsed_hours);
  v_new_crystal := v_resources.crystal + (v_crystal_production * v_elapsed_hours);
  v_new_deuterium := v_resources.deuterium + (v_deuterium_production * v_elapsed_hours);

  v_metal_storage := 10000 * POWER(2, v_metal_storage_level);
  v_crystal_storage := 10000 * POWER(2, v_crystal_storage_level);
  v_deuterium_storage := 10000 * POWER(2, v_deuterium_tank_level);
  -- [SOFT CAP] Solo limitar producción si estamos POR DEBAJO del almacén.
  -- Si ya estamos por encima (transporte externo), no recortar.
  IF v_resources.metal <= v_metal_storage THEN
    v_new_metal := LEAST(v_new_metal, v_metal_storage);
  END IF;
  IF v_resources.crystal <= v_crystal_storage THEN
    v_new_crystal := LEAST(v_new_crystal, v_crystal_storage);
  END IF;
  IF v_resources.deuterium <= v_deuterium_storage THEN
    v_new_deuterium := LEAST(v_new_deuterium, v_deuterium_storage);
  END IF;

  UPDATE planet_resources SET metal = v_new_metal, crystal = v_new_crystal, deuterium = v_new_deuterium, metal_per_hour = v_metal_production, crystal_per_hour = v_crystal_production, deuterium_per_hour = v_deuterium_production, metal_storage = v_metal_storage, crystal_storage = v_crystal_storage, deuterium_storage = v_deuterium_storage, energy_used = v_total_energy_consumption, energy_max = v_total_energy_production, last_update = v_now WHERE planet_id = p_planet_id;

  RETURN jsonb_build_object('metal', v_new_metal, 'crystal', v_new_crystal, 'deuterium', v_new_deuterium, 'metal_per_hour', v_metal_production, 'crystal_per_hour', v_crystal_production, 'deuterium_per_hour', v_deuterium_production, 'metal_storage', v_metal_storage, 'crystal_storage', v_crystal_storage, 'deuterium_storage', v_deuterium_storage, 'energy_used', v_total_energy_consumption, 'energy_max', v_total_energy_production, 'last_update', v_now);
END;
$$;


--
-- TOC entry 607 (class 1255 OID 18417)
-- Name: calculate_research_points(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_research_points(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_total_cost bigint := 0;
  v_record record;
BEGIN
  FOR v_record IN
    SELECT 
      tt.base_metal,
      tt.base_crystal,
      tt.base_deuterium,
      tt.cost_factor,
      ut.level
    FROM public.user_technologies ut
    JOIN public.technology_types tt ON ut.technology_type_id = tt.id
    WHERE ut.user_id = p_user_id AND ut.level > 0
  LOOP
    v_total_cost := v_total_cost + public.calculate_building_total_cost(
      v_record.base_metal,
      v_record.base_crystal,
      v_record.base_deuterium,
      v_record.cost_factor::numeric,
      v_record.level
    );
  END LOOP;
  
  RETURN floor(v_total_cost / 1000)::integer;
END;
$$;


--
-- TOC entry 1146 (class 1255 OID 22361)
-- Name: calculate_resource_value(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_resource_value(p_metal bigint, p_crystal bigint, p_deuterium bigint) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Standard resource value: metal=1, crystal=1.5, deuterium=3
  RETURN COALESCE(p_metal, 0)::numeric * 1.0 
       + COALESCE(p_crystal, 0)::numeric * 1.5 
       + COALESCE(p_deuterium, 0)::numeric * 3.0;
END;
$$;


--
-- TOC entry 1004 (class 1255 OID 20853)
-- Name: calculate_running_fxu_credit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_running_fxu_credit(p_user_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cutoff timestamptz;
  v_credit numeric := 0;
  v_row RECORD;
  v_credit_multiplier numeric := 1.3; -- 130% credit on company spending
BEGIN
  SELECT earnings_cutoff_date INTO v_cutoff
  FROM market_resource_limits WHERE id = 1;

  FOR v_row IN (
    -- Company spending events (add to credit) — ALL history, NO cutoff
    SELECT created_at, amount as delta, 'SPEND' as event_type
    FROM admin_revenue
    WHERE related_user_id = p_user_id
      AND revenue_type IN (
        'plus_subscription', 'officer_fxu',
        'instant_ship', 'instant_build', 'instant_research', 'supply_box'
      )

    UNION ALL

    -- Market sale events (subtract from credit) — only from cutoff
    SELECT mt.created_at, mt.total_price as delta, 'SALE' as event_type
    FROM market_transactions mt
    JOIN market_listings ml ON ml.id = mt.listing_id
    WHERE mt.seller_id = p_user_id
      AND ml.listing_type IN ('resource', 'ship')
      AND (v_cutoff IS NULL OR mt.created_at >= v_cutoff)

    ORDER BY created_at ASC
  ) LOOP
    IF v_row.event_type = 'SPEND' THEN
      -- Apply 130% credit multiplier on spending
      v_credit := v_credit + (v_row.delta * v_credit_multiplier);
    ELSE
      v_credit := v_credit - v_row.delta;
      IF v_credit < 0 THEN
        v_credit := 0;
      END IF;
    END IF;
  END LOOP;

  RETURN v_credit;
END;
$$;


--
-- TOC entry 639 (class 1255 OID 18647)
-- Name: can_alliance_accept_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_alliance_accept_member(p_alliance_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_member_count int;
  v_max_members int := 3;
BEGIN
  SELECT COUNT(*) INTO v_member_count
  FROM alliance_members
  WHERE alliance_id = p_alliance_id;
  
  RETURN v_member_count < v_max_members;
END;
$$;


--
-- TOC entry 666 (class 1255 OID 18765)
-- Name: can_attack_player(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_attack_player(p_target_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target_profile record;
BEGIN
  SELECT vacation_mode, is_banned, username
  INTO v_target_profile
  FROM profiles
  WHERE id = p_target_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('can_attack', false, 'reason', 'Player not found');
  END IF;

  IF v_target_profile.is_banned THEN
    RETURN jsonb_build_object('can_attack', false, 'reason', 'Player is banned');
  END IF;

  IF v_target_profile.vacation_mode THEN
    RETURN jsonb_build_object(
      'can_attack', false, 
      'reason', format('Player %s is in vacation mode', v_target_profile.username)
    );
  END IF;

  RETURN jsonb_build_object('can_attack', true);
END;
$$;


--
-- TOC entry 7766 (class 0 OID 0)
-- Dependencies: 666
-- Name: FUNCTION can_attack_player(p_target_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_attack_player(p_target_user_id uuid) IS 'Checks if a player can be attacked. Returns false if target is in vacation mode or banned.';


--
-- TOC entry 1125 (class 1255 OID 21910)
-- Name: cancel_blueprint_market_listing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_blueprint_market_listing(p_listing_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_listing market_listings%ROWTYPE;
  v_escrow blueprint_market_escrow%ROWTYPE;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_listing
  FROM market_listings
  WHERE id = p_listing_id
    AND seller_id = v_user_id
    AND listing_type = 'blueprint'
    AND status = 'active'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Listing no encontrado');
  END IF;

  SELECT * INTO v_escrow
  FROM blueprint_market_escrow
  WHERE listing_id = p_listing_id
    AND delivered_at IS NULL
    AND returned_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Escrow no disponible');
  END IF;

  UPDATE market_listings
  SET status = 'cancelled', updated_at = now()
  WHERE id = p_listing_id;

  INSERT INTO user_ship_blueprints (user_id, blueprint_id, source, metadata)
  VALUES (
    v_escrow.seller_id,
    v_escrow.blueprint_id,
    'admin',
    jsonb_build_object('reason', 'listing_cancelled', 'listing_id', p_listing_id)
  );

  UPDATE blueprint_market_escrow
  SET returned_at = now()
  WHERE listing_id = p_listing_id;

  RETURN jsonb_build_object('success', true, 'message', 'Listing cancelado y plano devuelto');
END;
$$;


--
-- TOC entry 910 (class 1255 OID 20274)
-- Name: cancel_buy_offer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_buy_offer(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_offer RECORD;
  v_refund numeric;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_offer
  FROM market_buy_offers
  WHERE id = p_offer_id AND buyer_id = v_user_id AND status = 'active'
  FOR UPDATE;

  IF v_offer IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oferta no encontrada o no puedes cancelarla');
  END IF;

  v_refund := (v_offer.quantity - v_offer.quantity_filled) * v_offer.price_per_unit;

  IF v_refund > 0 THEN
    PERFORM _internal_set_fxu_context();
    UPDATE profiles SET fxu_balance = fxu_balance + v_refund WHERE id = v_user_id;
  END IF;

  UPDATE market_buy_offers
  SET status = 'cancelled', updated_at = now()
  WHERE id = p_offer_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Oferta cancelada. Se devolvieron ' || v_refund || ' FXU.',
    'refund', v_refund
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Error al cancelar: ' || SQLERRM);
END;
$$;


--
-- TOC entry 854 (class 1255 OID 20014)
-- Name: cancel_diplomacy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_diplomacy(p_diplomacy_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_alliance_id uuid;
  v_can_edit boolean;
  v_diplomacy record;
  v_other_alliance_id uuid;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  -- Get user's alliance and permissions
  SELECT alliance_id, can_edit INTO v_user_alliance_id, v_can_edit
  FROM alliance_members
  WHERE user_id = v_user_id;
  
  IF NOT COALESCE(v_can_edit, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes permiso para gestionar diplomacia');
  END IF;
  
  -- Get diplomacy record
  SELECT * INTO v_diplomacy
  FROM alliance_diplomacy
  WHERE id = p_diplomacy_id AND status = 'active';
  
  IF v_diplomacy IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Relacion no encontrada o no activa');
  END IF;
  
  -- Check user is part of this diplomacy
  IF v_diplomacy.alliance_id != v_user_alliance_id AND v_diplomacy.target_alliance_id != v_user_alliance_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes acceso a esta relacion');
  END IF;
  
  -- Determine other alliance
  v_other_alliance_id := CASE 
    WHEN v_diplomacy.alliance_id = v_user_alliance_id THEN v_diplomacy.target_alliance_id
    ELSE v_diplomacy.alliance_id
  END;

  -- Delete old cancelled/rejected rows for same pair and type to avoid any constraint issues
  DELETE FROM alliance_diplomacy
  WHERE alliance_id = v_diplomacy.alliance_id
    AND target_alliance_id = v_diplomacy.target_alliance_id
    AND diplomacy_type = v_diplomacy.diplomacy_type
    AND status IN ('cancelled', 'rejected')
    AND id != p_diplomacy_id;
  
  -- Cancel diplomacy
  UPDATE alliance_diplomacy
  SET status = 'cancelled'
  WHERE id = p_diplomacy_id;
  
  -- Notify other alliance
  INSERT INTO messages (recipient_id, subject, body, message_type)
  SELECT 
    a.leader_id,
    CASE v_diplomacy.diplomacy_type
      WHEN 'nap' THEN '⚠️ Pacto de No Agresion Cancelado'
      WHEN 'trade' THEN '⚠️ Pacto Comercial Cancelado'
      WHEN 'war' THEN '🕊️ Guerra Cancelada'
    END,
    format(
      'La alianza %s ha cancelado %s.',
      (SELECT name FROM alliances WHERE id = v_user_alliance_id),
      CASE v_diplomacy.diplomacy_type
        WHEN 'nap' THEN 'el Pacto de No Agresion'
        WHEN 'trade' THEN 'el Pacto Comercial'
        WHEN 'war' THEN 'la Guerra'
      END
    ),
    'alliance'
  FROM alliances a
  WHERE a.id = v_other_alliance_id;
  
  RETURN jsonb_build_object(
    'success', true, 
    'message', 'Relacion diplomatica cancelada'
  );
END;
$$;


--
-- TOC entry 805 (class 1255 OID 19512)
-- Name: cancel_fleet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_fleet(p_fleet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
    v_fleet RECORD;
    v_user_id uuid;
    v_elapsed_seconds numeric;
    v_return_seconds numeric;
  BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
    END IF;

    SELECT * INTO v_fleet FROM fleets WHERE id = p_fleet_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'Flota no encontrada');
    END IF;

    IF v_fleet.user_id != v_user_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'No puedes cancelar esta flota');
    END IF;

    IF v_fleet.is_completed = true THEN
      RETURN jsonb_build_object('success', false, 'error', 'La flota ya ha llegado a su destino');
    END IF;

    IF v_fleet.is_returning = true THEN
      RETURN jsonb_build_object('success', false, 'error', 'La flota ya esta regresando');
    END IF;

    -- Calculate return time = time already elapsed (same time to go back)
    v_elapsed_seconds := EXTRACT(EPOCH FROM (now() - v_fleet.departure_time));
    v_return_seconds := v_elapsed_seconds;

    -- Set fleet as returning with proper return time
    UPDATE fleets 
    SET is_returning = true,
        return_time = now() + (v_return_seconds || ' seconds')::interval
    WHERE id = p_fleet_id;

    RETURN jsonb_build_object(
      'success', true,
      'message', 'Flota regresando. Llegara en ' || ROUND(v_return_seconds / 60) || ' minutos.',
      'return_time', now() + (v_return_seconds || ' seconds')::interval
    );
  END;
  $$;


--
-- TOC entry 1090 (class 1255 OID 21550)
-- Name: cancel_hero_duel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_hero_duel(p_duel_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_duel record;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_duel FROM hero_duels WHERE id = p_duel_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Duelo no encontrado');
  END IF;

  IF v_duel.creator_id != v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo el creador puede cancelar el duelo');
  END IF;

  IF v_duel.status != 'waiting' THEN
    RETURN jsonb_build_object('success', false, 'error', 'El duelo ya no se puede cancelar');
  END IF;

  PERFORM _internal_set_fxu_context();
  UPDATE profiles SET fxu_balance = fxu_balance + v_duel.stake WHERE id = v_user_id;

  UPDATE hero_duels SET status = 'cancelled', updated_at = now() WHERE id = p_duel_id;

  RETURN jsonb_build_object('success', true, 'message', 'Duelo cancelado');
END;
$$;


--
-- TOC entry 617 (class 1255 OID 18506)
-- Name: cancel_market_listing(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_market_listing(p_listing_id uuid, p_return_planet_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_listing record;
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_listing
  FROM market_listings
  WHERE id = p_listing_id
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oferta no encontrada');
  END IF;
  
  IF v_listing.seller_id != v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No eres el dueno de esta oferta');
  END IF;
  
  IF v_listing.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Esta oferta ya no se puede cancelar');
  END IF;
  
  UPDATE market_listings
  SET status = 'cancelled', updated_at = now()
  WHERE id = p_listing_id;
  
  IF v_listing.listing_type = 'dark_matter' THEN
    UPDATE profiles
    SET dark_matter = COALESCE(dark_matter, 0) + v_listing.quantity
    WHERE id = v_user_id;
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Oferta cancelada exitosamente'
  );
  
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Error al cancelar oferta: ' || SQLERRM);
END;
$$;


--
-- TOC entry 680 (class 1255 OID 18861)
-- Name: cancel_withdrawal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_withdrawal(p_tx_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tx wallet_transactions%ROWTYPE;
  v_caller_id uuid;
  v_is_admin boolean;
  v_fee_amount numeric;
  v_admin_id uuid;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_caller_id;
  IF v_is_admin IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Admin access required');
  END IF;

  SELECT * INTO v_tx FROM wallet_transactions WHERE id = p_tx_id;

  IF v_tx.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction not found');
  END IF;

  IF v_tx.tx_type != 'withdrawal' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction is not a withdrawal');
  END IF;

  IF v_tx.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only cancel pending withdrawals. Current status: ' || v_tx.status);
  END IF;

  v_fee_amount := v_tx.fxu_amount - v_tx.amount;

  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);

  UPDATE profiles 
  SET fxu_balance = fxu_balance + v_tx.fxu_amount,
      updated_at = now()
  WHERE id = v_tx.user_id;

  IF v_fee_amount > 0 THEN
    SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
    IF v_admin_id IS NOT NULL THEN
      UPDATE profiles 
      SET fxu_balance = GREATEST(fxu_balance - v_fee_amount, 0),
          updated_at = now()
      WHERE id = v_admin_id;
    END IF;
  END IF;

  UPDATE wallet_transactions
  SET status = 'cancelled',
      error_message = 'Cancelled by admin',
      updated_at = now()
  WHERE id = p_tx_id;

  RETURN jsonb_build_object(
    'success', true,
    'refunded_amount', v_tx.fxu_amount,
    'user_id', v_tx.user_id
  );
END;
$$;


