COMMENT ON FUNCTION public.cancel_withdrawal(p_tx_id uuid) IS 'SECURITY: Requires is_admin check';


--
-- TOC entry 786 (class 1255 OID 19307)
-- Name: cancel_withdrawal_usdt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_withdrawal_usdt(p_tx_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tx wallet_transactions%ROWTYPE;
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_tx FROM wallet_transactions WHERE id = p_tx_id AND user_id = v_user_id;
  
  IF v_tx.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction not found');
  END IF;

  IF v_tx.tx_type != 'withdrawal' OR v_tx.token_type != 'USDT' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only cancel USDT withdrawals');
  END IF;

  IF v_tx.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only cancel pending withdrawals');
  END IF;

  -- Refund USDT to user
  UPDATE profiles 
  SET usdt_balance = usdt_balance + v_tx.fxu_amount,
      updated_at = now()
  WHERE id = v_user_id;

  -- Mark as cancelled
  UPDATE wallet_transactions
  SET status = 'cancelled',
      updated_at = now()
  WHERE id = p_tx_id;

  RETURN jsonb_build_object('success', true, 'refunded', v_tx.fxu_amount);
END;
$$;


--
-- TOC entry 809 (class 1255 OID 19516)
-- Name: charge_expedition_fee(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.charge_expedition_fee(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_active_expeditions integer;
  v_astrophysics_level integer;
  v_max_expeditions integer;
BEGIN
  SELECT COALESCE(ut.level, 0) INTO v_astrophysics_level
  FROM user_technologies ut
  JOIN technology_types tt ON ut.technology_type_id = tt.id
  WHERE ut.user_id = p_user_id AND tt.code = 'astrophysics';

  v_astrophysics_level := COALESCE(v_astrophysics_level, 0);

  IF v_astrophysics_level < 1 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Necesitas investigar Astrofisica para enviar expediciones'
    );
  END IF;

  v_max_expeditions := GREATEST(1, FLOOR(SQRT(v_astrophysics_level::numeric)));

  v_active_expeditions := get_active_expedition_count(p_user_id);

  IF v_active_expeditions >= v_max_expeditions THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('Has alcanzado el maximo de expediciones simultaneas (%s). Investiga Astrofisica para desbloquear mas.', v_max_expeditions),
      'required_fee', 0,
      'current_balance', 0
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'charged', false,
    'fee', 0,
    'expedition_number', v_active_expeditions + 1,
    'message', 'Expedicion gratuita'
  );
END;
$$;


