--
-- TOC entry 596 (class 1255 OID 18395)
-- Name: check_bashing_limit(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_bashing_limit(p_attacker_id uuid, p_defender_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_attack_count integer;
  v_bashing_enabled boolean;
  v_max_attacks integer := 5;
BEGIN
  SELECT (value = 'true') INTO v_bashing_enabled
  FROM game_settings WHERE key = 'bashing_protection';

  IF NOT COALESCE(v_bashing_enabled, false) THEN
    RETURN jsonb_build_object('allowed', true);
  END IF;

  -- Count attacks AND destroy missions in the last 24 hours
  -- Also count active (in-flight) attack/destroy fleets not yet completed
  SELECT COUNT(*) INTO v_attack_count
  FROM (
    -- Completed attacks from attack_log
    SELECT attack_time AS ts
    FROM attack_log
    WHERE attacker_id = p_attacker_id
      AND defender_id = p_defender_id
      AND attack_time > NOW() - INTERVAL '24 hours'
    UNION ALL
    -- In-flight attack/destroy fleets not yet landed
    SELECT departure_time AS ts
    FROM fleets
    WHERE user_id = p_attacker_id
      AND mission_type IN ('attack', 'destroy')
      AND is_completed = false
      AND is_returning = false
      AND departure_time > NOW() - INTERVAL '24 hours'
      AND EXISTS (
        SELECT 1 FROM planets
        WHERE galaxy = fleets.target_galaxy
          AND solar_system = fleets.target_system
          AND position = fleets.target_position
          AND user_id = p_defender_id
          AND NOT is_destroyed
      )
  ) combined;

  IF v_attack_count >= v_max_attacks THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', format('Has alcanzado el limite de %s ataques en 24 horas a este jugador (%s/%s)', v_max_attacks, v_attack_count, v_max_attacks),
      'count', v_attack_count,
      'max', v_max_attacks
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'count', v_attack_count,
    'max', v_max_attacks
  );
END;
$$;


--
-- TOC entry 851 (class 1255 OID 19972)
-- Name: check_bashing_rule(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_bashing_rule(p_attacker_id uuid, p_defender_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN check_bashing_limit(p_attacker_id, p_defender_id);
END;
$$;


--
-- TOC entry 588 (class 1255 OID 18287)
-- Name: check_building_queue_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_building_queue_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
current_queue_count INTEGER;
max_slots INTEGER;
has_commander BOOLEAN;
BEGIN
SELECT COUNT(*) INTO current_queue_count
FROM public.building_queue
WHERE planet_id = NEW.planet_id;

SELECT EXISTS(
SELECT 1 FROM public.user_officers uo
JOIN public.officer_types ot ON uo.officer_type_id = ot.id
WHERE uo.user_id = (SELECT user_id FROM public.planets WHERE id = NEW.planet_id)
AND ot.code = 'commander'
AND uo.expires_at > NOW()
) INTO has_commander;

IF has_commander THEN
max_slots := 5;
ELSE
max_slots := 3;
END IF;

IF current_queue_count >= max_slots THEN
RAISE EXCEPTION 'Building queue is full (max % slots)', max_slots;
END IF;

RETURN NEW;
END;
$$;


--
-- TOC entry 705 (class 1255 OID 18931)
-- Name: check_email_verified_by_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_email_verified_by_email(p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_verified boolean;
  v_smtp_enabled boolean := false;
BEGIN
  SELECT id INTO v_user_id
  FROM auth.users
  WHERE LOWER(email) = LOWER(p_email);

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('exists', false, 'verified', false);
  END IF;

  SELECT COALESCE(is_enabled, false)
  INTO v_smtp_enabled
  FROM admin_smtp_settings
  WHERE id = 1;

  IF NOT COALESCE(v_smtp_enabled, false) THEN
    RETURN jsonb_build_object(
      'exists', true,
      'verified', true,
      'user_id', v_user_id,
      'smtp_enabled', false
    );
  END IF;

  SELECT email_verified
  INTO v_verified
  FROM profiles
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'exists', true,
    'verified', COALESCE(v_verified, false),
    'user_id', v_user_id,
    'smtp_enabled', true
  );
END;
$$;


--
-- TOC entry 664 (class 1255 OID 18763)
-- Name: check_incoming_hostile_fleets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_incoming_hostile_fleets(p_user_id uuid) RETURNS TABLE(fleet_id uuid, mission_type text, arrival_time timestamp with time zone, attacker_username text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Buscar flotas hostiles que van hacia planetas del usuario
  -- y que aun no han llegado (no estan completadas ni retornando)
  RETURN QUERY
  SELECT 
    f.id as fleet_id,
    f.mission_type::text,
    f.arrival_time,
    COALESCE(p2.username, 'Unknown') as attacker_username
  FROM fleets f
  JOIN planets p ON 
    p.galaxy = f.target_galaxy 
    AND p.solar_system = f.target_system 
    AND p.position = f.target_position
    AND p.user_id = p_user_id
  LEFT JOIN profiles p2 ON p2.id = f.user_id
  WHERE f.mission_type IN ('attack', 'destroy', 'espionage')
    AND f.is_completed = false
    AND f.is_returning = false
    AND f.arrival_time > now()
    AND f.user_id != p_user_id;  -- No contar flotas propias
END;
$$;


