Used to prevent enabling vacation mode while under attack.';


--
-- TOC entry 774 (class 1255 OID 19277)
-- Name: check_login_for_multiaccount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_login_for_multiaccount() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_other_user_id uuid;
  v_other_username text;
BEGIN
  FOR v_other_user_id, v_other_username IN
    SELECT DISTINCT ls.user_id, p.username
    FROM login_sessions ls
    JOIN profiles p ON p.id = ls.user_id
    WHERE ls.ip_address = NEW.ip_address
      AND ls.user_id != NEW.user_id
      AND ls.created_at > now() - interval '30 days'
    LIMIT 5
  LOOP
    INSERT INTO suspicious_accounts (
      user_id, 
      linked_user_id, 
      suspicion_type, 
      evidence,
      severity
    )
    VALUES (
      NEW.user_id,
      v_other_user_id,
      'shared_ip',
      jsonb_build_object(
        'ip_address', NEW.ip_address,
        'detected_at', now(),
        'other_username', v_other_username
      ),
      'medium'
    )
    ON CONFLICT (user_id, linked_user_id, suspicion_type) 
    DO UPDATE SET 
      evidence = suspicious_accounts.evidence || jsonb_build_object('last_seen', now()),
      updated_at = now();
  END LOOP;
  
  IF NEW.fingerprint IS NOT NULL AND NEW.fingerprint != '' THEN
    FOR v_other_user_id, v_other_username IN
      SELECT DISTINCT ls.user_id, p.username
      FROM login_sessions ls
      JOIN profiles p ON p.id = ls.user_id
      WHERE ls.fingerprint = NEW.fingerprint
        AND ls.user_id != NEW.user_id
        AND ls.created_at > now() - interval '30 days'
      LIMIT 5
    LOOP
      INSERT INTO suspicious_accounts (
        user_id, 
        linked_user_id, 
        suspicion_type, 
        evidence,
        severity
      )
      VALUES (
        NEW.user_id,
        v_other_user_id,
        'shared_fingerprint',
        jsonb_build_object(
          'fingerprint', NEW.fingerprint,
          'detected_at', now(),
          'other_username', v_other_username
        ),
        'high'
      )
      ON CONFLICT (user_id, linked_user_id, suspicion_type) 
      DO UPDATE SET 
        evidence = suspicious_accounts.evidence || jsonb_build_object('last_seen', now()),
        updated_at = now(),
        severity = 'high';
    END LOOP;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- TOC entry 620 (class 1255 OID 18552)
-- Name: check_moon_creation(integer, integer, integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_moon_creation(p_galaxy integer, p_system integer, p_position integer, p_debris_metal numeric, p_debris_crystal numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_debris numeric;
  v_moon_chance numeric;
  v_existing_moon record;
  v_planet record;
  v_moon_created boolean := false;
  v_moon_diameter integer;
  v_new_moon_id uuid;
BEGIN
  -- Verificar si ya existe una luna en esa posicion
  SELECT * INTO v_existing_moon
  FROM planets
  WHERE galaxy = p_galaxy
    AND solar_system = p_system
    AND position = p_position
    AND planet_type = 'moon';
  
  IF FOUND THEN
    RETURN jsonb_build_object('moon_created', false, 'reason', 'Ya existe una luna');
  END IF;
  
  -- Obtener planeta principal para el propietario
  SELECT * INTO v_planet
  FROM planets
  WHERE galaxy = p_galaxy
    AND solar_system = p_system
    AND position = p_position
    AND planet_type = 'planet'
    AND user_id IS NOT NULL;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('moon_created', false, 'reason', 'No hay planeta');
  END IF;
  
  -- Calcular probabilidad de luna
  -- Cada 100.000 unidades de escombros = 1% de probabilidad (max 20%)
  v_total_debris := p_debris_metal + p_debris_crystal;
  v_moon_chance := LEAST(20, v_total_debris / 100000);
  
  -- Tirar dados para creacion de luna
  IF random() * 100 < v_moon_chance THEN
    v_moon_created := true;
    
    -- Calcular diametro de la luna (basado en escombros, entre 3474 y 8944 km)
    v_moon_diameter := LEAST(8944, GREATEST(3474, 3474 + floor(v_total_debris / 50000) * 100));
    
    -- Crear la luna
    INSERT INTO planets (
      user_id,
      name,
      galaxy,
      solar_system,
      position,
      planet_type,
      diameter,
      temp_min,
      temp_max,
      fields_max,
      is_main_planet
    ) VALUES (
      v_planet.user_id,
      'Luna',
      p_galaxy,
      p_system,
      p_position,
      'moon',
      v_moon_diameter,
      -40,
      -20,
      1,
      false
    )
    RETURNING id INTO v_new_moon_id;
    
    -- Crear recursos iniciales para la luna
    INSERT INTO planet_resources (planet_id, metal, crystal, deuterium)
    VALUES (v_new_moon_id, 0, 0, 0);
    
    -- Notificar al propietario
    INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
    VALUES (
      NULL,
      v_planet.user_id,
      'Una Luna ha aparecido!',
      format('Los escombros de la batalla en [%s:%s:%s] se han fusionado y han formado una luna con un diametro de %s km!', 
        p_galaxy, p_system, p_position, v_moon_diameter),
      'system'
    );

    -- FIX: Los escombros se fusionaron en la luna, eliminar campo de escombros
    DELETE FROM debris_fields
    WHERE galaxy = p_galaxy
      AND solar_system = p_system
      AND position = p_position;
  END IF;
  
  RETURN jsonb_build_object(
    'moon_created', v_moon_created,
    'moon_chance', v_moon_chance,
    'moon_diameter', CASE WHEN v_moon_created THEN v_moon_diameter ELSE NULL END,
    'total_debris', v_total_debris
  );
END;
$$;


--
-- TOC entry 591 (class 1255 OID 18312)
-- Name: check_noob_protection(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_noob_protection(p_attacker_id uuid, p_defender_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_attacker_points integer;
  v_defender_points integer;
  v_noob_limit integer;
  v_protection_ratio integer;
  v_attacker_vacation boolean;
  v_defender_vacation boolean;
BEGIN
  SELECT points_total, vacation_mode INTO v_attacker_points, v_attacker_vacation
  FROM public.profiles WHERE id = p_attacker_id;

  SELECT points_total, vacation_mode INTO v_defender_points, v_defender_vacation
  FROM public.profiles WHERE id = p_defender_id;

  SELECT value::integer INTO v_noob_limit
  FROM public.game_settings WHERE key = 'newbie_protection_points';

  IF v_noob_limit IS NULL THEN
    v_noob_limit := 5000;
  END IF;

  -- Read protection ratio from admin settings (default 5 if not set)
  SELECT value::integer INTO v_protection_ratio
  FROM public.game_settings WHERE key = 'protection_ratio';

  IF v_protection_ratio IS NULL OR v_protection_ratio < 1 THEN
    v_protection_ratio := 5;
  END IF;

  -- Vacation mode checks
  IF v_attacker_vacation THEN
    RETURN jsonb_build_object(
      'can_attack', false,
      'reason', 'No puedes atacar en modo vacaciones'
    );
  END IF;

  IF v_defender_vacation THEN
    RETURN jsonb_build_object(
      'can_attack', false,
      'reason', 'El jugador esta en modo vacaciones'
    );
  END IF;

  -- Big player cannot attack noob
  IF v_defender_points <= v_noob_limit AND v_attacker_points > v_noob_limit THEN
    RETURN jsonb_build_object(
      'can_attack', false,
      'reason', 'El jugador esta bajo proteccion de novatos'
    );
  END IF;

  -- Noob cannot attack big player (mirror rule)
  IF v_attacker_points <= v_noob_limit AND v_defender_points > v_noob_limit THEN
    RETURN jsonb_build_object(
      'can_attack', false,
      'reason', 'El jugador es demasiado fuerte'
    );
  END IF;

  -- Attacker is Nx stronger than defender (uses admin-configured ratio)
  IF v_attacker_points > v_defender_points * v_protection_ratio AND v_defender_points > 0 THEN
    RETURN jsonb_build_object(
      'can_attack', false,
      'reason', format('El jugador es demasiado debil (ratio %s:1)', v_protection_ratio)
    );
  END IF;

  -- Defender is Nx stronger than attacker (uses admin-configured ratio)
  IF v_defender_points > v_attacker_points * v_protection_ratio AND v_defender_points > v_noob_limit THEN
    RETURN jsonb_build_object(
      'can_attack', false,
      'reason', format('El jugador es demasiado fuerte (ratio 1:%s)', v_protection_ratio)
    );
  END IF;

  RETURN jsonb_build_object('can_attack', true, 'reason', null);
END;
$$;


--
