--
-- TOC entry 913 (class 1255 OID 20301)
-- Name: check_protection_status(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_protection_status(p_target_galaxy integer, p_target_system integer, p_target_position integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_target_planet record;
  v_protection_check jsonb;
  v_bashing_check jsonb;
  v_attacker_points integer;
  v_defender_points integer;
  v_protection_ratio integer;
  v_noob_limit integer;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Not authenticated');
  END IF;

  SELECT p.*, pr.username as owner_username, pr.points_total as owner_points
  INTO v_target_planet
  FROM planets p
  JOIN profiles pr ON p.user_id = pr.id
  WHERE p.galaxy = p_target_galaxy
    AND p.solar_system = p_target_system
    AND p.position = p_target_position
    AND NOT p.is_destroyed;

  IF v_target_planet IS NULL THEN
    RETURN jsonb_build_object(
      'has_planet', false,
      'can_attack', true,
      'can_spy', true
    );
  END IF;

  IF v_target_planet.user_id = v_user_id THEN
    RETURN jsonb_build_object(
      'has_planet', true,
      'is_own', true,
      'can_attack', false,
      'can_spy', false,
      'reason', 'Tu propio planeta'
    );
  END IF;

  SELECT points_total INTO v_attacker_points FROM profiles WHERE id = v_user_id;
  v_attacker_points := COALESCE(v_attacker_points, 0);

  SELECT value::integer INTO v_protection_ratio FROM game_settings WHERE key = 'protection_ratio';
  v_protection_ratio := COALESCE(v_protection_ratio, 5);

  SELECT value::integer INTO v_noob_limit FROM game_settings WHERE key = 'newbie_protection_points';
  v_noob_limit := COALESCE(v_noob_limit, 5000);

  v_protection_check := check_noob_protection(v_user_id, v_target_planet.user_id);
  v_bashing_check := check_bashing_rule(v_user_id, v_target_planet.user_id);

  RETURN jsonb_build_object(
    'has_planet', true,
    'is_own', false,
    'owner_username', v_target_planet.owner_username,
    'owner_points', v_target_planet.owner_points,
    'attacker_points', v_attacker_points,
    'protection_ratio', v_protection_ratio,
    'noob_limit', v_noob_limit,
    'can_attack', COALESCE((v_protection_check->>'can_attack')::boolean, false)
      AND COALESCE((v_bashing_check->>'allowed')::boolean, true),
    'can_spy', true,
    'protection_reason', v_protection_check->>'reason',
    'bashing_reason', v_bashing_check->>'reason'
  );
END;
$$;


--
-- TOC entry 586 (class 1255 OID 18284)
-- Name: check_single_research(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_single_research() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
IF NEW.is_researching = true AND (OLD.is_researching IS NULL OR OLD.is_researching = false) THEN
IF EXISTS (
SELECT 1 FROM public.user_technologies
WHERE user_id = NEW.user_id
AND is_researching = true
AND id != NEW.id
) THEN
RAISE EXCEPTION 'User already has a research in progress';
END IF;
END IF;
RETURN NEW;
END;
$$;


--
-- TOC entry 1072 (class 1255 OID 21436)
-- Name: claim_daily_mission_reward(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_daily_mission_reward(p_user_id uuid, p_mission_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mission record;
  v_bonus_id uuid;
BEGIN
  SELECT udm.*, dm.reward_type, dm.reward_value, dm.reward_duration_hours, dm.code
  INTO v_mission
  FROM user_daily_missions udm
  JOIN daily_missions dm ON dm.id = udm.mission_id
  WHERE udm.id = p_mission_id AND udm.user_id = p_user_id
    AND udm.completed = true AND udm.claimed = false
    AND udm.expires_at > now()
  FOR UPDATE OF udm;

  IF v_mission IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mision no disponible o ya reclamada');
  END IF;

  UPDATE user_daily_missions SET claimed = true WHERE id = p_mission_id;

  INSERT INTO user_active_bonuses (user_id, mission_id, bonus_type, bonus_value, expires_at)
  VALUES (p_user_id, v_mission.mission_id, v_mission.reward_type, v_mission.reward_value, now() + (v_mission.reward_duration_hours || ' hours')::interval);

  RETURN jsonb_build_object(
    'success', true,
    'bonus_type', v_mission.reward_type,
    'bonus_value', v_mission.reward_value,
    'expires_at', now() + (v_mission.reward_duration_hours || ' hours')::interval
  );
END;
$$;


--
-- TOC entry 1081 (class 1255 OID 21455)
-- Name: claim_hero_expedition(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_hero_expedition(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_active record;
  v_expedition record;
  v_reward_items jsonb := '[]'::jsonb;
  v_rarity text;
  v_common_prob numeric;
  v_rare_prob numeric;
  v_epic_prob numeric;
  v_legendary_prob numeric;
  v_kit_25_prob numeric;
  v_kit_50_prob numeric;
  v_kit_75_prob numeric;
  v_kit_100_prob numeric;
  v_roll numeric;
  v_found_item record;
  v_ship record;
  v_lvl integer;
  v_item_lvl integer;
  v_scale numeric;
BEGIN
  PERFORM create_hero_ship(p_user_id);
  SELECT * INTO v_ship FROM user_hero_ships WHERE user_id = p_user_id;
  v_lvl := GREATEST(v_ship.level, 1);
  SELECT * INTO v_active FROM hero_ship_active_expedition WHERE user_id = p_user_id AND claimed = false FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes expedicion pendiente');
  END IF;

  IF now() < v_active.returns_at THEN
    RETURN jsonb_build_object('success', false, 'error', 'La expedicion aun no regresa');
  END IF;

  SELECT * INTO v_expedition FROM hero_ship_expeditions WHERE id = v_active.expedition_id;

  SELECT value::numeric INTO v_common_prob FROM game_settings WHERE key = 'hero_item_common_prob';
  SELECT value::numeric INTO v_rare_prob FROM game_settings WHERE key = 'hero_item_rare_prob';
  SELECT value::numeric INTO v_epic_prob FROM game_settings WHERE key = 'hero_item_epic_prob';
  SELECT value::numeric INTO v_legendary_prob FROM game_settings WHERE key = 'hero_item_legendary_prob';
  SELECT value::numeric INTO v_kit_25_prob FROM game_settings WHERE key = 'hero_repair_kit_25_prob';
  SELECT value::numeric INTO v_kit_50_prob FROM game_settings WHERE key = 'hero_repair_kit_50_prob';
  SELECT value::numeric INTO v_kit_75_prob FROM game_settings WHERE key = 'hero_repair_kit_75_prob';
  SELECT value::numeric INTO v_kit_100_prob FROM game_settings WHERE key = 'hero_repair_kit_100_prob';
  v_common_prob := COALESCE(v_common_prob, 50); v_rare_prob := COALESCE(v_rare_prob, 25);
  v_epic_prob := COALESCE(v_epic_prob, 15); v_legendary_prob := COALESCE(v_legendary_prob, 5);
  v_kit_25_prob := COALESCE(v_kit_25_prob, 25); v_kit_50_prob := COALESCE(v_kit_50_prob, 15);
  v_kit_75_prob := COALESCE(v_kit_75_prob, 8); v_kit_100_prob := COALESCE(v_kit_100_prob, 3);

  PERFORM add_hero_xp(p_user_id, v_expedition.xp_reward);

  UPDATE user_hero_ships SET hp = GREATEST(0, hp - v_expedition.hp_damage), updated_at = now() WHERE user_id = p_user_id;

  -- Weighted pool: single roll, always drops something
  IF v_kit_25_prob + v_kit_50_prob + v_kit_75_prob + v_kit_100_prob +
     v_common_prob + v_rare_prob + v_epic_prob + v_legendary_prob > 0 THEN
    v_roll := random() * (
      v_kit_25_prob + v_kit_50_prob + v_kit_75_prob + v_kit_100_prob +
      v_common_prob + v_rare_prob + v_epic_prob + v_legendary_prob
    );
    v_found_item := NULL;
    IF v_roll <= v_kit_25_prob THEN
      SELECT * INTO v_found_item FROM hero_ship_items WHERE name = 'Kit de Reparacion I' LIMIT 1;
    ELSIF v_roll <= v_kit_25_prob + v_kit_50_prob THEN
      SELECT * INTO v_found_item FROM hero_ship_items WHERE name = 'Kit de Reparacion II' LIMIT 1;
    ELSIF v_roll <= v_kit_25_prob + v_kit_50_prob + v_kit_75_prob THEN
      SELECT * INTO v_found_item FROM hero_ship_items WHERE name = 'Kit de Reparacion III' LIMIT 1;
    ELSIF v_roll <= v_kit_25_prob + v_kit_50_prob + v_kit_75_prob + v_kit_100_prob THEN
      SELECT * INTO v_found_item FROM hero_ship_items WHERE name = 'Kit de Reparacion IV' LIMIT 1;
    ELSIF v_roll <= v_kit_25_prob + v_kit_50_prob + v_kit_75_prob + v_kit_100_prob + v_common_prob THEN
      SELECT * INTO v_found_item FROM hero_ship_items
      WHERE rarity = 'common' AND slot_type != 'consumable'
      ORDER BY random() LIMIT 1;
    ELSIF v_roll <= v_kit_25_prob + v_kit_50_prob + v_kit_75_prob + v_kit_100_prob + v_common_prob + v_rare_prob THEN
      SELECT * INTO v_found_item FROM hero_ship_items
      WHERE rarity = 'rare' AND slot_type != 'consumable'
      ORDER BY random() LIMIT 1;
    ELSIF v_roll <= v_kit_25_prob + v_kit_50_prob + v_kit_75_prob + v_kit_100_prob + v_common_prob + v_rare_prob + v_epic_prob THEN
      SELECT * INTO v_found_item FROM hero_ship_items
      WHERE rarity = 'epic' AND slot_type != 'consumable'
      ORDER BY random() LIMIT 1;
    ELSE
      SELECT * INTO v_found_item FROM hero_ship_items
      WHERE rarity = 'legendary' AND slot_type != 'consumable'
      ORDER BY random() LIMIT 1;
    END IF;
  END IF;

  -- Guaranteed fallback: if no item was selected (all probs were 0 or queries returned nothing), force a common
  IF v_found_item.id IS NULL THEN
    SELECT * INTO v_found_item FROM hero_ship_items
    WHERE rarity = 'common' AND slot_type != 'consumable'
    ORDER BY random() LIMIT 1;
  END IF;

  IF v_found_item.id IS NOT NULL THEN
    IF v_lvl < v_found_item.min_level THEN
      v_item_lvl := v_found_item.min_level;
    ELSE
      v_item_lvl := FLOOR(random() * (v_lvl - v_found_item.min_level + 1))::integer + v_found_item.min_level;
    END IF;
    v_scale := v_item_lvl;

    INSERT INTO user_hero_ship_inventory (user_id, item_id, item_level, quantity)
    VALUES (p_user_id, v_found_item.id, v_item_lvl, 1)
    ON CONFLICT (user_id, item_id, item_level) DO UPDATE SET quantity = user_hero_ship_inventory.quantity + 1;

    v_reward_items := jsonb_build_array(jsonb_build_object(
      'name', v_found_item.name, 'rarity', v_found_item.rarity,
      'type', CASE WHEN v_found_item.is_repair_kit THEN 'repair_kit' ELSE 'equipment' END,
      'slot_type', v_found_item.slot_type,
      'item_level', v_item_lvl,
      'attack_bonus', FLOOR(v_found_item.attack_bonus * v_scale),
      'defense_bonus', FLOOR(v_found_item.defense_bonus * v_scale),
      'shield_bonus', FLOOR(v_found_item.shield_bonus * v_scale),
      'speed_bonus', FLOOR(v_found_item.speed_bonus * v_scale),
      'loot_bonus', FLOOR(v_found_item.loot_bonus * v_scale)
    ));
  END IF;

  UPDATE hero_ship_active_expedition SET claimed = true WHERE id = v_active.id;

  RETURN jsonb_build_object(
    'success', true,
    'xp_gained', v_expedition.xp_reward,
    'hp_damage', v_expedition.hp_damage,
    'items_found', v_reward_items
  );
END;
$$;


--
-- TOC entry 1116 (class 1255 OID 21811)
-- Name: clean_expired_cosmetics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clean_expired_cosmetics(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_expired record;
  v_type text;
BEGIN
  FOR v_expired IN
    SELECT uc.id, ci.cosmetic_type
    FROM user_cosmetics uc
    JOIN cosmetic_items ci ON ci.id = uc.cosmetic_id
    WHERE uc.user_id = p_user_id
      AND uc.equipped = true
      AND uc.expires_at < now()
  LOOP
    v_type := v_expired.cosmetic_type;

    UPDATE user_cosmetics SET equipped = false WHERE id = v_expired.id;

    IF v_type = 'title' THEN
      UPDATE profiles SET active_title = NULL, active_title_icon = NULL WHERE id = p_user_id;
    ELSIF v_type = 'badge' THEN
      UPDATE profiles SET active_badge = NULL WHERE id = p_user_id;
    ELSIF v_type = 'planet_effect' THEN
      UPDATE profiles SET active_planet_effect = NULL WHERE id = p_user_id;
    ELSIF v_type = 'hero_skin' THEN
      UPDATE profiles SET active_hero_skin = NULL WHERE id = p_user_id;
    END IF;
  END LOOP;
END;
$$;


--
-- TOC entry 633 (class 1255 OID 18595)
-- Name: complete_building_queue_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_building_queue_item(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET lock_timeout TO '30s'
    AS $$
DECLARE
  v_queue building_queue%ROWTYPE;
  v_planet planets%ROWTYPE;
  v_existing_building planet_buildings%ROWTYPE;
  v_levels_added integer;
  v_building_type building_types%ROWTYPE;
  v_fields_increase integer := 0;
  v_old_level integer;
BEGIN
  SELECT * INTO v_queue FROM building_queue WHERE id = p_queue_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Queue item not found');
  END IF;

  SELECT * INTO v_planet FROM planets WHERE id = v_queue.planet_id;
  IF NOT FOUND OR v_planet.user_id != auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not found or not owned');
  END IF;

  IF v_queue.end_time IS NULL OR v_queue.end_time > (NOW() + INTERVAL '2 seconds') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Build not complete yet');
  END IF;

  SELECT * INTO v_building_type FROM building_types WHERE id = v_queue.building_type_id;

  SELECT * INTO v_existing_building
  FROM planet_buildings
  WHERE planet_id = v_queue.planet_id AND building_type_id = v_queue.building_type_id;

  IF FOUND THEN
    v_levels_added := v_queue.target_level - v_existing_building.level;
    v_old_level := v_existing_building.level;
    UPDATE planet_buildings
    SET level = v_queue.target_level, is_upgrading = false, upgrade_end_time = NULL
    WHERE id = v_existing_building.id;
  ELSE
    v_levels_added := v_queue.target_level;
    v_old_level := 0;
    INSERT INTO planet_buildings (planet_id, building_type_id, level, is_upgrading)
    VALUES (v_queue.planet_id, v_queue.building_type_id, v_queue.target_level, false);
  END IF;

  IF v_building_type.code = 'lunar_base' THEN
    v_fields_increase := v_levels_added * 3;

    UPDATE planets
    SET
      fields_used = fields_used + v_levels_added,
      fields_max = fields_max + v_fields_increase
    WHERE id = v_queue.planet_id;
  ELSIF v_building_type.code = 'terraformer' THEN
    -- Exponencial: diferencia entre bonus del nuevo nivel y bonus del nivel anterior
    v_fields_increase := terraformer_field_bonus(v_queue.target_level) - terraformer_field_bonus(v_old_level);

    UPDATE planets
    SET
      fields_used = fields_used + v_levels_added,
      fields_max = fields_max + v_fields_increase
    WHERE id = v_queue.planet_id;
  ELSE
    IF v_levels_added > 0 THEN
      UPDATE planets SET fields_used = fields_used + v_levels_added WHERE id = v_queue.planet_id;
    END IF;
  END IF;

  DELETE FROM building_queue WHERE id = p_queue_id;

  WITH reordered AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY queue_position) as new_pos
    FROM building_queue
    WHERE planet_id = v_queue.planet_id
  )
  UPDATE building_queue bq
  SET
    queue_position = r.new_pos,
    start_time = CASE WHEN r.new_pos = 1 AND bq.start_time IS NULL THEN NOW() ELSE bq.start_time END,
    end_time = CASE WHEN r.new_pos = 1 AND bq.end_time IS NULL THEN NOW() + (bq.build_time || ' seconds')::interval ELSE bq.end_time END
  FROM reordered r
  WHERE bq.id = r.id;

  RETURN jsonb_build_object(
    'success', true,
    'building_type_id', v_queue.building_type_id,
    'new_level', v_queue.target_level,
    'fields_increase', v_fields_increase
  );
END;
$$;


--
-- TOC entry 587 (class 1255 OID 18286)
-- Name: complete_research(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_research(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  research_record RECORD;
BEGIN
  IF p_user_id != auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: can only complete own research';
  END IF;

  FOR research_record IN
    SELECT id, level
    FROM user_technologies
    WHERE user_id = p_user_id
    AND is_researching = true
    AND research_end_time <= NOW()
  LOOP
    UPDATE user_technologies
    SET
      level = level + 1,
      is_researching = false,
      research_end_time = NULL,
      research_planet_id = NULL
    WHERE id = research_record.id;
  END LOOP;
END;
$$;


--
-- TOC entry 798 (class 1255 OID 19467)
-- Name: complete_telegram_link(text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_telegram_link(p_link_code text, p_telegram_id bigint, p_telegram_username text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_link telegram_links%ROWTYPE;
  v_existing_telegram telegram_links%ROWTYPE;
BEGIN
  -- Check if this Telegram ID is already linked to another account
  SELECT * INTO v_existing_telegram 
  FROM telegram_links 
  WHERE telegram_id = p_telegram_id;

  IF v_existing_telegram IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'This Telegram account is already linked to another game account'
    );
  END IF;

  -- Find the link code (extended to 24 hours)
  SELECT * INTO v_link 
  FROM telegram_links 
  WHERE link_code = upper(p_link_code)
    AND telegram_id IS NULL
    AND created_at > now() - interval '24 hours';

  IF v_link IS NULL THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Invalid or expired link code'
    );
  END IF;

  -- Update the link
  UPDATE telegram_links
  SET telegram_id = p_telegram_id,
      telegram_username = p_telegram_username,
      linked_at = now(),
      link_code = NULL
  WHERE id = v_link.id;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', v_link.user_id,
    'message', 'Account linked successfully'
  );
END;
$$;


--
-- TOC entry 679 (class 1255 OID 18859)
-- Name: complete_withdrawal(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_withdrawal(p_tx_id uuid, p_tx_hash text, p_block_number bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  -- SECURITY: Only service_role can call this function
  v_role := current_setting('role', true);
  IF v_role IS DISTINCT FROM 'service_role' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Only server can complete withdrawals');
  END IF;

  UPDATE wallet_transactions
  SET status = 'confirmed',
      tx_hash = p_tx_hash,
      block_number = p_block_number,
      processed_at = now(),
      updated_at = now()
  WHERE id = p_tx_id AND status = 'processing';

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction not found or not in processing status');
  END IF;

  RETURN jsonb_build_object('success', true, 'tx_hash', p_tx_hash);
END;
$$;


