--
-- TOC entry 784 (class 1255 OID 19305)
-- Name: confirm_deposit_usdt(text, uuid, numeric, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_deposit_usdt(p_tx_hash text, p_user_id uuid, p_amount numeric, p_block_number bigint, p_confirmations integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing_tx wallet_transactions%ROWTYPE;
  v_tx_id uuid;
BEGIN
  -- Check if transaction already exists
  SELECT * INTO v_existing_tx FROM wallet_transactions WHERE tx_hash = p_tx_hash;
  
  IF v_existing_tx.id IS NOT NULL THEN
    IF v_existing_tx.status = 'confirmed' THEN
      RETURN jsonb_build_object('success', false, 'error', 'Transaction already confirmed');
    END IF;
    
    -- Update existing transaction
    UPDATE wallet_transactions
    SET status = 'confirmed',
        confirmations = p_confirmations,
        block_number = p_block_number,
        processed_at = now(),
        updated_at = now()
    WHERE id = v_existing_tx.id;
    
    v_tx_id := v_existing_tx.id;
  ELSE
    -- Create new confirmed transaction
    INSERT INTO wallet_transactions (
      user_id, tx_hash, tx_type, token_type, amount, fxu_amount, wallet_address, 
      status, confirmations, block_number, processed_at
    ) VALUES (
      p_user_id, p_tx_hash, 'deposit', 'USDT', p_amount, p_amount, '',
      'confirmed', p_confirmations, p_block_number, now()
    ) RETURNING id INTO v_tx_id;
  END IF;

  -- Credit USDT to user (1:1 ratio)
  UPDATE profiles 
  SET usdt_balance = usdt_balance + p_amount,
      updated_at = now()
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'transaction_id', v_tx_id,
    'amount_credited', p_amount
  );
END;
$$;


--
-- TOC entry 983 (class 1255 OID 20613)
-- Name: contribute_to_jackpot(numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contribute_to_jackpot(p_amount numeric, p_source text, p_user_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_expedition_amount numeric;
  v_monthly_amount numeric;
  v_plus_amount numeric;
  v_destruction_amount numeric;
  v_expedition_percent int;
  v_monthly_percent int;
  v_plus_percent int;
  v_destruction_percent int;
  v_new_total numeric;
BEGIN
  IF p_amount <= 0 THEN
    RETURN 0;
  END IF;

  SELECT expedition_percent, monthly_percent, plus_percent, destruction_percent
  INTO v_expedition_percent, v_monthly_percent, v_plus_percent, v_destruction_percent
  FROM jackpot_pools WHERE id = 1;

  IF v_expedition_percent IS NULL THEN
    v_expedition_percent := 10;
    v_monthly_percent := 10;
    v_plus_percent := 50;
    v_destruction_percent := 30;
  END IF;
  IF v_destruction_percent IS NULL THEN
    v_destruction_percent := 40;
  END IF;

  v_expedition_amount := FLOOR(p_amount * v_expedition_percent / 100);
  v_monthly_amount := FLOOR(p_amount * v_monthly_percent / 100);
  v_plus_amount := FLOOR(p_amount * v_plus_percent / 100);
  v_destruction_amount := FLOOR(p_amount * v_destruction_percent / 100);

  UPDATE jackpot_pools
  SET 
    expedition_balance = expedition_balance + v_expedition_amount,
    expedition_total = expedition_total + v_expedition_amount,
    monthly_balance = monthly_balance + v_monthly_amount,
    monthly_total = monthly_total + v_monthly_amount,
    plus_balance = plus_balance + v_plus_amount,
    plus_total = plus_total + v_plus_amount,
    destruction_balance = destruction_balance + v_destruction_amount,
    destruction_total = destruction_total + v_destruction_amount,
    updated_at = now()
  WHERE id = 1;

  UPDATE jackpot
  SET balance = balance + p_amount, total_contributed = total_contributed + p_amount, updated_at = now()
  WHERE id = 1;

  SELECT expedition_balance + monthly_balance + plus_balance + destruction_balance 
  INTO v_new_total
  FROM jackpot_pools WHERE id = 1;

  INSERT INTO jackpot_history (user_id, type, amount, source, jackpot_balance_after)
  VALUES (p_user_id, 'contribution', p_amount, p_source, v_new_total);

  RETURN v_new_total;
END;
$$;


--
-- TOC entry 713 (class 1255 OID 18943)
-- Name: create_acs_from_fleet(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_acs_from_fleet(p_fleet_id uuid, p_acs_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fleet record;
  v_alliance_id uuid;
  v_acs_id uuid;
  v_acs_name text;
  v_user_id uuid;
  v_depot_level integer;
  v_max_fleets integer;
  v_depot_type_id integer;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_fleet FROM fleets 
  WHERE id = p_fleet_id 
  AND user_id = v_user_id
  AND mission_type = 'attack'
  AND is_returning = false 
  AND is_completed = false;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Flota no encontrada o no es una mision de ataque valida');
  END IF;

  IF v_fleet.acs_id IS NOT NULL OR v_fleet.is_acs = true THEN
    RETURN jsonb_build_object('success', false, 'error', 'Esta flota ya forma parte de un ACS');
  END IF;

  SELECT alliance_id INTO v_alliance_id FROM alliance_members WHERE user_id = v_user_id;
  IF v_alliance_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Debes ser miembro de una alianza para crear un ataque ACS');
  END IF;

  -- Calculate max_fleets based on alliance_depot level on origin planet
  -- Formula: min(5, 1 + floor(alliance_depot_level / 2))
  SELECT id INTO v_depot_type_id FROM building_types WHERE code = 'alliance_depot';

  IF v_depot_type_id IS NOT NULL AND v_fleet.origin_planet_id IS NOT NULL THEN
    SELECT COALESCE(pb.level, 0) INTO v_depot_level
    FROM planet_buildings pb
    WHERE pb.planet_id = v_fleet.origin_planet_id
      AND pb.building_type_id = v_depot_type_id;
  END IF;

  v_depot_level := COALESCE(v_depot_level, 0);
  v_max_fleets := LEAST(5, 1 + FLOOR(v_depot_level / 2)::integer);

  v_acs_name := COALESCE(NULLIF(TRIM(p_acs_name), ''), 'ACS-' || substr(p_fleet_id::text, 1, 8));

  INSERT INTO acs_fleets (
    main_fleet_id, alliance_id, name, creator_id,
    target_galaxy, target_system, target_position,
    arrival_time, max_fleets, is_active, status, 
    current_participants, invited_users
  ) VALUES (
    p_fleet_id, v_alliance_id, v_acs_name, v_user_id,
    v_fleet.target_galaxy, v_fleet.target_system, v_fleet.target_position,
    v_fleet.arrival_time, v_max_fleets, true, 'waiting',
    1, ARRAY[]::uuid[]
  ) RETURNING id INTO v_acs_id;

  UPDATE fleets SET acs_id = v_acs_id, is_acs = true WHERE id = p_fleet_id;

  INSERT INTO acs_participants (acs_id, fleet_id, user_id)
  VALUES (v_acs_id, p_fleet_id, v_user_id);

  RETURN jsonb_build_object(
    'success', true, 
    'acs_id', v_acs_id,
    'max_fleets', v_max_fleets,
    'message', format('Ataque ACS "%s" creado exitosamente', v_acs_name)
  );
END;
$$;


--
-- TOC entry 1098 (class 1255 OID 21689)
-- Name: create_alliance_war(text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_alliance_war(p_title text, p_entry_fee_fxu integer, p_war_type text DEFAULT 'weekly'::text, p_duration_hours integer DEFAULT 168) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
