--
-- TOC entry 998 (class 1255 OID 20836)
-- Name: create_lottery_draw(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_lottery_draw(p_closes_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
  v_existing record;
  v_accumulated numeric := 0;
  v_draw_id uuid;
  v_close_date timestamptz;
BEGIN
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = auth.uid();
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  SELECT * INTO v_existing FROM lottery_draws WHERE status = 'open' LIMIT 1 FOR UPDATE;
  IF v_existing.id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya hay un sorteo activo (#' || v_existing.draw_number || '). Ciérralo primero.');
  END IF;

  SELECT COALESCE(accumulated_jackpot, 0) + COALESCE(prize_pool, 0)
  INTO v_accumulated
  FROM lottery_draws WHERE status = 'completed'
  AND jackpot_winner_id IS NULL
  ORDER BY drawn_at DESC LIMIT 1;

  IF v_accumulated IS NULL THEN v_accumulated := 0; END IF;

  -- ★ FIX: Próximo domingo 23:59 UTC (max 7 días, no 12+)
  v_close_date := COALESCE(p_closes_at,
    (date_trunc('week', now() + interval '1 day') + interval '6 days 23 hours 59 minutes')::timestamptz
  );

  INSERT INTO lottery_draws (status, opens_at, closes_at, accumulated_jackpot)
  VALUES ('open', now(), v_close_date, v_accumulated)
  RETURNING id INTO v_draw_id;

  RETURN jsonb_build_object(
    'success', true,
    'draw_id', v_draw_id,
    'closes_at', v_close_date,
    'accumulated_jackpot', v_accumulated
  );
END;
$$;


--
-- TOC entry 618 (class 1255 OID 18507)
-- Name: create_market_listing(text, text, bigint, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_market_listing(p_listing_type text, p_item_code text, p_quantity bigint, p_price_per_unit numeric, p_planet_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_total_price numeric;
  v_current_amount numeric;
  v_ship_quantity int;
  v_user_dm int;
  v_listing_id uuid;
  v_telegram_id bigint;
  v_is_member boolean;
  v_username text;
  v_limits RECORD;
  v_year_week text;
  v_current_sold bigint;
  v_active_listed bigint;
  v_weekly_limit bigint;
  v_min_price numeric;
  v_remaining bigint;
  v_ship_value bigint;
  v_ship_total_value bigint;
  v_current_ships_value_sold bigint;
  v_active_ships_value bigint;
  v_ships_value_remaining bigint;
  v_fxu_limit numeric;
  v_fxu_value_this_listing numeric;
  v_fxu_value_sold numeric;
  v_fxu_value_active numeric;
  v_fxu_remaining numeric;
  v_fxu_ok boolean := false;
  v_unit_ok boolean := false;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  -- Block if user is in vacation mode
  IF EXISTS (SELECT 1 FROM profiles WHERE id = v_user_id AND vacation_mode = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes usar el mercado en modo vacaciones. Desactiva el modo vacaciones primero.');
  END IF;

  SELECT telegram_id INTO v_telegram_id
  FROM telegram_links WHERE user_id = v_user_id;

  IF v_telegram_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Debes vincular tu cuenta de Telegram para usar el mercado. Ve a la seccion de Tareas para vincular tu cuenta.',
      'requires_telegram', true
    );
  END IF;

  SELECT is_member INTO v_is_member
  FROM telegram_task_rewards WHERE user_id = v_user_id AND task_type = 'join_group';

  IF v_is_member IS NULL OR v_is_member = false THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Debes ser miembro del grupo de Telegram para usar el mercado. Unete al grupo desde la seccion de Tareas.',
      'requires_telegram', true
    );
  END IF;

  IF (SELECT COUNT(*) FROM market_listings WHERE seller_id = v_user_id AND status = 'active') >= 15 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Maximo 15 ofertas activas permitidas. Cancela o espera que se vendan algunas.');
  END IF;

  IF p_quantity <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cantidad debe ser mayor a 0');
  END IF;

  IF p_price_per_unit <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Precio debe ser mayor a 0');
  END IF;

  IF p_listing_type NOT IN ('resource', 'ship', 'dark_matter') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tipo de listado invalido');
  END IF;

  IF p_listing_type != 'dark_matter' THEN
    IF p_planet_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Planeta requerido');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM planets WHERE id = p_planet_id AND user_id = v_user_id) THEN
      RETURN jsonb_build_object('success', false, 'error', 'No eres dueno de este planeta');
    END IF;
  END IF;

  v_total_price := p_quantity * p_price_per_unit;

  SELECT * INTO v_limits FROM market_resource_limits WHERE id = 1;

  IF v_limits.monthly_limit_enabled AND p_listing_type IN ('resource', 'ship') THEN
    v_year_week := to_char(now(), 'IYYY-"W"IW');

    -- Min price ALWAYS applies (even VIP)
    IF p_listing_type = 'resource' THEN
      IF p_item_code = 'metal' THEN v_min_price := v_limits.min_price_metal;
      ELSIF p_item_code = 'crystal' THEN v_min_price := v_limits.min_price_crystal;
      ELSIF p_item_code = 'deuterium' THEN v_min_price := v_limits.min_price_deuterium;
      END IF;

      IF p_price_per_unit < v_min_price THEN
        RETURN jsonb_build_object(
          'success', false,
          'error', 'Precio minimo por unidad de ' || p_item_code || ' es ' || v_min_price || ' FXU',
          'min_price', v_min_price
        );
      END IF;
    END IF;

    -- ========== VIP PLUS: SKIP ALL LIMITS ==========
    IF is_user_plus(v_user_id) THEN
      -- VIP Plus users have no selling limits
      NULL;
    ELSE

    -- ========== CHECK 1: FXU CREDIT MODE ==========
    v_fxu_limit := calculate_fxu_weekly_limit(v_user_id);

    IF v_fxu_limit > 0 THEN
      v_fxu_value_this_listing := v_total_price;

      SELECT COALESCE(fxu_value_sold, 0) INTO v_fxu_value_sold
      FROM market_monthly_sales WHERE user_id = v_user_id AND year_month = v_year_week;
      v_fxu_value_sold := COALESCE(v_fxu_value_sold, 0);

      SELECT COALESCE(SUM(ml.quantity * ml.price_per_unit), 0) INTO v_fxu_value_active
      FROM market_listings ml
      WHERE ml.seller_id = v_user_id AND ml.status = 'active'
        AND ml.listing_type IN ('resource', 'ship')
        AND ml.created_at >= date_trunc('week', now());

      v_fxu_remaining := v_fxu_limit - v_fxu_value_sold - v_fxu_value_active;

      IF v_fxu_value_this_listing <= v_fxu_remaining THEN
        v_fxu_ok := true;
      END IF;
    END IF;

    -- ========== CHECK 2: UNIT LIMIT BY RANKING POINTS ==========
    IF p_listing_type = 'resource' THEN
      v_weekly_limit := calculate_monthly_market_limit(v_user_id);

      SELECT CASE p_item_code
        WHEN 'metal' THEN COALESCE(metal_sold, 0)
        WHEN 'crystal' THEN COALESCE(crystal_sold, 0)
        WHEN 'deuterium' THEN COALESCE(deuterium_sold, 0)
      END INTO v_current_sold
      FROM market_monthly_sales WHERE user_id = v_user_id AND year_month = v_year_week;
      v_current_sold := COALESCE(v_current_sold, 0);

      SELECT COALESCE(SUM(quantity), 0) INTO v_active_listed
      FROM market_listings
      WHERE seller_id = v_user_id AND listing_type = 'resource' AND item_code = p_item_code
        AND status = 'active' AND created_at >= date_trunc('week', now());

      v_remaining := v_weekly_limit - v_current_sold - v_active_listed;
      IF p_quantity <= v_remaining THEN v_unit_ok := true; END IF;
    END IF;

    IF p_listing_type = 'ship' THEN
      SELECT (COALESCE(metal_cost, 0) + COALESCE(crystal_cost, 0) + COALESCE(deuterium_cost, 0))::bigint
      INTO v_ship_value FROM ship_types WHERE code = p_item_code;
      v_ship_value := COALESCE(v_ship_value, 0);

      IF v_ship_value > 0 THEN
        v_ship_total_value := p_quantity * v_ship_value;
        v_weekly_limit := calculate_monthly_market_limit(v_user_id);

        SELECT COALESCE(ships_value_sold, 0) INTO v_current_ships_value_sold
        FROM market_monthly_sales WHERE user_id = v_user_id AND year_month = v_year_week;
        v_current_ships_value_sold := COALESCE(v_current_ships_value_sold, 0);

        SELECT COALESCE(SUM(ml.quantity * (COALESCE(st.metal_cost, 0) + COALESCE(st.crystal_cost, 0) + COALESCE(st.deuterium_cost, 0))), 0)
        INTO v_active_ships_value
        FROM market_listings ml JOIN ship_types st ON st.code = ml.item_code
        WHERE ml.seller_id = v_user_id AND ml.listing_type = 'ship' AND ml.status = 'active'
          AND ml.created_at >= date_trunc('week', now());

        v_ships_value_remaining := v_weekly_limit - v_current_ships_value_sold - v_active_ships_value;
        IF v_ship_total_value <= v_ships_value_remaining THEN v_unit_ok := true; END IF;
      ELSE
        v_unit_ok := true;
      END IF;
    END IF;

    -- ========== BLOCK ONLY IF BOTH MODES FAIL ==========
    IF NOT v_fxu_ok AND NOT v_unit_ok THEN
      IF v_fxu_limit > 0 AND v_weekly_limit > 0 THEN
        RETURN jsonb_build_object(
          'success', false,
          'error', 'Excede ambos limites semanales. Credito FXU restante: ' || ROUND(GREATEST(0, v_fxu_remaining), 2) || ' FXU. Limite de unidades restante: ' || GREATEST(0, COALESCE(v_remaining, v_ships_value_remaining)) || '.',
          'fxu_limit', v_fxu_limit, 'fxu_remaining', GREATEST(0, v_fxu_remaining),
          'unit_remaining', GREATEST(0, COALESCE(v_remaining, v_ships_value_remaining))
        );
      ELSIF v_fxu_limit > 0 THEN
        RETURN jsonb_build_object(
          'success', false,
          'error', 'Excede tu credito de inversion. Restante: ' || ROUND(GREATEST(0, v_fxu_remaining), 2) || ' FXU (credito total: ' || ROUND(v_fxu_limit, 2) || ' FXU)',
          'fxu_limit', v_fxu_limit, 'fxu_remaining', GREATEST(0, v_fxu_remaining)
        );
      ELSE
        IF p_listing_type = 'resource' THEN
          RETURN jsonb_build_object(
            'success', false,
            'error', 'Excede tu limite semanal de unidades de ' || p_item_code || '. Restante: ' || GREATEST(0, v_remaining) || ' unidades (limite: ' || v_weekly_limit || ')',
            'weekly_limit', v_weekly_limit, 'remaining', GREATEST(0, v_remaining)
          );
        ELSE
          RETURN jsonb_build_object(
            'success', false,
            'error', 'Excede tu limite semanal de venta de naves. Valor restante: ' || GREATEST(0, v_ships_value_remaining) || ' (limite: ' || v_weekly_limit || ', valor por nave: ' || v_ship_value || ')',
            'weekly_limit', v_weekly_limit, 'remaining', GREATEST(0, v_ships_value_remaining), 'ship_value', v_ship_value
          );
        END IF;
      END IF;
    END IF;

    END IF; -- end VIP Plus check
  END IF;

  -- === Validate resources/ships/DM ===
  IF p_listing_type = 'resource' THEN
    IF p_item_code NOT IN ('metal', 'crystal', 'deuterium') THEN
      RETURN jsonb_build_object('success', false, 'error', 'Recurso invalido');
    END IF;
    IF p_item_code = 'metal' THEN
      SELECT metal INTO v_current_amount FROM planet_resources WHERE planet_id = p_planet_id FOR UPDATE;
      IF v_current_amount IS NULL OR v_current_amount < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Metal insuficiente');
      END IF;
    ELSIF p_item_code = 'crystal' THEN
      SELECT crystal INTO v_current_amount FROM planet_resources WHERE planet_id = p_planet_id FOR UPDATE;
      IF v_current_amount IS NULL OR v_current_amount < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cristal insuficiente');
      END IF;
    ELSIF p_item_code = 'deuterium' THEN
      SELECT deuterium INTO v_current_amount FROM planet_resources WHERE planet_id = p_planet_id FOR UPDATE;
      IF v_current_amount IS NULL OR v_current_amount < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Deuterio insuficiente');
      END IF;
    END IF;
  ELSIF p_listing_type = 'dark_matter' THEN
    SELECT dark_matter INTO v_user_dm FROM profiles WHERE id = v_user_id FOR UPDATE;
    IF v_user_dm IS NULL OR v_user_dm < p_quantity THEN
      RETURN jsonb_build_object('success', false, 'error', 'Materia oscura insuficiente');
    END IF;
    UPDATE profiles SET dark_matter = dark_matter - p_quantity WHERE id = v_user_id;
  ELSIF p_listing_type = 'ship' THEN
    IF NOT EXISTS (SELECT 1 FROM ship_types WHERE code = p_item_code) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Tipo de nave invalido');
    END IF;
    SELECT ps.quantity INTO v_ship_quantity
    FROM planet_ships ps JOIN ship_types st ON st.id = ps.ship_type_id
    WHERE ps.planet_id = p_planet_id AND st.code = p_item_code FOR UPDATE;
    IF v_ship_quantity IS NULL OR v_ship_quantity < p_quantity THEN
      RETURN jsonb_build_object('success', false, 'error', 'Naves insuficientes');
    END IF;
  END IF;

  INSERT INTO market_listings (seller_id, listing_type, item_code, quantity, price_per_unit, total_price, planet_id, status)
  VALUES (v_user_id, p_listing_type, p_item_code, p_quantity, p_price_per_unit, v_total_price, p_planet_id, 'active')
  RETURNING id INTO v_listing_id;

  SELECT username INTO v_username FROM profiles WHERE id = v_user_id;

  PERFORM send_market_telegram_notification(
    v_listing_id, COALESCE(v_username, 'Jugador'),
    p_listing_type, p_item_code, p_quantity, p_price_per_unit, v_total_price
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Oferta creada exitosamente. Los recursos permanecen en tu planeta hasta que se vendan.',
    'listing_id', v_listing_id
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Error al crear oferta: ' || SQLERRM);
END;
$$;


--
-- TOC entry 593 (class 1255 OID 18314)
-- Name: create_moon_from_battle(uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_moon_from_battle(p_planet_id uuid, p_debris_metal numeric, p_debris_crystal numeric) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
v_total_debris numeric;
v_moon_chance integer;
v_random_roll integer;
v_moon_diameter integer;
v_moon_fields integer;
v_planet record;
v_existing_moon uuid;
v_new_moon_id uuid;
BEGIN
SELECT id INTO v_existing_moon
FROM public.planets
WHERE galaxy = (SELECT galaxy FROM public.planets WHERE id = p_planet_id)
AND solar_system = (SELECT solar_system FROM public.planets WHERE id = p_planet_id)
AND position = (SELECT position FROM public.planets WHERE id = p_planet_id)
AND planet_type = 'moon';

IF v_existing_moon IS NOT NULL THEN
RETURN NULL;
END IF;

v_total_debris := COALESCE(p_debris_metal, 0) + COALESCE(p_debris_crystal, 0);
v_moon_chance := LEAST(20, GREATEST(0, FLOOR(v_total_debris / 100000)::integer));

IF v_moon_chance < 1 THEN
RETURN NULL;
END IF;

v_random_roll := FLOOR(RANDOM() * 100)::integer + 1;

IF v_random_roll > v_moon_chance THEN
RETURN NULL;
END IF;

SELECT * INTO v_planet FROM public.planets WHERE id = p_planet_id;

v_moon_diameter := 8000 + (v_moon_chance * 100) + FLOOR(RANDOM() * 1000)::integer;
v_moon_fields := FLOOR(POWER(v_moon_diameter / 1000.0, 2) * 0.5)::integer;

INSERT INTO public.planets (
user_id, name, galaxy, solar_system, position,
planet_type, diameter, fields_max, temp_min, temp_max
) VALUES (
v_planet.user_id,
'Luna',
v_planet.galaxy,
v_planet.solar_system,
v_planet.position,
'moon',
v_moon_diameter,
v_moon_fields,
-40,
-20
) RETURNING id INTO v_new_moon_id;

INSERT INTO public.planet_resources (planet_id, metal, crystal, deuterium)
VALUES (v_new_moon_id, 0, 0, 0);

INSERT INTO public.messages (recipient_id, subject, body, message_type)
VALUES (
v_planet.user_id,
'Nueva Luna Creada',
'Los escombros de la batalla han formado una luna en las coordenadas [' ||
v_planet.galaxy || ':' || v_planet.solar_system || ':' || v_planet.position ||
']. Diametro: ' || v_moon_diameter || ' km. Campos: ' || v_moon_fields,
'system'
);

RETURN v_new_moon_id;
END;
$$;


--
-- TOC entry 583 (class 1255 OID 18212)
-- Name: delete_user_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_user_account() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  current_user_id uuid;
  user_alliance_id uuid;
  alliance_member_count int;
  next_leader_id uuid;
BEGIN
  current_user_id := auth.uid();

  IF current_user_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Check if user is alliance leader and handle transfer/disband
  SELECT am.alliance_id INTO user_alliance_id
  FROM alliance_members am
  JOIN alliances a ON a.id = am.alliance_id
  WHERE am.user_id = current_user_id
  AND a.leader_id = current_user_id;

  IF user_alliance_id IS NOT NULL THEN
    -- Count remaining members (excluding current user)
    SELECT COUNT(*) INTO alliance_member_count
    FROM alliance_members
    WHERE alliance_id = user_alliance_id
    AND user_id != current_user_id;

    IF alliance_member_count > 0 THEN
      -- Transfer leadership to longest-standing member
      SELECT user_id INTO next_leader_id
      FROM alliance_members
      WHERE alliance_id = user_alliance_id
      AND user_id != current_user_id
      ORDER BY joined_at ASC
      LIMIT 1;

      UPDATE alliances
      SET leader_id = next_leader_id
      WHERE id = user_alliance_id;

      -- Promote new leader to officer if not already
      UPDATE alliance_members
      SET role = 'officer'
      WHERE alliance_id = user_alliance_id
      AND user_id = next_leader_id
      AND role = 'member';
    ELSE
      -- No other members, disband alliance
      DELETE FROM alliances WHERE id = user_alliance_id;
    END IF;
  END IF;

  -- Cancel active fleets (return resources if possible)
  DELETE FROM fleets WHERE user_id = current_user_id;

  -- Clear building and shipyard queues
  DELETE FROM building_queue WHERE planet_id IN (
    SELECT id FROM planets WHERE user_id = current_user_id
  );
  DELETE FROM shipyard_queue WHERE planet_id IN (
    SELECT id FROM planets WHERE user_id = current_user_id
  );

  -- Cancel active research
  UPDATE profiles 
  SET current_research_id = NULL,
      research_end_time = NULL
  WHERE id = current_user_id;

  -- Delete the profile (cascades to most related tables)
  DELETE FROM profiles WHERE id = current_user_id;

  RETURN json_build_object('success', true);
EXCEPTION
  WHEN OTHERS THEN
    RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- TOC entry 1158 (class 1255 OID 22479)
-- Name: deploy_to_fortress(integer, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deploy_to_fortress(p_galaxy integer, p_planet_id uuid, p_ships jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_alliance_id uuid;
  v_fortress record;
  v_ship record;
  v_existing integer;
  v_total bigint := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  -- Verificar membresía de alianza
  SELECT am.alliance_id INTO v_alliance_id
  FROM alliance_members am
  WHERE am.user_id = v_user_id;
  
  IF v_alliance_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No perteneces a ninguna alianza');
  END IF;

  -- Verificar que la alianza es dueña de la fortaleza
  SELECT * INTO v_fortress
  FROM alliance_fortresses
  WHERE galaxy = p_galaxy;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Fortaleza no encontrada en galaxia ' || p_galaxy);
  END IF;

  IF v_fortress.owner_alliance_id IS NULL OR v_fortress.owner_alliance_id != v_alliance_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tu alianza no controla esta fortaleza');
  END IF;

  -- Procesar cada tipo de nave
  FOR v_ship IN SELECT * FROM jsonb_to_recordset(p_ships) AS x(ship_type_id integer, quantity integer)
  LOOP
    -- Verificar que el usuario tiene esas naves en su planeta
    SELECT quantity INTO v_existing
    FROM planet_ships
    WHERE planet_id = p_planet_id AND ship_type_id = v_ship.ship_type_id;
    
    IF v_existing IS NULL OR v_existing < v_ship.quantity THEN
      RETURN jsonb_build_object('success', false, 'error', 'No tienes suficientes naves tipo ' || v_ship.ship_type_id);
    END IF;

    -- Restar de planet_ships
    UPDATE planet_ships
    SET quantity = quantity - v_ship.quantity
    WHERE planet_id = p_planet_id AND ship_type_id = v_ship.ship_type_id;

    -- Eliminar fila si quantity = 0
    DELETE FROM planet_ships
    WHERE planet_id = p_planet_id AND ship_type_id = v_ship.ship_type_id AND quantity <= 0;

    -- Sumar a fortress_ships
    INSERT INTO fortress_ships (fortress_id, user_id, alliance_id, ship_type_id, quantity)
    VALUES (v_fortress.id, v_user_id, v_alliance_id, v_ship.ship_type_id, v_ship.quantity)
    ON CONFLICT (id) DO NOTHING;
  END LOOP;

  -- Calcular total de naves en la fortaleza
  SELECT COALESCE(SUM(quantity), 0) INTO v_total
  FROM fortress_ships
  WHERE fortress_id = v_fortress.id;

  RETURN jsonb_build_object(
    'success', true,
    'total_ships', v_total,
    'message', 'Naves desplegadas exitosamente'
  );
END;
$$;


--
-- TOC entry 1053 (class 1255 OID 21273)
-- Name: diagnose_planet_fields(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.diagnose_planet_fields(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_planet record;
  v_calculated_max integer;
  v_terraformer_level integer;
  v_result jsonb;
BEGIN
  SELECT * INTO v_planet FROM public.planets WHERE id = p_planet_id;
  
  IF v_planet IS NULL THEN
    RETURN jsonb_build_object('error', 'Planet not found');
  END IF;
  
  v_calculated_max := public.calculate_planet_max_fields(p_planet_id);
  
  SELECT COALESCE(pb.level, 0) INTO v_terraformer_level
  FROM public.planet_buildings pb
  JOIN public.building_types bt ON pb.building_type_id = bt.id
  WHERE pb.planet_id = p_planet_id AND bt.code = 'terraformer';
  
  v_result := jsonb_build_object(
    'planet_id', v_planet.id,
    'planet_name', v_planet.name,
    'diameter', v_planet.diameter,
    'position', v_planet.position,
    'fields_used', v_planet.fields_used,
    'fields_max_current', v_planet.fields_max,
    'fields_max_calculated', v_calculated_max,
    'terraformer_level', v_terraformer_level,
    'terraformer_bonus', public.terraformer_field_bonus(v_terraformer_level),
    'status', CASE 
      WHEN v_planet.fields_used > v_planet.fields_max THEN 'OVERFLOW ⚠️'
      WHEN v_planet.fields_used = v_planet.fields_max THEN 'FULL (no free fields) ⚠️'
      WHEN v_planet.fields_max < v_calculated_max THEN 'UNDERESTIMATED (fields_max too low) ⚠️'
      WHEN v_planet.fields_max > v_calculated_max THEN 'OVERESTIMATED (fields_max too high) ⚠️'
      ELSE 'OK ✓'
    END,
    'free_fields', v_planet.fields_max - v_planet.fields_used,
    'needs_recalc', v_planet.fields_max != v_calculated_max
  );
  
  RETURN v_result;
END;
$$;


--
-- TOC entry 744 (class 1255 OID 19067)
-- Name: distribute_acs_loot(uuid, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distribute_acs_loot(p_acs_id uuid, p_metal bigint, p_crystal bigint, p_deuterium bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_capacity bigint;
  v_participant RECORD;
  v_ratio numeric;
  v_metal_share bigint;
  v_crystal_share bigint;
  v_deut_share bigint;
BEGIN
  v_total_capacity := get_acs_total_cargo_capacity(p_acs_id);
  
  IF v_total_capacity <= 0 THEN
    RETURN;
  END IF;

  FOR v_participant IN
    SELECT ap.fleet_id, f.user_id,
      COALESCE(SUM(fs.quantity * st.cargo_capacity), 0) as capacity
    FROM acs_participants ap
    JOIN fleets f ON ap.fleet_id = f.id
    JOIN fleet_ships fs ON ap.fleet_id = fs.fleet_id
    JOIN ship_types st ON fs.ship_type_id = st.id
    WHERE ap.acs_id = p_acs_id
    GROUP BY ap.fleet_id, f.user_id
  LOOP
    v_ratio := v_participant.capacity::numeric / v_total_capacity::numeric;
    v_metal_share := FLOOR(p_metal * v_ratio)::bigint;
    v_crystal_share := FLOOR(p_crystal * v_ratio)::bigint;
    v_deut_share := FLOOR(p_deuterium * v_ratio)::bigint;
    
    UPDATE fleets 
    SET cargo_metal = COALESCE(cargo_metal, 0) + v_metal_share,
        cargo_crystal = COALESCE(cargo_crystal, 0) + v_crystal_share,
        cargo_deuterium = COALESCE(cargo_deuterium, 0) + v_deut_share
    WHERE id = v_participant.fleet_id;
  END LOOP;
END;
$$;


--
-- TOC entry 742 (class 1255 OID 19065)
-- Name: distribute_acs_ships_after_combat(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distribute_acs_ships_after_combat(p_acs_id uuid, p_remaining_ships jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_participant RECORD;
  v_ship_code text;
  v_original_total integer;
  v_remaining_total integer;
  v_participant_remaining integer;
  v_ratio numeric;
BEGIN
  FOR v_ship_code IN SELECT jsonb_object_keys(p_remaining_ships)
  LOOP
    v_remaining_total := COALESCE((p_remaining_ships->>v_ship_code)::integer, 0);
    
    SELECT COALESCE(SUM(fs.quantity), 0) INTO v_original_total
    FROM acs_participants ap
    JOIN fleet_ships fs ON ap.fleet_id = fs.fleet_id
    JOIN ship_types st ON fs.ship_type_id = st.id
    WHERE ap.acs_id = p_acs_id AND st.code = v_ship_code;
    
    IF v_original_total > 0 THEN
      v_ratio := v_remaining_total::numeric / v_original_total::numeric;
      
      FOR v_participant IN
        SELECT ap.fleet_id, fs.id as fleet_ship_id, fs.quantity
        FROM acs_participants ap
        JOIN fleet_ships fs ON ap.fleet_id = fs.fleet_id
        JOIN ship_types st ON fs.ship_type_id = st.id
        WHERE ap.acs_id = p_acs_id AND st.code = v_ship_code
      LOOP
        v_participant_remaining := FLOOR(v_participant.quantity * v_ratio)::integer;
        UPDATE fleet_ships SET quantity = v_participant_remaining WHERE id = v_participant.fleet_ship_id;
      END LOOP;
    END IF;
  END LOOP;
END;
$$;


--
-- TOC entry 1031 (class 1255 OID 21200)
-- Name: enforce_lunar_base_fields_max(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_lunar_base_fields_max() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lunar_base_id integer;
  v_planet_type text;
  v_expected_max integer;
BEGIN
  -- Solo actúa si esta fila corresponde a la Base Lunar.
  SELECT id INTO v_lunar_base_id FROM building_types WHERE code = 'lunar_base' LIMIT 1;
  IF v_lunar_base_id IS NULL OR NEW.building_type_id <> v_lunar_base_id THEN
    RETURN NEW;
  END IF;

  -- Solo en lunas.
  SELECT planet_type INTO v_planet_type FROM planets WHERE id = NEW.planet_id;
  IF v_planet_type IS DISTINCT FROM 'moon' THEN
    RETURN NEW;
  END IF;

  -- fields_max >= 1 + level*3. Nunca reduce (GREATEST).
  v_expected_max := 2 + COALESCE(NEW.level, 0) * 3;

  UPDATE planets
     SET fields_max = GREATEST(fields_max, v_expected_max)
   WHERE id = NEW.planet_id
     AND fields_max < v_expected_max;

  RETURN NEW;
END;
$$;


--
-- TOC entry 1097 (class 1255 OID 21561)
-- Name: enforce_shield_dome_per_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_shield_dome_per_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_acct integer;
  v_user_id uuid;
  v_def_name text;
BEGIN
  IF NEW.defense_type_id NOT IN (7, 8) THEN
    RETURN NEW;
  END IF;

  IF NEW.quantity <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT user_id INTO v_user_id FROM planets WHERE id = NEW.planet_id;

  SELECT COALESCE(SUM(pd.quantity), 0) INTO v_total_acct
  FROM planet_defenses pd
  JOIN planets pl ON pl.id = pd.planet_id
  WHERE pl.user_id = v_user_id
    AND pd.defense_type_id = NEW.defense_type_id
    AND pd.id IS DISTINCT FROM NEW.id;

  IF v_total_acct + NEW.quantity > 1 THEN
    SELECT name INTO v_def_name FROM defense_types WHERE id = NEW.defense_type_id;
    RAISE EXCEPTION 'Límite: solo 1 % por cuenta permitido. Ya tienes %.', v_def_name, v_total_acct;
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 1122 (class 1255 OID 21875)
-- Name: enforce_ship_blueprint_requirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_ship_blueprint_requirement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner_id uuid;
  v_blueprint_id bigint;
  v_ship_name text;
  v_needed integer;
  v_available integer;
  v_consumed integer;
  v_shipyard_level integer;
  v_validation jsonb;
BEGIN
  IF NEW.item_type <> 'ship' OR NEW.ship_type_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_needed := GREATEST(1, COALESCE(NEW.quantity, 1));

  SELECT p.user_id INTO v_owner_id
  FROM planets p
  WHERE p.id = NEW.planet_id;

  IF v_owner_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Siempre requiere Hangar nivel 1 minimo
  SELECT COALESCE(pb.level, 0)
    INTO v_shipyard_level
  FROM planet_buildings pb
  JOIN building_types bt ON bt.id = pb.building_type_id
  WHERE pb.planet_id = NEW.planet_id
    AND bt.code = 'shipyard'
  LIMIT 1;

  IF COALESCE(v_shipyard_level, 0) < 1 THEN
    RAISE EXCEPTION 'Necesitas Hangar nivel 1 para construir esta nave.'
      USING ERRCODE = 'P0001';
  END IF;

  -- Buscar si esta nave tiene plano asociado
  SELECT sb.id, st.name
    INTO v_blueprint_id, v_ship_name
  FROM ship_blueprints sb
  JOIN ship_types st ON st.id = sb.ship_type_id
  WHERE sb.ship_type_id = NEW.ship_type_id
    AND sb.is_active = true
  LIMIT 1;

  -- Si no tiene sistema de plano, no se altera el flujo normal
  IF v_blueprint_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*)::integer INTO v_available
  FROM user_ship_blueprints usb
  WHERE usb.user_id = v_owner_id
    AND usb.blueprint_id = v_blueprint_id;

  -- Si tiene planos suficientes, consumir y permitir bypass de requisitos
  IF v_available >= v_needed THEN
    WITH to_consume AS (
      SELECT usb.id
      FROM user_ship_blueprints usb
      WHERE usb.user_id = v_owner_id
        AND usb.blueprint_id = v_blueprint_id
      ORDER BY usb.acquired_at ASC, usb.id ASC
      LIMIT v_needed
      FOR UPDATE SKIP LOCKED
    )
    DELETE FROM user_ship_blueprints d
    USING to_consume tc
    WHERE d.id = tc.id;

    GET DIAGNOSTICS v_consumed = ROW_COUNT;

    IF v_consumed < v_needed THEN
      RAISE EXCEPTION 'No se pudieron reservar suficientes planos para %.', COALESCE(v_ship_name, 'la nave')
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
  END IF;

  -- Si no tiene planos suficientes, validar requisitos completos
  v_validation := validate_ship_requirements(NEW.planet_id, NEW.ship_type_id);
  IF NOT COALESCE((v_validation->>'valid')::boolean, false) THEN
    RAISE EXCEPTION 'No cumples los requisitos para construir % sin plano.', COALESCE(v_ship_name, 'esta nave')
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 747 (class 1255 OID 19070)
-- Name: ensure_all_queue_timers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_all_queue_timers() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_fixed_count integer := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Fix building queue timers for all user's planets
  WITH updated AS (
    UPDATE building_queue bq
    SET 
      start_time = COALESCE(bq.start_time, NOW()),
      end_time = COALESCE(bq.end_time, NOW() + (bq.build_time || ' seconds')::interval)
    FROM planets p
    WHERE bq.planet_id = p.id
      AND p.user_id = v_user_id
      AND bq.queue_position = 1
      AND (bq.start_time IS NULL OR bq.end_time IS NULL)
    RETURNING bq.id
  )
  SELECT COUNT(*) INTO v_fixed_count FROM updated;

  -- Fix shipyard queue timers for all user's planets
  WITH updated AS (
    UPDATE shipyard_queue sq
    SET 
      start_time = COALESCE(sq.start_time, NOW()),
      current_unit_end_time = COALESCE(sq.current_unit_end_time, NOW() + (sq.build_time_per_unit || ' seconds')::interval)
    FROM planets p
    WHERE sq.planet_id = p.id
      AND p.user_id = v_user_id
      AND sq.queue_position = 1
      AND (sq.start_time IS NULL OR sq.current_unit_end_time IS NULL)
    RETURNING sq.id
  )
  SELECT v_fixed_count + COUNT(*) INTO v_fixed_count FROM updated;

  RETURN jsonb_build_object('success', true, 'fixed_count', v_fixed_count);
END;
$$;


--
-- TOC entry 1118 (class 1255 OID 21813)
-- Name: equip_cosmetic(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equip_cosmetic(p_cosmetic_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_item cosmetic_items%ROWTYPE;
  v_user_cosmetic user_cosmetics%ROWTYPE;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_item FROM cosmetic_items WHERE id = p_cosmetic_id AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cosmético no encontrado');
  END IF;

  -- Verificar que lo tiene y no expiró
  SELECT * INTO v_user_cosmetic FROM user_cosmetics
  WHERE user_id = v_user_id AND cosmetic_id = p_cosmetic_id AND expires_at > now()
  ORDER BY purchased_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes este cosmético o expiró');
  END IF;

  -- Desequipar otros del mismo tipo
  UPDATE user_cosmetics uc
  SET equipped = false
  FROM cosmetic_items ci
  WHERE ci.id = uc.cosmetic_id
    AND uc.user_id = v_user_id
    AND ci.cosmetic_type = v_item.cosmetic_type
    AND uc.id != v_user_cosmetic.id;

  -- Equipar este
  UPDATE user_cosmetics SET equipped = true WHERE id = v_user_cosmetic.id;

  -- Actualizar columna en profiles
  IF v_item.cosmetic_type = 'title' THEN
    UPDATE profiles SET active_title = v_item.name_es, active_title_icon = v_item.icon WHERE id = v_user_id;
  ELSIF v_item.cosmetic_type = 'badge' THEN
    UPDATE profiles SET active_badge = v_item.icon WHERE id = v_user_id;
  ELSIF v_item.cosmetic_type = 'planet_effect' THEN
    UPDATE profiles SET active_planet_effect = v_item.code WHERE id = v_user_id;
  ELSIF v_item.cosmetic_type = 'hero_skin' THEN
    UPDATE profiles SET active_hero_skin = v_item.code WHERE id = v_user_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'message', v_item.name_es || ' equipado');
END;
$$;


--
-- TOC entry 1174 (class 1255 OID 22731)
-- Name: estimate_defense_power(integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
