CREATE FUNCTION public.estimate_defense_power(p_rocket_launcher integer DEFAULT 0, p_light_laser integer DEFAULT 0, p_heavy_laser integer DEFAULT 0, p_gauss_cannon integer DEFAULT 0, p_ion_cannon integer DEFAULT 0, p_plasma_turret integer DEFAULT 0) RETURNS bigint
