-- TOC entry 882 (class 1255 OID 20074)
-- Name: exec_sql_admin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exec_sql_admin(p_sql text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row_count int;
BEGIN
  EXECUTE p_sql;
  GET DIAGNOSTICS v_row_count = ROW_COUNT;
  
  RETURN jsonb_build_object(
    'success', true,
    'row_count', v_row_count
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', SQLERRM
    );
END;
$$;


--
-- TOC entry 996 (class 1255 OID 20832)
-- Name: execute_lottery_draw(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_lottery_draw(p_draw_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
  v_draw record;
  v_winning integer[];
  v_num integer;
  v_ticket record;
  v_match_count integer;
  v_prize_3match integer;
  v_prize_2match integer;
  v_total_minor_prizes numeric := 0;
  v_jackpot_winners integer := 0;
  v_jackpot_per_winner numeric := 0;
  v_remaining_jackpot numeric := 0;
  v_total_jackpot numeric := 0;
  v_jackpot_after_minors numeric := 0;
  v_winners_3 integer := 0;
  v_winners_2 integer := 0;
  v_next_draw_id uuid;
  -- Telegram notification vars
  v_supabase_url text;
  v_service_key text;
  v_jackpot_names text[];
  v_names_3 text[];
  v_names_2 text[];
  v_winner_username text;
  v_request_id bigint;
  -- In-game message vars
  v_msg_subject text;
  v_msg_body text;
BEGIN
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = auth.uid();
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  IF p_draw_id IS NOT NULL THEN
    SELECT * INTO v_draw FROM lottery_draws WHERE id = p_draw_id AND status IN ('open', 'closed') FOR UPDATE;
  ELSE
    SELECT * INTO v_draw FROM lottery_draws WHERE status = 'open' ORDER BY closes_at ASC LIMIT 1 FOR UPDATE;
  END IF;

  IF v_draw.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No hay sorteo pendiente');
  END IF;

  -- Generate 4 unique winning numbers from 1-30
  v_winning := ARRAY[]::integer[];
  WHILE array_length(v_winning, 1) IS NULL OR array_length(v_winning, 1) < 4 LOOP
    v_num := FLOOR(random() * 30 + 1)::integer;
    IF NOT v_num = ANY(v_winning) THEN
      v_winning := v_winning || v_num;
    END IF;
  END LOOP;
  SELECT ARRAY(SELECT unnest(v_winning) ORDER BY 1) INTO v_winning;

  -- Read prize config from game_settings
  SELECT COALESCE(value::integer, 500) INTO v_prize_3match FROM game_settings WHERE key = 'lottery_3match_prize';
  SELECT COALESCE(value::integer, 50)  INTO v_prize_2match FROM game_settings WHERE key = 'lottery_2match_prize';
  IF v_prize_3match IS NULL THEN v_prize_3match := 500; END IF;
  IF v_prize_2match IS NULL THEN v_prize_2match := 50;  END IF;

  v_total_jackpot := COALESCE(v_draw.accumulated_jackpot, 0) + COALESCE(v_draw.prize_pool, 0);

  PERFORM _internal_set_fxu_context();

  -- Initialize winner name arrays
  v_jackpot_names := ARRAY[]::text[];
  v_names_3 := ARRAY[]::text[];
  v_names_2 := ARRAY[]::text[];

  -- ================================================================
  -- PHASE 1: Score all tickets and count winners (no payments yet)
  -- ================================================================
  FOR v_ticket IN SELECT * FROM lottery_tickets WHERE draw_id = v_draw.id LOOP
    SELECT COUNT(*) INTO v_match_count
    FROM unnest(v_ticket.numbers) n WHERE n = ANY(v_winning);

    UPDATE lottery_tickets SET matches = v_match_count WHERE id = v_ticket.id;

    IF v_match_count = 4 THEN
      v_jackpot_winners := v_jackpot_winners + 1;
    ELSIF v_match_count = 3 THEN
      v_winners_3 := v_winners_3 + 1;
      v_total_minor_prizes := v_total_minor_prizes + v_prize_3match;
    ELSIF v_match_count = 2 THEN
      v_winners_2 := v_winners_2 + 1;
      v_total_minor_prizes := v_total_minor_prizes + v_prize_2match;
    END IF;
  END LOOP;

  -- ================================================================
  -- PHASE 2: Cap minor prizes to available jackpot (prevent inflation)
  -- ================================================================
  IF v_total_minor_prizes > v_total_jackpot THEN
    v_total_minor_prizes := v_total_jackpot;
  END IF;

  -- Jackpot available for 4/4 winners AFTER paying minor prizes
  v_jackpot_after_minors := v_total_jackpot - v_total_minor_prizes;

  -- ================================================================
  -- PHASE 3: Pay minor prize winners (2 and 3 match)
  -- ================================================================
  -- Pay 3-match winners
  IF v_winners_3 > 0 THEN
    FOR v_ticket IN SELECT lt.*, p.username
      FROM lottery_tickets lt
      JOIN profiles p ON p.id = lt.user_id
      WHERE lt.draw_id = v_draw.id AND lt.matches = 3
    LOOP
      UPDATE profiles SET fxu_balance = fxu_balance + v_prize_3match WHERE id = v_ticket.user_id;
      UPDATE lottery_tickets SET prize = v_prize_3match WHERE id = v_ticket.id;
      INSERT INTO lottery_winners (draw_id, user_id, matches, prize, numbers, winning_numbers)
      VALUES (v_draw.id, v_ticket.user_id, 3, v_prize_3match, v_ticket.numbers, v_winning);

      v_winner_username := COALESCE(v_ticket.username, 'Jugador');
      v_names_3 := v_names_3 || v_winner_username;

      -- Send in-game notification
      INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
      VALUES (
        NULL,
        v_ticket.user_id,
        '🎰 ¡Ganaste en la Lotería Galáctica!',
        format('¡Felicidades! En el Sorteo #%s acertaste 3 de 4 coordenadas.

🎯 Tus números: [%s]
⭐ Números ganadores: [%s]

💰 Premio: %s FXU (acreditados a tu cuenta)

¡Sigue jugando para ganar el JACKPOT!',
          v_draw.draw_number,
          array_to_string(v_ticket.numbers, ', '),
          array_to_string(v_winning, ', '),
          v_prize_3match),
        'system'
      );
    END LOOP;
  END IF;

  -- Pay 2-match winners
  IF v_winners_2 > 0 THEN
    FOR v_ticket IN SELECT lt.*, p.username
      FROM lottery_tickets lt
      JOIN profiles p ON p.id = lt.user_id
      WHERE lt.draw_id = v_draw.id AND lt.matches = 2
    LOOP
      UPDATE profiles SET fxu_balance = fxu_balance + v_prize_2match WHERE id = v_ticket.user_id;
      UPDATE lottery_tickets SET prize = v_prize_2match WHERE id = v_ticket.id;
      INSERT INTO lottery_winners (draw_id, user_id, matches, prize, numbers, winning_numbers)
      VALUES (v_draw.id, v_ticket.user_id, 2, v_prize_2match, v_ticket.numbers, v_winning);

      v_winner_username := COALESCE(v_ticket.username, 'Jugador');
      v_names_2 := v_names_2 || v_winner_username;

      -- Send in-game notification
      INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
      VALUES (
        NULL,
        v_ticket.user_id,
        '🎰 ¡Ganaste en la Lotería Galáctica!',
        format('¡Felicidades! En el Sorteo #%s acertaste 2 de 4 coordenadas.

🎯 Tus números: [%s]
⭐ Números ganadores: [%s]

💰 Premio: %s FXU (acreditados a tu cuenta)

¡Sigue jugando para ganar el JACKPOT!',
          v_draw.draw_number,
          array_to_string(v_ticket.numbers, ', '),
          array_to_string(v_winning, ', '),
          v_prize_2match),
        'system'
      );
    END LOOP;
  END IF;

  -- ================================================================
  -- PHASE 4: Pay jackpot winners (4/4 match) from remaining pool
  -- ================================================================
  IF v_jackpot_winners > 0 THEN
    v_jackpot_per_winner := FLOOR(v_jackpot_after_minors / v_jackpot_winners);
    v_remaining_jackpot := 0;

    FOR v_ticket IN SELECT lt.*, p.username
      FROM lottery_tickets lt
      JOIN profiles p ON p.id = lt.user_id
      WHERE lt.draw_id = v_draw.id AND lt.matches = 4
    LOOP
      UPDATE profiles SET fxu_balance = fxu_balance + v_jackpot_per_winner WHERE id = v_ticket.user_id;
      UPDATE lottery_tickets SET prize = v_jackpot_per_winner WHERE id = v_ticket.id;
      INSERT INTO lottery_winners (draw_id, user_id, matches, prize, numbers, winning_numbers)
      VALUES (v_draw.id, v_ticket.user_id, 4, v_jackpot_per_winner, v_ticket.numbers, v_winning);

      v_winner_username := COALESCE(v_ticket.username, 'Jugador');
      v_jackpot_names := v_jackpot_names || v_winner_username;

      -- Send in-game notification for JACKPOT winner
      INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
      VALUES (
        NULL,
        v_ticket.user_id,
        '🏆🎰 ¡¡¡JACKPOT!!! ¡Ganaste el premio mayor!',
        format('🎉🎉🎉 ¡¡¡INCREÍBLE!!! 🎉🎉🎉

¡Acertaste las 4 Coordenadas Galácticas en el Sorteo #%s!

🎯 Tus números: [%s]
⭐ Números ganadores: [%s]

💰💰💰 JACKPOT: %s FXU 💰💰💰

El premio ha sido acreditado a tu cuenta. ¡Eres leyenda!',
          v_draw.draw_number,
          array_to_string(v_ticket.numbers, ', '),
          array_to_string(v_winning, ', '),
          v_jackpot_per_winner),
        'system'
      );
    END LOOP;

    UPDATE lottery_draws SET
      jackpot_winner_id = (SELECT user_id FROM lottery_tickets WHERE draw_id = v_draw.id AND matches = 4 LIMIT 1),
      jackpot_amount = v_jackpot_per_winner * v_jackpot_winners
    WHERE id = v_draw.id;
  ELSE
    -- No jackpot winner: rollover remaining (total - minor prizes paid)
    v_remaining_jackpot := v_jackpot_after_minors;
  END IF;

  -- ================================================================
  -- PHASE 5: Complete draw and create next one
  -- ================================================================
  UPDATE lottery_draws SET
    status = 'completed',
    winning_numbers = v_winning,
    drawn_at = now()
  WHERE id = v_draw.id;

  -- Next draw closes next Sunday 23:59 UTC (max 7 days)
  INSERT INTO lottery_draws (status, opens_at, closes_at, accumulated_jackpot)
  VALUES (
    'open',
    now(),
    (date_trunc('week', now() + interval '1 day') + interval '6 days 23 hours 59 minutes')::timestamptz,
    v_remaining_jackpot
  ) RETURNING id INTO v_next_draw_id;

  -- ================================================================
  -- PHASE 6: Telegram group notification (non-blocking, best-effort)
  -- ================================================================
  BEGIN
    v_supabase_url := current_setting('app.settings.supabase_url', true);
    v_service_key  := current_setting('app.settings.service_role_key', true);

    IF v_supabase_url IS NOT NULL AND v_service_key IS NOT NULL THEN
      SELECT net.http_post(
        url     := v_supabase_url || '/functions/v1/notify-lottery-result',
        body    := jsonb_build_object(
          'draw_number',          v_draw.draw_number,
          'winning_numbers',      v_winning,
          'total_tickets',        COALESCE(v_draw.total_tickets, 0),
          'total_pool',           COALESCE(v_draw.total_pool, 0),
          'jackpot',              v_total_jackpot,
          'jackpot_winners',      v_jackpot_winners,
          'jackpot_per_winner',   v_jackpot_per_winner,
          'winners_3match',       v_winners_3,
          'winners_2match',       v_winners_2,
          'minor_prizes_paid',    v_total_minor_prizes,
          'accumulated_to_next',  v_remaining_jackpot,
          'prize_3match',         v_prize_3match,
          'prize_2match',         v_prize_2match,
          'jackpot_winner_names', v_jackpot_names,
          'winners_3_names',      v_names_3,
          'winners_2_names',      v_names_2
        ),
        headers := jsonb_build_object(
          'Content-Type',  'application/json',
          'Authorization', 'Bearer ' || v_service_key
        )
      ) INTO v_request_id;
    ELSE
      RAISE NOTICE 'Lottery Telegram: missing supabase_url or service_role_key config';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE NOTICE 'Lottery Telegram notification error: %', SQLERRM;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'draw_number', v_draw.draw_number,
    'winning_numbers', v_winning,
    'total_tickets', v_draw.total_tickets,
    'total_pool', v_draw.total_pool,
    'jackpot', v_total_jackpot,
    'jackpot_winners', v_jackpot_winners,
    'jackpot_per_winner', v_jackpot_per_winner,
    'winners_3match', v_winners_3,
    'winners_2match', v_winners_2,
    'minor_prizes_paid', v_total_minor_prizes,
    'accumulated_to_next', v_remaining_jackpot,
    'next_draw_id', v_next_draw_id
  );
END;
$$;


--
-- TOC entry 1096 (class 1255 OID 21556)
-- Name: expire_old_market_listings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_old_market_listings() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_listing RECORD;
  v_count integer := 0;
BEGIN
  FOR v_listing IN
    SELECT id, seller_id, item_code, quantity, listing_type
    FROM market_listings
    WHERE status = 'active'
      AND created_at < NOW() - INTERVAL '24 hours'
  LOOP
    UPDATE market_listings
    SET status = 'cancelled', updated_at = now()
    WHERE id = v_listing.id;

    IF v_listing.listing_type = 'dark_matter' THEN
      UPDATE profiles
      SET dark_matter = COALESCE(dark_matter, 0) + v_listing.quantity
      WHERE id = v_listing.seller_id;
    END IF;

    INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
    VALUES (
      v_listing.seller_id,
      v_listing.seller_id,
      'Oferta expirada (24h)',
      'Tu oferta de ' || v_listing.quantity || ' ' || v_listing.item_code || ' ha expirado tras 24 horas en el mercado.',
      'system'
    );

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- TOC entry 695 (class 1255 OID 18898)
-- Name: fail_withdrawal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_withdrawal(p_tx_id uuid, p_error_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tx wallet_transactions%ROWTYPE;
  v_fee_amount numeric;
  v_admin_id uuid;
  v_role text;
BEGIN
  v_role := current_setting('role', true);
  IF v_role IS DISTINCT FROM 'service_role' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Only server can fail withdrawals');
  END IF;

  SELECT * INTO v_tx FROM wallet_transactions WHERE id = p_tx_id;

  IF v_tx.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction not found');
  END IF;

  IF v_tx.tx_type != 'withdrawal' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction is not a withdrawal');
  END IF;

  IF v_tx.status NOT IN ('pending', 'processing') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction already processed');
  END IF;

  v_fee_amount := v_tx.fxu_amount - v_tx.amount;

  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);

  UPDATE profiles 
  SET fxu_balance = fxu_balance + v_tx.fxu_amount,
      updated_at = now()
  WHERE id = v_tx.user_id;

  IF v_fee_amount > 0 THEN
    SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
    IF v_admin_id IS NOT NULL THEN
      UPDATE profiles 
      SET fxu_balance = GREATEST(fxu_balance - v_fee_amount, 0),
          updated_at = now()
      WHERE id = v_admin_id;
    END IF;
  END IF;

  UPDATE wallet_transactions
  SET status = 'failed',
      error_message = p_error_message,
      updated_at = now()
  WHERE id = p_tx_id;

  RETURN jsonb_build_object(
    'success', true,
    'refunded_amount', v_tx.fxu_amount,
    'user_id', v_tx.user_id
  );
END;
$$;


--
-- TOC entry 787 (class 1255 OID 19308)
-- Name: fail_withdrawal_usdt(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_withdrawal_usdt(p_tx_id uuid, p_error_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tx wallet_transactions%ROWTYPE;
BEGIN
  SELECT * INTO v_tx FROM wallet_transactions WHERE id = p_tx_id;
  
  IF v_tx.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction not found');
  END IF;

  IF v_tx.token_type != 'USDT' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not a USDT transaction');
  END IF;

  IF v_tx.status NOT IN ('pending', 'processing') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot fail transaction in status: ' || v_tx.status);
  END IF;

  -- Refund USDT to user
  UPDATE profiles 
  SET usdt_balance = usdt_balance + v_tx.fxu_amount,
      updated_at = now()
  WHERE id = v_tx.user_id;

  -- Mark transaction as failed
  UPDATE wallet_transactions
  SET status = 'failed',
      error_message = p_error_message,
      updated_at = now()
  WHERE id = p_tx_id;

  RETURN jsonb_build_object('success', true, 'refunded', v_tx.fxu_amount);
END;
$$;


--
-- TOC entry 844 (class 1255 OID 19958)
-- Name: fleet_calc_distance(integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fleet_calc_distance(p_origin_galaxy integer, p_origin_system integer, p_origin_position integer, p_target_galaxy integer, p_target_system integer, p_target_position integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_origin_galaxy != p_target_galaxy THEN
    RETURN ABS(p_origin_galaxy - p_target_galaxy) * 20000;
  END IF;
  
  IF p_origin_system != p_target_system THEN
    RETURN ABS(p_origin_system - p_target_system) * 95 + 2700;
  END IF;
  
  IF p_origin_position != p_target_position THEN
    RETURN ABS(p_origin_position - p_target_position) * 5 + 1000;
  END IF;
  
  RETURN 5;
END;
$$;


--
-- TOC entry 847 (class 1255 OID 19961)
-- Name: fleet_calc_flight_time(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fleet_calc_flight_time(p_distance integer, p_slowest_speed integer, p_speed_percent integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fleet_speed numeric;
  v_effective_speed numeric;
  v_flight_time int;
BEGIN
  IF p_slowest_speed <= 0 THEN
    RETURN 0;
  END IF;
  
  v_fleet_speed := get_fleet_speed();
  v_effective_speed := p_slowest_speed * (p_speed_percent::numeric / 100);
  
  v_flight_time := GREATEST(
    10,
    ROUND(
      (35000::numeric / (p_speed_percent::numeric / 100) * 
       SQRT(p_distance::numeric * 10 / v_effective_speed) + 10) / v_fleet_speed
    )
  );
  
  RETURN v_flight_time;
END;
$$;


--
-- TOC entry 953 (class 1255 OID 20468)
-- Name: fleet_calc_flight_time(integer, integer, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fleet_calc_flight_time(p_distance integer, p_slowest_speed integer, p_speed_percent integer, p_admiral_bonus numeric DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fleet_speed numeric;
  v_effective_speed numeric;
  v_flight_time int;
BEGIN
  IF p_slowest_speed <= 0 THEN
    RETURN 0;
  END IF;
  
  v_fleet_speed := get_fleet_speed();
  v_effective_speed := p_slowest_speed * (p_speed_percent::numeric / 100);
  
  v_flight_time := GREATEST(
    10,
    ROUND(
      (35000::numeric / (p_speed_percent::numeric / 100) * 
       SQRT(p_distance::numeric * 10 / v_effective_speed) + 10) / v_fleet_speed
    )
  );
  
  -- Apply admiral bonus: reduce flight time by the bonus percentage
  -- e.g. p_admiral_bonus = 0.2 means 20% faster → divide by 1.2
  IF p_admiral_bonus > 0 THEN
    v_flight_time := GREATEST(10, ROUND(v_flight_time::numeric / (1 + p_admiral_bonus)));
  END IF;
  
  RETURN v_flight_time;
END;
$$;


--
-- TOC entry 848 (class 1255 OID 19962)
-- Name: fleet_calc_fuel(jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fleet_calc_fuel(p_fleet_ships jsonb, p_distance integer, p_speed_percent integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ship record;
  v_ship_type record;
  v_total_fuel bigint := 0;
  v_ship_fuel numeric;
  v_distance_factor numeric;
  v_speed_factor numeric;
BEGIN
  v_distance_factor := p_distance::numeric / 35000;
  v_speed_factor := (p_speed_percent::numeric / 100) + 1;
  
  FOR v_ship IN SELECT * FROM jsonb_to_recordset(p_fleet_ships) AS x(ship_type_id int, quantity int)
  LOOP
    IF v_ship.quantity > 0 THEN
      SELECT * INTO v_ship_type FROM ship_types WHERE id = v_ship.ship_type_id;
      
      IF v_ship_type IS NOT NULL THEN
        v_ship_fuel := v_ship_type.fuel_consumption * v_ship.quantity * v_distance_factor * v_speed_factor;
        v_total_fuel := v_total_fuel + CEIL(v_ship_fuel);
      END IF;
    END IF;
  END LOOP;
  
  RETURN v_total_fuel;
END;
$$;


--
-- TOC entry 845 (class 1255 OID 19959)
-- Name: fleet_calc_ship_speed(text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fleet_calc_ship_speed(p_ship_code text, p_base_speed integer, p_combustion_level integer, p_impulse_level integer, p_hyperspace_level integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bonus numeric := 0;
BEGIN
  IF p_base_speed = 0 OR p_base_speed IS NULL THEN
    RETURN 0;
  END IF;

  IF p_ship_code IN ('small_cargo', 'large_cargo', 'light_fighter', 'espionage_probe', 'recycler', 'mega_recycler', 'large_frigate') THEN
    v_bonus := p_combustion_level * 0.10;
  ELSIF p_ship_code IN ('heavy_fighter', 'cruiser', 'battleship', 'battlecruiser', 'bomber', 'colony_ship') THEN
    v_bonus := p_impulse_level * 0.20;
  ELSIF p_ship_code IN ('destroyer', 'deathstar', 'pathfinder', 'star_destroyer', 'black_moon', 'falco_x_clasica', 'nova', 'destruccion_masiva') THEN
    v_bonus := p_hyperspace_level * 0.30;
  END IF;

  RETURN FLOOR(p_base_speed * (1 + v_bonus));
END;
$$;


--
-- TOC entry 846 (class 1255 OID 19960)
-- Name: fleet_calc_slowest_speed(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fleet_calc_slowest_speed(p_fleet_ships jsonb, p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ship record;
  v_ship_type record;
  v_tech_combustion int := 0;
  v_tech_impulse int := 0;
  v_tech_hyperspace int := 0;
  v_speed int;
  v_slowest int := 999999999;
BEGIN
  SELECT COALESCE(
    (SELECT level FROM user_technologies ut 
     JOIN technology_types tt ON ut.technology_type_id = tt.id 
     WHERE ut.user_id = p_user_id AND tt.code = 'combustion_drive'), 0
  ) INTO v_tech_combustion;
  
  SELECT COALESCE(
    (SELECT level FROM user_technologies ut 
     JOIN technology_types tt ON ut.technology_type_id = tt.id 
     WHERE ut.user_id = p_user_id AND tt.code = 'impulse_drive'), 0
  ) INTO v_tech_impulse;
  
  SELECT COALESCE(
    (SELECT level FROM user_technologies ut 
     JOIN technology_types tt ON ut.technology_type_id = tt.id 
     WHERE ut.user_id = p_user_id AND tt.code = 'hyperspace_drive'), 0
  ) INTO v_tech_hyperspace;

  FOR v_ship IN SELECT * FROM jsonb_to_recordset(p_fleet_ships) AS x(ship_type_id int, quantity int)
  LOOP
    IF v_ship.quantity > 0 THEN
      SELECT * INTO v_ship_type FROM ship_types WHERE id = v_ship.ship_type_id;
      
      IF v_ship_type.base_speed > 0 THEN
        v_speed := fleet_calc_ship_speed(
          v_ship_type.code,
          v_ship_type.base_speed,
          v_tech_combustion,
          v_tech_impulse,
          v_tech_hyperspace
        );
        
        IF v_speed < v_slowest THEN
          v_slowest := v_speed;
        END IF;
      END IF;
    END IF;
  END LOOP;
  
  IF v_slowest = 999999999 THEN
    RETURN 0;
  END IF;
  
  RETURN v_slowest;
END;
$$;


--
-- TOC entry 689 (class 1255 OID 18885)
-- Name: format_unit_report(jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.format_unit_report(p_initial_units jsonb, p_remaining_units jsonb, p_side text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_report text := '';
  v_unit_data jsonb;
  v_initial_qty integer;
  v_remaining_qty integer;
  v_unit_name text;
  v_unit_code text;
  v_unit_fleet_id text;
  v_idx integer := 0;
BEGIN
  IF p_initial_units IS NULL OR jsonb_array_length(p_initial_units) = 0 THEN
    RETURN '  Ninguna';
  END IF;

  FOR v_unit_data IN SELECT * FROM jsonb_array_elements(p_initial_units)
  LOOP
    v_unit_name := v_unit_data->>'name';
    v_unit_code := v_unit_data->>'code';
    v_unit_fleet_id := v_unit_data->>'fleet_id';
    v_initial_qty := COALESCE((v_unit_data->>'initial_quantity')::integer, (v_unit_data->>'quantity')::integer, 0);

    IF v_initial_qty <= 0 THEN
      v_idx := v_idx + 1;
      CONTINUE;
    END IF;

    v_remaining_qty := 0;

    IF p_remaining_units IS NOT NULL THEN
      -- Method 1: Try index-based matching first (most reliable for ACS)
      -- Both initial and remaining arrays maintain the same order from combat simulation
      IF v_idx < jsonb_array_length(p_remaining_units) THEN
        DECLARE
          v_remaining_at_idx jsonb;
          v_remaining_code text;
        BEGIN
          v_remaining_at_idx := p_remaining_units->v_idx;
          v_remaining_code := v_remaining_at_idx->>'code';
          
          -- Verify the code matches at this index (sanity check)
          IF v_remaining_code = v_unit_code THEN
            v_remaining_qty := COALESCE((v_remaining_at_idx->>'quantity')::integer, 0);
          ELSE
            -- Fallback: code+fleet_id matching for ACS, then code-only
            IF v_unit_fleet_id IS NOT NULL THEN
              SELECT (r_unit->>'quantity')::integer INTO v_remaining_qty
              FROM jsonb_array_elements(p_remaining_units) AS r_unit
              WHERE r_unit->>'code' = v_unit_code
                AND r_unit->>'fleet_id' = v_unit_fleet_id
              LIMIT 1;
            END IF;
            
            IF v_remaining_qty IS NULL OR v_remaining_qty = 0 THEN
              SELECT (r_unit->>'quantity')::integer INTO v_remaining_qty
              FROM jsonb_array_elements(p_remaining_units) AS r_unit
              WHERE r_unit->>'code' = v_unit_code
              LIMIT 1;
            END IF;
          END IF;
        END;
      ELSE
        -- Array sizes differ, use fleet_id+code or code-only fallback
        IF v_unit_fleet_id IS NOT NULL THEN
          SELECT (r_unit->>'quantity')::integer INTO v_remaining_qty
          FROM jsonb_array_elements(p_remaining_units) AS r_unit
          WHERE r_unit->>'code' = v_unit_code
            AND r_unit->>'fleet_id' = v_unit_fleet_id
          LIMIT 1;
        END IF;
        
        IF v_remaining_qty IS NULL THEN
          SELECT (r_unit->>'quantity')::integer INTO v_remaining_qty
          FROM jsonb_array_elements(p_remaining_units) AS r_unit
          WHERE r_unit->>'code' = v_unit_code
          LIMIT 1;
        END IF;
      END IF;
    END IF;

    v_remaining_qty := COALESCE(v_remaining_qty, 0);

    IF v_report != '' THEN
      v_report := v_report || E'\n';
    END IF;

    IF v_remaining_qty = 0 THEN
      v_report := v_report || format('  %s: %s -> 0 (-%s destruidas)',
        v_unit_name, v_initial_qty, v_initial_qty);
    ELSIF v_remaining_qty < v_initial_qty THEN
      v_report := v_report || format('  %s: %s -> %s (-%s)',
        v_unit_name, v_initial_qty, v_remaining_qty, v_initial_qty - v_remaining_qty);
    ELSE
      v_report := v_report || format('  %s: %s (sin perdidas)',
        v_unit_name, v_initial_qty);
    END IF;

    v_idx := v_idx + 1;
  END LOOP;

  IF v_report = '' THEN
    v_report := '  Ninguna';
  END IF;

  RETURN v_report;
END;
$$;


