--
-- TOC entry 779 (class 1255 OID 19288)
-- Name: full_reconnect_sync(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.full_reconnect_sync(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
DECLARE
  v_user_id uuid;
  v_planet RECORD;
  v_resources jsonb;
  v_buildings_completed int := 0;
  v_ships_completed int := 0;
  v_build_result jsonb;
  v_ship_result jsonb;
BEGIN
  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Planet not found');
  END IF;

  IF v_planet.user_id != auth.uid() THEN
    RETURN jsonb_build_object('error', 'Unauthorized');
  END IF;

  v_user_id := v_planet.user_id;

  BEGIN
    UPDATE user_technologies
    SET
      level = level + 1,
      is_researching = false,
      research_end_time = NULL,
      research_planet_id = NULL,
      updated_at = now()
    WHERE user_id = v_user_id
    AND is_researching = true
    AND research_end_time IS NOT NULL
    AND research_end_time <= now() + interval '2 seconds';

    IF FOUND THEN
      PERFORM update_user_points(v_user_id);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  BEGIN
    v_build_result := process_building_queue_internal(p_planet_id, v_user_id);
    IF v_build_result IS NOT NULL AND (v_build_result->>'success')::boolean THEN
      v_buildings_completed := COALESCE((v_build_result->>'completed_count')::int, 0);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  BEGIN
    v_ship_result := process_shipyard_queue_internal(p_planet_id, v_user_id);
    IF v_ship_result IS NOT NULL AND (v_ship_result->>'success')::boolean THEN
      v_ships_completed := COALESCE((v_ship_result->>'completed_units')::int, 0);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  v_resources := calculate_planet_resources(p_planet_id);

  IF NOT (v_resources ? 'error') THEN
    UPDATE planet_resources
    SET
      metal = (v_resources->>'metal')::numeric,
      crystal = (v_resources->>'crystal')::numeric,
      deuterium = (v_resources->>'deuterium')::numeric,
      metal_per_hour = (v_resources->>'metal_per_hour')::numeric,
      crystal_per_hour = (v_resources->>'crystal_per_hour')::numeric,
      deuterium_per_hour = (v_resources->>'deuterium_per_hour')::numeric,
      metal_storage = (v_resources->>'metal_storage')::numeric,
      crystal_storage = (v_resources->>'crystal_storage')::numeric,
      deuterium_storage = (v_resources->>'deuterium_storage')::numeric,
      energy_used = (v_resources->>'energy_used')::numeric,
      energy_max = (v_resources->>'energy_max')::numeric,
      last_update = now()
    WHERE planet_id = p_planet_id;
  END IF;

  IF v_buildings_completed > 0 OR v_ships_completed > 0 THEN
    PERFORM update_user_points(v_user_id);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'buildings_completed', v_buildings_completed,
    'ships_completed', v_ships_completed,
    'resources', v_resources,
    'synced_at', now()
  );
END;
$$;


--
-- TOC entry 782 (class 1255 OID 19291)
-- Name: full_reconnect_sync_all_planets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.full_reconnect_sync_all_planets() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_planet RECORD;
  v_result jsonb;
  v_total_buildings_completed int := 0;
  v_total_ships_completed int := 0;
  v_planets_synced int := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Not authenticated');
  END IF;

  -- Step 1: Process research completion (user-level, only one at a time)
  BEGIN
    UPDATE user_technologies
    SET 
      level = level + 1,
      is_researching = false,
      research_end_time = NULL,
      research_planet_id = NULL,
      updated_at = now()
    WHERE user_id = v_user_id
      AND is_researching = true
      AND research_end_time IS NOT NULL
      AND research_end_time <= now() + interval '2 seconds';

    IF FOUND THEN
      PERFORM update_user_points(v_user_id);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- Step 2: Process ALL planets
  FOR v_planet IN 
    SELECT id FROM planets WHERE user_id = v_user_id
  LOOP
    -- Process building queue
    BEGIN
      v_result := process_building_queue_internal(v_planet.id, v_user_id);
      IF v_result IS NOT NULL AND (v_result->>'success')::boolean THEN
        v_total_buildings_completed := v_total_buildings_completed + COALESCE((v_result->>'completed_count')::int, 0);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    -- Process shipyard queue
    BEGIN
      v_result := process_shipyard_queue_internal(v_planet.id, v_user_id);
      IF v_result IS NOT NULL AND (v_result->>'success')::boolean THEN
        v_total_ships_completed := v_total_ships_completed + COALESCE((v_result->>'completed_units')::int, 0);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    -- Calculate and sync resources for this planet
    BEGIN
      PERFORM calculate_and_sync_resources_internal(v_planet.id, v_user_id);
      v_planets_synced := v_planets_synced + 1;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;

  -- Update user points if anything completed
  IF v_total_buildings_completed > 0 OR v_total_ships_completed > 0 THEN
    PERFORM update_user_points(v_user_id);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'buildings_completed', v_total_buildings_completed,
    'ships_completed', v_total_ships_completed,
    'planets_synced', v_planets_synced,
    'synced_at', now()
  );
END;
$$;


--
-- TOC entry 905 (class 1255 OID 20189)
-- Name: galaxy_navigate(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.galaxy_navigate(p_planet_id uuid, p_target_galaxy integer, p_target_system integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_planet record;
  v_resources record;
  v_cost numeric;
  v_cost_setting text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id AND user_id = v_user_id;
  IF v_planet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not found');
  END IF;

  IF v_planet.galaxy = p_target_galaxy AND v_planet.solar_system = p_target_system THEN
    RETURN jsonb_build_object('success', true, 'cost', 0, 'free', true);
  END IF;

  SELECT value INTO v_cost_setting FROM game_settings WHERE key = 'galaxy_navigation_cost';
  v_cost := COALESCE(v_cost_setting::numeric, 10);

  IF v_cost <= 0 THEN
    RETURN jsonb_build_object('success', true, 'cost', 0, 'free', true);
  END IF;

  PERFORM calculate_and_sync_resources(p_planet_id);

  SELECT * INTO v_resources FROM planet_resources WHERE planet_id = p_planet_id;
  IF v_resources IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Resources not found');
  END IF;

  IF v_resources.deuterium < v_cost THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Insufficient deuterium',
      'required', v_cost,
      'available', v_resources.deuterium
    );
  END IF;

  UPDATE planet_resources
  SET deuterium = deuterium - v_cost,
      last_update = now()
  WHERE planet_id = p_planet_id;

  RETURN jsonb_build_object(
    'success', true,
    'cost', v_cost,
    'remaining_deuterium', v_resources.deuterium - v_cost
  );
END;
$$;


--
-- TOC entry 1014 (class 1255 OID 20911)
-- Name: generate_espionage_report(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_espionage_report(p_attacker_id uuid, p_target_planet_id uuid, p_target_user_id uuid, p_probe_count integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  target_resources RECORD;
  target_buildings JSONB;
  target_ships JSONB;
  target_defenses JSONB;
  target_techs JSONB;
  target_planet RECORD;
  report_data JSONB;
  v_attacker_spy_level integer;
  v_defender_counter_spy_level integer;
  v_tech_difference numeric;
  v_effective_tech_diff numeric;
  v_detection_chance numeric;
  v_detected boolean := false;
  v_visibility_level integer;
  v_probe_bonus numeric;
  v_allied_ships JSONB;
  v_allied_fleet RECORD;
  v_ally_username text;
  v_ally_ships JSONB;
  v_has_technocrat boolean := false;
  -- New: destruction
  v_destruction_chance numeric;
  v_probes_destroyed boolean := false;
BEGIN
  SELECT * INTO target_planet FROM planets WHERE id = p_target_planet_id;

  SELECT COALESCE(ut.level, 0) INTO v_attacker_spy_level
  FROM user_technologies ut
  JOIN technology_types tt ON ut.technology_type_id = tt.id
  WHERE ut.user_id = p_attacker_id AND tt.code = 'espionage_tech';
  v_attacker_spy_level := COALESCE(v_attacker_spy_level, 0);

  -- FIX: aplicar +2 niveles efectivos de espionaje si Tecnócrata está activo
  v_has_technocrat := has_active_officer(p_attacker_id, 'technocrat');
  IF v_has_technocrat THEN
    v_attacker_spy_level := v_attacker_spy_level + 2;
  END IF;

  SELECT COALESCE(ut.level, 0) INTO v_defender_counter_spy_level
  FROM user_technologies ut
  JOIN technology_types tt ON ut.technology_type_id = tt.id
  WHERE ut.user_id = p_target_user_id AND tt.code = 'espionage_tech';
  v_defender_counter_spy_level := COALESCE(v_defender_counter_spy_level, 0);

  v_tech_difference := v_attacker_spy_level - v_defender_counter_spy_level;

  -- Cada 5 sondas = +1 nivel efectivo
  v_probe_bonus := FLOOR(COALESCE(p_probe_count, 1)::numeric / 5.0);
  v_effective_tech_diff := v_tech_difference + v_probe_bonus;

  IF v_effective_tech_diff >= 4 THEN
    v_visibility_level := 5;
  ELSIF v_effective_tech_diff >= 2 THEN
    v_visibility_level := 4;
  ELSIF v_effective_tech_diff >= 0 THEN
    v_visibility_level := 3;
  ELSIF v_effective_tech_diff >= -2 THEN
    v_visibility_level := 2;
  ELSE
    v_visibility_level := 1;
  END IF;

  -- Sync target planet resources to current time before reading
  PERFORM calculate_and_sync_resources_internal(p_target_planet_id, p_target_user_id);

  -- Resources (always visible)
  SELECT metal, crystal, deuterium, energy_used, energy_max
  INTO target_resources
  FROM planet_resources WHERE planet_id = p_target_planet_id;

  -- Ships (visibility level >= 2): planet owner's ships
  IF v_visibility_level >= 2 THEN
    SELECT jsonb_agg(jsonb_build_object(
      'name', st.name,
      'quantity', ps.quantity
    ))
    INTO target_ships
    FROM planet_ships ps
    JOIN ship_types st ON ps.ship_type_id = st.id
    WHERE ps.planet_id = p_target_planet_id AND ps.quantity > 0;

    -- Allied stationed fleets (deployed via Alliance Depot)
    v_allied_ships := '[]'::jsonb;

    FOR v_allied_fleet IN
      SELECT f.id as fleet_id, f.user_id as ally_user_id
      FROM fleets f
      WHERE f.is_completed = false
        AND f.is_returning = false
        AND f.mission_type = 'hold'
        AND f.target_galaxy = target_planet.galaxy
        AND f.target_system = target_planet.solar_system
        AND f.target_position = target_planet.position
        AND f.user_id != p_target_user_id
    LOOP
      SELECT username INTO v_ally_username
      FROM profiles WHERE id = v_allied_fleet.ally_user_id;

      SELECT jsonb_agg(jsonb_build_object(
        'name', st.name,
        'quantity', fs.quantity,
        'owner', v_ally_username
      ))
      INTO v_ally_ships
      FROM fleet_ships fs
      JOIN ship_types st ON fs.ship_type_id = st.id
      WHERE fs.fleet_id = v_allied_fleet.fleet_id AND fs.quantity > 0;

      IF v_ally_ships IS NOT NULL THEN
        v_allied_ships := v_allied_ships || v_ally_ships;
      END IF;
    END LOOP;
  ELSE
    target_ships := NULL;
    v_allied_ships := NULL;
  END IF;

  -- Defenses (visibility level >= 3)
  IF v_visibility_level >= 3 THEN
    SELECT jsonb_agg(jsonb_build_object(
      'name', dt.name,
      'quantity', pd.quantity
    ))
    INTO target_defenses
    FROM planet_defenses pd
    JOIN defense_types dt ON pd.defense_type_id = dt.id
    WHERE pd.planet_id = p_target_planet_id AND pd.quantity > 0;
  ELSE
    target_defenses := NULL;
  END IF;

  -- Buildings (visibility level >= 4)
  IF v_visibility_level >= 4 THEN
    SELECT jsonb_agg(jsonb_build_object(
      'name', bt.name,
      'level', pb.level
    ))
    INTO target_buildings
    FROM planet_buildings pb
    JOIN building_types bt ON pb.building_type_id = bt.id
    WHERE pb.planet_id = p_target_planet_id AND pb.level > 0;
  ELSE
    target_buildings := NULL;
  END IF;

  -- Technologies (visibility level >= 5)
  IF v_visibility_level >= 5 THEN
    SELECT jsonb_agg(jsonb_build_object(
      'name', tt.name,
      'level', ut.level
    ))
    INTO target_techs
    FROM user_technologies ut
    JOIN technology_types tt ON ut.technology_type_id = tt.id
    WHERE ut.user_id = p_target_user_id AND ut.level > 0;
  ELSE
    target_techs := NULL;
  END IF;

  -- Detection chance (defender notified)
  v_detection_chance := GREATEST(0, LEAST(100,
    30 + (v_defender_counter_spy_level - v_attacker_spy_level) * 8 + (COALESCE(p_probe_count, 1) * 3)
  ));
  v_detected := random() * 100 < v_detection_chance;

  -- Destruction chance = 3% per probe, capped at 100%
  v_destruction_chance := LEAST(100, COALESCE(p_probe_count, 1) * 3);
  v_probes_destroyed := random() * 100 < v_destruction_chance;

  report_data := jsonb_build_object(
    'planet_name', target_planet.name,
    'coordinates', format('[%s:%s:%s]', target_planet.galaxy, target_planet.solar_system, target_planet.position),
    'resources', jsonb_build_object(
      'metal', COALESCE(target_resources.metal, 0),
      'crystal', COALESCE(target_resources.crystal, 0),
      'deuterium', COALESCE(target_resources.deuterium, 0)
    ),
    'buildings', COALESCE(target_buildings, '[]'::jsonb),
    'ships', COALESCE(target_ships, '[]'::jsonb),
    'defenses', COALESCE(target_defenses, '[]'::jsonb),
    'technologies', COALESCE(target_techs, '[]'::jsonb),
    'allied_fleets', COALESCE(v_allied_ships, '[]'::jsonb),
    'visibility_level', v_visibility_level,
    'tech_difference', v_tech_difference,
    'probe_count', COALESCE(p_probe_count, 1),
    'spy_detected', v_detected,
    'probes_destroyed', v_probes_destroyed,
    'destruction_chance', v_destruction_chance
  );

  INSERT INTO messages (
    sender_id,
    recipient_id,
    subject,
    body,
    message_type
  ) VALUES (
    NULL,
    p_attacker_id,
    CASE WHEN v_probes_destroyed
      THEN '⚠️ Reporte de Espionaje - ' || target_planet.name || ' (Sondas destruidas)'
      ELSE 'Reporte de Espionaje - ' || target_planet.name
    END,
    report_data::text,
    'espionage'
  );

  IF v_detected THEN
    INSERT INTO messages (
      sender_id,
      recipient_id,
      subject,
      body,
      message_type
    ) VALUES (
      NULL,
      p_target_user_id,
      'Actividad de Espionaje Detectada',
      format('Tus sistemas de contraespionaje detectaron actividad de espionaje en tu planeta %s [%s:%s:%s]. Un jugador enemigo envió %s sonda(s) para obtener información sobre tus instalaciones.%s',
        target_planet.name, target_planet.galaxy, target_planet.solar_system, target_planet.position,
        COALESCE(p_probe_count, 1),
        CASE WHEN v_probes_destroyed THEN ' Las sondas enemigas fueron destruidas.' ELSE '' END
      ),
      'espionage'
    );
  END IF;

  RETURN jsonb_build_object(
    'probes_destroyed', v_probes_destroyed,
    'detected', v_detected
  );
END;
$$;


--
-- TOC entry 797 (class 1255 OID 19466)
-- Name: generate_telegram_link_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_telegram_link_code() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_code text;
  v_existing telegram_links%ROWTYPE;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Check if already linked
  SELECT * INTO v_existing FROM telegram_links WHERE user_id = v_user_id;
  
  IF v_existing IS NOT NULL AND v_existing.telegram_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_linked', true,
      'telegram_username', v_existing.telegram_username
    );
  END IF;

  -- Generate unique 8-character code
  v_code := upper(substring(md5(random()::text || clock_timestamp()::text) from 1 for 8));

  -- Upsert the link record
  INSERT INTO telegram_links (user_id, link_code, created_at)
  VALUES (v_user_id, v_code, now())
  ON CONFLICT (user_id) DO UPDATE
  SET link_code = v_code, created_at = now();

  RETURN jsonb_build_object(
    'success', true,
    'code', v_code,
    'expires_in_minutes', 10
  );
END;
$$;


--
-- TOC entry 740 (class 1255 OID 19063)
-- Name: get_acs_combined_ships(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acs_combined_ships(p_acs_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_combined_ships jsonb := '{}';
  v_fleet_ships RECORD;
  v_ship_key text;
  v_ship_count integer;
BEGIN
  FOR v_fleet_ships IN
    SELECT fs.ship_type_id, fs.quantity, st.code
    FROM acs_participants ap
    JOIN fleet_ships fs ON ap.fleet_id = fs.fleet_id
    JOIN ship_types st ON fs.ship_type_id = st.id
    WHERE ap.acs_id = p_acs_id
  LOOP
    v_ship_key := v_fleet_ships.code;
    v_ship_count := COALESCE((v_combined_ships->>v_ship_key)::integer, 0) + v_fleet_ships.quantity;
    v_combined_ships := v_combined_ships || jsonb_build_object(v_ship_key, v_ship_count);
  END LOOP;

  RETURN v_combined_ships;
END;
$$;


--
-- TOC entry 904 (class 1255 OID 20186)
-- Name: get_acs_participant_details(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acs_participant_details(p_acs_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_alliance_id uuid;
  v_acs_alliance_id uuid;
  v_result jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT am.alliance_id INTO v_user_alliance_id
  FROM alliance_members am
  WHERE am.user_id = v_user_id;

  SELECT af.alliance_id INTO v_acs_alliance_id
  FROM acs_fleets af
  WHERE af.id = p_acs_id;

  IF v_acs_alliance_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'ACS no encontrado');
  END IF;

  IF v_user_alliance_id IS DISTINCT FROM v_acs_alliance_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No perteneces a esta alianza');
  END IF;

  SELECT jsonb_build_object(
    'success', true,
    'participants', COALESCE(jsonb_agg(
      jsonb_build_object(
        'username', sub.username,
        'user_id', sub.user_id,
        'is_creator', sub.is_creator,
        'ships', sub.ships
      ) ORDER BY sub.joined_at
    ), '[]'::jsonb)
  )
  INTO v_result
  FROM (
    SELECT
      pr.username,
      ap.user_id,
      ap.joined_at,
      (ap.user_id = (SELECT creator_id FROM acs_fleets WHERE id = p_acs_id)) AS is_creator,
      COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object(
            'name', st.name,
            'code', st.code,
            'quantity', fs.quantity,
            'image_url', st.image_url
          ) ORDER BY st.name
        )
        FROM fleet_ships fs
        JOIN ship_types st ON fs.ship_type_id = st.id
        WHERE fs.fleet_id = ap.fleet_id),
        '[]'::jsonb
      ) AS ships
    FROM acs_participants ap
    JOIN profiles pr ON ap.user_id = pr.id
    WHERE ap.acs_id = p_acs_id
  ) sub;

  RETURN COALESCE(v_result, jsonb_build_object('success', true, 'participants', '[]'::jsonb));
END;
$$;


--
-- TOC entry 743 (class 1255 OID 19066)
-- Name: get_acs_total_cargo_capacity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acs_total_cargo_capacity(p_acs_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_capacity bigint := 0;
BEGIN
  SELECT COALESCE(SUM(fs.quantity * st.cargo_capacity), 0) INTO v_total_capacity
  FROM acs_participants ap
  JOIN fleet_ships fs ON ap.fleet_id = fs.fleet_id
  JOIN ship_types st ON fs.ship_type_id = st.id
  WHERE ap.acs_id = p_acs_id;

  RETURN v_total_capacity;
END;
$$;


