CREATE FUNCTION public.get_active_alliance_wars() RETURNS TABLE(id uuid, alliance1_id uuid, alliance1_tag text, alliance1_name text, alliance2_id uuid, alliance2_tag text, alliance2_name text, declared_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    d.id,
    d.alliance_id as alliance1_id,
    a1.tag as alliance1_tag,
    a1.name as alliance1_name,
    d.target_alliance_id as alliance2_id,
