--
-- TOC entry 938 (class 1255 OID 20404)
-- Name: get_all_constraints(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_constraints() RETURNS TABLE(table_name text, constraint_name text, constraint_type text, constraint_def text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    cl.relname::text,
    co.conname::text,
    CASE co.contype
      WHEN 'f' THEN 'FOREIGN KEY'
      WHEN 'u' THEN 'UNIQUE'
      WHEN 'c' THEN 'CHECK'
      WHEN 'p' THEN 'PRIMARY KEY'
      ELSE co.contype::text
    END,
    pg_get_constraintdef(co.oid, true)::text
  FROM pg_constraint co
  JOIN pg_class cl ON cl.oid = co.conrelid
  JOIN pg_namespace n ON n.oid = cl.relnamespace
  WHERE n.nspname = 'public'
  ORDER BY cl.relname, co.contype, co.conname;
$$;


