-- TOC entry 1162 (class 1255 OID 22483)
-- Name: get_all_fortresses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_fortresses() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'galaxy', af.galaxy,
      'system', af.system,
      'position', af.position,
      'owner_alliance_id', af.owner_alliance_id,
      'owner_alliance_name', a.name,
      'owner_alliance_tag', a.tag,
      'captured_at', af.captured_at,
      'total_ships', COALESCE((SELECT SUM(quantity) FROM fortress_ships fs WHERE fs.fortress_id = af.id), 0),
      'total_combat_power', COALESCE((SELECT SUM(fs.quantity * COALESCE(st.weapon_power, 0)) FROM fortress_ships fs LEFT JOIN ship_types st ON st.id = fs.ship_type_id WHERE fs.fortress_id = af.id), 0)::bigint
    ) ORDER BY af.galaxy
  ), '[]'::jsonb)
  INTO v_result
  FROM alliance_fortresses af
  LEFT JOIN alliances a ON a.id = af.owner_alliance_id;

  RETURN jsonb_build_object('success', true, 'fortresses', v_result);
END;
$$;


