--
-- TOC entry 936 (class 1255 OID 20402)
-- Name: get_all_indexes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_indexes() RETURNS TABLE(table_name text, index_name text, index_def text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    t.relname::text,
    i.relname::text,
    pg_get_indexdef(ix.indexrelid)::text
  FROM pg_index ix
  JOIN pg_class t ON t.oid = ix.indrelid
  JOIN pg_class i ON i.oid = ix.indexrelid
  JOIN pg_namespace n ON n.oid = t.relnamespace
  WHERE n.nspname = 'public'
    AND NOT ix.indisprimary  -- Exclude primary keys (handled in CREATE TABLE)
    AND NOT ix.indisunique   -- Exclude unique constraints (handled separately)
  ORDER BY t.relname, i.relname;
$$;


