--
-- TOC entry 943 (class 1255 OID 20409)
-- Name: get_all_sequences_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_sequences_state() RETURNS TABLE(seq_name text, seq_last_value bigint, seq_start_value bigint, seq_increment bigint, seq_max_value bigint, seq_min_value bigint, seq_cycle boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  rec record;
BEGIN
  FOR rec IN 
    SELECT s.relname::text as sname
    FROM pg_class s
    JOIN pg_namespace n ON n.oid = s.relnamespace
    WHERE s.relkind = 'S' AND n.nspname = 'public'
    ORDER BY s.relname
  LOOP
    RETURN QUERY EXECUTE format(
      'SELECT %L::text, last_value, start_value, increment_by, max_value, min_value, is_cycled FROM public.%I',
      rec.sname, rec.sname
    );
  END LOOP;
END;
$$;


