--
-- TOC entry 937 (class 1255 OID 20403)
-- Name: get_all_unique_indexes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_unique_indexes() RETURNS TABLE(table_name text, index_name text, index_def text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    t.relname::text,
    i.relname::text,
    pg_get_indexdef(ix.indexrelid)::text
  FROM pg_index ix
  JOIN pg_class t ON t.oid = ix.indrelid
  JOIN pg_class i ON i.oid = ix.indexrelid
  JOIN pg_namespace n ON n.oid = t.relnamespace
  LEFT JOIN pg_constraint c ON c.conindid = ix.indexrelid
  WHERE n.nspname = 'public'
    AND ix.indisunique
    AND NOT ix.indisprimary
    AND c.oid IS NULL  -- Not backing a constraint
  ORDER BY t.relname, i.relname;
$$;


--
-- TOC entry 791 (class 1255 OID 19326)
-- Name: get_all_user_emails(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_user_emails() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_emails jsonb;
BEGIN
  v_admin_id := auth.uid();
  
  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;
  
  SELECT jsonb_agg(jsonb_build_object('id', u.id, 'email', u.email, 'username', p.username))
  INTO v_emails
  FROM auth.users u
  JOIN profiles p ON p.id = u.id
  WHERE u.email IS NOT NULL;
  
  RETURN jsonb_build_object(
    'success', true,
    'users', COALESCE(v_emails, '[]'::jsonb)
  );
END;
$$;


