--
-- TOC entry 855 (class 1255 OID 20015)
-- Name: get_alliance_diplomacy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_alliance_diplomacy(p_alliance_id uuid) RETURNS TABLE(id uuid, alliance_id uuid, alliance_name text, alliance_tag text, target_alliance_id uuid, target_alliance_name text, target_alliance_tag text, diplomacy_type text, status text, proposed_at timestamp with time zone, accepted_at timestamp with time zone, expires_at timestamp with time zone, message text, is_incoming boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    d.id,
    d.alliance_id,
    a1.name as alliance_name,
    a1.tag as alliance_tag,
    d.target_alliance_id,
    a2.name as target_alliance_name,
    a2.tag as target_alliance_tag,
    d.diplomacy_type,
    d.status,
    d.proposed_at,
    d.accepted_at,
    d.expires_at,
    d.message,
    (d.target_alliance_id = p_alliance_id) as is_incoming
  FROM alliance_diplomacy d
  JOIN alliances a1 ON d.alliance_id = a1.id
  JOIN alliances a2 ON d.target_alliance_id = a2.id
  WHERE (d.alliance_id = p_alliance_id OR d.target_alliance_id = p_alliance_id)
    AND d.status IN ('pending', 'active')
  ORDER BY 
    CASE d.status WHEN 'pending' THEN 0 ELSE 1 END,
    d.proposed_at DESC;
END;
$$;


