--
-- TOC entry 1103 (class 1255 OID 21695)
-- Name: get_alliance_wars(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_alliance_wars(p_filter text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_war record;
  v_result jsonb;
BEGIN
  -- Auto-resolve any active wars past end_time
  FOR v_war IN
    SELECT id FROM alliance_wars WHERE status = 'active' AND end_time <= now()
  LOOP
    BEGIN
      -- We need auth.uid() context for resolve function
      -- Auto-resolve bypass: directly run the logic
      PERFORM auto_resolve_single_war(v_war.id);
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Auto-resolve failed for war %: %', v_war.id, SQLERRM;
    END;
  END LOOP;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', aw.id,
      'title', aw.title,
      'war_type', aw.war_type,
      'entry_fee_fxu', aw.entry_fee_fxu,
      'total_pool_fxu', aw.total_pool_fxu,
      'status', aw.status,
      'start_time', aw.start_time,
      'end_time', aw.end_time,
      'winner_alliance_id', aw.winner_alliance_id,
      'entry_count', (SELECT COUNT(*) FROM alliance_war_entries awe WHERE awe.war_id = aw.id),
      'scores', (
        SELECT jsonb_agg(jsonb_build_object(
          'alliance_id', aws.alliance_id,
          'alliance_name', a.name,
          'alliance_tag', a.tag,
          'total_score', aws.total_score,
          'battle_count', aws.battle_count
        ) ORDER BY aws.total_score DESC)
        FROM alliance_war_scores aws
        JOIN alliances a ON a.id = aws.alliance_id
        WHERE aws.war_id = aw.id
      ),
      'created_at', aw.created_at,
      'resolved_at', aw.resolved_at
    ) ORDER BY aw.created_at DESC
  ) INTO v_result
  FROM alliance_wars aw
  WHERE CASE
    WHEN p_filter = 'active' THEN aw.status = 'active'
    WHEN p_filter = 'open' THEN aw.status = 'open'
    WHEN p_filter = 'completed' THEN aw.status = 'completed'
    ELSE true
  END;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- TOC entry 932 (class 1255 OID 20396)
-- Name: get_ally_depot_planet_ids(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ally_depot_planet_ids(p_planet_ids uuid[]) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_alliance_id uuid;
  v_result uuid[];
BEGIN
  IF v_user_id IS NULL THEN
    RETURN ARRAY[]::uuid[];
  END IF;

  SELECT alliance_id INTO v_alliance_id
  FROM alliance_members
  WHERE user_id = v_user_id;

  IF v_alliance_id IS NULL THEN
    RETURN ARRAY[]::uuid[];
  END IF;

  SELECT array_agg(pb.planet_id) INTO v_result
  FROM planet_buildings pb
  JOIN planets pl ON pl.id = pb.planet_id
  JOIN alliance_members am ON am.user_id = pl.user_id AND am.alliance_id = v_alliance_id
  WHERE pb.planet_id = ANY(p_planet_ids)
    AND pb.building_type_id = 18
    AND pb.level >= 1
    AND pl.user_id != v_user_id;

  RETURN COALESCE(v_result, ARRAY[]::uuid[]);
END;
$$;


--
-- TOC entry 773 (class 1255 OID 19276)
-- Name: get_anti_multi_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_anti_multi_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  
  SELECT jsonb_build_object(
    'shared_ips_count', (
      SELECT COUNT(*) FROM (
        SELECT ip_address FROM login_sessions
        WHERE created_at > now() - interval '30 days'
        GROUP BY ip_address
        HAVING COUNT(DISTINCT user_id) > 1
      ) x
    ),
    'shared_fingerprints_count', (
      SELECT COUNT(*) FROM (
        SELECT fingerprint FROM login_sessions
        WHERE fingerprint IS NOT NULL AND fingerprint != ''
          AND created_at > now() - interval '30 days'
        GROUP BY fingerprint
        HAVING COUNT(DISTINCT user_id) > 1
      ) x
    ),
    'pending_reports', (
      SELECT COUNT(*) FROM multiaccounting_reports WHERE status = 'pending'
    ),
    'confirmed_multis', (
      SELECT COUNT(*) FROM suspicious_accounts WHERE is_confirmed_multi = true
    ),
    'unreviewed_suspicious', (
      SELECT COUNT(*) FROM suspicious_accounts WHERE is_reviewed = false
    ),
    'total_logins_today', (
      SELECT COUNT(*) FROM login_sessions WHERE created_at > now() - interval '1 day'
    ),
    'unique_users_today', (
      SELECT COUNT(DISTINCT user_id) FROM login_sessions WHERE created_at > now() - interval '1 day'
    )
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


