--
-- TOC entry 1021 (class 1255 OID 20960)
-- Name: get_autopilot_events(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_autopilot_events(p_planet_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(e)), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT
      ev.id,
      ev.planet_id,
      p.name AS planet_name,
      ev.event_type,
      ev.payload,
      ev.created_at
    FROM public.autopilot_events ev
    LEFT JOIN public.planets p ON p.id = ev.planet_id
    WHERE ev.user_id = auth.uid()
      AND (p_planet_id IS NULL OR ev.planet_id = p_planet_id)
    ORDER BY ev.created_at DESC
    LIMIT GREATEST(1, LEAST(p_limit, 100))
  ) e;

  RETURN jsonb_build_object('success', true, 'events', v_rows);
END;
$$;


--
-- TOC entry 1024 (class 1255 OID 20964)
-- Name: get_autopilot_stats(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_autopilot_stats(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stats jsonb;
  v_window integer := GREATEST(1, LEAST(p_hours, 168));
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT COALESCE(jsonb_object_agg(event_type, total), '{}'::jsonb)
  INTO v_stats
  FROM (
    SELECT event_type, COUNT(*)::int AS total
    FROM public.autopilot_events
    WHERE user_id = auth.uid()
      AND created_at >= now() - make_interval(hours => v_window)
    GROUP BY event_type
  ) s;

  RETURN jsonb_build_object('success', true, 'hours', v_window, 'stats', v_stats);
END;
$$;


