--
-- TOC entry 1120 (class 1255 OID 21815)
-- Name: get_cosmetic_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cosmetic_catalog() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_result jsonb;
BEGIN
  v_user_id := auth.uid();
  
  -- Auto-clean expired first
  IF v_user_id IS NOT NULL THEN
    PERFORM clean_expired_cosmetics(v_user_id);
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ci.id,
      'code', ci.code,
      'type', ci.cosmetic_type,
      'name', ci.name_es,
      'description', ci.description_es,
      'icon', ci.icon,
      'cost', ci.fxu_cost,
      'duration_days', ci.duration_days,
      'rarity', ci.rarity,
      'owned', CASE WHEN v_user_id IS NOT NULL THEN
        EXISTS(SELECT 1 FROM user_cosmetics uc WHERE uc.user_id = v_user_id AND uc.cosmetic_id = ci.id AND uc.expires_at > now())
      ELSE false END,
      'equipped', CASE WHEN v_user_id IS NOT NULL THEN
        EXISTS(SELECT 1 FROM user_cosmetics uc WHERE uc.user_id = v_user_id AND uc.cosmetic_id = ci.id AND uc.expires_at > now() AND uc.equipped = true)
      ELSE false END,
      'expires_at', CASE WHEN v_user_id IS NOT NULL THEN
        (SELECT uc.expires_at::text FROM user_cosmetics uc WHERE uc.user_id = v_user_id AND uc.cosmetic_id = ci.id AND uc.expires_at > now() AND uc.equipped = true LIMIT 1)
      ELSE NULL END
    ) ORDER BY ci.sort_order
  ) INTO v_result
  FROM cosmetic_items ci
  WHERE ci.is_active = true;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- TOC entry 934 (class 1255 OID 20400)
-- Name: get_custom_types(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_custom_types() RETURNS TABLE(type_name text, type_schema text, enum_values text[], type_kind text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    t.typname::text,
    n.nspname::text,
    ARRAY(
      SELECT e.enumlabel::text 
      FROM pg_enum e 
      WHERE e.enumtypid = t.oid 
      ORDER BY e.enumsortorder
    ),
    CASE t.typtype 
      WHEN 'e' THEN 'enum'
      WHEN 'c' THEN 'composite'
      ELSE t.typtype::text
    END
  FROM pg_type t
  JOIN pg_namespace n ON t.typnamespace = n.oid
  WHERE n.nspname = 'public'
    AND t.typtype IN ('e', 'c')
  ORDER BY t.typname;
$$;


--
-- TOC entry 725 (class 1255 OID 18985)
-- Name: get_daily_revenue(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_daily_revenue(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_result jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  SELECT jsonb_build_object(
    'success', true,
    'data', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'date', d.day::date,
            'amount', COALESCE(r.total, 0)
          )
          ORDER BY d.day
        )
        FROM generate_series(
          CURRENT_DATE - (p_days - 1),
          CURRENT_DATE,
          '1 day'::interval
        ) AS d(day)
        LEFT JOIN (
          SELECT DATE(created_at) as day,
                 SUM(CASE WHEN currency = 'USDT' THEN amount * 10000 ELSE amount END) as total
          FROM public.admin_revenue
          WHERE created_at >= CURRENT_DATE - p_days
          GROUP BY DATE(created_at)
        ) r ON d.day::date = r.day
      ),
      '[]'::jsonb
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- TOC entry 1132 (class 1255 OID 22220)
