    'best_streak',COALESCE(v_streak.best_streak,0),
    'expires_at',v_streak.expires_at,
    'cost',10,
    'balance',COALESCE((SELECT fxu_balance FROM profiles WHERE id=v_user_id),0)
  );
END;
$$;


