--
-- TOC entry 812 (class 1255 OID 19606)
-- Name: get_hall_of_fame(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hall_of_fame(p_round_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_round_id uuid;
  v_result jsonb;
BEGIN
  IF p_round_id IS NULL THEN
    SELECT id INTO v_round_id FROM game_rounds ORDER BY round_number DESC LIMIT 1;
  ELSE
    v_round_id := p_round_id;
  END IF;
  
  IF v_round_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No hay rondas registradas');
  END IF;
  
  SELECT jsonb_build_object(
    'success', true,
    'round', (SELECT row_to_json(r) FROM game_rounds r WHERE r.id = v_round_id),
    'players', (
      SELECT jsonb_agg(row_to_json(p) ORDER BY p.category, p.rank)
      FROM hall_of_fame_players p
      WHERE p.round_id = v_round_id
    ),
    'alliances', (
      SELECT jsonb_agg(row_to_json(a) ORDER BY a.rank)
      FROM hall_of_fame_alliances a
      WHERE a.round_id = v_round_id
    ),
    'records', (
      SELECT jsonb_agg(row_to_json(rec))
      FROM hall_of_fame_records rec
      WHERE rec.round_id = v_round_id
    )
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


--
-- TOC entry 1086 (class 1255 OID 21495)
-- Name: get_hero_active_expedition(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hero_active_expedition(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_active record;
BEGIN
  SELECT a.*, e.name, e.duration_minutes, e.xp_reward, e.hp_damage
  INTO v_active
  FROM hero_ship_active_expedition a
  JOIN hero_ship_expeditions e ON e.id = a.expedition_id
  WHERE a.user_id = p_user_id AND a.claimed = false;

  IF NOT FOUND THEN
    RETURN 'null'::jsonb;
  END IF;

  -- If expedition is ready, return it as claimable — do NOT delete it
  IF now() >= v_active.returns_at THEN
    RETURN jsonb_build_object(
      'id', v_active.id,
      'expedition_name', v_active.name,
      'duration_minutes', v_active.duration_minutes,
      'xp_reward', v_active.xp_reward,
      'hp_damage', v_active.hp_damage,
      'started_at', v_active.started_at::text,
      'returns_at', v_active.returns_at::text,
      'can_claim', true,
      'remaining_seconds', 0
    );
  END IF;

  RETURN jsonb_build_object(
    'id', v_active.id,
    'expedition_name', v_active.name,
    'duration_minutes', v_active.duration_minutes,
    'xp_reward', v_active.xp_reward,
    'hp_damage', v_active.hp_damage,
    'started_at', v_active.started_at::text,
    'returns_at', v_active.returns_at::text,
    'can_claim', false,
    'remaining_seconds', EXTRACT(EPOCH FROM (v_active.returns_at - now()))
  );
END;
$$;


--
-- TOC entry 1095 (class 1255 OID 21555)
-- Name: get_hero_duel_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hero_duel_history(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', d.id,
    'stake', d.stake,
    'winner_id', d.winner_id,
    'loser_id', d.loser_id,
    'is_winner', (d.winner_id = p_user_id),
    'opponent_username', CASE WHEN d.creator_id = p_user_id
      THEN (SELECT username FROM profiles WHERE id = d.opponent_id)
      ELSE (SELECT username FROM profiles WHERE id = d.creator_id) END,
    'opponent_level', CASE WHEN d.creator_id = p_user_id
      THEN d.opponent_level_before
      ELSE d.creator_level_before END,
    'resolved_at', d.updated_at::text
  ) ORDER BY d.updated_at DESC), '[]'::jsonb) INTO v_result
  FROM hero_duels d
  WHERE d.status = 'completed'
    AND (d.creator_id = p_user_id OR d.opponent_id = p_user_id);

  RETURN v_result;
END;
$$;


