-- TOC entry 1130 (class 1255 OID 22148)
-- Name: get_hero_inventory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hero_inventory(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_items jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'inventory_id', inv.id,
    'item_id', inv.item_id,
    'item_level', inv.item_level,
    'quantity', inv.quantity,
    'name', i.name,
    'rarity', i.rarity,
    'description', i.description,
    'slot_type', i.slot_type,
    'is_repair_kit', i.is_repair_kit,
    'repair_amount', i.repair_amount,
    'attack_bonus', i.attack_bonus,
    'defense_bonus', i.defense_bonus,
    'shield_bonus', i.shield_bonus,
    'speed_bonus', i.speed_bonus,
    'loot_bonus', i.loot_bonus,
    'min_level', i.min_level,
    'image_url', i.image_url
  ) ORDER BY i.rarity DESC, i.name), '[]'::jsonb) INTO v_items
  FROM user_hero_ship_inventory inv
  JOIN hero_ship_items i ON i.id = inv.item_id
  WHERE inv.user_id = p_user_id AND inv.quantity > 0;

  RETURN v_items;
END;
$$;


