--
-- TOC entry 1140 (class 1255 OID 22283)
-- Name: get_hero_ship(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hero_ship(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ship record;
  v_total_points integer;
  v_respec_cost integer;
BEGIN
  PERFORM create_hero_ship(p_user_id);
  SELECT * INTO v_ship FROM user_hero_ships WHERE user_id = p_user_id;
  v_total_points := (COALESCE(v_ship.level,1) - 1) * 10;
  v_total_points := GREATEST(v_total_points, COALESCE(v_ship.attack_points,0) + COALESCE(v_ship.defense_points,0) + COALESCE(v_ship.shield_points,0) + COALESCE(v_ship.speed_points,0));
  SELECT COALESCE((SELECT value::integer FROM game_settings WHERE key = 'fxu_hero_respec_cost'), 10000) INTO v_respec_cost;
  RETURN jsonb_build_object(
    'id', v_ship.id, 'level', v_ship.level, 'xp', v_ship.xp, 'xp_to_next', v_ship.xp_to_next,
    'attack_points', v_ship.attack_points, 'defense_points', v_ship.defense_points,
    'shield_points', v_ship.shield_points, 'speed_points', v_ship.speed_points,
    'total_points', v_total_points,
    'free_points', v_total_points - (COALESCE(v_ship.attack_points,0) + COALESCE(v_ship.defense_points,0) + COALESCE(v_ship.shield_points,0) + COALESCE(v_ship.speed_points,0)),
    'respec_cost', v_respec_cost,
    'hp', v_ship.hp, 'hp_max', v_ship.hp_max
  );
END;
$$;


--
-- TOC entry 948 (class 1255 OID 20430)
-- Name: get_incoming_attacks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_incoming_attacks(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
  v_defender_spy_level integer;
BEGIN
  SELECT COALESCE(ut.level, 0) INTO v_defender_spy_level
  FROM user_technologies ut
  JOIN technology_types tt ON ut.technology_type_id = tt.id
  WHERE ut.user_id = p_user_id AND tt.code = 'espionage_tech';
  v_defender_spy_level := COALESCE(v_defender_spy_level, 0);

  SELECT json_agg(row_to_json(t))
  INTO v_result
  FROM (
    SELECT
      f.id AS fleet_id,
      f.mission_type,
      f.departure_time,
      f.arrival_time,
      f.is_returning,
      f.target_galaxy,
      f.target_system,
      f.target_position,
      f.target_type,
      p_target.name AS target_planet_name,
      p_origin.galaxy AS origin_galaxy,
      p_origin.solar_system AS origin_system,
      p_origin.position AS origin_position,
      attacker.username AS attacker_name,
      COALESCE(attacker_spy.level, 0) AS attacker_spy_level,
      CASE
        WHEN v_defender_spy_level - COALESCE(attacker_spy.level, 0) >= 0 THEN (
          SELECT json_agg(json_build_object(
            'ship_name', st.name,
            'ship_code', st.code,
            'quantity', fs.quantity
          ))
          FROM fleet_ships fs
          JOIN ship_types st ON st.id = fs.ship_type_id
          WHERE fs.fleet_id = f.id
            AND fs.quantity > 0
        )
        ELSE NULL
      END AS ships,
      (v_defender_spy_level - COALESCE(attacker_spy.level, 0) >= 0) AS can_see_fleet
    FROM fleets f
    JOIN planets p_target
      ON p_target.galaxy = f.target_galaxy
     AND p_target.solar_system = f.target_system
     AND p_target.position = f.target_position
     -- ✅ FIX: distinguir planeta vs luna para no duplicar el ataque
     AND p_target.planet_type = COALESCE(f.target_type, 'planet')
     AND p_target.is_destroyed = false
    JOIN planets p_origin ON p_origin.id = f.origin_planet_id
    JOIN profiles attacker ON attacker.id = f.user_id
    LEFT JOIN user_technologies attacker_spy ON attacker_spy.user_id = f.user_id
      AND attacker_spy.technology_type_id = (
        SELECT id FROM technology_types WHERE code = 'espionage_tech' LIMIT 1
      )
    WHERE f.is_completed = false
      AND f.is_returning = false
      AND f.user_id != p_user_id
      AND p_target.user_id = p_user_id
      AND f.mission_type IN ('attack', 'destroy', 'acs_attack', 'missile_attack')
    ORDER BY f.arrival_time ASC
  ) t;

  RETURN COALESCE(v_result, '[]'::json);
END;
$$;


