--
-- TOC entry 899 (class 1255 OID 20174)
-- Name: get_market_resource_prices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_market_resource_prices() RETURNS TABLE(resource_code text, avg_price numeric, listing_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH ranked AS (
    SELECT
      ml.item_code,
      ml.price_per_unit,
      ROW_NUMBER() OVER (PARTITION BY ml.item_code ORDER BY ml.price_per_unit) AS rn,
      COUNT(*) OVER (PARTITION BY ml.item_code) AS total
    FROM market_listings ml
    WHERE ml.status = 'active'
      AND ml.listing_type = 'resource'
      AND ml.item_code IN ('metal', 'crystal', 'deuterium')
  ),
  trimmed AS (
    SELECT
      r.item_code,
      r.price_per_unit
    FROM ranked r
    WHERE r.rn > (r.total * 0.25)
      AND r.rn <= (r.total * 0.75)
  )
  SELECT
    t.item_code AS resource_code,
    ROUND(COALESCE(AVG(t.price_per_unit), 0), 4) AS avg_price,
    COUNT(*)::integer AS listing_count
  FROM trimmed t
  GROUP BY t.item_code;
END;
$$;


