--
-- TOC entry 738 (class 1255 OID 19061)
-- Name: get_missile_silo_capacity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_missile_silo_capacity(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet record;
  v_silo_level integer;
  v_impulse_level integer;
  v_ipm_type_id integer;
  v_abm_type_id integer;
  v_ipm_count integer;
  v_abm_count integer;
  v_max_missiles integer;
  v_max_range integer;
BEGIN
  -- Get planet owner
  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Planet not found');
  END IF;

  -- Get silo level
  SELECT COALESCE(pb.level, 0) INTO v_silo_level
  FROM planet_buildings pb
  JOIN building_types bt ON pb.building_type_id = bt.id
  WHERE pb.planet_id = p_planet_id AND bt.code = 'missile_silo';

  v_silo_level := COALESCE(v_silo_level, 0);

  -- Max missiles = silo_level * 10
  v_max_missiles := v_silo_level * 10;

  -- Get impulse drive level for range calculation
  SELECT COALESCE(ut.level, 0) INTO v_impulse_level
  FROM user_technologies ut
  JOIN technology_types tt ON ut.technology_type_id = tt.id
  WHERE ut.user_id = v_planet.user_id AND tt.code = 'impulse_drive';

  v_impulse_level := COALESCE(v_impulse_level, 0);

  -- Range = (impulse_level * 5) - 1, minimum 0
  v_max_range := GREATEST(0, (v_impulse_level * 5) - 1);

  -- Get missile type IDs
  SELECT id INTO v_ipm_type_id FROM defense_types WHERE code = 'interplanetary_missile';
  SELECT id INTO v_abm_type_id FROM defense_types WHERE code = 'anti_ballistic_missile';

  -- Get current counts
  SELECT COALESCE(quantity, 0) INTO v_ipm_count
  FROM planet_defenses WHERE planet_id = p_planet_id AND defense_type_id = v_ipm_type_id;

  SELECT COALESCE(quantity, 0) INTO v_abm_count
  FROM planet_defenses WHERE planet_id = p_planet_id AND defense_type_id = v_abm_type_id;

  RETURN jsonb_build_object(
    'silo_level', v_silo_level,
    'max_missiles', v_max_missiles,
    'ipm_count', COALESCE(v_ipm_count, 0),
    'abm_count', COALESCE(v_abm_count, 0),
    'available_slots', GREATEST(0, v_max_missiles - COALESCE(v_ipm_count, 0) - COALESCE(v_abm_count, 0)),
    'impulse_level', v_impulse_level,
    'max_range', v_max_range,
    'can_launch', v_silo_level >= 4 AND v_impulse_level >= 1
  );
END;
$$;


--
-- TOC entry 727 (class 1255 OID 18987)
-- Name: get_monthly_revenue(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_monthly_revenue(p_months integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_result jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  SELECT jsonb_build_object(
    'success', true,
    'data', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'month_start', m.month_start::date,
            'month', EXTRACT(MONTH FROM m.month_start),
            'year', EXTRACT(YEAR FROM m.month_start),
            'amount', COALESCE(r.total, 0)
          )
          ORDER BY m.month_start
        )
        FROM generate_series(
          DATE_TRUNC('month', CURRENT_DATE) - ((p_months - 1) * INTERVAL '1 month'),
          DATE_TRUNC('month', CURRENT_DATE),
          '1 month'::interval
        ) AS m(month_start)
        LEFT JOIN (
          SELECT DATE_TRUNC('month', created_at) as month_start,
                 SUM(CASE WHEN currency = 'USDT' THEN amount * 10000 ELSE amount END) as total
          FROM public.admin_revenue
          WHERE created_at >= DATE_TRUNC('month', CURRENT_DATE) - (p_months * INTERVAL '1 month')
          GROUP BY DATE_TRUNC('month', created_at)
        ) r ON m.month_start = r.month_start
      ),
      '[]'::jsonb
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- TOC entry 719 (class 1255 OID 18976)
-- Name: get_monthly_revenue_breakdown(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_monthly_revenue_breakdown(p_year integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_year integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;
  
  v_year := COALESCE(p_year, EXTRACT(YEAR FROM now())::integer);
  
  RETURN jsonb_build_object(
    'success', true,
    'year', v_year,
    'months', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'month', month_num,
          'total', total,
          'by_type', by_type
        ) ORDER BY month_num
      ), '[]'::jsonb)
      FROM (
        SELECT 
          EXTRACT(MONTH FROM created_at)::integer as month_num,
          SUM(amount) as total,
          jsonb_object_agg(revenue_type, type_sum) as by_type
        FROM (
          SELECT 
            created_at,
            revenue_type,
            SUM(amount) OVER (PARTITION BY EXTRACT(MONTH FROM created_at), revenue_type) as type_sum,
            amount
          FROM admin_revenue
          WHERE EXTRACT(YEAR FROM created_at) = v_year
        ) sub
        GROUP BY EXTRACT(MONTH FROM created_at)
      ) monthly
    )
  );
END;
$$;


