--
-- TOC entry 896 (class 1255 OID 20166)
-- Name: get_multi_account_risk_clusters(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_multi_account_risk_clusters() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  WITH ip_pairs AS (
    SELECT
      LEAST(a.user_id, b.user_id) AS user1_id,
      GREATEST(a.user_id, b.user_id) AS user2_id,
      'shared_ip' AS indicator,
      COUNT(DISTINCT a.ip_address) AS shared_count
    FROM login_sessions a
    JOIN login_sessions b
      ON a.ip_address = b.ip_address
      AND a.user_id < b.user_id
      AND b.created_at > now() - interval '60 days'
    WHERE a.created_at > now() - interval '60 days'
    GROUP BY LEAST(a.user_id, b.user_id), GREATEST(a.user_id, b.user_id)
  ),
  fingerprint_pairs AS (
    SELECT
      LEAST(a.user_id, b.user_id) AS user1_id,
      GREATEST(a.user_id, b.user_id) AS user2_id,
      'shared_fingerprint' AS indicator,
      COUNT(DISTINCT a.fingerprint) AS shared_count
    FROM login_sessions a
    JOIN login_sessions b
      ON a.fingerprint = b.fingerprint
      AND a.fingerprint IS NOT NULL
      AND a.fingerprint != ''
      AND a.user_id < b.user_id
      AND b.created_at > now() - interval '60 days'
    WHERE a.created_at > now() - interval '60 days'
    GROUP BY LEAST(a.user_id, b.user_id), GREATEST(a.user_id, b.user_id)
  ),
  transfer_pairs AS (
    SELECT
      LEAST(ail.from_user_id, ail.to_user_id) AS user1_id,
      GREATEST(ail.from_user_id, ail.to_user_id) AS user2_id,
      'transfers' AS indicator,
      COUNT(*) AS shared_count
    FROM account_interaction_log ail
    WHERE ail.interaction_type = 'transport'
      AND ail.created_at > now() - interval '60 days'
    GROUP BY LEAST(ail.from_user_id, ail.to_user_id), GREATEST(ail.from_user_id, ail.to_user_id)
    HAVING COUNT(*) >= 2
  ),
  all_pairs AS (
    SELECT user1_id, user2_id, indicator, shared_count FROM ip_pairs
    UNION ALL
    SELECT user1_id, user2_id, indicator, shared_count FROM fingerprint_pairs
    UNION ALL
    SELECT user1_id, user2_id, indicator, shared_count FROM transfer_pairs
  ),
  pair_summary AS (
    SELECT
      ap.user1_id,
      ap.user2_id,
      p1.username AS user1_name,
      p2.username AS user2_name,
      COUNT(DISTINCT ap.indicator) AS indicator_count,
      jsonb_agg(DISTINCT jsonb_build_object(
        'type', ap.indicator,
        'count', ap.shared_count
      )) AS indicators,
      CASE
        WHEN COUNT(DISTINCT ap.indicator) >= 3 THEN 'critical'
        WHEN COUNT(DISTINCT ap.indicator) >= 2 THEN 'high'
        ELSE 'medium'
      END AS risk_level,
      LEAST(
        SUM(
          CASE ap.indicator
            WHEN 'shared_fingerprint' THEN 40 * LEAST(ap.shared_count, 5)
            WHEN 'shared_ip' THEN 25 * LEAST(ap.shared_count, 5)
            WHEN 'transfers' THEN 15 + LEAST(ap.shared_count * 2, 30)
            ELSE 10
          END
        ),
        100
      ) AS risk_score,
      EXISTS (
        SELECT 1 FROM suspicious_accounts sa
        WHERE ((sa.user_id = ap.user1_id AND sa.linked_user_id = ap.user2_id)
            OR (sa.user_id = ap.user2_id AND sa.linked_user_id = ap.user1_id))
          AND sa.is_confirmed_multi = true
      ) AS already_confirmed
    FROM all_pairs ap
    JOIN profiles p1 ON p1.id = ap.user1_id
    JOIN profiles p2 ON p2.id = ap.user2_id
    GROUP BY ap.user1_id, ap.user2_id, p1.username, p2.username
  )
  SELECT jsonb_build_object(
    'success', true,
    'clusters', COALESCE(
      (SELECT jsonb_agg(
        jsonb_build_object(
          'user1_id', ps.user1_id,
          'user2_id', ps.user2_id,
          'user1_name', ps.user1_name,
          'user2_name', ps.user2_name,
          'indicator_count', ps.indicator_count,
          'indicators', ps.indicators,
          'risk_level', ps.risk_level,
          'risk_score', ps.risk_score,
          'already_confirmed', ps.already_confirmed
        ) ORDER BY ps.risk_score DESC
      )
      FROM pair_summary ps),
      '[]'::jsonb
    ),
    'total_pairs', (SELECT COUNT(*) FROM pair_summary),
    'critical_count', (SELECT COUNT(*) FROM pair_summary WHERE risk_level = 'critical'),
    'high_count', (SELECT COUNT(*) FROM pair_summary WHERE risk_level = 'high'),
    'medium_count', (SELECT COUNT(*) FROM pair_summary WHERE risk_level = 'medium')
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- TOC entry 1093 (class 1255 OID 21553)
-- Name: get_my_hero_duel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_hero_duel(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_duel record;
  v_winner_id uuid;
  v_loser_id uuid;
  v_winner_bet integer;
  v_referrer_amount integer;
  v_company_amount integer;
  v_admin_id uuid;
  v_referrer_id uuid;
  v_winner_hp_loss integer;
  v_total_power numeric;
  v_creator_ship record;
  v_opponent_ship record;
  v_creator_power numeric;
  v_opponent_power numeric;
BEGIN
  SELECT d.*,
    cp.username AS creator_username,
    op.username AS opponent_username
  INTO v_duel
  FROM hero_duels d
  LEFT JOIN profiles cp ON cp.id = d.creator_id
  LEFT JOIN profiles op ON op.id = d.opponent_id
  WHERE (d.creator_id = p_user_id OR d.opponent_id = p_user_id)
    AND d.status IN ('waiting', 'accepted')
  ORDER BY d.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN 'null'::jsonb;
  END IF;

  -- Auto-resolve if duel is ready
  IF v_duel.status = 'accepted' AND now() >= v_duel.resolves_at THEN
    SELECT * INTO v_creator_ship FROM user_hero_ships WHERE user_id = v_duel.creator_id;
    SELECT * INTO v_opponent_ship FROM user_hero_ships WHERE user_id = v_duel.opponent_id;

    v_creator_power :=
      COALESCE(v_creator_ship.attack_points, 0) * 3 +
      COALESCE(v_creator_ship.defense_points, 0) * 2 +
      COALESCE(v_creator_ship.shield_points, 0) * 1.5 +
      COALESCE(v_creator_ship.speed_points, 0) +
      COALESCE(v_creator_ship.level, 1) * 5 +
      (GREATEST(COALESCE(v_duel.creator_hp_before, 100), 0)::numeric / GREATEST(COALESCE(v_creator_ship.hp_max, 100), 1)) * 50;

    v_opponent_power :=
      COALESCE(v_opponent_ship.attack_points, 0) * 3 +
      COALESCE(v_opponent_ship.defense_points, 0) * 2 +
      COALESCE(v_opponent_ship.shield_points, 0) * 1.5 +
      COALESCE(v_opponent_ship.speed_points, 0) +
      COALESCE(v_opponent_ship.level, 1) * 5 +
      (GREATEST(COALESCE(v_duel.opponent_hp_before, 100), 0)::numeric / GREATEST(COALESCE(v_opponent_ship.hp_max, 100), 1)) * 50;

    IF random() * (v_creator_power + v_opponent_power) <= v_creator_power THEN
      v_winner_id := v_duel.creator_id;
      v_loser_id := v_duel.opponent_id;
    ELSE
      v_winner_id := v_duel.opponent_id;
      v_loser_id := v_duel.creator_id;
    END IF;

    v_total_power := GREATEST(v_creator_power + v_opponent_power, 1);
    IF v_winner_id = v_duel.creator_id THEN
      v_winner_hp_loss := CEIL((v_opponent_power / v_total_power) * v_creator_ship.hp_max);
      UPDATE user_hero_ships SET hp = GREATEST(1, hp - v_winner_hp_loss), updated_at = now() WHERE user_id = v_winner_id;
    ELSE
      v_winner_hp_loss := CEIL((v_creator_power / v_total_power) * v_opponent_ship.hp_max);
      UPDATE user_hero_ships SET hp = GREATEST(1, hp - v_winner_hp_loss), updated_at = now() WHERE user_id = v_winner_id;
    END IF;
    UPDATE user_hero_ships SET hp = 1, updated_at = now() WHERE user_id = v_loser_id;

    PERFORM _internal_set_fxu_context();

    v_winner_bet := CEIL(v_duel.stake * 80 / 100);
    UPDATE profiles SET fxu_balance = fxu_balance + v_duel.stake + v_winner_bet WHERE id = v_winner_id;

    v_company_amount := v_duel.stake - v_winner_bet;

    SELECT referred_by INTO v_referrer_id FROM profiles WHERE id = v_winner_id;
    IF v_referrer_id IS NOT NULL THEN
      v_referrer_amount := CEIL(v_duel.stake * 5 / 100);
      v_company_amount := v_company_amount - v_referrer_amount;
      IF v_referrer_amount > 0 THEN
        UPDATE profiles SET fxu_balance = fxu_balance + v_referrer_amount WHERE id = v_referrer_id;
      END IF;
    END IF;

    IF v_company_amount > 0 THEN
      v_admin_id := get_admin_account_id();
      IF v_admin_id IS NOT NULL THEN
        UPDATE profiles SET fxu_balance = fxu_balance + CEIL(v_company_amount / 2) WHERE id = v_admin_id;
      END IF;
      PERFORM record_admin_revenue('hero_duel', v_company_amount, 'Duelo galactico - ganador: ' || v_winner_id::text, v_loser_id, v_duel.id);
      PERFORM contribute_to_jackpot((v_company_amount / 2)::numeric, 'hero_duel', v_winner_id);
    END IF;

    UPDATE hero_duels SET status = 'completed', winner_id = v_winner_id, loser_id = v_loser_id, updated_at = now() WHERE id = v_duel.id;

    RETURN jsonb_build_object(
      'id', v_duel.id,
      'status', 'completed',
      'stake', v_duel.stake,
      'winner_id', v_winner_id,
      'loser_id', v_loser_id,
      'winner_amount', v_duel.stake + v_winner_bet,
      'creator_username', v_duel.creator_username,
      'opponent_username', v_duel.opponent_username
    );
  END IF;

  RETURN jsonb_build_object(
    'id', v_duel.id,
    'status', v_duel.status,
    'stake', v_duel.stake,
    'creator_id', v_duel.creator_id,
    'creator_username', v_duel.creator_username,
    'creator_level', v_duel.creator_level_before,
    'opponent_id', v_duel.opponent_id,
    'opponent_username', v_duel.opponent_username,
    'opponent_level', v_duel.opponent_level_before,
    'is_creator', (v_duel.creator_id = p_user_id),
    'created_at', v_duel.created_at::text,
    'accepted_at', COALESCE(v_duel.accepted_at::text, NULL),
    'resolves_at', COALESCE(v_duel.resolves_at::text, NULL),
    'remaining_seconds', CASE WHEN v_duel.resolves_at IS NOT NULL
      THEN GREATEST(0, EXTRACT(EPOCH FROM (v_duel.resolves_at - now())))::integer
      ELSE NULL END
  );
END;
$$;


--
-- TOC entry 989 (class 1255 OID 20674)
-- Name: get_my_market_fee(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_market_fee() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_fee numeric;
  v_is_plus boolean;
  v_rank integer;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('fee_percent', 30, 'is_plus', false, 'rank', 9999);
  END IF;
  
  v_is_plus := is_user_plus(v_user_id);
  
  SELECT COALESCE(rank_position, 9999) INTO v_rank
  FROM profiles WHERE id = v_user_id;
  
  v_fee := get_market_fee_for_user(v_user_id);
  
  RETURN jsonb_build_object(
    'fee_percent', v_fee,
    'is_plus', v_is_plus,
    'rank', v_rank
  );
END;
$$;


--
-- TOC entry 1135 (class 1255 OID 22244)
-- Name: get_my_monthly_market_sales(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_monthly_market_sales() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id uuid;
  v_year_week text;
  v_metal_sold bigint := 0;
  v_crystal_sold bigint := 0;
  v_deuterium_sold bigint := 0;
  v_limit_metal bigint := 0;
  v_limit_crystal bigint := 0;
  v_limit_deuterium bigint := 0;
  v_active_metal bigint := 0;
  v_active_crystal bigint := 0;
  v_active_deuterium bigint := 0;
  v_total_metal bigint;
  v_total_crystal bigint;
  v_total_deuterium bigint;
  v_limits RECORD;
  v_is_plus boolean;
  v_limit_enabled boolean;
  v_fxu_spent numeric := 0;
  v_fxu_earned numeric := 0;
  v_fxu_limit numeric := 0;
  v_fxu_value_sold numeric := 0;
  v_fxu_value_active numeric := 0;
  v_fxu_remaining numeric;
  v_has_credit boolean := false;
  v_fxu_exhausted boolean := false;
  v_ships_value_sold bigint := 0;
  v_active_ships_value bigint := 0;
  v_ships_value_remaining bigint;
  v_user_points bigint := 0;
  v_monthly_limit bigint := 0;
  v_week_reset timestamp;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  v_year_week := to_char(now(), 'IYYY-"W"IW');

  -- Get limits config
  SELECT * INTO v_limits FROM market_resource_limits WHERE id = 1;
  v_limit_enabled := COALESCE(v_limits.monthly_limit_enabled, false);
  v_limit_metal := COALESCE(v_limits.monthly_limit_metal, 0);
  v_limit_crystal := COALESCE(v_limits.monthly_limit_crystal, 0);
  v_limit_deuterium := COALESCE(v_limits.monthly_limit_deuterium, 0);

  -- Check VIP Plus
  v_is_plus := is_user_plus(v_user_id);

  -- Get completed sales this week
  SELECT COALESCE(metal_sold,0), COALESCE(crystal_sold,0), COALESCE(deuterium_sold,0),
         COALESCE(fxu_value_sold,0), COALESCE(ships_value_sold,0)
  INTO v_metal_sold, v_crystal_sold, v_deuterium_sold, v_fxu_value_sold, v_ships_value_sold
  FROM market_monthly_sales WHERE user_id = v_user_id AND year_month = v_year_week;

  -- Get active listings
  SELECT COALESCE(SUM(CASE WHEN item_code='metal' THEN quantity ELSE 0 END),0),
         COALESCE(SUM(CASE WHEN item_code='crystal' THEN quantity ELSE 0 END),0),
         COALESCE(SUM(CASE WHEN item_code='deuterium' THEN quantity ELSE 0 END),0)
  INTO v_active_metal, v_active_crystal, v_active_deuterium
  FROM market_listings WHERE seller_id = v_user_id AND listing_type = 'resource' AND status = 'active'
  AND created_at >= date_trunc('week', now());

  -- Active ships value
  SELECT COALESCE(SUM(ml.quantity * (COALESCE(st.metal_cost,0) + COALESCE(st.crystal_cost,0) + COALESCE(st.deuterium_cost,0))), 0)
  INTO v_active_ships_value
  FROM market_listings ml JOIN ship_types st ON st.code = ml.item_code
  WHERE ml.seller_id = v_user_id AND ml.listing_type = 'ship' AND ml.status = 'active'
    AND ml.created_at >= date_trunc('week', now());

  -- Active FXU value
  SELECT COALESCE(SUM(ml.quantity * ml.price_per_unit), 0) INTO v_fxu_value_active
  FROM market_listings ml
  WHERE ml.seller_id = v_user_id AND ml.status = 'active'
    AND ml.listing_type IN ('resource', 'ship')
    AND ml.created_at >= date_trunc('week', now());

  v_total_metal := v_metal_sold + v_active_metal;
  v_total_crystal := v_crystal_sold + v_active_crystal;
  v_total_deuterium := v_deuterium_sold + v_active_deuterium;

  -- Calculate FXU limit and credit
  v_fxu_limit := calculate_fxu_weekly_limit(v_user_id);
  v_fxu_remaining := v_fxu_limit - v_fxu_value_sold - v_fxu_value_active;
  v_has_credit := v_fxu_limit > 0;
  v_fxu_exhausted := v_has_credit AND v_fxu_remaining <= 0;

  -- Calculate monthly limit based on points
  v_monthly_limit := calculate_monthly_market_limit(v_user_id);
  SELECT COALESCE(points_total, 0) INTO v_user_points FROM profiles WHERE id = v_user_id;

  -- Ships value remaining
  v_ships_value_remaining := v_monthly_limit - v_ships_value_sold - v_active_ships_value;

  -- Week reset: next Monday midnight UTC
  v_week_reset := date_trunc('week', now()) + interval '7 days';

  RETURN jsonb_build_object(
    'success', true,
    'monthly_limit_enabled', v_limit_enabled,
    'vip_unlimited', v_is_plus,
    'year_month', v_year_week,
    'monthly_limit', v_monthly_limit,
    'user_points', v_user_points,
    'fxu_spent', 0,
    'fxu_earned', 0,
    'fxu_credit', v_fxu_limit,
    'fxu_limit', v_fxu_limit,
    'fxu_value_sold', v_fxu_value_sold,
    'fxu_value_remaining', GREATEST(0, v_fxu_remaining),
    'has_credit', v_has_credit,
    'fxu_exhausted', v_fxu_exhausted,
    'metal_sold', v_total_metal,
    'crystal_sold', v_total_crystal,
    'deuterium_sold', v_total_deuterium,
    'metal_completed', v_metal_sold,
    'crystal_completed', v_crystal_sold,
    'deuterium_completed', v_deuterium_sold,
    'metal_active', v_active_metal,
    'crystal_active', v_active_crystal,
    'deuterium_active', v_active_deuterium,
    'metal_limit', v_limit_metal,
    'crystal_limit', v_limit_crystal,
    'deuterium_limit', v_limit_deuterium,
    'metal_remaining', GREATEST(0, v_limit_metal - v_total_metal),
    'crystal_remaining', GREATEST(0, v_limit_crystal - v_total_crystal),
    'deuterium_remaining', GREATEST(0, v_limit_deuterium - v_total_deuterium),
    'ships_value_sold', v_ships_value_sold + v_active_ships_value,
    'ships_value_remaining', GREATEST(0, v_ships_value_remaining),
    'week_resets_at', to_char(v_week_reset, 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$$;


--
-- TOC entry 840 (class 1255 OID 19897)
-- Name: get_my_pending_plus_rewards(); Type: FUNCTION; Schema: public; Owner: -
