--
-- TOC entry 1065 (class 1255 OID 21346)
-- Name: get_p2p_reputations_for_users(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_p2p_reputations_for_users(p_user_ids uuid[]) RETURNS TABLE(user_id uuid, total_orders integer, completed_orders integer, abandoned_orders integer, success_rate numeric, rating_avg numeric, rating_count integer, is_banned boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    p.id,
    COALESCE(r.total_orders, 0),
    COALESCE(r.completed_orders, 0),
    COALESCE(r.abandoned_orders, 0),
    CASE
      WHEN COALESCE(r.completed_orders,0) + COALESCE(r.abandoned_orders,0) + COALESCE(r.lost_disputes,0) > 0
        THEN round(
               (r.completed_orders::numeric * 100
                / (r.completed_orders + COALESCE(r.abandoned_orders,0) + COALESCE(r.lost_disputes,0)))
             ::numeric, 1)
      ELSE 0
    END,
    CASE WHEN COALESCE(r.rating_count,0) > 0
         THEN round((r.rating_sum::numeric / r.rating_count)::numeric, 2)
         ELSE 0 END,
    COALESCE(r.rating_count, 0),
    COALESCE(r.is_banned, false)
  FROM profiles p
  LEFT JOIN p2p_reputation r ON r.user_id = p.id
  WHERE p.id = ANY(p_user_ids);
$$;


--
-- TOC entry 7777 (class 0 OID 0)
-- Dependencies: 1065
-- Name: FUNCTION get_p2p_reputations_for_users(p_user_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_p2p_reputations_for_users(p_user_ids uuid[]) IS 'Batch reputación pública: success_rate = completed / (completed + abandoned + lost_disputes). Incluye rating promedio y abandonos.';


--
-- TOC entry 1042 (class 1255 OID 21244)
-- Name: get_p2p_user_reputation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_p2p_user_reputation(p_user_id uuid) RETURNS TABLE(user_id uuid, username text, total_orders integer, completed_orders integer, cancelled_orders integer, disputed_orders integer, lost_disputes integer, success_rate numeric, avg_release_minutes numeric, rating_avg numeric, rating_count integer, is_banned boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
    SELECT
      p.id,
      p.username,
      COALESCE(r.total_orders, 0),
      COALESCE(r.completed_orders, 0),
      COALESCE(r.cancelled_orders, 0),
      COALESCE(r.disputed_orders, 0),
      COALESCE(r.lost_disputes, 0),
      CASE WHEN COALESCE(r.total_orders,0) > 0
           THEN round((r.completed_orders::numeric * 100 / r.total_orders)::numeric, 1)
           ELSE 0 END,
      CASE WHEN COALESCE(r.avg_release_seconds,0) > 0
           THEN round((r.avg_release_seconds::numeric / 60)::numeric, 1)
           ELSE 0 END,
      CASE WHEN COALESCE(r.rating_count,0) > 0
           THEN round((r.rating_sum::numeric / r.rating_count)::numeric, 2)
           ELSE 0 END,
      COALESCE(r.rating_count, 0),
      COALESCE(r.is_banned, false)
    FROM profiles p
    LEFT JOIN p2p_reputation r ON r.user_id = p.id
    WHERE p.id = p_user_id;
END;
$$;


--
-- TOC entry 686 (class 1255 OID 18880)
-- Name: get_pending_withdrawal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_withdrawal(p_tx_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tx wallet_transactions%ROWTYPE;
  v_config wallet_config%ROWTYPE;
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_tx FROM wallet_transactions 
  WHERE id = p_tx_id AND user_id = v_user_id;
  
  IF v_tx.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction not found');
  END IF;

  SELECT * INTO v_config FROM wallet_config WHERE id = 1;

  RETURN jsonb_build_object(
    'success', true,
    'tx_id', v_tx.id,
    'status', v_tx.status,
    'amount', v_tx.amount,
    'fxu_amount', v_tx.fxu_amount,
    'wallet_address', v_tx.wallet_address,
    'signature_data', v_tx.signature_data,
    'signature_expiry', v_tx.signature_expiry,
    'contract_tx_hash', v_tx.contract_tx_hash,
    'contract_address', v_config.contract_address,
    'chain_id', v_config.chain_id,
    'created_at', v_tx.created_at
  );
END;
$$;


--
-- TOC entry 1153 (class 1255 OID 22405)
-- Name: get_planet_deposits(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_planet_deposits(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet RECORD;
  v_result jsonb;
BEGIN
  SELECT id, is_main_planet, planet_status,
         metal_deposit, crystal_deposit, deuterium_deposit,
         metal_initial_deposit, crystal_initial_deposit, deuterium_initial_deposit,
         depleted_at, regenerates_at,
         fields_max, fields_used, position
  INTO v_planet
  FROM planets WHERE id = p_planet_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not found');
  END IF;
  
  v_result := jsonb_build_object(
    'success', true,
    'is_main_planet', v_planet.is_main_planet,
    'planet_status', v_planet.planet_status,
    'metal_deposit', v_planet.metal_deposit,
    'crystal_deposit', v_planet.crystal_deposit,
    'deuterium_deposit', v_planet.deuterium_deposit,
    'depleted_at', v_planet.depleted_at,
    'regenerates_at', v_planet.regenerates_at,
    'position', v_planet.position
  );
  
  -- Calculate percentages from ACTUAL initial deposits
  IF v_planet.metal_initial_deposit IS NOT NULL AND v_planet.metal_initial_deposit > 0 THEN
    v_result := jsonb_set(v_result, '{metal_deposit_pct}', 
      to_jsonb(ROUND((v_planet.metal_deposit::numeric / v_planet.metal_initial_deposit::numeric) * 100, 1)));
  ELSE
    v_result := jsonb_set(v_result, '{metal_deposit_pct}', 'null'::jsonb);
  END IF;
  
  IF v_planet.crystal_initial_deposit IS NOT NULL AND v_planet.crystal_initial_deposit > 0 THEN
    v_result := jsonb_set(v_result, '{crystal_deposit_pct}', 
      to_jsonb(ROUND((v_planet.crystal_deposit::numeric / v_planet.crystal_initial_deposit::numeric) * 100, 1)));
  ELSE
    v_result := jsonb_set(v_result, '{crystal_deposit_pct}', 'null'::jsonb);
  END IF;
  
  IF v_planet.deuterium_initial_deposit IS NOT NULL AND v_planet.deuterium_initial_deposit > 0 THEN
    v_result := jsonb_set(v_result, '{deuterium_deposit_pct}', 
      to_jsonb(ROUND((v_planet.deuterium_deposit::numeric / v_planet.deuterium_initial_deposit::numeric) * 100, 1)));
  ELSE
    v_result := jsonb_set(v_result, '{deuterium_deposit_pct}', 'null'::jsonb);
  END IF;
  
  RETURN v_result;
END;
$$;


