--
-- TOC entry 718 (class 1255 OID 18975)
-- Name: get_platform_financial_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_platform_financial_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_user_fxu numeric;
  v_total_user_usdt numeric;
  v_total_deposits_fxu numeric;
  v_total_deposits_usdt numeric;
  v_total_withdrawals_fxu numeric;
  v_total_withdrawals_usdt numeric;
  v_pending_withdrawals_fxu numeric;
  v_pending_withdrawals_usdt numeric;
  v_total_admin_revenue numeric;
  v_total_admin_expenses numeric;
  v_month_revenue numeric;
  v_year_revenue numeric;
  v_admin_available numeric;
  v_current_month integer;
  v_current_year integer;
BEGIN
  IF NOT is_current_user_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  SELECT COALESCE(SUM(fxu_balance), 0) INTO v_total_user_fxu
  FROM profiles
  WHERE is_admin = false OR is_admin IS NULL;

  SELECT COALESCE(SUM(usdt_balance), 0) INTO v_total_user_usdt
  FROM profiles
  WHERE is_admin = false OR is_admin IS NULL;

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_total_deposits_fxu
  FROM wallet_transactions
  WHERE tx_type = 'deposit' AND status = 'confirmed' AND (token_type = 'TUNG' OR token_type IS NULL);

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_total_deposits_usdt
  FROM wallet_transactions
  WHERE tx_type = 'deposit' AND status = 'confirmed' AND token_type = 'USDT';

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_total_withdrawals_fxu
  FROM wallet_transactions
  WHERE tx_type = 'withdrawal' AND status = 'confirmed' AND (token_type = 'TUNG' OR token_type IS NULL);

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_total_withdrawals_usdt
  FROM wallet_transactions
  WHERE tx_type = 'withdrawal' AND status = 'confirmed' AND token_type = 'USDT';

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_pending_withdrawals_fxu
  FROM wallet_transactions
  WHERE tx_type = 'withdrawal' AND status = 'pending' AND (token_type = 'TUNG' OR token_type IS NULL);

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_pending_withdrawals_usdt
  FROM wallet_transactions
  WHERE tx_type = 'withdrawal' AND status = 'pending' AND token_type = 'USDT';

  SELECT COALESCE(SUM(CASE WHEN currency = 'USDT' THEN amount * 10000 ELSE amount END), 0)
  INTO v_total_admin_revenue
  FROM admin_revenue;

  SELECT COALESCE(SUM(amount), 0) INTO v_total_admin_expenses
  FROM admin_expenses;

  v_current_month := EXTRACT(MONTH FROM CURRENT_DATE);
  v_current_year := EXTRACT(YEAR FROM CURRENT_DATE);

  SELECT COALESCE(SUM(CASE WHEN currency = 'USDT' THEN amount * 10000 ELSE amount END), 0)
  INTO v_month_revenue
  FROM admin_revenue
  WHERE EXTRACT(MONTH FROM created_at) = v_current_month
    AND EXTRACT(YEAR FROM created_at) = v_current_year;

  SELECT COALESCE(SUM(CASE WHEN currency = 'USDT' THEN amount * 10000 ELSE amount END), 0)
  INTO v_year_revenue
  FROM admin_revenue
  WHERE EXTRACT(YEAR FROM created_at) = v_current_year;

  v_admin_available := get_admin_available_balance();

  RETURN jsonb_build_object(
    'success', true,
    'total_user_fxu', v_total_user_fxu,
    'total_user_usdt', v_total_user_usdt,
    'total_deposits', v_total_deposits_fxu,
    'total_withdrawals', v_total_withdrawals_fxu,
    'pending_withdrawals', v_pending_withdrawals_fxu,
    'total_deposits_usdt', v_total_deposits_usdt,
    'total_withdrawals_usdt', v_total_withdrawals_usdt,
    'pending_withdrawals_usdt', v_pending_withdrawals_usdt,
    'total_admin_revenue', v_total_admin_revenue,
    'total_admin_expenses', v_total_admin_expenses,
    'month_revenue', v_month_revenue,
    'year_revenue', v_year_revenue,
    'admin_available_balance', v_admin_available,
    'current_month', v_current_month,
    'current_year', v_current_year
  );
END;
$$;


--
-- TOC entry 837 (class 1255 OID 19860)
-- Name: get_plus_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_plus_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_subscription plus_subscriptions%ROWTYPE;
  v_plan plus_plans%ROWTYPE;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('is_plus', false);
  END IF;

  SELECT * INTO v_subscription 
  FROM plus_subscriptions 
  WHERE user_id = v_user_id AND is_active = true AND expires_at > now()
  ORDER BY expires_at DESC
  LIMIT 1;

  IF v_subscription.id IS NULL THEN
    RETURN jsonb_build_object('is_plus', false);
  END IF;

  SELECT * INTO v_plan FROM plus_plans WHERE id = v_subscription.plan_id;

  RETURN jsonb_build_object(
    'is_plus', true,
    'plan_name', v_plan.name,
    'expires_at', v_subscription.expires_at,
    'commission_share', v_subscription.commission_share_percent,
    'total_earned', v_subscription.total_commissions_received
  );
END;
$$;


--
-- TOC entry 1138 (class 1255 OID 22249)
-- Name: get_premium_missions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_premium_missions() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_result jsonb;
BEGIN
  v_uid := auth.uid();
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', dm.id,
    'code', dm.code,
    'title_es', dm.title_es,
    'description_es', dm.desc_es,
    'mission_type', dm.mission_type,
    'target_count', dm.target_count,
    'reward_type', dm.reward_type,
    'reward_value', dm.reward_value,
    'reward_duration_hours', dm.reward_duration_hours,
    'cost_fxu', dm.cost_fxu,
    'icon', dm.icon,
    'is_active', dm.is_active
  ) ORDER BY dm.cost_fxu ASC), '[]'::jsonb) INTO v_result
  FROM daily_missions dm
  WHERE dm.is_active = true AND dm.cost_fxu > 0;
  RETURN v_result;
END;
$$;


--
-- TOC entry 951 (class 1255 OID 20452)
-- Name: get_public_game_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_game_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '5s'
    AS $$
DECLARE
  v_total_players bigint;
  v_ranked_players bigint;
  v_total_deposited numeric;
  v_total_withdrawn numeric;
  v_market_transactions bigint;
  v_market_volume_usdt numeric;
  v_expedition_pool_fxu numeric;
  v_monthly_pool_fxu numeric;
BEGIN
  -- Total registered players
  SELECT COUNT(*) INTO v_total_players
  FROM profiles
  WHERE COALESCE(is_banned, false) = false;

  -- Players with points (active in ranking)
  SELECT COUNT(*) INTO v_ranked_players
  FROM profiles
  WHERE COALESCE(is_banned, false) = false
    AND COALESCE(points_total, 0) > 0;

  -- Total USDT deposited (confirmed, USDT only — matches admin dashboard)
  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_total_deposited
  FROM wallet_transactions
  WHERE tx_type = 'deposit' AND status = 'confirmed' AND token_type = 'USDT';

  -- Total USDT withdrawn (confirmed, USDT only — matches admin dashboard)
  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_total_withdrawn
  FROM wallet_transactions
  WHERE tx_type = 'withdrawal' AND status = 'confirmed' AND token_type = 'USDT';

  -- Total P2P market transactions
  SELECT COUNT(*), COALESCE(SUM(total_price), 0) * 0.0001
  INTO v_market_transactions, v_market_volume_usdt
  FROM market_transactions;

  -- Jackpot pools
  SELECT COALESCE(expedition_balance, 0), COALESCE(monthly_balance, 0)
  INTO v_expedition_pool_fxu, v_monthly_pool_fxu
  FROM jackpot_pools WHERE id = 1;

  RETURN jsonb_build_object(
    'total_players', v_total_players,
    'ranked_players', v_ranked_players,
    'total_deposited', ROUND(v_total_deposited, 2),
    'total_withdrawn', ROUND(v_total_withdrawn, 2),
    'market_transactions', v_market_transactions,
    'market_volume_usdt', ROUND(v_market_volume_usdt, 2),
    'expedition_pool_fxu', ROUND(v_expedition_pool_fxu, 3),
    'monthly_pool_fxu', ROUND(v_monthly_pool_fxu, 3),
    'total_jackpot_fxu', ROUND(v_expedition_pool_fxu + v_monthly_pool_fxu, 3)
  );
END;
$$;


--
-- TOC entry 651 (class 1255 OID 18709)
-- Name: get_rankings(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_rankings(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(rank bigint, user_id uuid, username text, alliance_tag text, total_points bigint, economy_points bigint, research_points bigint, military_points bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    ROW_NUMBER() OVER (ORDER BY p.total_points DESC) as rank,
    p.id as user_id,
    p.username,
    a.tag as alliance_tag,
    p.total_points,
    p.economy_points,
    p.research_points,
    p.military_points
  FROM profiles p
  LEFT JOIN alliance_members am ON am.user_id = p.id
  LEFT JOIN alliances a ON a.id = am.alliance_id
  WHERE (p.is_hidden = false OR p.is_hidden IS NULL)
    AND (p.is_admin = false OR p.is_admin IS NULL)
  ORDER BY p.total_points DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


--
-- TOC entry 721 (class 1255 OID 18978)
-- Name: get_recent_revenue(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recent_revenue(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '10s'
    AS $$
BEGIN
  IF NOT is_current_user_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  RETURN jsonb_build_object('success', true, 'revenues', (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    FROM (
      SELECT
        ar.id,
        ar.revenue_type as type,
        ar.amount,
        ar.currency,
        CASE WHEN ar.currency = 'USDT' THEN ar.amount * 10000 ELSE ar.amount END AS amount_fxu,
        ar.description,
        p.username,
        ar.created_at
      FROM public.admin_revenue ar
      LEFT JOIN public.profiles p ON p.id = ar.related_user_id
      ORDER BY ar.created_at DESC
      LIMIT p_limit
    ) t
  ));
END;
$$;


