--
-- TOC entry 638 (class 1255 OID 18640)
-- Name: get_referral_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_referral_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_referral_code text;
  v_total_referrals int;
  v_total_fxu numeric;
  v_total_metal numeric;
  v_total_crystal numeric;
  v_total_deuterium numeric;
  v_recent_commissions jsonb;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT referral_code INTO v_referral_code FROM profiles WHERE id = v_user_id;

  IF v_referral_code IS NULL THEN
    v_referral_code := UPPER(SUBSTRING(v_user_id::text, 1, 8));
    UPDATE profiles SET referral_code = v_referral_code WHERE id = v_user_id;
  END IF;

  SELECT COUNT(*) INTO v_total_referrals FROM profiles WHERE referred_by = v_user_id;

  SELECT
    COALESCE(SUM(CASE WHEN commission_type = 'fxu' THEN fxu_amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN commission_type = 'resource' AND resource_type = 'metal' THEN amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN commission_type = 'resource' AND resource_type = 'crystal' THEN amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN commission_type = 'resource' AND resource_type = 'deuterium' THEN amount ELSE 0 END), 0)
  INTO v_total_fxu, v_total_metal, v_total_crystal, v_total_deuterium
  FROM referral_commissions
  WHERE referrer_id = v_user_id;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', rc.id,
        'amount', CASE WHEN rc.commission_type = 'fxu' THEN rc.fxu_amount ELSE rc.amount END,
        'commission_type', rc.commission_type,
        'resource_type', rc.resource_type,
        'created_at', rc.created_at,
        'seller_username', p.username
      ) ORDER BY rc.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_recent_commissions
  FROM referral_commissions rc
  JOIN profiles p ON p.id = rc.seller_id
  WHERE rc.referrer_id = v_user_id
  LIMIT 20;

  RETURN jsonb_build_object(
    'success', true,
    'referral_code', v_referral_code,
    'total_referrals', v_total_referrals,
    'total_fxu', v_total_fxu,
    'total_metal', v_total_metal,
    'total_crystal', v_total_crystal,
    'total_deuterium', v_total_deuterium,
    'recent_commissions', v_recent_commissions
  );
END;
$$;


--
-- TOC entry 1001 (class 1255 OID 20844)
-- Name: get_rename_costs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_rename_costs() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet_cost integer;
  v_alliance_cost integer;
  v_create_alliance_cost integer;
  v_is_plus boolean;
BEGIN
  SELECT COALESCE(value::integer, 100) INTO v_planet_cost
  FROM game_settings WHERE key = 'fxu_rename_planet_cost';
  IF v_planet_cost IS NULL THEN v_planet_cost := 100; END IF;

  SELECT COALESCE(value::integer, 1000) INTO v_alliance_cost
  FROM game_settings WHERE key = 'fxu_rename_alliance_cost';
  IF v_alliance_cost IS NULL THEN v_alliance_cost := 1000; END IF;

  SELECT COALESCE(value::integer, 1000) INTO v_create_alliance_cost
  FROM game_settings WHERE key = 'fxu_create_alliance_cost';
  IF v_create_alliance_cost IS NULL THEN v_create_alliance_cost := 1000; END IF;

  v_is_plus := is_user_plus(auth.uid());

  RETURN jsonb_build_object(
    'planet_cost', v_planet_cost,
    'alliance_cost', v_alliance_cost,
    'create_alliance_cost', v_create_alliance_cost,
    'planet_cost_vip', CEIL(v_planet_cost * 0.50),
    'alliance_cost_vip', CEIL(v_alliance_cost * 0.50),
    'create_alliance_cost_vip', CEIL(v_create_alliance_cost * 0.50),
    'is_vip', v_is_plus
  );
END;
$$;


