--
-- TOC entry 877 (class 1255 OID 20052)
-- Name: get_stuck_items_diagnostics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stuck_items_diagnostics() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_building_count integer;
  v_shipyard_count integer;
  v_fleet_count integer;
  v_research_count integer;
BEGIN
  SELECT auth.uid() INTO v_user_id;
  
  IF v_user_id IS NOT NULL THEN
    SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
    IF NOT COALESCE(v_is_admin, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
    END IF;
  END IF;

  SELECT COUNT(*) INTO v_building_count
  FROM building_queue
  WHERE end_time IS NOT NULL AND end_time <= NOW();

  SELECT COUNT(*) INTO v_shipyard_count
  FROM shipyard_queue
  WHERE current_unit_end_time IS NOT NULL AND current_unit_end_time <= NOW();

  SELECT COUNT(*) INTO v_fleet_count
  FROM fleets
  WHERE is_completed = false
    AND (
      (NOT COALESCE(is_returning, false) AND arrival_time IS NOT NULL AND arrival_time <= NOW())
      OR
      (COALESCE(is_returning, false) AND return_time IS NOT NULL AND return_time <= NOW())
    );

  SELECT COUNT(*) INTO v_research_count
  FROM user_technologies
  WHERE is_researching = true
    AND research_end_time IS NOT NULL
    AND research_end_time <= NOW();

  RETURN jsonb_build_object(
    'success', true,
    'stuck_buildings', v_building_count,
    'stuck_shipyard', v_shipyard_count,
    'stuck_fleets', v_fleet_count,
    'stuck_research', v_research_count,
    'checked_at', NOW()
  );
END;
$$;


--
-- TOC entry 769 (class 1255 OID 19272)
-- Name: get_suspicious_interactions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_suspicious_interactions() RETURNS TABLE(from_user_id uuid, from_username text, to_user_id uuid, to_username text, total_sent_metal numeric, total_sent_crystal numeric, total_sent_deuterium numeric, total_received_metal numeric, total_received_crystal numeric, total_received_deuterium numeric, transfer_count bigint, suspicion_score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  
  RETURN QUERY
  WITH sent AS (
    SELECT 
      ail.from_user_id,
      ail.to_user_id,
      SUM(ail.metal_amount) as total_metal,
      SUM(ail.crystal_amount) as total_crystal,
      SUM(ail.deuterium_amount) as total_deuterium,
      COUNT(*) as cnt
    FROM account_interaction_log ail
    WHERE ail.interaction_type = 'transport'
      AND ail.created_at > now() - interval '30 days'
    GROUP BY ail.from_user_id, ail.to_user_id
  ),
  received AS (
    SELECT 
      ail.to_user_id as from_user_id,
      ail.from_user_id as to_user_id,
      SUM(ail.metal_amount) as total_metal,
      SUM(ail.crystal_amount) as total_crystal,
      SUM(ail.deuterium_amount) as total_deuterium
    FROM account_interaction_log ail
    WHERE ail.interaction_type = 'transport'
      AND ail.created_at > now() - interval '30 days'
    GROUP BY ail.to_user_id, ail.from_user_id
  )
  SELECT 
    s.from_user_id,
    p1.username as from_username,
    s.to_user_id,
    p2.username as to_username,
    s.total_metal as total_sent_metal,
    s.total_crystal as total_sent_crystal,
    s.total_deuterium as total_sent_deuterium,
    COALESCE(r.total_metal, 0) as total_received_metal,
    COALESCE(r.total_crystal, 0) as total_received_crystal,
    COALESCE(r.total_deuterium, 0) as total_received_deuterium,
    s.cnt as transfer_count,
    CASE 
      WHEN COALESCE(r.total_metal, 0) + COALESCE(r.total_crystal, 0) + COALESCE(r.total_deuterium, 0) = 0 
      THEN 100
      ELSE ROUND(
        (s.total_metal + s.total_crystal + s.total_deuterium) / 
        NULLIF(COALESCE(r.total_metal, 0) + COALESCE(r.total_crystal, 0) + COALESCE(r.total_deuterium, 0), 0) * 10,
        2
      )
    END as suspicion_score
  FROM sent s
  JOIN profiles p1 ON p1.id = s.from_user_id
  JOIN profiles p2 ON p2.id = s.to_user_id
  LEFT JOIN received r ON r.from_user_id = s.from_user_id AND r.to_user_id = s.to_user_id
  WHERE s.cnt >= 3
  ORDER BY suspicion_score DESC NULLS LAST
  LIMIT 100;
END;
$$;


