--

CREATE FUNCTION public.get_table_columns_detail() RETURNS TABLE(tbl_name text, col_name text, col_position integer, col_default text, is_nullable text, data_type text, char_max_length integer, numeric_precision integer, numeric_scale integer, udt_name text, is_identity text, identity_generation text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    c.table_name::text,
    c.column_name::text,
    c.ordinal_position::integer,
    c.column_default::text,
    c.is_nullable::text,
    c.data_type::text,
    c.character_maximum_length::integer,
    c.numeric_precision::integer,
    c.numeric_scale::integer,
    c.udt_name::text,
    c.is_identity::text,
    c.identity_generation::text
  FROM information_schema.columns c
  WHERE c.table_schema = 'public'
  ORDER BY c.table_name, c.ordinal_position;
$$;


--
-- TOC entry 801 (class 1255 OID 19470)
-- Name: get_telegram_task_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_telegram_task_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_link telegram_links%ROWTYPE;
  v_reward telegram_task_rewards%ROWTYPE;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_link FROM telegram_links WHERE user_id = v_user_id;
  
  IF v_link IS NULL OR v_link.telegram_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'telegram_linked', false,
      'task_completed', false,
      'is_member', false
    );
  END IF;

  SELECT * INTO v_reward 
  FROM telegram_task_rewards 
  WHERE user_id = v_user_id AND task_type = 'join_group';

  RETURN jsonb_build_object(
    'success', true,
    'telegram_linked', true,
    'telegram_username', v_link.telegram_username,
    'task_completed', COALESCE(v_reward.reward_claimed, false),
    'is_member', COALESCE(v_reward.is_member, false),
    'reward_amount', COALESCE(v_reward.reward_amount, 50),
    'reward_revoked', COALESCE(v_reward.reward_revoked, false)
  );
END;
$$;


--
-- TOC entry 916 (class 1255 OID 20337)
-- Name: get_transfer_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_transfer_history() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_transfers jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT COALESCE(jsonb_agg(t ORDER BY t.created_at DESC), '[]'::jsonb) INTO v_transfers
  FROM (
    SELECT
      it.id,
      it.token_type,
      it.gross_amount,
      it.fee_amount,
      it.net_amount,
      it.fee_percent,
      it.created_at,
      CASE WHEN it.sender_id = v_user_id THEN 'sent' ELSE 'received' END AS direction,
      CASE WHEN it.sender_id = v_user_id THEN rp.username ELSE sp.username END AS other_user
    FROM internal_transfers it
    JOIN profiles sp ON sp.id = it.sender_id
    JOIN profiles rp ON rp.id = it.receiver_id
    WHERE it.sender_id = v_user_id OR it.receiver_id = v_user_id
    ORDER BY it.created_at DESC
    LIMIT 50
  ) t;

  RETURN jsonb_build_object('success', true, 'transfers', v_transfers);
END;
$$;


--
-- TOC entry 957 (class 1255 OID 20555)
-- Name: get_twitter_social_ranking(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_twitter_social_ranking(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ranking jsonb;
  v_reset_at timestamptz;
BEGIN
  -- Obtener fecha del último reinicio del ranking
  SELECT ranking_reset_at INTO v_reset_at FROM twitter_social_config LIMIT 1;
  
  IF v_reset_at IS NULL THEN
    v_reset_at := '1970-01-01'::timestamptz;
  END IF;

  SELECT jsonb_agg(row_data ORDER BY total_points DESC)
  INTO v_ranking
  FROM (
    SELECT jsonb_build_object(
      'user_id', tl.user_id,
      'twitter_username', tl.twitter_username,
      'username', p.username,
      'total_points', COALESCE(SUM(ta.points_awarded), 0),
      'total_actions', COUNT(ta.id) FILTER (WHERE ta.points_awarded > 0),
      'quote_tweets', COUNT(ta.id) FILTER (WHERE ta.action_type = 'quote_tweet' AND ta.points_awarded > 0),
      'comments', COUNT(ta.id) FILTER (WHERE ta.action_type = 'comment' AND ta.points_awarded > 0)
    ) as row_data,
    COALESCE(SUM(ta.points_awarded), 0) as total_points
    FROM twitter_links tl
    INNER JOIN profiles p ON p.id = tl.user_id
    LEFT JOIN twitter_actions ta ON ta.user_id = tl.user_id 
      AND ta.validated = true
      AND ta.created_at >= v_reset_at  -- Solo acciones del período actual
    GROUP BY tl.user_id, tl.twitter_username, p.username
    HAVING COALESCE(SUM(ta.points_awarded), 0) > 0
    ORDER BY total_points DESC
    LIMIT p_limit
  ) sub;

  RETURN jsonb_build_object(
    'success', true,
    'ranking', COALESCE(v_ranking, '[]'::jsonb)
  );
END;
$$;


--
-- TOC entry 956 (class 1255 OID 20554)
-- Name: get_twitter_task_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_twitter_task_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid;
  v_link twitter_links%ROWTYPE;
  v_total_points bigint;
  v_total_actions bigint;
  v_config twitter_social_config%ROWTYPE;
  v_reset_at timestamptz;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_config FROM twitter_social_config LIMIT 1;
  SELECT * INTO v_link FROM twitter_links WHERE user_id = v_user_id;

  -- Obtener fecha del último reinicio
  v_reset_at := COALESCE(v_config.ranking_reset_at, '1970-01-01'::timestamptz);

  IF v_link IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'twitter_linked', false,
      'total_points', 0,
      'total_actions', 0,
      'link_reward_fxu', COALESCE(v_config.link_reward_fxu, 20)
    );
  END IF;

  -- Solo contar puntos/acciones del período actual
  SELECT COALESCE(SUM(points_awarded), 0), COUNT(*)
  INTO v_total_points, v_total_actions
  FROM twitter_actions
  WHERE user_id = v_user_id 
    AND validated = true
    AND created_at >= v_reset_at;

  RETURN jsonb_build_object(
    'success', true,
    'twitter_linked', true,
    'twitter_username', v_link.twitter_username,
    'link_reward_claimed', v_link.link_reward_claimed,
    'link_reward_fxu', COALESCE(v_config.link_reward_fxu, 20),
    'total_points', v_total_points,
    'total_actions', v_total_actions,
    'quote_tweet_points', COALESCE(v_config.quote_tweet_points, 10),
    'comment_points', COALESCE(v_config.comment_points, 5)
  );
END;
$$;


--
-- TOC entry 926 (class 1255 OID 20381)
-- Name: get_universe_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_universe_records() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_buildings jsonb;
  v_research jsonb;
  v_ships jsonb;
  v_defense jsonb;
BEGIN
  -- Records de edificios: nivel más alto de cada tipo
  SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
  INTO v_buildings
  FROM (
    SELECT DISTINCT ON (bt.id)
      bt.id AS item_id,
      bt.name AS item_name,
      bt.image_url AS item_image,
      pb.level AS value,
      p.name AS planet_name,
      pr.username
    FROM building_types bt
    JOIN planet_buildings pb ON pb.building_type_id = bt.id AND pb.level > 0
    JOIN planets p ON p.id = pb.planet_id AND p.is_destroyed = false
    JOIN profiles pr ON pr.id = p.user_id AND pr.is_banned = false
    ORDER BY bt.id, pb.level DESC
  ) r;

  -- Records de investigación: nivel más alto de cada tecnología
  SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
  INTO v_research
  FROM (
    SELECT DISTINCT ON (tt.id)
      tt.id AS item_id,
      tt.name AS item_name,
      tt.image_url AS item_image,
      ut.level AS value,
      pr.username
    FROM technology_types tt
    JOIN user_technologies ut ON ut.technology_type_id = tt.id AND ut.level > 0
    JOIN profiles pr ON pr.id = ut.user_id AND pr.is_banned = false
    ORDER BY tt.id, ut.level DESC
  ) r;

  -- Records de naves: mayor cantidad de cada tipo en un solo planeta
  SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
  INTO v_ships
  FROM (
    SELECT DISTINCT ON (st.id)
      st.id AS item_id,
      st.name AS item_name,
      st.image_url AS item_image,
      ps.quantity AS value,
      p.name AS planet_name,
      pr.username
    FROM ship_types st
    JOIN planet_ships ps ON ps.ship_type_id = st.id AND ps.quantity > 0
    JOIN planets p ON p.id = ps.planet_id AND p.is_destroyed = false
    JOIN profiles pr ON pr.id = p.user_id AND pr.is_banned = false
    ORDER BY st.id, ps.quantity DESC
  ) r;

  -- Records de defensas: mayor cantidad de cada tipo en un solo planeta
  SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
  INTO v_defense
  FROM (
    SELECT DISTINCT ON (dt.id)
      dt.id AS item_id,
      dt.name AS item_name,
      dt.image_url AS item_image,
      pd.quantity AS value,
      p.name AS planet_name,
      pr.username
    FROM defense_types dt
    JOIN planet_defenses pd ON pd.defense_type_id = dt.id AND pd.quantity > 0
    JOIN planets p ON p.id = pd.planet_id AND p.is_destroyed = false
    JOIN profiles pr ON pr.id = p.user_id AND pr.is_banned = false
    ORDER BY dt.id, pd.quantity DESC
  ) r;

  RETURN jsonb_build_object(
    'buildings', v_buildings,
    'research', v_research,
    'ships', v_ships,
    'defense', v_defense
  );
END;
$$;


--
-- TOC entry 1085 (class 1255 OID 21493)
-- Name: get_user_active_bonuses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_active_bonuses(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_agg(jsonb_build_object(
    'id', uab.id,
    'mission_id', uab.mission_id,
    'bonus_type', uab.bonus_type,
    'bonus_value', uab.bonus_value,
    'expires_at', uab.expires_at,
    'title', dm.title_es,
    'icon', dm.icon
  ) ORDER BY uab.expires_at ASC)
  INTO v_result
  FROM user_active_bonuses uab
  LEFT JOIN daily_missions dm ON dm.id = uab.mission_id
  WHERE uab.user_id = p_user_id AND uab.expires_at > now();

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- TOC entry 703 (class 1255 OID 18928)
-- Name: get_user_by_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_by_email(p_email text) RETURNS TABLE(id uuid, username text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    u.id,
    COALESCE(u.raw_user_meta_data->>'username', p.username, 'Comandante') as username
  FROM auth.users u
  LEFT JOIN profiles p ON p.id = u.id
  WHERE LOWER(u.email) = LOWER(p_email)
  LIMIT 1;
END;
$$;


--
-- TOC entry 702 (class 1255 OID 18927)
-- Name: get_user_by_email_for_verification(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_by_email_for_verification(p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_username text;
BEGIN
  SELECT au.id, COALESCE(au.raw_user_meta_data->>'username', p.username, 'Comandante')
  INTO v_user_id, v_username
  FROM auth.users au
  LEFT JOIN profiles p ON p.id = au.id
  WHERE au.email = p_email
  LIMIT 1;
  
  IF v_user_id IS NULL THEN
    RETURN NULL;
  END IF;
  
  RETURN jsonb_build_object('user_id', v_user_id, 'username', v_username);
END;
$$;


--
-- TOC entry 1121 (class 1255 OID 21816)
-- Name: get_user_cosmetics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_cosmetics() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_result jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  PERFORM clean_expired_cosmetics(v_user_id);

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ci.id,
      'code', ci.code,
      'type', ci.cosmetic_type,
      'name', ci.name_es,
      'icon', ci.icon,
      'rarity', ci.rarity,
      'cost', ci.fxu_cost,
      'purchased_at', uc.purchased_at,
      'expires_at', uc.expires_at,
      'equipped', uc.equipped,
      'remaining_hours', GREATEST(0, EXTRACT(EPOCH FROM (uc.expires_at - now()))/3600)
    ) ORDER BY uc.equipped DESC, uc.expires_at DESC
  ) INTO v_result
  FROM user_cosmetics uc
  JOIN cosmetic_items ci ON ci.id = uc.cosmetic_id
  WHERE uc.user_id = v_user_id AND uc.expires_at > now();

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


