--

CREATE FUNCTION public.get_user_daily_missions(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM assign_daily_missions(p_user_id);
  SELECT jsonb_agg(jsonb_build_object(
    'id', udm.id, 'mission_id', dm.id, 'code', dm.code,
    'title', dm.title_es, 'description', dm.desc_es,
    'mission_type', dm.mission_type, 'target_count', dm.target_count,
    'progress', udm.progress, 'completed', udm.completed, 'claimed', udm.claimed,
    'reward_type', dm.reward_type, 'reward_value', dm.reward_value,
    'reward_duration_hours', dm.reward_duration_hours, 'icon', dm.icon,
    'expires_at', udm.expires_at
  ) ORDER BY udm.completed ASC, udm.claimed ASC, dm.id)
  INTO v_result
  FROM user_daily_missions udm
  JOIN daily_missions dm ON dm.id = udm.mission_id
  WHERE udm.user_id = p_user_id AND dm.is_active = true AND udm.expires_at > now();
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


