--
-- TOC entry 672 (class 1255 OID 18779)
-- Name: get_user_officer_bonuses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_officer_bonuses(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bonuses jsonb := '{"mineProduction": 0, "energyProduction": 0, "fleetSpeed": 0, "researchSpeed": 0, "buildingQueueSlots": 0}'::jsonb;
  v_officer RECORD;
BEGIN
  FOR v_officer IN
    SELECT ot.code, uo.expires_at
    FROM user_officers uo
    JOIN officer_types ot ON ot.id = uo.officer_type_id
    WHERE uo.user_id = p_user_id
      AND (uo.expires_at IS NULL OR uo.expires_at > now())
  LOOP
    CASE v_officer.code
      WHEN 'geologist' THEN
        v_bonuses := jsonb_set(v_bonuses, '{mineProduction}', '0.1'::jsonb);
      WHEN 'engineer' THEN
        v_bonuses := jsonb_set(v_bonuses, '{energyProduction}', '0.1'::jsonb);
      WHEN 'admiral' THEN
        v_bonuses := jsonb_set(v_bonuses, '{fleetSpeed}', '0.2'::jsonb);
      WHEN 'technocrat' THEN
        v_bonuses := jsonb_set(v_bonuses, '{researchSpeed}', '0.25'::jsonb);
      WHEN 'commander' THEN
        v_bonuses := jsonb_set(v_bonuses, '{buildingQueueSlots}', '2'::jsonb);
      ELSE NULL;
    END CASE;
  END LOOP;
  
  RETURN v_bonuses;
END;
$$;


--
-- TOC entry 667 (class 1255 OID 18766)
-- Name: get_vacation_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_vacation_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_profile record;
  v_hours_elapsed numeric;
  v_hours_remaining numeric;
  v_incoming_count integer;
  v_min_vacation_hours constant integer := 48;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Not authenticated');
  END IF;

  SELECT vacation_mode, vacation_mode_enabled_at
  INTO v_profile
  FROM profiles
  WHERE id = v_user_id;

  -- Contar ataques entrantes
  SELECT COUNT(*) INTO v_incoming_count
  FROM check_incoming_hostile_fleets(v_user_id);

  IF v_profile.vacation_mode AND v_profile.vacation_mode_enabled_at IS NOT NULL THEN
    v_hours_elapsed := EXTRACT(EPOCH FROM (now() - v_profile.vacation_mode_enabled_at)) / 3600;
    v_hours_remaining := GREATEST(0, v_min_vacation_hours - v_hours_elapsed);
    
    RETURN jsonb_build_object(
      'is_active', true,
      'enabled_at', v_profile.vacation_mode_enabled_at,
      'hours_elapsed', ROUND(v_hours_elapsed::numeric, 1),
      'hours_remaining', ROUND(v_hours_remaining::numeric, 1),
      'can_disable', v_hours_remaining <= 0,
      'can_disable_at', v_profile.vacation_mode_enabled_at + (v_min_vacation_hours || ' hours')::interval,
      'incoming_attacks', v_incoming_count
    );
  ELSE
    RETURN jsonb_build_object(
      'is_active', false,
      'can_enable', v_incoming_count = 0,
      'incoming_attacks', v_incoming_count
    );
  END IF;
END;
$$;


