-- Name: get_wallet_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_wallet_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_fxu_balance numeric;
  v_usdt_balance numeric;
  v_total_deposited numeric;
  v_total_withdrawn numeric;
  v_total_deposited_usdt numeric;
  v_total_withdrawn_usdt numeric;
  v_pending_withdrawals numeric;
  v_pending_withdrawals_usdt numeric;
  v_daily_withdrawn numeric;
  v_daily_withdrawn_usdt numeric;
  v_config wallet_config%ROWTYPE;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Not authenticated');
  END IF;

  SELECT fxu_balance, usdt_balance INTO v_fxu_balance, v_usdt_balance FROM profiles WHERE id = v_user_id;

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_total_deposited
  FROM wallet_transactions
  WHERE user_id = v_user_id AND tx_type = 'deposit' AND token_type = 'TUNG' AND status = 'confirmed';

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_total_withdrawn
  FROM wallet_transactions
  WHERE user_id = v_user_id AND tx_type = 'withdrawal' AND token_type = 'TUNG' AND status = 'confirmed';

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_pending_withdrawals
  FROM wallet_transactions
  WHERE user_id = v_user_id AND tx_type = 'withdrawal' AND token_type = 'TUNG' AND status IN ('pending', 'processing');

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_total_deposited_usdt
  FROM wallet_transactions
  WHERE user_id = v_user_id AND tx_type = 'deposit' AND token_type = 'USDT' AND status = 'confirmed';

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_total_withdrawn_usdt
  FROM wallet_transactions
  WHERE user_id = v_user_id AND tx_type = 'withdrawal' AND token_type = 'USDT' AND status = 'confirmed';

  SELECT COALESCE(SUM(fxu_amount), 0) INTO v_pending_withdrawals_usdt
  FROM wallet_transactions
  WHERE user_id = v_user_id AND tx_type = 'withdrawal' AND token_type = 'USDT' AND status IN ('pending', 'processing');

  v_daily_withdrawn := get_daily_withdrawal_total(v_user_id);
  v_daily_withdrawn_usdt := get_daily_usdt_withdrawal_total(v_user_id);

  SELECT * INTO v_config FROM wallet_config WHERE id = 1;

  RETURN jsonb_build_object(
    'fxu_balance', v_fxu_balance,
    'usdt_balance', v_usdt_balance,
    'total_deposited', v_total_deposited,
    'total_withdrawn', v_total_withdrawn,
    'total_deposited_usdt', v_total_deposited_usdt,
    'total_withdrawn_usdt', v_total_withdrawn_usdt,
    'pending_withdrawals', v_pending_withdrawals,
    'pending_withdrawals_usdt', v_pending_withdrawals_usdt,
    'daily_withdrawn', v_daily_withdrawn,
    'daily_withdrawn_usdt', v_daily_withdrawn_usdt,
    'daily_limit', v_config.max_withdrawal_daily,
    'daily_limit_usdt', v_config.usdt_max_withdrawal_daily,
    'daily_remaining', v_config.max_withdrawal_daily - v_daily_withdrawn,
    'daily_remaining_usdt', v_config.usdt_max_withdrawal_daily - v_daily_withdrawn_usdt,
    'min_amount', v_config.min_deposit,
    'min_amount_usdt', v_config.usdt_min_deposit,
    'withdrawal_fee_percent', v_config.withdrawal_fee_percent,
    'withdrawal_fee_percent_usdt', v_config.usdt_withdrawal_fee_percent,
    'deposits_enabled', v_config.is_deposits_enabled,
    'withdrawals_enabled', v_config.is_withdrawals_enabled,
    'usdt_deposits_enabled', v_config.is_usdt_deposits_enabled,
    'usdt_withdrawals_enabled', v_config.is_usdt_withdrawals_enabled,
    'usdt_contract', v_config.usdt_contract_address,
    'swap_enabled', v_config.is_swap_enabled,
    'swap_rate', v_config.swap_rate_fxu_per_usdt,
    'swap_min_fxu', v_config.swap_min_fxu,
    'swap_min_usdt', v_config.swap_min_usdt,
    'swap_fee_percent', COALESCE(v_config.swap_fee_percent, 1.0)
  );
END;
$$;


--
-- TOC entry 1136 (class 1255 OID 22246)
-- Name: get_war_hall_of_fame(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_war_hall_of_fame() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH ranked AS (
    SELECT 
      alliance_name, alliance_tag, total_wins, total_wars, total_fxu_won, last_win_at,
      ROW_NUMBER() OVER (ORDER BY total_wins DESC, total_fxu_won DESC) as rank
    FROM alliance_war_hall_of_fame
    ORDER BY total_wins DESC, total_fxu_won DESC
    LIMIT 50
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'rank', rank,
      'alliance_name', alliance_name,
      'alliance_tag', alliance_tag,
      'total_wins', total_wins,
      'total_wars', total_wars,
      'total_fxu_won', total_fxu_won,
      'last_win_at', last_win_at
    )
  ) INTO v_result
  FROM ranked;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- TOC entry 726 (class 1255 OID 18986)
-- Name: get_weekly_revenue(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_weekly_revenue(p_weeks integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  v_result jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  SELECT jsonb_build_object(
    'success', true,
    'data', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'week_start', w.week_start::date,
            'week_number', EXTRACT(WEEK FROM w.week_start),
            'amount', COALESCE(r.total, 0)
          )
          ORDER BY w.week_start
        )
        FROM generate_series(
          DATE_TRUNC('week', CURRENT_DATE) - ((p_weeks - 1) * INTERVAL '1 week'),
          DATE_TRUNC('week', CURRENT_DATE),
          '1 week'::interval
        ) AS w(week_start)
        LEFT JOIN (
          SELECT DATE_TRUNC('week', created_at) as week_start,
                 SUM(CASE WHEN currency = 'USDT' THEN amount * 10000 ELSE amount END) as total
          FROM public.admin_revenue
          WHERE created_at >= DATE_TRUNC('week', CURRENT_DATE) - (p_weeks * INTERVAL '1 week')
          GROUP BY DATE_TRUNC('week', created_at)
        ) r ON w.week_start = r.week_start
      ),
      '[]'::jsonb
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- TOC entry 991 (class 1255 OID 20746)
-- Name: get_weekly_revenue_snapshots(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_weekly_revenue_snapshots(p_limit integer DEFAULT 52) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_is_admin boolean;
  v_snapshots jsonb;
  v_current_week_breakdown jsonb;
  v_current_week_total numeric;
  v_current_week_start date;
  v_current_week_end date;
  v_current_week_number integer;
  v_current_year integer;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true
  ) INTO v_is_admin;

  IF NOT v_is_admin THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  v_current_week_start := DATE_TRUNC('week', CURRENT_DATE)::date;
  v_current_week_end := (v_current_week_start + INTERVAL '6 days')::date;
  v_current_week_number := EXTRACT(WEEK FROM v_current_week_start);
  v_current_year := EXTRACT(YEAR FROM v_current_week_start);

  SELECT
    COALESCE(jsonb_object_agg(revenue_type, type_total), '{}'::jsonb),
    COALESCE(SUM(type_total), 0)
  INTO v_current_week_breakdown, v_current_week_total
  FROM (
    SELECT
      revenue_type,
      SUM(CASE WHEN currency = 'USDT' THEN amount * 10000 ELSE amount END) AS type_total
    FROM public.admin_revenue
    WHERE created_at >= v_current_week_start::timestamptz
      AND created_at < (v_current_week_end + INTERVAL '1 day')::timestamptz
    GROUP BY revenue_type
  ) sub;

  SELECT COALESCE(jsonb_agg(row_to_json(s) ORDER BY s.week_start DESC), '[]'::jsonb)
  INTO v_snapshots
  FROM (
    SELECT
      id,
      week_start,
      week_end,
      week_number,
      year,
      breakdown,
      total::float,
      created_at
    FROM public.weekly_revenue_snapshots
    ORDER BY week_start DESC
    LIMIT p_limit
  ) s;

  RETURN jsonb_build_object(
    'success', true,
    'current_week', jsonb_build_object(
      'week_start', v_current_week_start,
      'week_end', v_current_week_end,
      'week_number', v_current_week_number,
      'year', v_current_year,
      'breakdown', v_current_week_breakdown,
      'total', v_current_week_total::float,
      'is_current', true
    ),
    'snapshots', v_snapshots
  );
END;
$$;


--
-- TOC entry 876 (class 1255 OID 20051)
-- Name: global_process_all_expired_queues(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_process_all_expired_queues() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_queue_item RECORD;
v_building_completed integer := 0;
v_shipyard_completed integer := 0;
v_fleet_processed integer := 0;
v_research_completed integer := 0;
v_errors integer := 0;
v_units_to_complete integer;
v_lunar_base_id integer;
BEGIN
SELECT id INTO v_lunar_base_id FROM building_types WHERE code = 'lunar_base' LIMIT 1;

FOR v_queue_item IN 
SELECT bq.*
FROM building_queue bq
WHERE bq.end_time IS NOT NULL 
AND bq.end_time <= NOW()
ORDER BY bq.end_time ASC
LIMIT 100
LOOP
BEGIN
INSERT INTO planet_buildings (planet_id, building_type_id, level, is_upgrading, upgrade_end_time)
VALUES (v_queue_item.planet_id, v_queue_item.building_type_id, v_queue_item.target_level, false, NULL)
ON CONFLICT (planet_id, building_type_id)
DO UPDATE SET 
level = GREATEST(planet_buildings.level, v_queue_item.target_level),
is_upgrading = false,
upgrade_end_time = NULL;

UPDATE planets SET fields_used = LEAST(fields_max, fields_used + 1) WHERE id = v_queue_item.planet_id;

-- [FIX 2026-05-06] Lunar base on moon: grant +3 fields per level
IF v_lunar_base_id IS NOT NULL AND v_queue_item.building_type_id = v_lunar_base_id THEN
  UPDATE planets
  SET fields_max = GREATEST(fields_max, 1 + v_queue_item.target_level * 3)
  WHERE id = v_queue_item.planet_id AND planet_type = 'moon';
END IF;

DELETE FROM building_queue WHERE id = v_queue_item.id;
UPDATE building_queue SET queue_position = queue_position - 1 
WHERE planet_id = v_queue_item.planet_id AND queue_position > v_queue_item.queue_position;

v_building_completed := v_building_completed + 1;
EXCEPTION WHEN OTHERS THEN
v_errors := v_errors + 1;
END;
END LOOP;

FOR v_queue_item IN 
SELECT sq.*
FROM shipyard_queue sq
WHERE sq.current_unit_end_time IS NOT NULL 
AND sq.current_unit_end_time <= NOW()
ORDER BY sq.current_unit_end_time ASC
LIMIT 100
LOOP
BEGIN
v_units_to_complete := v_queue_item.quantity - v_queue_item.quantity_completed;

IF v_queue_item.item_type = 'ship' AND v_queue_item.ship_type_id IS NOT NULL THEN
INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
VALUES (v_queue_item.planet_id, v_queue_item.ship_type_id, v_units_to_complete)
ON CONFLICT (planet_id, ship_type_id)
DO UPDATE SET quantity = planet_ships.quantity + v_units_to_complete;
ELSIF v_queue_item.item_type = 'defense' AND v_queue_item.defense_type_id IS NOT NULL THEN
INSERT INTO planet_defenses (planet_id, defense_type_id, quantity)
VALUES (v_queue_item.planet_id, v_queue_item.defense_type_id, v_units_to_complete)
ON CONFLICT (planet_id, defense_type_id)
DO UPDATE SET quantity = planet_defenses.quantity + v_units_to_complete;
END IF;

DELETE FROM shipyard_queue WHERE id = v_queue_item.id;
UPDATE shipyard_queue SET queue_position = queue_position - 1 
WHERE planet_id = v_queue_item.planet_id AND queue_position > v_queue_item.queue_position;

v_shipyard_completed := v_shipyard_completed + v_units_to_complete;
EXCEPTION WHEN OTHERS THEN
v_errors := v_errors + 1;
END;
END LOOP;

FOR v_queue_item IN 
SELECT ut.*
FROM user_technologies ut
WHERE ut.is_researching = true
AND ut.research_end_time IS NOT NULL
AND ut.research_end_time <= NOW()
ORDER BY ut.research_end_time ASC
LIMIT 50
LOOP
BEGIN
UPDATE user_technologies
SET level = level + 1,
is_researching = false,
research_end_time = NULL,
research_planet_id = NULL
WHERE id = v_queue_item.id;

v_research_completed := v_research_completed + 1;
EXCEPTION WHEN OTHERS THEN
v_errors := v_errors + 1;
END;
END LOOP;

RETURN jsonb_build_object(
'success', true,
'building_completed', v_building_completed,
'shipyard_completed', v_shipyard_completed,
'research_completed', v_research_completed,
'errors', v_errors,
'timestamp', NOW()
);
END;
$$;


--
-- TOC entry 582 (class 1255 OID 18036)
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_username text;
  v_referral_code text;
  v_referred_by_code text;
  v_referrer_id uuid;
  v_start_galaxy integer;
  v_start_system integer;
  v_start_position integer;
  v_planet_id uuid;
  v_attempts integer := 0;
  v_max_attempts integer := 100;
  v_position_found boolean := false;
  v_starting_fxu numeric;
BEGIN
  -- Determine username with fallback
  v_username := COALESCE(
    NULLIF(TRIM(NEW.raw_user_meta_data->>'username'), ''),
    split_part(NEW.email, '@', 1)
  );

  -- Ensure username is not empty
  IF v_username IS NULL OR v_username = '' THEN
    v_username := 'user_' || substr(NEW.id::text, 1, 8);
  END IF;

  -- Handle duplicate username
  IF EXISTS (SELECT 1 FROM profiles WHERE username = v_username) THEN
    v_username := v_username || '_' || substr(NEW.id::text, 1, 4);
  END IF;

  -- Generate unique referral code from user ID
  v_referral_code := UPPER(SUBSTRING(NEW.id::text, 1, 8));

  -- Check if there's a referral code in metadata
  v_referred_by_code := UPPER(TRIM(COALESCE(NEW.raw_user_meta_data->>'referral_code', '')));
  
  IF v_referred_by_code IS NOT NULL AND v_referred_by_code <> '' THEN
    -- Look up the referrer by their referral code
    SELECT id INTO v_referrer_id 
    FROM profiles 
    WHERE referral_code = v_referred_by_code;
    
    -- Don't allow self-referral
    IF v_referrer_id = NEW.id THEN
      v_referrer_id := NULL;
    END IF;
  END IF;

  -- Read starting FXU from game_settings (default 0 if not set)
  SELECT COALESCE(value::numeric, 0) INTO v_starting_fxu
  FROM game_settings WHERE key = 'test_starting_fxu';

  -- Create profile with test_starting_fxu AND referred_by
  INSERT INTO profiles (id, username, email, dark_matter, fxu_balance, referral_code, referred_by)
  VALUES (NEW.id, v_username, NEW.email, 0, v_starting_fxu, v_referral_code, v_referrer_id);

  -- Find empty position for planet
  WHILE NOT v_position_found AND v_attempts < v_max_attempts LOOP
    v_start_galaxy := 1 + floor(random() * 3)::integer;
    v_start_system := 1 + floor(random() * 200)::integer;
    v_start_position := 4 + floor(random() * 9)::integer;

    IF NOT EXISTS (
      SELECT 1 FROM planets 
      WHERE galaxy = v_start_galaxy 
      AND solar_system = v_start_system 
      AND position = v_start_position
    ) THEN
      v_position_found := true;
    END IF;

    v_attempts := v_attempts + 1;
  END LOOP;

  -- Fallback position search
  IF NOT v_position_found THEN
    v_start_galaxy := 1;
    v_start_system := 1;
    v_start_position := 1;

    WHILE EXISTS (
      SELECT 1 FROM planets 
      WHERE galaxy = v_start_galaxy 
      AND solar_system = v_start_system 
      AND position = v_start_position
    ) LOOP
      v_start_position := v_start_position + 1;
      IF v_start_position > 15 THEN
        v_start_position := 1;
        v_start_system := v_start_system + 1;
        IF v_start_system > 400 THEN
          v_start_system := 1;
          v_start_galaxy := v_start_galaxy + 1;
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- Create main planet
  INSERT INTO planets (
    user_id, name, galaxy, solar_system, position,
    planet_type, diameter, fields_max, fields_used,
    temp_min, temp_max, is_main_planet
  ) VALUES (
    NEW.id, 'Planeta Principal',
    v_start_galaxy, v_start_system, v_start_position,
    'planet', 12800, 163, 0,
    -20 + floor(random() * 60)::integer,
    20 + floor(random() * 60)::integer,
    true
  )
  RETURNING id INTO v_planet_id;

  -- Create planet resources
  INSERT INTO planet_resources (
    planet_id, metal, crystal, deuterium,
    metal_per_hour, crystal_per_hour, deuterium_per_hour,
    energy_used, energy_max
  ) VALUES (
    v_planet_id, 500, 300, 100, 30, 15, 0, 0, 0
  );

  RETURN NEW;
EXCEPTION
  WHEN unique_violation THEN
    RAISE LOG 'Profile already exists for user %: %', NEW.id, SQLERRM;
    RETURN NEW;
  WHEN OTHERS THEN
    RAISE LOG 'Error in handle_new_user for %: % - %', NEW.id, SQLSTATE, SQLERRM;
    RETURN NEW;
END;
$$;


--
-- TOC entry 658 (class 1255 OID 18744)
-- Name: has_active_officer(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_active_officer(p_user_id uuid, p_officer_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM user_officers uo
    JOIN officer_types ot ON uo.officer_type_id = ot.id
    WHERE uo.user_id = p_user_id 
    AND ot.code = p_officer_code 
    AND uo.expires_at > NOW()
  );
END;
$$;


--
-- TOC entry 1131 (class 1255 OID 22219)
-- Name: has_autopilot_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_autopilot_access(p_user_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_autopilot_eligible boolean;
  v_autopilot_active boolean;
BEGIN
  v_uid := COALESCE(p_user_id, auth.uid());
  IF v_uid IS NULL THEN RETURN false; END IF;
  
  SELECT autopilot_eligible, autopilot_active 
  INTO v_autopilot_eligible, v_autopilot_active 
  FROM profiles WHERE id = v_uid;
  
  -- Access granted if admin-enabled (eligible) OR already active
  RETURN COALESCE(v_autopilot_eligible, false) OR COALESCE(v_autopilot_active, false);
END;
$$;


