--
-- TOC entry 696 (class 1255 OID 18899)
-- Name: instant_complete_building(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instant_complete_building(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$




DECLARE
  v_user_id uuid;
  v_queue_item RECORD;
  v_fxu_cost integer;
  v_current_fxu numeric;
  v_remaining_seconds integer;
  v_admin_id uuid;
BEGIN
  v_user_id := auth.uid();
IF is_user_in_vacation_mode(v_user_id) THEN
RETURN jsonb_build_object('success', false, 'error', 'Cannot use instant complete while in vacation mode');
END IF;
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT bq.*, bt.name as building_name, p.user_id as planet_owner
  INTO v_queue_item
  FROM building_queue bq
  JOIN building_types bt ON bq.building_type_id = bt.id
  JOIN planets p ON bq.planet_id = p.id
  WHERE bq.id = p_queue_id AND bq.status = 'building';

  IF v_queue_item IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Queue item not found or not building');
  END IF;

  IF v_queue_item.planet_owner != v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not your planet');
  END IF;

  v_remaining_seconds := GREATEST(0, EXTRACT(EPOCH FROM (v_queue_item.end_time - now()))::integer);
  v_fxu_cost := calculate_fxu_cost_building(p_queue_id);

  SELECT fxu_balance INTO v_current_fxu FROM profiles WHERE id = v_user_id;
  IF v_current_fxu < v_fxu_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient FXU', 'required', v_fxu_cost, 'available', v_current_fxu);
  END IF;

  PERFORM set_config('app.fxu_update_allowed', 'instant_complete_building', true);

  UPDATE profiles SET fxu_balance = fxu_balance - v_fxu_cost WHERE id = v_user_id;

  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_id != v_user_id THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_fxu_cost WHERE id = v_admin_id;
  END IF;

  UPDATE building_queue SET end_time = now() - interval '1 second' WHERE id = p_queue_id;
  PERFORM complete_building_queue_item(p_queue_id);

  RETURN jsonb_build_object('success', true, 'fxu_spent', v_fxu_cost);
END;




$$;


--
-- TOC entry 723 (class 1255 OID 18982)
-- Name: instant_complete_research(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instant_complete_research(p_technology_type_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_queue_item record;
  v_tech record;
  v_tech_type technology_types%ROWTYPE;
  v_fxu_cost integer;
  v_current_fxu numeric;
  v_admin_id uuid;
  v_seconds_remaining integer;
  v_total_research_time integer;
  v_time_ratio numeric;
  v_metal_cost bigint;
  v_crystal_cost bigint;
  v_deut_cost bigint;
  v_resource_value numeric;
  v_fxu_ratio numeric;
BEGIN
  v_user_id := auth.uid();
  IF is_user_in_vacation_mode(v_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot use instant complete while in vacation mode');
  END IF;
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_queue_item FROM research_queue
  WHERE user_id = v_user_id AND technology_type_id = p_technology_type_id AND status = 'in_progress' LIMIT 1;

  IF v_queue_item IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No hay investigacion en progreso');
  END IF;

  v_seconds_remaining := GREATEST(0, EXTRACT(EPOCH FROM (v_queue_item.end_time - now()))::integer);

  IF v_seconds_remaining <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Research already complete');
  END IF;

  SELECT * INTO v_tech_type FROM technology_types WHERE id = p_technology_type_id;

  IF v_tech_type IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Technology type not found');
  END IF;

  v_total_research_time := GREATEST(1, EXTRACT(EPOCH FROM (v_queue_item.end_time - v_queue_item.start_time))::integer);
  v_time_ratio := LEAST(1, GREATEST(0.01, v_seconds_remaining::numeric / v_total_research_time::numeric));

  v_metal_cost := FLOOR(COALESCE(v_tech_type.base_metal, 0) * POWER(COALESCE(v_tech_type.cost_factor, 2), v_queue_item.target_level - 1));
  v_crystal_cost := FLOOR(COALESCE(v_tech_type.base_crystal, 0) * POWER(COALESCE(v_tech_type.cost_factor, 2), v_queue_item.target_level - 1));
  v_deut_cost := FLOOR(COALESCE(v_tech_type.base_deuterium, 0) * POWER(COALESCE(v_tech_type.cost_factor, 2), v_queue_item.target_level - 1));

  v_resource_value := calculate_resource_value(v_metal_cost, v_crystal_cost, v_deut_cost);

  SELECT COALESCE(value::numeric, 3000) INTO v_fxu_ratio
  FROM game_settings WHERE key = 'fxu_cost_ratio_research';
  IF v_fxu_ratio IS NULL OR v_fxu_ratio <= 0 THEN
    v_fxu_ratio := 3000;
  END IF;

  v_fxu_cost := GREATEST(1, CEIL((v_resource_value / v_fxu_ratio) * v_time_ratio))::integer;

  -- VIP discount: 50% off (changed from 75%)
  IF is_user_plus(v_user_id) THEN
    v_fxu_cost := GREATEST(1, CEIL(v_fxu_cost * 0.50))::integer;
  END IF;

  SELECT fxu_balance INTO v_current_fxu FROM profiles WHERE id = v_user_id;

  IF v_current_fxu < v_fxu_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'FXU insuficiente', 'required', v_fxu_cost);
  END IF;

  PERFORM _internal_set_fxu_context();

  UPDATE profiles SET fxu_balance = fxu_balance - v_fxu_cost WHERE id = v_user_id;

  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_id != v_user_id THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_fxu_cost WHERE id = v_admin_id;
  END IF;

  PERFORM record_admin_revenue('instant_research', v_fxu_cost,
    'Investigacion: ' || v_tech_type.name, v_user_id, v_queue_item.id);

  INSERT INTO user_technologies (user_id, technology_type_id, level)
  VALUES (v_user_id, p_technology_type_id, v_queue_item.target_level)
  ON CONFLICT (user_id, technology_type_id) DO UPDATE SET level = v_queue_item.target_level;

  DELETE FROM research_queue WHERE id = v_queue_item.id;

  UPDATE research_queue SET status = 'in_progress', start_time = now(), end_time = now() + (end_time - start_time)
  WHERE user_id = v_user_id AND status = 'pending'
  AND queue_position = (SELECT MIN(queue_position) FROM research_queue WHERE user_id = v_user_id AND status = 'pending');

  PERFORM update_user_points(v_user_id);

  RETURN jsonb_build_object('success', true, 'fxu_spent', v_fxu_cost, 'new_level', v_queue_item.target_level);
END;
$$;


--
-- TOC entry 697 (class 1255 OID 18900)
-- Name: instant_complete_research(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instant_complete_research(p_research_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$




DECLARE
  v_user_id uuid;
  v_research RECORD;
  v_fxu_cost integer;
  v_current_fxu numeric;
  v_remaining_seconds integer;
  v_admin_id uuid;
BEGIN
  v_user_id := auth.uid();
IF is_user_in_vacation_mode(v_user_id) THEN
RETURN jsonb_build_object('success', false, 'error', 'Cannot use instant complete while in vacation mode');
END IF;
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT ur.*, rt.name as research_name
  INTO v_research
  FROM user_technologies ur
  JOIN technology_types rt ON ur.technology_type_id = rt.id
  WHERE ur.id = p_research_id AND ur.is_researching = true;

  IF v_research IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Research not found or not in progress');
  END IF;

  IF v_research.user_id != v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not your research');
  END IF;

  v_remaining_seconds := GREATEST(0, EXTRACT(EPOCH FROM (v_research.research_end_time - now()))::integer);
  v_fxu_cost := calculate_fxu_cost_research(p_research_id);

  SELECT fxu_balance INTO v_current_fxu FROM profiles WHERE id = v_user_id;
  IF v_current_fxu < v_fxu_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient FXU', 'required', v_fxu_cost, 'available', v_current_fxu);
  END IF;

  PERFORM set_config('app.fxu_update_allowed', 'instant_complete_research', true);

  UPDATE profiles SET fxu_balance = fxu_balance - v_fxu_cost WHERE id = v_user_id;

  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_id != v_user_id THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_fxu_cost WHERE id = v_admin_id;
  END IF;

  UPDATE user_technologies 
  SET level = level + 1, 
      is_researching = false, 
      research_end_time = NULL
  WHERE id = p_research_id;

  PERFORM update_user_points(v_user_id);

  RETURN jsonb_build_object('success', true, 'fxu_spent', v_fxu_cost);
END;




$$;


--
-- TOC entry 724 (class 1255 OID 18983)
-- Name: instant_complete_shipyard(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instant_complete_shipyard(p_planet_id uuid, p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_queue_item record;
  v_fxu_cost numeric;
  v_current_fxu numeric;
  v_remaining_seconds numeric;
  v_item_name text;
BEGIN
  SELECT user_id INTO v_user_id FROM planets WHERE id = p_planet_id;
  
  IF v_user_id IS NULL OR v_user_id != auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planeta no encontrado');
  END IF;
  
  SELECT * INTO v_queue_item FROM shipyard_queue WHERE id = p_queue_id AND planet_id = p_planet_id;
  
  IF v_queue_item IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item no encontrado');
  END IF;
  
  v_remaining_seconds := GREATEST(0, EXTRACT(EPOCH FROM (v_queue_item.end_time - now())));
  
  IF v_remaining_seconds <= 600 THEN v_fxu_cost := GREATEST(1, CEIL(v_remaining_seconds / 60));
  ELSIF v_remaining_seconds <= 3600 THEN v_fxu_cost := 10 + CEIL((v_remaining_seconds - 600) / 120);
  ELSIF v_remaining_seconds <= 86400 THEN v_fxu_cost := 35 + CEIL((v_remaining_seconds - 3600) / 300);
  ELSE v_fxu_cost := 100 + CEIL((v_remaining_seconds - 86400) / 600);
  END IF;
  
  SELECT fxu_balance INTO v_current_fxu FROM profiles WHERE id = v_user_id;
  
  IF v_current_fxu < v_fxu_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'FXU insuficiente', 'required', v_fxu_cost);
  END IF;
  
  UPDATE profiles SET fxu_balance = fxu_balance - v_fxu_cost WHERE id = v_user_id;
  
  IF v_queue_item.item_type = 'ship' THEN
    SELECT name INTO v_item_name FROM ship_types WHERE id = v_queue_item.item_id;
  ELSE
    SELECT name INTO v_item_name FROM defense_types WHERE id = v_queue_item.item_id;
  END IF;
  
  PERFORM record_admin_revenue('instant_ship', v_fxu_cost,
    v_queue_item.quantity || 'x ' || COALESCE(v_item_name, 'Item'), v_user_id, v_queue_item.id);
  
  IF v_queue_item.item_type = 'ship' THEN
    INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
    VALUES (p_planet_id, v_queue_item.item_id, v_queue_item.quantity)
    ON CONFLICT (planet_id, ship_type_id) DO UPDATE SET quantity = planet_ships.quantity + v_queue_item.quantity;
  ELSE
    INSERT INTO planet_defenses (planet_id, defense_type_id, quantity)
    VALUES (p_planet_id, v_queue_item.item_id, v_queue_item.quantity)
    ON CONFLICT (planet_id, defense_type_id) DO UPDATE SET quantity = planet_defenses.quantity + v_queue_item.quantity;
  END IF;
  
  DELETE FROM shipyard_queue WHERE id = p_queue_id;
  PERFORM update_user_points(v_user_id);
  
  RETURN jsonb_build_object('success', true, 'fxu_spent', v_fxu_cost, 'quantity', v_queue_item.quantity);
END;
$$;


--
-- TOC entry 698 (class 1255 OID 18901)
-- Name: instant_complete_shipyard_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instant_complete_shipyard_item(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_queue_item RECORD;
  v_fxu_cost integer;
  v_current_fxu numeric;
  v_admin_id uuid;
  v_item_name text;
  v_item_id integer;
BEGIN
  v_user_id := auth.uid();
IF is_user_in_vacation_mode(v_user_id) THEN
RETURN jsonb_build_object('success', false, 'error', 'Cannot use instant complete while in vacation mode');
END IF;
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT sq.id, sq.planet_id, sq.item_type, sq.ship_type_id, sq.defense_type_id, 
         sq.quantity, sq.quantity_completed, sq.build_time_per_unit,
         sq.queue_position, sq.start_time, sq.current_unit_end_time, p.user_id as planet_owner
  INTO v_queue_item
  FROM shipyard_queue sq
  JOIN planets p ON sq.planet_id = p.id
  WHERE sq.id = p_queue_id AND sq.queue_position = 1 AND sq.current_unit_end_time IS NOT NULL;

  IF v_queue_item IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Queue item not found or not active');
  END IF;
  
  IF v_queue_item.planet_owner != v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not your planet');
  END IF;

  v_fxu_cost := calculate_fxu_cost_shipyard(p_queue_id);
  IF v_fxu_cost <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Construction already complete');
  END IF;

  SELECT fxu_balance INTO v_current_fxu FROM profiles WHERE id = v_user_id FOR UPDATE;
  IF v_current_fxu IS NULL OR v_current_fxu < v_fxu_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient FXU', 'required', v_fxu_cost);
  END IF;

  PERFORM _internal_set_fxu_context();
  UPDATE profiles SET fxu_balance = fxu_balance - v_fxu_cost WHERE id = v_user_id;

  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_id != v_user_id THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_fxu_cost WHERE id = v_admin_id;
  END IF;

  -- Determine the item_id and name based on type
  IF v_queue_item.item_type = 'ship' THEN
    v_item_id := v_queue_item.ship_type_id;
    SELECT name INTO v_item_name FROM ship_types WHERE id = v_item_id;
  ELSE
    v_item_id := v_queue_item.defense_type_id;
    SELECT name INTO v_item_name FROM defense_types WHERE id = v_item_id;
  END IF;

  -- Calculate remaining quantity
  DECLARE
    v_remaining_quantity integer;
  BEGIN
    v_remaining_quantity := v_queue_item.quantity - v_queue_item.quantity_completed;

    -- Record revenue
    PERFORM record_admin_revenue('instant_ship', v_fxu_cost,
      v_remaining_quantity || 'x ' || COALESCE(v_item_name, v_queue_item.item_type), v_user_id, p_queue_id);

    -- Add the items to the planet
    IF v_queue_item.item_type = 'ship' THEN
      INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
      VALUES (v_queue_item.planet_id, v_item_id, v_remaining_quantity)
      ON CONFLICT (planet_id, ship_type_id) DO UPDATE SET quantity = planet_ships.quantity + v_remaining_quantity;
    ELSE
      INSERT INTO planet_defenses (planet_id, defense_type_id, quantity)
      VALUES (v_queue_item.planet_id, v_item_id, v_remaining_quantity)
      ON CONFLICT (planet_id, defense_type_id) DO UPDATE SET quantity = planet_defenses.quantity + v_remaining_quantity;
    END IF;

    -- Delete the queue item
    DELETE FROM shipyard_queue WHERE id = p_queue_id;

    -- Reorder remaining queue items and activate next item
    WITH reordered AS (
      SELECT id, ROW_NUMBER() OVER (ORDER BY queue_position) as new_pos 
      FROM shipyard_queue WHERE planet_id = v_queue_item.planet_id
    )
    UPDATE shipyard_queue sq SET 
      queue_position = r.new_pos,
      start_time = CASE WHEN r.new_pos = 1 AND sq.start_time IS NULL THEN NOW() ELSE sq.start_time END,
      current_unit_end_time = CASE WHEN r.new_pos = 1 AND sq.current_unit_end_time IS NULL THEN NOW() + (sq.build_time_per_unit || ' seconds')::interval ELSE sq.current_unit_end_time END
    FROM reordered r WHERE sq.id = r.id;

    PERFORM update_user_points(v_user_id);
    RETURN jsonb_build_object('success', true, 'fxu_spent', v_fxu_cost, 'quantity', v_remaining_quantity);
  END;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', 'Database error: ' || SQLERRM);
END;
$$;


