--
-- TOC entry 924 (class 1255 OID 20361)
-- Name: join_acs_attack(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_acs_attack(p_fleet_id uuid, p_invite_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fleet RECORD;
  v_acs RECORD;
  v_user_alliance_id uuid;
  v_target_planet record;
  v_protection_check jsonb;
BEGIN
  SELECT f.*,
    p.galaxy as origin_galaxy,
    p.solar_system as origin_system,
    p.position as origin_position
  INTO v_fleet
  FROM fleets f
  JOIN planets p ON f.origin_planet_id = p.id
  WHERE f.id = p_fleet_id
    AND f.user_id = auth.uid()
    AND f.is_completed = false
    AND f.is_returning = false
    AND f.mission_type = 'attack';

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Flota no encontrada o no es un ataque valido');
  END IF;

  IF v_fleet.acs_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Esta flota ya es parte de un ACS');
  END IF;

  SELECT * INTO v_acs
  FROM acs_fleets
  WHERE invite_code = p_invite_code
    AND is_active = true
    AND status = 'waiting';

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Codigo de invitacion invalido o ACS no disponible');
  END IF;

  SELECT am.alliance_id INTO v_user_alliance_id
  FROM alliance_members am
  WHERE am.user_id = auth.uid();

  IF v_user_alliance_id IS NULL OR v_user_alliance_id != v_acs.alliance_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Debes pertenecer a la misma alianza para unirte al ACS');
  END IF;

  SELECT * INTO v_target_planet
  FROM planets
  WHERE galaxy = v_acs.target_galaxy
    AND solar_system = v_acs.target_system
    AND position = v_acs.target_position
    AND NOT is_destroyed
  LIMIT 1;

  IF v_target_planet IS NOT NULL AND v_target_planet.user_id IS NOT NULL THEN
    IF v_target_planet.user_id = auth.uid() THEN
      RETURN jsonb_build_object('success', false, 'error', 'No puedes atacar tu propio planeta');
    END IF;

    v_protection_check := check_noob_protection(auth.uid(), v_target_planet.user_id);
    IF NOT COALESCE((v_protection_check->>'can_attack')::boolean, false) THEN
      RETURN jsonb_build_object('success', false, 'error', v_protection_check->>'reason');
    END IF;
  END IF;

  IF v_acs.current_participants >= v_acs.max_fleets THEN
    RETURN jsonb_build_object('success', false, 'error', 'El ACS ya tiene el maximo de participantes');
  END IF;

  IF v_fleet.target_galaxy != v_acs.target_galaxy OR
     v_fleet.target_system != v_acs.target_system OR
     v_fleet.target_position != v_acs.target_position THEN
    RETURN jsonb_build_object('success', false, 'error', 'La flota debe ir al mismo destino que el ACS');
  END IF;

  IF v_fleet.arrival_time > v_acs.arrival_time THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tu flota no puede llegar a tiempo para el ACS. Necesitas naves mas rapidas.');
  END IF;

  UPDATE fleets
  SET
    acs_id = v_acs.id,
    is_acs = true,
    arrival_time = v_acs.arrival_time,
    return_time = v_acs.arrival_time + (v_acs.arrival_time - departure_time)
  WHERE id = p_fleet_id;

  INSERT INTO acs_participants (acs_id, fleet_id, user_id)
  VALUES (v_acs.id, p_fleet_id, auth.uid());

  UPDATE acs_fleets
  SET current_participants = current_participants + 1
  WHERE id = v_acs.id;

  RETURN jsonb_build_object(
    'success', true,
    'acs_id', v_acs.id,
    'message', format('Te has unido al ACS "%s". Tu flota llegara sincronizada con el grupo.', v_acs.name)
  );
END;
$$;


--
-- TOC entry 714 (class 1255 OID 18947)
-- Name: join_acs_attack(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_acs_attack(p_acs_id uuid, p_fleet uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acs_record RECORD;
  v_fleet_record RECORD;
  v_user_id uuid;
  v_user_alliance uuid;
  v_new_arrival timestamptz;
  v_participant_count int;
  v_target_planet record;
  v_protection_check jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Usuario no autenticado');
  END IF;

  SELECT af.*, af.alliance_id as acs_alliance_id
  INTO v_acs_record
  FROM acs_fleets af
  WHERE af.id = p_acs_id
    AND af.is_active = true
    AND af.status = 'waiting'
    AND af.arrival_time > NOW();

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ataque ACS no encontrado o ya no esta disponible');
  END IF;

  SELECT am.alliance_id INTO v_user_alliance
  FROM alliance_members am
  WHERE am.user_id = v_user_id;

  IF v_user_alliance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Debes pertenecer a una alianza');
  END IF;

  IF v_user_alliance != v_acs_record.acs_alliance_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo miembros de la misma alianza pueden unirse');
  END IF;

  SELECT * INTO v_target_planet
  FROM planets
  WHERE galaxy = v_acs_record.target_galaxy
    AND solar_system = v_acs_record.target_system
    AND position = v_acs_record.target_position
    AND NOT is_destroyed
  LIMIT 1;

  IF v_target_planet IS NOT NULL AND v_target_planet.user_id IS NOT NULL THEN
    IF v_target_planet.user_id = v_user_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'No puedes atacar tu propio planeta');
    END IF;

    v_protection_check := check_noob_protection(v_user_id, v_target_planet.user_id);
    IF NOT COALESCE((v_protection_check->>'can_attack')::boolean, false) THEN
      RETURN jsonb_build_object('success', false, 'error', v_protection_check->>'reason');
    END IF;
  END IF;

  SELECT f.* INTO v_fleet_record
  FROM fleets f
  WHERE f.id = p_fleet
    AND f.user_id = v_user_id
    AND f.is_completed = false
    AND f.is_returning = false;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Flota no encontrada o no te pertenece');
  END IF;

  IF v_fleet_record.target_galaxy != v_acs_record.target_galaxy OR
     v_fleet_record.target_system != v_acs_record.target_system OR
     v_fleet_record.target_position != v_acs_record.target_position THEN
    RETURN jsonb_build_object('success', false, 'error', 'La flota debe tener el mismo destino que el ataque ACS');
  END IF;

  IF v_fleet_record.mission_type != 'attack' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo flotas de ataque pueden unirse a ataques ACS');
  END IF;

  IF v_fleet_record.acs_id IS NOT NULL OR v_fleet_record.is_acs = true THEN
    RETURN jsonb_build_object('success', false, 'error', 'Esta flota ya pertenece a un ataque ACS');
  END IF;

  SELECT COUNT(*) INTO v_participant_count FROM acs_participants WHERE acs_id = p_acs_id;
  IF v_participant_count >= v_acs_record.max_fleets THEN
    RETURN jsonb_build_object('success', false, 'error', 'El ataque ACS ya tiene el maximo de participantes');
  END IF;

  INSERT INTO acs_participants (acs_id, fleet_id, user_id)
  VALUES (p_acs_id, p_fleet, v_user_id);

  UPDATE fleets
  SET acs_id = p_acs_id, is_acs = true
  WHERE id = p_fleet;

  UPDATE acs_fleets
  SET current_participants = current_participants + 1
  WHERE id = p_acs_id;

  IF v_fleet_record.arrival_time > v_acs_record.arrival_time THEN
    v_new_arrival := v_fleet_record.arrival_time;
    UPDATE acs_fleets SET arrival_time = v_new_arrival WHERE id = p_acs_id;
    UPDATE fleets f
    SET arrival_time = v_new_arrival
    FROM acs_participants ap
    WHERE ap.acs_id = p_acs_id AND ap.fleet_id = f.id;
  ELSE
    UPDATE fleets SET arrival_time = v_acs_record.arrival_time WHERE id = p_fleet;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Te has unido al ataque ACS exitosamente'
  );
END;
$$;


--
-- TOC entry 923 (class 1255 OID 20359)
-- Name: join_acs_with_fleet(uuid, uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_acs_with_fleet(p_acs_id uuid, p_origin_planet_id uuid, p_fleet_ships jsonb, p_speed_percent integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$   
DECLARE
  v_user_id uuid;
  v_planet record;
  v_resources record;
  v_profile record;
  v_acs_record record;
  v_user_alliance uuid;
  v_distance int;
  v_slowest_speed int;
  v_flight_time int;
  v_fuel_consumption bigint;
  v_ship record;
  v_ship_type record;
  v_planet_ship record;
  v_total_cargo_capacity bigint := 0;
  v_fleet_id uuid;
  v_arrival_time timestamptz;
  v_return_time timestamptz;
  v_participant_count int;
  v_new_arrival timestamptz;
  v_computer_tech_level int := 0;
  v_has_admiral boolean;
  v_max_fleet_slots int;
  v_active_fleet_count int;
  v_target_planet record;
  v_protection_check jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  -- Lock the ACS record to prevent concurrent joins exceeding max_fleets
  SELECT * INTO v_acs_record
  FROM acs_fleets
  WHERE id = p_acs_id
    AND is_active = true
    AND status = 'waiting'
    AND arrival_time > NOW()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ataque ACS no encontrado o ya no esta disponible');
  END IF;

  SELECT am.alliance_id INTO v_user_alliance
  FROM alliance_members am
  WHERE am.user_id = v_user_id;

  IF v_user_alliance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Debes pertenecer a una alianza');
  END IF;

  IF v_user_alliance != v_acs_record.alliance_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo miembros de la misma alianza pueden unirse');
  END IF;

  SELECT * INTO v_target_planet
  FROM planets
  WHERE galaxy = v_acs_record.target_galaxy
    AND solar_system = v_acs_record.target_system
    AND position = v_acs_record.target_position
    AND NOT is_destroyed
  LIMIT 1;

  IF v_target_planet IS NOT NULL AND v_target_planet.user_id IS NOT NULL THEN
    IF v_target_planet.user_id = v_user_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'No puedes atacar tu propio planeta');
    END IF;

    v_protection_check := check_noob_protection(v_user_id, v_target_planet.user_id);
    IF NOT COALESCE((v_protection_check->>'can_attack')::boolean, false) THEN
      RETURN jsonb_build_object('success', false, 'error', v_protection_check->>'reason');
    END IF;
  END IF;

  SELECT COUNT(*) INTO v_participant_count FROM acs_participants WHERE acs_id = p_acs_id;
  IF v_participant_count >= v_acs_record.max_fleets THEN
    RETURN jsonb_build_object('success', false, 'error', 'El ataque ACS ya tiene el maximo de participantes');
  END IF;

  IF EXISTS (SELECT 1 FROM acs_participants WHERE acs_id = p_acs_id AND user_id = v_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya tienes una flota en este ataque ACS');
  END IF;

  SELECT * INTO v_planet FROM planets WHERE id = p_origin_planet_id AND user_id = v_user_id;
  IF v_planet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planeta no encontrado');
  END IF;

  SELECT * INTO v_profile FROM profiles WHERE id = v_user_id;
  IF v_profile.vacation_mode THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes enviar flotas en modo vacaciones');
  END IF;

  IF p_speed_percent < 10 OR p_speed_percent > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'La velocidad debe ser entre 10 y 100');
  END IF;

  -- Lock planet_resources to prevent concurrent fuel depletion
  SELECT * INTO v_resources FROM planet_resources WHERE planet_id = p_origin_planet_id FOR UPDATE;
  IF v_resources IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Recursos del planeta no encontrados');
  END IF;

  SELECT COALESCE(
    (SELECT level FROM user_technologies ut
     JOIN technology_types tt ON ut.technology_type_id = tt.id
     WHERE ut.user_id = v_user_id AND tt.code = 'computer_tech'), 0
  ) INTO v_computer_tech_level;

  v_has_admiral := has_active_officer(v_user_id, 'admiral');
  v_max_fleet_slots := 1 + v_computer_tech_level + (CASE WHEN v_has_admiral THEN 2 ELSE 0 END);

  SELECT COUNT(*) INTO v_active_fleet_count
  FROM fleets
  WHERE user_id = v_user_id AND is_completed = false;

  IF v_active_fleet_count >= v_max_fleet_slots THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes slots de flota disponibles');
  END IF;

  -- Validate and lock planet_ships FOR UPDATE to prevent concurrent ship subtraction
  FOR v_ship IN SELECT * FROM jsonb_to_recordset(p_fleet_ships) AS x(ship_type_id int, quantity int)
  LOOP
    IF v_ship.quantity > 0 THEN
      SELECT * INTO v_ship_type FROM ship_types WHERE id = v_ship.ship_type_id;
      IF v_ship_type IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Tipo de nave invalido: ' || v_ship.ship_type_id);
      END IF;

      -- FOR UPDATE lock to prevent race condition with concurrent fleet sends
      SELECT * INTO v_planet_ship
      FROM planet_ships
      WHERE planet_id = p_origin_planet_id AND ship_type_id = v_ship.ship_type_id
      FOR UPDATE;

      IF v_planet_ship IS NULL OR v_planet_ship.quantity < v_ship.quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Naves insuficientes: ' || v_ship_type.name);
      END IF;

      v_total_cargo_capacity := v_total_cargo_capacity + (v_ship_type.cargo_capacity * v_ship.quantity);
    END IF;
  END LOOP;

  v_distance := fleet_calc_distance(
    v_planet.galaxy, v_planet.solar_system, v_planet.position,
    v_acs_record.target_galaxy, v_acs_record.target_system, v_acs_record.target_position
  );

  v_slowest_speed := fleet_calc_slowest_speed(p_fleet_ships, v_user_id);
  IF v_slowest_speed <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No se seleccionaron naves validas con velocidad');
  END IF;

  v_flight_time := fleet_calc_flight_time(v_distance, v_slowest_speed, p_speed_percent, CASE WHEN v_has_admiral THEN 0.2 ELSE 0 END);

  -- VIP Plus: -10% flight time (stacks with Admiral)
  IF is_user_plus(v_user_id) THEN
    v_flight_time := GREATEST(10, FLOOR(v_flight_time * 0.90));
  END IF;
  v_fuel_consumption := fleet_calc_fuel(p_fleet_ships, v_distance, p_speed_percent);

  IF v_resources.deuterium < v_fuel_consumption THEN
    RETURN jsonb_build_object('success', false, 'error', 'Deuterio insuficiente para combustible');
  END IF;

  v_arrival_time := now() + (v_flight_time || ' seconds')::interval;
  v_return_time := now() + (v_flight_time * 2 || ' seconds')::interval;

  INSERT INTO fleets (
    user_id, origin_planet_id,
    target_galaxy, target_system, target_position,
    mission_type,
    cargo_metal, cargo_crystal, cargo_deuterium,
    departure_time, arrival_time, return_time,
    is_acs, acs_id
  ) VALUES (
    v_user_id, p_origin_planet_id,
    v_acs_record.target_galaxy, v_acs_record.target_system, v_acs_record.target_position,
    'attack',
    0, 0, 0,
    now(), v_arrival_time, v_return_time,
    true, p_acs_id
  ) RETURNING id INTO v_fleet_id;

  FOR v_ship IN SELECT * FROM jsonb_to_recordset(p_fleet_ships) AS x(ship_type_id int, quantity int)
  LOOP
    IF v_ship.quantity > 0 THEN
      INSERT INTO fleet_ships (fleet_id, ship_type_id, quantity)
      VALUES (v_fleet_id, v_ship.ship_type_id, v_ship.quantity);

      UPDATE planet_ships
      SET quantity = quantity - v_ship.quantity
      WHERE planet_id = p_origin_planet_id AND ship_type_id = v_ship.ship_type_id;
    END IF;
  END LOOP;

  UPDATE planet_resources
  SET deuterium = deuterium - v_fuel_consumption
  WHERE planet_id = p_origin_planet_id;

  INSERT INTO acs_participants (acs_id, fleet_id, user_id)
  VALUES (p_acs_id, v_fleet_id, v_user_id);

  UPDATE acs_fleets
  SET current_participants = current_participants + 1
  WHERE id = p_acs_id;

  IF v_arrival_time > v_acs_record.arrival_time THEN
    v_new_arrival := v_arrival_time;
    UPDATE acs_fleets SET arrival_time = v_new_arrival WHERE id = p_acs_id;
    UPDATE fleets f
    SET arrival_time = v_new_arrival
    FROM acs_participants ap
    WHERE ap.acs_id = p_acs_id AND ap.fleet_id = f.id;
  ELSE
    v_new_arrival := v_acs_record.arrival_time;
    UPDATE fleets SET arrival_time = v_new_arrival WHERE id = v_fleet_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'fleet_id', v_fleet_id,
    'arrival_time', v_new_arrival,
    'flight_time', v_flight_time,
    'fuel_consumption', v_fuel_consumption,
    'message', 'Te has unido al ataque ACS exitosamente'
  );
END;
   $$;


--
-- TOC entry 1099 (class 1255 OID 21690)
-- Name: join_alliance_war(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_alliance_war(p_war_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_war alliance_wars%ROWTYPE;
  v_member alliance_members%ROWTYPE;
  v_alliance alliances%ROWTYPE;
  v_fxu numeric;
  v_admin_id uuid;
  v_admin_amount integer;
  v_pool_amount integer;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_war FROM alliance_wars WHERE id = p_war_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Guerra no encontrada');
  END IF;

  IF v_war.status != 'open' THEN
    RETURN jsonb_build_object('success', false, 'error', 'La guerra no está abierta para inscripciones');
  END IF;

  -- Check user is leader of an alliance
  SELECT * INTO v_member FROM alliance_members WHERE user_id = v_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No perteneces a ninguna alianza');
  END IF;

  IF v_member.rank_level < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo el líder de la alianza puede inscribirla');
  END IF;

  -- Check alliance not already enrolled
  IF EXISTS (SELECT 1 FROM alliance_war_entries WHERE war_id = p_war_id AND alliance_id = v_member.alliance_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tu alianza ya está inscrita en esta guerra');
  END IF;

  SELECT * INTO v_alliance FROM alliances WHERE id = v_member.alliance_id;

  -- Check FXU balance
  SELECT COALESCE(fxu_balance, 0) INTO v_fxu FROM profiles WHERE id = v_user_id;
  IF v_fxu < v_war.entry_fee_fxu THEN
    RETURN jsonb_build_object('success', false, 'error', 'FXU insuficiente. Necesitas ' || v_war.entry_fee_fxu || ' FXU, tienes ' || v_fxu || ' FXU');
  END IF;

  -- Charge leader's FXU
  PERFORM _internal_set_fxu_context();
  UPDATE profiles SET fxu_balance = fxu_balance - v_war.entry_fee_fxu WHERE id = v_user_id;

  -- Split entry fee: 50% to pool, 25% admin, 25% reserve
  v_admin_amount := FLOOR(v_war.entry_fee_fxu * 0.50);  -- 50% to war pool
  v_pool_amount := v_war.entry_fee_fxu - v_admin_amount;  -- rest split admin/reserve later

  -- Add to war pool
  UPDATE alliance_wars SET total_pool_fxu = total_pool_fxu + v_war.entry_fee_fxu WHERE id = p_war_id;

  -- Register entry
  INSERT INTO alliance_war_entries (war_id, alliance_id, leader_id, paid_fee)
  VALUES (p_war_id, v_alliance.id, v_user_id, v_war.entry_fee_fxu);

  -- Initialize score at 0
  INSERT INTO alliance_war_scores (war_id, alliance_id, total_score, battle_count)
  VALUES (p_war_id, v_alliance.id, 0, 0)
  ON CONFLICT (war_id, alliance_id) DO NOTHING;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Alianza ' || v_alliance.name || ' inscrita en la guerra',
    'fee_paid', v_war.entry_fee_fxu,
    'total_pool', v_war.total_pool_fxu + v_war.entry_fee_fxu
  );
END;
$$;


--
-- TOC entry 641 (class 1255 OID 18649)
-- Name: join_open_alliance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_open_alliance(p_alliance_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_member_count int;
v_max_members int := 3;
v_is_open boolean;
v_existing_member boolean;
BEGIN
SELECT EXISTS(
SELECT 1 FROM alliance_members WHERE user_id = auth.uid()
) INTO v_existing_member;

IF v_existing_member THEN
RETURN jsonb_build_object('success', false, 'error', 'Ya perteneces a una alianza');
END IF;

SELECT is_open INTO v_is_open FROM alliances WHERE id = p_alliance_id;
IF v_is_open IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Alianza no encontrada');
END IF;

IF NOT v_is_open THEN
RETURN jsonb_build_object('success', false, 'error', 'Esta alianza requiere solicitud');
END IF;

SELECT COUNT(*) INTO v_member_count FROM alliance_members WHERE alliance_id = p_alliance_id;

IF v_member_count >= v_max_members THEN
RETURN jsonb_build_object(
'success', false,
'error', 'La alianza ha alcanzado el limite maximo de ' || v_max_members || ' miembros'
);
END IF;

INSERT INTO alliance_members (alliance_id, user_id)
VALUES (p_alliance_id, auth.uid());

UPDATE alliance_applications
SET status = 'rejected'
WHERE user_id = auth.uid() AND status = 'pending';

UPDATE alliances SET member_count = v_member_count + 1 WHERE id = p_alliance_id;

RETURN jsonb_build_object('success', true);
END;
$$;


--
-- TOC entry 858 (class 1255 OID 20020)
-- Name: kick_alliance_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kick_alliance_member(p_member_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_membership record;
  v_target_membership record;
  v_alliance record;
  v_is_leader boolean;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT * INTO v_user_membership
  FROM alliance_members
  WHERE user_id = v_user_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No estas en una alianza');
  END IF;
  
  IF NOT COALESCE(v_user_membership.can_kick, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes permiso para expulsar miembros');
  END IF;
  
  SELECT * INTO v_target_membership
  FROM alliance_members
  WHERE id = p_member_id AND alliance_id = v_user_membership.alliance_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Miembro no encontrado');
  END IF;
  
  IF v_target_membership.user_id = v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes expulsarte a ti mismo');
  END IF;
  
  SELECT * INTO v_alliance
  FROM alliances
  WHERE id = v_user_membership.alliance_id;
  
  v_is_leader := (v_user_id = v_alliance.leader_id);
  
  IF v_target_membership.user_id = v_alliance.leader_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes expulsar al lider');
  END IF;
  
  IF NOT v_is_leader AND v_target_membership.rank_level >= v_user_membership.rank_level THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes expulsar a alguien de mayor o igual rango');
  END IF;
  
  DELETE FROM alliance_members WHERE id = p_member_id;
  
  DELETE FROM alliance_applications
  WHERE user_id = v_target_membership.user_id AND alliance_id = v_user_membership.alliance_id;
  
  UPDATE alliances
  SET member_count = member_count - 1
  WHERE id = v_user_membership.alliance_id;
  
  INSERT INTO messages (recipient_id, subject, body, message_type)
  VALUES (
    v_target_membership.user_id,
    'Has sido expulsado de ' || v_alliance.name,
    'Has sido expulsado de la alianza [' || v_alliance.tag || '] ' || v_alliance.name || '.',
    'alliance'
  );
  
  RETURN jsonb_build_object('success', true, 'message', 'Miembro expulsado');
END;
$$;


--
-- TOC entry 690 (class 1255 OID 18890)
-- Name: launch_missiles(uuid, integer, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.launch_missiles(p_origin_planet_id uuid, p_target_galaxy integer, p_target_system integer, p_target_position integer, p_missile_count integer, p_primary_target text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_origin_planet record;
  v_target_planet record;
  v_target_owner record;
  v_attacker_id uuid;
  v_attacker_profile record;
  v_available_missiles integer;
  v_abm_count integer;
  v_effective_missiles integer;
  v_silo_level integer;
  v_impulse_level integer;
  v_max_range integer;
  v_actual_distance integer;
  v_destroyed_defenses jsonb := '[]'::jsonb;
  v_defense_record record;
  v_remaining_damage integer;
  v_defense_destroyed integer;
  v_ipm_damage_per_missile CONSTANT integer := 12000;
  v_protection_check jsonb;
  v_bashing_check jsonb;
  v_attacker_weapons_level integer;
  v_defender_armour_level integer;
  v_actual_damage_per_missile numeric;
  v_effective_integrity numeric;
BEGIN
  SELECT p.*, p.user_id as owner_id
  INTO v_origin_planet
  FROM planets p
  WHERE p.id = p_origin_planet_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planeta de origen no encontrado');
  END IF;

  v_attacker_id := v_origin_planet.owner_id;

  SELECT * INTO v_attacker_profile FROM profiles WHERE id = v_attacker_id;

  IF COALESCE(v_attacker_profile.vacation_mode, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes lanzar misiles en modo vacaciones');
  END IF;

  SELECT COALESCE(pb.level, 0) INTO v_silo_level
  FROM planet_buildings pb
  JOIN building_types bt ON pb.building_type_id = bt.id
  WHERE pb.planet_id = p_origin_planet_id AND bt.code = 'missile_silo';

  v_silo_level := COALESCE(v_silo_level, 0);

  IF v_silo_level < 4 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Necesitas Silo de Misiles nivel 4 para lanzar misiles interplanetarios');
  END IF;

  SELECT COALESCE(ut.level, 0) INTO v_impulse_level
  FROM user_technologies ut
  JOIN technology_types tt ON ut.technology_type_id = tt.id
  WHERE ut.user_id = v_attacker_id AND tt.code = 'impulse_drive';

  v_impulse_level := COALESCE(v_impulse_level, 0);

  IF v_impulse_level < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Necesitas Motor de Impulso nivel 1 para lanzar misiles');
  END IF;

  v_max_range := (v_impulse_level * 5) - 1;

  SELECT COALESCE(pd.quantity, 0) INTO v_available_missiles
  FROM planet_defenses pd
  JOIN defense_types dt ON pd.defense_type_id = dt.id
  WHERE pd.planet_id = p_origin_planet_id AND dt.code = 'interplanetary_missile';

  v_available_missiles := COALESCE(v_available_missiles, 0);

  IF v_available_missiles < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes misiles interplanetarios');
  END IF;

  IF v_available_missiles < p_missile_count THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('Solo tienes %s misiles interplanetarios disponibles', v_available_missiles)
    );
  END IF;

  IF v_origin_planet.galaxy != p_target_galaxy THEN
    RETURN jsonb_build_object('success', false, 'error', 'Los misiles solo pueden alcanzar objetivos en la misma galaxia');
  END IF;

  v_actual_distance := ABS(v_origin_planet.solar_system - p_target_system);

  IF v_actual_distance > v_max_range THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', format('Objetivo fuera de alcance. Motor de Impulso nivel %s permite %s sistemas. Distancia: %s sistemas.', 
        v_impulse_level, v_max_range, v_actual_distance)
    );
  END IF;

  SELECT p.* INTO v_target_planet
  FROM planets p
  WHERE p.galaxy = p_target_galaxy
    AND p.solar_system = p_target_system
    AND p.position = p_target_position
    AND p.planet_type = 'planet'
    AND NOT p.is_destroyed;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No hay planeta en esas coordenadas');
  END IF;

  IF v_target_planet.user_id = v_attacker_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes atacar tus propios planetas');
  END IF;

  IF v_target_planet.user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'El planeta objetivo no esta colonizado');
  END IF;

  SELECT * INTO v_target_owner FROM profiles WHERE id = v_target_planet.user_id;
  IF v_target_owner.vacation_mode = true THEN
    RETURN jsonb_build_object('success', false, 'error', 'El jugador objetivo esta en modo vacaciones');
  END IF;

  v_protection_check := check_noob_protection(v_attacker_id, v_target_planet.user_id);
  IF NOT (v_protection_check->>'can_attack')::boolean THEN
    RETURN jsonb_build_object('success', false, 'error', v_protection_check->>'reason');
  END IF;

  v_bashing_check := check_bashing_limit(v_attacker_id, v_target_planet.user_id);
  IF NOT (v_bashing_check->>'allowed')::boolean THEN
    RETURN jsonb_build_object('success', false, 'error', v_bashing_check->>'reason');
  END IF;

  -- Get attacker's Weapons Tech level for damage bonus
  SELECT COALESCE(ut.level, 0) INTO v_attacker_weapons_level
  FROM user_technologies ut
  JOIN technology_types tt ON ut.technology_type_id = tt.id
  WHERE ut.user_id = v_attacker_id AND tt.code = 'weapons_tech';

  v_attacker_weapons_level := COALESCE(v_attacker_weapons_level, 0);

  -- Get defender's Armour Tech level for structural bonus
  SELECT COALESCE(ut.level, 0) INTO v_defender_armour_level
  FROM user_technologies ut
  JOIN technology_types tt ON ut.technology_type_id = tt.id
  WHERE ut.user_id = v_target_planet.user_id AND tt.code = 'armour_tech';

  v_defender_armour_level := COALESCE(v_defender_armour_level, 0);

  -- IPM damage scaled by attacker's Weapons Tech
  v_actual_damage_per_missile := v_ipm_damage_per_missile * (1 + v_attacker_weapons_level * 0.10);

  SELECT COALESCE(pd.quantity, 0) INTO v_abm_count
  FROM planet_defenses pd
  JOIN defense_types dt ON pd.defense_type_id = dt.id
  WHERE pd.planet_id = v_target_planet.id AND dt.code = 'anti_ballistic_missile';

  v_abm_count := COALESCE(v_abm_count, 0);

  v_effective_missiles := GREATEST(0, p_missile_count - v_abm_count);

  UPDATE planet_defenses pd
  SET quantity = quantity - p_missile_count
  FROM defense_types dt
  WHERE pd.defense_type_id = dt.id 
    AND pd.planet_id = p_origin_planet_id 
    AND dt.code = 'interplanetary_missile';

  IF v_abm_count > 0 THEN
    UPDATE planet_defenses pd
    SET quantity = GREATEST(0, quantity - LEAST(p_missile_count, v_abm_count))
    FROM defense_types dt
    WHERE pd.defense_type_id = dt.id 
      AND pd.planet_id = v_target_planet.id 
      AND dt.code = 'anti_ballistic_missile';
  END IF;

  INSERT INTO attack_log (attacker_id, defender_id, target_planet_id)
  VALUES (v_attacker_id, v_target_planet.user_id, v_target_planet.id);

  IF v_effective_missiles > 0 THEN
    v_remaining_damage := FLOOR(v_effective_missiles * v_actual_damage_per_missile);

    FOR v_defense_record IN 
      SELECT pd.id, pd.quantity, dt.structural_integrity, dt.name, dt.code
      FROM planet_defenses pd
      JOIN defense_types dt ON pd.defense_type_id = dt.id
      WHERE pd.planet_id = v_target_planet.id 
        AND pd.quantity > 0
        AND dt.code NOT IN ('anti_ballistic_missile', 'interplanetary_missile')
      ORDER BY 
        CASE WHEN dt.code = p_primary_target THEN 0 ELSE 1 END,
        dt.structural_integrity ASC
    LOOP
      IF v_remaining_damage <= 0 THEN 
        EXIT; 
      END IF;

      -- Structural integrity scaled by defender's Armour Tech
      v_effective_integrity := v_defense_record.structural_integrity * (1 + v_defender_armour_level * 0.10);

      v_defense_destroyed := LEAST(
        v_defense_record.quantity,
        FLOOR(v_remaining_damage::numeric / GREATEST(1, v_effective_integrity))::integer
      );

      IF v_defense_destroyed > 0 THEN
        v_remaining_damage := v_remaining_damage - FLOOR(v_defense_destroyed * v_effective_integrity);

        UPDATE planet_defenses 
        SET quantity = quantity - v_defense_destroyed 
        WHERE id = v_defense_record.id;

        v_destroyed_defenses := v_destroyed_defenses || jsonb_build_object(
          'name', v_defense_record.name,
          'code', v_defense_record.code,
          'quantity', v_defense_destroyed
        );
      END IF;
    END LOOP;
  END IF;

  -- Send message to defender
  INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
  VALUES (
    NULL,
    v_target_planet.user_id,
    'Ataque de Misiles Interplanetarios',
    format(E'Tu planeta %s en [%s:%s:%s] ha sido atacado con misiles interplanetarios.\n\nMisiles recibidos: %s\nMisiles interceptados: %s\nMisiles impactados: %s\nDaño total: %s\n\nDefensas destruidas:\n%s',
      v_target_planet.name,
      p_target_galaxy, p_target_system, p_target_position,
      p_missile_count,
      LEAST(v_abm_count, p_missile_count),
      v_effective_missiles,
      FLOOR(v_effective_missiles * v_actual_damage_per_missile),
      CASE WHEN jsonb_array_length(v_destroyed_defenses) > 0
        THEN (SELECT string_agg(format('- %s x%s', elem->>'name', elem->>'quantity'), E'\n')
              FROM jsonb_array_elements(v_destroyed_defenses) elem)
        ELSE 'Ninguna'
      END
    ),
    'battle'
  );

  -- Send confirmation to attacker
  INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
  VALUES (
    NULL,
    v_attacker_id,
    'Informe de Ataque de Misiles',
    format(E'Has lanzado misiles interplanetarios a [%s:%s:%s].\n\nMisiles lanzados: %s\nMisiles interceptados: %s\nMisiles efectivos: %s\nDaño total: %s\n\nDefensas destruidas:\n%s',
      p_target_galaxy, p_target_system, p_target_position,
      p_missile_count,
      LEAST(v_abm_count, p_missile_count),
      v_effective_missiles,
      FLOOR(v_effective_missiles * v_actual_damage_per_missile),
      CASE WHEN jsonb_array_length(v_destroyed_defenses) > 0
        THEN (SELECT string_agg(format('- %s x%s', elem->>'name', elem->>'quantity'), E'\n')
              FROM jsonb_array_elements(v_destroyed_defenses) elem)
        ELSE 'Ninguna'
      END
    ),
    'battle'
  );

  RETURN jsonb_build_object(
    'success', true,
    'missiles_launched', p_missile_count,
    'missiles_intercepted', LEAST(v_abm_count, p_missile_count),
    'missiles_effective', v_effective_missiles,
    'total_damage', FLOOR(v_effective_missiles * v_actual_damage_per_missile),
    'destroyed_defenses', v_destroyed_defenses,
    'impulse_level', v_impulse_level,
    'max_range', v_max_range
  );
END;
$$;


--
-- TOC entry 857 (class 1255 OID 20019)
-- Name: leave_alliance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leave_alliance() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_membership record;
  v_member_count int;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT am.*, a.leader_id, a.id as alliance_id, a.name as alliance_name
  INTO v_membership
  FROM alliance_members am
  JOIN alliances a ON am.alliance_id = a.id
  WHERE am.user_id = v_user_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No estas en una alianza');
  END IF;
  
  SELECT COUNT(*) INTO v_member_count
  FROM alliance_members
  WHERE alliance_id = v_membership.alliance_id;
  
  IF v_membership.leader_id = v_user_id THEN
    IF v_member_count > 1 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Debes transferir el liderazgo antes de salir');
    END IF;
  END IF;
  
  DELETE FROM alliance_members WHERE user_id = v_user_id AND alliance_id = v_membership.alliance_id;
  
  DELETE FROM alliance_applications
  WHERE user_id = v_user_id AND alliance_id = v_membership.alliance_id;
  
  IF v_member_count = 1 THEN
    DELETE FROM alliance_applications WHERE alliance_id = v_membership.alliance_id;
    DELETE FROM alliance_diplomacy WHERE alliance_id = v_membership.alliance_id OR target_alliance_id = v_membership.alliance_id;
    DELETE FROM alliances WHERE id = v_membership.alliance_id;
    
    RETURN jsonb_build_object('success', true, 'message', 'Alianza disuelta');
  ELSE
    UPDATE alliances
    SET member_count = member_count - 1
    WHERE id = v_membership.alliance_id;
    
    RETURN jsonb_build_object('success', true, 'message', 'Has salido de la alianza');
  END IF;
END;
$$;


--
-- TOC entry 954 (class 1255 OID 20552)
-- Name: link_twitter_account(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_twitter_account(p_twitter_username text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_existing twitter_links%ROWTYPE;
  v_username text;
  v_config twitter_social_config%ROWTYPE;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Clean username (remove @ if present)
  v_username := trim(both ' ' from p_twitter_username);
  IF left(v_username, 1) = '@' THEN
    v_username := substring(v_username from 2);
  END IF;

  IF length(v_username) < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid username');
  END IF;

  -- Check if user already has a linked account
  SELECT * INTO v_existing FROM twitter_links WHERE user_id = v_user_id;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_linked', true,
      'twitter_username', v_existing.twitter_username
    );
  END IF;

  -- Check if this twitter username is already linked to another account
  SELECT * INTO v_existing FROM twitter_links WHERE lower(twitter_username) = lower(v_username);
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'This Twitter/X account is already linked to another game account'
    );
  END IF;

  -- Get config
  SELECT * INTO v_config FROM twitter_social_config LIMIT 1;

  -- Insert the link
  INSERT INTO twitter_links (user_id, twitter_username, linked_at, link_reward_claimed)
  VALUES (v_user_id, v_username, now(), true);

  -- Give FXU reward
  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
  UPDATE profiles SET fxu_balance = fxu_balance + COALESCE(v_config.link_reward_fxu, 20) WHERE id = v_user_id;
  PERFORM set_config('fxu.allow_update_9x7k2m', 'false', true);

  RETURN jsonb_build_object(
    'success', true,
    'twitter_username', v_username,
    'reward_given', true,
    'reward_amount', COALESCE(v_config.link_reward_fxu, 20),
    'message', 'Twitter/X account linked! +' || COALESCE(v_config.link_reward_fxu, 20) || ' FXU!'
  );
END;
$$;


--
-- TOC entry 1054 (class 1255 OID 21274)
-- Name: list_field_problems(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_field_problems() RETURNS TABLE(username text, planet_name text, planet_position integer, fields_used integer, fields_max integer, expected_max integer, problem text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    pr.username,
    p.name,
    p.position,
    p.fields_used,
    p.fields_max,
    public.calculate_planet_max_fields(p.id),
    CASE 
      WHEN p.fields_used > p.fields_max THEN 'OVERFLOW'::text
      WHEN p.fields_max < public.calculate_planet_max_fields(p.id) THEN 'UNDERESTIMATED'::text
      WHEN p.fields_max > public.calculate_planet_max_fields(p.id) THEN 'OVERESTIMATED'::text
      ELSE NULL::text
    END as problem
  FROM public.planets p
  LEFT JOIN public.profiles pr ON pr.id = p.user_id
  WHERE p.user_id IS NOT NULL
    AND p.planet_type = 'planet'
    AND (
      p.fields_used > p.fields_max
      OR p.fields_max != public.calculate_planet_max_fields(p.id)
    )
  ORDER BY 
    CASE 
      WHEN p.fields_used > p.fields_max THEN 1
      ELSE 2
    END,
    (p.fields_used - p.fields_max) DESC,
    p.diameter DESC;
END;
$$;


