--
-- TOC entry 1022 (class 1255 OID 20961)
-- Name: log_autopilot_event(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_autopilot_event(p_user_id uuid, p_planet_id uuid, p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.autopilot_events (user_id, planet_id, event_type, payload)
  VALUES (p_user_id, p_planet_id, p_event_type, COALESCE(p_payload, '{}'::jsonb));

  -- Mantener tabla acotada: borrar eventos de más de 7 días o >500 por usuario
  DELETE FROM public.autopilot_events
  WHERE user_id = p_user_id
    AND created_at < now() - interval '7 days';

  DELETE FROM public.autopilot_events
  WHERE id IN (
    SELECT id FROM public.autopilot_events
    WHERE user_id = p_user_id
    ORDER BY created_at DESC
    OFFSET 500
  );
END;
$$;


--
-- TOC entry 765 (class 1255 OID 19268)
-- Name: log_login_session(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_login_session(p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_fingerprint text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_real_ip text;
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  -- Try to get real IP from request headers (Supabase passes these)
  BEGIN
    -- X-Forwarded-For contains the original client IP when behind proxy/load balancer
    v_real_ip := current_setting('request.headers', true)::json->>'x-forwarded-for';
    
    -- X-Forwarded-For can contain multiple IPs, take the first one (original client)
    IF v_real_ip IS NOT NULL AND v_real_ip LIKE '%,%' THEN
      v_real_ip := split_part(v_real_ip, ',', 1);
    END IF;
    
    -- Fallback to X-Real-IP if X-Forwarded-For not available
    IF v_real_ip IS NULL OR v_real_ip = '' THEN
      v_real_ip := current_setting('request.headers', true)::json->>'x-real-ip';
    END IF;
    
    -- Fallback to CF-Connecting-IP (Cloudflare)
    IF v_real_ip IS NULL OR v_real_ip = '' THEN
      v_real_ip := current_setting('request.headers', true)::json->>'cf-connecting-ip';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_real_ip := NULL;
  END;

  -- Final fallback: use parameter if provided and valid, otherwise 'unknown'
  IF v_real_ip IS NULL OR v_real_ip = '' OR v_real_ip = 'client' THEN
    IF p_ip_address IS NOT NULL AND p_ip_address != '' AND p_ip_address != 'client' THEN
      v_real_ip := p_ip_address;
    ELSE
      v_real_ip := 'unknown';
    END IF;
  END IF;

  -- Trim whitespace
  v_real_ip := TRIM(v_real_ip);

  INSERT INTO login_sessions (user_id, ip_address, user_agent, fingerprint, country_code)
  VALUES (v_user_id, v_real_ip, p_user_agent, p_fingerprint, p_country_code);
END;
$$;


--
-- TOC entry 7780 (class 0 OID 0)
