    );
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- TOC entry 775 (class 1255 OID 19279)
-- Name: log_transport_interaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_transport_interaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target_planet RECORD;
  v_target_user_id uuid;
BEGIN
  IF NEW.is_completed = true AND OLD.is_completed = false 
     AND NEW.mission_type = 'transport' 
     AND NEW.is_returning = false THEN
    
    SELECT p.user_id INTO v_target_user_id
    FROM planets p
    WHERE p.galaxy = NEW.target_galaxy
      AND p.solar_system = NEW.target_system
      AND p.position = NEW.target_position
      AND p.planet_type = COALESCE(NEW.target_type, 'planet')
    LIMIT 1;
    
    IF v_target_user_id IS NOT NULL AND v_target_user_id != NEW.user_id THEN
      INSERT INTO account_interaction_log (
        from_user_id,
        to_user_id,
        interaction_type,
        metal_amount,
        crystal_amount,
        deuterium_amount
      ) VALUES (
        NEW.user_id,
        v_target_user_id,
        'transport',
        COALESCE(NEW.cargo_metal, 0),
        COALESCE(NEW.cargo_crystal, 0),
        COALESCE(NEW.cargo_deuterium, 0)
      );
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- TOC entry 683 (class 1255 OID 18876)
-- Name: mark_withdrawal_signed(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_withdrawal_signed(p_tx_id uuid, p_signature text, p_expiry bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_expiry_ts timestamptz;
BEGIN
  v_expiry_ts := to_timestamp(p_expiry);

  UPDATE wallet_transactions
  SET 
    status = 'processing',
    signature_data = jsonb_build_object(
      'signature', p_signature,
      'expiry', p_expiry,
      'generated_at', EXTRACT(EPOCH FROM now())::bigint
    ),
    signature_expiry = v_expiry_ts,
    updated_at = now()
  WHERE id = p_tx_id AND status = 'pending';

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction not found or not pending');
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- TOC entry 903 (class 1255 OID 20183)
-- Name: notify_alliance_attack_launched(uuid, integer, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_alliance_attack_launched(p_attacker_id uuid, p_target_galaxy integer, p_target_system integer, p_target_position integer, p_arrival_time timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_attacker_username text;
  v_alliance_id uuid;
  v_member RECORD;
  v_coords text;
  v_arrival_text text;
BEGIN
  SELECT username INTO v_attacker_username FROM profiles WHERE id = p_attacker_id;
  IF v_attacker_username IS NULL THEN
    RETURN;
  END IF;

  SELECT alliance_id INTO v_alliance_id FROM alliance_members WHERE user_id = p_attacker_id;

  v_coords := format('[%s:%s:%s]', p_target_galaxy, p_target_system, p_target_position);
  v_arrival_text := to_char(p_arrival_time AT TIME ZONE 'UTC', 'HH24:MI:SS DD/MM');

  INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
  VALUES (
    NULL,
    p_attacker_id,
    format('Ataque lanzado a %s', v_coords),
    format(E'Tu flota de ataque ha sido enviada a %s.\n\nLlegada estimada: %s UTC', v_coords, v_arrival_text),
    'alliance'
  );

  IF v_alliance_id IS NOT NULL THEN
    FOR v_member IN
      SELECT user_id FROM alliance_members
      WHERE alliance_id = v_alliance_id AND user_id != p_attacker_id
    LOOP
      INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
      VALUES (
        NULL,
        v_member.user_id,
        format('Aliado %s lanzo un ataque', v_attacker_username),
        format(E'Tu aliado %s ha lanzado un ataque a %s.\n\nLlegada estimada: %s UTC\n\nPuedes unirte con un ataque ACS desde la pagina de Flotas.', v_attacker_username, v_coords, v_arrival_text),
        'alliance'
      );
    END LOOP;
  END IF;
END;
$$;


--
-- TOC entry 643 (class 1255 OID 18652)
-- Name: notify_hostile_fleet_incoming(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_hostile_fleet_incoming() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  target_planet RECORD;
  attacker_profile RECORD;
  attacker_planet RECORD;
  mission_text TEXT;
  time_remaining INTERVAL;
BEGIN
  -- Only notify for hostile missions (attack, espionage, destroy)
  IF NEW.mission_type NOT IN ('attack', 'espionage', 'destroy') THEN
    RETURN NEW;
  END IF;
  
  -- Find the target planet and its owner
  SELECT p.*, pr.username as owner_name
  INTO target_planet
  FROM planets p
  LEFT JOIN profiles pr ON p.user_id = pr.id
  WHERE p.galaxy = NEW.target_galaxy
    AND p.solar_system = NEW.target_system
    AND p.position = NEW.target_position
    AND p.planet_type = COALESCE(NEW.target_type, 'planet');
  
  -- Only notify if target belongs to another player
  IF NOT FOUND OR target_planet.user_id IS NULL OR target_planet.user_id = NEW.user_id THEN
    RETURN NEW;
  END IF;
  
  -- Get attacker info
  SELECT username INTO attacker_profile FROM profiles WHERE id = NEW.user_id;
  SELECT galaxy, solar_system, position INTO attacker_planet FROM planets WHERE id = NEW.origin_planet_id;
  
  -- Set mission text based on type
  CASE NEW.mission_type
    WHEN 'attack' THEN mission_text := 'atacando';
    WHEN 'espionage' THEN mission_text := 'espiando';
    WHEN 'destroy' THEN mission_text := 'destruyendo';
    ELSE mission_text := 'enviando flota a';
  END CASE;
  
  -- Calculate time remaining
  time_remaining := NEW.arrival_time - NOW();
  
  -- Send notification message to defender
  INSERT INTO messages (
    sender_id,
    recipient_id,
    subject,
    body,
    message_type
  ) VALUES (
    NULL,
    target_planet.user_id,
    'Flota hostil detectada!',
    format('El jugador %s [%s:%s:%s] te esta %s en %s [%s:%s:%s]. Tiempo estimado de llegada: %s',
      COALESCE(attacker_profile.username, 'Desconocido'),
      COALESCE(attacker_planet.galaxy, 0),
      COALESCE(attacker_planet.solar_system, 0),
      COALESCE(attacker_planet.position, 0),
      mission_text,
      target_planet.name,
      NEW.target_galaxy,
      NEW.target_system,
      NEW.target_position,
      CASE 
        WHEN time_remaining < interval '1 minute' THEN 'menos de 1 minuto'
        WHEN time_remaining < interval '1 hour' THEN floor(extract(epoch from time_remaining) / 60) || ' minutos'
        ELSE floor(extract(epoch from time_remaining) / 3600) || ' horas ' || 
             floor(mod(extract(epoch from time_remaining), 3600) / 60) || ' minutos'
      END
    ),
    'fleet_warning'
  );
  
  RETURN NEW;
END;
$$;


--
-- TOC entry 895 (class 1255 OID 20157)
-- Name: notify_telegram_dm_on_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_telegram_dm_on_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_config RECORD;
  v_has_telegram boolean;
  v_has_plus boolean;
  v_msg_type text;
  v_request_id bigint;
BEGIN
  -- Get DM config
  SELECT edge_function_url, anon_key, is_enabled INTO v_config
  FROM telegram_dm_config
  WHERE id = 1;

  IF v_config IS NULL OR NOT v_config.is_enabled OR v_config.edge_function_url = '' THEN
    RETURN NEW;
  END IF;

  IF NEW.recipient_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Check if user has Telegram linked
  SELECT EXISTS (
    SELECT 1 FROM telegram_links
    WHERE user_id = NEW.recipient_id
      AND telegram_id IS NOT NULL
  ) INTO v_has_telegram;

  IF NOT v_has_telegram THEN
    RETURN NEW;
  END IF;

  -- Determine message type
  v_msg_type := COALESCE(NEW.message_type, 'system');

  -- VIP check: ALL notifications require active Plus subscription
  -- EXCEPT broadcast (admin announcements) which always reach everyone
  IF v_msg_type <> 'broadcast' THEN
    SELECT EXISTS (
      SELECT 1 FROM plus_subscriptions
      WHERE user_id = NEW.recipient_id
        AND is_active = true
        AND expires_at > now()
    ) INTO v_has_plus;

    IF NOT v_has_plus THEN
      -- Not VIP: skip Telegram DM (in-game message is still saved)
      RETURN NEW;
    END IF;
  END IF;

  -- Send Telegram DM via edge function
  SELECT net.http_post(
    url := v_config.edge_function_url,
    body := jsonb_build_object(
      'recipient_id', NEW.recipient_id,
      'subject', NEW.subject,
      'body', LEFT(COALESCE(NEW.body, ''), 600),
      'message_type', v_msg_type
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', v_config.anon_key
    )
  ) INTO v_request_id;

  RETURN NEW;

EXCEPTION
  WHEN OTHERS THEN
    RAISE NOTICE 'Telegram DM notification error: %', SQLERRM;
    RETURN NEW;
END;
$$;


--
-- TOC entry 889 (class 1255 OID 20101)
-- Name: optimized_global_queue_processor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.optimized_global_queue_processor() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$

DECLARE
v_building_count integer := 0;
v_shipyard_count integer := 0;
v_research_count integer := 0;
v_fleet_count integer := 0;
v_has_pending boolean;
v_queue_item record;
v_now timestamptz := NOW();
v_build_time_ms bigint;
v_elapsed_ms bigint;
v_units_to_complete integer;
v_remaining_units integer;
v_next_item record;
v_affected_users uuid[] := ARRAY[]::uuid[];
v_stuck RECORD;
v_is_lunar_base boolean;
v_is_moon boolean;
BEGIN
ALTER TABLE planet_buildings DISABLE TRIGGER trigger_building_points;
ALTER TABLE planet_ships DISABLE TRIGGER trigger_fleet_points;
ALTER TABLE planet_defenses DISABLE TRIGGER trigger_defense_points;

-- =========================================================================
-- BUILDING QUEUE
-- =========================================================================
BEGIN
SELECT EXISTS(
SELECT 1 FROM building_queue
WHERE end_time IS NOT NULL AND end_time <= v_now
LIMIT 1
) INTO v_has_pending;

IF v_has_pending THEN
FOR v_queue_item IN
SELECT bq.id, bq.planet_id, bq.building_type_id, bq.target_level,
bq.queue_position, bq.end_time, p.user_id
FROM building_queue bq
JOIN planets p ON p.id = bq.planet_id
WHERE bq.end_time IS NOT NULL AND bq.end_time <= v_now
ORDER BY bq.planet_id, bq.end_time
LIMIT 100
FOR UPDATE OF bq SKIP LOCKED
LOOP
BEGIN
INSERT INTO planet_buildings (planet_id, building_type_id, level, is_upgrading, upgrade_end_time)
VALUES (v_queue_item.planet_id, v_queue_item.building_type_id, v_queue_item.target_level, false, NULL)
ON CONFLICT (planet_id, building_type_id)
DO UPDATE SET
level = GREATEST(planet_buildings.level, EXCLUDED.level),
is_upgrading = false,
upgrade_end_time = NULL;

UPDATE planets SET fields_used = LEAST(fields_max, fields_used + 1)
WHERE id = v_queue_item.planet_id;

-- If this is a Lunar Base on a moon, update fields_max
SELECT
v_queue_item.building_type_id = 15,
pl.planet_type = 'moon'
INTO v_is_lunar_base, v_is_moon
FROM planets pl WHERE pl.id = v_queue_item.planet_id;

IF v_is_lunar_base AND v_is_moon THEN
UPDATE planets
SET fields_max = 2 + (v_queue_item.target_level * 3)
WHERE id = v_queue_item.planet_id;
END IF;

DELETE FROM building_queue WHERE id = v_queue_item.id;
v_building_count := v_building_count + 1;

IF NOT (v_queue_item.user_id = ANY(v_affected_users)) THEN
v_affected_users := array_append(v_affected_users, v_queue_item.user_id);
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Cron: Error building %: %', v_queue_item.id, SQLERRM;
END;
END LOOP;

UPDATE building_queue bq
SET queue_position = sub.new_pos
FROM (
SELECT id, ROW_NUMBER() OVER (PARTITION BY planet_id ORDER BY queue_position) as new_pos
FROM building_queue
) sub
WHERE bq.id = sub.id AND bq.queue_position != sub.new_pos;

UPDATE building_queue
SET start_time = v_now,
end_time = v_now + (build_time * INTERVAL '1 second')
WHERE queue_position = 1 AND start_time IS NULL;
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Cron: Building section error: %', SQLERRM;
END;

-- =========================================================================
-- SHIPYARD QUEUE
-- =========================================================================
BEGIN
FOR v_stuck IN
SELECT sq.id, sq.planet_id, sq.queue_position, p.user_id
FROM shipyard_queue sq
JOIN planets p ON p.id = sq.planet_id
WHERE sq.quantity_completed >= sq.quantity
ORDER BY sq.planet_id, sq.queue_position
FOR UPDATE OF sq SKIP LOCKED
LOOP
BEGIN
DELETE FROM shipyard_queue WHERE id = v_stuck.id;

UPDATE shipyard_queue
SET queue_position = queue_position - 1
WHERE planet_id = v_stuck.planet_id
AND queue_position > v_stuck.queue_position;

UPDATE shipyard_queue
SET start_time = v_now,
current_unit_end_time = v_now + (build_time_per_unit || ' seconds')::interval
WHERE planet_id = v_stuck.planet_id
AND queue_position = 1
AND start_time IS NULL;

IF NOT (v_stuck.user_id = ANY(v_affected_users)) THEN
v_affected_users := array_append(v_affected_users, v_stuck.user_id);
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Cron: Error cleaning stuck shipyard %: %', v_stuck.id, SQLERRM;
END;
END LOOP;

UPDATE shipyard_queue
SET
start_time = COALESCE(start_time, v_now),
current_unit_end_time = COALESCE(start_time, v_now) + (build_time_per_unit || ' seconds')::interval
WHERE queue_position = 1
AND current_unit_end_time IS NULL;

SELECT EXISTS(
SELECT 1 FROM shipyard_queue
WHERE queue_position = 1
AND current_unit_end_time IS NOT NULL
AND current_unit_end_time <= v_now
LIMIT 1
) INTO v_has_pending;

IF v_has_pending THEN
FOR v_queue_item IN
SELECT sq.*, p.user_id
FROM shipyard_queue sq
JOIN planets p ON p.id = sq.planet_id
WHERE sq.queue_position = 1
AND sq.current_unit_end_time IS NOT NULL
AND sq.current_unit_end_time <= v_now
ORDER BY sq.current_unit_end_time
LIMIT 100
FOR UPDATE OF sq SKIP LOCKED
LOOP
BEGIN
v_build_time_ms := GREATEST(1000, v_queue_item.build_time_per_unit * 1000);
v_elapsed_ms := EXTRACT(EPOCH FROM (v_now - v_queue_item.current_unit_end_time)) * 1000 + v_build_time_ms;
v_remaining_units := v_queue_item.quantity - v_queue_item.quantity_completed;
v_units_to_complete := LEAST(
FLOOR(v_elapsed_ms / v_build_time_ms)::integer,
v_remaining_units
);

IF v_units_to_complete > 0 THEN
IF v_queue_item.item_type = 'ship' AND v_queue_item.ship_type_id IS NOT NULL THEN
INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
VALUES (v_queue_item.planet_id, v_queue_item.ship_type_id, v_units_to_complete)
ON CONFLICT (planet_id, ship_type_id)
DO UPDATE SET quantity = planet_ships.quantity + EXCLUDED.quantity;
ELSIF v_queue_item.item_type = 'defense' AND v_queue_item.defense_type_id IS NOT NULL THEN
INSERT INTO planet_defenses (planet_id, defense_type_id, quantity)
VALUES (v_queue_item.planet_id, v_queue_item.defense_type_id, v_units_to_complete)
ON CONFLICT (planet_id, defense_type_id)
DO UPDATE SET quantity = planet_defenses.quantity + EXCLUDED.quantity;
END IF;

v_shipyard_count := v_shipyard_count + v_units_to_complete;

IF NOT (v_queue_item.user_id = ANY(v_affected_users)) THEN
v_affected_users := array_append(v_affected_users, v_queue_item.user_id);
END IF;

IF v_queue_item.quantity_completed + v_units_to_complete >= v_queue_item.quantity THEN
DELETE FROM shipyard_queue WHERE id = v_queue_item.id;

SELECT * INTO v_next_item
FROM shipyard_queue
WHERE planet_id = v_queue_item.planet_id AND queue_position = 2
LIMIT 1;

IF FOUND THEN
UPDATE shipyard_queue
SET queue_position = 1,
start_time = v_now,
current_unit_end_time = v_now + (build_time_per_unit * INTERVAL '1 second')
WHERE id = v_next_item.id;

UPDATE shipyard_queue
SET queue_position = queue_position - 1
WHERE planet_id = v_queue_item.planet_id AND queue_position > 2;
END IF;
ELSE
UPDATE shipyard_queue
SET quantity_completed = quantity_completed + v_units_to_complete,
current_unit_end_time = v_now + (build_time_per_unit * INTERVAL '1 second')
WHERE id = v_queue_item.id;
END IF;
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Cron: Error shipyard %: %', v_queue_item.id, SQLERRM;
END;
END LOOP;
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Cron: Shipyard section error: %', SQLERRM;
END;

ALTER TABLE planet_buildings ENABLE TRIGGER trigger_building_points;
ALTER TABLE planet_ships ENABLE TRIGGER trigger_fleet_points;
ALTER TABLE planet_defenses ENABLE TRIGGER trigger_defense_points;

-- =========================================================================
-- RESEARCH
-- =========================================================================
BEGIN
SELECT EXISTS(
SELECT 1 FROM user_technologies
WHERE is_researching = true
AND research_end_time IS NOT NULL
AND research_end_time <= v_now
LIMIT 1
) INTO v_has_pending;

IF v_has_pending THEN
FOR v_queue_item IN
SELECT ut.id, ut.user_id
FROM user_technologies ut
WHERE ut.is_researching = true
AND ut.research_end_time IS NOT NULL
AND ut.research_end_time <= v_now
FOR UPDATE OF ut SKIP LOCKED
LOOP
BEGIN
UPDATE user_technologies
SET level = level + 1,
is_researching = false,
research_end_time = NULL,
research_planet_id = NULL
WHERE id = v_queue_item.id;

v_research_count := v_research_count + 1;

IF NOT (v_queue_item.user_id = ANY(v_affected_users)) THEN
v_affected_users := array_append(v_affected_users, v_queue_item.user_id);
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Cron: Error research %: %', v_queue_item.id, SQLERRM;
END;
END LOOP;
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Cron: Research error: %', SQLERRM;
END;

-- =========================================================================
-- FLEETS
-- =========================================================================
BEGIN
SELECT EXISTS(
SELECT 1 FROM fleets
WHERE is_completed = false
AND (
(NOT is_returning AND arrival_time IS NOT NULL AND arrival_time <= v_now)
OR (is_returning AND return_time IS NOT NULL AND return_time <= v_now)
)
LIMIT 1
) INTO v_has_pending;

IF v_has_pending THEN
SELECT COALESCE((process_all_pending_fleets()->>'processed_count')::integer, 0) INTO v_fleet_count;
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Cron: Fleet error: %', SQLERRM;
END;

-- =========================================================================
-- BATCH POINTS UPDATE
-- =========================================================================
BEGIN
IF array_length(v_affected_users, 1) > 0 THEN
UPDATE profiles p
SET
points_buildings = COALESCE((
SELECT SUM(
CASE WHEN bt.metal_cost > 0 OR bt.crystal_cost > 0 OR bt.deuterium_cost > 0
THEN (bt.metal_cost + bt.crystal_cost + bt.deuterium_cost) *
(POWER(bt.cost_factor, pb.level) - 1) / (bt.cost_factor - 1) / 1000
ELSE 0 END
)
FROM planet_buildings pb
JOIN building_types bt ON bt.id = pb.building_type_id
JOIN planets pl ON pl.id = pb.planet_id
WHERE pl.user_id = p.id AND pb.level > 0
), 0),
points_fleet = COALESCE((
          SELECT SUM((st.metal_cost + st.crystal_cost + st.deuterium_cost) * ps.quantity / 1000)
          FROM planet_ships ps
          JOIN ship_types st ON st.id = ps.ship_type_id
          JOIN planets pl ON pl.id = ps.planet_id
          WHERE pl.user_id = p.id AND ps.quantity > 0
        ), 0) + COALESCE((
          SELECT SUM((st2.metal_cost + st2.crystal_cost + st2.deuterium_cost) * fs.quantity / 1000)
          FROM fleet_ships fs
          JOIN fleets fl ON fl.id = fs.fleet_id
          JOIN ship_types st2 ON st2.id = fs.ship_type_id
          WHERE fl.user_id = p.id AND fl.is_completed = false AND fs.quantity > 0
        ), 0),
points_defense = COALESCE((
SELECT SUM((dt.metal_cost + dt.crystal_cost + dt.deuterium_cost) * pd.quantity / 1000)
FROM planet_defenses pd
JOIN defense_types dt ON dt.id = pd.defense_type_id
JOIN planets pl ON pl.id = pd.planet_id
WHERE pl.user_id = p.id AND pd.quantity > 0
), 0),
updated_at = now()
WHERE p.id = ANY(v_affected_users);

UPDATE profiles
SET points_total = COALESCE(points_buildings, 0) + COALESCE(points_research, 0) + COALESCE(points_fleet, 0) + COALESCE(points_defense, 0)
WHERE id = ANY(v_affected_users);
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Cron: Points update error: %', SQLERRM;
END;

-- =========================================================================
-- GLOBAL RANKING UPDATE
-- =========================================================================
-- Rankings moved to separate cron job (every 10h)

RETURN jsonb_build_object(
'success', true,
'buildings_completed', v_building_count,
'shipyard_completed', v_shipyard_count,
'research_completed', v_research_count,
'fleets_processed', v_fleet_count,
'affected_users', array_length(v_affected_users, 1),
'timestamp', v_now
);
END;

$$;


--
-- TOC entry 1029 (class 1255 OID 21194)
-- Name: p2p_accept_offer(uuid, numeric, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p2p_accept_offer(p_offer_id uuid, p_asset_amount numeric, p_payment_method_id integer, p_buyer_payment_details jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_offer p2p_offers%ROWTYPE;
  v_order_id uuid;
  v_fiat_amount numeric;
  v_fee_percent numeric;
  v_fee_asset numeric;
  v_taker_fxu numeric;
  v_taker_usdt numeric;
  v_internal_fiat boolean;
BEGIN
  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
  PERFORM p2p_expire_stale_offers();

  IF v_user_id IS NULL THEN RAISE EXCEPTION 'No autenticado'; END IF;
  IF p_asset_amount <= 0 THEN RAISE EXCEPTION 'Monto invalido'; END IF;

  SELECT * INTO v_offer FROM p2p_offers WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Oferta no existe'; END IF;
  IF v_offer.status <> 'active' THEN RAISE EXCEPTION 'Oferta no esta activa'; END IF;
  IF v_offer.expires_at <= now() THEN
    RAISE EXCEPTION 'La oferta ha vencido';
  END IF;

  IF v_offer.user_id = v_user_id THEN
    RAISE EXCEPTION 'No puedes tomar tu propia oferta';
  END IF;

  IF NOT (p_payment_method_id = ANY(v_offer.payment_method_ids)) THEN
    RAISE EXCEPTION 'Metodo de pago no permitido para esta oferta';
  END IF;

  IF p_asset_amount > v_offer.available_amount THEN
    RAISE EXCEPTION 'No hay liquidez suficiente';
  END IF;

  IF v_offer.min_trade_amount > 0 AND p_asset_amount < v_offer.min_trade_amount THEN
    RAISE EXCEPTION 'Monto menor al minimo';
  END IF;

  IF v_offer.max_trade_amount IS NOT NULL AND p_asset_amount > v_offer.max_trade_amount THEN
    RAISE EXCEPTION 'Monto mayor al maximo';
  END IF;

  SELECT COALESCE(value::numeric, 1) INTO v_fee_percent
  FROM game_settings WHERE key = 'p2p_fee_percent';
  v_fee_percent := COALESCE(v_fee_percent, 1);

  v_fee_asset := round((p_asset_amount * v_fee_percent / 100.0)::numeric, 8);
  v_fiat_amount := round((p_asset_amount * v_offer.price_per_unit)::numeric, 8);
  v_internal_fiat := upper(v_offer.fiat_currency) IN ('FXU','USDT');

  SELECT fxu_balance, usdt_balance INTO v_taker_fxu, v_taker_usdt
  FROM profiles
  WHERE id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Perfil del tomador no encontrado'; END IF;

  IF v_offer.side = 'sell' THEN
    IF v_internal_fiat THEN
      IF upper(v_offer.fiat_currency) = 'FXU' THEN
        IF COALESCE(v_taker_fxu, 0) < v_fiat_amount THEN
          RAISE EXCEPTION 'Comprador sin saldo FXU suficiente';
        END IF;
        UPDATE profiles SET fxu_balance = fxu_balance - v_fiat_amount WHERE id = v_user_id;
      ELSE
        IF COALESCE(v_taker_usdt, 0) < v_fiat_amount THEN
          RAISE EXCEPTION 'Comprador sin saldo USDT suficiente';
        END IF;
        UPDATE profiles SET usdt_balance = usdt_balance - v_fiat_amount WHERE id = v_user_id;
      END IF;
    END IF;
  ELSE
    IF v_offer.asset = 'FXU' THEN
      IF COALESCE(v_taker_fxu, 0) < p_asset_amount THEN
        RAISE EXCEPTION 'Vendedor sin saldo FXU suficiente';
      END IF;
      UPDATE profiles SET fxu_balance = fxu_balance - p_asset_amount WHERE id = v_user_id;
    ELSE
      IF COALESCE(v_taker_usdt, 0) < p_asset_amount THEN
        RAISE EXCEPTION 'Vendedor sin saldo USDT suficiente';
      END IF;
      UPDATE profiles SET usdt_balance = usdt_balance - p_asset_amount WHERE id = v_user_id;
    END IF;
  END IF;

  UPDATE p2p_offers
  SET available_amount = available_amount - p_asset_amount,
      updated_at = now()
  WHERE id = v_offer.id;

  IF v_offer.side = 'sell' THEN
    INSERT INTO p2p_orders (
      offer_id, seller_id, buyer_id, asset, asset_amount,
      fiat_currency, fiat_amount, price_per_unit,
      payment_method_id, buyer_payment_details,
      fee_asset, fee_percent,
      payment_deadline, status
    ) VALUES (
      v_offer.id, v_offer.user_id, v_user_id, v_offer.asset, p_asset_amount,
      v_offer.fiat_currency, v_fiat_amount, v_offer.price_per_unit,
      p_payment_method_id, coalesce(p_buyer_payment_details, '{}'::jsonb),
      v_fee_asset, v_fee_percent,
      now() + make_interval(mins => v_offer.time_limit_minutes), 'pending_payment'
    ) RETURNING id INTO v_order_id;
  ELSE
    INSERT INTO p2p_orders (
      offer_id, seller_id, buyer_id, asset, asset_amount,
      fiat_currency, fiat_amount, price_per_unit,
      payment_method_id, buyer_payment_details,
      fee_asset, fee_percent,
      payment_deadline, status
    ) VALUES (
      v_offer.id, v_user_id, v_offer.user_id, v_offer.asset, p_asset_amount,
      v_offer.fiat_currency, v_fiat_amount, v_offer.price_per_unit,
      p_payment_method_id, coalesce(p_buyer_payment_details, '{}'::jsonb),
      v_fee_asset, v_fee_percent,
      now() + make_interval(mins => v_offer.time_limit_minutes), 'pending_payment'
    ) RETURNING id INTO v_order_id;
  END IF;

  INSERT INTO p2p_audit_log(order_id, offer_id, actor_id, action, meta)
  VALUES (
    v_order_id,
    v_offer.id,
    v_user_id,
    'order_created',
    jsonb_build_object(
      'asset_amount', p_asset_amount,
      'fiat_amount', v_fiat_amount,
      'fee_asset', v_fee_asset,
      'fee_percent', v_fee_percent,
      'internal_fiat', v_internal_fiat,
      'escrowed_by_taker', (v_offer.side = 'buy') OR (v_offer.side = 'sell' AND v_internal_fiat)
    )
  );

  RETURN v_order_id;
END;
$$;


--
-- TOC entry 1035 (class 1255 OID 21219)
-- Name: p2p_admin_list_disputes(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p2p_admin_list_disputes(p_status text DEFAULT 'open'::text) RETURNS TABLE(dispute_id uuid, order_id uuid, offer_id uuid, dispute_status text, reason text, admin_notes text, opened_by uuid, opened_at timestamp with time zone, resolved_at timestamp with time zone, asset text, asset_amount numeric, fiat_currency text, fiat_amount numeric, seller_id uuid, seller_name text, buyer_id uuid, buyer_name text, order_status text, order_created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_is_admin boolean;
BEGIN
  IF v_caller_id IS NULL THEN RAISE EXCEPTION 'No autenticado'; END IF;
  SELECT COALESCE(is_admin, false) INTO v_is_admin FROM profiles WHERE id = v_caller_id;
  IF NOT v_is_admin THEN RAISE EXCEPTION 'Solo admin'; END IF;

  RETURN QUERY
  SELECT
    d.id,
    o.id,
    o.offer_id,
    d.status::text,
    d.reason,
    d.admin_notes,
    d.opened_by,
    d.opened_at,
    d.resolved_at,
    o.asset::text,
    o.asset_amount,
    o.fiat_currency,
    o.fiat_amount,
    o.seller_id,
    ps.username,
    o.buyer_id,
    pb.username,
    o.status::text,
    o.created_at
  FROM p2p_disputes d
  JOIN p2p_orders o ON o.id = d.order_id
  LEFT JOIN profiles ps ON ps.id = o.seller_id
  LEFT JOIN profiles pb ON pb.id = o.buyer_id
  WHERE (p_status IS NULL OR p_status = 'all' OR d.status = p_status)
  ORDER BY d.opened_at DESC
  LIMIT 200;
END;
$$;


--
-- TOC entry 1033 (class 1255 OID 21210)
-- Name: p2p_admin_resolve_dispute(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p2p_admin_resolve_dispute(p_order_id uuid, p_release_to_buyer boolean, p_admin_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order p2p_orders%ROWTYPE;
  v_offer p2p_offers%ROWTYPE;
  v_dispute p2p_disputes%ROWTYPE;
  v_transfer_asset numeric;
  v_fee_asset numeric;

  v_caller_id uuid := auth.uid();
  v_caller_is_admin boolean := false;

  v_admin_id uuid;
  v_referrer_id uuid;

  v_admin_share numeric;
  v_ref_share numeric;
  v_pool_share numeric;

  v_admin_fee numeric;
  v_ref_fee numeric;
  v_pool_fee numeric;

  v_internal_fiat boolean;

  v_fxu_usd_rate numeric;
  v_fee_distrib_currency text;
  v_fee_distrib_amount numeric;
BEGIN
  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);

  IF coalesce(auth.role(),'') <> 'service_role' THEN
    IF v_caller_id IS NULL THEN RAISE EXCEPTION 'No autenticado'; END IF;
    SELECT COALESCE(is_admin, false) INTO v_caller_is_admin FROM profiles WHERE id = v_caller_id;
    IF NOT v_caller_is_admin THEN RAISE EXCEPTION 'Solo admin o service_role puede resolver disputas'; END IF;
  END IF;

  SELECT * INTO v_order FROM p2p_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Orden no existe'; END IF;
  IF v_order.status <> 'disputed' THEN RAISE EXCEPTION 'La orden no esta en disputa'; END IF;

  SELECT * INTO v_offer FROM p2p_offers WHERE id = v_order.offer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Oferta no existe'; END IF;

  SELECT * INTO v_dispute FROM p2p_disputes WHERE order_id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Disputa no existe'; END IF;

  v_internal_fiat := upper(v_order.fiat_currency) IN ('FXU','USDT');

  IF p_release_to_buyer THEN
    v_fee_asset := COALESCE(v_order.fee_asset, 0);
    v_transfer_asset := GREATEST(0, v_order.asset_amount - v_fee_asset);

    IF v_internal_fiat THEN
      IF upper(v_order.fiat_currency) = 'FXU' THEN
        UPDATE profiles SET fxu_balance = fxu_balance + v_order.fiat_amount WHERE id = v_order.seller_id;
      ELSE
        UPDATE profiles SET usdt_balance = usdt_balance + v_order.fiat_amount WHERE id = v_order.seller_id;
      END IF;
    END IF;

    IF v_order.asset = 'FXU' THEN
      UPDATE profiles SET fxu_balance = fxu_balance + v_transfer_asset WHERE id = v_order.buyer_id;
    ELSE
      UPDATE profiles SET usdt_balance = usdt_balance + v_transfer_asset WHERE id = v_order.buyer_id;
    END IF;

    SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
    SELECT referred_by INTO v_referrer_id FROM profiles WHERE id = v_order.seller_id;

    SELECT COALESCE(value::numeric,50) INTO v_admin_share FROM game_settings WHERE key='p2p_fee_admin_share';
    SELECT COALESCE(value::numeric,5)  INTO v_ref_share   FROM game_settings WHERE key='p2p_fee_referrer_share';
    SELECT COALESCE(value::numeric,45) INTO v_pool_share  FROM game_settings WHERE key='p2p_fee_pool_share';

    IF v_referrer_id IS NULL THEN
      v_pool_share := v_pool_share + v_ref_share;
      v_ref_share := 0;
    END IF;

    IF v_order.asset = 'USDT' AND v_fee_asset > 0 THEN
      SELECT COALESCE(value::numeric, 0.0001) INTO v_fxu_usd_rate FROM game_settings WHERE key = 'fxu_usd_rate';
      IF v_fxu_usd_rate IS NULL OR v_fxu_usd_rate <= 0 THEN v_fxu_usd_rate := 0.0001; END IF;
      v_fee_distrib_currency := 'FXU';
      v_fee_distrib_amount := v_fee_asset / v_fxu_usd_rate;
    ELSE
      v_fee_distrib_currency := v_order.asset::text;
      v_fee_distrib_amount := v_fee_asset;
    END IF;

    v_admin_fee := round((v_fee_distrib_amount * v_admin_share / 100.0)::numeric, 8);
    v_ref_fee   := round((v_fee_distrib_amount * v_ref_share   / 100.0)::numeric, 8);
    v_pool_fee  := GREATEST(0, v_fee_distrib_amount - v_admin_fee - v_ref_fee);

    IF v_admin_id IS NOT NULL AND v_admin_fee > 0 THEN
      IF v_fee_distrib_currency = 'FXU' THEN
        UPDATE profiles SET fxu_balance = fxu_balance + v_admin_fee WHERE id = v_admin_id;
      ELSE
        UPDATE profiles SET usdt_balance = usdt_balance + v_admin_fee WHERE id = v_admin_id;
      END IF;

      -- [NUEVO] Registrar en admin_revenue
      PERFORM record_admin_revenue(
        'p2p_fee',
        v_admin_fee,
        'P2P dispute resolved (order ' || substr(p_order_id::text, 1, 8) || ')',
        v_order.seller_id,
        NULL,
        v_fee_distrib_currency
      );
    END IF;

    IF v_referrer_id IS NOT NULL AND v_ref_fee > 0 THEN
      IF v_fee_distrib_currency = 'FXU' THEN
        UPDATE profiles SET fxu_balance = fxu_balance + v_ref_fee WHERE id = v_referrer_id;
      ELSE
        UPDATE profiles SET usdt_balance = usdt_balance + v_ref_fee WHERE id = v_referrer_id;
      END IF;

      INSERT INTO referral_commissions (
        referrer_id, seller_id, transaction_id,
        commission_type, resource_type, amount, fxu_amount, created_at
      ) VALUES (
        v_referrer_id, v_order.seller_id, NULL,
        'market_referral', lower(v_fee_distrib_currency), CEIL(v_ref_fee)::bigint, v_ref_fee, now()
      );
    END IF;

    IF v_pool_fee > 0 THEN
      IF v_fee_distrib_currency = 'FXU' THEN
        PERFORM contribute_to_jackpot(v_pool_fee, 'p2p_fee', v_order.seller_id);
      ELSIF v_admin_id IS NOT NULL THEN
        UPDATE profiles SET usdt_balance = usdt_balance + v_pool_fee WHERE id = v_admin_id;
      END IF;
    END IF;

    UPDATE p2p_offers
    SET locked_amount = GREATEST(0, locked_amount - v_order.asset_amount),
        status = CASE WHEN (available_amount <= 0 AND (locked_amount - v_order.asset_amount) <= 0) THEN 'completed' ELSE status END,
        updated_at = now()
    WHERE id = v_order.offer_id;

    UPDATE p2p_orders SET status = 'resolved', released_at = now(), updated_at = now() WHERE id = p_order_id;

    UPDATE p2p_disputes
    SET status = 'resolved_buyer', admin_id = v_caller_id, admin_notes = p_admin_notes, resolved_at = now()
    WHERE id = v_dispute.id;

    INSERT INTO p2p_reputation(user_id) VALUES (v_order.seller_id) ON CONFLICT (user_id) DO NOTHING;
    UPDATE p2p_reputation SET lost_disputes = lost_disputes + 1, updated_at = now() WHERE user_id = v_order.seller_id;
  ELSE
    UPDATE p2p_offers
    SET available_amount = available_amount + v_order.asset_amount, updated_at = now()
    WHERE id = v_order.offer_id;

    IF v_offer.side = 'sell' THEN
      IF v_internal_fiat THEN
        IF upper(v_order.fiat_currency) = 'FXU' THEN
          UPDATE profiles SET fxu_balance = fxu_balance + v_order.fiat_amount WHERE id = v_order.buyer_id;
        ELSE
          UPDATE profiles SET usdt_balance = usdt_balance + v_order.fiat_amount WHERE id = v_order.buyer_id;
        END IF;
      END IF;
    ELSE
      IF v_order.asset = 'FXU' THEN
        UPDATE profiles SET fxu_balance = fxu_balance + v_order.asset_amount WHERE id = v_order.seller_id;
      ELSE
        UPDATE profiles SET usdt_balance = usdt_balance + v_order.asset_amount WHERE id = v_order.seller_id;
      END IF;
    END IF;

    UPDATE p2p_orders
    SET status = 'resolved', cancelled_at = now(), cancellation_reason = 'admin_resolved_seller', updated_at = now()
    WHERE id = p_order_id;

    UPDATE p2p_disputes
    SET status = 'resolved_seller', admin_id = v_caller_id, admin_notes = p_admin_notes, resolved_at = now()
    WHERE id = v_dispute.id;

    INSERT INTO p2p_reputation(user_id) VALUES (v_order.buyer_id) ON CONFLICT (user_id) DO NOTHING;
    UPDATE p2p_reputation SET lost_disputes = lost_disputes + 1, updated_at = now() WHERE user_id = v_order.buyer_id;
  END IF;

  INSERT INTO p2p_audit_log(order_id, offer_id, action, meta)
  VALUES (
    p_order_id,
    v_order.offer_id,
    'dispute_resolved',
    jsonb_build_object(
      'release_to_buyer', p_release_to_buyer,
      'offer_side', v_offer.side,
      'internal_fiat', v_internal_fiat,
      'resolved_by', v_caller_id,
      'fee_asset', v_fee_asset,
      'admin_fee', v_admin_fee,
      'fee_distrib_currency', v_fee_distrib_currency,
      'fee_distrib_amount', v_fee_distrib_amount,
      'fxu_usd_rate', v_fxu_usd_rate
    )
  );

  RETURN true;
END;
$$;


--
-- TOC entry 1040 (class 1255 OID 21241)
-- Name: p2p_autoban_on_dispute(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p2p_autoban_on_dispute() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_loser uuid;
  v_threshold int;
  v_count int;
  v_order p2p_orders%ROWTYPE;
BEGIN
  -- Solo actuar cuando la disputa pasa a resuelta
  IF NEW.status NOT IN ('resolved_buyer','resolved_seller') THEN
    RETURN NEW;
  END IF;
  IF OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_order FROM p2p_orders WHERE id = NEW.order_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- resolved_buyer => seller pierde; resolved_seller => buyer pierde
  IF NEW.status = 'resolved_buyer' THEN
    v_loser := v_order.seller_id;
  ELSE
    v_loser := v_order.buyer_id;
  END IF;

  SELECT COALESCE(value::int, 3) INTO v_threshold
    FROM game_settings WHERE key = 'p2p_autoban_lost_disputes_7d';

  -- Contar disputas perdidas del v_loser en 7d
  SELECT count(*) INTO v_count
    FROM p2p_disputes d
    JOIN p2p_orders   o ON o.id = d.order_id
   WHERE d.resolved_at >= now() - interval '7 days'
     AND (
           (d.status = 'resolved_buyer'  AND o.seller_id = v_loser) OR
           (d.status = 'resolved_seller' AND o.buyer_id  = v_loser)
         );

  IF v_count >= v_threshold THEN
    INSERT INTO p2p_reputation(user_id, is_banned, updated_at)
    VALUES (v_loser, true, now())
    ON CONFLICT (user_id) DO UPDATE SET is_banned = true, updated_at = now();

    INSERT INTO p2p_audit_log(order_id, action, actor_id, meta)
    VALUES (
      NEW.order_id,
      'user_autobanned',
      v_loser,
      jsonb_build_object('lost_disputes_7d', v_count, 'threshold', v_threshold)
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 7781 (class 0 OID 0)
-- Dependencies: 1040
-- Name: FUNCTION p2p_autoban_on_dispute(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.p2p_autoban_on_dispute() IS 'Fase 5: auto-banea a quien pierde ≥ p2p_autoban_lost_disputes_7d disputas en 7 días.';


--
-- TOC entry 1028 (class 1255 OID 21193)
-- Name: p2p_cancel_offer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p2p_cancel_offer(p_offer_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_offer p2p_offers%ROWTYPE;
  v_return_amount numeric := 0;
  v_open_orders int := 0;
  v_internal_fiat boolean;
BEGIN
  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'No autenticado'; END IF;

  SELECT * INTO v_offer
  FROM p2p_offers
  WHERE id = p_offer_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Oferta no existe'; END IF;
  IF v_offer.user_id <> v_user_id THEN RAISE EXCEPTION 'No autorizado'; END IF;

  IF v_offer.status IN ('cancelled','completed') THEN
    RETURN true;
  END IF;

  SELECT count(*) INTO v_open_orders
  FROM p2p_orders
  WHERE offer_id = p_offer_id
    AND status IN ('pending_payment','paid','disputed');

  IF v_open_orders > 0 THEN
    RAISE EXCEPTION 'No puedes cancelar: hay ordenes activas en la oferta';
  END IF;

  v_internal_fiat := upper(coalesce(v_offer.fiat_currency, '')) IN ('FXU', 'USDT');

  IF v_offer.side = 'sell' THEN
    v_return_amount := COALESCE(v_offer.available_amount, 0);
    IF v_return_amount > 0 THEN
      IF v_offer.asset = 'FXU' THEN
        UPDATE profiles SET fxu_balance = fxu_balance + v_return_amount WHERE id = v_user_id;
      ELSE
        UPDATE profiles SET usdt_balance = usdt_balance + v_return_amount WHERE id = v_user_id;
      END IF;
    END IF;
  ELSE
    -- BUY: solo devolver fiat si fue interno
    IF v_internal_fiat THEN
      v_return_amount := round((COALESCE(v_offer.available_amount, 0) * COALESCE(v_offer.price_per_unit, 0))::numeric, 8);
      IF v_return_amount > 0 THEN
        IF upper(v_offer.fiat_currency) = 'FXU' THEN
          UPDATE profiles SET fxu_balance = fxu_balance + v_return_amount WHERE id = v_user_id;
        ELSE
          UPDATE profiles SET usdt_balance = usdt_balance + v_return_amount WHERE id = v_user_id;
        END IF;
      END IF;
    END IF;
  END IF;

  UPDATE p2p_offers
  SET status = 'cancelled',
      available_amount = 0,
      locked_amount = GREATEST(0, locked_amount - COALESCE(v_offer.available_amount, 0)),
      updated_at = now()
  WHERE id = p_offer_id;

  INSERT INTO p2p_audit_log(offer_id, actor_id, action, meta)
  VALUES (
    p_offer_id,
    v_user_id,
    'offer_cancelled',
    jsonb_build_object(
      'returned', v_return_amount,
      'side', v_offer.side,
      'internal_fiat', v_internal_fiat
    )
  );

  RETURN true;
END;
$$;


--
-- TOC entry 1063 (class 1255 OID 21342)
-- Name: p2p_cleanup_old_dispute_evidence(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p2p_cleanup_old_dispute_evidence(p_days integer DEFAULT NULL::integer) RETURNS TABLE(deleted_count integer, scanned_disputes integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_days int;
  v_deleted int := 0;
  v_scanned int := 0;
  v_dispute record;
  v_path text;
BEGIN
  IF p_days IS NULL THEN
    SELECT COALESCE(value::int, 90) INTO v_days
      FROM game_settings WHERE key = 'p2p_evidence_retention_days';
    v_days := COALESCE(v_days, 90);
  ELSE
    v_days := GREATEST(1, p_days);
  END IF;

  FOR v_dispute IN
    SELECT id, evidence
    FROM p2p_disputes
    WHERE status IN ('resolved_buyer','resolved_seller','cancelled')
      AND resolved_at IS NOT NULL
      AND resolved_at < (now() - make_interval(days => v_days))
      AND jsonb_typeof(evidence) = 'array'
      AND jsonb_array_length(evidence) > 0
  LOOP
    v_scanned := v_scanned + 1;

    -- Borrado físico de cada path en el bucket p2p-evidence
    FOR v_path IN
      SELECT DISTINCT (e->>'path')::text
      FROM jsonb_array_elements(v_dispute.evidence) AS e
      WHERE (e->>'path') IS NOT NULL
    LOOP
      DELETE FROM storage.objects
       WHERE bucket_id = 'p2p-evidence' AND name = v_path;
      IF FOUND THEN
        v_deleted := v_deleted + 1;
      END IF;
    END LOOP;

    -- Marcamos la evidencia como purgada pero conservamos la traza histórica
    UPDATE p2p_disputes
       SET evidence = jsonb_build_array(jsonb_build_object(
                        'purged', true,
                        'original_count', jsonb_array_length(v_dispute.evidence),
                        'purged_at', now()
                      ))
     WHERE id = v_dispute.id;
  END LOOP;

  RETURN QUERY SELECT v_deleted, v_scanned;
END;
$$;


--
-- TOC entry 7782 (class 0 OID 0)
-- Dependencies: 1063
-- Name: FUNCTION p2p_cleanup_old_dispute_evidence(p_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.p2p_cleanup_old_dispute_evidence(p_days integer) IS 'Fase 13: borra archivos de evidencia de disputas resueltas hace > N días (default 90). Conserva las filas con marca purged=true.';


--
-- TOC entry 1027 (class 1255 OID 21191)
-- Name: p2p_create_offer(text, text, text, numeric, numeric, numeric, numeric, integer[], text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p2p_create_offer(p_side text, p_asset text, p_fiat_currency text, p_price_per_unit numeric, p_total_amount numeric, p_min_trade_amount numeric DEFAULT 0, p_max_trade_amount numeric DEFAULT NULL::numeric, p_payment_method_ids integer[] DEFAULT '{}'::integer[], p_terms text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text, p_time_limit_minutes integer DEFAULT 1440) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_offer_id uuid;
  v_fxu numeric;
  v_usdt numeric;
  v_valid_methods int;
  v_side text := upper(coalesce(p_side,''));
  v_asset text := upper(coalesce(p_asset,''));
  v_fiat text := upper(coalesce(p_fiat_currency,''));
  v_internal_fiat boolean;
BEGIN
  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'No autenticado'; END IF;

  IF v_side NOT IN ('SELL','BUY') THEN
    RAISE EXCEPTION 'side invalido';
  END IF;

  IF v_asset NOT IN ('FXU','USDT') THEN
    RAISE EXCEPTION 'Asset invalido';
  END IF;

  IF p_price_per_unit <= 0 OR p_total_amount <= 0 THEN
    RAISE EXCEPTION 'Precio y monto deben ser > 0';
  END IF;

  IF p_min_trade_amount < 0 OR (p_max_trade_amount IS NOT NULL AND p_max_trade_amount <= 0) THEN
    RAISE EXCEPTION 'Min/Max trade invalidos';
  END IF;

  IF p_max_trade_amount IS NOT NULL AND p_max_trade_amount < p_min_trade_amount THEN
    RAISE EXCEPTION 'max_trade_amount debe ser >= min_trade_amount';
  END IF;

  IF p_time_limit_minutes < 5 OR p_time_limit_minutes > 1440 THEN
    RAISE EXCEPTION 'time_limit_minutes fuera de rango';
  END IF;

  IF array_length(p_payment_method_ids,1) IS NULL THEN
    RAISE EXCEPTION 'Debes seleccionar al menos 1 metodo de pago';
  END IF;

  SELECT count(*) INTO v_valid_methods
  FROM p2p_payment_methods
  WHERE is_enabled = true
    AND id = ANY(p_payment_method_ids)
    AND upper(currency_code) = v_fiat;

  IF v_valid_methods <> array_length(p_payment_method_ids,1) THEN
    RAISE EXCEPTION 'Hay metodos de pago invalidos/deshabilitados o no corresponden a la moneda fiat';
  END IF;

  v_internal_fiat := v_fiat IN ('FXU','USDT');

  SELECT fxu_balance, usdt_balance INTO v_fxu, v_usdt
  FROM profiles
  WHERE id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Perfil no encontrado'; END IF;

  IF v_side = 'SELL' THEN
    IF v_asset = 'FXU' THEN
      IF coalesce(v_fxu,0) < p_total_amount THEN RAISE EXCEPTION 'Saldo FXU insuficiente'; END IF;
      UPDATE profiles SET fxu_balance = fxu_balance - p_total_amount WHERE id = v_user_id;
    ELSE
      IF coalesce(v_usdt,0) < p_total_amount THEN RAISE EXCEPTION 'Saldo USDT insuficiente'; END IF;
      UPDATE profiles SET usdt_balance = usdt_balance - p_total_amount WHERE id = v_user_id;
    END IF;
  ELSE
    -- BUY: solo bloquear cuando fiat es interno
    IF v_internal_fiat THEN
      IF v_fiat = 'FXU' THEN
        IF coalesce(v_fxu,0) < (p_total_amount * p_price_per_unit) THEN
          RAISE EXCEPTION 'Saldo FXU insuficiente para BUY';
        END IF;
        UPDATE profiles SET fxu_balance = fxu_balance - (p_total_amount * p_price_per_unit) WHERE id = v_user_id;
      ELSE
        IF coalesce(v_usdt,0) < (p_total_amount * p_price_per_unit) THEN
          RAISE EXCEPTION 'Saldo USDT insuficiente para BUY';
        END IF;
        UPDATE profiles SET usdt_balance = usdt_balance - (p_total_amount * p_price_per_unit) WHERE id = v_user_id;
      END IF;
    END IF;
  END IF;

  INSERT INTO p2p_offers (
    user_id, side, asset, fiat_currency,
    price_per_unit, total_amount, available_amount, locked_amount,
    min_trade_amount, max_trade_amount, payment_method_ids,
    terms, country_code, time_limit_minutes, status
  ) VALUES (
    v_user_id, lower(v_side), v_asset, v_fiat,
    p_price_per_unit, p_total_amount, p_total_amount, p_total_amount,
    coalesce(p_min_trade_amount,0), p_max_trade_amount, p_payment_method_ids,
    p_terms, p_country_code, p_time_limit_minutes, 'active'
  ) RETURNING id INTO v_offer_id;

  INSERT INTO p2p_audit_log(offer_id, actor_id, action, meta)
  VALUES (
    v_offer_id,
    v_user_id,
    'offer_created',
    jsonb_build_object(
      'side', lower(v_side),
      'asset', v_asset,
      'fiat_currency', v_fiat,
      'internal_fiat', v_internal_fiat,
      'amount', p_total_amount
    )
  );

  RETURN v_offer_id;
END;
$$;


