-- TOC entry 7786 (class 0 OID 0)
-- Dependencies: 1062
-- Name: FUNCTION p2p_expire_stale_offers(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.p2p_expire_stale_offers() IS 'Fase 12: expira ofertas activas vencidas, las saca del libro y devuelve el saldo disponible no tomado.';


--
-- TOC entry 1034 (class 1255 OID 21216)
-- Name: p2p_mark_paid(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p2p_mark_paid(p_order_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_order p2p_orders%ROWTYPE;
  v_offer p2p_offers%ROWTYPE;
  v_msg text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  SELECT * INTO v_order FROM p2p_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Orden no existe'; END IF;

  IF v_order.buyer_id <> v_user_id THEN
    RAISE EXCEPTION 'Solo el comprador puede marcar como pagado';
  END IF;

  IF v_order.status <> 'pending_payment' THEN
    RAISE EXCEPTION 'Estado invalido para marcar pagado';
  END IF;

  IF now() > v_order.payment_deadline THEN
    RAISE EXCEPTION 'Orden vencida';
  END IF;

  SELECT * INTO v_offer FROM p2p_offers WHERE id = v_order.offer_id;

  UPDATE p2p_orders
  SET status = 'paid', paid_at = now(), updated_at = now()
  WHERE id = p_order_id;

  IF v_offer.side = 'sell' THEN
    v_msg := 'El comprador confirmo el envio del pago. Esperando liberacion del vendedor.';
  ELSE
    v_msg := 'El comprador confirmo la recepcion del pago. Puede liberar el escrow.';
  END IF;

  INSERT INTO p2p_messages(order_id, sender_id, body, is_system)
  VALUES (p_order_id, v_user_id, v_msg, true);

  INSERT INTO p2p_audit_log(order_id, offer_id, actor_id, action, meta)
  VALUES (
    p_order_id,
    v_order.offer_id,
    v_user_id,
    'order_marked_paid',
    jsonb_build_object('offer_side', v_offer.side)
  );

  RETURN true;
END;
$$;


--
-- TOC entry 1061 (class 1255 OID 21334)
-- Name: p2p_message_notify_telegram(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p2p_message_notify_telegram() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order        p2p_orders%ROWTYPE;
  v_recipient    uuid;
  v_sender_name  text;
  v_cfg_url      text;
  v_cfg_key      text;
  v_enabled      boolean;
  v_has_link     boolean;
  v_subject      text;
  v_body         text;
  v_req_id       bigint;
BEGIN
  -- Solo mensajes reales, no los de sistema
  IF NEW.is_system THEN RETURN NEW; END IF;

  SELECT edge_function_url, anon_key, is_enabled
    INTO v_cfg_url, v_cfg_key, v_enabled
    FROM telegram_dm_config
   WHERE id = 1;

  IF NOT COALESCE(v_enabled, false) OR COALESCE(v_cfg_url,'') = '' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_order FROM p2p_orders WHERE id = NEW.order_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- Destinatario = la contraparte del sender en la orden
  IF NEW.sender_id = v_order.seller_id THEN
    v_recipient := v_order.buyer_id;
  ELSIF NEW.sender_id = v_order.buyer_id THEN
    v_recipient := v_order.seller_id;
  ELSE
    RETURN NEW;  -- mensaje enviado por terceros (admin?), no notificamos
  END IF;

  -- Verificar que el receptor tenga cuenta de Telegram vinculada
  SELECT EXISTS (SELECT 1 FROM telegram_links WHERE user_id = v_recipient)
    INTO v_has_link;
  IF NOT v_has_link THEN RETURN NEW; END IF;

  SELECT username INTO v_sender_name FROM profiles WHERE id = NEW.sender_id;

  v_subject := '💬 Nuevo mensaje P2P de ' || COALESCE(v_sender_name, 'contraparte');
  v_body := LEFT(COALESCE(NEW.body, ''), 500);
  IF COALESCE(NEW.attachment_url,'') <> '' THEN
    v_body := v_body || E'\n\n📎 (incluye adjunto)';
  END IF;
  v_body := v_body || E'\n\n🎮 Abre la orden en el Mercado P2P para responder.';

  BEGIN
    SELECT net.http_post(
      url := v_cfg_url,
      body := jsonb_build_object(
        'recipient_id', v_recipient,
        'subject',      v_subject,
        'body',         v_body,
        'message_type', 'player'
      ),
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'apikey',       v_cfg_key,
        'Authorization','Bearer ' || v_cfg_key
      )
    ) INTO v_req_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'p2p_message_notify_telegram: %', SQLERRM;
  END;

  RETURN NEW;
END;
$$;


