--
-- TOC entry 741 (class 1255 OID 19064)
-- Name: perform_acs_combat(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.perform_acs_combat(p_acs_id uuid, p_target_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_attacker_units jsonb := '[]'::jsonb;
  v_defender_units jsonb := '[]'::jsonb;
  v_combat_result jsonb;
  v_fleet_record RECORD;
  v_ship_record RECORD;
  v_defense_record RECORD;
  v_defender_id uuid;
  v_weapon_bonus numeric;
  v_shield_bonus numeric;
  v_hull_bonus numeric;
  v_weapon numeric;
  v_shield numeric;
  v_hull numeric;
  v_fleet_contributions jsonb := '[]'::jsonb;
  v_fleet_power numeric;
  v_total_fleet_power numeric := 0;
  v_unit jsonb;
  v_i integer;
BEGIN
  SELECT user_id INTO v_defender_id FROM planets WHERE id = p_target_planet_id;

  FOR v_fleet_record IN
    SELECT ap.fleet_id, ap.user_id
    FROM acs_participants ap
    WHERE ap.acs_id = p_acs_id
  LOOP
    SELECT
      COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_fleet_record.user_id AND tt.code = 'weapons_tech'), 0),
      COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_fleet_record.user_id AND tt.code = 'shielding_tech'), 0),
      COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_fleet_record.user_id AND tt.code = 'armour_tech'), 0)
    INTO v_weapon_bonus, v_shield_bonus, v_hull_bonus;

    v_fleet_power := 0;

    FOR v_ship_record IN
      SELECT fs.ship_type_id, fs.quantity, st.code, st.name, st.weapon_power, st.shield_power,
             st.structural_integrity, st.metal_cost, st.crystal_cost, st.rapid_fire, st.cargo_capacity
      FROM fleet_ships fs
      JOIN ship_types st ON fs.ship_type_id = st.id
      WHERE fs.fleet_id = v_fleet_record.fleet_id AND fs.quantity > 0
    LOOP
      v_weapon := FLOOR(v_ship_record.weapon_power * (1 + v_weapon_bonus * 0.10));
      v_shield := FLOOR(v_ship_record.shield_power * (1 + v_shield_bonus * 0.10));
      v_hull := FLOOR(v_ship_record.structural_integrity * (1 + v_hull_bonus * 0.10));

      v_fleet_power := v_fleet_power + (v_weapon * v_ship_record.quantity);

      v_attacker_units := v_attacker_units || jsonb_build_object(
        'type_id', v_ship_record.ship_type_id,
        'code', v_ship_record.code,
        'name', v_ship_record.name,
        'quantity', v_ship_record.quantity,
        'initial_quantity', v_ship_record.quantity,
        'weapon', v_weapon,
        'shield', v_shield,
        'hull', v_hull,
        'current_hull', v_hull * v_ship_record.quantity,
        'current_shield', v_shield * v_ship_record.quantity,
        'metal_cost', v_ship_record.metal_cost,
        'crystal_cost', v_ship_record.crystal_cost,
        'cargo_capacity', COALESCE(v_ship_record.cargo_capacity, 0),
        'rapid_fire', COALESCE(v_ship_record.rapid_fire, '{}'::jsonb),
        'is_defense', false,
        'fleet_id', v_fleet_record.fleet_id::text
      );
    END LOOP;

    v_total_fleet_power := v_total_fleet_power + v_fleet_power;

    v_fleet_contributions := v_fleet_contributions || jsonb_build_object(
      'fleet_id', v_fleet_record.fleet_id::text,
      'user_id', v_fleet_record.user_id::text,
      'power', v_fleet_power
    );
  END LOOP;

  SELECT
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_defender_id AND tt.code = 'weapons_tech'), 0),
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_defender_id AND tt.code = 'shielding_tech'), 0),
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_defender_id AND tt.code = 'armour_tech'), 0)
  INTO v_weapon_bonus, v_shield_bonus, v_hull_bonus;

  FOR v_ship_record IN
    SELECT ps.ship_type_id, ps.quantity, st.code, st.name, st.weapon_power, st.shield_power,
           st.structural_integrity, st.metal_cost, st.crystal_cost, st.rapid_fire
    FROM planet_ships ps
    JOIN ship_types st ON ps.ship_type_id = st.id
    WHERE ps.planet_id = p_target_planet_id AND ps.quantity > 0
  LOOP
    v_weapon := FLOOR(v_ship_record.weapon_power * (1 + v_weapon_bonus * 0.10));
    v_shield := FLOOR(v_ship_record.shield_power * (1 + v_shield_bonus * 0.10));
    v_hull := FLOOR(v_ship_record.structural_integrity * (1 + v_hull_bonus * 0.10));

    v_defender_units := v_defender_units || jsonb_build_object(
      'type_id', v_ship_record.ship_type_id,
      'code', v_ship_record.code,
      'name', v_ship_record.name,
      'quantity', v_ship_record.quantity,
      'initial_quantity', v_ship_record.quantity,
      'weapon', v_weapon,
      'shield', v_shield,
      'hull', v_hull,
      'current_hull', v_hull * v_ship_record.quantity,
      'current_shield', v_shield * v_ship_record.quantity,
      'metal_cost', v_ship_record.metal_cost,
      'crystal_cost', v_ship_record.crystal_cost,
      'rapid_fire', COALESCE(v_ship_record.rapid_fire, '{}'::jsonb),
      'is_defense', false
    );
  END LOOP;

  FOR v_defense_record IN
    SELECT pd.defense_type_id, pd.quantity, dt.code, dt.name, dt.weapon_power, dt.shield_power,
           dt.structural_integrity, dt.metal_cost, dt.crystal_cost
    FROM planet_defenses pd
    JOIN defense_types dt ON pd.defense_type_id = dt.id
    WHERE pd.planet_id = p_target_planet_id AND pd.quantity > 0
    AND dt.code NOT IN ('interplanetary_missile', 'anti_ballistic_missile')
  LOOP
    v_weapon := FLOOR(v_defense_record.weapon_power * (1 + v_weapon_bonus * 0.10));
    v_shield := FLOOR(v_defense_record.shield_power * (1 + v_shield_bonus * 0.10));
    v_hull := FLOOR(v_defense_record.structural_integrity * (1 + v_hull_bonus * 0.10));

    v_defender_units := v_defender_units || jsonb_build_object(
      'type_id', v_defense_record.defense_type_id,
      'code', v_defense_record.code,
      'name', v_defense_record.name,
      'quantity', v_defense_record.quantity,
      'initial_quantity', v_defense_record.quantity,
      'weapon', v_weapon,
      'shield', v_shield,
      'hull', v_hull,
      'current_hull', v_hull * v_defense_record.quantity,
      'current_shield', v_shield * v_defense_record.quantity,
      'metal_cost', v_defense_record.metal_cost,
      'crystal_cost', v_defense_record.crystal_cost,
      'rapid_fire', '{}'::jsonb,
      'is_defense', true
    );
  END LOOP;

  v_combat_result := simulate_xnova_combat(v_attacker_units, v_defender_units);

  RETURN jsonb_build_object(
    'result', v_combat_result->>'result',
    'rounds', v_combat_result->>'rounds',
    'rounds_data', v_combat_result->'rounds_data',
    'attacker_remaining', v_combat_result->'attacker_remaining',
    'defender_remaining', v_combat_result->'defender_remaining',
    'debris_metal', v_combat_result->'debris_metal',
    'debris_crystal', v_combat_result->'debris_crystal',
    'attacker_losses_metal', v_combat_result->'attacker_losses_metal',
    'attacker_losses_crystal', v_combat_result->'attacker_losses_crystal',
    'defender_losses_metal', v_combat_result->'defender_losses_metal',
    'defender_losses_crystal', v_combat_result->'defender_losses_crystal',
    'destroyed_defenses', v_combat_result->'destroyed_defenses',
    'initial_attacker', v_combat_result->'initial_attacker',
    'initial_defender', v_combat_result->'initial_defender',
    'fleet_contributions', v_fleet_contributions,
    'total_fleet_power', v_total_fleet_power
  );
END;
$$;


--
-- TOC entry 622 (class 1255 OID 18556)
-- Name: perform_combat(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.perform_combat(p_attacker_fleet_id uuid, p_target_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_attacker_units jsonb := '[]'::jsonb;
  v_defender_units jsonb := '[]'::jsonb;
  v_combat_result jsonb;
  v_ship_record record;
  v_defense_record record;
  v_allied_fleet record;
  v_attacker_id uuid;
  v_defender_id uuid;
  v_weapon_bonus numeric;
  v_shield_bonus numeric;
  v_hull_bonus numeric;
  v_weapon numeric;
  v_shield numeric;
  v_hull numeric;
BEGIN
  SELECT user_id INTO v_attacker_id FROM fleets WHERE id = p_attacker_fleet_id;
  SELECT user_id INTO v_defender_id FROM planets WHERE id = p_target_planet_id;

  -- === ATTACKER UNITS ===
  SELECT 
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_attacker_id AND tt.code = 'weapons_tech'), 0),
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_attacker_id AND tt.code = 'shielding_tech'), 0),
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_attacker_id AND tt.code = 'armour_tech'), 0)
  INTO v_weapon_bonus, v_shield_bonus, v_hull_bonus;

  FOR v_ship_record IN
    SELECT fs.ship_type_id, fs.quantity, st.code, st.name, st.weapon_power, st.shield_power,
           st.structural_integrity, st.metal_cost, st.crystal_cost, st.rapid_fire
    FROM fleet_ships fs
    JOIN ship_types st ON fs.ship_type_id = st.id
    WHERE fs.fleet_id = p_attacker_fleet_id AND fs.quantity > 0
  LOOP
    v_weapon := FLOOR(v_ship_record.weapon_power * (1 + v_weapon_bonus * 0.10));
    v_shield := FLOOR(v_ship_record.shield_power * (1 + v_shield_bonus * 0.10));
    v_hull := FLOOR(v_ship_record.structural_integrity * (1 + v_hull_bonus * 0.10));
    
    v_attacker_units := v_attacker_units || jsonb_build_object(
      'type_id', v_ship_record.ship_type_id,
      'code', v_ship_record.code,
      'name', v_ship_record.name,
      'quantity', v_ship_record.quantity,
      'initial_quantity', v_ship_record.quantity,
      'weapon', v_weapon,
      'shield', v_shield,
      'hull', v_hull,
      'current_hull', v_hull * v_ship_record.quantity,
      'current_shield', v_shield * v_ship_record.quantity,
      'metal_cost', v_ship_record.metal_cost,
      'crystal_cost', v_ship_record.crystal_cost,
      'rapid_fire', COALESCE(v_ship_record.rapid_fire, '{}'::jsonb),
      'is_defense', false,
      'source', 'planet'
    );
  END LOOP;

  -- === DEFENDER UNITS (planet owner ships) ===
  SELECT 
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_defender_id AND tt.code = 'weapons_tech'), 0),
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_defender_id AND tt.code = 'shielding_tech'), 0),
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_defender_id AND tt.code = 'armour_tech'), 0)
  INTO v_weapon_bonus, v_shield_bonus, v_hull_bonus;

  FOR v_ship_record IN
    SELECT ps.ship_type_id, ps.quantity, st.code, st.name, st.weapon_power, st.shield_power,
           st.structural_integrity, st.metal_cost, st.crystal_cost, st.rapid_fire
    FROM planet_ships ps
    JOIN ship_types st ON ps.ship_type_id = st.id
    WHERE ps.planet_id = p_target_planet_id AND ps.quantity > 0
  LOOP
    v_weapon := FLOOR(v_ship_record.weapon_power * (1 + v_weapon_bonus * 0.10));
    v_shield := FLOOR(v_ship_record.shield_power * (1 + v_shield_bonus * 0.10));
    v_hull := FLOOR(v_ship_record.structural_integrity * (1 + v_hull_bonus * 0.10));
    
    v_defender_units := v_defender_units || jsonb_build_object(
      'type_id', v_ship_record.ship_type_id,
      'code', v_ship_record.code,
      'name', v_ship_record.name,
      'quantity', v_ship_record.quantity,
      'initial_quantity', v_ship_record.quantity,
      'weapon', v_weapon,
      'shield', v_shield,
      'hull', v_hull,
      'current_hull', v_hull * v_ship_record.quantity,
      'current_shield', v_shield * v_ship_record.quantity,
      'metal_cost', v_ship_record.metal_cost,
      'crystal_cost', v_ship_record.crystal_cost,
      'rapid_fire', COALESCE(v_ship_record.rapid_fire, '{}'::jsonb),
      'is_defense', false,
      'source', 'planet'
    );
  END LOOP;

  -- === DEFENDER DEFENSES ===
  FOR v_defense_record IN
    SELECT pd.defense_type_id, pd.quantity, dt.code, dt.name, dt.weapon_power, dt.shield_power,
           dt.structural_integrity, dt.metal_cost, dt.crystal_cost
    FROM planet_defenses pd
    JOIN defense_types dt ON pd.defense_type_id = dt.id
    WHERE pd.planet_id = p_target_planet_id AND pd.quantity > 0
    AND dt.code NOT IN ('interplanetary_missile', 'anti_ballistic_missile')
  LOOP
    v_weapon := FLOOR(v_defense_record.weapon_power * (1 + v_weapon_bonus * 0.10));
    v_shield := FLOOR(v_defense_record.shield_power * (1 + v_shield_bonus * 0.10));
    v_hull := FLOOR(v_defense_record.structural_integrity * (1 + v_hull_bonus * 0.10));
    
    v_defender_units := v_defender_units || jsonb_build_object(
      'type_id', v_defense_record.defense_type_id,
      'code', v_defense_record.code,
      'name', v_defense_record.name,
      'quantity', v_defense_record.quantity,
      'initial_quantity', v_defense_record.quantity,
      'weapon', v_weapon,
      'shield', v_shield,
      'hull', v_hull,
      'current_hull', v_hull * v_defense_record.quantity,
      'current_shield', v_shield * v_defense_record.quantity,
      'metal_cost', v_defense_record.metal_cost,
      'crystal_cost', v_defense_record.crystal_cost,
      'rapid_fire', '{}'::jsonb,
      'is_defense', true,
      'source', 'defense'
    );
  END LOOP;

  -- === ALLIED STATIONED FLEETS (deployed on this planet via Alliance Depot) ===
  -- FIX: Was 'hold', must be 'deploy' (that's how fleets are stored)
  FOR v_allied_fleet IN
    SELECT f.id as fleet_id, f.user_id as ally_user_id
    FROM fleets f
    WHERE f.target_galaxy = (SELECT galaxy FROM planets WHERE id = p_target_planet_id)
      AND f.target_system = (SELECT solar_system FROM planets WHERE id = p_target_planet_id)
      AND f.target_position = (SELECT position FROM planets WHERE id = p_target_planet_id)
      AND f.mission_type = 'deploy'
      AND f.is_completed = false
      AND f.is_returning = false
      AND f.user_id != v_defender_id
      AND f.user_id != v_attacker_id
      AND f.arrival_time <= now()
  LOOP
    -- Get this ally's tech bonuses
    SELECT 
      COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_allied_fleet.ally_user_id AND tt.code = 'weapons_tech'), 0),
      COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_allied_fleet.ally_user_id AND tt.code = 'shielding_tech'), 0),
      COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_allied_fleet.ally_user_id AND tt.code = 'armour_tech'), 0)
    INTO v_weapon_bonus, v_shield_bonus, v_hull_bonus;

    -- Add this ally's ships as defender units, tagged with fleet_id as source
    FOR v_ship_record IN
      SELECT fs.ship_type_id, fs.quantity, st.code, st.name, st.weapon_power, st.shield_power,
             st.structural_integrity, st.metal_cost, st.crystal_cost, st.rapid_fire
      FROM fleet_ships fs
      JOIN ship_types st ON fs.ship_type_id = st.id
      WHERE fs.fleet_id = v_allied_fleet.fleet_id AND fs.quantity > 0
    LOOP
      v_weapon := FLOOR(v_ship_record.weapon_power * (1 + v_weapon_bonus * 0.10));
      v_shield := FLOOR(v_ship_record.shield_power * (1 + v_shield_bonus * 0.10));
      v_hull := FLOOR(v_ship_record.structural_integrity * (1 + v_hull_bonus * 0.10));
      
      v_defender_units := v_defender_units || jsonb_build_object(
        'type_id', v_ship_record.ship_type_id,
        'code', v_ship_record.code,
        'name', v_ship_record.name,
        'quantity', v_ship_record.quantity,
        'initial_quantity', v_ship_record.quantity,
        'weapon', v_weapon,
        'shield', v_shield,
        'hull', v_hull,
        'current_hull', v_hull * v_ship_record.quantity,
        'current_shield', v_shield * v_ship_record.quantity,
        'metal_cost', v_ship_record.metal_cost,
        'crystal_cost', v_ship_record.crystal_cost,
        'rapid_fire', COALESCE(v_ship_record.rapid_fire, '{}'::jsonb),
        'is_defense', false,
        'source', v_allied_fleet.fleet_id::text
      );
    END LOOP;
  END LOOP;

  -- Run the combat simulation
  v_combat_result := simulate_xnova_combat(v_attacker_units, v_defender_units);

  RETURN v_combat_result;
END;
$$;


--
-- TOC entry 712 (class 1255 OID 18941)
-- Name: perform_combat_acs(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.perform_combat_acs(p_acs_id uuid, p_target_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_attacker_units jsonb := '[]'::jsonb;
  v_defender_units jsonb := '[]'::jsonb;
  v_combat_result jsonb;
  v_fleet_record record;
  v_ship_record record;
  v_defense_record record;
  v_defender_id uuid;
  v_weapon_bonus numeric;
  v_shield_bonus numeric;
  v_hull_bonus numeric;
  v_weapon numeric;
  v_shield numeric;
  v_hull numeric;
  v_total_cargo bigint := 0;
  v_fleet_distributions jsonb := '[]'::jsonb;
  v_fleet_cargo bigint;
BEGIN
  SELECT user_id INTO v_defender_id FROM planets WHERE id = p_target_planet_id;

  FOR v_fleet_record IN
    SELECT f.id as fleet_id, f.user_id
    FROM fleets f
    JOIN acs_participants ap ON ap.fleet_id = f.id
    WHERE ap.acs_id = p_acs_id 
    AND f.is_completed = false 
    AND f.is_returning = false
  LOOP
    SELECT 
      COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_fleet_record.user_id AND tt.code = 'weapons_tech'), 0),
      COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_fleet_record.user_id AND tt.code = 'shielding_tech'), 0),
      COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_fleet_record.user_id AND tt.code = 'armour_tech'), 0)
    INTO v_weapon_bonus, v_shield_bonus, v_hull_bonus;

    v_fleet_cargo := 0;
    
    FOR v_ship_record IN
      SELECT fs.ship_type_id, fs.quantity, st.code, st.name, st.weapon_power, st.shield_power,
             st.structural_integrity, st.metal_cost, st.crystal_cost, st.cargo_capacity, st.rapid_fire
      FROM fleet_ships fs
      JOIN ship_types st ON fs.ship_type_id = st.id
      WHERE fs.fleet_id = v_fleet_record.fleet_id AND fs.quantity > 0
    LOOP
      v_weapon := FLOOR(v_ship_record.weapon_power * (1 + v_weapon_bonus * 0.10));
      v_shield := FLOOR(v_ship_record.shield_power * (1 + v_shield_bonus * 0.10));
      v_hull := FLOOR(v_ship_record.structural_integrity * (1 + v_hull_bonus * 0.10));
      
      v_fleet_cargo := v_fleet_cargo + (v_ship_record.quantity * v_ship_record.cargo_capacity);

      IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_attacker_units) AS elem
        WHERE (elem->>'code') = v_ship_record.code
      ) THEN
        v_attacker_units := (
          SELECT jsonb_agg(
            CASE
              WHEN (elem->>'code') = v_ship_record.code THEN
                jsonb_set(
                  jsonb_set(
                    jsonb_set(
                      jsonb_set(elem, '{quantity}', to_jsonb((elem->>'quantity')::integer + v_ship_record.quantity)),
                      '{initial_quantity}', to_jsonb((elem->>'initial_quantity')::integer + v_ship_record.quantity)
                    ),
                    '{current_hull}', to_jsonb((elem->>'current_hull')::numeric + (v_hull * v_ship_record.quantity))
                  ),
                  '{current_shield}', to_jsonb((elem->>'current_shield')::numeric + (v_shield * v_ship_record.quantity))
                )
              ELSE elem
            END
          )
          FROM jsonb_array_elements(v_attacker_units) AS elem
        );
      ELSE
        v_attacker_units := v_attacker_units || jsonb_build_object(
          'type_id', v_ship_record.ship_type_id,
          'code', v_ship_record.code,
          'name', v_ship_record.name,
          'quantity', v_ship_record.quantity,
          'initial_quantity', v_ship_record.quantity,
          'weapon', v_weapon,
          'shield', v_shield,
          'hull', v_hull,
          'current_hull', v_hull * v_ship_record.quantity,
          'current_shield', v_shield * v_ship_record.quantity,
          'metal_cost', v_ship_record.metal_cost,
          'crystal_cost', v_ship_record.crystal_cost,
          'cargo_capacity', v_ship_record.cargo_capacity,
          'rapid_fire', COALESCE(v_ship_record.rapid_fire, '{}'::jsonb),
          'is_defense', false
        );
      END IF;
    END LOOP;

    v_total_cargo := v_total_cargo + v_fleet_cargo;
    
    v_fleet_distributions := v_fleet_distributions || jsonb_build_object(
      'fleet_id', v_fleet_record.fleet_id,
      'user_id', v_fleet_record.user_id,
      'cargo_capacity', v_fleet_cargo
    );
  END LOOP;

  SELECT 
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_defender_id AND tt.code = 'weapons_tech'), 0),
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_defender_id AND tt.code = 'shielding_tech'), 0),
    COALESCE((SELECT level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = v_defender_id AND tt.code = 'armour_tech'), 0)
  INTO v_weapon_bonus, v_shield_bonus, v_hull_bonus;

  FOR v_ship_record IN
    SELECT ps.ship_type_id, ps.quantity, st.code, st.name, st.weapon_power, st.shield_power,
           st.structural_integrity, st.metal_cost, st.crystal_cost, st.rapid_fire
    FROM planet_ships ps
    JOIN ship_types st ON ps.ship_type_id = st.id
    WHERE ps.planet_id = p_target_planet_id AND ps.quantity > 0
  LOOP
    v_weapon := FLOOR(v_ship_record.weapon_power * (1 + v_weapon_bonus * 0.10));
    v_shield := FLOOR(v_ship_record.shield_power * (1 + v_shield_bonus * 0.10));
    v_hull := FLOOR(v_ship_record.structural_integrity * (1 + v_hull_bonus * 0.10));
    
    v_defender_units := v_defender_units || jsonb_build_object(
      'type_id', v_ship_record.ship_type_id,
      'code', v_ship_record.code,
      'name', v_ship_record.name,
      'quantity', v_ship_record.quantity,
      'initial_quantity', v_ship_record.quantity,
      'weapon', v_weapon,
      'shield', v_shield,
      'hull', v_hull,
      'current_hull', v_hull * v_ship_record.quantity,
      'current_shield', v_shield * v_ship_record.quantity,
      'metal_cost', v_ship_record.metal_cost,
      'crystal_cost', v_ship_record.crystal_cost,
      'rapid_fire', COALESCE(v_ship_record.rapid_fire, '{}'::jsonb),
      'is_defense', false
    );
  END LOOP;

  FOR v_defense_record IN
    SELECT pd.defense_type_id, pd.quantity, dt.code, dt.name, dt.weapon_power, dt.shield_power,
           dt.structural_integrity, dt.metal_cost, dt.crystal_cost
    FROM planet_defenses pd
    JOIN defense_types dt ON pd.defense_type_id = dt.id
    WHERE pd.planet_id = p_target_planet_id AND pd.quantity > 0
    AND dt.code NOT IN ('interplanetary_missile', 'anti_ballistic_missile')
  LOOP
    v_weapon := FLOOR(v_defense_record.weapon_power * (1 + v_weapon_bonus * 0.10));
    v_shield := FLOOR(v_defense_record.shield_power * (1 + v_shield_bonus * 0.10));
    v_hull := FLOOR(v_defense_record.structural_integrity * (1 + v_hull_bonus * 0.10));
    
    v_defender_units := v_defender_units || jsonb_build_object(
      'type_id', v_defense_record.defense_type_id,
      'code', v_defense_record.code,
      'name', v_defense_record.name,
      'quantity', v_defense_record.quantity,
      'initial_quantity', v_defense_record.quantity,
      'weapon', v_weapon,
      'shield', v_shield,
      'hull', v_hull,
      'current_hull', v_hull * v_defense_record.quantity,
      'current_shield', v_shield * v_defense_record.quantity,
      'metal_cost', v_defense_record.metal_cost,
      'crystal_cost', v_defense_record.crystal_cost,
      'rapid_fire', '{}'::jsonb,
      'is_defense', true
    );
  END LOOP;

  v_combat_result := simulate_xnova_combat(v_attacker_units, v_defender_units);

  IF v_total_cargo > 0 THEN
    v_fleet_distributions := (
      SELECT jsonb_agg(
        jsonb_set(elem, '{cargo_ratio}', to_jsonb((elem->>'cargo_capacity')::numeric / v_total_cargo))
      )
      FROM jsonb_array_elements(v_fleet_distributions) AS elem
    );
  END IF;

  RETURN jsonb_set(
    jsonb_set(v_combat_result, '{total_cargo_capacity}', to_jsonb(v_total_cargo)),
    '{fleet_distributions}', v_fleet_distributions
  );
END;
$$;


--
-- TOC entry 597 (class 1255 OID 18398)
-- Name: phalanx_scan(uuid, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phalanx_scan(p_moon_id uuid, p_target_galaxy integer, p_target_system integer, p_target_position integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE
      v_moon record;
      v_phalanx_level integer;
      v_phalanx_range integer;
      v_system_distance integer;
      v_target_planet record;
      v_fleets jsonb;
      v_deuterium_cost integer;
    BEGIN
      -- Verify caller is authenticated
      IF auth.uid() IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
      END IF;

      -- Get moon info
      SELECT p.*
      INTO v_moon
      FROM planets p
      WHERE p.id = p_moon_id 
        AND p.planet_type = 'moon'
        AND p.user_id = auth.uid();

      IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Luna no encontrada o no es tuya');
      END IF;

      -- Get phalanx level SPECIFICALLY
      SELECT COALESCE(pb.level, 0)
      INTO v_phalanx_level
      FROM building_types bt
      LEFT JOIN planet_buildings pb 
        ON pb.building_type_id = bt.id 
        AND pb.planet_id = p_moon_id
      WHERE bt.code = 'sensor_phalanx';

      IF v_phalanx_level IS NULL OR v_phalanx_level = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'No tienes Sensor Phalanx en esta luna');
      END IF;

      -- Same galaxy only
      IF v_moon.galaxy != p_target_galaxy THEN
        RETURN jsonb_build_object('success', false, 'error', 'Solo puedes escanear en tu misma galaxia');
      END IF;

      -- Range: level^2 - 1 systems
      v_phalanx_range := (v_phalanx_level * v_phalanx_level) - 1;
      v_system_distance := ABS(v_moon.solar_system - p_target_system);

      IF v_system_distance > v_phalanx_range THEN
        RETURN jsonb_build_object(
          'success', false, 
          'error', format('Fuera de alcance. Rango: %s sistemas, Distancia: %s', v_phalanx_range, v_system_distance)
        );
      END IF;

      -- Target must be an enemy PLANET (not moon, not own)
      SELECT * INTO v_target_planet
      FROM planets
      WHERE galaxy = p_target_galaxy
        AND solar_system = p_target_system
        AND position = p_target_position
        AND planet_type = 'planet'
        AND user_id IS NOT NULL
        AND user_id != v_moon.user_id;

      IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'No hay planeta enemigo en esas coordenadas');
      END IF;

      -- Cost: 5000 deuterium from the MOON itself
      v_deuterium_cost := 5000;

      UPDATE planet_resources
      SET deuterium = deuterium - v_deuterium_cost
      WHERE planet_id = p_moon_id
        AND deuterium >= v_deuterium_cost;

      IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', format('Deuterio insuficiente en la luna (%s requerido)', v_deuterium_cost));
      END IF;

      -- =====================================================================
      -- Get ALL fleet movements related to the target planet
      -- OGame Phalanx shows 3 types of fleet activity:
      --   A) Fleets heading TO the target planet (incoming - not returning)
      --   B) Fleets SENT FROM the target planet (outgoing - not yet arrived)
      --   C) Fleets RETURNING to the target planet (completed missions going home)
      -- =====================================================================
      SELECT jsonb_agg(fleet_data ORDER BY (fleet_data->>'arrival_time'))
      INTO v_fleets
      FROM (
        SELECT jsonb_build_object(
          'id', f.id,
          'mission', f.mission_type,
          'origin', format('[%s:%s:%s]', 
            op.galaxy, op.solar_system, op.position
          ),
          'destination', format('[%s:%s:%s]',
            f.target_galaxy, f.target_system, f.target_position
          ),
          'arrival_time', f.arrival_time,
          'return_time', f.return_time,
          'is_returning', f.is_returning,
          'ships', (
            SELECT jsonb_agg(jsonb_build_object('type', st.name, 'quantity', fs.quantity))
            FROM fleet_ships fs
            JOIN ship_types st ON fs.ship_type_id = st.id
            WHERE fs.fleet_id = f.id AND fs.quantity > 0
          )
        ) as fleet_data
        FROM fleets f
        JOIN planets op ON f.origin_planet_id = op.id
        WHERE f.is_completed = false
          AND (
            -- A) Fleets heading TO the target planet (not returning)
            --    Filter by target_type to exclude fleets going to moon at same coords
            (f.target_galaxy = p_target_galaxy 
             AND f.target_system = p_target_system 
             AND f.target_position = p_target_position
             AND COALESCE(f.target_type, 'planet') = 'planet'
             AND NOT f.is_returning)
            OR
            -- B) Fleets SENT FROM the target planet (outgoing, haven't arrived yet)
            --    THIS WAS THE MISSING CASE - the main tactical use of Phalanx!
            (f.origin_planet_id = v_target_planet.id AND NOT f.is_returning)
            OR 
            -- C) Fleets RETURNING to the target planet (completed missions heading home)
            (f.origin_planet_id = v_target_planet.id AND f.is_returning)
          )
      ) sub;

      RETURN jsonb_build_object(
        'success', true,
        'planet_name', v_target_planet.name,
        'player', (SELECT username FROM profiles WHERE id = v_target_planet.user_id),
        'coordinates', format('[%s:%s:%s]', p_target_galaxy, p_target_system, p_target_position),
        'fleets', COALESCE(v_fleets, '[]'::jsonb),
        'deuterium_used', v_deuterium_cost,
        'phalanx_level', v_phalanx_level,
        'phalanx_range', v_phalanx_range
      );
    END;
$$;


--
-- TOC entry 682 (class 1255 OID 18875)
-- Name: prepare_withdrawal_for_signing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_withdrawal_for_signing(p_tx_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tx wallet_transactions%ROWTYPE;
  v_config wallet_config%ROWTYPE;
  v_expiry_timestamp bigint;
  v_amount_wei text;
BEGIN
  SELECT * INTO v_tx FROM wallet_transactions WHERE id = p_tx_id;
  
  IF v_tx.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction not found');
  END IF;

  IF v_tx.tx_type != 'withdrawal' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not a withdrawal transaction');
  END IF;

  IF v_tx.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction not in pending status');
  END IF;

  SELECT * INTO v_config FROM wallet_config WHERE id = 1;

  IF v_config.contract_address = '' OR v_config.contract_address IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Smart contract not configured');
  END IF;

  v_expiry_timestamp := EXTRACT(EPOCH FROM (now() + (v_config.signature_expiry_seconds || ' seconds')::interval))::bigint;
  v_amount_wei := (v_tx.amount * 1e18)::numeric::text;

  RETURN jsonb_build_object(
    'success', true,
    'tx_id', v_tx.id,
    'user_wallet', v_tx.wallet_address,
    'amount', v_tx.amount,
    'amount_wei', v_amount_wei,
    'withdraw_id', v_tx.id::text,
    'expiry', v_expiry_timestamp,
    'chain_id', v_config.chain_id,
    'contract_address', v_config.contract_address
  );
END;
$$;


--
-- TOC entry 691 (class 1255 OID 18893)
-- Name: prevent_direct_fxu_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_direct_fxu_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_current_role text;
BEGIN
  -- Get the current role
  v_current_role := current_setting('role', true);
  
  -- Allow service_role to make any changes (this is our edge functions)
  IF v_current_role = 'service_role' THEN
    RETURN NEW;
  END IF;
  
  -- Allow if called from a SECURITY DEFINER function (our database functions)
  -- This check works because triggers run with the permissions of the trigger owner
  -- but we're inside a SECURITY DEFINER function now
  
  -- For authenticated users, prevent direct fxu_balance changes
  IF v_current_role = 'authenticated' THEN
    -- Check if fxu_balance is being changed
    IF OLD.fxu_balance IS DISTINCT FROM NEW.fxu_balance THEN
      -- Check if this is coming from a legitimate function call
      -- by checking if we're in a transaction started by a known function
      RAISE EXCEPTION 'Direct modification of fxu_balance is not allowed. Use the proper deposit/withdrawal functions.';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- TOC entry 668 (class 1255 OID 18767)
-- Name: prevent_direct_vacation_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_direct_vacation_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Si vacation_mode cambio y no es el sistema (SECURITY DEFINER)
  -- Solo permitir cambios via toggle_vacation_mode
  IF OLD.vacation_mode IS DISTINCT FROM NEW.vacation_mode THEN
    -- Verificar si la llamada viene de una funcion SECURITY DEFINER
    -- El contexto de sesion indica si es una llamada interna
    IF current_setting('app.allow_vacation_update', true) != 'true' THEN
      RAISE EXCEPTION 'Vacation mode can only be changed via toggle_vacation_mode() function';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- TOC entry 733 (class 1255 OID 19053)
-- Name: preview_building_fxu_cost(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_building_fxu_cost(p_building_type_id uuid, p_current_level integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_building_type building_types%ROWTYPE;
  v_target_level integer;
  v_metal_cost numeric;
  v_crystal_cost numeric;
  v_deuterium_cost numeric;
  v_total_resource_value numeric;
  v_fxu_ratio numeric;
  v_cost_factor numeric;
BEGIN
  SELECT * INTO v_building_type FROM building_types WHERE id = p_building_type_id;
  
  IF v_building_type IS NULL THEN
    RETURN 0;
  END IF;
  
  v_target_level := p_current_level + 1;
  v_cost_factor := COALESCE(v_building_type.cost_factor::numeric, 1.5);
  
  v_metal_cost := COALESCE(v_building_type.base_metal, 0) * 
    POWER(v_cost_factor, v_target_level - 1);
  v_crystal_cost := COALESCE(v_building_type.base_crystal, 0) * 
    POWER(v_cost_factor, v_target_level - 1);
  v_deuterium_cost := COALESCE(v_building_type.base_deuterium, 0) * 
    POWER(v_cost_factor, v_target_level - 1);
  
  v_total_resource_value := v_metal_cost + (v_crystal_cost * 1.5) + (v_deuterium_cost * 3);
  
  SELECT COALESCE(value::numeric, 5000) INTO v_fxu_ratio 
  FROM game_settings WHERE key = 'fxu_cost_ratio_building';
  
  IF v_fxu_ratio IS NULL OR v_fxu_ratio <= 0 THEN
    v_fxu_ratio := 5000;
  END IF;
  
  RETURN GREATEST(1, CEIL(v_total_resource_value / v_fxu_ratio)::integer);
END;
$$;


--
-- TOC entry 734 (class 1255 OID 19054)
-- Name: preview_research_fxu_cost(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_research_fxu_cost(p_technology_type_id uuid, p_current_level integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tech_type technology_types%ROWTYPE;
  v_metal_cost numeric;
  v_crystal_cost numeric;
  v_deuterium_cost numeric;
  v_total_resource_value numeric;
  v_fxu_ratio numeric;
BEGIN
  SELECT * INTO v_tech_type FROM technology_types WHERE id = p_technology_type_id;
  
  IF v_tech_type IS NULL THEN
    RETURN 0;
  END IF;
  
  v_metal_cost := COALESCE(v_tech_type.base_metal, 0) * 
    POWER(COALESCE(v_tech_type.cost_factor, 2), p_current_level);
  v_crystal_cost := COALESCE(v_tech_type.base_crystal, 0) * 
    POWER(COALESCE(v_tech_type.cost_factor, 2), p_current_level);
  v_deuterium_cost := COALESCE(v_tech_type.base_deuterium, 0) * 
    POWER(COALESCE(v_tech_type.cost_factor, 2), p_current_level);
  
  v_total_resource_value := v_metal_cost + (v_crystal_cost * 1.5) + (v_deuterium_cost * 3);
  
  SELECT COALESCE(value::numeric, 3000) INTO v_fxu_ratio 
  FROM game_settings WHERE key = 'fxu_cost_ratio_research';
  
  IF v_fxu_ratio IS NULL OR v_fxu_ratio <= 0 THEN
    v_fxu_ratio := 3000;
  END IF;
  
  RETURN GREATEST(1, CEIL(v_total_resource_value / v_fxu_ratio)::integer);
END;
$$;


--
-- TOC entry 735 (class 1255 OID 19055)
-- Name: preview_shipyard_fxu_cost(text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_shipyard_fxu_cost(p_item_type text, p_item_id uuid, p_quantity integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ship_type ship_types%ROWTYPE;
  v_defense_type defense_types%ROWTYPE;
  v_metal_cost numeric;
  v_crystal_cost numeric;
  v_deuterium_cost numeric;
  v_total_resource_value numeric;
  v_fxu_ratio numeric;
BEGIN
  IF p_item_type = 'ship' THEN
    SELECT * INTO v_ship_type FROM ship_types WHERE id = p_item_id;
    IF v_ship_type IS NULL THEN RETURN 0; END IF;
    
    v_metal_cost := COALESCE(v_ship_type.metal_cost, 0);
    v_crystal_cost := COALESCE(v_ship_type.crystal_cost, 0);
    v_deuterium_cost := COALESCE(v_ship_type.deuterium_cost, 0);
    
    SELECT COALESCE(value::numeric, 8000) INTO v_fxu_ratio 
    FROM game_settings WHERE key = 'fxu_cost_ratio_ships';
  ELSE
    SELECT * INTO v_defense_type FROM defense_types WHERE id = p_item_id;
    IF v_defense_type IS NULL THEN RETURN 0; END IF;
    
    v_metal_cost := COALESCE(v_defense_type.metal_cost, 0);
    v_crystal_cost := COALESCE(v_defense_type.crystal_cost, 0);
    v_deuterium_cost := COALESCE(v_defense_type.deuterium_cost, 0);
    
    SELECT COALESCE(value::numeric, 10000) INTO v_fxu_ratio 
    FROM game_settings WHERE key = 'fxu_cost_ratio_defense';
  END IF;
  
  IF v_fxu_ratio IS NULL OR v_fxu_ratio <= 0 THEN
    v_fxu_ratio := 8000;
  END IF;
  
  v_total_resource_value := (v_metal_cost + (v_crystal_cost * 1.5) + (v_deuterium_cost * 3)) * p_quantity;
  
  RETURN GREATEST(1, CEIL(v_total_resource_value / v_fxu_ratio)::integer);
END;
$$;


--
-- TOC entry 900 (class 1255 OID 20179)
-- Name: process_acs_fleet_arrival(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_acs_fleet_arrival(p_acs_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acs RECORD;
  v_target_planet RECORD;
  v_combat_result jsonb;
  v_total_cargo_capacity integer := 0;
  v_loot_metal numeric := 0;
  v_loot_crystal numeric := 0;
  v_loot_deuterium numeric := 0;
  v_participant RECORD;
  v_contribution jsonb;
  v_share_percent numeric;
  v_unit jsonb;
  v_debris_metal numeric;
  v_debris_crystal numeric;
  v_destroyed_qty integer;
  v_rebuilt_qty integer;
  v_i integer;
  v_attacker_units_report text;
  v_defender_units_report text;
  v_attacker_names text;
BEGIN
  SELECT * INTO v_acs
  FROM acs_fleets
  WHERE id = p_acs_id
  AND is_active = true
  AND status = 'waiting'
  FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_acs.arrival_time > NOW() THEN
    RETURN;
  END IF;

  UPDATE acs_fleets SET status = 'in_combat' WHERE id = p_acs_id;

  SELECT p.* INTO v_target_planet
  FROM planets p
  WHERE p.galaxy = v_acs.target_galaxy
  AND p.solar_system = v_acs.target_system
  AND p.position = v_acs.target_position
  AND p.user_id IS NOT NULL;

  IF NOT FOUND OR v_target_planet.user_id IS NULL THEN
    FOR v_participant IN
      SELECT ap.fleet_id FROM acs_participants ap WHERE ap.acs_id = p_acs_id
    LOOP
      UPDATE fleets SET is_returning = true WHERE id = v_participant.fleet_id;
    END LOOP;
    UPDATE acs_fleets SET is_active = false, status = 'completed' WHERE id = p_acs_id;
    RETURN;
  END IF;

  v_combat_result := perform_acs_combat(p_acs_id, v_target_planet.id);

  v_attacker_units_report := format_unit_report(v_combat_result->'initial_attacker', v_combat_result->'attacker_remaining', 'attacker');
  v_defender_units_report := format_unit_report(v_combat_result->'initial_defender', v_combat_result->'defender_remaining', 'defender');

  SELECT string_agg(pr.username, ', ')
  INTO v_attacker_names
  FROM acs_participants ap
  JOIN profiles pr ON ap.user_id = pr.id
  WHERE ap.acs_id = p_acs_id;

  IF (v_combat_result->>'result') = 'attacker_won' THEN
    SELECT COALESCE(SUM((unit->>'quantity')::integer * COALESCE((unit->>'cargo_capacity')::integer, 0)), 0)
    INTO v_total_cargo_capacity
    FROM jsonb_array_elements(v_combat_result->'attacker_remaining') AS unit
    WHERE (unit->>'quantity')::integer > 0;

    SELECT 
      LEAST(metal * 0.5, v_total_cargo_capacity / 3),
      LEAST(crystal * 0.5, v_total_cargo_capacity / 3),
      LEAST(deuterium * 0.5, v_total_cargo_capacity / 3)
    INTO v_loot_metal, v_loot_crystal, v_loot_deuterium
    FROM planet_resources WHERE planet_id = v_target_planet.id;

    UPDATE planet_resources
    SET
      metal = GREATEST(0, metal - v_loot_metal),
      crystal = GREATEST(0, crystal - v_loot_crystal),
      deuterium = GREATEST(0, deuterium - v_loot_deuterium)
    WHERE planet_id = v_target_planet.id;

    FOR v_contribution IN SELECT * FROM jsonb_array_elements(v_combat_result->'fleet_contributions')
    LOOP
      IF (v_combat_result->>'total_fleet_power')::numeric > 0 THEN
        v_share_percent := (v_contribution->>'power')::numeric / (v_combat_result->>'total_fleet_power')::numeric;
      ELSE
        v_share_percent := 1.0 / jsonb_array_length(v_combat_result->'fleet_contributions');
      END IF;

      UPDATE fleets
      SET
        cargo_metal = cargo_metal + FLOOR(v_loot_metal * v_share_percent),
        cargo_crystal = cargo_crystal + FLOOR(v_loot_crystal * v_share_percent),
        cargo_deuterium = cargo_deuterium + FLOOR(v_loot_deuterium * v_share_percent)
      WHERE id = (v_contribution->>'fleet_id')::uuid;
    END LOOP;
  END IF;

  FOR v_participant IN
    SELECT ap.fleet_id, ap.user_id FROM acs_participants ap WHERE ap.acs_id = p_acs_id
  LOOP
    DELETE FROM fleet_ships WHERE fleet_id = v_participant.fleet_id;

    FOR v_unit IN 
      SELECT * FROM jsonb_array_elements(v_combat_result->'attacker_remaining')
      WHERE (value->>'fleet_id')::uuid = v_participant.fleet_id
      AND (value->>'quantity')::integer > 0
    LOOP
      INSERT INTO fleet_ships (fleet_id, ship_type_id, quantity)
      VALUES (v_participant.fleet_id, (v_unit->>'type_id')::integer, (v_unit->>'quantity')::integer);
    END LOOP;

    IF EXISTS (SELECT 1 FROM fleet_ships WHERE fleet_id = v_participant.fleet_id AND quantity > 0) THEN
      UPDATE fleets SET is_returning = true WHERE id = v_participant.fleet_id;
    ELSE
      UPDATE fleets SET is_completed = true WHERE id = v_participant.fleet_id;
    END IF;

    IF (v_combat_result->>'result') = 'attacker_won' THEN
      UPDATE profiles SET battles_won = battles_won + 1 WHERE id = v_participant.user_id;
    ELSIF (v_combat_result->>'result') = 'defender_won' THEN
      UPDATE profiles SET battles_lost = battles_lost + 1 WHERE id = v_participant.user_id;
    ELSE
      UPDATE profiles SET battles_draw = battles_draw + 1 WHERE id = v_participant.user_id;
    END IF;
  END LOOP;

  FOR v_unit IN SELECT * FROM jsonb_array_elements(v_combat_result->'defender_remaining')
  LOOP
    IF (v_unit->>'is_defense')::boolean THEN
      UPDATE planet_defenses
      SET quantity = (v_unit->>'quantity')::integer
      WHERE planet_id = v_target_planet.id AND defense_type_id = (v_unit->>'type_id')::integer;
    ELSE
      UPDATE planet_ships
      SET quantity = (v_unit->>'quantity')::integer
      WHERE planet_id = v_target_planet.id AND ship_type_id = (v_unit->>'type_id')::integer;
    END IF;
  END LOOP;

  FOR v_unit IN SELECT * FROM jsonb_array_elements(v_combat_result->'destroyed_defenses')
  LOOP
    v_destroyed_qty := (v_unit->>'quantity')::integer;
    v_rebuilt_qty := 0;
    FOR v_i IN 1..v_destroyed_qty LOOP
      IF random() < 0.7 THEN
        v_rebuilt_qty := v_rebuilt_qty + 1;
      END IF;
    END LOOP;
    UPDATE planet_defenses
    SET quantity = quantity + v_rebuilt_qty
    WHERE planet_id = v_target_planet.id AND defense_type_id = (v_unit->>'defense_type_id')::integer;
  END LOOP;

  v_debris_metal := COALESCE((v_combat_result->>'debris_metal')::numeric, 0);
  v_debris_crystal := COALESCE((v_combat_result->>'debris_crystal')::numeric, 0);

  IF v_debris_metal > 0 OR v_debris_crystal > 0 THEN
    INSERT INTO debris_fields (galaxy, solar_system, position, metal, crystal)
    VALUES (v_acs.target_galaxy, v_acs.target_system, v_acs.target_position, v_debris_metal, v_debris_crystal)
    ON CONFLICT (galaxy, solar_system, position)
    DO UPDATE SET metal = debris_fields.metal + EXCLUDED.metal, crystal = debris_fields.crystal + EXCLUDED.crystal, updated_at = NOW();
  END IF;

  IF (v_combat_result->>'result') = 'attacker_won' THEN
    UPDATE profiles SET battles_lost = battles_lost + 1 WHERE id = v_target_planet.user_id;
  ELSIF (v_combat_result->>'result') = 'defender_won' THEN
    UPDATE profiles SET battles_won = battles_won + 1 WHERE id = v_target_planet.user_id;
  ELSE
    UPDATE profiles SET battles_draw = battles_draw + 1 WHERE id = v_target_planet.user_id;
  END IF;

  FOR v_participant IN
    SELECT ap.user_id, pr.username FROM acs_participants ap
    JOIN profiles pr ON ap.user_id = pr.id
    WHERE ap.acs_id = p_acs_id
  LOOP
    INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
    VALUES (
      NULL,
      v_participant.user_id,
      format('Reporte ACS - %s', 
        CASE (v_combat_result->>'result')
          WHEN 'attacker_won' THEN 'Victoria'
          WHEN 'defender_won' THEN 'Derrota'
          ELSE 'Empate'
        END),
      format(E'Combate ACS en [%s:%s:%s]\n\nResultado: %s\nRondas: %s\nParticipantes ACS: %s\n\n=== FUERZAS ATACANTES ===\n%s\n\n=== FUERZAS DEFENSORAS ===\n%s\n\nBotin total: %s Metal, %s Cristal, %s Deuterio\nEscombros generados: %s Metal, %s Cristal\n\nPerdidas atacantes: %s Metal, %s Cristal\nPerdidas defensor: %s Metal, %s Cristal\n\nLas defensas destruidas tienen 70%% de probabilidad de ser reconstruidas automaticamente.',
        v_acs.target_galaxy, v_acs.target_system, v_acs.target_position,
        CASE (v_combat_result->>'result') WHEN 'attacker_won' THEN 'VICTORIA' WHEN 'defender_won' THEN 'DERROTA' ELSE 'EMPATE' END,
        (v_combat_result->>'rounds'),
        v_acs.current_participants,
        v_attacker_units_report,
        v_defender_units_report,
        FLOOR(v_loot_metal), FLOOR(v_loot_crystal), FLOOR(v_loot_deuterium),
        FLOOR(v_debris_metal), FLOOR(v_debris_crystal),
        FLOOR(COALESCE((v_combat_result->>'attacker_losses_metal')::numeric, 0)),
        FLOOR(COALESCE((v_combat_result->>'attacker_losses_crystal')::numeric, 0)),
        FLOOR(COALESCE((v_combat_result->>'defender_losses_metal')::numeric, 0)),
        FLOOR(COALESCE((v_combat_result->>'defender_losses_crystal')::numeric, 0))),
      'battle'
    );
  END LOOP;

  INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
  VALUES (
    NULL,
    v_target_planet.user_id,
    format('Tu planeta fue atacado por ACS (%s) - %s',
      COALESCE(v_attacker_names, 'Desconocido'),
      CASE (v_combat_result->>'result')
        WHEN 'attacker_won' THEN 'Derrota'
        WHEN 'defender_won' THEN 'Victoria'
        ELSE 'Empate'
      END),
    format(E'Tu planeta en [%s:%s:%s] fue atacado por un ACS de %s flotas.\nAtacantes: %s\n\nResultado: %s\nRondas: %s\n\n=== TUS FUERZAS ===\n%s\n\n=== FUERZAS ATACANTES ===\n%s\n\nRecursos saqueados: %s Metal, %s Cristal, %s Deuterio\nEscombros generados: %s Metal, %s Cristal\n\nTus perdidas: %s Metal, %s Cristal\nPerdidas atacantes: %s Metal, %s Cristal\n\nLas defensas destruidas tienen 70%% de probabilidad de ser reconstruidas automaticamente.',
      v_acs.target_galaxy, v_acs.target_system, v_acs.target_position,
      v_acs.current_participants,
      COALESCE(v_attacker_names, 'Desconocido'),
      CASE (v_combat_result->>'result') WHEN 'attacker_won' THEN 'DERROTA' WHEN 'defender_won' THEN 'VICTORIA' ELSE 'EMPATE' END,
      (v_combat_result->>'rounds'),
      v_defender_units_report,
      v_attacker_units_report,
      FLOOR(v_loot_metal), FLOOR(v_loot_crystal), FLOOR(v_loot_deuterium),
      FLOOR(v_debris_metal), FLOOR(v_debris_crystal),
      FLOOR(COALESCE((v_combat_result->>'defender_losses_metal')::numeric, 0)),
      FLOOR(COALESCE((v_combat_result->>'defender_losses_crystal')::numeric, 0)),
      FLOOR(COALESCE((v_combat_result->>'attacker_losses_metal')::numeric, 0)),
      FLOOR(COALESCE((v_combat_result->>'attacker_losses_crystal')::numeric, 0))),
    'battle'
  );

  UPDATE acs_fleets SET is_active = false, status = 'completed' WHERE id = p_acs_id;
END;
$$;


--
-- TOC entry 731 (class 1255 OID 19010)
-- Name: process_admin_withdrawal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_admin_withdrawal(p_withdrawal_id uuid, p_tx_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
BEGIN
  v_user_id := auth.uid();
  
  SELECT is_admin INTO v_is_admin
  FROM profiles
  WHERE id = v_user_id;
  
  IF NOT v_is_admin THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores');
  END IF;
  
  UPDATE admin_withdrawals
  SET status = 'confirmed',
      tx_hash = p_tx_hash,
      processed_at = now()
  WHERE id = p_withdrawal_id
  AND status = 'pending';
  
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- TOC entry 756 (class 1255 OID 19086)
-- Name: process_all_pending_fleets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_all_pending_fleets() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fleet record;
  v_processed_count integer := 0;
  v_error_count integer := 0;
BEGIN
  FOR v_fleet IN
    SELECT id, user_id, mission_type
    FROM fleets
    WHERE is_completed = false
    AND NOT is_returning
    AND arrival_time <= NOW()
    AND mission_type != 'hold'
    AND NOT (
      mission_type = 'deploy' 
      AND cargo_metal = 0 AND cargo_crystal = 0 AND cargo_deuterium = 0
      AND NOT EXISTS (
        SELECT 1 FROM planets p 
        WHERE p.user_id = fleets.user_id 
        AND p.galaxy = fleets.target_galaxy 
        AND p.solar_system = fleets.target_system 
        AND p.position = fleets.target_position
      )
    )
    ORDER BY arrival_time ASC
    LIMIT 100
  LOOP
    BEGIN
      PERFORM process_fleet_arrival(v_fleet.id);
      v_processed_count := v_processed_count + 1;
    EXCEPTION WHEN OTHERS THEN
      v_error_count := v_error_count + 1;
      RAISE WARNING 'Error processing fleet %: %', v_fleet.id, SQLERRM;
    END;
  END LOOP;

  FOR v_fleet IN
    SELECT id, user_id, mission_type
    FROM fleets
    WHERE is_completed = false
    AND is_returning
    AND return_time <= NOW()
    ORDER BY return_time ASC
    LIMIT 100
  LOOP
    BEGIN
      PERFORM process_fleet_arrival(v_fleet.id);
      v_processed_count := v_processed_count + 1;
    EXCEPTION WHEN OTHERS THEN
      v_error_count := v_error_count + 1;
      RAISE WARNING 'Error processing returning fleet %: %', v_fleet.id, SQLERRM;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'processed_count', v_processed_count,
    'error_count', v_error_count
  );
END;
$$;


--
-- TOC entry 764 (class 1255 OID 19139)
-- Name: process_all_research_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_all_research_completion() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user record;
  v_processed_count integer := 0;
BEGIN
  FOR v_user IN 
    SELECT DISTINCT ut.user_id
    FROM user_technologies ut
    WHERE ut.is_researching = true
    AND ut.research_end_time <= NOW()
  LOOP
    BEGIN
      PERFORM complete_research(v_user.user_id);
      v_processed_count := v_processed_count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Error completing research for user %: %', v_user.user_id, SQLERRM;
    END;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'processed_count', v_processed_count
  );
END;
$$;


--
-- TOC entry 746 (class 1255 OID 19069)
-- Name: process_all_user_building_queues(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_all_user_building_queues() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_user_id uuid;
v_completed_count integer := 0;
v_has_pending boolean;
v_lunar_base_id integer;
BEGIN
SELECT auth.uid() INTO v_user_id;
IF v_user_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
END IF;

SELECT id INTO v_lunar_base_id FROM building_types WHERE code = 'lunar_base' LIMIT 1;

SELECT EXISTS(
SELECT 1 FROM building_queue bq
JOIN planets p ON bq.planet_id = p.id
WHERE p.user_id = v_user_id
AND bq.end_time IS NOT NULL 
AND bq.end_time <= NOW()
LIMIT 1
) INTO v_has_pending;

IF NOT v_has_pending THEN
UPDATE building_queue bq
SET start_time = NOW(),
end_time = NOW() + (bq.build_time * INTERVAL '1 second')
FROM planets p
WHERE bq.planet_id = p.id
AND p.user_id = v_user_id
AND bq.queue_position = 1
AND bq.start_time IS NULL;

RETURN jsonb_build_object('success', true, 'completed_count', 0);
END IF;

WITH completed AS (
SELECT bq.id, bq.planet_id, bq.building_type_id, bq.target_level
FROM building_queue bq
JOIN planets p ON bq.planet_id = p.id
WHERE p.user_id = v_user_id
AND bq.end_time IS NOT NULL 
AND bq.end_time <= NOW()
ORDER BY bq.end_time
LIMIT 20
FOR UPDATE OF bq SKIP LOCKED
),
upserted AS (
INSERT INTO planet_buildings (planet_id, building_type_id, level, is_upgrading, upgrade_end_time)
SELECT c.planet_id, c.building_type_id, c.target_level, false, NULL
FROM completed c
ON CONFLICT (planet_id, building_type_id)
DO UPDATE SET 
level = GREATEST(planet_buildings.level, EXCLUDED.level),
is_upgrading = false,
upgrade_end_time = NULL
RETURNING planet_id
),
fields_updated AS (
UPDATE planets p
SET fields_used = LEAST(fields_max, fields_used + sub.cnt)
FROM (SELECT planet_id, COUNT(*) as cnt FROM upserted GROUP BY planet_id) sub
WHERE p.id = sub.planet_id
),
-- [FIX 2026-05-06] Lunar base on moon: grant +3 fields per level
moon_fields_updated AS (
UPDATE planets p
SET fields_max = GREATEST(p.fields_max, 1 + c.target_level * 3)
FROM completed c
WHERE p.id = c.planet_id
  AND p.planet_type = 'moon'
  AND c.building_type_id = v_lunar_base_id
),
deleted AS (
DELETE FROM building_queue WHERE id IN (SELECT id FROM completed)
RETURNING id
)
SELECT COUNT(*) INTO v_completed_count FROM deleted;

UPDATE building_queue bq
SET queue_position = sub.new_pos
FROM (
SELECT id, ROW_NUMBER() OVER (PARTITION BY planet_id ORDER BY queue_position) as new_pos
FROM building_queue bq2
JOIN planets p ON bq2.planet_id = p.id
WHERE p.user_id = v_user_id
) sub
WHERE bq.id = sub.id AND bq.queue_position != sub.new_pos;

UPDATE building_queue bq
SET start_time = NOW(),
end_time = NOW() + (bq.build_time * INTERVAL '1 second')
FROM planets p
WHERE bq.planet_id = p.id
AND p.user_id = v_user_id
AND bq.queue_position = 1
AND bq.start_time IS NULL;

RETURN jsonb_build_object('success', true, 'completed_count', v_completed_count);
END;
$$;


--
-- TOC entry 778 (class 1255 OID 19287)
-- Name: process_all_user_queues_on_reconnect(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_all_user_queues_on_reconnect(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet RECORD;
  v_buildings_completed int := 0;
  v_ships_completed int := 0;
  v_research_completed boolean := false;
  v_result jsonb;
BEGIN
  -- Verify this is the authenticated user
  IF p_user_id != auth.uid() THEN
    RETURN jsonb_build_object('error', 'Unauthorized');
  END IF;

  -- Process research first (user-level)
  BEGIN
    UPDATE user_technologies
    SET 
      level = level + 1,
      is_researching = false,
      research_end_time = NULL,
      research_planet_id = NULL,
      updated_at = now()
    WHERE user_id = p_user_id
      AND is_researching = true
      AND research_end_time IS NOT NULL
      AND research_end_time <= now() + interval '2 seconds';
    
    IF FOUND THEN
      v_research_completed := true;
      PERFORM update_user_points(p_user_id);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Continue even if research fails
    NULL;
  END;

  -- Process ALL planets' queues
  FOR v_planet IN 
    SELECT id FROM planets WHERE user_id = p_user_id
  LOOP
    -- Process building queue
    BEGIN
      SELECT * INTO v_result FROM process_completed_building_queue(v_planet.id);
      IF v_result IS NOT NULL AND (v_result->>'buildings_completed')::int > 0 THEN
        v_buildings_completed := v_buildings_completed + (v_result->>'buildings_completed')::int;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    -- Process shipyard queue
    BEGIN
      SELECT * INTO v_result FROM process_completed_shipyard_queue(v_planet.id);
      IF v_result IS NOT NULL AND (v_result->>'units_completed')::int > 0 THEN
        v_ships_completed := v_ships_completed + (v_result->>'units_completed')::int;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'buildings_completed', v_buildings_completed,
    'ships_completed', v_ships_completed,
    'research_completed', v_research_completed,
    'processed_at', now()
  );
END;
$$;


--
-- TOC entry 710 (class 1255 OID 18937)
-- Name: process_all_user_shipyard_queues(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_all_user_shipyard_queues() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_completed_units integer := 0;
  v_has_pending boolean;
BEGIN
  SELECT auth.uid() INTO v_user_id;
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Early exit check
  SELECT EXISTS(
    SELECT 1 FROM shipyard_queue sq
    JOIN planets p ON sq.planet_id = p.id
    WHERE p.user_id = v_user_id
      AND sq.current_unit_end_time IS NOT NULL 
      AND sq.current_unit_end_time <= NOW()
    LIMIT 1
  ) INTO v_has_pending;
  
  IF NOT v_has_pending THEN
    -- Just activate pending first items
    UPDATE shipyard_queue sq
    SET start_time = NOW(),
        current_unit_end_time = NOW() + (sq.build_time_per_unit * INTERVAL '1 second')
    FROM planets p
    WHERE sq.planet_id = p.id
      AND p.user_id = v_user_id
      AND sq.queue_position = 1
      AND sq.start_time IS NULL;
    
    RETURN jsonb_build_object('success', true, 'completed_units', 0);
  END IF;

  -- Bulk process ships
  WITH completed_ships AS (
    SELECT sq.id, sq.planet_id, sq.ship_type_id, sq.quantity - sq.quantity_completed as units
    FROM shipyard_queue sq
    JOIN planets p ON sq.planet_id = p.id
    WHERE p.user_id = v_user_id
      AND sq.item_type = 'ship'
      AND sq.ship_type_id IS NOT NULL
      AND sq.current_unit_end_time IS NOT NULL 
      AND sq.current_unit_end_time <= NOW()
    LIMIT 20
    FOR UPDATE OF sq SKIP LOCKED
  ),
  ship_upsert AS (
    INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
    SELECT cs.planet_id, cs.ship_type_id, cs.units
    FROM completed_ships cs
    ON CONFLICT (planet_id, ship_type_id)
    DO UPDATE SET quantity = planet_ships.quantity + EXCLUDED.quantity
    RETURNING 1 as done
  ),
  deleted_ships AS (
    DELETE FROM shipyard_queue WHERE id IN (SELECT id FROM completed_ships)
    RETURNING quantity - quantity_completed as units
  )
  SELECT COALESCE(SUM(units), 0) INTO v_completed_units FROM deleted_ships;

  -- Bulk process defense
  WITH completed_defense AS (
    SELECT sq.id, sq.planet_id, sq.defense_type_id, sq.quantity - sq.quantity_completed as units
    FROM shipyard_queue sq
    JOIN planets p ON sq.planet_id = p.id
    WHERE p.user_id = v_user_id
      AND sq.item_type = 'defense'
      AND sq.defense_type_id IS NOT NULL
      AND sq.current_unit_end_time IS NOT NULL 
      AND sq.current_unit_end_time <= NOW()
    LIMIT 20
    FOR UPDATE OF sq SKIP LOCKED
  ),
  defense_upsert AS (
    INSERT INTO planet_defenses (planet_id, defense_type_id, quantity)
    SELECT cd.planet_id, cd.defense_type_id, cd.units
    FROM completed_defense cd
    ON CONFLICT (planet_id, defense_type_id)
    DO UPDATE SET quantity = planet_defenses.quantity + EXCLUDED.quantity
    RETURNING 1 as done
  ),
  deleted_defense AS (
    DELETE FROM shipyard_queue WHERE id IN (SELECT id FROM completed_defense)
    RETURNING quantity - quantity_completed as units
  )
  SELECT v_completed_units + COALESCE(SUM(units), 0) INTO v_completed_units FROM deleted_defense;

  -- Reorder and activate
  UPDATE shipyard_queue sq
  SET queue_position = sub.new_pos
  FROM (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY planet_id ORDER BY queue_position) as new_pos
    FROM shipyard_queue sq2
    JOIN planets p ON sq2.planet_id = p.id
    WHERE p.user_id = v_user_id
  ) sub
  WHERE sq.id = sub.id AND sq.queue_position != sub.new_pos;

  UPDATE shipyard_queue sq
  SET start_time = NOW(),
      current_unit_end_time = NOW() + (sq.build_time_per_unit * INTERVAL '1 second')
  FROM planets p
  WHERE sq.planet_id = p.id
    AND p.user_id = v_user_id
    AND sq.queue_position = 1
    AND sq.start_time IS NULL;

  RETURN jsonb_build_object('success', true, 'completed_units', v_completed_units);
END;
$$;


--
-- TOC entry 745 (class 1255 OID 19068)
-- Name: process_building_queue_internal(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_building_queue_internal(p_planet_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
DECLARE
  v_planet planets%ROWTYPE;
  v_queue_item RECORD;
  v_completed_count integer := 0;
  v_result jsonb;
  v_legacy_completed integer := 0;
  v_existing_building planet_buildings%ROWTYPE;
  v_levels_added integer;
  v_building_code text;
  v_fields_increase integer;
BEGIN
  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id AND user_id = p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not found or not owned');
  END IF;

  UPDATE building_queue
  SET 
    start_time = COALESCE(start_time, NOW()),
    end_time = COALESCE(end_time, NOW() + (build_time || ' seconds')::interval)
  WHERE planet_id = p_planet_id
    AND queue_position = 1
    AND (start_time IS NULL OR end_time IS NULL);

  FOR v_queue_item IN 
    SELECT bq.*, bt.code as building_code
    FROM building_queue bq
    JOIN building_types bt ON bt.id = bq.building_type_id
    WHERE bq.planet_id = p_planet_id 
      AND bq.end_time IS NOT NULL 
      AND bq.end_time <= (NOW() + INTERVAL '2 seconds')
    ORDER BY bq.queue_position
  LOOP
    SELECT * INTO v_existing_building 
    FROM planet_buildings 
    WHERE planet_id = v_queue_item.planet_id AND building_type_id = v_queue_item.building_type_id;

    IF FOUND THEN
      v_levels_added := v_queue_item.target_level - v_existing_building.level;
      UPDATE planet_buildings 
      SET level = v_queue_item.target_level, is_upgrading = false, upgrade_end_time = NULL
      WHERE id = v_existing_building.id;
    ELSE
      v_levels_added := v_queue_item.target_level;
      INSERT INTO planet_buildings (planet_id, building_type_id, level, is_upgrading)
      VALUES (v_queue_item.planet_id, v_queue_item.building_type_id, v_queue_item.target_level, false);
    END IF;

    -- Lunar Base: +3 fields_max per level | Terraformer: +5 fields_max per level
    IF v_queue_item.building_code = 'lunar_base' THEN
      v_fields_increase := v_levels_added * 3;
      UPDATE planets 
      SET fields_used = fields_used + v_levels_added,
          fields_max = fields_max + v_fields_increase
      WHERE id = v_queue_item.planet_id;
    ELSIF v_queue_item.building_code = 'terraformer' THEN
      v_fields_increase := v_levels_added * 5;
      UPDATE planets 
      SET fields_used = fields_used + v_levels_added,
          fields_max = fields_max + v_fields_increase
      WHERE id = v_queue_item.planet_id;
    ELSIF v_levels_added > 0 THEN
      UPDATE planets SET fields_used = fields_used + v_levels_added WHERE id = v_queue_item.planet_id;
    END IF;

    DELETE FROM building_queue WHERE id = v_queue_item.id;
    v_completed_count := v_completed_count + 1;
  END LOOP;

  WITH reordered AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY queue_position) as new_pos
    FROM building_queue
    WHERE planet_id = p_planet_id
  )
  UPDATE building_queue bq
  SET 
    queue_position = r.new_pos,
    start_time = CASE WHEN r.new_pos = 1 THEN COALESCE(bq.start_time, NOW()) ELSE bq.start_time END,
    end_time = CASE WHEN r.new_pos = 1 THEN COALESCE(bq.end_time, NOW() + (bq.build_time || ' seconds')::interval) ELSE bq.end_time END
  FROM reordered r
  WHERE bq.id = r.id;

  SELECT COUNT(*) INTO v_legacy_completed
  FROM planet_buildings
  WHERE planet_id = p_planet_id
    AND is_upgrading = true
    AND upgrade_end_time IS NOT NULL
    AND upgrade_end_time <= (NOW() + INTERVAL '2 seconds');

  IF v_legacy_completed > 0 THEN
    UPDATE planets 
    SET fields_used = fields_used + v_legacy_completed 
    WHERE id = p_planet_id;
    
    UPDATE planet_buildings
    SET level = level + 1, is_upgrading = false, upgrade_end_time = NULL
    WHERE planet_id = p_planet_id
      AND is_upgrading = true
      AND upgrade_end_time IS NOT NULL
      AND upgrade_end_time <= (NOW() + INTERVAL '2 seconds');
  END IF;

  RETURN jsonb_build_object('success', true, 'completed_count', v_completed_count + v_legacy_completed);
END;
$$;


--
-- TOC entry 634 (class 1255 OID 18596)
-- Name: process_completed_building_queue(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_completed_building_queue(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    SET lock_timeout TO '30s'
    AS $$
DECLARE
  v_planet planets%ROWTYPE;
  v_queue_item RECORD;
  v_completed_count integer := 0;
  v_result jsonb;
  v_legacy_completed integer := 0;
BEGIN
  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id;
  IF NOT FOUND OR v_planet.user_id != auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not found or not owned');
  END IF;

  FOR v_queue_item IN
    SELECT bq.* FROM building_queue bq
    WHERE bq.planet_id = p_planet_id
    AND bq.end_time IS NOT NULL
    AND bq.end_time <= (NOW() + INTERVAL '2 seconds')
    ORDER BY bq.queue_position
    FOR UPDATE OF bq SKIP LOCKED
  LOOP
    v_result := complete_building_queue_item(v_queue_item.id);
    IF (v_result->>'success')::boolean THEN
      v_completed_count := v_completed_count + 1;
    END IF;
  END LOOP;

  SELECT COUNT(*) INTO v_legacy_completed
  FROM planet_buildings
  WHERE planet_id = p_planet_id
  AND is_upgrading = true
  AND upgrade_end_time IS NOT NULL
  AND upgrade_end_time <= (NOW() + INTERVAL '2 seconds');

  IF v_legacy_completed > 0 THEN
    UPDATE planets
    SET fields_used = fields_used + v_legacy_completed
    WHERE id = p_planet_id;

    UPDATE planet_buildings
    SET level = level + 1, is_upgrading = false, upgrade_end_time = NULL
    WHERE planet_id = p_planet_id
    AND is_upgrading = true
    AND upgrade_end_time IS NOT NULL
    AND upgrade_end_time <= (NOW() + INTERVAL '2 seconds');
  END IF;

  RETURN jsonb_build_object('success', true, 'completed_count', v_completed_count + v_legacy_completed);
END;
$$;


--
-- TOC entry 675 (class 1255 OID 18785)
-- Name: process_completed_shipyard_queue(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_completed_shipyard_queue(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet planets%ROWTYPE;
  v_queue_item RECORD;
  v_completed_units integer := 0;
  v_total_completed integer := 0;
  v_now timestamptz := NOW();
  v_build_time_ms bigint;
  v_elapsed_ms bigint;
  v_units_to_complete integer;
  v_remaining_units integer;
  v_existing_ship planet_ships%ROWTYPE;
  v_existing_defense planet_defenses%ROWTYPE;
  v_next_item RECORD;
BEGIN
  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id;
  IF NOT FOUND OR v_planet.user_id != auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not found or not owned');
  END IF;

  -- STEP 1: Clean up fully completed items (critical fix)
  FOR v_queue_item IN
    SELECT * FROM shipyard_queue
    WHERE planet_id = p_planet_id
      AND quantity_completed >= quantity
    ORDER BY queue_position
    FOR UPDATE SKIP LOCKED
  LOOP
    DELETE FROM shipyard_queue WHERE id = v_queue_item.id;
    
    -- Reorder remaining items
    UPDATE shipyard_queue
    SET queue_position = queue_position - 1
    WHERE planet_id = p_planet_id 
      AND queue_position > v_queue_item.queue_position;
  END LOOP;

  -- STEP 2: Initialize position-1 items with NULL current_unit_end_time
  UPDATE shipyard_queue
  SET
    start_time = COALESCE(start_time, v_now),
    current_unit_end_time = COALESCE(start_time, v_now) + (build_time_per_unit || ' seconds')::interval
  WHERE planet_id = p_planet_id
    AND queue_position = 1
    AND current_unit_end_time IS NULL;

  -- STEP 3: Process completed units
  FOR v_queue_item IN
    SELECT * FROM shipyard_queue
    WHERE planet_id = p_planet_id
      AND queue_position = 1
      AND current_unit_end_time IS NOT NULL
      AND current_unit_end_time <= v_now
    ORDER BY queue_position
  LOOP
    v_build_time_ms := GREATEST(1000, v_queue_item.build_time_per_unit * 1000);
    v_elapsed_ms := EXTRACT(EPOCH FROM (v_now - v_queue_item.current_unit_end_time)) * 1000;
    v_remaining_units := v_queue_item.quantity - v_queue_item.quantity_completed;

    v_units_to_complete := LEAST(
      1 + FLOOR(v_elapsed_ms / v_build_time_ms)::integer,
      v_remaining_units
    );

    IF v_units_to_complete > 0 THEN
      IF v_queue_item.item_type = 'ship' AND v_queue_item.ship_type_id IS NOT NULL THEN
        SELECT * INTO v_existing_ship
        FROM planet_ships
        WHERE planet_id = p_planet_id AND ship_type_id = v_queue_item.ship_type_id;

        IF FOUND THEN
          UPDATE planet_ships
          SET quantity = quantity + v_units_to_complete
          WHERE id = v_existing_ship.id;
        ELSE
          INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
          VALUES (p_planet_id, v_queue_item.ship_type_id, v_units_to_complete);
        END IF;
      ELSIF v_queue_item.item_type = 'defense' AND v_queue_item.defense_type_id IS NOT NULL THEN
        -- [SAFETY] Shield dome per-account check: skip if account already has one
        IF v_queue_item.defense_type_id IN (7, 8) THEN
          IF EXISTS (
            SELECT 1 FROM planet_defenses pd
            JOIN planets pl ON pl.id = pd.planet_id
            WHERE pl.user_id = v_planet.user_id
              AND pd.defense_type_id = v_queue_item.defense_type_id
              AND pd.quantity > 0
              AND pd.planet_id IS DISTINCT FROM p_planet_id
          ) THEN
            -- Account already has this shield dome on another planet, skip silently
            DELETE FROM shipyard_queue WHERE id = v_queue_item.id;
            CONTINUE;
          END IF;
        END IF;

        SELECT * INTO v_existing_defense
        FROM planet_defenses
        WHERE planet_id = p_planet_id AND defense_type_id = v_queue_item.defense_type_id;

        IF FOUND THEN
          UPDATE planet_defenses
          SET quantity = quantity + v_units_to_complete
          WHERE id = v_existing_defense.id;
        ELSE
          INSERT INTO planet_defenses (planet_id, defense_type_id, quantity)
          VALUES (p_planet_id, v_queue_item.defense_type_id, v_units_to_complete);
        END IF;
      END IF;

      v_total_completed := v_total_completed + v_units_to_complete;

      IF v_queue_item.quantity_completed + v_units_to_complete >= v_queue_item.quantity THEN
        DELETE FROM shipyard_queue WHERE id = v_queue_item.id;

        UPDATE shipyard_queue
        SET
          queue_position = queue_position - 1,
          start_time = CASE WHEN queue_position = 2 THEN v_now ELSE start_time END,
          current_unit_end_time = CASE
            WHEN queue_position = 2 THEN v_now + (build_time_per_unit || ' seconds')::interval
            ELSE current_unit_end_time
          END
        WHERE planet_id = p_planet_id AND queue_position > 1;
      ELSE
        UPDATE shipyard_queue
        SET
          quantity_completed = quantity_completed + v_units_to_complete,
          current_unit_end_time = v_now + (build_time_per_unit || ' seconds')::interval
        WHERE id = v_queue_item.id;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'completed_units', v_total_completed);
END;
$$;


--
-- TOC entry 894 (class 1255 OID 20134)
-- Name: process_espionage_mission(uuid, record, record); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_espionage_mission(p_fleet_id uuid, p_fleet_record record, p_target_planet record) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_probe_type_id integer;
  v_probe_count integer := 1;
BEGIN
  SELECT id INTO v_probe_type_id FROM ship_types WHERE code = 'espionage_probe';
  
  SELECT COALESCE(quantity, 1) INTO v_probe_count
  FROM fleet_ships
  WHERE fleet_id = p_fleet_id AND ship_type_id = v_probe_type_id;
  
  v_probe_count := GREATEST(1, COALESCE(v_probe_count, 1));

  PERFORM generate_espionage_report(
    p_fleet_record.user_id, 
    p_target_planet.id, 
    p_target_planet.user_id,
    v_probe_count
  );

  UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
END;
$$;


--
-- TOC entry 619 (class 1255 OID 18550)
-- Name: process_expedition(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_expedition(p_fleet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_fleet record;
v_user_id uuid;
v_event_roll numeric;
v_result jsonb;
v_message_subject text;
v_message_body text;
v_metal_reward numeric := 0;
v_crystal_reward numeric := 0;
v_deuterium_reward numeric := 0;
v_metal_found numeric := 0;
v_crystal_found numeric := 0;
v_deuterium_found numeric := 0;
v_dark_matter_reward integer := 0;
v_fxu_reward numeric := 0;
v_ships_found jsonb := '[]'::jsonb;
v_ships_lost jsonb := '[]'::jsonb;
v_cargo_capacity numeric;
v_current_cargo numeric;
v_available_cargo numeric;
v_total_resources_found numeric;
v_ship_type record;
v_ship_quantity integer;
v_fleet_lost boolean := false;
v_partial_loss boolean := false;
v_loss_percent numeric := 0;
v_astrophysics_level integer := 0;
v_pool_result jsonb;
v_pool_won boolean := false;
v_pool_amount numeric := 0;
v_cargo_full boolean := false;
v_event_type text;
v_ships_before jsonb;
v_ships_lost_count integer := 0;
v_probe_type_id integer;
v_only_probes boolean := false;
v_total_ships integer := 0;
v_probe_count integer := 0;
BEGIN
SELECT * INTO v_fleet FROM fleets WHERE id = p_fleet_id;
IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'reason', 'Flota no encontrada');
END IF;

v_user_id := v_fleet.user_id;

SELECT id INTO v_probe_type_id FROM ship_types WHERE code = 'espionage_probe';

SELECT
COALESCE(SUM(fs.quantity), 0),
COALESCE(SUM(CASE WHEN fs.ship_type_id = v_probe_type_id THEN fs.quantity ELSE 0 END), 0)
INTO v_total_ships, v_probe_count
FROM fleet_ships fs
WHERE fs.fleet_id = p_fleet_id;

IF v_total_ships > 0 AND v_probe_count = v_total_ships THEN
v_only_probes := true;
END IF;

IF v_only_probes THEN
v_event_type := 'probes_nothing';
v_message_subject := 'Expedicion - Sondas Sin Hallazgos';
v_message_body := 'Tus Sondas de Espionaje exploraron la region pero no estan equipadas para ' ||
'recolectar recursos ni detectar tesoros. Las sondas estan disenadas para ' ||
'espionaje, no para expediciones de exploracion. ' ||
'Considera enviar naves de combate o transporte en futuras expediciones.';

UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;

INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
VALUES (NULL, v_user_id, v_message_subject, v_message_body, 'expedition');

RETURN jsonb_build_object(
'success', true,
'event_type', v_event_type,
'metal', 0,
'crystal', 0,
'deuterium', 0,
'dark_matter', 0,
'fxu_reward', 0,
'ships_found', '[]'::jsonb,
'ships_lost', '[]'::jsonb,
'fleet_lost', false,
'partial_loss', false,
'loss_percent', 0,
'pool_won', false,
'pool_amount', 0,
'cargo_was_full', false,
'only_probes', true
);
END IF;

SELECT COALESCE(ut.level, 0) INTO v_astrophysics_level
FROM user_technologies ut
JOIN technology_types tt ON ut.technology_type_id = tt.id
WHERE ut.user_id = v_user_id AND tt.code = 'astrophysics';

IF v_astrophysics_level IS NULL THEN
v_astrophysics_level := 0;
END IF;

SELECT COALESCE(SUM(fs.quantity * st.cargo_capacity), 0)
INTO v_cargo_capacity
FROM fleet_ships fs
JOIN ship_types st ON fs.ship_type_id = st.id
WHERE fs.fleet_id = p_fleet_id;

v_current_cargo := COALESCE(v_fleet.cargo_metal, 0) + COALESCE(v_fleet.cargo_crystal, 0) + COALESCE(v_fleet.cargo_deuterium, 0);
v_available_cargo := GREATEST(0, v_cargo_capacity - v_current_cargo);

SELECT jsonb_agg(jsonb_build_object('ship_type_id', fs.ship_type_id, 'name', st.name, 'quantity', fs.quantity))
INTO v_ships_before
FROM fleet_ships fs
JOIN ship_types st ON fs.ship_type_id = st.id
WHERE fs.fleet_id = p_fleet_id;

v_event_roll := random() * 100;

-- ====== EVENTOS NEGATIVOS: 13% total ======

IF v_event_roll < 2 THEN
-- AGUJERO NEGRO (2%) - Pierde toda la flota
v_fleet_lost := true;
v_event_type := 'black_hole';
v_message_subject := 'Expedicion PERDIDA - Agujero Negro';
v_message_body := 'DESASTRE! Tu flota de expedicion fue tragada por un agujero negro masivo. ' ||
'Las comunicaciones se cortaron abruptamente y no hubo senales de vida. ' ||
'Todas las naves y tripulacion se perdieron para siempre.';

v_ships_lost := v_ships_before;
DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id;
UPDATE fleets SET is_completed = true WHERE id = p_fleet_id;

ELSIF v_event_roll < 7 THEN
-- PIRATAS (5%) - Pierde 40-70% naves
v_partial_loss := true;
v_loss_percent := 40 + (random() * 30);
v_event_type := 'pirates';
v_message_subject := 'Expedicion - Emboscada Pirata Severa';
v_message_body := 'Tu flota fue emboscada por una armada pirata bien organizada! ' ||
'Despues de una feroz batalla, lograron escapar pero con grandes perdidas. ' ||
'Aproximadamente ' || floor(v_loss_percent)::text || '% de tus naves fueron destruidas.';

FOR v_ship_type IN
SELECT fs.ship_type_id, fs.quantity, st.name
FROM fleet_ships fs
JOIN ship_types st ON fs.ship_type_id = st.id
WHERE fs.fleet_id = p_fleet_id
LOOP
v_ships_lost_count := floor(v_ship_type.quantity * v_loss_percent / 100);
IF v_ships_lost_count > 0 THEN
v_ships_lost := v_ships_lost || jsonb_build_object(
'ship_type_id', v_ship_type.ship_type_id,
'name', v_ship_type.name,
'quantity', v_ships_lost_count
);
END IF;
END LOOP;

UPDATE fleet_ships
SET quantity = GREATEST(1, floor(quantity * (100 - v_loss_percent) / 100))
WHERE fleet_id = p_fleet_id;

UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;

ELSIF v_event_roll < 10 THEN
-- ANOMALIA GRAVITATORIA (3%) - Pierde 20-50% naves
v_partial_loss := true;
v_loss_percent := 20 + (random() * 30);
v_event_type := 'gravity_anomaly';
v_message_subject := 'Expedicion - Anomalia Gravitacional';
v_message_body := 'Tu flota se encontro con una anomalia gravitacional inesperada! ' ||
'Las fuerzas de marea extremas destrozaron varias naves antes de poder escapar. ' ||
'Perdiste aproximadamente ' || floor(v_loss_percent)::text || '% de tu flota.';

FOR v_ship_type IN
SELECT fs.ship_type_id, fs.quantity, st.name
FROM fleet_ships fs
JOIN ship_types st ON fs.ship_type_id = st.id
WHERE fs.fleet_id = p_fleet_id
LOOP
v_ships_lost_count := floor(v_ship_type.quantity * v_loss_percent / 100);
IF v_ships_lost_count > 0 THEN
v_ships_lost := v_ships_lost || jsonb_build_object(
'ship_type_id', v_ship_type.ship_type_id,
'name', v_ship_type.name,
'quantity', v_ships_lost_count
);
END IF;
END LOOP;

UPDATE fleet_ships
SET quantity = GREATEST(1, floor(quantity * (100 - v_loss_percent) / 100))
WHERE fleet_id = p_fleet_id;

UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;

ELSIF v_event_roll < 13 THEN
-- TORMENTA IONICA (3%) - Pierde 20-40% naves
v_partial_loss := true;
v_loss_percent := 20 + (random() * 20);
v_event_type := 'ion_storm';
v_message_subject := 'Expedicion - Tormenta de Iones';
v_message_body := 'Una violenta tormenta de iones golpeo tu flota sin previo aviso! ' ||
'Los sistemas electronicos fallaron y varias naves colisionaron entre si. ' ||
'Perdidas estimadas: ' || floor(v_loss_percent)::text || '% de la flota.';

FOR v_ship_type IN
SELECT fs.ship_type_id, fs.quantity, st.name
FROM fleet_ships fs
JOIN ship_types st ON fs.ship_type_id = st.id
WHERE fs.fleet_id = p_fleet_id
LOOP
v_ships_lost_count := floor(v_ship_type.quantity * v_loss_percent / 100);
IF v_ships_lost_count > 0 THEN
v_ships_lost := v_ships_lost || jsonb_build_object(
'ship_type_id', v_ship_type.ship_type_id,
'name', v_ship_type.name,
'quantity', v_ships_lost_count
);
END IF;
END LOOP;

UPDATE fleet_ships
SET quantity = GREATEST(1, floor(quantity * (100 - v_loss_percent) / 100))
WHERE fleet_id = p_fleet_id;

UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;

-- ====== EVENTO NEUTRAL: 17% ======

ELSIF v_event_roll < 30 THEN
-- NADA (17%) - Sin perdidas ni ganancias
v_event_type := 'nothing';
v_message_subject := 'Expedicion - Sin Hallazgos';
v_message_body := 'Tu flota exploro vastas regiones del espacio profundo durante dias, ' ||
'pero desafortunadamente no encontraron nada de valor. ' ||
'El universo a veces es un lugar vacio y desolado.';

UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;

-- ====== EVENTOS POSITIVOS: 70% total ======

ELSIF v_event_roll < 42 THEN
-- MATERIA OSCURA (12%)
v_event_type := 'dark_matter';
v_dark_matter_reward := 20 + floor(random() * 60)::integer + (v_astrophysics_level * 5);
v_message_subject := 'Expedicion - Materia Oscura';
v_message_body := 'Tu flota detecto una pequena concentracion de Materia Oscura flotando en el vacio. ' ||
'Lograron recolectar ' || v_dark_matter_reward::text || ' unidades.';

UPDATE profiles
SET dark_matter = COALESCE(dark_matter, 0) + v_dark_matter_reward
WHERE id = v_user_id;

UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;

ELSIF v_event_roll < 58 THEN
-- RECURSOS (16%)
v_event_type := 'resources';
v_metal_found := (3000 + floor(random() * 12000) * (1 + v_astrophysics_level * 0.05));
v_crystal_found := (1800 + floor(random() * 9000) * (1 + v_astrophysics_level * 0.05));
v_deuterium_found := (600 + floor(random() * 6000) * (1 + v_astrophysics_level * 0.05));
v_total_resources_found := v_metal_found + v_crystal_found + v_deuterium_found;

IF v_total_resources_found > v_available_cargo AND v_total_resources_found > 0 THEN
v_cargo_full := true;
v_metal_reward := floor(v_available_cargo * (v_metal_found / v_total_resources_found));
v_crystal_reward := floor(v_available_cargo * (v_crystal_found / v_total_resources_found));
v_deuterium_reward := floor(v_available_cargo * (v_deuterium_found / v_total_resources_found));
ELSE
v_metal_reward := floor(v_metal_found);
v_crystal_reward := floor(v_crystal_found);
v_deuterium_reward := floor(v_deuterium_found);
END IF;

v_message_subject := 'Expedicion - Recursos Encontrados';
IF v_cargo_full THEN
v_message_body := 'Tu flota encontro recursos abandonados en una estacion derrelicta. ' ||
'Solo pudieron cargar lo que cabia: ' ||
floor(v_metal_reward)::text || ' Metal, ' ||
floor(v_crystal_reward)::text || ' Cristal, ' ||
floor(v_deuterium_reward)::text || ' Deuterio.';
ELSE
v_message_body := 'Tu flota descubrio recursos flotando en los restos de una batalla antigua: ' ||
floor(v_metal_reward)::text || ' Metal, ' ||
floor(v_crystal_reward)::text || ' Cristal, ' ||
floor(v_deuterium_reward)::text || ' Deuterio.';
END IF;

UPDATE fleets
SET
cargo_metal = cargo_metal + v_metal_reward,
cargo_crystal = cargo_crystal + v_crystal_reward,
cargo_deuterium = cargo_deuterium + v_deuterium_reward,
is_returning = true
WHERE id = p_fleet_id;

ELSIF v_event_roll < 68 THEN
-- NAVES ENCONTRADAS (10%) - SOLO naves que el usuario puede construir
v_event_type := 'ships';
SELECT * INTO v_ship_type
FROM ship_types st
WHERE st.code NOT IN ('deathstar', 'colony_ship', 'star_destroyer', 'black_moon', 'espionage_probe', 'solar_satellite', 'falco_x_clasica')
AND st.base_speed > 0
AND user_can_build_ship(v_user_id, st.id)
ORDER BY random()
LIMIT 1;

IF FOUND THEN
v_ship_quantity := 1 + floor(random() * LEAST(3, 1 + v_astrophysics_level / 3))::integer;
v_ships_found := jsonb_build_array(jsonb_build_object(
'ship_type_id', v_ship_type.id,
'name', v_ship_type.name,
'quantity', v_ship_quantity
));

INSERT INTO fleet_ships (fleet_id, ship_type_id, quantity)
VALUES (p_fleet_id, v_ship_type.id, v_ship_quantity)
ON CONFLICT (fleet_id, ship_type_id)
DO UPDATE SET quantity = fleet_ships.quantity + v_ship_quantity;

v_message_subject := 'Expedicion - Naves Abandonadas';
v_message_body := 'Tu flota encontro ' || v_ship_quantity::text || ' ' || v_ship_type.name ||
' a la deriva con sistemas de soporte vital minimos. ' ||
'Fueron reactivadas y se unieron a tu flota.';
ELSE
v_event_type := 'resources';
v_metal_found := 2000 + floor(random() * 5000);
v_crystal_found := 1000 + floor(random() * 3000);
v_total_resources_found := v_metal_found + v_crystal_found;

IF v_total_resources_found > v_available_cargo AND v_total_resources_found > 0 THEN
v_cargo_full := true;
v_metal_reward := floor(v_available_cargo * (v_metal_found / v_total_resources_found));
v_crystal_reward := floor(v_available_cargo * (v_crystal_found / v_total_resources_found));
ELSE
v_metal_reward := floor(v_metal_found);
v_crystal_reward := floor(v_crystal_found);
END IF;

v_message_subject := 'Expedicion - Restos Espaciales';
v_message_body := 'Tu flota encontro los restos de una nave danada, pero no tenian ' ||
'la tecnologia necesaria para repararla. Recuperaron ' ||
floor(v_metal_reward)::text || ' Metal y ' ||
floor(v_crystal_reward)::text || ' Cristal de los escombros.';

UPDATE fleets
SET
cargo_metal = cargo_metal + v_metal_reward,
cargo_crystal = cargo_crystal + v_crystal_reward
WHERE id = p_fleet_id;
END IF;

UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;

ELSIF v_event_roll < 78 THEN
-- RECURSOS + MATERIA OSCURA (10%)
v_event_type := 'resources_and_dm';
v_metal_found := (2000 + floor(random() * 6000));
v_crystal_found := (1200 + floor(random() * 5000));
v_total_resources_found := v_metal_found + v_crystal_found;
v_dark_matter_reward := 15 + floor(random() * 45)::integer;

IF v_total_resources_found > v_available_cargo AND v_total_resources_found > 0 THEN
v_cargo_full := true;
v_metal_reward := floor(v_available_cargo * (v_metal_found / v_total_resources_found));
v_crystal_reward := floor(v_available_cargo * (v_crystal_found / v_total_resources_found));
ELSE
v_metal_reward := floor(v_metal_found);
v_crystal_reward := floor(v_crystal_found);
END IF;

v_message_subject := 'Expedicion - Descubrimiento Mixto';
v_message_body := 'Tu flota descubrio un pequeno deposito de recursos y Materia Oscura: ' ||
floor(v_metal_reward)::text || ' Metal, ' ||
floor(v_crystal_reward)::text || ' Cristal y ' ||
v_dark_matter_reward::text || ' Materia Oscura.';

UPDATE profiles SET dark_matter = COALESCE(dark_matter, 0) + v_dark_matter_reward WHERE id = v_user_id;

UPDATE fleets
SET
cargo_metal = cargo_metal + v_metal_reward,
cargo_crystal = cargo_crystal + v_crystal_reward,
is_returning = true
WHERE id = p_fleet_id;

ELSIF v_event_roll < 86 THEN
-- ARTEFACTO ANTIGUO (8%)
v_event_type := 'artifact';
v_dark_matter_reward := 100 + floor(random() * 150)::integer + (v_astrophysics_level * 15);
v_message_subject := 'Expedicion - Artefacto Antiguo';
v_message_body := 'Tu flota descubrio los restos de una civilizacion antigua! ' ||
'Entre los escombros encontraron un artefacto que contenia ' ||
v_dark_matter_reward::text || ' unidades de Materia Oscura cristalizada.';

UPDATE profiles SET dark_matter = COALESCE(dark_matter, 0) + v_dark_matter_reward WHERE id = v_user_id;
UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;

ELSIF v_event_roll < 94 THEN
-- HALLAZGO DE TOKENS (8%)
v_event_type := 'token_discovery';
v_fxu_reward := 5 + floor(random() * 21) + (v_astrophysics_level * 2);

v_message_subject := 'Expedicion - Hallazgo de Tokens FXU!';
v_message_body := 'Tu flota descubrio una capsula de almacenamiento digital a la deriva en el espacio! ' ||
'Al descifrar su contenido, encontraron ' || floor(v_fxu_reward)::text || ' Tokens FXU ' ||
'almacenados en un monedero cuantico antiguo. ' ||
'Los tokens han sido transferidos a tu cuenta.';

PERFORM _internal_set_fxu_context();

UPDATE profiles
SET fxu_balance = fxu_balance + v_fxu_reward
WHERE id = v_user_id;

INSERT INTO admin_revenue (revenue_type, amount, description, user_id)
VALUES ('expedition_token_find', v_fxu_reward, 'Hallazgo de tokens en expedicion', v_user_id);

UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;

ELSE
-- TESORO LEGENDARIO (6%)
v_event_type := 'legendary_treasure';
v_dark_matter_reward := 150 + floor(random() * 200)::integer + (v_astrophysics_level * 20);

v_pool_result := attempt_expedition_pool_win(v_user_id, true);
v_pool_won := COALESCE((v_pool_result->>'won')::boolean, false);
v_pool_amount := COALESCE((v_pool_result->>'amount')::numeric, 0);

v_message_subject := 'Expedicion - TESORO LEGENDARIO!';
v_message_body := 'INCREIBLE! Tu flota descubrio las coordenadas de un tesoro legendario perdido hace eones! ' ||
'Encontraron ' || v_dark_matter_reward::text || ' Materia Oscura.';

IF v_pool_won AND v_pool_amount > 0 THEN
v_message_body := v_message_body || E'\n\n*** JACKPOT DEL POOL DE EXPEDICIONES! ***\n' ||
'El tesoro legendario contenia ' || floor(v_pool_amount)::text || ' FXU!';
END IF;

UPDATE profiles SET dark_matter = COALESCE(dark_matter, 0) + v_dark_matter_reward WHERE id = v_user_id;
UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
END IF;

IF NOT v_fleet_lost AND NOT v_partial_loss AND v_event_type NOT IN ('nothing', 'legendary_treasure', 'token_discovery') THEN
v_pool_result := attempt_expedition_pool_win(v_user_id, false);
v_pool_won := COALESCE((v_pool_result->>'won')::boolean, false);
v_pool_amount := COALESCE((v_pool_result->>'amount')::numeric, 0);

IF v_pool_won AND v_pool_amount > 0 THEN
v_message_body := v_message_body || E'\n\n*** BONUS! Tu expedicion encontro parte del Pool de Expediciones! ***\n' ||
'Ganaste ' || floor(v_pool_amount)::text || ' FXU adicionales!';
END IF;
END IF;

INSERT INTO messages (sender_id, recipient_id, subject, body, message_type)
VALUES (NULL, v_user_id, v_message_subject, v_message_body, 'expedition');

RETURN jsonb_build_object(
'success', true,
'event_type', v_event_type,
'metal', v_metal_reward,
'crystal', v_crystal_reward,
'deuterium', v_deuterium_reward,
'dark_matter', v_dark_matter_reward,
'fxu_reward', v_fxu_reward,
'ships_found', v_ships_found,
'ships_lost', v_ships_lost,
'fleet_lost', v_fleet_lost,
'partial_loss', v_partial_loss,
'loss_percent', v_loss_percent,
'pool_won', v_pool_won,
'pool_amount', v_pool_amount,
'cargo_was_full', v_cargo_full
);
END;
$$;


--
-- TOC entry 589 (class 1255 OID 18289)
-- Name: process_fleet_arrival(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_fleet_arrival(p_fleet_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  fleet_record RECORD;
  target_planet RECORD;
  ship_record RECORD;
  total_cargo_capacity INTEGER;
  loot_metal NUMERIC;
  loot_crystal NUMERIC;
  loot_deuterium NUMERIC;
  combat_result jsonb;
  v_unit jsonb;
  v_debris_metal NUMERIC := 0;
  v_debris_crystal NUMERIC := 0;
  v_dark_matter_found INTEGER := 0;
  v_expedition_message TEXT;
  v_attacker_units_report TEXT;
  v_defender_units_report TEXT;
  v_all_acs_fleets_arrived BOOLEAN;
  v_expedition_result jsonb;
  v_colony_stats RECORD;
  v_colonization_success BOOLEAN := false;
  -- Fortress variables
  v_fortress_ships jsonb;
  v_fortress_alliance uuid;
  v_fortress_result jsonb;
  v_fortress_ship record;
  v_fortress_msg text;
  v_fortress_i integer;
  v_fortress_j integer;
  v_fortress_name text;
  v_fortress_init_qty integer;
  v_fortress_rem_qty integer;
  v_fortress_lost integer;
  v_fortress_combat jsonb;
  v_fortress_rounds integer;
  v_fortress_debris_m numeric;
  v_fortress_debris_c numeric;
  v_fortress_result_text text;
  v_fortress_att_init jsonb;
  v_fortress_def_init jsonb;
  v_fortress_att_rem jsonb;
  v_fortress_def_rem jsonb;
  v_fortress_u jsonb;
  v_fortress_ru jsonb;
  v_fortress_def_ally_id uuid;
  v_fortress_def_member record;
BEGIN
  -- Load fleet record
  SELECT * INTO fleet_record FROM fleets WHERE id = p_fleet_id AND is_completed = false;
  IF NOT FOUND THEN RETURN; END IF;

  -- ========================================================================
  -- FORTRESS CHECK
  -- ========================================================================
  IF NOT fleet_record.is_returning AND fleet_record.target_system = 250 AND fleet_record.target_position = 8 AND
     fleet_record.mission_type IN ('attack', 'destroy', 'deploy', 'transport') THEN
    
    -- Get attacker ships
    SELECT COALESCE(jsonb_agg(jsonb_build_object('ship_type_id', fs.ship_type_id, 'quantity', fs.quantity)), '[]'::jsonb)
    INTO v_fortress_ships FROM fleet_ships fs WHERE fs.fleet_id = p_fleet_id;
    
    -- Get attacker alliance
    SELECT alliance_id INTO v_fortress_alliance FROM alliance_members WHERE user_id = fleet_record.user_id LIMIT 1;
    
    -- Deploy/transport to own alliance fortress: add ships directly
    IF fleet_record.mission_type IN ('deploy', 'transport') THEN
      IF EXISTS (SELECT 1 FROM alliance_members am JOIN alliance_fortresses af ON af.owner_alliance_id = am.alliance_id WHERE am.user_id = fleet_record.user_id AND af.galaxy = fleet_record.target_galaxy) THEN
        FOR v_fortress_ship IN SELECT * FROM fleet_ships WHERE fleet_id = p_fleet_id LOOP
          INSERT INTO fortress_ships (fortress_id, user_id, alliance_id, ship_type_id, quantity)
          SELECT af.id, fleet_record.user_id, af.owner_alliance_id, v_fortress_ship.ship_type_id, v_fortress_ship.quantity
          FROM alliance_fortresses af WHERE af.galaxy = fleet_record.target_galaxy;
        END LOOP;
        DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id;
        UPDATE fleets SET is_completed = true WHERE id = p_fleet_id;
        INSERT INTO messages (recipient_id, sender_id, subject, body, created_at)
        VALUES (fleet_record.user_id, NULL, 'Refuerzo Enviado', 'Tus naves se han sumado a la defensa de la fortaleza en Galaxia ' || fleet_record.target_galaxy, now());
        RETURN;
      END IF;
    END IF;
    
    -- Save defender alliance BEFORE combat (ownership may change on capture)
    SELECT owner_alliance_id INTO v_fortress_def_ally_id FROM alliance_fortresses WHERE galaxy = fleet_record.target_galaxy;
    
    -- Execute fortress combat
    v_fortress_result := resolve_fortress_attack(fleet_record.target_galaxy, fleet_record.user_id, v_fortress_alliance, v_fortress_ships);
    
    -- Check if fortress attack was rejected (e.g., no alliance)
    IF (v_fortress_result->>'success')::boolean = false THEN
      INSERT INTO messages (recipient_id, sender_id, subject, body, message_type, created_at)
      VALUES (fleet_record.user_id, NULL, 'Ataque a Fortaleza',
        'Tu flota llego a [' || fleet_record.target_galaxy || ':' || fleet_record.target_system || ':' || fleet_record.target_position || '] pero no pudo atacar la fortaleza. ' || COALESCE(v_fortress_result->>'error', 'Error desconocido.') || E'

La flota regresa a tu planeta.',
        'battle', now());
      UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
      RETURN;
    END IF;

    -- Build detailed combat report
    v_fortress_combat := v_fortress_result->'combat';
    v_fortress_msg := '';
    
    IF v_fortress_combat IS NOT NULL THEN
      v_fortress_rounds := 0;
      IF v_fortress_combat->'rounds_data' IS NOT NULL THEN
        v_fortress_rounds := jsonb_array_length(v_fortress_combat->'rounds_data');
      END IF;
      
      v_fortress_debris_m := COALESCE((v_fortress_combat->>'debris_metal')::numeric, 0);
      v_fortress_debris_c := COALESCE((v_fortress_combat->>'debris_crystal')::numeric, 0);
      v_fortress_result_text := CASE WHEN (v_fortress_result->>'result') = 'captured' THEN 'VICTORIA ATACANTE' WHEN (v_fortress_result->>'result') = 'draw' THEN 'EMPATE' ELSE 'VICTORIA DEFENSOR' END;
      v_fortress_att_init := v_fortress_combat->'attacker_initial';
      v_fortress_def_init := v_fortress_combat->'defender_initial';
      v_fortress_att_rem := v_fortress_combat->'attacker_remaining';
      v_fortress_def_rem := v_fortress_combat->'defender_remaining';
      
      -- Header
      v_fortress_msg := 'Combate en [' || fleet_record.target_galaxy || ':' || fleet_record.target_system || ':' || fleet_record.target_position || ']' || E'

';
      v_fortress_msg := v_fortress_msg || 'Resultado: ' || v_fortress_result_text || E'
';
      v_fortress_msg := v_fortress_msg || 'Rondas: ' || v_fortress_rounds || E'

';
      
      -- Attacker units
      IF v_fortress_att_init IS NOT NULL AND jsonb_array_length(v_fortress_att_init) > 0 THEN
        v_fortress_msg := v_fortress_msg || '--- Unidades Atacante ---' || E'
';
        v_fortress_i := 0;
        WHILE v_fortress_i < jsonb_array_length(v_fortress_att_init) LOOP
          v_fortress_u := v_fortress_att_init->v_fortress_i;
          v_fortress_name := COALESCE(v_fortress_u->>'name', 'Nave');
          v_fortress_init_qty := COALESCE((v_fortress_u->>'quantity')::integer, 0);
          v_fortress_rem_qty := 0;
          
          IF v_fortress_att_rem IS NOT NULL THEN
            v_fortress_j := 0;
            WHILE v_fortress_j < jsonb_array_length(v_fortress_att_rem) LOOP
              v_fortress_ru := v_fortress_att_rem->v_fortress_j;
              IF (v_fortress_ru->>'type_id')::integer = (v_fortress_u->>'type_id')::integer THEN
                v_fortress_rem_qty := COALESCE((v_fortress_ru->>'quantity')::integer, 0);
                EXIT;
              END IF;
              v_fortress_j := v_fortress_j + 1;
            END LOOP;
          END IF;
          
          v_fortress_lost := v_fortress_init_qty - v_fortress_rem_qty;
          IF v_fortress_lost > 0 THEN
            v_fortress_msg := v_fortress_msg || v_fortress_name || ': ' || v_fortress_init_qty || ' -> ' || v_fortress_rem_qty || ' (-' || v_fortress_lost || ')' || E'
';
          ELSE
            v_fortress_msg := v_fortress_msg || v_fortress_name || ': ' || v_fortress_init_qty || ' (sin perdidas)' || E'
';
          END IF;
          v_fortress_i := v_fortress_i + 1;
        END LOOP;
        v_fortress_msg := v_fortress_msg || E'
';
      END IF;
      
      -- Defender units
      IF v_fortress_def_init IS NOT NULL AND jsonb_array_length(v_fortress_def_init) > 0 THEN
        v_fortress_msg := v_fortress_msg || '--- Unidades Defensor ---' || E'
';
        v_fortress_i := 0;
        WHILE v_fortress_i < jsonb_array_length(v_fortress_def_init) LOOP
          v_fortress_u := v_fortress_def_init->v_fortress_i;
          v_fortress_name := COALESCE(v_fortress_u->>'name', 'Nave');
          v_fortress_init_qty := COALESCE((v_fortress_u->>'quantity')::integer, 0);
          v_fortress_rem_qty := 0;
          
          IF v_fortress_def_rem IS NOT NULL THEN
            v_fortress_j := 0;
            WHILE v_fortress_j < jsonb_array_length(v_fortress_def_rem) LOOP
              v_fortress_ru := v_fortress_def_rem->v_fortress_j;
              IF (v_fortress_ru->>'type_id')::integer = (v_fortress_u->>'type_id')::integer THEN
                v_fortress_rem_qty := COALESCE((v_fortress_ru->>'quantity')::integer, 0);
                EXIT;
              END IF;
              v_fortress_j := v_fortress_j + 1;
            END LOOP;
          END IF;
          
          v_fortress_lost := v_fortress_init_qty - v_fortress_rem_qty;
          IF v_fortress_lost > 0 THEN
            v_fortress_msg := v_fortress_msg || v_fortress_name || ': ' || v_fortress_init_qty || ' -> ' || v_fortress_rem_qty || ' (-' || v_fortress_lost || ' destruidas)' || E'
';
          ELSE
            v_fortress_msg := v_fortress_msg || v_fortress_name || ': ' || v_fortress_init_qty || ' (sin perdidas)' || E'
';
          END IF;
          v_fortress_i := v_fortress_i + 1;
        END LOOP;
        v_fortress_msg := v_fortress_msg || E'
';
      END IF;
      
      -- Debris
      IF v_fortress_debris_m > 0 OR v_fortress_debris_c > 0 THEN
        v_fortress_msg := v_fortress_msg || 'Escombros generados: ' || floor(v_fortress_debris_m) || ' Metal, ' || floor(v_fortress_debris_c) || ' Cristal' || E'

';
      END IF;
      
      -- Footer
      IF (v_fortress_result->>'result') = 'captured' THEN
        v_fortress_msg := v_fortress_msg || 'La fortaleza ha sido capturada!';
      ELSIF (v_fortress_result->>'result') = 'won_no_claim' THEN
        v_fortress_msg := v_fortress_msg || 'Ganaste el combate pero necesitas una alianza para reclamar la fortaleza.';
      ELSIF (v_fortress_result->>'result') = 'draw' THEN
        v_fortress_msg := v_fortress_msg || 'Empate tactico. La fortaleza mantiene su dueño.';
      ELSE
        v_fortress_msg := v_fortress_msg || 'La fortaleza resistio el ataque.';
      END IF;
    ELSE
      v_fortress_msg := COALESCE(v_fortress_result->>'message', 'Combate finalizado.');
    END IF;
    
    -- Send to ATTACKER
    INSERT INTO messages (recipient_id, sender_id, subject, body, message_type, created_at)
    VALUES (fleet_record.user_id, NULL,
      CASE WHEN (v_fortress_result->>'result') = 'captured' THEN 'Fortaleza Capturada!' WHEN (v_fortress_result->>'result') = 'won_no_claim' THEN 'Victoria en Fortaleza (Sin Alianza)' WHEN (v_fortress_result->>'result') = 'draw' THEN 'Ataque a Fortaleza (Empate)' ELSE 'Ataque a Fortaleza' END,
      v_fortress_msg, 'battle', now());
    
    -- Send to DEFENDER alliance (v_fortress_def_ally_id captured before combat)
    -- Flip result perspective for defender: attacker victory = defender defeat
    v_fortress_msg := replace(v_fortress_msg, 'Resultado: VICTORIA ATACANTE', 'Resultado: DERROTA');
    v_fortress_msg := replace(v_fortress_msg, 'Resultado: VICTORIA DEFENSOR', 'Resultado: VICTORIA');
    v_fortress_msg := replace(v_fortress_msg, 'La fortaleza ha sido capturada!', '¡Tu fortaleza ha sido conquistada!');
    IF v_fortress_def_ally_id IS NOT NULL AND v_fortress_alliance IS NOT NULL AND v_fortress_def_ally_id != v_fortress_alliance THEN
      FOR v_fortress_def_member IN SELECT user_id FROM alliance_members WHERE alliance_id = v_fortress_def_ally_id LOOP
        INSERT INTO messages (recipient_id, sender_id, subject, body, message_type, created_at)
        VALUES (v_fortress_def_member.user_id, NULL,
          CASE WHEN (v_fortress_result->>'result') = 'captured' THEN 'Fortaleza Perdida!' WHEN (v_fortress_result->>'result') = 'draw' THEN 'Fortaleza Defendida (Empate)' ELSE 'Fortaleza Defendida' END,
          v_fortress_msg, 'battle', now());
      END LOOP;
    END IF;
    
    -- NOTE: resolve_fortress_attack already handles fortress_ships insertion
    -- (clear + insert for capture, adjust for draw/defeat, add for reinforce)
    -- Do NOT duplicate here or ships get counted twice
    
    DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id;
    UPDATE fleets SET is_completed = true WHERE id = p_fleet_id;
    RETURN;
  END IF;
  -- END FORTRESS CHECK

  -- Continue with normal fleet processing (for non-fortress targets)
  IF fleet_record.arrival_time > NOW() AND NOT fleet_record.is_returning THEN RETURN; END IF;
  IF fleet_record.is_returning AND fleet_record.return_time > NOW() THEN RETURN; END IF;

  IF fleet_record.is_returning THEN
    FOR ship_record IN SELECT fs.ship_type_id, fs.quantity FROM fleet_ships fs WHERE fs.fleet_id = p_fleet_id LOOP
      INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
      VALUES (fleet_record.origin_planet_id, ship_record.ship_type_id, ship_record.quantity)
      ON CONFLICT (planet_id, ship_type_id) DO UPDATE SET quantity = planet_ships.quantity + EXCLUDED.quantity;
    END LOOP;
    UPDATE planet_resources SET metal = metal + fleet_record.cargo_metal, crystal = crystal + fleet_record.cargo_crystal, deuterium = deuterium + fleet_record.cargo_deuterium WHERE planet_id = fleet_record.origin_planet_id;
    DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id;
    UPDATE fleets SET is_completed = true WHERE id = p_fleet_id;
    RETURN;
  END IF;

  -- Handle other mission types (espionage, transport, deploy, recycle, expedition, colonize, attack)
  CASE fleet_record.mission_type
  WHEN 'espionage' THEN
    SELECT p.* INTO target_planet FROM planets p WHERE p.galaxy = fleet_record.target_galaxy AND p.solar_system = fleet_record.target_system AND p.position = fleet_record.target_position AND p.planet_type = 'planet';
    IF FOUND AND target_planet.user_id IS NOT NULL THEN
      PERFORM generate_espionage_report(fleet_record.user_id, target_planet.id, target_planet.user_id);
    END IF;
    UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
  WHEN 'transport' THEN
    SELECT p.* INTO target_planet FROM planets p WHERE p.galaxy = fleet_record.target_galaxy AND p.solar_system = fleet_record.target_system AND p.position = fleet_record.target_position;
    IF FOUND THEN
      UPDATE planet_resources SET metal = metal + fleet_record.cargo_metal, crystal = crystal + fleet_record.cargo_crystal, deuterium = deuterium + fleet_record.cargo_deuterium WHERE planet_id = target_planet.id;
      UPDATE fleets SET cargo_metal = 0, cargo_crystal = 0, cargo_deuterium = 0, is_returning = true WHERE id = p_fleet_id;
    ELSE
      UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
    END IF;
  WHEN 'deploy' THEN
    -- Try own planet first (ships + resources)
    SELECT p.* INTO target_planet FROM planets p WHERE p.galaxy = fleet_record.target_galaxy AND p.solar_system = fleet_record.target_system AND p.position = fleet_record.target_position AND p.user_id = fleet_record.user_id;
    IF FOUND THEN
      FOR ship_record IN SELECT fs.ship_type_id, fs.quantity FROM fleet_ships fs WHERE fs.fleet_id = p_fleet_id LOOP
        INSERT INTO planet_ships (planet_id, ship_type_id, quantity) VALUES (target_planet.id, ship_record.ship_type_id, ship_record.quantity) ON CONFLICT (planet_id, ship_type_id) DO UPDATE SET quantity = planet_ships.quantity + EXCLUDED.quantity;
      END LOOP;
      UPDATE planet_resources SET metal = metal + fleet_record.cargo_metal, crystal = crystal + fleet_record.cargo_crystal, deuterium = deuterium + fleet_record.cargo_deuterium WHERE planet_id = target_planet.id;
      DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id;
      UPDATE fleets SET is_completed = true WHERE id = p_fleet_id;
    ELSE
      -- Try alliance depot (ships ONLY, resources are NOT transferred)
      SELECT p.* INTO target_planet FROM planets p WHERE p.galaxy = fleet_record.target_galaxy AND p.solar_system = fleet_record.target_system AND p.position = fleet_record.target_position;
      IF FOUND AND EXISTS (
        SELECT 1 FROM alliance_members am1 JOIN alliance_members am2 ON am2.alliance_id = am1.alliance_id
        WHERE am1.user_id = fleet_record.user_id AND am2.user_id = target_planet.user_id
      ) THEN
        FOR ship_record IN SELECT fs.ship_type_id, fs.quantity FROM fleet_ships fs WHERE fs.fleet_id = p_fleet_id LOOP
          INSERT INTO planet_ships (planet_id, ship_type_id, quantity) VALUES (target_planet.id, ship_record.ship_type_id, ship_record.quantity) ON CONFLICT (planet_id, ship_type_id) DO UPDATE SET quantity = planet_ships.quantity + EXCLUDED.quantity;
        END LOOP;
        DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id;
        UPDATE fleets SET is_completed = true, cargo_metal = 0, cargo_crystal = 0, cargo_deuterium = 0 WHERE id = p_fleet_id;
      ELSE
        UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
      END IF;
    END IF;
  WHEN 'recycle' THEN
    DECLARE
      debris RECORD;
      recycler_capacity INTEGER;
      collected_metal NUMERIC;
      collected_crystal NUMERIC;
    BEGIN
      SELECT * INTO debris FROM debris_fields WHERE galaxy = fleet_record.target_galaxy AND solar_system = fleet_record.target_system AND position = fleet_record.target_position;
      IF FOUND AND (debris.metal > 0 OR debris.crystal > 0) THEN
        SELECT COALESCE(SUM(fs.quantity * st.cargo_capacity), 0) INTO recycler_capacity FROM fleet_ships fs JOIN ship_types st ON fs.ship_type_id = st.id WHERE fs.fleet_id = p_fleet_id AND st.code = 'recycler';
        collected_metal := LEAST(debris.metal, recycler_capacity / 2);
        collected_crystal := LEAST(debris.crystal, recycler_capacity / 2);
        UPDATE debris_fields SET metal = metal - collected_metal, crystal = crystal - collected_crystal, updated_at = NOW() WHERE id = debris.id;
        DELETE FROM debris_fields WHERE id = debris.id AND metal <= 0 AND crystal <= 0;
        UPDATE fleets SET cargo_metal = cargo_metal + collected_metal, cargo_crystal = cargo_crystal + collected_crystal, is_returning = true WHERE id = p_fleet_id;
      ELSE
        UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
      END IF;
    END;
  WHEN 'expedition' THEN
    -- Simplified expedition
    UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
  WHEN 'colonize' THEN
    SELECT p.* INTO target_planet FROM planets p WHERE p.galaxy = fleet_record.target_galaxy AND p.solar_system = fleet_record.target_system AND p.position = fleet_record.target_position;
    IF NOT FOUND THEN
    DECLARE
    colony_ship_type_id INTEGER;
    has_colony_ship BOOLEAN;
    new_planet_id uuid;
    v_colony_ship_quantity INTEGER;
    v_cargo_metal NUMERIC;
    v_cargo_crystal NUMERIC;
    v_cargo_deuterium NUMERIC;
    v_remaining_ships INTEGER;
    v_current_colonies INTEGER;
    v_astrophysics_level INTEGER;
    v_max_colonies INTEGER;
    BEGIN
    SELECT COUNT(*) INTO v_current_colonies FROM planets WHERE user_id = fleet_record.user_id AND NOT is_destroyed;
    SELECT COALESCE(ut.level, 0) INTO v_astrophysics_level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id = tt.id WHERE ut.user_id = fleet_record.user_id AND tt.code = 'astrophysics';
    v_max_colonies := 1 + FLOOR((COALESCE(v_astrophysics_level, 0) + 1) / 2);
    IF v_current_colonies >= v_max_colonies THEN
      UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
      RETURN;
    END IF;
    SELECT id INTO colony_ship_type_id FROM ship_types WHERE code = 'colony_ship';
    SELECT quantity INTO v_colony_ship_quantity FROM fleet_ships WHERE fleet_id = p_fleet_id AND ship_type_id = colony_ship_type_id;
    has_colony_ship := COALESCE(v_colony_ship_quantity, 0) > 0;
    IF has_colony_ship THEN
    v_cargo_metal := COALESCE(fleet_record.cargo_metal, 0);
    v_cargo_crystal := COALESCE(fleet_record.cargo_crystal, 0);
    v_cargo_deuterium := COALESCE(fleet_record.cargo_deuterium, 0);
    INSERT INTO planets (user_id, name, galaxy, solar_system, position, planet_type, is_main_planet, diameter, fields_max, temp_min, temp_max)
    VALUES (fleet_record.user_id, 'Colonia', fleet_record.target_galaxy, fleet_record.target_system, fleet_record.target_position,
    'planet', false, 12800 + floor(random() * 5000)::integer, 163 + floor(random() * 50)::integer,
    -20 + floor(random() * 40)::integer, 20 + floor(random() * 60)::integer)
    RETURNING id INTO new_planet_id;
    INSERT INTO planet_resources (planet_id, metal, crystal, deuterium, metal_per_hour, crystal_per_hour, deuterium_per_hour)
    VALUES (new_planet_id, 500 + v_cargo_metal, 500 + v_cargo_crystal, v_cargo_deuterium, 30, 15, 0);
    IF v_colony_ship_quantity = 1 THEN
    DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id AND ship_type_id = colony_ship_type_id;
    ELSE
    UPDATE fleet_ships SET quantity = quantity - 1 WHERE fleet_id = p_fleet_id AND ship_type_id = colony_ship_type_id;
    END IF;
    UPDATE fleets SET cargo_metal = 0, cargo_crystal = 0, cargo_deuterium = 0 WHERE id = p_fleet_id;
    v_colonization_success := true;
    SELECT COALESCE(SUM(quantity), 0) INTO v_remaining_ships FROM fleet_ships WHERE fleet_id = p_fleet_id;
    IF v_remaining_ships > 0 THEN
    UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
    ELSE
    DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id;
    UPDATE fleets SET is_completed = true WHERE id = p_fleet_id;
    END IF;
    END IF;
    END;
    END IF;
    IF NOT v_colonization_success THEN
    UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
    END IF;
  WHEN 'attack' THEN
    SELECT p.* INTO target_planet FROM planets p WHERE p.galaxy = fleet_record.target_galaxy AND p.solar_system = fleet_record.target_system AND p.position = fleet_record.target_position;
    IF FOUND AND target_planet.user_id IS NOT NULL AND target_planet.user_id != fleet_record.user_id THEN
      combat_result := perform_combat(p_fleet_id, target_planet.id);
      v_attacker_units_report := format_unit_report(combat_result->'initial_attacker', combat_result->'attacker_remaining', 'attacker');
      v_defender_units_report := format_unit_report(combat_result->'initial_defender', combat_result->'defender_remaining', 'defender');
      IF (combat_result->>'result') = 'attacker_won' THEN
        SELECT COALESCE(SUM((unit->>'quantity')::integer * (SELECT cargo_capacity FROM ship_types WHERE id = (unit->>'type_id')::integer)), 0) INTO total_cargo_capacity FROM jsonb_array_elements(combat_result->'attacker_remaining') AS unit WHERE (unit->>'quantity')::integer > 0;
        SELECT lmt.looted_metal, lmt.looted_crystal, lmt.looted_deuterium INTO loot_metal, loot_crystal, loot_deuterium FROM planet_resources pr, calculate_loot(pr.metal, pr.crystal, pr.deuterium, total_cargo_capacity) AS lmt WHERE pr.planet_id = target_planet.id;
        UPDATE planet_resources SET metal = GREATEST(0, metal - loot_metal), crystal = GREATEST(0, crystal - loot_crystal), deuterium = GREATEST(0, deuterium - loot_deuterium) WHERE planet_id = target_planet.id;
        UPDATE fleets SET cargo_metal = cargo_metal + loot_metal, cargo_crystal = cargo_crystal + loot_crystal, cargo_deuterium = cargo_deuterium + loot_deuterium WHERE id = p_fleet_id;
        DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id;
        FOR v_unit IN SELECT * FROM jsonb_array_elements(combat_result->'attacker_remaining') LOOP IF (v_unit->>'quantity')::integer > 0 THEN INSERT INTO fleet_ships (fleet_id, ship_type_id, quantity) VALUES (p_fleet_id, (v_unit->>'type_id')::integer, (v_unit->>'quantity')::integer); END IF; END LOOP;
        FOR v_unit IN SELECT * FROM jsonb_array_elements(combat_result->'defender_remaining') LOOP IF NOT (v_unit->>'is_defense')::boolean THEN UPDATE planet_ships SET quantity = (v_unit->>'quantity')::integer WHERE planet_id = target_planet.id AND ship_type_id = (v_unit->>'type_id')::integer; END IF; END LOOP;
        FOR v_unit IN SELECT * FROM jsonb_array_elements(combat_result->'destroyed_defenses') LOOP DECLARE v_dq INTEGER := (v_unit->>'quantity')::integer; v_rq INTEGER := 0; v_i INTEGER; BEGIN FOR v_i IN 1..v_dq LOOP IF random() < 0.7 THEN v_rq := v_rq + 1; END IF; END LOOP; UPDATE planet_defenses SET quantity = GREATEST(0, quantity - v_dq + v_rq) WHERE planet_id = target_planet.id AND defense_type_id = (v_unit->>'defense_type_id')::integer; END; END LOOP;
        UPDATE profiles SET battles_won = battles_won + 1, units_destroyed = units_destroyed + COALESCE((combat_result->>'defender_losses_metal')::bigint / 1000, 0) WHERE id = fleet_record.user_id;
        UPDATE profiles SET battles_lost = battles_lost + 1, units_lost = units_lost + COALESCE((combat_result->>'defender_losses_metal')::bigint / 1000, 0) WHERE id = target_planet.user_id;
      ELSIF (combat_result->>'result') = 'defender_won' THEN
        DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id;
        FOR v_unit IN SELECT * FROM jsonb_array_elements(combat_result->'defender_remaining') LOOP IF (v_unit->>'is_defense')::boolean THEN UPDATE planet_defenses SET quantity = (v_unit->>'quantity')::integer WHERE planet_id = target_planet.id AND defense_type_id = (v_unit->>'type_id')::integer; ELSE UPDATE planet_ships SET quantity = (v_unit->>'quantity')::integer WHERE planet_id = target_planet.id AND ship_type_id = (v_unit->>'type_id')::integer; END IF; END LOOP;
        FOR v_unit IN SELECT * FROM jsonb_array_elements(combat_result->'destroyed_defenses') LOOP DECLARE v_dq INTEGER := (v_unit->>'quantity')::integer; v_rq INTEGER := 0; v_i INTEGER; BEGIN FOR v_i IN 1..v_dq LOOP IF random() < 0.7 THEN v_rq := v_rq + 1; END IF; END LOOP; UPDATE planet_defenses SET quantity = quantity + v_rq WHERE planet_id = target_planet.id AND defense_type_id = (v_unit->>'defense_type_id')::integer; END; END LOOP;
        UPDATE profiles SET battles_lost = battles_lost + 1 WHERE id = fleet_record.user_id;
        UPDATE profiles SET battles_won = battles_won + 1 WHERE id = target_planet.user_id;
        loot_metal := 0; loot_crystal := 0; loot_deuterium := 0;
      ELSE
        DELETE FROM fleet_ships WHERE fleet_id = p_fleet_id;
        FOR v_unit IN SELECT * FROM jsonb_array_elements(combat_result->'attacker_remaining') LOOP IF (v_unit->>'quantity')::integer > 0 THEN INSERT INTO fleet_ships (fleet_id, ship_type_id, quantity) VALUES (p_fleet_id, (v_unit->>'type_id')::integer, (v_unit->>'quantity')::integer); END IF; END LOOP;
        FOR v_unit IN SELECT * FROM jsonb_array_elements(combat_result->'defender_remaining') LOOP IF (v_unit->>'is_defense')::boolean THEN UPDATE planet_defenses SET quantity = (v_unit->>'quantity')::integer WHERE planet_id = target_planet.id AND defense_type_id = (v_unit->>'type_id')::integer; ELSE UPDATE planet_ships SET quantity = (v_unit->>'quantity')::integer WHERE planet_id = target_planet.id AND ship_type_id = (v_unit->>'type_id')::integer; END IF; END LOOP;
        UPDATE profiles SET battles_draw = battles_draw + 1 WHERE id = fleet_record.user_id;
        UPDATE profiles SET battles_draw = battles_draw + 1 WHERE id = target_planet.user_id;
        loot_metal := 0; loot_crystal := 0; loot_deuterium := 0;
      END IF;
      v_debris_metal := COALESCE((combat_result->>'debris_metal')::numeric, 0);
      v_debris_crystal := COALESCE((combat_result->>'debris_crystal')::numeric, 0);
      IF v_debris_metal > 0 OR v_debris_crystal > 0 THEN
        INSERT INTO debris_fields (galaxy, solar_system, position, metal, crystal) VALUES (fleet_record.target_galaxy, fleet_record.target_system, fleet_record.target_position, v_debris_metal, v_debris_crystal) ON CONFLICT (galaxy, solar_system, position) DO UPDATE SET metal = debris_fields.metal + EXCLUDED.metal, crystal = debris_fields.crystal + EXCLUDED.crystal, updated_at = NOW();
        UPDATE profiles SET debris_metal_total = debris_metal_total + v_debris_metal, debris_crystal_total = debris_crystal_total + v_debris_crystal WHERE id = fleet_record.user_id;
      END IF;
      INSERT INTO messages (sender_id, recipient_id, subject, body, message_type) VALUES (NULL, fleet_record.user_id, format('Reporte de Combate - %s', CASE (combat_result->>'result') WHEN 'attacker_won' THEN 'Victoria' WHEN 'defender_won' THEN 'Derrota' ELSE 'Empate' END), format(E'Combate en %s [%s:%s:%s]\nResultado: %s\nRondas: %s\n=== TUS FUERZAS ===\n%s\n=== FUERZAS ENEMIGAS ===\n%s\nBotin: %s Metal, %s Cristal, %s Deuterio\nEscombros: %s Metal, %s Cristal', target_planet.name, fleet_record.target_galaxy, fleet_record.target_system, fleet_record.target_position, CASE (combat_result->>'result') WHEN 'attacker_won' THEN 'VICTORIA' WHEN 'defender_won' THEN 'DERROTA' ELSE 'EMPATE' END, (combat_result->>'rounds'), v_attacker_units_report, v_defender_units_report, floor(COALESCE(loot_metal,0)), floor(COALESCE(loot_crystal,0)), floor(COALESCE(loot_deuterium,0)), floor(v_debris_metal), floor(v_debris_crystal)), 'battle');
      INSERT INTO messages (sender_id, recipient_id, subject, body, message_type) VALUES (NULL, target_planet.user_id, format('Tu planeta %s fue atacado - %s', target_planet.name, CASE (combat_result->>'result') WHEN 'attacker_won' THEN 'Derrota' WHEN 'defender_won' THEN 'Victoria' ELSE 'Empate' END), format(E'Tu planeta %s en [%s:%s:%s] fue atacado.\nResultado: %s\nRondas: %s\n=== TUS FUERZAS ===\n%s\n=== FUERZAS ATACANTES ===\n%s\nRecursos saqueados: %s Metal, %s Cristal, %s Deuterio\nEscombros: %s Metal, %s Cristal', target_planet.name, fleet_record.target_galaxy, fleet_record.target_system, fleet_record.target_position, CASE (combat_result->>'result') WHEN 'attacker_won' THEN 'DERROTA' WHEN 'defender_won' THEN 'VICTORIA' ELSE 'EMPATE' END, (combat_result->>'rounds'), v_defender_units_report, v_attacker_units_report, floor(COALESCE(loot_metal,0)), floor(COALESCE(loot_crystal,0)), floor(COALESCE(loot_deuterium,0)), floor(v_debris_metal), floor(v_debris_crystal)), 'battle');
      IF EXISTS (SELECT 1 FROM fleet_ships WHERE fleet_id = p_fleet_id AND quantity > 0) THEN
        UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
      ELSE
        UPDATE fleets SET is_completed = true WHERE id = p_fleet_id;
      END IF;
    ELSE
      UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
    END IF;
  ELSE
    UPDATE fleets SET is_returning = true WHERE id = p_fleet_id;
  END CASE;
END;
$$;


--
-- TOC entry 600 (class 1255 OID 18401)
-- Name: process_moon_destruction(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_moon_destruction(p_fleet_id uuid, p_target_moon_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
v_fleet record;
v_moon record;
v_deathstar_count integer;
v_destruction_chance integer;
v_fleet_loss_chance integer;
v_moon_destroyed boolean := false;
v_fleet_destroyed boolean := false;
v_moon_diameter integer;
BEGIN
SELECT * INTO v_fleet FROM public.fleets WHERE id = p_fleet_id;
SELECT * INTO v_moon FROM public.planets WHERE id = p_target_moon_id AND planet_type = 'moon';

IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'reason', 'Luna no encontrada');
END IF;

SELECT COALESCE(SUM(fs.quantity), 0) INTO v_deathstar_count
FROM public.fleet_ships fs
JOIN public.ship_types st ON fs.ship_type_id = st.id
WHERE fs.fleet_id = p_fleet_id AND st.code = 'deathstar';

IF v_deathstar_count = 0 THEN
RETURN jsonb_build_object('success', false, 'reason', 'Necesitas Estrellas de la Muerte');
END IF;

v_moon_diameter := v_moon.diameter;

v_destruction_chance := (100 - SQRT(v_moon_diameter)) * SQRT(v_deathstar_count);
v_destruction_chance := GREATEST(0, LEAST(100, v_destruction_chance));

v_fleet_loss_chance := SQRT(v_moon_diameter) / 2;
v_fleet_loss_chance := GREATEST(0, LEAST(100, v_fleet_loss_chance));

IF random() * 100 < v_destruction_chance THEN
v_moon_destroyed := true;

UPDATE public.planets SET is_destroyed = true WHERE id = p_target_moon_id;

INSERT INTO public.messages (sender_id, recipient_id, subject, body, message_type)
VALUES (
NULL,
v_moon.user_id,
'Tu luna ha sido destruida!',
format('Tu luna en [%s:%s:%s] ha sido destruida por una flota enemiga.',
v_moon.galaxy, v_moon.solar_system, v_moon.position),
'battle'
);
END IF;

IF random() * 100 < v_fleet_loss_chance THEN
v_fleet_destroyed := true;

DELETE FROM public.fleet_ships WHERE fleet_id = p_fleet_id;
UPDATE public.fleets SET is_completed = true WHERE id = p_fleet_id;

INSERT INTO public.messages (sender_id, recipient_id, subject, body, message_type)
VALUES (
NULL,
v_fleet.user_id,
'Tu flota fue destruida!',
format('Tu flota fue atrapada en la explosion de la luna en [%s:%s:%s].',
v_moon.galaxy, v_moon.solar_system, v_moon.position),
'battle'
);
END IF;

RETURN jsonb_build_object(
'success', true,
'moon_destroyed', v_moon_destroyed,
'fleet_destroyed', v_fleet_destroyed,
'destruction_chance', v_destruction_chance,
'fleet_loss_chance', v_fleet_loss_chance
);
END;
$$;


--
-- TOC entry 1105 (class 1255 OID 21704)
-- Name: process_next_shipyard_unit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_next_shipyard_unit(p_planet_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_queue_item RECORD;
  v_ship_type ship_types%ROWTYPE;
  v_defense_type defense_types%ROWTYPE;
  v_existing integer;
BEGIN
  -- Get the first pending/building item for this planet
  SELECT * INTO v_queue_item
  FROM shipyard_queue
  WHERE planet_id = p_planet_id
    AND quantity > quantity_completed
  ORDER BY queue_position ASC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN RETURN; END IF;

  BEGIN
    IF v_queue_item.item_type = 'ship' THEN
      SELECT * INTO v_ship_type FROM ship_types WHERE id = v_queue_item.ship_type_id;
      
      INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
      VALUES (p_planet_id, v_queue_item.ship_type_id, 1)
      ON CONFLICT (planet_id, ship_type_id)
      DO UPDATE SET quantity = planet_ships.quantity + 1;

    ELSIF v_queue_item.item_type = 'defense' THEN
      SELECT * INTO v_defense_type FROM defense_types WHERE id = v_queue_item.defense_type_id;
      
      INSERT INTO planet_defenses (planet_id, defense_type_id, quantity)
      VALUES (p_planet_id, v_queue_item.defense_type_id, 1)
      ON CONFLICT (planet_id, defense_type_id)
      DO UPDATE SET quantity = planet_defenses.quantity + 1;
    END IF;

    UPDATE shipyard_queue
    SET quantity_completed = quantity_completed + 1,
        current_unit_end_time = CASE 
          WHEN quantity_completed + 1 >= quantity THEN NULL 
          ELSE now() + (build_time_per_unit || ' seconds')::interval 
        END,
        start_time = now()
    WHERE id = v_queue_item.id;

  EXCEPTION WHEN OTHERS THEN
    -- Log the error and move on to next item
    RAISE WARNING 'Shipyard queue item % failed: %', v_queue_item.id, SQLERRM;
    
    -- Mark as failed by completing the remaining quantity
    UPDATE shipyard_queue
    SET quantity_completed = quantity
    WHERE id = v_queue_item.id;
  END;
END;
$$;


--
-- TOC entry 748 (class 1255 OID 19071)
-- Name: process_shipyard_queue_internal(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_shipyard_queue_internal(p_planet_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet_exists boolean;
  v_queue_item shipyard_queue%ROWTYPE;
  v_total_units_completed integer := 0;
  v_units_to_complete integer;
  v_elapsed_seconds numeric;
  v_time_per_unit numeric;
  v_max_iterations integer := 50;
  v_iteration integer := 0;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM planets WHERE id = p_planet_id AND user_id = p_user_id
  ) INTO v_planet_exists;

  IF NOT v_planet_exists THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not found');
  END IF;

  LOOP
    v_iteration := v_iteration + 1;
    IF v_iteration > v_max_iterations THEN
      EXIT;
    END IF;

    SELECT * INTO v_queue_item
    FROM shipyard_queue
    WHERE planet_id = p_planet_id
    ORDER BY queue_position
    LIMIT 1
    FOR UPDATE SKIP LOCKED;

    IF NOT FOUND THEN
      EXIT;
    END IF;

    -- Si el item activo aún no tiene start_time, inicializar desde AHORA.
    IF v_queue_item.start_time IS NULL THEN
      v_queue_item.start_time := NOW();
      UPDATE shipyard_queue
      SET start_time = v_queue_item.start_time,
          current_unit_end_time = v_queue_item.start_time
                                  + (build_time_per_unit || ' seconds')::interval
      WHERE id = v_queue_item.id;
    END IF;

    v_time_per_unit := v_queue_item.build_time_per_unit;
    IF v_time_per_unit <= 0 THEN
      v_time_per_unit := 1;
    END IF;

    v_elapsed_seconds := EXTRACT(EPOCH FROM (NOW() - v_queue_item.start_time));

    v_units_to_complete := LEAST(
      FLOOR(v_elapsed_seconds / v_time_per_unit)::integer
        - v_queue_item.quantity_completed,
      v_queue_item.quantity - v_queue_item.quantity_completed
    );

    IF v_units_to_complete <= 0 THEN
      EXIT;
    END IF;

    -- Insertar las unidades producidas
    -- (FIX adicional: la tabla usa ship_type_id/defense_type_id, no type_id)
    IF v_queue_item.item_type = 'ship' AND v_queue_item.ship_type_id IS NOT NULL THEN
      INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
      VALUES (p_planet_id, v_queue_item.ship_type_id, v_units_to_complete)
      ON CONFLICT (planet_id, ship_type_id)
      DO UPDATE SET quantity = planet_ships.quantity + v_units_to_complete;
    ELSIF v_queue_item.item_type = 'defense' AND v_queue_item.defense_type_id IS NOT NULL THEN
      INSERT INTO planet_defenses (planet_id, defense_type_id, quantity)
      VALUES (p_planet_id, v_queue_item.defense_type_id, v_units_to_complete)
      ON CONFLICT (planet_id, defense_type_id)
      DO UPDATE SET quantity = planet_defenses.quantity + v_units_to_complete;
    END IF;

    v_total_units_completed := v_total_units_completed + v_units_to_complete;

    IF v_queue_item.quantity_completed + v_units_to_complete
         >= v_queue_item.quantity
    THEN
      -- Item completado totalmente → eliminar y avanzar la cola
      DELETE FROM shipyard_queue WHERE id = v_queue_item.id;

      UPDATE shipyard_queue
      SET queue_position = queue_position - 1
      WHERE planet_id = p_planet_id
        AND queue_position > 1;

      -- ✅ FIX: el siguiente item arranca desde AHORA, no desde la hora
      --        pasada en que terminó el anterior. Así su tiempo de
      --        construcción se respeta íntegramente.
      UPDATE shipyard_queue
      SET start_time = NOW(),
          current_unit_end_time = NOW()
                                  + (build_time_per_unit || ' seconds')::interval
      WHERE planet_id = p_planet_id
        AND queue_position = 1
        AND start_time IS NULL;

      -- El siguiente ciclo del LOOP verá elapsed=0 → units_to_complete=0
      -- → EXIT natural. Solo cascadea si quedan items, no los completa.

    ELSE
      -- Avance parcial: actualizar progreso y siguiente unit_end_time
      UPDATE shipyard_queue
      SET quantity_completed = quantity_completed + v_units_to_complete,
          current_unit_end_time = v_queue_item.start_time
            + ((v_queue_item.quantity_completed + v_units_to_complete + 1)
               * v_time_per_unit || ' seconds')::interval
      WHERE id = v_queue_item.id;
      EXIT;
    END IF;

  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'completed_units', v_total_units_completed
  );
END;
$$;


--
-- TOC entry 7792 (class 0 OID 0)
-- Dependencies: 748
-- Name: FUNCTION process_shipyard_queue_internal(p_planet_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.process_shipyard_queue_internal(p_planet_id uuid, p_user_id uuid) IS 'Procesa la cola del astillero respetando build_time por unidad. Solo el item activo (posición 1) progresa con el tiempo offline; los items en cola arrancan desde NOW() cuando les toca. Fix aplicado 2026-05-01: evita que toda la cola se complete al reconectar.';


--
-- TOC entry 799 (class 1255 OID 19468)
-- Name: process_telegram_join(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_telegram_join(p_telegram_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_link telegram_links%ROWTYPE;
  v_reward telegram_task_rewards%ROWTYPE;
  v_reward_amount integer := 50;
  v_old_balance numeric;
  v_new_balance numeric;
BEGIN
  SELECT * INTO v_link FROM telegram_links WHERE telegram_id = p_telegram_id;

  IF v_link IS NULL OR v_link.user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Telegram account not linked to any game account'
    );
  END IF;

  SELECT * INTO v_reward 
  FROM telegram_task_rewards 
  WHERE telegram_id = p_telegram_id AND task_type = 'join_group';

  IF v_reward IS NULL THEN
    INSERT INTO telegram_task_rewards (
      user_id, telegram_id, task_type, reward_amount, 
      reward_claimed, first_join_at, is_member, updated_at
    )
    VALUES (
      v_link.user_id, p_telegram_id, 'join_group', v_reward_amount,
      true, now(), true, now()
    );

    PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
    UPDATE profiles SET fxu_balance = fxu_balance + v_reward_amount WHERE id = v_link.user_id;
    PERFORM set_config('fxu.allow_update_9x7k2m', 'false', true);

    RETURN jsonb_build_object(
      'success', true,
      'reward_given', true,
      'amount', v_reward_amount,
      'message', 'Welcome! You received ' || v_reward_amount || ' FXU!'
    );

  ELSE
    UPDATE telegram_task_rewards
    SET is_member = true,
        updated_at = now()
    WHERE id = v_reward.id;

    IF v_reward.reward_claimed AND v_reward.reward_revoked THEN
      SELECT fxu_balance INTO v_old_balance FROM profiles WHERE id = v_link.user_id;
      v_new_balance := v_old_balance + v_reward_amount;

      PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
      UPDATE profiles 
      SET fxu_balance = v_new_balance,
          updated_at = now()
      WHERE id = v_link.user_id;
      PERFORM set_config('fxu.allow_update_9x7k2m', 'false', true);

      UPDATE telegram_task_rewards
      SET reward_revoked = false,
          updated_at = now()
      WHERE id = v_reward.id;

      RETURN jsonb_build_object(
        'success', true,
        'reward_given', true,
        'reward_restored', true,
        'amount', v_reward_amount,
        'old_balance', v_old_balance,
        'new_balance', v_new_balance,
        'message', 'Welcome back! Your ' || v_reward_amount || ' FXU reward has been restored!'
      );
    ELSE
      RETURN jsonb_build_object(
        'success', true,
        'reward_given', false,
        'message', 'Welcome back!'
      );
    END IF;
  END IF;
END;
$$;


--
-- TOC entry 800 (class 1255 OID 19469)
-- Name: process_telegram_leave(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_telegram_leave(p_telegram_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reward telegram_task_rewards%ROWTYPE;
  v_link telegram_links%ROWTYPE;
  v_user_id uuid;
  v_old_balance numeric;
  v_new_balance numeric;
  v_reward_amount integer;
BEGIN
  -- Get reward record
  SELECT * INTO v_reward 
  FROM telegram_task_rewards 
  WHERE telegram_id = p_telegram_id AND task_type = 'join_group';

  IF v_reward IS NULL THEN
    RETURN jsonb_build_object('success', true, 'message', 'No reward record found');
  END IF;

  -- Get link to find user_id
  SELECT * INTO v_link FROM telegram_links WHERE telegram_id = p_telegram_id;
  
  IF v_link IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No linked account found');
  END IF;

  v_user_id := v_link.user_id;
  v_reward_amount := v_reward.reward_amount;

  -- Check if we need to revoke (reward was claimed and not already revoked)
  IF v_reward.reward_claimed AND NOT v_reward.reward_revoked THEN
    -- Get current balance
    SELECT fxu_balance INTO v_old_balance FROM profiles WHERE id = v_user_id;
    
    -- Calculate new balance (can go negative)
    v_new_balance := v_old_balance - v_reward_amount;
    
    -- Enable FXU update
    PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
    
    -- Deduct FXU (allows negative balance)
    UPDATE profiles 
    SET fxu_balance = v_new_balance,
        updated_at = now()
    WHERE id = v_user_id;
    
    -- Disable FXU update
    PERFORM set_config('fxu.allow_update_9x7k2m', 'false', true);
    
    -- Mark reward as revoked
    UPDATE telegram_task_rewards
    SET is_member = false,
        last_leave_at = now(),
        updated_at = now(),
        reward_revoked = true
    WHERE id = v_reward.id;

    RETURN jsonb_build_object(
      'success', true,
      'reward_revoked', true,
      'amount', v_reward_amount,
      'old_balance', v_old_balance,
      'new_balance', v_new_balance,
      'message', 'Reward revoked, FXU deducted'
    );
  END IF;

  -- Just update membership status (no revocation needed)
  UPDATE telegram_task_rewards
  SET is_member = false,
      last_leave_at = now(),
      updated_at = now()
  WHERE id = v_reward.id;

  RETURN jsonb_build_object(
    'success', true,
    'reward_revoked', false,
    'message', 'User left group, no revocation needed'
  );
END;
$$;


--
-- TOC entry 590 (class 1255 OID 18290)
-- Name: process_user_fleets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_user_fleets(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
fleet_record RECORD;
BEGIN
FOR fleet_record IN
SELECT id FROM public.fleets
WHERE user_id = p_user_id
AND is_completed = false
AND (
(is_returning = false AND arrival_time <= NOW())
OR (is_returning = true AND return_time <= NOW())
)
LOOP
PERFORM public.process_fleet_arrival(fleet_record.id);
END LOOP;
END;
$$;


--
-- TOC entry 621 (class 1255 OID 18554)
-- Name: process_user_pending_fleets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_user_pending_fleets(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fleet record;
  v_processed_count integer := 0;
  v_error_count integer := 0;
BEGIN
  FOR v_fleet IN
    SELECT id, arrival_time, return_time, is_returning
    FROM fleets
    WHERE user_id = p_user_id
    AND is_completed = false
    AND (
      (NOT is_returning AND arrival_time <= NOW()
        AND NOT (
          mission_type = 'deploy' 
          AND cargo_metal = 0 AND cargo_crystal = 0 AND cargo_deuterium = 0
          AND NOT EXISTS (
            SELECT 1 FROM planets p 
            WHERE p.user_id = fleets.user_id 
            AND p.galaxy = fleets.target_galaxy 
            AND p.solar_system = fleets.target_system 
            AND p.position = fleets.target_position
          )
        )
      )
      OR (is_returning AND return_time <= NOW())
    )
    ORDER BY
      CASE WHEN is_returning THEN return_time ELSE arrival_time END ASC
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      PERFORM process_fleet_arrival(v_fleet.id);
      v_processed_count := v_processed_count + 1;
    EXCEPTION WHEN OTHERS THEN
      v_error_count := v_error_count + 1;
      RAISE WARNING 'Error processing fleet % for user %: %', v_fleet.id, p_user_id, SQLERRM;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'processed_count', v_processed_count,
    'error_count', v_error_count
  );
END;
$$;


--
-- TOC entry 852 (class 1255 OID 20012)
-- Name: propose_diplomacy(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_diplomacy(p_target_alliance_id uuid, p_diplomacy_type text, p_message text DEFAULT NULL::text, p_duration_days integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_alliance_id uuid;
  v_can_edit boolean;
  v_existing record;
  v_diplomacy_id uuid;
  v_expires_at timestamptz;
  v_target_alliance record;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  -- Get user's alliance and permissions
  SELECT alliance_id, can_edit INTO v_user_alliance_id, v_can_edit
  FROM alliance_members
  WHERE user_id = v_user_id;
  
  IF v_user_alliance_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No estas en una alianza');
  END IF;
  
  IF NOT COALESCE(v_can_edit, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes permiso para gestionar diplomacia');
  END IF;
  
  -- Validate target alliance
  SELECT * INTO v_target_alliance FROM alliances WHERE id = p_target_alliance_id;
  IF v_target_alliance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Alianza objetivo no encontrada');
  END IF;
  
  IF v_user_alliance_id = p_target_alliance_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes hacer diplomacia con tu propia alianza');
  END IF;
  
  -- Check for existing active/pending diplomacy of same type
  SELECT * INTO v_existing
  FROM alliance_diplomacy
  WHERE ((alliance_id = v_user_alliance_id AND target_alliance_id = p_target_alliance_id)
         OR (alliance_id = p_target_alliance_id AND target_alliance_id = v_user_alliance_id))
    AND diplomacy_type = p_diplomacy_type
    AND status IN ('pending', 'active');
    
  IF v_existing IS NOT NULL THEN
    IF v_existing.status = 'pending' THEN
      RETURN jsonb_build_object('success', false, 'error', 'Ya existe una propuesta pendiente de este tipo');
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'Ya existe una relacion activa de este tipo');
    END IF;
  END IF;
  
  -- Calculate expiration if duration provided
  IF p_duration_days IS NOT NULL AND p_duration_days > 0 THEN
    v_expires_at := now() + (p_duration_days || ' days')::interval;
  END IF;
  
  -- Create diplomacy proposal
  INSERT INTO alliance_diplomacy (
    alliance_id, target_alliance_id, diplomacy_type, status, 
    proposed_by, message, expires_at
  ) VALUES (
    v_user_alliance_id, p_target_alliance_id, p_diplomacy_type, 
    CASE WHEN p_diplomacy_type = 'war' THEN 'active' ELSE 'pending' END,
    v_user_id, p_message, v_expires_at
  ) RETURNING id INTO v_diplomacy_id;
  
  -- Send notification to target alliance leader
  INSERT INTO messages (recipient_id, subject, body, message_type)
  SELECT 
    a.leader_id,
    CASE p_diplomacy_type
      WHEN 'nap' THEN 'Propuesta de Pacto de No Agresion'
      WHEN 'trade' THEN 'Propuesta de Pacto Comercial'
      WHEN 'war' THEN 'Declaracion de Guerra!'
    END,
    CASE p_diplomacy_type
      WHEN 'war' THEN 
        'La alianza ' || (SELECT name FROM alliances WHERE id = v_user_alliance_id) || 
        ' te ha declarado la guerra!' || 
        CASE WHEN p_message IS NOT NULL THEN E'\n\nMensaje: ' || p_message ELSE '' END
      ELSE
        'La alianza ' || (SELECT name FROM alliances WHERE id = v_user_alliance_id) || 
        ' te ha enviado una propuesta diplomatica.' ||
        CASE WHEN p_message IS NOT NULL THEN E'\n\nMensaje: ' || p_message ELSE '' END ||
        E'\n\nRevisa la seccion de Alianza > Diplomacia para responder.'
    END,
    'alliance'
  FROM alliances a
  WHERE a.id = p_target_alliance_id AND a.leader_id IS NOT NULL;
  
  RETURN jsonb_build_object(
    'success', true, 
    'diplomacy_id', v_diplomacy_id,
    'message', CASE p_diplomacy_type
      WHEN 'war' THEN 'Guerra declarada!'
      ELSE 'Propuesta enviada'
    END
  );
END;
$$;


--
-- TOC entry 1069 (class 1255 OID 21365)
-- Name: protect_alliance_members_sensitive_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_alliance_members_sensitive_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cu text := current_user;
  v_changed text;
BEGIN
  IF v_cu NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;
  IF current_setting('fxu.allow_update_9x7k2m', true) = 'true' THEN
    RETURN NEW;
  END IF;

  v_changed := NULL;
  IF NEW.user_id     IS DISTINCT FROM OLD.user_id     THEN v_changed := 'user_id'; END IF;
  IF v_changed IS NULL AND NEW.alliance_id IS DISTINCT FROM OLD.alliance_id THEN v_changed := 'alliance_id'; END IF;
  IF v_changed IS NULL AND NEW.joined_at   IS DISTINCT FROM OLD.joined_at   THEN v_changed := 'joined_at'; END IF;

  IF v_changed IS NOT NULL THEN
    RAISE EXCEPTION
      'SECURITY_VIOLATION: Direct modification of alliance_members.% is not allowed. Code: ALLY002',
      v_changed
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN NEW;
END;
$$;


