--
-- TOC entry 694 (class 1255 OID 18896)
-- Name: protect_fxu_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_fxu_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  DECLARE
    v_role text;
    v_context1 text;
    v_context2 text;
  BEGIN
    -- Only check if fxu_balance is being changed
    IF OLD.fxu_balance IS NOT DISTINCT FROM NEW.fxu_balance THEN
      RETURN NEW;
    END IF;

    -- Get current role
    v_role := current_setting('role', true);

    -- Allow service_role (edge functions with service key)
    IF v_role = 'service_role' THEN
      RETURN NEW;
    END IF;

    -- Check for legitimate context from our functions (both variable names)
    v_context1 := current_setting('app.fxu_update_allowed', true);
    v_context2 := current_setting('fxu.allow_update_9x7k2m', true);

    IF (v_context1 IS NOT NULL AND v_context1 != '') OR
       (v_context2 IS NOT NULL AND v_context2 = 'true') THEN
      RETURN NEW;
    END IF;

    -- Block direct updates from authenticated users
    IF v_role = 'authenticated' THEN
      RAISE EXCEPTION 'SECURITY_VIOLATION: Direct modification of fxu_balance is not allowed';
    END IF;

    RETURN NEW;
  END;
  $$;


--
-- TOC entry 1067 (class 1255 OID 21351)
-- Name: protect_game_table_full(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_game_table_full() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cu text := current_user;
BEGIN
  -- Bypass para roles no expuestos al cliente (postgres, service_role, etc.)
  IF v_cu NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  -- Bypass de emergencia compatible con el patrón existente.
  IF current_setting('fxu.allow_update_9x7k2m', true) = 'true' THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION
    'SECURITY_VIOLATION: Direct UPDATE on % from client is not allowed. Use the proper RPC. Code: GAME001',
    TG_TABLE_NAME
    USING ERRCODE = 'insufficient_privilege';
END;
$$;


