--
-- TOC entry 1124 (class 1255 OID 21909)
-- Name: purchase_blueprint_market_listing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_blueprint_market_listing(p_listing_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_buyer_id uuid;
  v_listing market_listings%ROWTYPE;
  v_escrow blueprint_market_escrow%ROWTYPE;
  v_buyer_balance numeric;
  v_fee numeric;
  v_seller_receive numeric;
  v_admin_id uuid;
  v_fee_admin_share numeric;
  v_fee_pool_share numeric;
BEGIN
  v_buyer_id := auth.uid();
  IF v_buyer_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_listing
  FROM market_listings
  WHERE id = p_listing_id
    AND status = 'active'
    AND listing_type = 'blueprint'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Listing no disponible');
  END IF;

  IF v_listing.seller_id = v_buyer_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes comprar tu propio listing');
  END IF;

  SELECT * INTO v_escrow
  FROM blueprint_market_escrow
  WHERE listing_id = p_listing_id
    AND delivered_at IS NULL
    AND returned_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Escrow de plano invalido');
  END IF;

  SELECT COALESCE(fxu_balance, 0) INTO v_buyer_balance
  FROM profiles
  WHERE id = v_buyer_id
  FOR UPDATE;

  IF v_buyer_balance < v_listing.total_price THEN
    RETURN jsonb_build_object('success', false, 'error', 'FXU insuficiente');
  END IF;

  v_fee := ROUND(v_listing.total_price * 0.05, 8);
  v_seller_receive := v_listing.total_price - v_fee;

  v_fee_pool_share  := ROUND(v_fee * 0.50, 8);
  v_fee_admin_share := v_fee - v_fee_pool_share;

  PERFORM _internal_set_fxu_context();

  UPDATE profiles
  SET fxu_balance = COALESCE(fxu_balance, 0) - v_listing.total_price
  WHERE id = v_buyer_id;

  UPDATE profiles
  SET fxu_balance = COALESCE(fxu_balance, 0) + v_seller_receive
  WHERE id = v_listing.seller_id;

  SELECT id INTO v_admin_id
  FROM profiles
  WHERE is_admin = true
  ORDER BY created_at ASC
  LIMIT 1;

  IF v_admin_id IS NOT NULL AND v_admin_id <> v_buyer_id AND v_fee_admin_share > 0 THEN
    UPDATE profiles
    SET fxu_balance = COALESCE(fxu_balance, 0) + v_fee_admin_share
    WHERE id = v_admin_id;
  END IF;

  IF v_fee_pool_share > 0 THEN
    PERFORM contribute_to_jackpot(
      v_fee_pool_share,
      'market_blueprint_fee:' || v_listing.item_code,
      v_buyer_id
    );
  END IF;

  INSERT INTO user_ship_blueprints (user_id, blueprint_id, source, metadata)
  VALUES (
    v_buyer_id,
    v_escrow.blueprint_id,
    'p2p',
    jsonb_build_object(
      'listing_id', p_listing_id,
      'price_fxu', v_listing.total_price,
      'fee', v_fee,
      'seller_received', v_seller_receive
    )
  );

  UPDATE blueprint_market_escrow
  SET delivered_at = now(), buyer_id = v_buyer_id
  WHERE listing_id = p_listing_id;

  UPDATE market_listings
  SET status = 'sold', updated_at = now()
  WHERE id = p_listing_id;

  INSERT INTO market_transactions (listing_id, buyer_id, seller_id, item_type, item_code, quantity, total_price)
  VALUES (p_listing_id, v_buyer_id, v_listing.seller_id, 'blueprint', v_listing.item_code, 1, v_listing.total_price);

  PERFORM record_admin_revenue(
    'market_fee',
    v_fee_admin_share,
    'market_blueprint_fee (50% admin): ' || v_listing.item_code,
    v_buyer_id,
    p_listing_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Plano comprado exitosamente',
    'quantity_added', 1,
    'price', v_listing.total_price,
    'fee', v_fee,
    'fee_admin_share', v_fee_admin_share,
    'fee_pool_share', v_fee_pool_share,
    'seller_received', v_seller_receive
  );
END;
$$;


--
-- TOC entry 1117 (class 1255 OID 21812)
-- Name: purchase_cosmetic(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_cosmetic(p_cosmetic_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_item cosmetic_items%ROWTYPE;
  v_balance numeric;
  v_expires timestamptz;
  v_purchase_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_item FROM cosmetic_items WHERE id = p_cosmetic_id AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cosmético no encontrado');
  END IF;

  SELECT COALESCE(fxu_balance, 0) INTO v_balance FROM profiles WHERE id = v_user_id;
  IF v_balance < v_item.fxu_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'FXU insuficiente. Necesitas ' || v_item.fxu_cost || ' FXU, tienes ' || FLOOR(v_balance));
  END IF;

  -- Ya tiene este cosmético activo? renovar en vez de duplicar
  UPDATE user_cosmetics
  SET expires_at = expires_at + (v_item.duration_days || ' days')::interval
  WHERE user_id = v_user_id AND cosmetic_id = p_cosmetic_id AND expires_at > now() AND equipped = true
  RETURNING id INTO v_purchase_id;

  IF FOUND THEN
    PERFORM _internal_set_fxu_context();
    UPDATE profiles SET fxu_balance = fxu_balance - v_item.fxu_cost WHERE id = v_user_id;
    PERFORM record_admin_revenue('cosmetic_renewal', v_item.fxu_cost, 'Renew: ' || v_item.name_es, v_user_id, NULL);
    RETURN jsonb_build_object('success', true, 'message', 'Renovado hasta ' || (v_expires + (v_item.duration_days || ' days')::interval)::text, 'cost', v_item.fxu_cost, 'renewal', true);
  END IF;

  -- Nueva compra
  v_expires := now() + (v_item.duration_days || ' days')::interval;

  -- Cobrar
  PERFORM _internal_set_fxu_context();
  UPDATE profiles SET fxu_balance = fxu_balance - v_item.fxu_cost WHERE id = v_user_id;
  PERFORM record_admin_revenue('cosmetic_' || v_item.cosmetic_type, v_item.fxu_cost, 'Purchase: ' || v_item.name_es, v_user_id, NULL);

  INSERT INTO user_cosmetics (user_id, cosmetic_id, purchased_at, expires_at, equipped)
  VALUES (v_user_id, p_cosmetic_id, now(), v_expires, false)
  RETURNING id INTO v_purchase_id;

  RETURN jsonb_build_object('success', true, 'message', '¡' || v_item.name_es || ' adquirido! ', 'expires_at', v_expires, 'cost', v_item.fxu_cost);
END;
$$;


--
-- TOC entry 1084 (class 1255 OID 21492)
-- Name: purchase_daily_mission_bonus(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_daily_mission_bonus(p_user_id uuid, p_mission_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
    v_mission record;
    v_fxu_balance numeric;
    v_bonus_id uuid;
    v_existing integer;
  BEGIN
    SELECT * INTO v_mission
    FROM daily_missions
    WHERE id = p_mission_id AND cost_fxu > 0 AND is_active = true;

    IF v_mission IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Mision premium no encontrada');
    END IF;

    SELECT COUNT(*) INTO v_existing
    FROM user_active_bonuses
    WHERE user_id = p_user_id AND mission_id = p_mission_id AND expires_at > now();

    IF v_existing > 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Ya tienes este bono activo. Espera a que expire.');
    END IF;

    SELECT fxu_balance INTO v_fxu_balance
    FROM profiles WHERE id = p_user_id FOR UPDATE;

    IF v_fxu_balance < v_mission.cost_fxu THEN
      RETURN jsonb_build_object('success', false, 'error', 'FXU insuficientes. Necesitas ' || v_mission.cost_fxu || ' FXU');
    END IF;

    PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
    UPDATE profiles SET fxu_balance = fxu_balance - v_mission.cost_fxu WHERE id = p_user_id;

    INSERT INTO user_active_bonuses (user_id, mission_id, bonus_type, bonus_value, expires_at)
    VALUES (p_user_id, p_mission_id, v_mission.reward_type, v_mission.reward_value, now() + (v_mission.reward_duration_hours || ' hours')::interval)
    RETURNING id INTO v_bonus_id;

    RETURN jsonb_build_object(
      'success', true,
      'bonus_type', v_mission.reward_type,
      'bonus_value', v_mission.reward_value,
      'expires_at', now() + (v_mission.reward_duration_hours || ' hours')::interval,
      'cost_fxu', v_mission.cost_fxu
    );
  END;
  $$;


--
-- TOC entry 699 (class 1255 OID 18902)
-- Name: purchase_market_listing(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_market_listing(p_listing_id uuid, p_quantity integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id uuid;
  v_listing RECORD;
  v_buyer_planet_id uuid;
  v_purchase_qty integer;
  v_total_price numeric;
  v_buyer_fxu numeric;
  v_admin_id uuid;
  v_fee numeric;
  v_jackpot_amount numeric;
  v_admin_fee numeric;
  v_referral_fee numeric;
  v_seller_amount numeric;
  v_ship_type_id integer;
  v_market_fee_percent numeric;
  v_referrer_id uuid;
  v_transaction_id uuid;
  v_seller_resources RECORD;
  v_seller_ship_qty integer;
  v_telegram_id bigint;
  v_is_member boolean;
  v_year_week text;
  v_ship_value bigint;
  -- Configurable share percentages
  v_admin_share numeric;
  v_pool_share numeric;
  v_referral_share numeric;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Vacation mode check
  IF EXISTS (SELECT 1 FROM profiles WHERE id = v_user_id AND vacation_mode = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot use the market while in vacation mode');
  END IF;

  -- Telegram verification
  SELECT telegram_id INTO v_telegram_id
  FROM telegram_links
  WHERE user_id = v_user_id;

  IF v_telegram_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Debes vincular tu cuenta de Telegram para usar el mercado. Ve a la seccion de Tareas para vincular tu cuenta.',
      'requires_telegram', true
    );
  END IF;

  SELECT is_member INTO v_is_member
  FROM telegram_task_rewards
  WHERE user_id = v_user_id AND task_type = 'join_group';

  IF v_is_member IS NULL OR v_is_member = false THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Debes ser miembro del grupo de Telegram para usar el mercado. Unete al grupo desde la seccion de Tareas.',
      'requires_telegram', true
    );
  END IF;

  SELECT * INTO v_listing
  FROM market_listings
  WHERE id = p_listing_id AND status = 'active'
  FOR UPDATE;

  IF v_listing IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Listing not found or not active');
  END IF;

  -- Cooldown check
  IF v_listing.purchasable_at > now() THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Esta oferta aun no esta disponible para compra. Espera a que termine el periodo de preparacion.',
      'cooldown_remaining', EXTRACT(EPOCH FROM (v_listing.purchasable_at - now()))::integer
    );
  END IF;

  IF v_listing.seller_id = v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot buy your own listing');
  END IF;

  v_purchase_qty := COALESCE(p_quantity, v_listing.quantity::integer);
  IF v_purchase_qty > v_listing.quantity OR v_purchase_qty < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid quantity');
  END IF;

  v_total_price := v_listing.price_per_unit * v_purchase_qty;

  IF v_total_price > 1000000000000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Total price exceeds maximum');
  END IF;

  SELECT fxu_balance INTO v_buyer_fxu
  FROM profiles
  WHERE id = v_user_id
  FOR UPDATE;

  IF v_buyer_fxu < v_total_price THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient FXU balance');
  END IF;

  SELECT id INTO v_buyer_planet_id FROM planets WHERE user_id = v_user_id AND is_main_planet = true LIMIT 1;
  IF v_buyer_planet_id IS NULL AND v_listing.listing_type != 'dark_matter' THEN
    RETURN jsonb_build_object('success', false, 'error', 'No main planet found');
  END IF;

  -- === DYNAMIC FEE: based on seller's rank + Plus status ===
  v_market_fee_percent := get_market_fee_for_user(v_listing.seller_id);

  -- Verify seller still has resources/ships
  IF v_listing.listing_type = 'resource' THEN
    SELECT metal, crystal, deuterium INTO v_seller_resources
    FROM planet_resources
    WHERE planet_id = v_listing.planet_id
    FOR UPDATE;

    IF v_listing.item_code = 'metal' AND v_seller_resources.metal < v_purchase_qty THEN
      RETURN jsonb_build_object('success', false, 'error', 'El vendedor ya no tiene suficiente metal (posiblemente fue atacado)');
    ELSIF v_listing.item_code = 'crystal' AND v_seller_resources.crystal < v_purchase_qty THEN
      RETURN jsonb_build_object('success', false, 'error', 'El vendedor ya no tiene suficiente cristal (posiblemente fue atacado)');
    ELSIF v_listing.item_code = 'deuterium' AND v_seller_resources.deuterium < v_purchase_qty THEN
      RETURN jsonb_build_object('success', false, 'error', 'El vendedor ya no tiene suficiente deuterio (posiblemente fue atacado)');
    END IF;

    IF v_listing.item_code = 'metal' THEN
      UPDATE planet_resources SET metal = metal - v_purchase_qty WHERE planet_id = v_listing.planet_id;
    ELSIF v_listing.item_code = 'crystal' THEN
      UPDATE planet_resources SET crystal = crystal - v_purchase_qty WHERE planet_id = v_listing.planet_id;
    ELSIF v_listing.item_code = 'deuterium' THEN
      UPDATE planet_resources SET deuterium = deuterium - v_purchase_qty WHERE planet_id = v_listing.planet_id;
    END IF;

  ELSIF v_listing.listing_type = 'ship' THEN
    SELECT id INTO v_ship_type_id FROM ship_types WHERE code = v_listing.item_code;
    IF v_ship_type_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Ship type not found');
    END IF;

    SELECT quantity INTO v_seller_ship_qty
    FROM planet_ships
    WHERE planet_id = v_listing.planet_id AND ship_type_id = v_ship_type_id
    FOR UPDATE;

    IF v_seller_ship_qty IS NULL OR v_seller_ship_qty < v_purchase_qty THEN
      RETURN jsonb_build_object('success', false, 'error', 'El vendedor ya no tiene suficientes naves (posiblemente fueron destruidas en combate)');
    END IF;

    UPDATE planet_ships
    SET quantity = quantity - v_purchase_qty
    WHERE planet_id = v_listing.planet_id AND ship_type_id = v_ship_type_id;

  ELSIF v_listing.listing_type = 'dark_matter' THEN
    NULL;
  END IF;

  -- ============================================================
  -- FEE DISTRIBUTION: 4-3-3 split (configurable via game_settings)
  -- 40% Admin | 30% Pool | 30% Referral (→ Pool if no referrer)
  -- ============================================================
  v_fee := v_total_price * (v_market_fee_percent / 100);
  v_seller_amount := v_total_price - v_fee;

  -- Read configurable shares (with defaults)
  SELECT COALESCE(value::numeric, 40) INTO v_admin_share FROM game_settings WHERE key = 'market_fee_admin_share';
  SELECT COALESCE(value::numeric, 30) INTO v_pool_share FROM game_settings WHERE key = 'market_fee_pool_share';
  SELECT COALESCE(value::numeric, 30) INTO v_referral_share FROM game_settings WHERE key = 'market_fee_referral_share';

  -- Calculate shares
  v_admin_fee := floor(v_fee * v_admin_share / 100);
  v_jackpot_amount := floor(v_fee * v_pool_share / 100);

  SELECT referred_by INTO v_referrer_id FROM profiles WHERE id = v_listing.seller_id;

  IF v_referrer_id IS NOT NULL THEN
    v_referral_fee := floor(v_fee * v_referral_share / 100);
  ELSE
    v_referral_fee := 0;
    -- Fallback: referral share goes to the pool
    v_jackpot_amount := v_jackpot_amount + floor(v_fee * v_referral_share / 100);
  END IF;

  PERFORM _internal_set_fxu_context();

  UPDATE profiles SET fxu_balance = fxu_balance - v_total_price WHERE id = v_user_id;
  UPDATE profiles SET fxu_balance = fxu_balance + v_seller_amount WHERE id = v_listing.seller_id;

  -- Admin fee → admin account + revenue tracking
  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_fee > 0 THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_admin_fee WHERE id = v_admin_id;

    PERFORM record_admin_revenue(
      'market_fee',
      v_admin_fee,
      'Venta: ' || v_purchase_qty || 'x ' || v_listing.item_code || 
      ' (fee ' || v_market_fee_percent || '%, admin ' || v_admin_share || '% de fee)',
      v_listing.seller_id,
      p_listing_id
    );
  END IF;

  -- Pool contribution
  IF v_jackpot_amount > 0 THEN
    PERFORM contribute_to_jackpot(v_jackpot_amount, 'market_fee', v_listing.seller_id);
  END IF;

  -- Transfer resources/ships/DM to buyer
  IF v_listing.listing_type = 'ship' THEN
    INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
    VALUES (v_buyer_planet_id, v_ship_type_id, v_purchase_qty)
    ON CONFLICT (planet_id, ship_type_id) DO UPDATE SET quantity = planet_ships.quantity + v_purchase_qty;

  ELSIF v_listing.listing_type = 'resource' THEN
    IF v_listing.item_code = 'metal' THEN
      UPDATE planet_resources SET metal = metal + v_purchase_qty WHERE planet_id = v_buyer_planet_id;
    ELSIF v_listing.item_code = 'crystal' THEN
      UPDATE planet_resources SET crystal = crystal + v_purchase_qty WHERE planet_id = v_buyer_planet_id;
    ELSIF v_listing.item_code = 'deuterium' THEN
      UPDATE planet_resources SET deuterium = deuterium + v_purchase_qty WHERE planet_id = v_buyer_planet_id;
    END IF;

  ELSIF v_listing.listing_type = 'dark_matter' THEN
    UPDATE profiles SET dark_matter = COALESCE(dark_matter, 0) + v_purchase_qty WHERE id = v_user_id;
  END IF;

  -- Record transaction
  INSERT INTO market_transactions (listing_id, buyer_id, seller_id, item_type, item_code, quantity, total_price)
  VALUES (p_listing_id, v_user_id, v_listing.seller_id, v_listing.listing_type, v_listing.item_code, v_purchase_qty, v_total_price)
  RETURNING id INTO v_transaction_id;

  -- Track monthly sales
  v_year_week := to_char(now(), 'IYYY-"W"IW');

  IF v_listing.listing_type = 'resource' THEN
    INSERT INTO market_monthly_sales (user_id, year_month, metal_sold, crystal_sold, deuterium_sold)
    VALUES (
      v_listing.seller_id,
      v_year_week,
      CASE WHEN v_listing.item_code = 'metal' THEN v_purchase_qty ELSE 0 END,
      CASE WHEN v_listing.item_code = 'crystal' THEN v_purchase_qty ELSE 0 END,
      CASE WHEN v_listing.item_code = 'deuterium' THEN v_purchase_qty ELSE 0 END
    )
    ON CONFLICT (user_id, year_month)
    DO UPDATE SET
      metal_sold = market_monthly_sales.metal_sold + CASE WHEN v_listing.item_code = 'metal' THEN v_purchase_qty ELSE 0 END,
      crystal_sold = market_monthly_sales.crystal_sold + CASE WHEN v_listing.item_code = 'crystal' THEN v_purchase_qty ELSE 0 END,
      deuterium_sold = market_monthly_sales.deuterium_sold + CASE WHEN v_listing.item_code = 'deuterium' THEN v_purchase_qty ELSE 0 END,
      updated_at = now();
  END IF;

  -- Track ship sales by resource value
  IF v_listing.listing_type = 'ship' THEN
    SELECT (COALESCE(metal_cost, 0) + COALESCE(crystal_cost, 0) + COALESCE(deuterium_cost, 0))::bigint
    INTO v_ship_value
    FROM ship_types WHERE code = v_listing.item_code;

    v_ship_value := COALESCE(v_ship_value, 0);

    IF v_ship_value > 0 THEN
      INSERT INTO market_monthly_sales (user_id, year_month, ships_value_sold)
      VALUES (
        v_listing.seller_id,
        v_year_week,
        v_purchase_qty * v_ship_value
      )
      ON CONFLICT (user_id, year_month)
      DO UPDATE SET
        ships_value_sold = market_monthly_sales.ships_value_sold + (v_purchase_qty * v_ship_value),
        updated_at = now();
    END IF;
  END IF;

  -- Track FXU value sold
  INSERT INTO market_monthly_sales (user_id, year_month, fxu_value_sold)
  VALUES (v_listing.seller_id, v_year_week, v_total_price)
  ON CONFLICT (user_id, year_month)
  DO UPDATE SET
    fxu_value_sold = market_monthly_sales.fxu_value_sold + v_total_price,
    updated_at = now();

  -- Referral commission: pay referrer and notify
  IF v_referrer_id IS NOT NULL AND v_referral_fee >= 1 THEN
    UPDATE profiles
    SET fxu_balance = COALESCE(fxu_balance, 0) + v_referral_fee
    WHERE id = v_referrer_id;

    INSERT INTO referral_commissions (referrer_id, seller_id, transaction_id, commission_type, resource_type, amount, fxu_amount)
    VALUES (v_referrer_id, v_listing.seller_id, v_transaction_id, 'market_referral', 'fxu', v_referral_fee, v_referral_fee);

    INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
    VALUES (
      v_referrer_id,
      v_listing.seller_id,
      'Comision de referido por venta en mercado',
      'Has recibido ' || ROUND(v_referral_fee, 2) || ' FXU como comision por la venta de tu referido en el mercado.',
      'system'
    );
  END IF;

  -- Update listing status
  IF v_purchase_qty = v_listing.quantity THEN
    UPDATE market_listings SET status = 'sold', updated_at = now() WHERE id = p_listing_id;
  ELSE
    UPDATE market_listings SET quantity = quantity - v_purchase_qty, total_price = (quantity - v_purchase_qty) * price_per_unit, updated_at = now() WHERE id = p_listing_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'quantity', v_purchase_qty,
    'total_price', v_total_price,
    'jackpot_contribution', v_jackpot_amount,
    'fee_percent', v_market_fee_percent
  );
END;
$$;


--
-- TOC entry 662 (class 1255 OID 18757)
-- Name: purchase_market_listing(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_market_listing(p_listing_id uuid, p_buyer_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_listing record;
  v_buyer_id uuid;
  v_buyer_profile record;
  v_total_cost numeric;
  v_market_fee_percent numeric := 10;
  v_seller_receives numeric;
  v_market_fee numeric;
  v_ship_type_id int;
  v_existing_ship record;
  v_referrer_id uuid;
  v_referral_commission_fxu numeric;
  v_transaction_id uuid;
  v_admin_id uuid;
BEGIN
  -- Verify authentication
  v_buyer_id := auth.uid();
  IF v_buyer_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Get buyer profile
  SELECT * INTO v_buyer_profile
  FROM profiles
  WHERE id = v_buyer_id;

  IF v_buyer_profile IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Profile not found');
  END IF;

  -- Lock listing for update
  SELECT * INTO v_listing
  FROM market_listings
  WHERE id = p_listing_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Listing not found');
  END IF;

  IF v_listing.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Listing no longer available');
  END IF;

  IF v_listing.seller_id = v_buyer_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot buy your own listing');
  END IF;

  -- Calculate costs
  v_total_cost := v_listing.total_price;
  v_market_fee := v_total_cost * v_market_fee_percent / 100;
  v_seller_receives := v_total_cost - v_market_fee;

  -- Check buyer has enough FXU
  IF COALESCE(v_buyer_profile.fxu_balance, 0) < v_total_cost THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Insufficient FXU. Have ' || COALESCE(v_buyer_profile.fxu_balance, 0)::text || ', need ' || v_total_cost::text
    );
  END IF;

  -- Validate buyer planet for non-dark_matter items
  IF v_listing.listing_type != 'dark_matter' THEN
    IF NOT EXISTS (
      SELECT 1 FROM planets WHERE id = p_buyer_planet_id AND user_id = v_buyer_id
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Invalid planet');
    END IF;
  END IF;

  -- Mark listing as sold
  UPDATE market_listings
  SET status = 'sold', updated_at = now()
  WHERE id = p_listing_id;

  -- Deduct FXU from buyer
  UPDATE profiles
  SET fxu_balance = COALESCE(fxu_balance, 0) - v_total_cost
  WHERE id = v_buyer_id;

  -- Pay seller (minus fee)
  UPDATE profiles
  SET fxu_balance = COALESCE(fxu_balance, 0) + v_seller_receives
  WHERE id = v_listing.seller_id;

  -- Deposit market fee to admin account
  v_admin_id := get_admin_account_id();
  IF v_admin_id IS NOT NULL AND v_market_fee > 0 THEN
    UPDATE profiles 
    SET fxu_balance = COALESCE(fxu_balance, 0) + v_market_fee 
    WHERE id = v_admin_id;
  END IF;

  -- Deliver purchased items
  IF v_listing.listing_type = 'resource' THEN
    IF v_listing.item_code = 'metal' THEN
      UPDATE planet_resources SET metal = metal + v_listing.quantity WHERE planet_id = p_buyer_planet_id;
    ELSIF v_listing.item_code = 'crystal' THEN
      UPDATE planet_resources SET crystal = crystal + v_listing.quantity WHERE planet_id = p_buyer_planet_id;
    ELSIF v_listing.item_code = 'deuterium' THEN
      UPDATE planet_resources SET deuterium = deuterium + v_listing.quantity WHERE planet_id = p_buyer_planet_id;
    END IF;

  ELSIF v_listing.listing_type = 'dark_matter' THEN
    UPDATE profiles
    SET dark_matter = COALESCE(dark_matter, 0) + v_listing.quantity
    WHERE id = v_buyer_id;

  ELSIF v_listing.listing_type = 'ship' THEN
    SELECT id INTO v_ship_type_id FROM ship_types WHERE code = v_listing.item_code;

    IF v_ship_type_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Ship type not found');
    END IF;

    SELECT * INTO v_existing_ship
    FROM planet_ships
    WHERE planet_id = p_buyer_planet_id AND ship_type_id = v_ship_type_id;

    IF FOUND THEN
      UPDATE planet_ships
      SET quantity = quantity + v_listing.quantity
      WHERE planet_id = p_buyer_planet_id AND ship_type_id = v_ship_type_id;
    ELSE
      INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
      VALUES (p_buyer_planet_id, v_ship_type_id, v_listing.quantity);
    END IF;
  END IF;

  -- Record transaction
  INSERT INTO market_transactions (listing_id, buyer_id, seller_id, item_type, item_code, quantity, total_price)
  VALUES (p_listing_id, v_buyer_id, v_listing.seller_id, v_listing.listing_type, v_listing.item_code, v_listing.quantity, v_listing.total_price)
  RETURNING id INTO v_transaction_id;

  -- Process referral commission (5% of total to referrer)
  SELECT referred_by INTO v_referrer_id FROM profiles WHERE id = v_listing.seller_id;

  IF v_referrer_id IS NOT NULL THEN
    v_referral_commission_fxu := FLOOR(v_total_cost * 5 / 100);

    IF v_referral_commission_fxu >= 1 THEN
      UPDATE profiles
      SET fxu_balance = COALESCE(fxu_balance, 0) + v_referral_commission_fxu
      WHERE id = v_referrer_id;

      INSERT INTO referral_commissions (referrer_id, seller_id, transaction_id, commission_type, resource_type, amount, fxu_amount)
      VALUES (v_referrer_id, v_listing.seller_id, v_transaction_id, 'fxu', 'fxu', v_referral_commission_fxu, v_referral_commission_fxu);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Purchase completed successfully',
    'total_paid', v_total_cost,
    'seller_received', v_seller_receives,
    'fee_collected', v_market_fee
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Error processing purchase: ' || SQLERRM);
END;
$$;


--
-- TOC entry 7795 (class 0 OID 0)
-- Dependencies: 662
-- Name: FUNCTION purchase_market_listing(p_listing_id uuid, p_buyer_planet_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purchase_market_listing(p_listing_id uuid, p_buyer_planet_id uuid) IS 'Handles P2P market purchases using FXU with 10% platform fee.
- Used by frontend with p_listing_id and p_buyer_planet_id parameters
- Validates buyer authentication, FXU balance, and listing status
- Deducts total price from buyer, pays 90% to seller
- Deposits 10% fee to admin account
- Delivers purchased items (resources, dark matter, or ships)
- Processes 5% referral commission to seller referrer if applicable';


--
-- TOC entry 1008 (class 1255 OID 20875)
-- Name: purchase_market_listing(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_market_listing(p_listing_id uuid, p_quantity integer DEFAULT NULL::integer, p_buyer_planet_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid;
  v_listing RECORD;
  v_buyer_planet_id uuid;
  v_purchase_qty integer;
  v_total_price numeric;
  v_buyer_fxu numeric;
  v_admin_id uuid;
  v_fee numeric;
  v_jackpot_amount numeric;
  v_admin_fee numeric;
  v_referral_fee numeric;
  v_seller_amount numeric;
  v_ship_type_id integer;
  v_market_fee_percent numeric;
  v_referrer_id uuid;
  v_transaction_id uuid;
  v_seller_resources RECORD;
  v_seller_ship_qty integer;
  v_telegram_id bigint;
  v_is_member boolean;
  v_year_week text;
  v_ship_value bigint;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF EXISTS (SELECT 1 FROM profiles WHERE id = v_user_id AND vacation_mode = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot use the market while in vacation mode');
  END IF;

  SELECT telegram_id INTO v_telegram_id FROM telegram_links WHERE user_id = v_user_id;
  IF v_telegram_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Debes vincular tu cuenta de Telegram para usar el mercado.', 'requires_telegram', true);
  END IF;

  SELECT is_member INTO v_is_member FROM telegram_task_rewards WHERE user_id = v_user_id AND task_type = 'join_group';
  IF v_is_member IS NULL OR v_is_member = false THEN
    RETURN jsonb_build_object('success', false, 'error', 'Debes ser miembro del grupo de Telegram para usar el mercado.', 'requires_telegram', true);
  END IF;

  SELECT * INTO v_listing FROM market_listings WHERE id = p_listing_id AND status = 'active' FOR UPDATE;
  IF v_listing IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Listing not found or not active');
  END IF;

  IF v_listing.purchasable_at > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Esta oferta aun no esta disponible para compra.', 'cooldown_remaining', EXTRACT(EPOCH FROM (v_listing.purchasable_at - now()))::integer);
  END IF;

  IF v_listing.seller_id = v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot buy your own listing');
  END IF;

  v_purchase_qty := COALESCE(p_quantity, v_listing.quantity::integer);
  IF v_purchase_qty > v_listing.quantity OR v_purchase_qty < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid quantity');
  END IF;

  v_total_price := v_listing.price_per_unit * v_purchase_qty;

  IF v_total_price > 1000000000000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Total price exceeds maximum');
  END IF;

  SELECT fxu_balance INTO v_buyer_fxu FROM profiles WHERE id = v_user_id FOR UPDATE;
  IF v_buyer_fxu < v_total_price THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient FXU balance');
  END IF;

  -- Use provided planet_id if valid, otherwise fall back to main planet
  IF p_buyer_planet_id IS NOT NULL THEN
    SELECT id INTO v_buyer_planet_id FROM planets WHERE id = p_buyer_planet_id AND user_id = v_user_id;
  END IF;
  IF v_buyer_planet_id IS NULL THEN
    SELECT id INTO v_buyer_planet_id FROM planets WHERE user_id = v_user_id AND is_main_planet = true LIMIT 1;
  END IF;
  IF v_buyer_planet_id IS NULL AND v_listing.listing_type != 'dark_matter' THEN
    RETURN jsonb_build_object('success', false, 'error', 'No main planet found');
  END IF;

  v_market_fee_percent := get_market_fee_for_user(v_listing.seller_id);

  -- Verify seller still has resources/ships
  IF v_listing.listing_type = 'resource' THEN
    SELECT metal, crystal, deuterium INTO v_seller_resources FROM planet_resources WHERE planet_id = v_listing.planet_id FOR UPDATE;

    IF v_listing.item_code = 'metal' AND COALESCE(v_seller_resources.metal, 0) < v_purchase_qty THEN
      UPDATE market_listings SET status = 'cancelled', updated_at = now() WHERE id = p_listing_id AND status = 'active';
      RETURN jsonb_build_object('success', false, 'error', 'El vendedor ya no tiene suficiente metal (oferta cancelada)');
    ELSIF v_listing.item_code = 'crystal' AND COALESCE(v_seller_resources.crystal, 0) < v_purchase_qty THEN
      UPDATE market_listings SET status = 'cancelled', updated_at = now() WHERE id = p_listing_id AND status = 'active';
      RETURN jsonb_build_object('success', false, 'error', 'El vendedor ya no tiene suficiente cristal (oferta cancelada)');
    ELSIF v_listing.item_code = 'deuterium' AND COALESCE(v_seller_resources.deuterium, 0) < v_purchase_qty THEN
      UPDATE market_listings SET status = 'cancelled', updated_at = now() WHERE id = p_listing_id AND status = 'active';
      RETURN jsonb_build_object('success', false, 'error', 'El vendedor ya no tiene suficiente deuterio (oferta cancelada)');
    END IF;

    IF v_listing.item_code = 'metal' THEN
      UPDATE planet_resources SET metal = metal - v_purchase_qty WHERE planet_id = v_listing.planet_id;
    ELSIF v_listing.item_code = 'crystal' THEN
      UPDATE planet_resources SET crystal = crystal - v_purchase_qty WHERE planet_id = v_listing.planet_id;
    ELSIF v_listing.item_code = 'deuterium' THEN
      UPDATE planet_resources SET deuterium = deuterium - v_purchase_qty WHERE planet_id = v_listing.planet_id;
    END IF;

  ELSIF v_listing.listing_type = 'ship' THEN
    SELECT id INTO v_ship_type_id FROM ship_types WHERE code = v_listing.item_code;
    IF v_ship_type_id IS NULL THEN
      UPDATE market_listings SET status = 'cancelled', updated_at = now() WHERE id = p_listing_id AND status = 'active';
      RETURN jsonb_build_object('success', false, 'error', 'Ship type not found (oferta cancelada)');
    END IF;

    SELECT quantity INTO v_seller_ship_qty FROM planet_ships WHERE planet_id = v_listing.planet_id AND ship_type_id = v_ship_type_id FOR UPDATE;
    IF v_seller_ship_qty IS NULL OR v_seller_ship_qty < v_purchase_qty THEN
      UPDATE market_listings SET status = 'cancelled', updated_at = now() WHERE id = p_listing_id AND status = 'active';
      RETURN jsonb_build_object('success', false, 'error', 'El vendedor ya no tiene suficientes naves (oferta cancelada)');
    END IF;

    UPDATE planet_ships SET quantity = quantity - v_purchase_qty WHERE planet_id = v_listing.planet_id AND ship_type_id = v_ship_type_id;

  ELSIF v_listing.listing_type = 'dark_matter' THEN
    NULL;
  END IF;

  -- Fee calculation
  v_fee := v_total_price * (v_market_fee_percent / 100);
  v_seller_amount := v_total_price - v_fee;
  v_jackpot_amount := floor(v_fee * 50 / 100);

  SELECT referred_by INTO v_referrer_id FROM profiles WHERE id = v_listing.seller_id;
  IF v_referrer_id IS NOT NULL THEN
    v_referral_fee := floor(v_fee * 20 / 100);
    v_admin_fee := v_fee - v_jackpot_amount - v_referral_fee;
  ELSE
    v_referral_fee := 0;
    v_admin_fee := v_fee - v_jackpot_amount;
  END IF;

  PERFORM _internal_set_fxu_context();

  UPDATE profiles SET fxu_balance = fxu_balance - v_total_price WHERE id = v_user_id;
  UPDATE profiles SET fxu_balance = fxu_balance + v_seller_amount WHERE id = v_listing.seller_id;

  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_fee > 0 THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_admin_fee WHERE id = v_admin_id;
    PERFORM record_admin_revenue('market_fee', v_admin_fee, 'Venta: ' || v_purchase_qty || 'x ' || v_listing.item_code || ' (fee ' || v_market_fee_percent || '%, admin ' || round(v_admin_fee / v_fee * 100) || '%)', v_listing.seller_id, p_listing_id);
  END IF;

  IF v_jackpot_amount > 0 THEN
    PERFORM contribute_to_jackpot(v_jackpot_amount, 'market_fee', v_listing.seller_id);
  END IF;

  -- Deliver to buyer's selected planet (or main planet as fallback)
  IF v_listing.listing_type = 'ship' THEN
    INSERT INTO planet_ships (planet_id, ship_type_id, quantity) VALUES (v_buyer_planet_id, v_ship_type_id, v_purchase_qty)
    ON CONFLICT (planet_id, ship_type_id) DO UPDATE SET quantity = planet_ships.quantity + v_purchase_qty;
  ELSIF v_listing.listing_type = 'resource' THEN
    IF v_listing.item_code = 'metal' THEN
      UPDATE planet_resources SET metal = metal + v_purchase_qty WHERE planet_id = v_buyer_planet_id;
    ELSIF v_listing.item_code = 'crystal' THEN
      UPDATE planet_resources SET crystal = crystal + v_purchase_qty WHERE planet_id = v_buyer_planet_id;
    ELSIF v_listing.item_code = 'deuterium' THEN
      UPDATE planet_resources SET deuterium = deuterium + v_purchase_qty WHERE planet_id = v_buyer_planet_id;
    END IF;
  ELSIF v_listing.listing_type = 'dark_matter' THEN
    UPDATE profiles SET dark_matter = COALESCE(dark_matter, 0) + v_purchase_qty WHERE id = v_user_id;
  END IF;

  INSERT INTO market_transactions (listing_id, buyer_id, seller_id, item_type, item_code, quantity, total_price)
  VALUES (p_listing_id, v_user_id, v_listing.seller_id, v_listing.listing_type, v_listing.item_code, v_purchase_qty, v_total_price)
  RETURNING id INTO v_transaction_id;

  v_year_week := to_char(now(), 'IYYY-"W"IW');

  -- Track resource sales (units + FXU value)
  IF v_listing.listing_type = 'resource' THEN
    INSERT INTO market_monthly_sales (user_id, year_month, metal_sold, crystal_sold, deuterium_sold, fxu_value_sold)
    VALUES (
      v_listing.seller_id,
      v_year_week,
      CASE WHEN v_listing.item_code = 'metal' THEN v_purchase_qty ELSE 0 END,
      CASE WHEN v_listing.item_code = 'crystal' THEN v_purchase_qty ELSE 0 END,
      CASE WHEN v_listing.item_code = 'deuterium' THEN v_purchase_qty ELSE 0 END,
      v_total_price
    )
    ON CONFLICT (user_id, year_month)
    DO UPDATE SET
      metal_sold = market_monthly_sales.metal_sold + CASE WHEN v_listing.item_code = 'metal' THEN v_purchase_qty ELSE 0 END,
      crystal_sold = market_monthly_sales.crystal_sold + CASE WHEN v_listing.item_code = 'crystal' THEN v_purchase_qty ELSE 0 END,
      deuterium_sold = market_monthly_sales.deuterium_sold + CASE WHEN v_listing.item_code = 'deuterium' THEN v_purchase_qty ELSE 0 END,
      fxu_value_sold = market_monthly_sales.fxu_value_sold + v_total_price,
      updated_at = now();
  END IF;

  -- Track ship sales (resource value + FXU value)
  IF v_listing.listing_type = 'ship' THEN
    SELECT (COALESCE(metal_cost, 0) + COALESCE(crystal_cost, 0) + COALESCE(deuterium_cost, 0))::bigint
    INTO v_ship_value FROM ship_types WHERE code = v_listing.item_code;
    v_ship_value := COALESCE(v_ship_value, 0);

    INSERT INTO market_monthly_sales (user_id, year_month, ships_value_sold, fxu_value_sold)
    VALUES (v_listing.seller_id, v_year_week, v_purchase_qty * v_ship_value, v_total_price)
    ON CONFLICT (user_id, year_month)
    DO UPDATE SET
      ships_value_sold = market_monthly_sales.ships_value_sold + (v_purchase_qty * v_ship_value),
      fxu_value_sold = market_monthly_sales.fxu_value_sold + v_total_price,
      updated_at = now();
  END IF;

  -- Referral
  IF v_referrer_id IS NOT NULL AND v_referral_fee >= 1 THEN
    UPDATE profiles SET fxu_balance = COALESCE(fxu_balance, 0) + v_referral_fee WHERE id = v_referrer_id;
    INSERT INTO referral_commissions (referrer_id, seller_id, transaction_id, commission_type, resource_type, amount, fxu_amount)
    VALUES (v_referrer_id, v_listing.seller_id, v_transaction_id, 'market_referral', 'fxu', v_referral_fee, v_referral_fee);
    INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
    VALUES (v_referrer_id, v_listing.seller_id, 'Comision de referido por venta en mercado', 'Has recibido ' || ROUND(v_referral_fee, 2) || ' FXU como comision por la venta de tu referido en el mercado.', 'system');
  END IF;

  IF v_purchase_qty = v_listing.quantity THEN
    UPDATE market_listings SET status = 'sold', updated_at = now() WHERE id = p_listing_id;
  ELSE
    UPDATE market_listings SET quantity = quantity - v_purchase_qty, total_price = (quantity - v_purchase_qty) * price_per_unit, updated_at = now() WHERE id = p_listing_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'quantity', v_purchase_qty, 'total_price', v_total_price, 'jackpot_contribution', v_jackpot_amount, 'fee_percent', v_market_fee_percent);

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Error al procesar la compra: ' || SQLERRM);
END;
$$;


--
-- TOC entry 751 (class 1255 OID 19079)
-- Name: purchase_officer_with_dark_matter(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_officer_with_dark_matter(p_officer_type_id uuid, p_duration text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_officer officer_types%ROWTYPE;
  v_dm_cost integer;
  v_current_dm integer;
  v_days_to_add integer;
  v_existing_officer user_officers%ROWTYPE;
  v_new_expiry timestamptz;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Check for existing ACTIVE officer - block purchase if active
  SELECT * INTO v_existing_officer
  FROM user_officers
  WHERE user_id = v_user_id 
    AND officer_type_id = p_officer_type_id
    AND expires_at > NOW();

  IF v_existing_officer IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Officer is still active. Wait until it expires to purchase again.');
  END IF;

  -- Get officer type
  SELECT * INTO v_officer FROM officer_types WHERE id = p_officer_type_id;
  IF v_officer IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Officer type not found');
  END IF;

  -- Get Dark Matter cost based on duration
  CASE p_duration
    WHEN '7d' THEN 
      v_dm_cost := v_officer.dark_matter_cost_7d;
      v_days_to_add := 7;
    WHEN '30d' THEN 
      v_dm_cost := v_officer.dark_matter_cost_30d;
      v_days_to_add := 30;
    WHEN '90d' THEN 
      v_dm_cost := v_officer.dark_matter_cost_90d;
      v_days_to_add := 90;
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'Invalid duration');
  END CASE;

  -- Get current Dark Matter balance
  SELECT dark_matter INTO v_current_dm FROM profiles WHERE id = v_user_id;
  
  IF v_current_dm < v_dm_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient Dark Matter');
  END IF;

  -- Deduct Dark Matter
  UPDATE profiles 
  SET dark_matter = dark_matter - v_dm_cost 
  WHERE id = v_user_id;

  -- Create new officer assignment
  v_new_expiry := NOW() + (v_days_to_add || ' days')::interval;
  
  -- Delete any expired officer record first
  DELETE FROM user_officers 
  WHERE user_id = v_user_id 
    AND officer_type_id = p_officer_type_id;
  
  -- Insert new officer
  INSERT INTO user_officers (user_id, officer_type_id, expires_at)
  VALUES (v_user_id, p_officer_type_id, v_new_expiry);

  RETURN jsonb_build_object(
    'success', true,
    'expires_at', v_new_expiry,
    'dark_matter_spent', v_dm_cost
  );
END;
$$;


--
-- TOC entry 750 (class 1255 OID 19078)
-- Name: purchase_officer_with_fxu(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_officer_with_fxu(p_officer_type_id uuid, p_duration text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_officer officer_types%ROWTYPE;
  v_fxu_cost integer;
  v_current_fxu numeric;
  v_days_to_add integer;
  v_existing_officer user_officers%ROWTYPE;
  v_new_expiry timestamptz;
  v_admin_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_existing_officer
  FROM user_officers
  WHERE user_id = v_user_id 
  AND officer_type_id = p_officer_type_id
  AND expires_at > NOW();

  IF v_existing_officer IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Officer is still active. Wait until it expires to purchase again.');
  END IF;

  SELECT * INTO v_officer FROM officer_types WHERE id = p_officer_type_id;
  IF v_officer IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Officer type not found');
  END IF;

  CASE p_duration
    WHEN '7d' THEN 
      v_fxu_cost := v_officer.fxu_cost_7d;
      v_days_to_add := 7;
    WHEN '30d' THEN 
      v_fxu_cost := v_officer.fxu_cost_30d;
      v_days_to_add := 30;
    WHEN '90d' THEN 
      v_fxu_cost := v_officer.fxu_cost_90d;
      v_days_to_add := 90;
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'Invalid duration');
  END CASE;

  SELECT fxu_balance INTO v_current_fxu FROM profiles WHERE id = v_user_id;

  IF v_current_fxu < v_fxu_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient FXU balance');
  END IF;

  PERFORM _internal_set_fxu_context();

  UPDATE profiles 
  SET fxu_balance = fxu_balance - v_fxu_cost 
  WHERE id = v_user_id;

  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_id != v_user_id THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_fxu_cost WHERE id = v_admin_id;
  END IF;

  INSERT INTO admin_revenue (revenue_type, amount, related_user_id, description)
  VALUES (
    'officer_fxu', 
    v_fxu_cost, 
    v_user_id, 
    'Officer: ' || v_officer.name || ' (' || p_duration || ')'
  );

  v_new_expiry := NOW() + (v_days_to_add || ' days')::interval;

  DELETE FROM user_officers 
  WHERE user_id = v_user_id 
  AND officer_type_id = p_officer_type_id;

  INSERT INTO user_officers (user_id, officer_type_id, expires_at)
  VALUES (v_user_id, p_officer_type_id, v_new_expiry);

  RETURN jsonb_build_object(
    'success', true,
    'expires_at', v_new_expiry,
    'fxu_spent', v_fxu_cost
  );
END;
$$;


--
-- TOC entry 834 (class 1255 OID 19856)
-- Name: purchase_plus_subscription(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_plus_subscription(p_plan_code text, p_payment_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_plan plus_plans%ROWTYPE;
  v_price numeric;
  v_current_fxu numeric;
  v_current_usdt numeric;
  v_expires_at timestamptz;
  v_existing_sub plus_subscriptions%ROWTYPE;
  v_sub_id uuid;
  v_referrer_id uuid;
  v_commission_percent numeric;
  v_commission_amount numeric;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_plan FROM plus_plans WHERE code = p_plan_code AND is_active = true;

  IF v_plan.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Plan no encontrado');
  END IF;

  SELECT * INTO v_existing_sub
  FROM plus_subscriptions
  WHERE user_id = v_user_id AND is_active = true AND expires_at > now();

  IF v_existing_sub.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Ya tienes una suscripcion Plus activa hasta ' || to_char(v_existing_sub.expires_at, 'DD/MM/YYYY')
    );
  END IF;

  PERFORM _internal_set_fxu_context();

  IF p_payment_type = 'fxu' THEN
    v_price := v_plan.price_fxu;

    SELECT fxu_balance INTO v_current_fxu FROM profiles WHERE id = v_user_id;

    IF v_current_fxu IS NULL OR v_current_fxu < v_price THEN
      RETURN jsonb_build_object('success', false, 'error', 'FXU insuficiente. Necesitas ' || v_price || ' FXU');
    END IF;

    UPDATE profiles SET fxu_balance = fxu_balance - v_price WHERE id = v_user_id;

    INSERT INTO public.admin_revenue (revenue_type, amount, currency, related_user_id, description)
    VALUES ('plus_subscription', v_price, 'FXU', v_user_id, 'Plus ' || v_plan.name || ' (FXU)');

  ELSIF p_payment_type = 'usdt' THEN
    v_price := v_plan.price_usdt;

    SELECT usdt_balance INTO v_current_usdt FROM profiles WHERE id = v_user_id;

    IF v_current_usdt IS NULL OR v_current_usdt < v_price THEN
      RETURN jsonb_build_object('success', false, 'error', 'USDT insuficiente. Necesitas ' || v_price || ' USDT');
    END IF;

    UPDATE profiles SET usdt_balance = usdt_balance - v_price WHERE id = v_user_id;

    INSERT INTO public.admin_revenue (revenue_type, amount, currency, related_user_id, description)
    VALUES ('plus_subscription', v_price, 'USDT', v_user_id, 'Plus ' || v_plan.name || ' (USDT)');
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'Tipo de pago invalido');
  END IF;

  -- Calculate expiration: use duration_days if set, otherwise duration_months
  IF COALESCE(v_plan.duration_days, 0) > 0 THEN
    v_expires_at := now() + (v_plan.duration_days || ' days')::interval;
  ELSE
    v_expires_at := now() + (v_plan.duration_months || ' months')::interval;
  END IF;

  INSERT INTO plus_subscriptions (user_id, plan_id, payment_type, amount_paid, expires_at, commission_share_percent)
  VALUES (v_user_id, v_plan.id, p_payment_type, v_price, v_expires_at, v_plan.commission_share_percent)
  RETURNING id INTO v_sub_id;

  SELECT referred_by INTO v_referrer_id FROM profiles WHERE id = v_user_id;

  IF v_referrer_id IS NOT NULL THEN
    v_commission_percent := get_referral_commission_percent();
    v_commission_amount := FLOOR(v_price * v_commission_percent / 100 * 100) / 100;

    IF v_commission_amount >= 0.01 THEN
      IF p_payment_type = 'fxu' THEN
        UPDATE profiles
        SET fxu_balance = COALESCE(fxu_balance, 0) + v_commission_amount
        WHERE id = v_referrer_id;
      ELSIF p_payment_type = 'usdt' THEN
        UPDATE profiles
        SET usdt_balance = COALESCE(usdt_balance, 0) + v_commission_amount
        WHERE id = v_referrer_id;
      END IF;

      INSERT INTO referral_commissions (
        referrer_id, seller_id, transaction_id,
        commission_type, resource_type, amount, fxu_amount
      )
      VALUES (
        v_referrer_id,
        v_user_id,
        NULL,
        'plus_subscription',
        p_payment_type,
        FLOOR(v_commission_amount)::bigint,
        v_commission_amount
      );

      INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
      VALUES (
        v_referrer_id,
        v_user_id,
        'Comision de referido por compra Plus',
        'Has recibido ' || ROUND(v_commission_amount, 2) || ' ' || UPPER(p_payment_type)
          || ' como comision porque tu referido compro Plus ' || v_plan.name || '.',
        'system'
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Suscripcion Plus activada hasta ' || to_char(v_expires_at, 'DD/MM/YYYY'),
    'subscription_id', v_sub_id,
    'expires_at', v_expires_at
  );
END;
$$;


--
-- TOC entry 1123 (class 1255 OID 21908)
-- Name: purchase_ship_blueprint(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_ship_blueprint(p_blueprint_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_blueprint ship_blueprints%ROWTYPE;
  v_balance numeric;
  v_admin_id uuid;
  v_pool_amount numeric;
  v_admin_amount numeric;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_blueprint
  FROM ship_blueprints
  WHERE code = p_blueprint_code AND is_active = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Plano no disponible');
  END IF;

  SELECT COALESCE(fxu_balance, 0) INTO v_balance
  FROM profiles
  WHERE id = v_user_id
  FOR UPDATE;

  IF v_balance < v_blueprint.price_fxu THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'FXU insuficiente',
      'required', v_blueprint.price_fxu,
      'balance', v_balance
    );
  END IF;

  PERFORM _internal_set_fxu_context();

  -- Cobrar al jugador
  UPDATE profiles
  SET fxu_balance = COALESCE(fxu_balance, 0) - v_blueprint.price_fxu
  WHERE id = v_user_id;

  -- Split 50% admin / 50% pools
  v_pool_amount  := FLOOR(v_blueprint.price_fxu * 0.50);
  v_admin_amount := v_blueprint.price_fxu - v_pool_amount;

  SELECT id INTO v_admin_id
  FROM profiles
  WHERE is_admin = true
  ORDER BY created_at ASC
  LIMIT 1;

  IF v_admin_id IS NOT NULL AND v_admin_id <> v_user_id AND v_admin_amount > 0 THEN
    UPDATE profiles
    SET fxu_balance = COALESCE(fxu_balance, 0) + v_admin_amount
    WHERE id = v_admin_id;
  END IF;

  PERFORM record_admin_revenue(
    'other',
    v_admin_amount,
    'blueprint_sale (50% admin): ' || v_blueprint.code,
    v_user_id,
    NULL
  );

  IF v_pool_amount > 0 THEN
    PERFORM contribute_to_jackpot(v_pool_amount, 'blueprint_sale:' || v_blueprint.code, v_user_id);
  END IF;

  -- Entregar 1 unidad de plano
  INSERT INTO user_ship_blueprints (user_id, blueprint_id, source, metadata)
  VALUES (
    v_user_id,
    v_blueprint.id,
    'shop',
    jsonb_build_object(
      'price_fxu', v_blueprint.price_fxu,
      'admin_share', v_admin_amount,
      'pool_share', v_pool_amount
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Plano comprado exitosamente',
    'blueprint_code', v_blueprint.code,
    'quantity_added', 1,
    'cost', v_blueprint.price_fxu,
    'admin_share', v_admin_amount,
    'pool_share', v_pool_amount
  );
END;
$$;


--
-- TOC entry 841 (class 1255 OID 19947)
-- Name: purchase_supply_box(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_supply_box(p_box_code text, p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_user_id uuid;
v_box supply_boxes%ROWTYPE;
v_planet planets%ROWTYPE;
v_current_fxu numeric;
v_calculated jsonb;
v_synced_metal numeric;
v_synced_crystal numeric;
v_synced_deuterium numeric;
BEGIN
v_user_id := auth.uid();

IF v_user_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
END IF;

SELECT * INTO v_box FROM supply_boxes WHERE code = p_box_code AND is_active = true;

IF v_box.id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Caja no encontrada o no disponible');
END IF;

SELECT * INTO v_planet FROM planets WHERE id = p_planet_id AND user_id = v_user_id;

IF v_planet.id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Planeta no encontrado o no te pertenece');
END IF;

SELECT fxu_balance INTO v_current_fxu FROM profiles WHERE id = v_user_id;

IF v_current_fxu IS NULL OR v_current_fxu < v_box.price_fxu THEN
RETURN jsonb_build_object('success', false, 'error', 'FXU insuficiente. Necesitas ' || v_box.price_fxu || ' FXU');
END IF;

v_calculated := calculate_planet_resources(p_planet_id);

IF v_calculated ? 'error' THEN
RETURN jsonb_build_object('success', false, 'error', 'Error calculando recursos del planeta');
END IF;

v_synced_metal := (v_calculated->>'metal')::numeric;
v_synced_crystal := (v_calculated->>'crystal')::numeric;
v_synced_deuterium := (v_calculated->>'deuterium')::numeric;

UPDATE planet_resources
SET 
metal = v_synced_metal,
crystal = v_synced_crystal,
deuterium = v_synced_deuterium,
metal_per_hour = (v_calculated->>'metal_per_hour')::numeric,
crystal_per_hour = (v_calculated->>'crystal_per_hour')::numeric,
deuterium_per_hour = (v_calculated->>'deuterium_per_hour')::numeric,
metal_storage = (v_calculated->>'metal_storage')::numeric,
crystal_storage = (v_calculated->>'crystal_storage')::numeric,
deuterium_storage = (v_calculated->>'deuterium_storage')::numeric,
energy_used = (v_calculated->>'energy_used')::numeric,
energy_max = (v_calculated->>'energy_max')::numeric,
last_update = now()
WHERE planet_id = p_planet_id;

PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);

UPDATE profiles 
SET fxu_balance = fxu_balance - v_box.price_fxu 
WHERE id = v_user_id;

PERFORM set_config('fxu.allow_update_9x7k2m', '', true);

UPDATE planet_resources
SET 
metal = v_synced_metal + v_box.metal_amount,
crystal = v_synced_crystal + v_box.crystal_amount,
deuterium = v_synced_deuterium + v_box.deuterium_amount,
last_update = now()
WHERE planet_id = p_planet_id;

INSERT INTO supply_box_purchases (user_id, planet_id, box_id, box_name, metal_received, crystal_received, deuterium_received, fxu_paid)
VALUES (v_user_id, p_planet_id, v_box.id, v_box.name, v_box.metal_amount, v_box.crystal_amount, v_box.deuterium_amount, v_box.price_fxu);

INSERT INTO admin_revenue (revenue_type, amount, related_user_id, description)
VALUES ('supply_box', v_box.price_fxu, v_user_id, 'Compra: ' || v_box.name);

RETURN jsonb_build_object(
'success', true,
'message', 'Caja comprada! Recursos agregados a ' || v_planet.name,
'metal', v_box.metal_amount,
'crystal', v_box.crystal_amount,
'deuterium', v_box.deuterium_amount,
'fxu_spent', v_box.price_fxu,
'storage_limited', false
);
END;
$$;


