--
-- TOC entry 601 (class 1255 OID 18402)
-- Name: rebuild_defenses_after_combat(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebuild_defenses_after_combat(p_planet_id uuid, p_destroyed_defenses jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
v_defense record;
v_rebuild_chance numeric := 0.7;
v_rebuilt_count integer := 0;
v_defense_type_id integer;
v_destroyed_quantity integer;
v_rebuilt_quantity integer;
BEGIN
FOR v_defense IN SELECT * FROM jsonb_array_elements(p_destroyed_defenses)
LOOP
v_defense_type_id := (v_defense.value->>'defense_type_id')::integer;
v_destroyed_quantity := (v_defense.value->>'quantity')::integer;

v_rebuilt_quantity := 0;
FOR i IN 1..v_destroyed_quantity LOOP
IF random() < v_rebuild_chance THEN
v_rebuilt_quantity := v_rebuilt_quantity + 1;
END IF;
END LOOP;

IF v_rebuilt_quantity > 0 THEN
UPDATE public.planet_defenses
SET quantity = quantity + v_rebuilt_quantity
WHERE planet_id = p_planet_id AND defense_type_id = v_defense_type_id;

v_rebuilt_count := v_rebuilt_count + v_rebuilt_quantity;
END IF;
END LOOP;

RETURN jsonb_build_object(
'rebuilt_count', v_rebuilt_count,
'rebuild_chance', v_rebuild_chance * 100
);
END;
$$;


--
-- TOC entry 660 (class 1255 OID 18747)
-- Name: rebuild_destroyed_defenses(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebuild_destroyed_defenses(p_planet_id uuid, p_destroyed_defenses jsonb, p_defender_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_unit jsonb;
  v_destroyed_qty INTEGER;
  v_rebuilt_qty INTEGER;
  v_i INTEGER;
  v_rebuild_chance NUMERIC;
BEGIN
  -- Get rebuild chance based on Engineer officer
  v_rebuild_chance := get_defense_rebuild_chance(p_defender_user_id);

  FOR v_unit IN SELECT * FROM jsonb_array_elements(p_destroyed_defenses)
  LOOP
    v_destroyed_qty := (v_unit->>'quantity')::integer;
    v_rebuilt_qty := 0;
    
    -- Roll for each destroyed defense unit
    FOR v_i IN 1..v_destroyed_qty LOOP
      IF random() < v_rebuild_chance THEN
        v_rebuilt_qty := v_rebuilt_qty + 1;
      END IF;
    END LOOP;

    -- Update defense quantity (add rebuilt units)
    IF v_rebuilt_qty > 0 THEN
      UPDATE planet_defenses
      SET quantity = quantity + v_rebuilt_qty
      WHERE planet_id = p_planet_id 
      AND defense_type_id = (v_unit->>'defense_type_id')::integer;
    END IF;
  END LOOP;
END;
$$;


