--
-- TOC entry 584 (class 1255 OID 18256)
-- Name: recalculate_planet_fields(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_planet_fields(p_planet_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
v_building_count integer;
v_terraformer_bonus integer;
BEGIN
SELECT COUNT(*) INTO v_building_count
FROM public.planet_buildings
WHERE planet_id = p_planet_id AND level > 0;

SELECT COALESCE(pb.level * 5, 0) INTO v_terraformer_bonus
FROM public.planet_buildings pb
JOIN public.building_types bt ON pb.building_type_id = bt.id
WHERE pb.planet_id = p_planet_id AND bt.code = 'terraformer';

UPDATE public.planets
SET fields_used = v_building_count
WHERE id = p_planet_id;
END;
$$;


--
-- TOC entry 947 (class 1255 OID 20422)
-- Name: recall_deployed_fleet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_deployed_fleet(p_fleet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_fleet RECORD;
  v_now timestamptz;
  v_original_flight_seconds numeric;
  v_return_time timestamptz;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_fleet
  FROM fleets
  WHERE id = p_fleet_id
  FOR UPDATE;

  IF v_fleet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Flota no encontrada');
  END IF;

  IF v_fleet.user_id != v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes retirar flotas de otros jugadores');
  END IF;

  IF v_fleet.is_completed THEN
    RETURN jsonb_build_object('success', false, 'error', 'La flota ya completo su mision');
  END IF;

  IF v_fleet.is_returning THEN
    RETURN jsonb_build_object('success', false, 'error', 'La flota ya esta regresando');
  END IF;

  IF v_fleet.mission_type != 'deploy' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo se pueden retirar flotas en mision de estacionamiento');
  END IF;

  v_now := now();

  -- Fleet must have already arrived (i.e. it's stationed, not in transit)
  IF v_fleet.arrival_time > v_now THEN
    RETURN jsonb_build_object('success', false, 'error', 'La flota aun no ha llegado. Usa cancelar flota en su lugar');
  END IF;

  -- Calculate return time = same duration as original flight
  v_original_flight_seconds := EXTRACT(EPOCH FROM (v_fleet.arrival_time - v_fleet.departure_time));
  IF v_original_flight_seconds < 10 THEN
    v_original_flight_seconds := 10;
  END IF;

  v_return_time := v_now + (v_original_flight_seconds || ' seconds')::interval;

  UPDATE fleets
  SET is_returning = true,
      arrival_time = v_now,
      return_time = v_return_time
  WHERE id = p_fleet_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Flota retirada. Regresara en ' || CEIL(v_original_flight_seconds) || ' segundos',
    'return_seconds', CEIL(v_original_flight_seconds)
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Error al retirar flota: ' || SQLERRM);
END;
$$;


--
-- TOC entry 1159 (class 1255 OID 22480)
-- Name: recall_from_fortress(integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_from_fortress(p_galaxy integer, p_ships jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_fortress record;
  v_main_planet record;
  v_ship record;
  v_existing integer;
  v_new_fleet_id uuid;
  v_distance int;
  v_slowest_speed int;
  v_flight_time int;
  v_speed_percent int;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  -- Obtener planeta principal (con coordenadas)
  SELECT id, galaxy, solar_system, position INTO v_main_planet
  FROM planets
  WHERE user_id = v_user_id AND is_main_planet = true
  LIMIT 1;

  IF v_main_planet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes planeta principal');
  END IF;

  -- Obtener fortaleza
  SELECT * INTO v_fortress
  FROM alliance_fortresses
  WHERE galaxy = p_galaxy;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Fortaleza no encontrada');
  END IF;

  -- Validar que tiene suficientes naves
  FOR v_ship IN SELECT * FROM jsonb_to_recordset(p_ships) AS x(ship_type_id integer, quantity integer)
  LOOP
    SELECT COALESCE(SUM(quantity), 0) INTO v_existing
    FROM fortress_ships
    WHERE fortress_id = v_fortress.id
      AND user_id = v_user_id
      AND ship_type_id = v_ship.ship_type_id;

    IF v_existing < v_ship.quantity THEN
      RETURN jsonb_build_object('success', false, 'error', 
        'No tienes suficientes naves tipo ' || v_ship.ship_type_id || ' en la fortaleza');
    END IF;
  END LOOP;

  -- Calcular distancia: fortaleza → planeta principal
  v_distance := fleet_calc_distance(
    p_galaxy, 250, 8,
    v_main_planet.galaxy, v_main_planet.solar_system, v_main_planet.position
  );

  -- Calcular velocidad de la nave mas lenta
  v_slowest_speed := fleet_calc_slowest_speed(p_ships, v_user_id);
  
  IF v_slowest_speed <= 0 OR v_slowest_speed > 99999999 THEN
    v_slowest_speed := 5000; -- default fallback speed
  END IF;

  -- Get fleet speed percent (default 100%)
  SELECT COALESCE((SELECT value::int FROM game_settings WHERE key = 'fleet_speed_percent'), 100)
  INTO v_speed_percent;

  -- Calcular tiempo de vuelo
  v_flight_time := fleet_calc_flight_time(v_distance, v_slowest_speed, v_speed_percent, 0);

  IF v_flight_time < 10 THEN
    v_flight_time := 10;
  END IF;

  -- Crear flota de regreso
  INSERT INTO fleets (
    user_id,
    origin_planet_id,
    target_galaxy,
    target_system,
    target_position,
    target_type,
    mission_type,
    departure_time,
    arrival_time,
    return_time,
    is_returning,
    is_completed
  ) VALUES (
    v_user_id,
    v_main_planet.id,
    v_main_planet.galaxy,
    v_main_planet.solar_system,
    v_main_planet.position,
    'planet',
    'deploy',
    now(),
    now() + (v_flight_time || ' seconds')::interval,
    now() + (v_flight_time || ' seconds')::interval,
    true,
    false
  )
  RETURNING id INTO v_new_fleet_id;

  -- Remover naves de la fortaleza y ponerlas en la flota
  FOR v_ship IN SELECT * FROM jsonb_to_recordset(p_ships) AS x(ship_type_id integer, quantity integer)
  LOOP
    -- Delete from fortress (handling CHECK constraint)
    SELECT COALESCE(SUM(quantity), 0) INTO v_existing
    FROM fortress_ships
    WHERE fortress_id = v_fortress.id
      AND user_id = v_user_id
      AND ship_type_id = v_ship.ship_type_id;

    IF v_existing = v_ship.quantity THEN
      DELETE FROM fortress_ships
      WHERE fortress_id = v_fortress.id
        AND user_id = v_user_id
        AND ship_type_id = v_ship.ship_type_id;
    ELSE
      UPDATE fortress_ships
      SET quantity = quantity - v_ship.quantity
      WHERE id = (
        SELECT id FROM fortress_ships
        WHERE fortress_id = v_fortress.id
          AND user_id = v_user_id
          AND ship_type_id = v_ship.ship_type_id
        ORDER BY deployed_at ASC
        LIMIT 1
      );
    END IF;

    -- Add to fleet
    INSERT INTO fleet_ships (fleet_id, ship_type_id, quantity)
    VALUES (v_new_fleet_id, v_ship.ship_type_id, v_ship.quantity);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Flota de regreso creada. Llegara en ' || v_flight_time || ' segundos.',
    'fleet_id', v_new_fleet_id,
    'return_time', now() + (v_flight_time || ' seconds')::interval,
    'flight_seconds', v_flight_time
  );
END;
$$;


--
-- TOC entry 1006 (class 1255 OID 20873)
-- Name: record_admin_revenue(text, numeric, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_admin_revenue(p_revenue_type text, p_amount numeric, p_description text DEFAULT NULL::text, p_related_user_id uuid DEFAULT NULL::uuid, p_related_tx_id uuid DEFAULT NULL::uuid, p_currency text DEFAULT 'FXU'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_revenue_id uuid;
  v_currency text;
BEGIN
  IF p_amount <= 0 THEN
    RETURN NULL;
  END IF;

  v_currency := UPPER(COALESCE(p_currency, 'FXU'));
  IF v_currency NOT IN ('FXU', 'USDT') THEN
    RAISE EXCEPTION 'Invalid currency for admin_revenue: %', v_currency;
  END IF;

  INSERT INTO public.admin_revenue (revenue_type, amount, currency, description, related_user_id, related_tx_id)
  VALUES (p_revenue_type, p_amount, v_currency, p_description, p_related_user_id, p_related_tx_id)
  RETURNING id INTO v_revenue_id;

  RETURN v_revenue_id;
END;
$$;


--
-- TOC entry 1152 (class 1255 OID 22404)
-- Name: regenerate_depleted_planets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.regenerate_depleted_planets() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet RECORD;
  v_count integer := 0;
  v_deposits RECORD;
  v_base_metal numeric;
BEGIN
  SELECT COALESCE(value::numeric, 40000) INTO v_base_metal
  FROM game_settings WHERE key = 'depletion_base_metal_per_field';

  FOR v_planet IN
    SELECT * FROM planets 
    WHERE planet_status = 'regenerating' 
      AND regenerates_at IS NOT NULL 
      AND regenerates_at <= now()
      AND user_id IS NULL
    FOR UPDATE SKIP LOCKED
  LOOP
    -- Recalculate deposits with fresh random values
    SELECT * INTO v_deposits FROM calculate_initial_deposits(
      v_planet.fields_max, v_planet.position, v_base_metal
    );
    
    UPDATE planets SET
      metal_deposit = v_deposits.metal_deposit,
      crystal_deposit = v_deposits.crystal_deposit,
      deuterium_deposit = v_deposits.deuterium_deposit,
      planet_status = 'active',
      depleted_at = NULL,
      regenerates_at = NULL,
      updated_at = now()
    WHERE id = v_planet.id;
    
    v_count := v_count + 1;
  END LOOP;
  
  RETURN jsonb_build_object('success', true, 'regenerated_count', v_count);
END;
$$;


--
-- TOC entry 860 (class 1255 OID 20022)
-- Name: reject_alliance_application(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_alliance_application(p_application_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_application record;
  v_membership record;
  v_alliance record;
  v_applicant_in_alliance boolean;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT * INTO v_application
  FROM alliance_applications
  WHERE id = p_application_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solicitud no encontrada');
  END IF;
  
  IF v_application.status != 'pending' THEN
    DELETE FROM alliance_applications WHERE id = p_application_id;
    RETURN jsonb_build_object('success', true, 'message', 'Solicitud eliminada');
  END IF;
  
  SELECT * INTO v_membership
  FROM alliance_members
  WHERE alliance_id = v_application.alliance_id AND user_id = v_user_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No eres miembro de esta alianza');
  END IF;
  
  IF NOT COALESCE(v_membership.can_invite, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes permiso para gestionar solicitudes');
  END IF;
  
  SELECT * INTO v_alliance
  FROM alliances
  WHERE id = v_application.alliance_id;
  
  SELECT EXISTS (
    SELECT 1 FROM alliance_members WHERE user_id = v_application.user_id
  ) INTO v_applicant_in_alliance;
  
  UPDATE alliance_applications
  SET 
    status = 'rejected',
    reviewed_at = now(),
    reviewed_by = v_user_id
  WHERE id = p_application_id;
  
  IF NOT v_applicant_in_alliance THEN
    INSERT INTO messages (recipient_id, subject, body, message_type)
    VALUES (
      v_application.user_id,
      'Solicitud rechazada - ' || v_alliance.name,
      'Tu solicitud para unirte a la alianza [' || v_alliance.tag || '] ' || v_alliance.name || ' ha sido rechazada.',
      'alliance'
    );
  END IF;
  
  RETURN jsonb_build_object('success', true, 'message', 'Solicitud rechazada');
END;
$$;


--
-- TOC entry 804 (class 1255 OID 19505)
-- Name: remove_telegram_group(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_telegram_group(p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
BEGIN
  SELECT is_admin INTO v_is_admin
  FROM profiles
  WHERE id = auth.uid();
  
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;
  
  DELETE FROM telegram_groups
  WHERE id = p_group_id;
  
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- TOC entry 865 (class 1255 OID 20028)
-- Name: repair_all_incomplete_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_all_incomplete_users() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_user record;
  v_result jsonb;
  v_ok integer := 0;
  v_fail integer := 0;
BEGIN
  FOR v_user IN 
    SELECT au.id FROM auth.users au
    LEFT JOIN profiles p ON au.id = p.id
    WHERE p.id IS NULL
  LOOP
    v_result := repair_incomplete_user(v_user.id);
    IF (v_result->>'success')::boolean THEN v_ok := v_ok + 1; ELSE v_fail := v_fail + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object('repaired', v_ok, 'failed', v_fail);
END;
$$;


--
-- TOC entry 864 (class 1255 OID 20027)
-- Name: repair_incomplete_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_incomplete_user(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_user_record record;
  v_username text;
  v_referral_code text;
  v_galaxy integer;
  v_system integer;
  v_position integer;
  v_planet_id uuid;
  v_found boolean := false;
BEGIN
  -- Obtener datos del usuario
  SELECT id, email, raw_user_meta_data INTO v_user_record
  FROM auth.users WHERE id = p_user_id;

  IF v_user_record IS NULL THEN
    RETURN '{"success":false,"error":"Usuario no existe"}'::jsonb;
  END IF;

  -- Ya tiene perfil?
  IF EXISTS (SELECT 1 FROM profiles WHERE id = p_user_id) THEN
    RETURN '{"success":true,"message":"Ya tiene perfil"}'::jsonb;
  END IF;

  -- Username
  v_username := COALESCE(
    NULLIF(TRIM(v_user_record.raw_user_meta_data->>'username'), ''),
    split_part(v_user_record.email, '@', 1),
    'user_' || substr(p_user_id::text, 1, 8)
  );

  IF EXISTS (SELECT 1 FROM profiles WHERE username = v_username) THEN
    v_username := v_username || '_' || substr(p_user_id::text, 1, 4);
  END IF;

  v_referral_code := UPPER(SUBSTRING(p_user_id::text, 1, 8));

  -- Crear perfil
  INSERT INTO profiles (id, username, email, dark_matter, fxu_balance, referral_code)
  VALUES (p_user_id, v_username, v_user_record.email, 0, 0, v_referral_code);

  -- Ya tiene planeta?
  IF EXISTS (SELECT 1 FROM planets WHERE user_id = p_user_id) THEN
    RETURN jsonb_build_object('success', true, 'profile_created', true, 'planet_existed', true);
  END IF;

  -- Buscar posicion libre
  FOR i IN 1..50 LOOP
    v_galaxy := 1 + floor(random() * 3)::integer;
    v_system := 1 + floor(random() * 200)::integer;
    v_position := 4 + floor(random() * 9)::integer;

    IF NOT EXISTS (
      SELECT 1 FROM planets 
      WHERE galaxy = v_galaxy AND solar_system = v_system AND position = v_position
    ) THEN
      v_found := true;
      EXIT;
    END IF;
  END LOOP;

  IF NOT v_found THEN
    v_galaxy := 1; v_system := 1; v_position := 1;
    WHILE EXISTS (SELECT 1 FROM planets WHERE galaxy = v_galaxy AND solar_system = v_system AND position = v_position) LOOP
      v_position := v_position + 1;
      IF v_position > 15 THEN v_position := 1; v_system := v_system + 1; END IF;
      IF v_system > 400 THEN v_system := 1; v_galaxy := v_galaxy + 1; END IF;
    END LOOP;
  END IF;

  -- Crear planeta
  INSERT INTO planets (user_id, name, galaxy, solar_system, position, planet_type, diameter, fields_max, fields_used, temp_min, temp_max, is_main_planet)
  VALUES (p_user_id, 'Planeta Principal', v_galaxy, v_system, v_position, 'planet', 12800, 163, 0, -20 + floor(random()*60)::int, 20 + floor(random()*60)::int, true)
  RETURNING id INTO v_planet_id;

  -- Crear recursos
  INSERT INTO planet_resources (planet_id, metal, crystal, deuterium, metal_per_hour, crystal_per_hour, deuterium_per_hour, energy_used, energy_max)
  VALUES (v_planet_id, 500, 300, 100, 30, 15, 0, 0, 0);

  RETURN jsonb_build_object('success', true, 'username', v_username, 'planet_id', v_planet_id, 'coords', v_galaxy||':'||v_system||':'||v_position);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- TOC entry 1101 (class 1255 OID 21692)
-- Name: report_war_battle(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_war_battle(p_war_id uuid, p_enemy_alliance_id uuid, p_resources_destroyed bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_war alliance_wars%ROWTYPE;
  v_member alliance_members%ROWTYPE;
  v_points integer;
  v_enemy_entry boolean;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_war FROM alliance_wars WHERE id = p_war_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Guerra no encontrada');
  END IF;

  IF v_war.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'error', 'La guerra no está activa');
  END IF;

  IF p_resources_destroyed <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Debes reportar al menos 1 recurso destruido');
  END IF;

  -- Check user belongs to an alliance enrolled in this war
  SELECT * INTO v_member FROM alliance_members WHERE user_id = v_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No perteneces a ninguna alianza');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM alliance_war_entries WHERE war_id = p_war_id AND alliance_id = v_member.alliance_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tu alianza no está inscrita en esta guerra');
  END IF;

  -- Can't attack your own alliance
  IF v_member.alliance_id = p_enemy_alliance_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes atacar a tu propia alianza');
  END IF;

  -- Enemy must be enrolled in this war
  SELECT EXISTS (
    SELECT 1 FROM alliance_war_entries WHERE war_id = p_war_id AND alliance_id = p_enemy_alliance_id
  ) INTO v_enemy_entry;
  IF NOT v_enemy_entry THEN
    RETURN jsonb_build_object('success', false, 'error', 'La alianza enemiga no participa en esta guerra');
  END IF;

  -- Calculate points: 1 point per 1000 resources
  v_points := FLOOR(p_resources_destroyed / 1000)::integer;
  IF v_points < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mínimo 1,000 recursos para sumar 1 punto');
  END IF;

  -- Log the battle
  INSERT INTO alliance_war_battle_log (war_id, attacker_id, attacker_alliance_id, defender_alliance_id, resources_destroyed, points)
  VALUES (p_war_id, v_user_id, v_member.alliance_id, p_enemy_alliance_id, p_resources_destroyed, v_points);

  -- Update live score
  INSERT INTO alliance_war_scores (war_id, alliance_id, total_score, battle_count)
  VALUES (p_war_id, v_member.alliance_id, v_points, 1)
  ON CONFLICT (war_id, alliance_id)
  DO UPDATE SET 
    total_score = alliance_war_scores.total_score + v_points,
    battle_count = alliance_war_scores.battle_count + 1,
    updated_at = now();

  RETURN jsonb_build_object(
    'success', true,
    'points', v_points,
    'alliance_id', v_member.alliance_id,
    'enemy_alliance_id', p_enemy_alliance_id,
    'message', '¡Batalla reportada! +' || v_points || ' pts'
  );
END;
$$;


--
-- TOC entry 677 (class 1255 OID 18857)
-- Name: request_withdrawal(numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_withdrawal(p_amount numeric, p_wallet_address text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_current_balance numeric;
  v_fee_percent numeric;
  v_fee_amount numeric;
  v_net_amount numeric;
  v_is_admin boolean;
  v_transaction_id uuid;
  v_withdrawals_enabled boolean;
  v_admin_id uuid;
  v_telegram_id bigint;
  v_is_member boolean;
  v_referrer_id uuid;
  v_referrer_share numeric;
  v_admin_share numeric;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT is_withdrawals_enabled INTO v_withdrawals_enabled
  FROM wallet_config WHERE id = 1;
  
  IF NOT v_withdrawals_enabled THEN
    RETURN jsonb_build_object('success', false, 'error', 'Los retiros estan deshabilitados temporalmente');
  END IF;
  
  SELECT telegram_id INTO v_telegram_id
  FROM telegram_links
  WHERE user_id = v_user_id;
  
  IF v_telegram_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Debes vincular tu cuenta de Telegram para poder retirar FXU. Ve a la seccion de Tareas para vincular tu Telegram.'
    );
  END IF;
  
  SELECT is_member INTO v_is_member
  FROM telegram_task_rewards
  WHERE user_id = v_user_id AND task_type = 'join_group';
  
  IF v_is_member IS NULL OR v_is_member = false THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Debes ser miembro del grupo de Telegram para poder retirar FXU. Ve a la seccion de Tareas para unirte al grupo.'
    );
  END IF;
  
  SELECT fxu_balance, is_admin INTO v_current_balance, v_is_admin
  FROM profiles
  WHERE id = v_user_id;
  
  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Monto invalido');
  END IF;
  
  IF p_amount > v_current_balance THEN
    RETURN jsonb_build_object('success', false, 'error', 'Saldo insuficiente');
  END IF;
  
  IF p_wallet_address IS NULL OR p_wallet_address = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Direccion de wallet requerida');
  END IF;
  
  IF v_is_admin THEN
    v_fee_percent := 0;
    v_fee_amount := 0;
    v_net_amount := p_amount;
    v_referrer_share := 0;
    v_admin_share := 0;
  ELSE
    SELECT withdrawal_fee_percent INTO v_fee_percent
    FROM wallet_config WHERE id = 1;
    
    v_fee_amount := p_amount * (v_fee_percent / 100);
    v_net_amount := p_amount - v_fee_amount;
    
    SELECT referred_by INTO v_referrer_id
    FROM profiles
    WHERE id = v_user_id;
    
    IF v_referrer_id IS NOT NULL THEN
      v_referrer_share := p_amount * 5 / 100;
      v_admin_share := v_fee_amount - v_referrer_share;
    ELSE
      v_referrer_share := 0;
      v_admin_share := v_fee_amount;
    END IF;
  END IF;
  
  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
  
  UPDATE profiles
  SET fxu_balance = fxu_balance - p_amount,
      updated_at = now()
  WHERE id = v_user_id;
  
  IF v_admin_share > 0 THEN
    SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
    IF v_admin_id IS NOT NULL THEN
      UPDATE profiles 
      SET fxu_balance = fxu_balance + v_admin_share,
          updated_at = now()
      WHERE id = v_admin_id;
    END IF;
  END IF;
  
  IF v_referrer_share > 0 AND v_referrer_id IS NOT NULL THEN
    UPDATE profiles 
    SET fxu_balance = fxu_balance + v_referrer_share,
        updated_at = now()
    WHERE id = v_referrer_id;
    
    INSERT INTO referral_commissions (referrer_id, seller_id, transaction_id, commission_type, fxu_amount)
    VALUES (v_referrer_id, v_user_id, NULL, 'withdrawal_referral', v_referrer_share);
    
    INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
    VALUES (
      v_referrer_id,
      v_user_id,
      'Comision de referido por retiro',
      'Has recibido ' || ROUND(v_referrer_share, 2) || ' FXU como comision por el retiro de tu referido.',
      'system'
    );
  END IF;
  
  INSERT INTO wallet_transactions (
    user_id, tx_type, amount, fxu_amount, wallet_address, status
  ) VALUES (
    v_user_id, 'withdrawal', v_net_amount, p_amount, p_wallet_address, 'pending'
  )
  RETURNING id INTO v_transaction_id;
  
  IF v_fee_amount > 0 THEN
    INSERT INTO admin_revenue (revenue_type, amount, description, related_user_id, related_tx_id)
    VALUES ('withdrawal_fee', v_admin_share, 'Comision de retiro (empresa)', v_user_id, v_transaction_id);
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'transaction_id', v_transaction_id,
    'amount', v_net_amount,
    'gross_amount', p_amount,
    'fee_amount', v_fee_amount,
    'is_admin', v_is_admin
  );
END;
$$;


