COMMENT ON FUNCTION public.request_withdrawal(p_amount numeric, p_wallet_address text) IS 'SECURITY: Uses auth.uid() - only owner can withdraw their own funds';


--
-- TOC entry 785 (class 1255 OID 19306)
-- Name: request_withdrawal_usdt(numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_withdrawal_usdt(p_amount numeric, p_wallet_address text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_usdt_balance numeric;
  v_daily_total numeric;
  v_config wallet_config%ROWTYPE;
  v_fee numeric;
  v_net_amount numeric;
  v_tx_id uuid;
  v_admin_id uuid;
  v_referrer_id uuid;
  v_referrer_share numeric;
  v_admin_share numeric;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_config FROM wallet_config WHERE id = 1;

  IF NOT v_config.is_usdt_withdrawals_enabled THEN
    RETURN jsonb_build_object('success', false, 'error', 'USDT withdrawals are currently disabled');
  END IF;

  IF p_amount < v_config.usdt_min_deposit THEN
    RETURN jsonb_build_object('success', false, 'error', 'Amount below minimum: ' || v_config.usdt_min_deposit);
  END IF;

  SELECT usdt_balance INTO v_usdt_balance FROM profiles WHERE id = v_user_id;

  IF v_usdt_balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient USDT balance');
  END IF;

  v_daily_total := get_daily_usdt_withdrawal_total(v_user_id);
  IF v_daily_total + p_amount > v_config.usdt_max_withdrawal_daily THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Daily USDT withdrawal limit exceeded. Remaining: ' || (v_config.usdt_max_withdrawal_daily - v_daily_total)
    );
  END IF;

  v_fee := p_amount * (v_config.usdt_withdrawal_fee_percent / 100);
  v_net_amount := p_amount - v_fee;

  SELECT referred_by INTO v_referrer_id
  FROM profiles
  WHERE id = v_user_id;

  IF v_referrer_id IS NOT NULL THEN
    v_referrer_share := p_amount * 5 / 100;
    v_admin_share := v_fee - v_referrer_share;
  ELSE
    v_referrer_share := 0;
    v_admin_share := v_fee;
  END IF;

  UPDATE profiles 
  SET usdt_balance = usdt_balance - p_amount,
      updated_at = now()
  WHERE id = v_user_id;

  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_share > 0 THEN
    UPDATE profiles 
    SET usdt_balance = usdt_balance + v_admin_share
    WHERE id = v_admin_id;
  END IF;

  IF v_referrer_share > 0 AND v_referrer_id IS NOT NULL THEN
    UPDATE profiles 
    SET usdt_balance = usdt_balance + v_referrer_share,
        updated_at = now()
    WHERE id = v_referrer_id;

    INSERT INTO referral_commissions (referrer_id, seller_id, transaction_id, commission_type, fxu_amount)
    VALUES (v_referrer_id, v_user_id, NULL, 'withdrawal_referral', v_referrer_share);

    INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
    VALUES (
      v_referrer_id,
      v_user_id,
      'Comision de referido por retiro USDT',
      'Has recibido ' || ROUND(v_referrer_share, 2) || ' USDT como comision por el retiro de tu referido.',
      'system'
    );
  END IF;

  INSERT INTO wallet_transactions (
    user_id, tx_type, token_type, amount, fxu_amount, wallet_address, status
  ) VALUES (
    v_user_id, 'withdrawal', 'USDT', v_net_amount, p_amount, p_wallet_address, 'pending'
  ) RETURNING id INTO v_tx_id;

  RETURN jsonb_build_object(
    'success', true,
    'transaction_id', v_tx_id,
    'amount', v_net_amount,
    'fee', v_fee,
    'message', 'USDT withdrawal request submitted'
  );
END;
$$;


--
-- TOC entry 1102 (class 1255 OID 21693)
-- Name: resolve_alliance_war(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_alliance_war(p_war_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_war alliance_wars%ROWTYPE;
  v_winner record;
  v_member record;
  v_leader_fee integer;
  v_winner_share integer;
  v_admin_share integer;
  v_reserve_share integer;
  v_remainder integer;
  v_member_count integer;
  v_per_member integer;
  v_admin_id_oldest uuid;
  v_leader_id uuid;
  v_hof record;
BEGIN
  v_admin_id := auth.uid();
  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores');
  END IF;

  SELECT * INTO v_war FROM alliance_wars WHERE id = p_war_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Guerra no encontrada');
  END IF;

  IF v_war.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'error', 'La guerra no está activa');
  END IF;

  -- Find winner (highest score, tiebreaker = most battles)
  SELECT aws.alliance_id, a.name as alliance_name, a.tag as alliance_tag, aws.total_score, aws.battle_count
  INTO v_winner
  FROM alliance_war_scores aws
  JOIN alliances a ON a.id = aws.alliance_id
  WHERE aws.war_id = p_war_id
  ORDER BY aws.total_score DESC, aws.battle_count DESC
  LIMIT 1;

  IF NOT FOUND THEN
    UPDATE alliance_wars SET status = 'cancelled', resolved_at = now() WHERE id = p_war_id;
    RETURN jsonb_build_object('success', false, 'error', 'Sin puntuaciones — guerra cancelada');
  END IF;

  -- Calculate payouts (pozo total)
  v_winner_share := FLOOR(v_war.total_pool_fxu * 0.70);  -- 70% winner
  v_admin_share := FLOOR(v_war.total_pool_fxu * 0.15);   -- 15% admin
  v_reserve_share := v_war.total_pool_fxu - v_winner_share - v_admin_share; -- 15% reserve

  -- Get entry fee paid by winner's leader
  SELECT COALESCE(paid_fee, 0) INTO v_leader_fee
  FROM alliance_war_entries
  WHERE war_id = p_war_id AND alliance_id = v_winner.alliance_id;

  -- Get winner's leader
  SELECT leader_id INTO v_leader_id FROM alliances WHERE id = v_winner.alliance_id;

  -- Leader recovers entry fee first
  IF v_leader_id IS NOT NULL AND v_leader_fee > 0 AND v_leader_fee <= v_winner_share THEN
    PERFORM _internal_set_fxu_context();
    UPDATE profiles SET fxu_balance = fxu_balance + v_leader_fee WHERE id = v_leader_id;
    v_remainder := v_winner_share - v_leader_fee;
  ELSE
    v_remainder := v_winner_share;
  END IF;

  -- Rest divided equally among all members
  SELECT COUNT(*) INTO v_member_count FROM alliance_members WHERE alliance_id = v_winner.alliance_id;
  IF v_member_count > 0 AND v_remainder > 0 THEN
    v_per_member := FLOOR(v_remainder / v_member_count);
    FOR v_member IN
      SELECT user_id FROM alliance_members WHERE alliance_id = v_winner.alliance_id
    LOOP
      UPDATE profiles SET fxu_balance = fxu_balance + v_per_member WHERE id = v_member.user_id;
    END LOOP;
  END IF;

  -- 15% to admin
  IF v_admin_share > 0 THEN
    SELECT id INTO v_admin_id_oldest FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
    IF v_admin_id_oldest IS NOT NULL THEN
      PERFORM _internal_set_fxu_context();
      UPDATE profiles SET fxu_balance = fxu_balance + v_admin_share WHERE id = v_admin_id_oldest;
    END IF;
    PERFORM record_admin_revenue('alliance_war', v_admin_share, 'War admin share: ' || v_war.title, v_winner.alliance_id, NULL);
  END IF;

  -- 15% to reserve pool
  IF v_reserve_share > 0 THEN
    UPDATE alliance_war_reserve_pool SET amount_fxu = amount_fxu + v_reserve_share, updated_at = now()
    WHERE id = '00000000-0000-0000-0000-000000000001'::uuid;
  END IF;

  -- Mark war as completed
  UPDATE alliance_wars 
  SET status = 'completed', 
      winner_alliance_id = v_winner.alliance_id, 
      resolved_at = now() 
  WHERE id = p_war_id;

  -- Update Hall of Fame
  SELECT * INTO v_hof FROM alliance_war_hall_of_fame WHERE alliance_id = v_winner.alliance_id;
  IF NOT FOUND THEN
    INSERT INTO alliance_war_hall_of_fame (alliance_id, alliance_name, alliance_tag, total_wins, total_wars, total_fxu_won, last_win_at)
    VALUES (v_winner.alliance_id, v_winner.alliance_name, v_winner.alliance_tag, 1, 1, v_winner_share, now());
  ELSE
    UPDATE alliance_war_hall_of_fame
    SET total_wins = total_wins + 1,
        total_wars = total_wars + 1,
        total_fxu_won = total_fxu_won + v_winner_share,
        last_win_at = now(),
        alliance_name = v_winner.alliance_name,
        alliance_tag = v_winner.alliance_tag
    WHERE alliance_id = v_winner.alliance_id;
  END IF;

  -- Update total_wars counter for losers
  UPDATE alliance_war_hall_of_fame SET total_wars = total_wars + 1
  FROM alliance_war_entries awe
  WHERE alliance_war_hall_of_fame.alliance_id = awe.alliance_id
    AND awe.war_id = p_war_id
    AND awe.alliance_id != v_winner.alliance_id;

  RETURN jsonb_build_object(
    'success', true,
    'winner_alliance', v_winner.alliance_name,
    'winner_score', v_winner.total_score,
    'winner_share', v_winner_share,
    'leader_refund', v_leader_fee,
    'per_member', v_per_member,
    'admin_share', v_admin_share,
    'reserve_share', v_reserve_share
  );
END;
$$;


--
-- TOC entry 1161 (class 1255 OID 22482)
-- Name: resolve_fortress_attack(integer, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_fortress_attack(p_galaxy integer, p_attacker_id uuid, p_attacker_alliance_id uuid, p_attacker_ships jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fortress record; v_combat_result jsonb; v_winner text; v_ship record;
  v_attacker_units jsonb := '[]'::jsonb; v_defender_units jsonb := '[]'::jsonb;
  v_weapon_bonus numeric; v_shield_bonus numeric; v_hull_bonus numeric; v_st record;
  v_debris_metal numeric := 0; v_debris_crystal numeric := 0;
  v_defender_alliance_id uuid; v_attacker_alliance_name text; v_defender_alliance_name text;
  v_can_claim boolean;
BEGIN
  v_can_claim := p_attacker_alliance_id IS NOT NULL;

  SELECT * INTO v_fortress FROM alliance_fortresses WHERE galaxy = p_galaxy;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Fortaleza no encontrada'); END IF;

  SELECT COALESCE(name,'Desconocida') INTO v_attacker_alliance_name FROM alliances WHERE id = p_attacker_alliance_id;
  SELECT COALESCE(name,'Sin Alianza') INTO v_defender_alliance_name FROM alliances WHERE id = v_fortress.owner_alliance_id;
  v_defender_alliance_id := v_fortress.owner_alliance_id;

  SELECT COALESCE((SELECT ut.level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id=tt.id WHERE ut.user_id=p_attacker_id AND tt.code='weapons_technology'),0),
         COALESCE((SELECT ut.level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id=tt.id WHERE ut.user_id=p_attacker_id AND tt.code='shielding_technology'),0),
         COALESCE((SELECT ut.level FROM user_technologies ut JOIN technology_types tt ON ut.technology_type_id=tt.id WHERE ut.user_id=p_attacker_id AND tt.code='armour_technology'),0)
  INTO v_weapon_bonus, v_shield_bonus, v_hull_bonus;

  FOR v_ship IN SELECT * FROM jsonb_to_recordset(p_attacker_ships) AS x(ship_type_id integer, quantity integer) LOOP
    SELECT * INTO v_st FROM ship_types WHERE id=v_ship.ship_type_id;
    IF v_st IS NOT NULL AND v_ship.quantity>0 THEN
      v_attacker_units := v_attacker_units || jsonb_build_object('type_id',v_ship.ship_type_id,'code',v_st.code,'name',v_st.name,'quantity',v_ship.quantity,'weapon',FLOOR(v_st.weapon_power*(1+v_weapon_bonus*0.10)),'shield',FLOOR(v_st.shield_power*(1+v_shield_bonus*0.10)),'hull',FLOOR(v_st.structural_integrity*(1+v_hull_bonus*0.10)),'metal_cost',v_st.metal_cost,'crystal_cost',v_st.crystal_cost,'rapid_fire',v_st.rapid_fire,'is_defense',false);
    END IF;
  END LOOP;

  IF v_fortress.owner_alliance_id IS NULL THEN
    IF v_can_claim THEN
      UPDATE alliance_fortresses SET owner_alliance_id=p_attacker_alliance_id, captured_at=now() WHERE id=v_fortress.id;
      FOR v_ship IN SELECT * FROM jsonb_to_recordset(p_attacker_ships) AS x(ship_type_id integer, quantity integer) LOOP
        IF v_ship.quantity>0 THEN INSERT INTO fortress_ships(fortress_id,user_id,alliance_id,ship_type_id,quantity) VALUES(v_fortress.id,p_attacker_id,p_attacker_alliance_id,v_ship.ship_type_id,v_ship.quantity); END IF;
      END LOOP;
    END IF;
    v_combat_result := jsonb_build_object('result','attacker_won','rounds',0,'rounds_data','[]'::jsonb,'attacker_initial',v_attacker_units,'defender_initial','[]'::jsonb,'attacker_remaining',v_attacker_units,'defender_remaining','[]'::jsonb,'attacker_losses_metal',0,'attacker_losses_crystal',0,'defender_losses_metal',0,'defender_losses_crystal',0,'debris_metal',0,'debris_crystal',0);
    RETURN jsonb_build_object('success',true,'result',CASE WHEN v_can_claim THEN 'captured' ELSE 'won_no_claim' END,'combat',v_combat_result,'message',CASE WHEN v_can_claim THEN 'Fortaleza capturada sin resistencia.' ELSE 'Victoria! Pero necesitas una alianza para reclamar la fortaleza.' END);
  END IF;

  IF v_fortress.owner_alliance_id = p_attacker_alliance_id THEN RETURN jsonb_build_object('success',false,'error','No puedes atacar tu propia fortaleza'); END IF;

  FOR v_ship IN SELECT fs.ship_type_id, SUM(fs.quantity) as total_qty FROM fortress_ships fs WHERE fs.fortress_id=v_fortress.id GROUP BY fs.ship_type_id LOOP
    SELECT * INTO v_st FROM ship_types WHERE id=v_ship.ship_type_id;
    IF v_st IS NOT NULL AND v_ship.total_qty>0 THEN v_defender_units:=v_defender_units||jsonb_build_object('type_id',v_ship.ship_type_id,'code',v_st.code,'name',v_st.name,'quantity',v_ship.total_qty,'weapon',v_st.weapon_power,'shield',v_st.shield_power,'hull',v_st.structural_integrity,'metal_cost',v_st.metal_cost,'crystal_cost',v_st.crystal_cost,'rapid_fire',v_st.rapid_fire,'is_defense',false); END IF;
  END LOOP;

  v_combat_result:=simulate_xnova_combat(v_attacker_units,v_defender_units); v_winner:=v_combat_result->>'result';
  v_combat_result:=v_combat_result||jsonb_build_object('attacker_initial',v_attacker_units)||jsonb_build_object('defender_initial',v_defender_units);

  v_debris_metal:=COALESCE((v_combat_result->>'debris_metal')::numeric,0); v_debris_crystal:=COALESCE((v_combat_result->>'debris_crystal')::numeric,0);
  IF v_debris_metal>0 OR v_debris_crystal>0 THEN INSERT INTO debris_fields(galaxy,solar_system,position,metal,crystal,created_at,updated_at) VALUES(v_fortress.galaxy,v_fortress.system,v_fortress.position,v_debris_metal,v_debris_crystal,now(),now()) ON CONFLICT(galaxy,solar_system,position) DO UPDATE SET metal=debris_fields.metal+EXCLUDED.metal,crystal=debris_fields.crystal+EXCLUDED.crystal,updated_at=now(); END IF;

  IF v_winner='attacker_won' THEN
    DELETE FROM fortress_ships WHERE fortress_id=v_fortress.id;
    IF v_can_claim AND v_combat_result->'attacker_remaining' IS NOT NULL THEN
      FOR v_ship IN SELECT * FROM jsonb_to_recordset(v_combat_result->'attacker_remaining') AS x(type_id integer, quantity integer) LOOP
        IF v_ship.quantity>0 THEN INSERT INTO fortress_ships(fortress_id,user_id,alliance_id,ship_type_id,quantity) VALUES(v_fortress.id,p_attacker_id,p_attacker_alliance_id,v_ship.type_id,v_ship.quantity); END IF;
      END LOOP;
    END IF;
    IF v_can_claim THEN UPDATE alliance_fortresses SET owner_alliance_id=p_attacker_alliance_id,captured_at=now() WHERE id=v_fortress.id; END IF;
    INSERT INTO battle_reports(attacker_id,defender_id,coordinates,battle_type,result,rounds,attacker_losses_metal,attacker_losses_crystal,defender_losses_metal,defender_losses_crystal,debris_metal,debris_crystal,galaxy,solar_system,position,report_data,created_at) VALUES(p_attacker_id,(SELECT leader_id FROM alliances WHERE id=v_defender_alliance_id),'[' || v_fortress.galaxy || ':' || v_fortress.system || ':' || v_fortress.position || ']','fortress','attacker_won',COALESCE(jsonb_array_length(v_combat_result->'rounds_data'), 0),COALESCE((v_combat_result->>'attacker_losses_metal')::numeric,0),COALESCE((v_combat_result->>'attacker_losses_crystal')::numeric,0),COALESCE((v_combat_result->>'defender_losses_metal')::numeric,0),COALESCE((v_combat_result->>'defender_losses_crystal')::numeric,0),v_debris_metal,v_debris_crystal,v_fortress.galaxy,v_fortress.system,v_fortress.position,jsonb_build_object('battle_type','fortress','attacker_alliance',v_attacker_alliance_name,'defender_alliance',v_defender_alliance_name,'rounds_data',v_combat_result->'rounds_data','attacker_initial',v_attacker_units,'defender_initial',v_defender_units,'attacker_remaining',v_combat_result->'attacker_remaining','defender_remaining','[]'::jsonb),now());
    RETURN jsonb_build_object('success',true,'result',CASE WHEN v_can_claim THEN 'captured' ELSE 'won_no_claim' END,'combat',v_combat_result,'message',CASE WHEN v_can_claim THEN 'Fortaleza capturada!' ELSE 'Victoria! Pero necesitas una alianza para reclamar la fortaleza.' END);
  END IF;

  INSERT INTO battle_reports(attacker_id,defender_id,coordinates,battle_type,result,rounds,attacker_losses_metal,attacker_losses_crystal,defender_losses_metal,defender_losses_crystal,debris_metal,debris_crystal,galaxy,solar_system,position,report_data,created_at) VALUES(p_attacker_id,(SELECT leader_id FROM alliances WHERE id=v_defender_alliance_id),'[' || v_fortress.galaxy || ':' || v_fortress.system || ':' || v_fortress.position || ']','fortress',v_winner,COALESCE(jsonb_array_length(v_combat_result->'rounds_data'), 0),COALESCE((v_combat_result->>'attacker_losses_metal')::numeric,0),COALESCE((v_combat_result->>'attacker_losses_crystal')::numeric,0),COALESCE((v_combat_result->>'defender_losses_metal')::numeric,0),COALESCE((v_combat_result->>'defender_losses_crystal')::numeric,0),v_debris_metal,v_debris_crystal,v_fortress.galaxy,v_fortress.system,v_fortress.position,jsonb_build_object('battle_type','fortress','attacker_alliance',v_attacker_alliance_name,'defender_alliance',v_defender_alliance_name,'rounds_data',v_combat_result->'rounds_data','attacker_initial',v_attacker_units,'defender_initial',v_defender_units,'attacker_remaining',v_combat_result->'attacker_remaining','defender_remaining',v_combat_result->'defender_remaining'),now());
  RETURN jsonb_build_object('success',true,'result',CASE WHEN v_winner='defender_won' THEN 'defender_won' ELSE 'draw' END,'combat',v_combat_result,'message',CASE WHEN v_winner='defender_won' THEN 'La fortaleza resistio el ataque' ELSE 'Empate tactico' END);
END;
$$;


--
-- TOC entry 1091 (class 1255 OID 21551)
-- Name: resolve_hero_duel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_hero_duel(p_duel_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_duel record;
  v_creator_ship record;
  v_opponent_ship record;
  v_creator_power numeric;
  v_opponent_power numeric;
  v_winner_id uuid;
  v_loser_id uuid;
  v_winner_bet integer;
  v_admin_id uuid;
  v_referrer_id uuid;
  v_winner_hp_loss integer;
  v_total_power numeric;
  -- Fee split variables
  v_fee integer;
  v_admin_fee integer;
  v_pool_fee integer;
  v_referral_fee integer;
  v_admin_share numeric;
  v_pool_share numeric;
  v_referral_share numeric;
BEGIN
  SELECT * INTO v_duel FROM hero_duels WHERE id = p_duel_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Duelo no encontrado');
  END IF;

  IF v_duel.status = 'completed' THEN
    RETURN jsonb_build_object('success', true, 'already_resolved', true,
      'winner_id', v_duel.winner_id,
      'loser_id', v_duel.loser_id);
  END IF;

  IF v_duel.status != 'accepted' THEN
    RETURN jsonb_build_object('success', false, 'error', 'El duelo no esta en estado aceptado');
  END IF;

  IF now() < v_duel.resolves_at THEN
    RETURN jsonb_build_object('success', false, 'error', 'El duelo aun no llega al punto de batalla');
  END IF;

  SELECT * INTO v_creator_ship FROM user_hero_ships WHERE user_id = v_duel.creator_id;
  SELECT * INTO v_opponent_ship FROM user_hero_ships WHERE user_id = v_duel.opponent_id;

  v_creator_power :=
    COALESCE(v_creator_ship.attack_points, 0) * 3 +
    COALESCE(v_creator_ship.defense_points, 0) * 2 +
    COALESCE(v_creator_ship.shield_points, 0) * 1.5 +
    COALESCE(v_creator_ship.speed_points, 0) +
    COALESCE(v_creator_ship.level, 1) * 5 +
    (GREATEST(COALESCE(v_duel.creator_hp_before, 100), 0)::numeric / GREATEST(COALESCE(v_creator_ship.hp_max, 100), 1)) * 50;

  v_opponent_power :=
    COALESCE(v_opponent_ship.attack_points, 0) * 3 +
    COALESCE(v_opponent_ship.defense_points, 0) * 2 +
    COALESCE(v_opponent_ship.shield_points, 0) * 1.5 +
    COALESCE(v_opponent_ship.speed_points, 0) +
    COALESCE(v_opponent_ship.level, 1) * 5 +
    (GREATEST(COALESCE(v_duel.opponent_hp_before, 100), 0)::numeric / GREATEST(COALESCE(v_opponent_ship.hp_max, 100), 1)) * 50;

  -- Determine winner
  IF random() * (v_creator_power + v_opponent_power) <= v_creator_power THEN
    v_winner_id := v_duel.creator_id;
    v_loser_id := v_duel.opponent_id;
  ELSE
    v_winner_id := v_duel.opponent_id;
    v_loser_id := v_duel.creator_id;
  END IF;

  -- Read configurable shares (same keys as main market)
  SELECT COALESCE(value::numeric, 40) INTO v_admin_share FROM game_settings WHERE key = 'market_fee_admin_share';
  SELECT COALESCE(value::numeric, 30) INTO v_pool_share FROM game_settings WHERE key = 'market_fee_pool_share';
  SELECT COALESCE(value::numeric, 30) INTO v_referral_share FROM game_settings WHERE key = 'market_fee_referral_share';

  -- Fee = 20% of one stake
  v_fee := CEIL(v_duel.stake * 0.2);
  -- Winner gets: both stakes back minus fee = 2 * stake - fee
  v_winner_bet := 2 * v_duel.stake - v_fee;

  -- 4-3-3 split of the fee
  v_admin_fee := FLOOR(v_fee * v_admin_share / 100);
  v_pool_fee := FLOOR(v_fee * v_pool_share / 100);
  v_referral_fee := FLOOR(v_fee * v_referral_share / 100);

  -- Referrer: from the referral share (falls back to pool if no referrer)
  SELECT referred_by INTO v_referrer_id FROM profiles WHERE id = v_winner_id;
  IF v_referrer_id IS NOT NULL AND v_referral_fee > 0 THEN
    -- Paid from the referral share
    NULL; -- will be paid below
  ELSE
    -- No referrer → referral share goes to pool
    v_pool_fee := v_pool_fee + v_referral_fee;
    v_referral_fee := 0;
  END IF;

  -- Apply HP damage from combat
  v_total_power := GREATEST(v_creator_power + v_opponent_power, 1);
  IF v_winner_id = v_duel.creator_id THEN
    v_winner_hp_loss := CEIL((v_opponent_power / v_total_power) * v_creator_ship.hp_max);
    UPDATE user_hero_ships SET hp = GREATEST(1, hp - v_winner_hp_loss), updated_at = now() WHERE user_id = v_winner_id;
  ELSE
    v_winner_hp_loss := CEIL((v_creator_power / v_total_power) * v_opponent_ship.hp_max);
    UPDATE user_hero_ships SET hp = GREATEST(1, hp - v_winner_hp_loss), updated_at = now() WHERE user_id = v_winner_id;
  END IF;
  UPDATE user_hero_ships SET hp = 1, updated_at = now() WHERE user_id = v_loser_id;

  -- Distribute FXU
  PERFORM _internal_set_fxu_context();
  -- Both players already paid their stake at create/accept (total = 2 * stake)
  -- Pay winner
  UPDATE profiles SET fxu_balance = fxu_balance + v_winner_bet WHERE id = v_winner_id;
  -- Loser already paid at acceptance, no further deduction

  -- Admin fee
  SELECT get_admin_account_id() INTO v_admin_id;
  IF v_admin_id IS NOT NULL AND v_admin_fee > 0 THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_admin_fee WHERE id = v_admin_id;
    PERFORM record_admin_revenue('hero_duel', v_admin_fee,
      'Hero duel fee (' || v_admin_share || '% admin, ' || v_pool_share || '% pool, ' || v_referral_share || '% referral)',
      v_winner_id, p_duel_id);
  END IF;

  -- Pool contribution
  IF v_pool_fee > 0 THEN
    PERFORM contribute_to_jackpot(v_pool_fee::numeric, 'hero_duel', v_winner_id);
  END IF;

  -- Referrer reward (from the fee split, not additional)
  IF v_referrer_id IS NOT NULL AND v_referral_fee > 0 THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_referral_fee WHERE id = v_referrer_id;
  END IF;

  UPDATE hero_duels SET
    status = 'completed',
    winner_id = v_winner_id,
    loser_id = v_loser_id,
    updated_at = now()
  WHERE id = p_duel_id;

  -- Winner XP gain (scaled by level difference)
  DECLARE
    v_level_diff integer;
    v_xp_gain integer;
  BEGIN
    v_level_diff := GREATEST(1, COALESCE((SELECT level FROM user_hero_ships WHERE user_id = v_loser_id), 1) - COALESCE((SELECT level FROM user_hero_ships WHERE user_id = v_winner_id), 1));
    v_xp_gain := 50 + v_level_diff * 10 + FLOOR(v_duel.stake / 10);
    UPDATE user_hero_ships SET xp = xp + v_xp_gain, updated_at = now() WHERE user_id = v_winner_id;
  END;

  RETURN jsonb_build_object('success', true,
    'winner_id', v_winner_id,
    'loser_id', v_loser_id,
    'winner_amount', v_winner_bet,
    'winner_hp_loss', v_winner_hp_loss);
END;
$$;


--
-- TOC entry 853 (class 1255 OID 20013)
-- Name: respond_diplomacy(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_diplomacy(p_diplomacy_id uuid, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_alliance_id uuid;
  v_can_edit boolean;
  v_diplomacy record;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  -- Get user's alliance and permissions
  SELECT alliance_id, can_edit INTO v_user_alliance_id, v_can_edit
  FROM alliance_members
  WHERE user_id = v_user_id;
  
  IF NOT COALESCE(v_can_edit, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes permiso para gestionar diplomacia');
  END IF;
  
  -- Get diplomacy record
  SELECT * INTO v_diplomacy
  FROM alliance_diplomacy
  WHERE id = p_diplomacy_id AND status = 'pending';
  
  IF v_diplomacy IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Propuesta no encontrada o ya procesada');
  END IF;
  
  -- Only target alliance can respond
  IF v_diplomacy.target_alliance_id != v_user_alliance_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo la alianza objetivo puede responder');
  END IF;
  
  -- Update diplomacy status
  UPDATE alliance_diplomacy
  SET 
    status = CASE WHEN p_accept THEN 'active' ELSE 'rejected' END,
    responded_by = v_user_id,
    accepted_at = CASE WHEN p_accept THEN now() ELSE NULL END
  WHERE id = p_diplomacy_id;
  
  -- Send notification to proposing alliance
  INSERT INTO messages (recipient_id, subject, body, message_type)
  SELECT 
    a.leader_id,
    CASE 
      WHEN p_accept THEN 'Propuesta Diplomatica Aceptada'
      ELSE 'Propuesta Diplomatica Rechazada'
    END,
    'La alianza ' || (SELECT name FROM alliances WHERE id = v_user_alliance_id) || 
    CASE 
      WHEN p_accept THEN ' ha aceptado tu propuesta de ' 
      ELSE ' ha rechazado tu propuesta de '
    END ||
    CASE v_diplomacy.diplomacy_type
      WHEN 'nap' THEN 'Pacto de No Agresion'
      WHEN 'trade' THEN 'Pacto Comercial'
    END || '.',
    'alliance'
  FROM alliances a
  WHERE a.id = v_diplomacy.alliance_id AND a.leader_id IS NOT NULL;
  
  RETURN jsonb_build_object(
    'success', true, 
    'message', CASE WHEN p_accept THEN 'Propuesta aceptada' ELSE 'Propuesta rechazada' END
  );
END;
$$;


--
-- TOC entry 771 (class 1255 OID 19274)
-- Name: review_multiaccounting_report(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_multiaccounting_report(p_report_id uuid, p_status text, p_review_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  
  UPDATE multiaccounting_reports
  SET 
    status = p_status,
    review_notes = p_review_notes,
    reviewed_by = auth.uid(),
    reviewed_at = now()
  WHERE id = p_report_id;
  
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- TOC entry 671 (class 1255 OID 18778)
-- Name: safe_deduct_resources(uuid, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safe_deduct_resources(p_planet_id uuid, p_metal bigint, p_crystal bigint, p_deuterium bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_resources RECORD;
BEGIN
  -- Get current resources with row lock (previene race conditions)
  SELECT metal, crystal, deuterium 
  INTO v_resources 
  FROM planet_resources 
  WHERE planet_id = p_planet_id
  FOR UPDATE;
  
  -- Check if we have enough resources
  IF v_resources.metal < p_metal OR 
     v_resources.crystal < p_crystal OR 
     v_resources.deuterium < p_deuterium THEN
    RETURN false;
  END IF;
  
  -- Deduct resources (CHECK constraints prevendrán valores negativos)
  UPDATE planet_resources
  SET 
    metal = metal - p_metal,
    crystal = crystal - p_crystal,
    deuterium = deuterium - p_deuterium,
    last_update = now()
  WHERE planet_id = p_planet_id;
  
  RETURN true;
END;
$$;


--
-- TOC entry 1171 (class 1255 OID 22726)
-- Name: save_ai_custom_orders(uuid, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_ai_custom_orders(p_planet_id uuid, p_buildings jsonb DEFAULT '{}'::jsonb, p_ships jsonb DEFAULT '{}'::jsonb, p_defenses jsonb DEFAULT '{}'::jsonb, p_research jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE
      v_user_id uuid;
    BEGIN
      -- Get planet owner
      SELECT user_id INTO v_user_id FROM planets WHERE id = p_planet_id;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Planeta no encontrado');
      END IF;
      
      -- Security: only planet owner can save
      IF v_user_id != auth.uid() THEN
        RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
      END IF;
      
      INSERT INTO ai_planet_custom_orders (planet_id, user_id, buildings, ships, defenses, research)
      VALUES (p_planet_id, v_user_id, p_buildings, p_ships, p_defenses, p_research)
      ON CONFLICT (planet_id)
      DO UPDATE SET
        buildings = EXCLUDED.buildings,
        ships = EXCLUDED.ships,
        defenses = EXCLUDED.defenses,
        research = EXCLUDED.research,
        updated_at = now();
      
      RETURN jsonb_build_object('success', true);
    END;
    $$;


--
-- TOC entry 928 (class 1255 OID 20383)
-- Name: secure_abandon_colony(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_abandon_colony(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$

DECLARE
  v_planet planets%ROWTYPE;
  v_fxu_fee numeric;
  v_user_fxu numeric;
  v_admin_id uuid;
  v_active_fleet_count integer;
  v_building_queue_count integer;
  v_shipyard_queue_count integer;
  v_research_on_planet boolean;
  v_regeneration_days integer;
BEGIN
  -- Authentication check
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Vacation mode check
  IF is_user_in_vacation_mode(auth.uid()) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot abandon colony while in vacation mode');
  END IF;

  -- Validate planet ownership
  SELECT * INTO v_planet
  FROM planets
  WHERE id = p_planet_id AND user_id = auth.uid();

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not found or not owned');
  END IF;

  -- Cannot abandon homeworld
  IF v_planet.is_main_planet THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot abandon your homeworld');
  END IF;

  -- ⚡ DEPLETION: If planet is depleted, use depletion flow instead of destruction
  IF v_planet.planet_status = 'depleted' THEN
    SELECT COALESCE(value::integer, 30) INTO v_regeneration_days
    FROM game_settings WHERE key = 'depletion_regeneration_days';
    
    -- Clear planet ownership and mark for regeneration
    UPDATE planets SET
      user_id = NULL,
      planet_status = 'regenerating',
      regenerates_at = now() + (v_regeneration_days || ' days')::interval,
      last_update = now()
    WHERE id = p_planet_id;
    
    -- Delete related data (buildings, ships, defenses, resources)
    DELETE FROM planet_buildings WHERE planet_id = p_planet_id;
    DELETE FROM planet_ships WHERE planet_id = p_planet_id;
    DELETE FROM planet_defenses WHERE planet_id = p_planet_id;
    DELETE FROM planet_resources WHERE planet_id = p_planet_id;
    DELETE FROM building_queue WHERE planet_id = p_planet_id;
    DELETE FROM shipyard_queue WHERE planet_id = p_planet_id;
    DELETE FROM supply_box_purchases WHERE planet_id = p_planet_id;
    
    -- Nullify references
    UPDATE fleets SET origin_planet_id = NULL WHERE origin_planet_id = p_planet_id;
    UPDATE market_listings SET planet_id = NULL WHERE planet_id = p_planet_id;
    UPDATE user_technologies SET research_planet_id = NULL WHERE research_planet_id = p_planet_id;
    UPDATE galaxy_positions SET occupied_by = NULL, is_occupied = false WHERE occupied_by = p_planet_id;
    
    -- Reset fields
    UPDATE planets SET fields_used = 0 WHERE id = p_planet_id;
    
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Colony abandoned. Planet will regenerate in ' || v_regeneration_days || ' days.',
      'regenerates_at', now() + (v_regeneration_days || ' days')::interval
    );
  END IF;

  -- Check for active building queue on this planet
  SELECT COUNT(*) INTO v_building_queue_count
  FROM building_queue
  WHERE planet_id = p_planet_id;

  IF v_building_queue_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot abandon planet with active building queue');
  END IF;

  -- Check for active shipyard queue
  SELECT COUNT(*) INTO v_shipyard_queue_count
  FROM shipyard_queue
  WHERE planet_id = p_planet_id;

  IF v_shipyard_queue_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot abandon planet with active shipyard queue');
  END IF;

  -- Check for research on this planet
  SELECT EXISTS(
    SELECT 1 FROM user_technologies
    WHERE research_planet_id = p_planet_id AND is_researching = true
  ) INTO v_research_on_planet;

  IF v_research_on_planet THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot abandon planet with active research');
  END IF;

  -- Check for active fleets from this planet
  SELECT COUNT(*) INTO v_active_fleet_count
  FROM fleets
  WHERE origin_planet_id = p_planet_id AND arrival_time > now();

  IF v_active_fleet_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot abandon planet with active fleets');
  END IF;

  -- Get FXU fee
  SELECT COALESCE(value::numeric, 10000) INTO v_fxu_fee
  FROM game_settings WHERE key = 'fxu_abandon_colony_fee';

  -- Check FXU balance
  SELECT fxu_balance INTO v_user_fxu
  FROM profiles WHERE id = auth.uid();

  IF v_user_fxu < v_fxu_fee THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient FXU. Required: ' || v_fxu_fee || ' FXU');
  END IF;

  -- Deduct FXU
  PERFORM set_config('app.fxu_update_allowed', 'abandon_colony', true);
  UPDATE profiles SET fxu_balance = fxu_balance - v_fxu_fee WHERE id = auth.uid();

  -- Pay admin
  SELECT get_admin_account_id() INTO v_admin_id;
  IF v_admin_id IS NOT NULL AND v_admin_id != auth.uid() THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_fxu_fee WHERE id = v_admin_id;
  END IF;

  -- Delete planet (cascading)
  -- DELETE FROM planets WHERE id = p_planet_id; -- replaced by ruin logic below

    -- [ABANDON RUINS] Clear data, leave planet as grey uninhabitable ruin
  DELETE FROM planet_buildings WHERE planet_id = p_planet_id;
  DELETE FROM planet_ships WHERE planet_id = p_planet_id;
  DELETE FROM planet_defenses WHERE planet_id = p_planet_id;
  DELETE FROM planet_resources WHERE planet_id = p_planet_id;
  DELETE FROM building_queue WHERE planet_id = p_planet_id;
  DELETE FROM shipyard_queue WHERE planet_id = p_planet_id;
  UPDATE fleets SET origin_planet_id = NULL WHERE origin_planet_id = p_planet_id;
  UPDATE market_listings SET planet_id = NULL WHERE planet_id = p_planet_id;
  UPDATE user_technologies SET research_planet_id = NULL WHERE research_planet_id = p_planet_id;
  UPDATE planets SET user_id = NULL, name = 'Ruinas', planet_status = 'abandoned', fields_used = 0, is_destroyed = true WHERE id = p_planet_id;
  UPDATE galaxy_positions SET occupied_by = NULL, is_occupied = false WHERE occupied_by = p_planet_id;
  
  RETURN jsonb_build_object('success', true, 'message', 'Colonia abandonada. Las ruinas permanecen.');
END;

$$;


--
-- TOC entry 850 (class 1255 OID 19967)
-- Name: secure_activate_building_queue(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_activate_building_queue(p_planet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_planet RECORD;
  v_first_item RECORD;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  -- Verify ownership
  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id AND user_id = v_user_id;
  IF v_planet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not owned by user');
  END IF;
  
  -- Get first queue item
  SELECT * INTO v_first_item 
  FROM building_queue 
  WHERE planet_id = p_planet_id AND queue_position = 1;
  
  IF v_first_item IS NULL THEN
    RETURN jsonb_build_object('success', true, 'message', 'No items in queue');
  END IF;
  
  -- Only activate if not already started
  IF v_first_item.start_time IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'message', 'Already started');
  END IF;
  
  -- Activate with server time
  UPDATE building_queue
  SET 
    start_time = now(),
    end_time = now() + (build_time || ' seconds')::interval
  WHERE id = v_first_item.id;
  
  RETURN jsonb_build_object(
    'success', true,
    'activated_id', v_first_item.id,
    'end_time', now() + (v_first_item.build_time || ' seconds')::interval
  );
END;
$$;


--
-- TOC entry 627 (class 1255 OID 18567)
-- Name: secure_add_to_building_queue(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_add_to_building_queue(p_planet_id uuid, p_building_type_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$

 
DECLARE
v_validation jsonb;
v_planet RECORD;
v_building_type RECORD;
v_current_level integer;
v_queued_count integer;
v_target_level integer;
v_resources RECORD;
v_cost_metal bigint;
v_cost_crystal bigint;
v_cost_deuterium bigint;
v_queue_position integer;
v_robotics_level integer;
v_nanite_level integer;
v_build_time integer;
v_is_first boolean;
v_start_time timestamptz;
v_end_time timestamptz;
v_total_queued_levels integer;
v_game_speed integer;
v_is_moon boolean;
v_moon_only_buildings text[];
v_planet_only_buildings text[];
v_has_active_research boolean;
BEGIN
IF auth.uid() IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
END IF;

IF is_user_in_vacation_mode(auth.uid()) THEN
RETURN jsonb_build_object('success', false, 'error', 'Cannot build while in vacation mode');
END IF;

SELECT * INTO v_planet FROM planets WHERE id = p_planet_id AND user_id = auth.uid();
IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Planet not found or not owned');
END IF;

SELECT * INTO v_building_type FROM building_types WHERE id = p_building_type_id;
IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Building type not found');
END IF;

v_is_moon := v_planet.planet_type = 'moon';
v_moon_only_buildings := get_moon_only_buildings();
v_planet_only_buildings := get_planet_only_buildings();

IF v_building_type.code = ANY(v_moon_only_buildings) AND NOT v_is_moon THEN
RETURN jsonb_build_object('success', false, 'error', 'This building can only be built on a moon');
END IF;

IF v_building_type.code = ANY(v_planet_only_buildings) AND v_is_moon THEN
RETURN jsonb_build_object('success', false, 'error', 'This building cannot be built on a moon');
END IF;

IF v_building_type.code = 'research_lab' THEN
SELECT EXISTS(
SELECT 1 FROM user_technologies
WHERE user_id = auth.uid() AND is_researching = true
) INTO v_has_active_research;

IF v_has_active_research THEN
RETURN jsonb_build_object('success', false, 'error', 'Cannot upgrade Research Lab while research is in progress');
END IF;
END IF;

SELECT COALESCE(COUNT(*), 0) INTO v_total_queued_levels FROM building_queue WHERE planet_id = p_planet_id;
IF (v_planet.fields_used + v_total_queued_levels) >= v_planet.fields_max THEN
RETURN jsonb_build_object('success', false, 'error', 'No available fields on planet');
END IF;

v_validation := validate_building_requirements(p_planet_id, p_building_type_id);
IF NOT (v_validation->>'valid')::boolean THEN
RETURN jsonb_build_object('success', false, 'error', 'Requirements not met', 'details', v_validation);
END IF;

SELECT COALESCE(pb.level, 0) INTO v_current_level
FROM planet_buildings pb
WHERE pb.planet_id = p_planet_id AND pb.building_type_id = p_building_type_id;
IF v_current_level IS NULL THEN v_current_level := 0; END IF;

SELECT COUNT(*) INTO v_queued_count
FROM building_queue
WHERE planet_id = p_planet_id AND building_type_id = p_building_type_id;

v_target_level := v_current_level + v_queued_count + 1;

IF v_target_level > v_building_type.max_level THEN
RETURN jsonb_build_object('success', false, 'error', 'Max level reached');
END IF;

v_cost_metal := FLOOR(v_building_type.base_metal * POWER(v_building_type.cost_factor, v_current_level + v_queued_count));
v_cost_crystal := FLOOR(v_building_type.base_crystal * POWER(v_building_type.cost_factor, v_current_level + v_queued_count));
v_cost_deuterium := FLOOR(v_building_type.base_deuterium * POWER(v_building_type.cost_factor, v_current_level + v_queued_count));

SELECT * INTO v_resources FROM planet_resources WHERE planet_id = p_planet_id;
IF v_resources.metal < v_cost_metal OR v_resources.crystal < v_cost_crystal OR v_resources.deuterium < v_cost_deuterium THEN
RETURN jsonb_build_object('success', false, 'error', 'Insufficient resources');
END IF;

SELECT COALESCE(COUNT(*), 0) + 1 INTO v_queue_position FROM building_queue WHERE planet_id = p_planet_id;

SELECT COALESCE(pb.level, 0) INTO v_robotics_level
FROM planet_buildings pb
JOIN building_types bt ON bt.id = pb.building_type_id
WHERE pb.planet_id = p_planet_id AND bt.code = 'robotics_factory';
IF v_robotics_level IS NULL THEN v_robotics_level := 0; END IF;

SELECT COALESCE(pb.level, 0) INTO v_nanite_level
FROM planet_buildings pb
JOIN building_types bt ON bt.id = pb.building_type_id
WHERE pb.planet_id = p_planet_id AND bt.code = 'nanite_factory';
IF v_nanite_level IS NULL THEN v_nanite_level := 0; END IF;

v_game_speed := get_game_speed();

v_build_time := GREATEST(1, FLOOR((v_cost_metal + v_cost_crystal) / (2500.0 * (1 + v_robotics_level) * POWER(2, v_nanite_level)) * 3600 / v_game_speed));

-- VIP Plus: -10% construction time
IF is_user_plus(auth.uid()) THEN
  v_build_time := GREATEST(1, FLOOR(v_build_time * 0.90));
END IF;

v_is_first := v_queue_position = 1;
IF v_is_first THEN
v_start_time := now();
v_end_time := now() + (v_build_time || ' seconds')::interval;
ELSE
v_start_time := NULL;
v_end_time := NULL;
END IF;

UPDATE planet_resources
SET metal = metal - v_cost_metal,
crystal = crystal - v_cost_crystal,
deuterium = deuterium - v_cost_deuterium,
last_update = now()
WHERE planet_id = p_planet_id;

INSERT INTO building_queue (
planet_id, building_type_id, target_level,
metal_cost, crystal_cost, deuterium_cost,
build_time, queue_position, start_time, end_time, status
) VALUES (
p_planet_id, p_building_type_id, v_target_level,
v_cost_metal, v_cost_crystal, v_cost_deuterium,
v_build_time, v_queue_position, v_start_time, v_end_time, 'building'
);

RETURN jsonb_build_object('success', true, 'target_level', v_target_level, 'build_time', v_build_time);
END;
 

$$;


--
-- TOC entry 1145 (class 1255 OID 22355)
-- Name: secure_add_to_shipyard_queue(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_add_to_shipyard_queue(p_planet_id uuid, p_ship_id integer, p_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$

DECLARE
v_planet planets%ROWTYPE;
v_resources planet_resources%ROWTYPE;
v_shipyard_level integer;
v_nanite_level integer;
v_metal_cost bigint;
v_crystal_cost bigint;
v_deuterium_cost bigint;
v_build_time_per_unit integer;
v_queue_position integer;
v_validation jsonb;
v_game_speed integer;
v_ship_type ship_types%ROWTYPE;
v_defense_type defense_types%ROWTYPE;
v_existing_count integer;
v_queued_count integer;
v_silo_level integer;
v_silo_max integer;
v_current_ipm integer;
v_current_abm integer;
v_queued_ipm integer;
v_queued_abm integer;
v_total_missiles integer;
v_available_slots integer;
v_ipm_type_id integer;
v_abm_type_id integer;
v_blueprint_id bigint;
v_owned_blueprints integer;
v_has_enough_blueprints boolean;
BEGIN
IF auth.uid() IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
END IF;

IF is_user_in_vacation_mode(auth.uid()) THEN
RETURN jsonb_build_object('success', false, 'error', 'Cannot build ships or defenses while in vacation mode');
END IF;

IF p_quantity <= 0 OR p_quantity > 10000 THEN
RETURN jsonb_build_object('success', false, 'error', 'Invalid quantity');
END IF;

SELECT * INTO v_planet FROM planets WHERE id = p_planet_id AND user_id = auth.uid();
IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Planet not found');
END IF;

IF p_item_type = 'ship' THEN
  -- Verificar si la nave tiene plano y cuantos posee el usuario
  v_blueprint_id := NULL;
  v_owned_blueprints := 0;
  v_has_enough_blueprints := false;

  SELECT sb.id INTO v_blueprint_id
  FROM ship_blueprints sb
  WHERE sb.ship_type_id = p_type_id AND sb.is_active = true
  LIMIT 1;

  IF v_blueprint_id IS NOT NULL THEN
    SELECT COUNT(*)::integer INTO v_owned_blueprints
    FROM user_ship_blueprints usb
    WHERE usb.user_id = auth.uid()
      AND usb.blueprint_id = v_blueprint_id;

    v_has_enough_blueprints := v_owned_blueprints >= p_quantity;
  END IF;

  -- Si no hay plano o no tiene suficientes -> validar requisitos completos
  IF NOT v_has_enough_blueprints THEN
    v_validation := validate_ship_requirements(p_planet_id, p_type_id);
    IF NOT (v_validation->>'valid')::boolean THEN
      RETURN jsonb_build_object('success', false, 'error', 'Requirements not met');
    END IF;
  ELSE
    -- Con planos suficientes solo se exige Hangar >= 1
    SELECT COALESCE(pb.level, 0) INTO v_shipyard_level
    FROM planet_buildings pb
    JOIN building_types bt ON bt.id = pb.building_type_id
    WHERE pb.planet_id = p_planet_id AND bt.code = 'shipyard';

    IF COALESCE(v_shipyard_level, 0) < 1 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Necesitas Hangar nivel 1 para construir esta nave');
    END IF;
  END IF;

  SELECT * INTO v_ship_type FROM ship_types WHERE id = p_type_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ship type not found');
  END IF;

  v_metal_cost := v_ship_type.metal_cost * p_quantity;
  v_crystal_cost := v_ship_type.crystal_cost * p_quantity;
  v_deuterium_cost := v_ship_type.deuterium_cost * p_quantity;

ELSIF p_item_type = 'defense' THEN
v_validation := validate_defense_requirements(p_planet_id, p_type_id);
IF NOT (v_validation->>'valid')::boolean THEN
RETURN jsonb_build_object('success', false, 'error', 'Requirements not met');
END IF;

SELECT * INTO v_defense_type FROM defense_types WHERE id = p_type_id;
IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Defense type not found');
END IF;

IF v_defense_type.max_per_planet IS NOT NULL THEN
SELECT COALESCE(pd.quantity, 0) INTO v_existing_count
FROM planet_defenses pd
WHERE pd.planet_id = p_planet_id AND pd.defense_type_id = p_type_id;

SELECT COALESCE(SUM(sq.quantity - sq.quantity_completed), 0) INTO v_queued_count
FROM shipyard_queue sq
WHERE sq.planet_id = p_planet_id AND sq.defense_type_id = p_type_id;

IF (COALESCE(v_existing_count, 0) + COALESCE(v_queued_count, 0) + p_quantity) > v_defense_type.max_per_planet THEN
RETURN jsonb_build_object('success', false, 'error', 'Maximum limit reached for this defense type');
END IF;
END IF;

IF v_defense_type.code IN ('anti_ballistic_missile', 'interplanetary_missile') THEN
SELECT COALESCE(pb.level, 0) INTO v_silo_level
FROM planet_buildings pb
JOIN building_types bt ON pb.building_type_id = bt.id
WHERE pb.planet_id = p_planet_id AND bt.code = 'missile_silo';

v_silo_level := COALESCE(v_silo_level, 0);
v_silo_max := v_silo_level * 10;

SELECT id INTO v_ipm_type_id FROM defense_types WHERE code = 'interplanetary_missile';
SELECT id INTO v_abm_type_id FROM defense_types WHERE code = 'anti_ballistic_missile';

SELECT COALESCE(pd.quantity, 0) INTO v_current_ipm
FROM planet_defenses pd
WHERE pd.planet_id = p_planet_id AND pd.defense_type_id = v_ipm_type_id;

SELECT COALESCE(pd.quantity, 0) INTO v_current_abm
FROM planet_defenses pd
WHERE pd.planet_id = p_planet_id AND pd.defense_type_id = v_abm_type_id;

SELECT COALESCE(SUM(sq.quantity - sq.quantity_completed), 0) INTO v_queued_ipm
FROM shipyard_queue sq
WHERE sq.planet_id = p_planet_id AND sq.defense_type_id = v_ipm_type_id;

SELECT COALESCE(SUM(sq.quantity - sq.quantity_completed), 0) INTO v_queued_abm
FROM shipyard_queue sq
WHERE sq.planet_id = p_planet_id AND sq.defense_type_id = v_abm_type_id;

v_total_missiles := COALESCE(v_current_ipm, 0) + COALESCE(v_current_abm, 0) + COALESCE(v_queued_ipm, 0) + COALESCE(v_queued_abm, 0);
v_available_slots := GREATEST(0, v_silo_max - v_total_missiles);

IF p_quantity > v_available_slots THEN
RETURN jsonb_build_object(
'success', false,
'error', format('Silo capacity exceeded. Level %s silo holds %s missiles. Available slots: %s', v_silo_level, v_silo_max, v_available_slots)
);
END IF;
END IF;

v_metal_cost := v_defense_type.metal_cost * p_quantity;
v_crystal_cost := v_defense_type.crystal_cost * p_quantity;
v_deuterium_cost := v_defense_type.deuterium_cost * p_quantity;
ELSE
RETURN jsonb_build_object('success', false, 'error', 'Invalid item type');
END IF;

SELECT * INTO v_resources FROM planet_resources WHERE planet_id = p_planet_id;
IF v_resources.metal < v_metal_cost OR v_resources.crystal < v_crystal_cost OR v_resources.deuterium < v_deuterium_cost THEN
RETURN jsonb_build_object('success', false, 'error', 'Insufficient resources');
END IF;

SELECT COALESCE(pb.level, 0) INTO v_shipyard_level
FROM planet_buildings pb
JOIN building_types bt ON pb.building_type_id = bt.id
WHERE pb.planet_id = p_planet_id AND bt.code = 'shipyard';

SELECT COALESCE(pb.level, 0) INTO v_nanite_level
FROM planet_buildings pb
JOIN building_types bt ON pb.building_type_id = bt.id
WHERE pb.planet_id = p_planet_id AND bt.code = 'nanite_factory';

v_game_speed := get_game_speed();

IF p_item_type = 'ship' THEN
v_build_time_per_unit := GREATEST(1, FLOOR(
(v_ship_type.metal_cost + v_ship_type.crystal_cost)
/ (2500.0 * (1 + COALESCE(v_shipyard_level, 0)))
* 3600
/ POWER(2, COALESCE(v_nanite_level, 0))
/ v_game_speed
));
ELSE
v_build_time_per_unit := GREATEST(1, FLOOR(
(v_defense_type.metal_cost + v_defense_type.crystal_cost)
/ (2500.0 * (1 + COALESCE(v_shipyard_level, 0)))
* 3600
/ POWER(2, COALESCE(v_nanite_level, 0))
/ v_game_speed
));
END IF;

-- VIP Plus: -10% shipyard construction time
IF is_user_plus(auth.uid()) THEN
  v_build_time_per_unit := GREATEST(1, FLOOR(v_build_time_per_unit * 0.90));
END IF;

UPDATE planet_resources
SET metal = metal - v_metal_cost,
crystal = crystal - v_crystal_cost,
deuterium = deuterium - v_deuterium_cost,
last_update = now()
WHERE planet_id = p_planet_id;

PERFORM auto_cancel_insufficient_listings(p_planet_id);

SELECT COALESCE(MAX(queue_position), 0) INTO v_queue_position
FROM shipyard_queue WHERE planet_id = p_planet_id;

INSERT INTO shipyard_queue (
planet_id, item_type, ship_type_id, defense_type_id,
quantity, quantity_completed,
metal_cost, crystal_cost, deuterium_cost,
build_time_per_unit, queue_position,
start_time, current_unit_end_time
) VALUES (
p_planet_id, p_item_type,
CASE WHEN p_item_type = 'ship' THEN p_type_id ELSE NULL END,
CASE WHEN p_item_type = 'defense' THEN p_type_id ELSE NULL END,
p_quantity, 0,
v_metal_cost, v_crystal_cost, v_deuterium_cost,
v_build_time_per_unit, v_queue_position + 1,
CASE WHEN v_queue_position = 0 THEN now() ELSE NULL END,
CASE WHEN v_queue_position = 0 THEN now() + (v_build_time_per_unit || ' seconds')::interval ELSE NULL END
);

RETURN jsonb_build_object(
  'success', true,
  'metal_cost', v_metal_cost,
  'crystal_cost', v_crystal_cost,
  'deuterium_cost', v_deuterium_cost,
  'build_time_per_unit', v_build_time_per_unit,
  'used_blueprint', COALESCE(v_has_enough_blueprints, false)
);
END;

$$;


