--
-- TOC entry 849 (class 1255 OID 19966)
-- Name: secure_cancel_building_queue_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_cancel_building_queue_item(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_queue_item RECORD;
  v_planet RECORD;
  v_is_first boolean;
  v_game_speed numeric;
  v_refund_metal numeric;
  v_refund_crystal numeric;
  v_refund_deuterium numeric;
  v_elapsed_seconds numeric;
  v_total_seconds numeric;
  v_remaining_percent numeric;
  v_current_level integer;
  v_seq integer;
  v_rec RECORD;
  v_new_target_level integer;
  v_building_type RECORD;
  v_new_cost_metal bigint;
  v_new_cost_crystal bigint;
  v_new_cost_deuterium bigint;
  v_diff_metal bigint;
  v_diff_crystal bigint;
  v_diff_deuterium bigint;
  v_total_diff_metal bigint := 0;
  v_total_diff_crystal bigint := 0;
  v_total_diff_deuterium bigint := 0;
  v_robotics_level integer;
  v_nanite_level integer;
  v_new_build_time integer;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  SELECT * INTO v_queue_item FROM building_queue WHERE id = p_queue_id;
  IF v_queue_item IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Queue item not found');
  END IF;
  
  SELECT * INTO v_planet FROM planets WHERE id = v_queue_item.planet_id AND user_id = v_user_id;
  IF v_planet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not owned by user');
  END IF;
  
  v_is_first := v_queue_item.queue_position = 1;
  
  IF v_queue_item.start_time IS NULL OR v_queue_item.end_time IS NULL THEN
    v_refund_metal := v_queue_item.metal_cost;
    v_refund_crystal := v_queue_item.crystal_cost;
    v_refund_deuterium := v_queue_item.deuterium_cost;
  ELSE
    v_elapsed_seconds := GREATEST(0, EXTRACT(EPOCH FROM (now() - v_queue_item.start_time)));
    v_total_seconds := EXTRACT(EPOCH FROM (v_queue_item.end_time - v_queue_item.start_time));
    
    IF v_elapsed_seconds >= v_total_seconds THEN
      v_remaining_percent := 0;
    ELSE
      v_remaining_percent := (v_total_seconds - v_elapsed_seconds) / v_total_seconds;
    END IF;
    
    v_refund_metal := FLOOR(v_queue_item.metal_cost * v_remaining_percent);
    v_refund_crystal := FLOOR(v_queue_item.crystal_cost * v_remaining_percent);
    v_refund_deuterium := FLOOR(v_queue_item.deuterium_cost * v_remaining_percent);
  END IF;
  
  UPDATE planet_resources
  SET 
    metal = metal + v_refund_metal,
    crystal = crystal + v_refund_crystal,
    deuterium = deuterium + v_refund_deuterium,
    last_update = now()
  WHERE planet_id = v_queue_item.planet_id;
  
  DELETE FROM building_queue WHERE id = p_queue_id;
  
  WITH reordered AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY queue_position) as new_pos
    FROM building_queue
    WHERE planet_id = v_queue_item.planet_id
  )
  UPDATE building_queue bq
  SET queue_position = r.new_pos
  FROM reordered r
  WHERE bq.id = r.id;
  
  -- Recalculate target_level for remaining items of the SAME building type
  SELECT COALESCE(pb.level, 0) INTO v_current_level
  FROM planet_buildings pb
  WHERE pb.planet_id = v_queue_item.planet_id AND pb.building_type_id = v_queue_item.building_type_id;
  v_current_level := COALESCE(v_current_level, 0);

  SELECT * INTO v_building_type FROM building_types WHERE id = v_queue_item.building_type_id;

  SELECT COALESCE(pb.level, 0) INTO v_robotics_level
  FROM planet_buildings pb
  JOIN building_types bt ON bt.id = pb.building_type_id
  WHERE pb.planet_id = v_queue_item.planet_id AND bt.code = 'robotics_factory';
  v_robotics_level := COALESCE(v_robotics_level, 0);

  SELECT COALESCE(pb.level, 0) INTO v_nanite_level
  FROM planet_buildings pb
  JOIN building_types bt ON bt.id = pb.building_type_id
  WHERE pb.planet_id = v_queue_item.planet_id AND bt.code = 'nanite_factory';
  v_nanite_level := COALESCE(v_nanite_level, 0);

  v_game_speed := get_game_speed();

  v_seq := 0;
  FOR v_rec IN
    SELECT id, target_level, metal_cost, crystal_cost, deuterium_cost, queue_position, start_time
    FROM building_queue
    WHERE planet_id = v_queue_item.planet_id
      AND building_type_id = v_queue_item.building_type_id
    ORDER BY queue_position
  LOOP
    v_seq := v_seq + 1;
    v_new_target_level := v_current_level + v_seq;

    IF v_new_target_level != v_rec.target_level THEN
      v_new_cost_metal := FLOOR(v_building_type.base_metal * POWER(v_building_type.cost_factor, v_new_target_level - 1));
      v_new_cost_crystal := FLOOR(v_building_type.base_crystal * POWER(v_building_type.cost_factor, v_new_target_level - 1));
      v_new_cost_deuterium := FLOOR(v_building_type.base_deuterium * POWER(v_building_type.cost_factor, v_new_target_level - 1));

      v_diff_metal := v_rec.metal_cost - v_new_cost_metal;
      v_diff_crystal := v_rec.crystal_cost - v_new_cost_crystal;
      v_diff_deuterium := v_rec.deuterium_cost - v_new_cost_deuterium;

      v_total_diff_metal := v_total_diff_metal + v_diff_metal;
      v_total_diff_crystal := v_total_diff_crystal + v_diff_crystal;
      v_total_diff_deuterium := v_total_diff_deuterium + v_diff_deuterium;

      v_new_build_time := GREATEST(1, FLOOR(
        (v_new_cost_metal + v_new_cost_crystal) / (2500.0 * (1 + v_robotics_level) * POWER(2, v_nanite_level)) * 3600 / v_game_speed
      ));

      IF v_rec.start_time IS NOT NULL THEN
        UPDATE building_queue
        SET target_level = v_new_target_level,
            metal_cost = v_new_cost_metal,
            crystal_cost = v_new_cost_crystal,
            deuterium_cost = v_new_cost_deuterium,
            build_time = v_new_build_time,
            end_time = start_time + (v_new_build_time || ' seconds')::interval
        WHERE id = v_rec.id;
      ELSE
        UPDATE building_queue
        SET target_level = v_new_target_level,
            metal_cost = v_new_cost_metal,
            crystal_cost = v_new_cost_crystal,
            deuterium_cost = v_new_cost_deuterium,
            build_time = v_new_build_time
        WHERE id = v_rec.id;
      END IF;
    END IF;
  END LOOP;

  IF v_total_diff_metal != 0 OR v_total_diff_crystal != 0 OR v_total_diff_deuterium != 0 THEN
    UPDATE planet_resources
    SET
      metal = metal + v_total_diff_metal,
      crystal = crystal + v_total_diff_crystal,
      deuterium = deuterium + v_total_diff_deuterium
    WHERE planet_id = v_queue_item.planet_id;
  END IF;

  IF v_is_first THEN
    UPDATE building_queue
    SET 
      start_time = now(),
      end_time = now() + (build_time || ' seconds')::interval
    WHERE planet_id = v_queue_item.planet_id
      AND queue_position = 1
      AND start_time IS NULL;
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'refunded_metal', FLOOR(v_refund_metal),
    'refunded_crystal', FLOOR(v_refund_crystal),
    'refunded_deuterium', FLOOR(v_refund_deuterium),
    'was_in_progress', v_queue_item.start_time IS NOT NULL,
    'percent_refunded', CASE 
      WHEN v_queue_item.start_time IS NULL THEN 100 
      ELSE FLOOR(v_remaining_percent * 100) 
    END
  );
END;
$$;


--
-- TOC entry 927 (class 1255 OID 20382)
-- Name: secure_cancel_research(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_cancel_research(p_technology_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tech RECORD;
  v_tech_type RECORD;
  v_current_level integer;
  v_cost_metal bigint;
  v_cost_crystal bigint;
  v_cost_deuterium bigint;
  v_elapsed_seconds numeric;
  v_total_seconds numeric;
  v_remaining_percent numeric;
  v_refund_metal bigint;
  v_refund_crystal bigint;
  v_refund_deuterium bigint;
  v_research_planet_id uuid;
  v_next RECORD;
  v_now timestamptz;
  v_end timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Get the technology record
  SELECT * INTO v_tech
  FROM user_technologies
  WHERE id = p_technology_id AND user_id = auth.uid();

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Technology not found or not owned');
  END IF;

  IF NOT v_tech.is_researching THEN
    RETURN jsonb_build_object('success', false, 'error', 'Technology is not being researched');
  END IF;

  v_research_planet_id := v_tech.research_planet_id;
  IF v_research_planet_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Research planet not found');
  END IF;

  -- Get technology type for cost calculation
  SELECT * INTO v_tech_type FROM technology_types WHERE id = v_tech.technology_type_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Technology type not found');
  END IF;

  v_current_level := v_tech.level;

  -- Calculate original cost (cost for the level being researched = current_level)
  v_cost_metal := FLOOR(v_tech_type.base_metal * POWER(v_tech_type.cost_factor, v_current_level));
  v_cost_crystal := FLOOR(v_tech_type.base_crystal * POWER(v_tech_type.cost_factor, v_current_level));
  v_cost_deuterium := FLOOR(v_tech_type.base_deuterium * POWER(v_tech_type.cost_factor, v_current_level));

  -- Calculate proportional refund based on remaining time
  IF v_tech.research_start_time IS NULL OR v_tech.research_end_time IS NULL THEN
    v_remaining_percent := 1.0;
  ELSE
    v_elapsed_seconds := GREATEST(0, EXTRACT(EPOCH FROM (now() - v_tech.research_start_time)));
    v_total_seconds := EXTRACT(EPOCH FROM (v_tech.research_end_time - v_tech.research_start_time));

    IF v_total_seconds <= 0 OR v_elapsed_seconds >= v_total_seconds THEN
      v_remaining_percent := 0;
    ELSE
      v_remaining_percent := (v_total_seconds - v_elapsed_seconds) / v_total_seconds;
    END IF;
  END IF;

  v_refund_metal := FLOOR(v_cost_metal * v_remaining_percent);
  v_refund_crystal := FLOOR(v_cost_crystal * v_remaining_percent);
  v_refund_deuterium := FLOOR(v_cost_deuterium * v_remaining_percent);

  -- Reset current active research state
  UPDATE user_technologies
  SET
    is_researching = false,
    research_start_time = NULL,
    research_end_time = NULL,
    research_planet_id = NULL
  WHERE id = p_technology_id;

  -- Refund resources
  UPDATE planet_resources
  SET
    metal = metal + v_refund_metal,
    crystal = crystal + v_refund_crystal,
    deuterium = deuterium + v_refund_deuterium,
    last_update = now()
  WHERE planet_id = v_research_planet_id;

  -- NEW: If user now has no active research, start first queued entry
  IF NOT EXISTS (
    SELECT 1 FROM user_technologies
    WHERE user_id = auth.uid() AND is_researching = true
  ) THEN
    SELECT * INTO v_next
    FROM research_queue
    WHERE user_id = auth.uid()
      AND status IN ('queued', 'pending')
    ORDER BY queue_position ASC, created_at ASC
    LIMIT 1;

    IF FOUND THEN
      v_now := now();
      v_end := v_now + (v_next.research_time || ' seconds')::interval;

      ALTER TABLE user_technologies DISABLE TRIGGER trigger_research_points;

      INSERT INTO user_technologies (
        user_id, technology_type_id, level, is_researching,
        research_start_time, research_end_time, research_planet_id
      ) VALUES (
        auth.uid(), v_next.technology_type_id, v_next.target_level - 1, true,
        v_now, v_end, v_next.planet_id
      )
      ON CONFLICT (user_id, technology_type_id) DO UPDATE SET
        is_researching = true,
        research_start_time = v_now,
        research_end_time = v_end,
        research_planet_id = v_next.planet_id;

      ALTER TABLE user_technologies ENABLE TRIGGER trigger_research_points;

      DELETE FROM research_queue WHERE id = v_next.id;

      WITH ranked AS (
        SELECT id, ROW_NUMBER() OVER (ORDER BY queue_position ASC, created_at ASC) AS new_pos
        FROM research_queue
        WHERE user_id = auth.uid() AND status IN ('queued', 'pending')
      )
      UPDATE research_queue rq
      SET queue_position = ranked.new_pos
      FROM ranked
      WHERE rq.id = ranked.id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'refund_metal', v_refund_metal,
    'refund_crystal', v_refund_crystal,
    'refund_deuterium', v_refund_deuterium,
    'refund_planet_id', v_research_planet_id,
    'remaining_percent', ROUND(v_remaining_percent * 100)
  );
END;
$$;


--
-- TOC entry 893 (class 1255 OID 20120)
-- Name: secure_cancel_shipyard_queue_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_cancel_shipyard_queue_item(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_queue_item record;
  v_planet record;
  v_remaining_quantity integer;
  v_unit_metal numeric;
  v_unit_crystal numeric;
  v_unit_deuterium numeric;
  v_refund_metal numeric;
  v_refund_crystal numeric;
  v_refund_deuterium numeric;
  v_is_first boolean;
  v_next_item record;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  -- Get queue item with lock
  SELECT * INTO v_queue_item 
  FROM shipyard_queue 
  WHERE id = p_queue_id
  FOR UPDATE;
  
  IF v_queue_item IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Queue item not found');
  END IF;
  
  -- Verify ownership via planet
  SELECT * INTO v_planet 
  FROM planets 
  WHERE id = v_queue_item.planet_id AND user_id = v_user_id;
  
  IF v_planet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not owned by user');
  END IF;
  
  v_is_first := v_queue_item.queue_position = 1;
  
  -- Calculate remaining quantity (units not yet built)
  v_remaining_quantity := v_queue_item.quantity - COALESCE(v_queue_item.quantity_completed, 0);
  
  IF v_remaining_quantity <= 0 THEN
    -- All units completed, just clean up
    DELETE FROM shipyard_queue WHERE id = p_queue_id;
    RETURN jsonb_build_object(
      'success', true,
      'refunded_metal', 0,
      'refunded_crystal', 0,
      'refunded_deuterium', 0,
      'message', 'All units already completed'
    );
  END IF;
  
  -- Calculate cost per unit
  v_unit_metal := v_queue_item.metal_cost / NULLIF(v_queue_item.quantity, 0);
  v_unit_crystal := v_queue_item.crystal_cost / NULLIF(v_queue_item.quantity, 0);
  v_unit_deuterium := v_queue_item.deuterium_cost / NULLIF(v_queue_item.quantity, 0);
  
  -- Calculate refund for remaining units
  v_refund_metal := FLOOR(COALESCE(v_unit_metal, 0) * v_remaining_quantity);
  v_refund_crystal := FLOOR(COALESCE(v_unit_crystal, 0) * v_remaining_quantity);
  v_refund_deuterium := FLOOR(COALESCE(v_unit_deuterium, 0) * v_remaining_quantity);
  
  -- Refund resources to planet
  UPDATE planet_resources
  SET 
    metal = metal + v_refund_metal,
    crystal = crystal + v_refund_crystal,
    deuterium = deuterium + v_refund_deuterium,
    last_update = now()
  WHERE planet_id = v_queue_item.planet_id;
  
  -- Delete the cancelled item
  DELETE FROM shipyard_queue WHERE id = p_queue_id;
  
  -- If we cancelled the first item, activate the new first item
  IF v_is_first THEN
    SELECT * INTO v_next_item
    FROM shipyard_queue
    WHERE planet_id = v_queue_item.planet_id AND queue_position = 2
    LIMIT 1;
    
    IF FOUND THEN
      UPDATE shipyard_queue
      SET 
        queue_position = 1,
        start_time = now(),
        current_unit_end_time = now() + (build_time_per_unit * INTERVAL '1 second')
      WHERE id = v_next_item.id;
    END IF;
  END IF;
  
  -- Reorder remaining queue items
  WITH reordered AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY queue_position) as new_pos
    FROM shipyard_queue
    WHERE planet_id = v_queue_item.planet_id
  )
  UPDATE shipyard_queue sq
  SET queue_position = r.new_pos
  FROM reordered r
  WHERE sq.id = r.id AND sq.queue_position != r.new_pos;
  
  RETURN jsonb_build_object(
    'success', true,
    'refunded_metal', v_refund_metal,
    'refunded_crystal', v_refund_crystal,
    'refunded_deuterium', v_refund_deuterium,
    'units_cancelled', v_remaining_quantity,
    'units_completed', COALESCE(v_queue_item.quantity_completed, 0)
  );
END;
$$;


--
-- TOC entry 1003 (class 1255 OID 20846)
-- Name: secure_create_alliance(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_create_alliance(p_tag text, p_name text, p_description text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_cost integer;
  v_user_fxu numeric;
  v_is_plus boolean;
  v_final_cost integer;
  v_admin_id uuid;
  v_admin_amount integer;
  v_pool_amount integer;
  v_existing_tag uuid;
  v_existing_member record;
  v_alliance_id uuid;
  v_has_created boolean;
  v_free_creation boolean;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Validar tag
  IF p_tag IS NULL OR LENGTH(TRIM(p_tag)) < 2 OR LENGTH(TRIM(p_tag)) > 8 THEN
    RETURN jsonb_build_object('success', false, 'error', 'El tag debe tener entre 2 y 8 caracteres');
  END IF;

  -- Validar nombre
  IF p_name IS NULL OR LENGTH(TRIM(p_name)) < 2 OR LENGTH(TRIM(p_name)) > 30 THEN
    RETURN jsonb_build_object('success', false, 'error', 'El nombre debe tener entre 2 y 30 caracteres');
  END IF;

  p_tag := UPPER(TRIM(p_tag));
  p_name := TRIM(p_name);

  -- Verificar que el usuario no esté ya en una alianza
  SELECT * INTO v_existing_member FROM alliance_members WHERE user_id = v_user_id LIMIT 1;
  IF v_existing_member IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya eres miembro de una alianza');
  END IF;

  -- Verificar tag único
  SELECT id INTO v_existing_tag FROM alliances WHERE tag = p_tag;
  IF v_existing_tag IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Esta etiqueta ya está en uso');
  END IF;

  -- Check if this is user's FIRST alliance creation (ever)
  SELECT has_created_alliance INTO v_has_created FROM profiles WHERE id = v_user_id;
  v_free_creation := (v_has_created IS FALSE);

  IF v_free_creation THEN
    -- First creation: FREE
    v_final_cost := 0;
    v_admin_amount := 0;
    v_pool_amount := 0;
    v_is_plus := false;
  ELSE
    -- Subsequent creation: normal cost
    SELECT COALESCE(value::integer, 1000) INTO v_cost
    FROM game_settings WHERE key = 'fxu_create_alliance_cost';
    IF v_cost IS NULL THEN v_cost := 1000; END IF;

    -- Descuento VIP 50%
    v_is_plus := is_user_plus(v_user_id);
    v_final_cost := v_cost;
    IF v_is_plus THEN
      v_final_cost := CEIL(v_cost * 0.50);
    END IF;

    -- Si el costo es > 0, verificar y cobrar
    IF v_final_cost > 0 THEN
      SELECT COALESCE(fxu_balance, 0) INTO v_user_fxu FROM profiles WHERE id = v_user_id;
      IF v_user_fxu < v_final_cost THEN
        RETURN jsonb_build_object(
          'success', false,
          'error', 'FXU insuficiente. Necesitas ' || v_final_cost || ' FXU, tienes ' || v_user_fxu || ' FXU',
          'required', v_final_cost,
          'available', v_user_fxu
        );
      END IF;

      -- Cobrar FXU
      PERFORM _internal_set_fxu_context();
      UPDATE profiles SET fxu_balance = fxu_balance - v_final_cost WHERE id = v_user_id;

      -- Split 50% admin / 50% pools de recompensa
      v_pool_amount := FLOOR(v_final_cost * 0.50);
      v_admin_amount := v_final_cost - v_pool_amount;

      -- 50% al admin
      SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
      IF v_admin_id IS NOT NULL AND v_admin_id != v_user_id AND v_admin_amount > 0 THEN
        UPDATE profiles SET fxu_balance = fxu_balance + v_admin_amount WHERE id = v_admin_id;
      END IF;

      PERFORM record_admin_revenue('alliance_creation', v_admin_amount, 'Create alliance (50% admin): [' || p_tag || '] ' || p_name, v_user_id, NULL);

      -- 50% a pools de recompensa
      IF v_pool_amount > 0 THEN
        PERFORM contribute_to_jackpot(v_pool_amount, 'alliance_creation', v_user_id);
      END IF;
    ELSE
      v_admin_amount := 0;
      v_pool_amount := 0;
    END IF;
  END IF;

  -- Crear alianza
  INSERT INTO alliances (tag, name, description, founder_id, leader_id, member_count, is_open, name_changed)
  VALUES (p_tag, p_name, COALESCE(p_description, ''), v_user_id, v_user_id, 1, false, true)
  RETURNING id INTO v_alliance_id;

  -- Agregar fundador como miembro
  INSERT INTO alliance_members (alliance_id, user_id, rank_name, rank_level, can_invite, can_kick, can_edit)
  VALUES (v_alliance_id, v_user_id, 'Fundador', 10, true, true, true);

  -- Mark user as having created an alliance
  UPDATE profiles SET has_created_alliance = true WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', CASE WHEN v_free_creation THEN '¡Alianza creada gratis! (primera creación)' ELSE 'Alianza creada exitosamente' END,
    'alliance_id', v_alliance_id,
    'cost', v_final_cost,
    'admin_share', v_admin_amount,
    'pool_share', v_pool_amount,
    'vip_discount', v_is_plus,
    'free_creation', v_free_creation
  );
END;
$$;


--
-- TOC entry 1166 (class 1255 OID 22574)
-- Name: secure_delete_all_my_messages(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_delete_all_my_messages(p_mode text DEFAULT 'inbox'::text, p_message_type text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_count integer;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_mode = 'sent' THEN
    -- Delete sent messages (user is sender)
    DELETE FROM messages WHERE sender_id = v_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
  ELSIF p_mode = 'inbox' THEN
    -- Delete received messages, optionally filtered by type
    IF p_message_type IS NOT NULL AND p_message_type != '' THEN
      DELETE FROM messages WHERE recipient_id = v_user_id AND message_type = p_message_type;
    ELSE
      DELETE FROM messages WHERE recipient_id = v_user_id;
    END IF;
    GET DIAGNOSTICS v_count = ROW_COUNT;
  ELSE
    RAISE EXCEPTION 'Invalid mode: %', p_mode;
  END IF;

  RETURN v_count;
END;
$$;


--
-- TOC entry 925 (class 1255 OID 20374)
-- Name: secure_demolish_building(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_demolish_building(p_planet_id uuid, p_building_type_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet planets%ROWTYPE; v_building planet_buildings%ROWTYPE; v_building_type building_types%ROWTYPE;
  v_queue_count integer; v_current_level integer;
  v_refund_metal bigint; v_refund_crystal bigint; v_refund_deuterium bigint;
  v_fields_decrease integer := 0; v_fxu_fee numeric; v_user_fxu numeric; v_admin_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  IF is_user_in_vacation_mode(auth.uid()) THEN RETURN jsonb_build_object('success', false, 'error', 'Cannot demolish while in vacation mode'); END IF;

  SELECT COALESCE(value::numeric, 0) INTO v_fxu_fee FROM game_settings WHERE key = 'fxu_demolish_fee';
  IF v_fxu_fee IS NULL THEN v_fxu_fee := 0; END IF;

  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id AND user_id = auth.uid();
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Planet not found or not owned'); END IF;
  SELECT * INTO v_building_type FROM building_types WHERE id = p_building_type_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Building type not found'); END IF;
  SELECT * INTO v_building FROM planet_buildings WHERE planet_id = p_planet_id AND building_type_id = p_building_type_id;
  IF NOT FOUND OR COALESCE(v_building.level,0) <= 0 THEN RETURN jsonb_build_object('success', false, 'error', 'Building not found or already at level 0'); END IF;
  v_current_level := v_building.level;
  SELECT COUNT(*) INTO v_queue_count FROM building_queue WHERE planet_id = p_planet_id;
  IF v_queue_count > 0 THEN RETURN jsonb_build_object('success', false, 'error', 'Cannot demolish while construction queue is active'); END IF;
  IF v_building.is_upgrading THEN RETURN jsonb_build_object('success', false, 'error', 'Cannot demolish while building is upgrading'); END IF;

  IF v_fxu_fee > 0 THEN
    SELECT COALESCE(fxu_balance,0) INTO v_user_fxu FROM profiles WHERE id = auth.uid();
    IF v_user_fxu < v_fxu_fee THEN
      RETURN jsonb_build_object('success', false, 'error', 'Insufficient FXU. Required: ' || v_fxu_fee::text || ', Available: ' || v_user_fxu::text);
    END IF;
    PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);
    UPDATE profiles SET fxu_balance = fxu_balance - v_fxu_fee WHERE id = auth.uid();
    v_admin_id := get_admin_account_id();
    IF v_admin_id IS NOT NULL THEN UPDATE profiles SET fxu_balance = fxu_balance + v_fxu_fee WHERE id = v_admin_id; END IF;
  END IF;

  v_refund_metal := FLOOR(v_building_type.base_metal * POWER(v_building_type.cost_factor, v_current_level - 1) * 0.5);
  v_refund_crystal := FLOOR(v_building_type.base_crystal * POWER(v_building_type.cost_factor, v_current_level - 1) * 0.5);
  v_refund_deuterium := FLOOR(v_building_type.base_deuterium * POWER(v_building_type.cost_factor, v_current_level - 1) * 0.5);

  UPDATE planet_buildings SET level = v_current_level - 1 WHERE id = v_building.id;
  UPDATE planet_resources SET metal = metal + v_refund_metal, crystal = crystal + v_refund_crystal,
    deuterium = deuterium + v_refund_deuterium, last_update = now() WHERE planet_id = p_planet_id;

  IF v_building_type.code = 'lunar_base' THEN
    v_fields_decrease := 3;
    UPDATE planets SET fields_used = GREATEST(0, fields_used - 1), fields_max = GREATEST(1, fields_max - v_fields_decrease) WHERE id = p_planet_id;
  ELSIF v_building_type.code = 'terraformer' THEN
    -- IMPORTANTE: trigger_update_fields_on_terraformer ya recalcula fields_max
    -- al cambiar level en planet_buildings. Aquí solo ajustamos fields_used.
    UPDATE planets SET fields_used = GREATEST(0, fields_used - 1) WHERE id = p_planet_id;
  ELSE
    UPDATE planets SET fields_used = GREATEST(0, fields_used - 1) WHERE id = p_planet_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'new_level', v_current_level - 1,
    'refund_metal', v_refund_metal, 'refund_crystal', v_refund_crystal,
    'refund_deuterium', v_refund_deuterium, 'fxu_charged', v_fxu_fee);
END;
$$;


--
-- TOC entry 1167 (class 1255 OID 22575)
-- Name: secure_mark_message_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_mark_message_read(p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE messages SET is_read = true 
  WHERE id = p_message_id AND recipient_id = v_user_id;
END;
$$;


--
-- TOC entry 1000 (class 1255 OID 20843)
-- Name: secure_rename_alliance(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_rename_alliance(p_alliance_id uuid, p_new_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_alliance record;
  v_member record;
  v_cost integer;
  v_user_fxu numeric;
  v_is_plus boolean;
  v_admin_id uuid;
  v_final_cost integer;
  v_admin_amount integer;
  v_pool_amount integer;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Validar nombre
  IF p_new_name IS NULL OR LENGTH(TRIM(p_new_name)) < 2 OR LENGTH(TRIM(p_new_name)) > 30 THEN
    RETURN jsonb_build_object('success', false, 'error', 'El nombre debe tener entre 2 y 30 caracteres');
  END IF;

  p_new_name := TRIM(p_new_name);

  -- Buscar alianza
  SELECT * INTO v_alliance FROM alliances WHERE id = p_alliance_id;
  IF v_alliance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Alianza no encontrada');
  END IF;

  -- Verificar que el usuario es líder o fundador
  SELECT * INTO v_member FROM alliance_members 
  WHERE alliance_id = p_alliance_id AND user_id = v_user_id;
  
  IF v_member IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No eres miembro de esta alianza');
  END IF;

  IF v_alliance.leader_id != v_user_id AND v_alliance.founder_id != v_user_id AND v_member.can_edit = false THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes permisos para renombrar la alianza');
  END IF;

  -- Si el nombre no cambió
  IF v_alliance.name = p_new_name THEN
    RETURN jsonb_build_object('success', true, 'message', 'Nombre sin cambios', 'cost', 0);
  END IF;

  -- Si es la primera vez (name_changed = false), es GRATIS
  IF v_alliance.name_changed = false THEN
    UPDATE alliances SET name = p_new_name, name_changed = true WHERE id = p_alliance_id;
    RETURN jsonb_build_object('success', true, 'message', 'Alianza renombrada gratis (primera vez)', 'cost', 0);
  END IF;

  -- A partir de aquí COBRA FXU
  SELECT COALESCE(value::integer, 1000) INTO v_cost
  FROM game_settings WHERE key = 'fxu_rename_alliance_cost';
  IF v_cost IS NULL THEN v_cost := 1000; END IF;

  -- Descuento VIP 50%
  v_is_plus := is_user_plus(v_user_id);
  v_final_cost := v_cost;
  IF v_is_plus THEN
    v_final_cost := CEIL(v_cost * 0.50);
  END IF;

  -- Verificar saldo
  SELECT COALESCE(fxu_balance, 0) INTO v_user_fxu FROM profiles WHERE id = v_user_id;
  IF v_user_fxu < v_final_cost THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'FXU insuficiente. Necesitas ' || v_final_cost || ' FXU, tienes ' || v_user_fxu || ' FXU',
      'required', v_final_cost,
      'available', v_user_fxu
    );
  END IF;

  -- Cobrar FXU
  PERFORM _internal_set_fxu_context();
  UPDATE profiles SET fxu_balance = fxu_balance - v_final_cost WHERE id = v_user_id;

  -- Split 50% admin / 50% pools de recompensa
  v_pool_amount := FLOOR(v_final_cost * 0.50);
  v_admin_amount := v_final_cost - v_pool_amount;

  -- 50% al admin
  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_id != v_user_id AND v_admin_amount > 0 THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_admin_amount WHERE id = v_admin_id;
  END IF;

  PERFORM record_admin_revenue('alliance_rename', v_admin_amount, 'Rename alliance (50% admin): ' || v_alliance.name || ' → ' || p_new_name, v_user_id, p_alliance_id);

  -- 50% a pools de recompensa
  IF v_pool_amount > 0 THEN
    PERFORM contribute_to_jackpot(v_pool_amount, 'alliance_rename', v_user_id);
  END IF;

  -- Renombrar
  UPDATE alliances SET name = p_new_name WHERE id = p_alliance_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Alianza renombrada exitosamente',
    'cost', v_final_cost,
    'admin_share', v_admin_amount,
    'pool_share', v_pool_amount,
    'new_name', p_new_name,
    'vip_discount', v_is_plus
  );
END;
$$;


--
-- TOC entry 999 (class 1255 OID 20842)
-- Name: secure_rename_planet(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_rename_planet(p_planet_id uuid, p_new_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_planet record;
  v_cost integer;
  v_user_fxu numeric;
  v_is_plus boolean;
  v_admin_id uuid;
  v_final_cost integer;
  v_admin_amount integer;
  v_pool_amount integer;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Validar nombre
  IF p_new_name IS NULL OR LENGTH(TRIM(p_new_name)) < 2 OR LENGTH(TRIM(p_new_name)) > 24 THEN
    RETURN jsonb_build_object('success', false, 'error', 'El nombre debe tener entre 2 y 24 caracteres');
  END IF;

  p_new_name := TRIM(p_new_name);

  -- Buscar planeta del usuario
  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id AND user_id = v_user_id;
  IF v_planet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planeta no encontrado');
  END IF;

  -- Si el nombre no cambió, no hacer nada
  IF v_planet.name = p_new_name THEN
    RETURN jsonb_build_object('success', true, 'message', 'Nombre sin cambios', 'cost', 0);
  END IF;

  -- Si es la primera vez (name_changed = false), es GRATIS
  IF v_planet.name_changed = false THEN
    UPDATE planets SET name = p_new_name, name_changed = true WHERE id = p_planet_id;
    RETURN jsonb_build_object('success', true, 'message', 'Planeta renombrado gratis (primera vez)', 'cost', 0);
  END IF;

  -- A partir de aquí COBRA FXU
  SELECT COALESCE(value::integer, 100) INTO v_cost
  FROM game_settings WHERE key = 'fxu_rename_planet_cost';
  IF v_cost IS NULL THEN v_cost := 100; END IF;

  -- Descuento VIP 50%
  v_is_plus := is_user_plus(v_user_id);
  v_final_cost := v_cost;
  IF v_is_plus THEN
    v_final_cost := CEIL(v_cost * 0.50);
  END IF;

  -- Verificar saldo
  SELECT COALESCE(fxu_balance, 0) INTO v_user_fxu FROM profiles WHERE id = v_user_id;
  IF v_user_fxu < v_final_cost THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'FXU insuficiente. Necesitas ' || v_final_cost || ' FXU, tienes ' || v_user_fxu || ' FXU',
      'required', v_final_cost,
      'available', v_user_fxu
    );
  END IF;

  -- Cobrar FXU
  PERFORM _internal_set_fxu_context();
  UPDATE profiles SET fxu_balance = fxu_balance - v_final_cost WHERE id = v_user_id;

  -- Split 50% admin / 50% pools de recompensa
  v_pool_amount := FLOOR(v_final_cost * 0.50);
  v_admin_amount := v_final_cost - v_pool_amount;

  -- 50% al admin
  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_admin_id != v_user_id AND v_admin_amount > 0 THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_admin_amount WHERE id = v_admin_id;
  END IF;

  PERFORM record_admin_revenue('planet_rename', v_admin_amount, 'Rename planet (50% admin): ' || v_planet.name || ' → ' || p_new_name, v_user_id, p_planet_id);

  -- 50% a pools de recompensa
  IF v_pool_amount > 0 THEN
    PERFORM contribute_to_jackpot(v_pool_amount, 'planet_rename', v_user_id);
  END IF;

  -- Renombrar
  UPDATE planets SET name = p_new_name WHERE id = p_planet_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Planeta renombrado exitosamente',
    'cost', v_final_cost,
    'admin_share', v_admin_amount,
    'pool_share', v_pool_amount,
    'new_name', p_new_name,
    'vip_discount', v_is_plus
  );
END;
$$;


--
-- TOC entry 1016 (class 1255 OID 20923)
-- Name: secure_send_fleet(uuid, integer, integer, integer, text, jsonb, bigint, bigint, bigint, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_send_fleet(p_origin_planet_id uuid, p_target_galaxy integer, p_target_system integer, p_target_position integer, p_mission_type text, p_fleet_ships jsonb, p_cargo_metal bigint DEFAULT 0, p_cargo_crystal bigint DEFAULT 0, p_cargo_deuterium bigint DEFAULT 0, p_speed_percent integer DEFAULT 100, p_target_type text DEFAULT 'planet'::text, p_override_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ 
DECLARE
  v_user_id uuid;
  v_caller_is_admin boolean := false;
  v_planet record;
  v_resources record;
  v_distance int;
  v_slowest_speed int;
  v_flight_time int;
  v_fuel_consumption bigint;
  v_total_deut_needed bigint;
  v_ship record;
  v_ship_type record;
  v_planet_ship record;
  v_total_cargo_capacity bigint := 0;
  v_total_cargo_used bigint;
  v_fleet_id uuid;
  v_arrival_time timestamptz;
  v_return_time timestamptz;
  v_validation jsonb;
  v_has_required_ship boolean := true;
  v_colony_ship_type_id int;
  v_recycler_type_id int;
  v_mega_recycler_type_id int;
  v_probe_type_id int;
  v_computer_tech_level int := 0;
  v_has_admiral boolean;
  v_admiral_speed_bonus numeric := 0;
  v_max_fleet_slots int;
  v_active_fleet_count int;
  v_profile record;
BEGIN
  IF p_override_user_id IS NOT NULL THEN
    IF auth.uid() IS NOT NULL THEN
      SELECT COALESCE(is_admin, false)
      INTO v_caller_is_admin
      FROM profiles
      WHERE id = auth.uid();

      IF NOT COALESCE(v_caller_is_admin, false) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized override');
      END IF;
    END IF;

    v_user_id := p_override_user_id;
  ELSE
    v_user_id := auth.uid();
  END IF;

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_planet FROM planets WHERE id = p_origin_planet_id AND user_id = v_user_id;
  IF v_planet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet not found or not owned by user');
  END IF;

  SELECT * INTO v_profile FROM profiles WHERE id = v_user_id;
  IF v_profile IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Profile not found');
  END IF;

  IF v_profile.vacation_mode THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot send fleets in vacation mode');
  END IF;

  IF p_speed_percent < 10 OR p_speed_percent > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Speed must be between 10 and 100');
  END IF;

  IF p_mission_type NOT IN ('attack', 'transport', 'deploy', 'colonize', 'espionage', 'recycle', 'expedition') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid mission type');
  END IF;

  IF p_target_type NOT IN ('planet', 'moon') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid target type');
  END IF;

  IF p_mission_type = 'expedition' AND p_target_position != 16 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Expeditions must target position 16');
  END IF;

  IF p_mission_type != 'expedition' AND p_target_position = 16 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only expeditions can target position 16');
  END IF;

  -- [PATCH 20260424] refrescar recursos antes de validar cargo
  PERFORM sync_planet_resources(p_origin_planet_id);
  SELECT * INTO v_resources FROM planet_resources WHERE planet_id = p_origin_planet_id FOR UPDATE;
  IF v_resources IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planet resources not found');
  END IF;

  SELECT COALESCE(
    (
      SELECT level
      FROM user_technologies ut
      JOIN technology_types tt ON ut.technology_type_id = tt.id
      WHERE ut.user_id = v_user_id AND tt.code = 'computer_tech'
    ),
    0
  ) INTO v_computer_tech_level;

  v_has_admiral := has_active_officer(v_user_id, 'admiral');
  v_max_fleet_slots := 1 + v_computer_tech_level + (CASE WHEN v_has_admiral THEN 2 ELSE 0 END);

  IF v_has_admiral THEN
    v_admiral_speed_bonus := 0.2;
  END IF;

  SELECT COUNT(*) INTO v_active_fleet_count
  FROM fleets
  WHERE user_id = v_user_id AND is_completed = false;

  IF v_active_fleet_count >= v_max_fleet_slots THEN
    RETURN jsonb_build_object('success', false, 'error', 'No available fleet slots');
  END IF;

  FOR v_ship IN
    SELECT * FROM jsonb_to_recordset(p_fleet_ships) AS x(ship_type_id int, quantity int)
  LOOP
    IF v_ship.quantity > 0 THEN
      SELECT * INTO v_ship_type FROM ship_types WHERE id = v_ship.ship_type_id;
      IF v_ship_type IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid ship type: ' || v_ship.ship_type_id);
      END IF;

      SELECT * INTO v_planet_ship
      FROM planet_ships
      WHERE planet_id = p_origin_planet_id AND ship_type_id = v_ship.ship_type_id;

      IF v_planet_ship IS NULL OR v_planet_ship.quantity < v_ship.quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not enough ships: ' || v_ship_type.name);
      END IF;

      v_total_cargo_capacity := v_total_cargo_capacity + (v_ship_type.cargo_capacity * v_ship.quantity);
    END IF;
  END LOOP;

  SELECT id INTO v_colony_ship_type_id FROM ship_types WHERE code = 'colony_ship';
  SELECT id INTO v_recycler_type_id FROM ship_types WHERE code = 'recycler';
  SELECT id INTO v_mega_recycler_type_id FROM ship_types WHERE code = 'mega_recycler';
  SELECT id INTO v_probe_type_id FROM ship_types WHERE code = 'espionage_probe';

  -- [BLOCK PROBE-ONLY ATTACKS] Las sondas de espionaje SOLO sirven para espiar, no pueden atacar
  IF p_mission_type = 'attack' THEN
    PERFORM 1 FROM jsonb_to_recordset(p_fleet_ships) AS x(ship_type_id int, quantity int)
    WHERE x.quantity > 0 AND x.ship_type_id != v_probe_type_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'No puedes atacar solo con sondas de espionaje. Las sondas solo sirven para espiar.');
    END IF;
  END IF;


  IF p_mission_type = 'colonize' THEN
    SELECT true INTO v_has_required_ship
    FROM jsonb_to_recordset(p_fleet_ships) AS x(ship_type_id int, quantity int)
    WHERE x.ship_type_id = v_colony_ship_type_id AND x.quantity >= 1;

    IF NOT COALESCE(v_has_required_ship, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Colonization requires a Colony Ship');
    END IF;
  END IF;

  IF p_mission_type = 'recycle' THEN
    SELECT true INTO v_has_required_ship
    FROM jsonb_to_recordset(p_fleet_ships) AS x(ship_type_id int, quantity int)
    WHERE x.ship_type_id IN (v_recycler_type_id, v_mega_recycler_type_id) AND x.quantity >= 1;

    IF NOT COALESCE(v_has_required_ship, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Recycling requires a Recycler or Mega Recycler');
    END IF;
  END IF;

  IF p_mission_type = 'espionage' THEN
    SELECT true INTO v_has_required_ship
    FROM jsonb_to_recordset(p_fleet_ships) AS x(ship_type_id int, quantity int)
    WHERE x.ship_type_id = v_probe_type_id AND x.quantity >= 1;

    IF NOT COALESCE(v_has_required_ship, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Espionage requires an Espionage Probe');
    END IF;
  END IF;

  v_total_cargo_used := COALESCE(p_cargo_metal, 0) + COALESCE(p_cargo_crystal, 0) + COALESCE(p_cargo_deuterium, 0);
  IF v_total_cargo_used > v_total_cargo_capacity THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cargo exceeds fleet capacity');
  END IF;

  v_distance := fleet_calc_distance(
    v_planet.galaxy,
    v_planet.solar_system,
    v_planet.position,
    p_target_galaxy,
    p_target_system,
    p_target_position
  );

  v_slowest_speed := fleet_calc_slowest_speed(p_fleet_ships, v_user_id);
  IF v_slowest_speed <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No valid ships with speed selected');
  END IF;

  v_flight_time := fleet_calc_flight_time(v_distance, v_slowest_speed, p_speed_percent, v_admiral_speed_bonus);
  -- Apply daily mission speed bonus (stackable with admiral and Plus)
  v_flight_time := GREATEST(10, FLOOR(v_flight_time / (1.0 + COALESCE(get_user_daily_mission_speed_bonus(v_user_id), 0))));

  IF is_user_plus(v_user_id) THEN
    v_flight_time := GREATEST(10, FLOOR(v_flight_time * 0.90));
  END IF;

  v_fuel_consumption := fleet_calc_fuel(p_fleet_ships, v_distance, p_speed_percent);
  v_total_deut_needed := v_fuel_consumption + COALESCE(p_cargo_deuterium, 0);

  IF v_resources.deuterium < v_total_deut_needed THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient deuterium for fuel and cargo');
  END IF;

  IF v_resources.metal < COALESCE(p_cargo_metal, 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient metal for cargo');
  END IF;

  IF v_resources.crystal < COALESCE(p_cargo_crystal, 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient crystal for cargo');
  END IF;

  SELECT validate_fleet_mission INTO v_validation FROM validate_fleet_mission(
    v_user_id,
    p_origin_planet_id,
    p_target_galaxy,
    p_target_system,
    p_target_position,
    p_mission_type,
    p_target_type
  );

  IF v_validation IS NOT NULL AND NOT (v_validation->>'valid')::boolean THEN
    RETURN jsonb_build_object('success', false, 'error', v_validation->>'reason');
  END IF;

  v_arrival_time := now() + (v_flight_time || ' seconds')::interval;
  v_return_time := now() + ((v_flight_time * 2) || ' seconds')::interval;

  INSERT INTO fleets (
    user_id,
    origin_planet_id,
    target_galaxy,
    target_system,
    target_position,
    target_type,
    mission_type,
    cargo_metal,
    cargo_crystal,
    cargo_deuterium,
    departure_time,
    arrival_time,
    return_time
  ) VALUES (
    v_user_id,
    p_origin_planet_id,
    p_target_galaxy,
    p_target_system,
    p_target_position,
    p_target_type,
    p_mission_type,
    COALESCE(p_cargo_metal, 0),
    COALESCE(p_cargo_crystal, 0),
    COALESCE(p_cargo_deuterium, 0),
    now(),
    v_arrival_time,
    v_return_time
  ) RETURNING id INTO v_fleet_id;

  FOR v_ship IN
    SELECT * FROM jsonb_to_recordset(p_fleet_ships) AS x(ship_type_id int, quantity int)
  LOOP
    IF v_ship.quantity > 0 THEN
      INSERT INTO fleet_ships (fleet_id, ship_type_id, quantity)
      VALUES (v_fleet_id, v_ship.ship_type_id, v_ship.quantity);

      UPDATE planet_ships
      SET quantity = quantity - v_ship.quantity
      WHERE planet_id = p_origin_planet_id AND ship_type_id = v_ship.ship_type_id;
    END IF;
  END LOOP;

  UPDATE planet_resources
  SET metal = metal - COALESCE(p_cargo_metal, 0),
      crystal = crystal - COALESCE(p_cargo_crystal, 0),
      deuterium = deuterium - v_total_deut_needed
  WHERE planet_id = p_origin_planet_id;

  RETURN jsonb_build_object(
    'success', true,
    'fleet_id', v_fleet_id,
    'arrival_time', v_arrival_time,
    'return_time', v_return_time,
    'flight_time', v_flight_time,
    'fuel_consumption', v_fuel_consumption
  );
END;
 $$;


--
-- TOC entry 628 (class 1255 OID 18568)
-- Name: secure_start_research(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.secure_start_research(p_planet_id uuid, p_tech_type_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    SET lock_timeout TO '30s'
    AS $$  
DECLARE
v_validation jsonb;
v_planet RECORD;
v_tech_type RECORD;
v_current_level integer;
v_resources RECORD;
v_cost_metal bigint;
v_cost_crystal bigint;
v_cost_deuterium bigint;
v_effective_lab_level integer;
v_research_time integer;
v_start_time timestamptz;
v_end_time timestamptz;
v_existing_research boolean;
v_game_speed integer;
v_has_technocrat boolean;
v_lab_in_queue boolean;
v_research_lab_type_id integer;
v_total_energy integer;
v_scaled_energy bigint;
BEGIN
IF auth.uid() IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
END IF;

IF is_user_in_vacation_mode(auth.uid()) THEN
RETURN jsonb_build_object('success', false, 'error', 'Cannot research while in vacation mode');
END IF;

SELECT * INTO v_planet FROM planets WHERE id = p_planet_id AND user_id = auth.uid();
IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Planet not found or not owned');
END IF;

SELECT EXISTS(
SELECT 1 FROM user_technologies
WHERE user_id = auth.uid() AND is_researching = true
) INTO v_existing_research;

IF v_existing_research THEN
RETURN jsonb_build_object('success', false, 'error', 'Research already in progress');
END IF;

SELECT id INTO v_research_lab_type_id FROM building_types WHERE code = 'research_lab';
IF v_research_lab_type_id IS NOT NULL THEN
SELECT EXISTS(
SELECT 1 FROM building_queue
WHERE planet_id = p_planet_id AND building_type_id = v_research_lab_type_id
) INTO v_lab_in_queue;

IF v_lab_in_queue THEN
RETURN jsonb_build_object('success', false, 'error', 'Cannot research while Research Lab is being upgraded');
END IF;
END IF;

v_validation := validate_research_requirements(auth.uid(), p_planet_id, p_tech_type_id);
IF NOT (v_validation->>'valid')::boolean THEN
RETURN jsonb_build_object('success', false, 'error', 'Requirements not met', 'details', v_validation);
END IF;

SELECT * INTO v_tech_type FROM technology_types WHERE id = p_tech_type_id;
IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Technology type not found');
END IF;

SELECT COALESCE(ut.level, 0) INTO v_current_level
FROM user_technologies ut
WHERE ut.user_id = auth.uid() AND ut.technology_type_id = p_tech_type_id;
IF v_current_level IS NULL THEN v_current_level := 0; END IF;

IF v_current_level >= v_tech_type.max_level THEN
RETURN jsonb_build_object('success', false, 'error', 'Max level reached');
END IF;

-- Check energy requirement scaled by level (e.g. Graviton Technology)
IF v_tech_type.energy_required > 0 THEN
SELECT COALESCE((calculate_planet_resources(p_planet_id)->>'energy_max')::integer, 0)
INTO v_total_energy;

v_scaled_energy := CEIL(v_tech_type.energy_required * POWER(v_tech_type.cost_factor, v_current_level));

IF COALESCE(v_total_energy, 0) < v_scaled_energy THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Insufficient energy production. Required: ' || v_scaled_energy || ', Available: ' || COALESCE(v_total_energy, 0)
);
END IF;
END IF;

v_cost_metal := FLOOR(v_tech_type.base_metal * POWER(v_tech_type.cost_factor, v_current_level));
v_cost_crystal := FLOOR(v_tech_type.base_crystal * POWER(v_tech_type.cost_factor, v_current_level));
v_cost_deuterium := FLOOR(v_tech_type.base_deuterium * POWER(v_tech_type.cost_factor, v_current_level));

SELECT * INTO v_resources FROM planet_resources WHERE planet_id = p_planet_id FOR UPDATE;
IF v_resources.metal < v_cost_metal OR v_resources.crystal < v_cost_crystal OR v_resources.deuterium < v_cost_deuterium THEN
RETURN jsonb_build_object('success', false, 'error', 'Insufficient resources');
END IF;

v_effective_lab_level := calculate_irn_lab_level(auth.uid(), p_planet_id);
IF v_effective_lab_level IS NULL OR v_effective_lab_level < 1 THEN
v_effective_lab_level := 1;
END IF;

v_game_speed := get_game_speed();
v_has_technocrat := has_active_officer(auth.uid(), 'technocrat');

v_research_time := GREATEST(1, FLOOR((v_cost_metal + v_cost_crystal) / (1000.0 * (1 + v_effective_lab_level)) * 3600 / v_game_speed));

IF v_has_technocrat THEN
v_research_time := GREATEST(1, FLOOR(v_research_time * 0.75));
END IF;

-- VIP Plus: -10% research time (stacks with Technocrat)
IF is_user_plus(auth.uid()) THEN
  v_research_time := GREATEST(1, FLOOR(v_research_time * 0.90));
END IF;

v_start_time := now();
v_end_time := v_start_time + (v_research_time || ' seconds')::interval;

UPDATE planet_resources
SET metal = metal - v_cost_metal,
crystal = crystal - v_cost_crystal,
deuterium = deuterium - v_cost_deuterium,
last_update = now()
WHERE planet_id = p_planet_id;

ALTER TABLE user_technologies DISABLE TRIGGER trigger_research_points;

INSERT INTO user_technologies (
user_id, technology_type_id, level, is_researching,
research_start_time, research_end_time, research_planet_id
) VALUES (
auth.uid(), p_tech_type_id, v_current_level, true,
v_start_time, v_end_time, p_planet_id
)
ON CONFLICT (user_id, technology_type_id) DO UPDATE SET
is_researching = true,
research_start_time = v_start_time,
research_end_time = v_end_time,
research_planet_id = p_planet_id;

ALTER TABLE user_technologies ENABLE TRIGGER trigger_research_points;

RETURN jsonb_build_object(
'success', true,
'target_level', v_current_level + 1,
'start_time', v_start_time,
'end_time', v_end_time,
'research_time_seconds', v_research_time,
'technocrat_bonus', v_has_technocrat
);
END;
  $$;


--
-- TOC entry 792 (class 1255 OID 19328)
-- Name: send_broadcast_message(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_broadcast_message(p_subject text, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_recipient record;
  v_count integer := 0;
BEGIN
  v_admin_id := auth.uid();
  
  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;
  
  FOR v_recipient IN 
    SELECT id FROM profiles WHERE id != v_admin_id
  LOOP
    INSERT INTO messages (
      sender_id,
      recipient_id,
      subject,
      body,
      message_type,
      is_read
    ) VALUES (
      v_admin_id,
      v_recipient.id,
      p_subject,
      p_body,
      'broadcast',
      false
    );
    
    v_count := v_count + 1;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'messages_sent', v_count
  );
END;
$$;


--
-- TOC entry 952 (class 1255 OID 20465)
-- Name: send_fleet(uuid, integer, integer, integer, text, jsonb, numeric, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_fleet(p_origin_planet_id uuid, p_target_galaxy integer, p_target_system integer, p_target_position integer, p_mission_type text, p_ships jsonb, p_cargo_metal numeric DEFAULT 0, p_cargo_crystal numeric DEFAULT 0, p_cargo_deuterium numeric DEFAULT 0, p_speed_percent integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid;
  v_origin_planet RECORD;
  v_distance numeric;
  v_slowest_speed integer;
  v_flight_time interval;
  v_fuel_consumption numeric;
  v_ship RECORD;
  v_ship_type RECORD;
  v_available_quantity integer;
  v_total_cargo_capacity numeric := 0;
  v_total_cargo numeric;
  v_fleet_id uuid;
  v_arrival_time timestamptz;
  v_return_time timestamptz;
  v_mission_validation jsonb;
  v_target_type text := 'planet';
  v_game_speed numeric;
  v_has_combat_ships boolean := false;
  v_only_probes boolean := true;
  v_probe_type_id integer;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_origin_planet FROM planets WHERE id = p_origin_planet_id AND user_id = v_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planeta no encontrado o no te pertenece');
  END IF;

  IF p_ships IS NULL OR jsonb_array_length(p_ships) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Debes seleccionar al menos una nave');
  END IF;

  -- Get espionage probe type id
  SELECT id INTO v_probe_type_id FROM ship_types WHERE code = 'espionage_probe';

  v_slowest_speed := 999999999;
  FOR v_ship IN SELECT * FROM jsonb_array_elements(p_ships)
  LOOP
    SELECT * INTO v_ship_type FROM ship_types WHERE id = (v_ship->>'ship_type_id')::integer;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'Tipo de nave no valido');
    END IF;

    -- FOR UPDATE lock to prevent race condition with concurrent fleet sends
    SELECT COALESCE(ps.quantity, 0) INTO v_available_quantity
    FROM planet_ships ps WHERE ps.planet_id = p_origin_planet_id AND ps.ship_type_id = v_ship_type.id
    FOR UPDATE;

    IF v_available_quantity < (v_ship->>'quantity')::integer THEN
      RETURN jsonb_build_object('success', false, 'error', format('No tienes suficientes %s', v_ship_type.name));
    END IF;

    v_total_cargo_capacity := v_total_cargo_capacity + (v_ship_type.cargo_capacity * (v_ship->>'quantity')::integer);
    IF v_ship_type.speed < v_slowest_speed THEN
      v_slowest_speed := v_ship_type.speed;
    END IF;

    IF v_ship_type.weapon > 0 THEN
      v_has_combat_ships := true;
    END IF;

    -- Check if this is NOT a probe
    IF v_ship_type.id != v_probe_type_id THEN
      v_only_probes := false;
    END IF;
  END LOOP;

  -- Block probe-only expeditions
  IF p_mission_type = 'expedition' AND v_only_probes THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes enviar expediciones solo con Sondas de Espionaje. Necesitas naves con capacidad de carga.');
  END IF;

  v_total_cargo := p_cargo_metal + p_cargo_crystal + p_cargo_deuterium;
  IF v_total_cargo > v_total_cargo_capacity THEN
    RETURN jsonb_build_object('success', false, 'error', format('Capacidad de carga excedida. Maximo: %s', floor(v_total_cargo_capacity)));
  END IF;

  v_mission_validation := validate_fleet_mission(v_user_id, p_origin_planet_id, p_target_galaxy, p_target_system, p_target_position, p_mission_type);
  IF NOT (v_mission_validation->>'valid')::boolean THEN
    RETURN jsonb_build_object('success', false, 'error', v_mission_validation->>'reason');
  END IF;

  IF p_mission_type = 'colonize' THEN
    DECLARE
      v_colony_ship_id integer;
      v_has_colony_ship boolean := false;
    BEGIN
      SELECT id INTO v_colony_ship_id FROM ship_types WHERE code = 'colony_ship';
      FOR v_ship IN SELECT * FROM jsonb_array_elements(p_ships)
      LOOP
        IF (v_ship->>'ship_type_id')::integer = v_colony_ship_id AND (v_ship->>'quantity')::integer > 0 THEN
          v_has_colony_ship := true;
          EXIT;
        END IF;
      END LOOP;
      IF NOT v_has_colony_ship THEN
        RETURN jsonb_build_object('success', false, 'error', 'Necesitas una Nave Colonizadora para colonizar');
      END IF;
    END;
  END IF;

  IF p_mission_type = 'recycle' THEN
    DECLARE
      v_recycler_id integer;
      v_has_recycler boolean := false;
    BEGIN
      SELECT id INTO v_recycler_id FROM ship_types WHERE code = 'recycler';
      FOR v_ship IN SELECT * FROM jsonb_array_elements(p_ships)
      LOOP
        IF (v_ship->>'ship_type_id')::integer = v_recycler_id AND (v_ship->>'quantity')::integer > 0 THEN
          v_has_recycler := true;
          EXIT;
        END IF;
      END LOOP;
      IF NOT v_has_recycler THEN
        RETURN jsonb_build_object('success', false, 'error', 'Necesitas Recicladores para recolectar escombros');
      END IF;
    END;
  END IF;

  v_distance := calculate_distance(
    v_origin_planet.galaxy, v_origin_planet.solar_system, v_origin_planet.position,
    p_target_galaxy, p_target_system, p_target_position
  );

  SELECT COALESCE(
    (SELECT (value#>>'{}')::numeric FROM game_config WHERE key = 'fleet_speed'),
    1
  ) INTO v_game_speed;

  v_flight_time := calculate_flight_time(v_distance, v_slowest_speed, p_speed_percent, v_game_speed);

  v_fuel_consumption := 0;
  FOR v_ship IN SELECT * FROM jsonb_array_elements(p_ships)
  LOOP
    SELECT * INTO v_ship_type FROM ship_types WHERE id = (v_ship->>'ship_type_id')::integer;
    v_fuel_consumption := v_fuel_consumption +
      (1 + FLOOR(((v_ship_type.fuel_consumption * (v_ship->>'quantity')::integer) * v_distance) / 35000 * POWER(p_speed_percent::numeric / 100 + 1, 2)));
  END LOOP;

  -- Lock planet_resources FOR UPDATE to prevent concurrent fuel depletion
  DECLARE
    v_current_deuterium numeric;
  BEGIN
    SELECT deuterium INTO v_current_deuterium FROM planet_resources WHERE planet_id = p_origin_planet_id FOR UPDATE;
    IF v_current_deuterium < (v_fuel_consumption + p_cargo_deuterium) THEN
      RETURN jsonb_build_object('success', false, 'error', format('No tienes suficiente deuterio. Necesitas: %s (combustible) + %s (carga)', floor(v_fuel_consumption), floor(p_cargo_deuterium)));
    END IF;
  END;

  UPDATE planet_resources
  SET metal = metal - p_cargo_metal,
      crystal = crystal - p_cargo_crystal,
      deuterium = deuterium - p_cargo_deuterium - v_fuel_consumption
  WHERE planet_id = p_origin_planet_id;

  FOR v_ship IN SELECT * FROM jsonb_array_elements(p_ships)
  LOOP
    UPDATE planet_ships
    SET quantity = quantity - (v_ship->>'quantity')::integer
    WHERE planet_id = p_origin_planet_id AND ship_type_id = (v_ship->>'ship_type_id')::integer;
  END LOOP;

  IF p_mission_type = 'expedition' THEN
    v_target_type := 'deep_space';
  END IF;

  v_arrival_time := NOW() + v_flight_time;
  v_return_time := NOW() + (v_flight_time * 2);

  IF p_mission_type = 'expedition' THEN
    v_return_time := v_arrival_time + v_flight_time + INTERVAL '1 hour';
  END IF;

  INSERT INTO fleets (
    user_id, origin_planet_id, target_galaxy, target_system, target_position, target_type,
    mission_type, cargo_metal, cargo_crystal, cargo_deuterium,
    departure_time, arrival_time, return_time, is_returning, is_completed
  ) VALUES (
    v_user_id, p_origin_planet_id, p_target_galaxy, p_target_system, p_target_position, v_target_type,
    p_mission_type, p_cargo_metal, p_cargo_crystal, p_cargo_deuterium,
    NOW(), v_arrival_time, v_return_time, false, false
  ) RETURNING id INTO v_fleet_id;

  FOR v_ship IN SELECT * FROM jsonb_array_elements(p_ships)
  LOOP
    INSERT INTO fleet_ships (fleet_id, ship_type_id, quantity)
    VALUES (v_fleet_id, (v_ship->>'ship_type_id')::integer, (v_ship->>'quantity')::integer);
  END LOOP;

  PERFORM update_user_points(v_user_id);

  RETURN jsonb_build_object(
    'success', true,
    'fleet_id', v_fleet_id,
    'arrival_time', v_arrival_time,
    'return_time', v_return_time,
    'fuel_consumption', floor(v_fuel_consumption),
    'expedition_charged', COALESCE((v_mission_validation->>'expedition_charged')::boolean, false),
    'expedition_fee', COALESCE((v_mission_validation->>'expedition_fee')::numeric, 0)
  );
END;
$$;


--
-- TOC entry 833 (class 1255 OID 19704)
-- Name: send_market_telegram_notification(uuid, text, text, text, bigint, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_market_telegram_notification(p_listing_id uuid, p_seller_username text, p_listing_type text, p_item_code text, p_quantity bigint, p_price_per_unit numeric, p_total_price numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_config RECORD;
  v_request_id bigint;
BEGIN
  SELECT edge_function_url, is_enabled, anon_key INTO v_config
  FROM market_notification_config
  WHERE id = 1;
  
  IF v_config IS NULL OR NOT v_config.is_enabled OR v_config.edge_function_url = '' THEN
    RETURN;
  END IF;
  
  SELECT net.http_post(
    url := v_config.edge_function_url,
    body := jsonb_build_object(
      'listing_id', p_listing_id,
      'seller_username', p_seller_username,
      'listing_type', p_listing_type,
      'item_code', p_item_code,
      'quantity', p_quantity,
      'price_per_unit', p_price_per_unit,
      'total_price', p_total_price
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', v_config.anon_key
    )
  ) INTO v_request_id;
  
EXCEPTION
  WHEN OTHERS THEN
    RAISE NOTICE 'Market notification error: %', SQLERRM;
END;
$$;


--
-- TOC entry 1059 (class 1255 OID 21331)
-- Name: send_p2p_offer_telegram_notification(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_p2p_offer_telegram_notification(p_offer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg       p2p_notification_config%ROWTYPE;
  v_offer     p2p_offers%ROWTYPE;
  v_username  text;
  v_methods   text[];
  v_amount_fxu_eq numeric;
  v_payload   jsonb;
  v_req_id    bigint;
BEGIN
  SELECT * INTO v_cfg FROM p2p_notification_config WHERE id = 1;
  IF v_cfg IS NULL OR NOT v_cfg.is_enabled OR coalesce(v_cfg.edge_function_url,'') = '' THEN
    RETURN;
  END IF;

  SELECT * INTO v_offer FROM p2p_offers WHERE id = p_offer_id;
  IF NOT FOUND OR v_offer.status <> 'active' THEN
    RETURN;
  END IF;

  -- Umbral mínimo (FXU-eq) para evitar spam con ofertas minúsculas
  v_amount_fxu_eq := CASE WHEN v_offer.asset = 'FXU'
                          THEN v_offer.available_amount
                          ELSE v_offer.available_amount * 10000
                     END;
  IF v_amount_fxu_eq < v_cfg.min_amount_fxu_eq THEN
    RETURN;
  END IF;

  SELECT username INTO v_username FROM profiles WHERE id = v_offer.user_id;

  SELECT COALESCE(array_agg(pm.name), '{}')
    INTO v_methods
    FROM unnest(v_offer.payment_method_ids) AS oid
    JOIN p2p_payment_methods pm ON pm.id = oid;

  v_payload := jsonb_build_object(
    'offer_id',         v_offer.id,
    'seller_username',  COALESCE(v_username, 'Trader'),
    'side',             v_offer.side,
    'asset',            v_offer.asset,
    'fiat_currency',    v_offer.fiat_currency,
    'price_per_unit',   v_offer.price_per_unit,
    'available_amount', v_offer.available_amount,
    'min_trade_amount', v_offer.min_trade_amount,
    'max_trade_amount', v_offer.max_trade_amount,
    'payment_methods',  v_methods
  );

  BEGIN
    SELECT net.http_post(
      url := v_cfg.edge_function_url,
      body := v_payload,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'apikey',       v_cfg.anon_key,
        'Authorization','Bearer ' || v_cfg.anon_key
      )
    ) INTO v_req_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'P2P Telegram notification error: %', SQLERRM;
  END;
END;
$$;


