-- TOC entry 7797 (class 0 OID 0)
-- Dependencies: 1059
-- Name: FUNCTION send_p2p_offer_telegram_notification(p_offer_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.send_p2p_offer_telegram_notification(p_offer_id uuid) IS 'Fase 10: envía la oferta P2P a Telegram vía edge function notify-p2p-offer.';


--
-- TOC entry 814 (class 1255 OID 19629)
-- Name: send_public_chat_message(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_public_chat_message(p_message text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_username text;
  v_avatar_url text;
  v_alliance_tag text;
  v_message_id uuid;
  v_is_vacation boolean;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Check vacation mode
  SELECT vacation_mode INTO v_is_vacation
  FROM profiles
  WHERE id = v_user_id;
  
  IF v_is_vacation THEN
    RAISE EXCEPTION 'Cannot send messages while in vacation mode';
  END IF;
  
  -- Validate message
  IF p_message IS NULL OR trim(p_message) = '' THEN
    RAISE EXCEPTION 'Message cannot be empty';
  END IF;
  
  IF char_length(p_message) > 500 THEN
    RAISE EXCEPTION 'Message too long (max 500 characters)';
  END IF;
  
  -- Get user info
  SELECT username, avatar_url INTO v_username, v_avatar_url
  FROM profiles
  WHERE id = v_user_id;
  
  -- Get alliance tag if member of alliance
  SELECT a.tag INTO v_alliance_tag
  FROM alliance_members am
  JOIN alliances a ON a.id = am.alliance_id
  WHERE am.user_id = v_user_id;
  
  -- Insert message
  INSERT INTO public_chat_messages (user_id, username, avatar_url, alliance_tag, message)
  VALUES (v_user_id, v_username, v_avatar_url, v_alliance_tag, trim(p_message))
  RETURNING id INTO v_message_id;
  
  -- Cleanup old messages (keep last 500)
  DELETE FROM public_chat_messages
  WHERE id NOT IN (
    SELECT id FROM public_chat_messages
    ORDER BY created_at DESC
    LIMIT 500
  );
  
  RETURN v_message_id;
END;
$$;


--
-- TOC entry 1169 (class 1255 OID 22633)
