--
-- TOC entry 1151 (class 1255 OID 22401)
-- Name: set_initial_deposits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_initial_deposits() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deposits RECORD;
  v_base_metal numeric;
BEGIN
  IF NEW.is_main_planet = false AND NEW.metal_deposit IS NULL THEN
    SELECT COALESCE(value::numeric, 30000) INTO v_base_metal
    FROM game_settings WHERE key = 'depletion_base_metal_per_field';
    
    -- Use fields_max at creation time (before any terraforming)
    SELECT * INTO v_deposits FROM calculate_initial_deposits(
      NEW.fields_max, NEW.position, v_base_metal
    );
    
    NEW.metal_deposit := v_deposits.metal_deposit;
    NEW.crystal_deposit := v_deposits.crystal_deposit;
    NEW.deuterium_deposit := v_deposits.deuterium_deposit;
    NEW.metal_initial_deposit := v_deposits.metal_deposit;
    NEW.crystal_initial_deposit := v_deposits.crystal_deposit;
    NEW.deuterium_initial_deposit := v_deposits.deuterium_deposit;
    NEW.planet_status := 'active';
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- TOC entry 931 (class 1255 OID 20390)
-- Name: set_market_listing_purchasable_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_market_listing_purchasable_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cooldown_minutes integer;
BEGIN
  SELECT COALESCE(value::integer, 5) INTO v_cooldown_minutes
  FROM game_settings
  WHERE key = 'market_listing_cooldown_minutes';

  v_cooldown_minutes := COALESCE(v_cooldown_minutes, 5);

  NEW.purchasable_at := NEW.created_at + (v_cooldown_minutes || ' minutes')::interval;
  RETURN NEW;
END;
$$;


--
-- TOC entry 1020 (class 1255 OID 20935)
-- Name: set_planet_autopilot_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_planet_autopilot_role(p_planet_id uuid, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF NOT has_autopilot_access(auth.uid()) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Necesitas el Oficial Androide activo o habilitación del admin');
  END IF;

  IF p_role NOT IN ('balanced', 'miner', 'military', 'research', 'colonizer') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rol inválido');
  END IF;

  UPDATE public.planets
  SET autopilot_role = p_role
  WHERE id = p_planet_id
    AND user_id = auth.uid()
    AND planet_type = 'planet'
    AND NOT is_destroyed;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Planeta no encontrado');
  END IF;

  RETURN jsonb_build_object('success', true, 'role', p_role);
END;
$$;


--
-- TOC entry 637 (class 1255 OID 18638)
-- Name: set_user_referral(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_user_referral(p_referral_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_referrer_id uuid;
  v_current_referrer uuid;
  v_profile_exists boolean;
  v_rows_updated int;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  IF p_referral_code IS NULL OR TRIM(p_referral_code) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Codigo de referido vacio');
  END IF;

  -- Check if profile exists
  SELECT EXISTS(SELECT 1 FROM profiles WHERE id = v_user_id) INTO v_profile_exists;
  
  IF NOT v_profile_exists THEN
    RETURN jsonb_build_object('success', false, 'error', 'Perfil no encontrado, intenta de nuevo en unos segundos');
  END IF;

  -- Check if user already has a referrer (can only set once)
  SELECT referred_by INTO v_current_referrer FROM profiles WHERE id = v_user_id;
  
  IF v_current_referrer IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya tienes un referidor asignado');
  END IF;

  -- Find referrer by code
  SELECT id INTO v_referrer_id FROM profiles WHERE referral_code = UPPER(TRIM(p_referral_code));
  
  IF v_referrer_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Codigo de referido no encontrado');
  END IF;

  -- Cannot refer yourself
  IF v_referrer_id = v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'No puedes referirte a ti mismo');
  END IF;

  -- Set the referral and get rows affected
  UPDATE profiles SET referred_by = v_referrer_id WHERE id = v_user_id AND referred_by IS NULL;
  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  
  IF v_rows_updated = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No se pudo asignar el referido');
  END IF;

  RETURN jsonb_build_object('success', true, 'message', 'Referido asignado correctamente');
END;
$$;


--
-- TOC entry 652 (class 1255 OID 18710)
-- Name: setup_admin_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.setup_admin_user(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
