--
-- TOC entry 711 (class 1255 OID 18939)
-- Name: simulate_xnova_combat(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.simulate_xnova_combat(p_attackers jsonb, p_defenders jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_round integer := 0;
  v_max_rounds integer := 6;
  v_attacker_units jsonb;
  v_defender_units jsonb;
  v_result text := 'draw';
  v_attacker_losses_metal numeric := 0;
  v_attacker_losses_crystal numeric := 0;
  v_defender_fleet_losses_metal numeric := 0;
  v_defender_fleet_losses_crystal numeric := 0;
  v_defender_defense_losses_metal numeric := 0;
  v_defender_defense_losses_crystal numeric := 0;
  v_defender_losses_metal numeric := 0;
  v_defender_losses_crystal numeric := 0;
  v_debris_metal numeric := 0;
  v_debris_crystal numeric := 0;
  v_rounds_data jsonb := '[]'::jsonb;
  v_destroyed_defenses jsonb := '[]'::jsonb;
  v_initial_attackers jsonb;
  v_initial_defenders jsonb;
  v_attacker_total_units integer;
  v_defender_total_units integer;
  v_unit jsonb;
  v_target jsonb;
  v_target_idx integer;
  v_damage numeric;
  v_shield_absorbed numeric;
  v_hull_damage numeric;
  v_i integer;
  v_j integer;
  v_k integer;
  v_unit_hull numeric;
  v_shield_per_unit numeric;
  v_shield_available numeric;
  v_rf_value integer;
  v_rf_continue boolean;
  v_rf_shots integer;
  v_target_qty integer;
  v_units_killed integer;
  v_hull_pool numeric;
  v_random_pick integer;
  v_cumulative integer;
  v_destroy_fraction numeric;
  v_alive_count integer;
  v_fleet_cdr numeric;
  v_defense_cdr numeric;
  v_rf_target_code text;
BEGIN
  v_attacker_units := p_attackers;
  v_defender_units := p_defenders;
  v_initial_attackers := p_attackers;
  v_initial_defenders := p_defenders;

  FOR v_i IN 0..(jsonb_array_length(v_attacker_units) - 1) LOOP
    v_attacker_units := jsonb_set(v_attacker_units, ARRAY[v_i::text, 'hull_damage_pool'], to_jsonb(0::numeric));
  END LOOP;
  FOR v_i IN 0..(jsonb_array_length(v_defender_units) - 1) LOOP
    v_defender_units := jsonb_set(v_defender_units, ARRAY[v_i::text, 'hull_damage_pool'], to_jsonb(0::numeric));
  END LOOP;

  SELECT COALESCE(SUM((u->>'quantity')::integer), 0) INTO v_defender_total_units
  FROM jsonb_array_elements(v_defender_units) u;

  IF v_defender_total_units = 0 THEN
    RETURN jsonb_build_object(
      'result', 'attacker_won',
      'rounds', 0,
      'rounds_data', '[]'::jsonb,
      'attacker_remaining', v_attacker_units,
      'defender_remaining', '[]'::jsonb,
      'debris_metal', 0,
      'debris_crystal', 0,
      'attacker_losses_metal', 0,
      'attacker_losses_crystal', 0,
      'defender_losses_metal', 0,
      'defender_losses_crystal', 0,
      'destroyed_defenses', '[]'::jsonb,
      'initial_attacker', v_initial_attackers,
      'initial_defender', v_initial_defenders
    );
  END IF;

  WHILE v_round < v_max_rounds LOOP
    v_round := v_round + 1;

    FOR v_i IN 0..(jsonb_array_length(v_attacker_units) - 1) LOOP
      v_attacker_units := jsonb_set(
        v_attacker_units,
        ARRAY[v_i::text, 'shield_pool'],
        to_jsonb(((v_attacker_units->v_i->>'shield')::numeric * (v_attacker_units->v_i->>'quantity')::integer)::numeric)
      );
    END LOOP;

    FOR v_i IN 0..(jsonb_array_length(v_defender_units) - 1) LOOP
      v_defender_units := jsonb_set(
        v_defender_units,
        ARRAY[v_i::text, 'shield_pool'],
        to_jsonb(((v_defender_units->v_i->>'shield')::numeric * (v_defender_units->v_i->>'quantity')::integer)::numeric)
      );
    END LOOP;

    SELECT COALESCE(SUM((u->>'quantity')::integer), 0) INTO v_attacker_total_units
    FROM jsonb_array_elements(v_attacker_units) u;

    SELECT COALESCE(SUM((u->>'quantity')::integer), 0) INTO v_defender_total_units
    FROM jsonb_array_elements(v_defender_units) u;

    IF v_attacker_total_units = 0 OR v_defender_total_units = 0 THEN
      EXIT;
    END IF;

    -- Attackers fire at defenders
    FOR v_i IN 0..(jsonb_array_length(v_attacker_units) - 1) LOOP
      v_unit := v_attacker_units->v_i;
      IF (v_unit->>'quantity')::integer <= 0 THEN CONTINUE; END IF;

      FOR v_k IN 1..(v_unit->>'quantity')::integer LOOP
        v_rf_continue := true;
        v_rf_shots := 0;
        v_rf_target_code := NULL;

        WHILE v_rf_continue LOOP
          v_rf_shots := v_rf_shots + 1;
          IF v_rf_shots > 100 THEN EXIT; END IF;

          IF v_rf_target_code IS NULL THEN
            -- Primer disparo: objetivo aleatorio entre todos los defensores vivos
            v_alive_count := 0;
            FOR v_j IN 0..(jsonb_array_length(v_defender_units) - 1) LOOP
              v_alive_count := v_alive_count + GREATEST(0, (v_defender_units->v_j->>'quantity')::integer);
            END LOOP;
            IF v_alive_count = 0 THEN EXIT; END IF;

            v_random_pick := FLOOR(random() * v_alive_count)::integer;
            v_cumulative := 0;
            v_target_idx := 0;
            FOR v_j IN 0..(jsonb_array_length(v_defender_units) - 1) LOOP
              v_target_qty := (v_defender_units->v_j->>'quantity')::integer;
              IF v_target_qty > 0 THEN
                v_cumulative := v_cumulative + v_target_qty;
                IF v_random_pick < v_cumulative THEN
                  v_target_idx := v_j;
                  EXIT;
                END IF;
              END IF;
            END LOOP;
            v_target := v_defender_units->v_target_idx;
            v_target_qty := (v_target->>'quantity')::integer;
            IF v_target_qty <= 0 THEN v_rf_continue := false; CONTINUE; END IF;
            v_rf_target_code := v_target->>'code';
          ELSE
            -- Disparos de fuego rápido: solo a unidades del mismo tipo
            v_alive_count := 0;
            FOR v_j IN 0..(jsonb_array_length(v_defender_units) - 1) LOOP
              IF (v_defender_units->v_j->>'code') = v_rf_target_code THEN
                v_alive_count := v_alive_count + GREATEST(0, (v_defender_units->v_j->>'quantity')::integer);
              END IF;
            END LOOP;
            IF v_alive_count = 0 THEN EXIT; END IF;

            v_random_pick := FLOOR(random() * v_alive_count)::integer;
            v_cumulative := 0;
            v_target_idx := -1;
            FOR v_j IN 0..(jsonb_array_length(v_defender_units) - 1) LOOP
              IF (v_defender_units->v_j->>'code') = v_rf_target_code THEN
                v_target_qty := (v_defender_units->v_j->>'quantity')::integer;
                IF v_target_qty > 0 THEN
                  v_cumulative := v_cumulative + v_target_qty;
                  IF v_random_pick < v_cumulative THEN
                    v_target_idx := v_j;
                    EXIT;
                  END IF;
                END IF;
              END IF;
            END LOOP;
            IF v_target_idx = -1 THEN EXIT; END IF;
            v_target := v_defender_units->v_target_idx;
            v_target_qty := (v_target->>'quantity')::integer;
            IF v_target_qty <= 0 THEN v_rf_continue := false; CONTINUE; END IF;
          END IF;

          v_damage := (v_unit->>'weapon')::numeric;
          v_shield_per_unit := (v_target->>'shield')::numeric;

          IF v_shield_per_unit > 0 AND v_damage < v_shield_per_unit * 0.01 THEN
            NULL;
          ELSE
            v_shield_available := LEAST(v_shield_per_unit, GREATEST(0, (v_defender_units->v_target_idx->>'shield_pool')::numeric));
            v_shield_absorbed := LEAST(v_damage, v_shield_available);
            v_hull_damage := v_damage - v_shield_absorbed;

            IF v_shield_absorbed > 0 THEN
              v_defender_units := jsonb_set(v_defender_units, ARRAY[v_target_idx::text, 'shield_pool'],
                to_jsonb(GREATEST(0, (v_defender_units->v_target_idx->>'shield_pool')::numeric - v_shield_absorbed)));
            END IF;

            IF v_hull_damage > 0 THEN
              v_unit_hull := (v_target->>'hull')::numeric;
              v_hull_pool := (v_defender_units->v_target_idx->>'hull_damage_pool')::numeric + v_hull_damage;
              v_defender_units := jsonb_set(v_defender_units, ARRAY[v_target_idx::text, 'hull_damage_pool'], to_jsonb(v_hull_pool));

              IF v_unit_hull > 0 THEN
                v_units_killed := FLOOR(v_hull_pool / v_unit_hull)::integer;
                IF v_units_killed < v_target_qty THEN
                  v_destroy_fraction := (v_hull_pool - (v_units_killed::numeric * v_unit_hull)) / v_unit_hull;
                  IF v_destroy_fraction > 0.3 THEN
                    IF random() < v_destroy_fraction THEN v_units_killed := v_units_killed + 1; END IF;
                  END IF;
                END IF;
                v_units_killed := LEAST(v_units_killed, v_target_qty);

                IF v_units_killed > 0 THEN
                  v_defender_units := jsonb_set(v_defender_units, ARRAY[v_target_idx::text, 'quantity'], to_jsonb(v_target_qty - v_units_killed));
                  v_defender_units := jsonb_set(v_defender_units, ARRAY[v_target_idx::text, 'hull_damage_pool'],
                    to_jsonb(GREATEST(0, v_hull_pool - (v_units_killed::numeric * v_unit_hull))));
                  IF v_target_qty <= v_units_killed THEN
                    v_defender_units := jsonb_set(v_defender_units, ARRAY[v_target_idx::text, 'shield_pool'], to_jsonb(0::numeric));
                  END IF;

                  IF (v_target->>'is_defense')::boolean THEN
                    v_defender_defense_losses_metal := v_defender_defense_losses_metal + ((v_target->>'metal_cost')::numeric * v_units_killed);
                    v_defender_defense_losses_crystal := v_defender_defense_losses_crystal + ((v_target->>'crystal_cost')::numeric * v_units_killed);
                    v_destroyed_defenses := v_destroyed_defenses || jsonb_build_object(
                      'defense_type_id', (v_target->>'type_id')::integer,
                      'quantity', v_units_killed
                    );
                  ELSE
                    v_defender_fleet_losses_metal := v_defender_fleet_losses_metal + ((v_target->>'metal_cost')::numeric * v_units_killed);
                    v_defender_fleet_losses_crystal := v_defender_fleet_losses_crystal + ((v_target->>'crystal_cost')::numeric * v_units_killed);
                  END IF;
                END IF;
              END IF;
            END IF;
          END IF;

          v_rf_value := COALESCE((v_unit->'rapid_fire'->>((v_defender_units->v_target_idx->>'code')::text))::integer, 0);
          IF v_rf_value > 1 THEN
            IF random() < ((v_rf_value - 1.0) / v_rf_value) THEN v_rf_continue := true; ELSE v_rf_continue := false; END IF;
          ELSE
            v_rf_continue := false;
          END IF;
        END LOOP;
      END LOOP;
    END LOOP;

    -- Defenders fire at attackers
    FOR v_i IN 0..(jsonb_array_length(v_defender_units) - 1) LOOP
      v_unit := v_defender_units->v_i;
      IF (v_unit->>'quantity')::integer <= 0 THEN CONTINUE; END IF;

      FOR v_k IN 1..(v_unit->>'quantity')::integer LOOP
        v_rf_continue := true;
        v_rf_shots := 0;
        v_rf_target_code := NULL;

        WHILE v_rf_continue LOOP
          v_rf_shots := v_rf_shots + 1;
          IF v_rf_shots > 100 THEN EXIT; END IF;

          IF v_rf_target_code IS NULL THEN
            -- Primer disparo: objetivo aleatorio entre todos los atacantes vivos
            v_alive_count := 0;
            FOR v_j IN 0..(jsonb_array_length(v_attacker_units) - 1) LOOP
              v_alive_count := v_alive_count + GREATEST(0, (v_attacker_units->v_j->>'quantity')::integer);
            END LOOP;
            IF v_alive_count = 0 THEN EXIT; END IF;

            v_random_pick := FLOOR(random() * v_alive_count)::integer;
            v_cumulative := 0;
            v_target_idx := 0;
            FOR v_j IN 0..(jsonb_array_length(v_attacker_units) - 1) LOOP
              v_target_qty := (v_attacker_units->v_j->>'quantity')::integer;
              IF v_target_qty > 0 THEN
                v_cumulative := v_cumulative + v_target_qty;
                IF v_random_pick < v_cumulative THEN
                  v_target_idx := v_j;
                  EXIT;
                END IF;
              END IF;
            END LOOP;
            v_target := v_attacker_units->v_target_idx;
            v_target_qty := (v_target->>'quantity')::integer;
            IF v_target_qty <= 0 THEN v_rf_continue := false; CONTINUE; END IF;
            v_rf_target_code := v_target->>'code';
          ELSE
            -- Disparos de fuego rápido: solo a unidades del mismo tipo
            v_alive_count := 0;
            FOR v_j IN 0..(jsonb_array_length(v_attacker_units) - 1) LOOP
              IF (v_attacker_units->v_j->>'code') = v_rf_target_code THEN
                v_alive_count := v_alive_count + GREATEST(0, (v_attacker_units->v_j->>'quantity')::integer);
              END IF;
            END LOOP;
            IF v_alive_count = 0 THEN EXIT; END IF;

            v_random_pick := FLOOR(random() * v_alive_count)::integer;
            v_cumulative := 0;
            v_target_idx := -1;
            FOR v_j IN 0..(jsonb_array_length(v_attacker_units) - 1) LOOP
              IF (v_attacker_units->v_j->>'code') = v_rf_target_code THEN
                v_target_qty := (v_attacker_units->v_j->>'quantity')::integer;
                IF v_target_qty > 0 THEN
                  v_cumulative := v_cumulative + v_target_qty;
                  IF v_random_pick < v_cumulative THEN
                    v_target_idx := v_j;
                    EXIT;
                  END IF;
                END IF;
              END IF;
            END LOOP;
            IF v_target_idx = -1 THEN EXIT; END IF;
            v_target := v_attacker_units->v_target_idx;
            v_target_qty := (v_target->>'quantity')::integer;
            IF v_target_qty <= 0 THEN v_rf_continue := false; CONTINUE; END IF;
          END IF;

          v_damage := (v_unit->>'weapon')::numeric;
          v_shield_per_unit := (v_target->>'shield')::numeric;

          IF v_shield_per_unit > 0 AND v_damage < v_shield_per_unit * 0.01 THEN
            NULL;
          ELSE
            v_shield_available := LEAST(v_shield_per_unit, GREATEST(0, (v_attacker_units->v_target_idx->>'shield_pool')::numeric));
            v_shield_absorbed := LEAST(v_damage, v_shield_available);
            v_hull_damage := v_damage - v_shield_absorbed;

            IF v_shield_absorbed > 0 THEN
              v_attacker_units := jsonb_set(v_attacker_units, ARRAY[v_target_idx::text, 'shield_pool'],
                to_jsonb(GREATEST(0, (v_attacker_units->v_target_idx->>'shield_pool')::numeric - v_shield_absorbed)));
            END IF;

            IF v_hull_damage > 0 THEN
              v_unit_hull := (v_target->>'hull')::numeric;
              v_hull_pool := (v_attacker_units->v_target_idx->>'hull_damage_pool')::numeric + v_hull_damage;
              v_attacker_units := jsonb_set(v_attacker_units, ARRAY[v_target_idx::text, 'hull_damage_pool'], to_jsonb(v_hull_pool));

              IF v_unit_hull > 0 THEN
                v_units_killed := FLOOR(v_hull_pool / v_unit_hull)::integer;
                IF v_units_killed < v_target_qty THEN
                  v_destroy_fraction := (v_hull_pool - (v_units_killed::numeric * v_unit_hull)) / v_unit_hull;
                  IF v_destroy_fraction > 0.3 THEN
                    IF random() < v_destroy_fraction THEN v_units_killed := v_units_killed + 1; END IF;
                  END IF;
                END IF;
                v_units_killed := LEAST(v_units_killed, v_target_qty);

                IF v_units_killed > 0 THEN
                  v_attacker_units := jsonb_set(v_attacker_units, ARRAY[v_target_idx::text, 'quantity'], to_jsonb(v_target_qty - v_units_killed));
                  v_attacker_units := jsonb_set(v_attacker_units, ARRAY[v_target_idx::text, 'hull_damage_pool'],
                    to_jsonb(GREATEST(0, v_hull_pool - (v_units_killed::numeric * v_unit_hull))));
                  IF v_target_qty <= v_units_killed THEN
                    v_attacker_units := jsonb_set(v_attacker_units, ARRAY[v_target_idx::text, 'shield_pool'], to_jsonb(0::numeric));
                  END IF;

                  v_attacker_losses_metal := v_attacker_losses_metal + ((v_target->>'metal_cost')::numeric * v_units_killed);
                  v_attacker_losses_crystal := v_attacker_losses_crystal + ((v_target->>'crystal_cost')::numeric * v_units_killed);
                END IF;
              END IF;
            END IF;
          END IF;

          v_rf_value := COALESCE((v_unit->'rapid_fire'->>((v_attacker_units->v_target_idx->>'code')::text))::integer, 0);
          IF v_rf_value > 1 THEN
            IF random() < ((v_rf_value - 1.0) / v_rf_value) THEN v_rf_continue := true; ELSE v_rf_continue := false; END IF;
          ELSE
            v_rf_continue := false;
          END IF;
        END LOOP;
      END LOOP;
    END LOOP;

    v_rounds_data := v_rounds_data || jsonb_build_object(
      'round', v_round,
      'attacker_remaining', (SELECT COALESCE(SUM((u->>'quantity')::integer), 0) FROM jsonb_array_elements(v_attacker_units) u),
      'defender_remaining', (SELECT COALESCE(SUM((u->>'quantity')::integer), 0) FROM jsonb_array_elements(v_defender_units) u)
    );

    SELECT COALESCE(SUM((u->>'quantity')::integer), 0) INTO v_attacker_total_units FROM jsonb_array_elements(v_attacker_units) u;
    SELECT COALESCE(SUM((u->>'quantity')::integer), 0) INTO v_defender_total_units FROM jsonb_array_elements(v_defender_units) u;

    IF v_attacker_total_units = 0 OR v_defender_total_units = 0 THEN EXIT; END IF;
  END LOOP;

  SELECT COALESCE(SUM((u->>'quantity')::integer), 0) INTO v_attacker_total_units FROM jsonb_array_elements(v_attacker_units) u;
  SELECT COALESCE(SUM((u->>'quantity')::integer), 0) INTO v_defender_total_units FROM jsonb_array_elements(v_defender_units) u;

  IF v_attacker_total_units > 0 AND v_defender_total_units = 0 THEN
    v_result := 'attacker_won';
  ELSIF v_attacker_total_units = 0 AND v_defender_total_units > 0 THEN
    v_result := 'defender_won';
  ELSE
    v_result := 'draw';
  END IF;

  -- Load configurable debris ratios
  SELECT
    COALESCE(fleet_debris_ratio, 30) / 100.0,
    COALESCE(defense_debris_ratio, 0) / 100.0
  INTO v_fleet_cdr, v_defense_cdr
  FROM admin_speed_settings
  WHERE id = 1;

  IF NOT FOUND THEN
    v_fleet_cdr := 0.3;
    v_defense_cdr := 0.0;
  END IF;

  -- Total defender losses = fleet + defense (for reporting)
  v_defender_losses_metal := v_defender_fleet_losses_metal + v_defender_defense_losses_metal;
  v_defender_losses_crystal := v_defender_fleet_losses_crystal + v_defender_defense_losses_crystal;

  -- Debris = attacker fleet losses * fleet_cdr + defender fleet losses * fleet_cdr + defender defense losses * defense_cdr
  v_debris_metal := FLOOR(
    (v_attacker_losses_metal + v_defender_fleet_losses_metal) * v_fleet_cdr
    + v_defender_defense_losses_metal * v_defense_cdr
  );
  v_debris_crystal := FLOOR(
    (v_attacker_losses_crystal + v_defender_fleet_losses_crystal) * v_fleet_cdr
    + v_defender_defense_losses_crystal * v_defense_cdr
  );

  RETURN jsonb_build_object(
    'result', v_result,
    'rounds', v_round,
    'rounds_data', v_rounds_data,
    'attacker_remaining', v_attacker_units,
    'defender_remaining', v_defender_units,
    'debris_metal', v_debris_metal,
    'debris_crystal', v_debris_crystal,
    'attacker_losses_metal', v_attacker_losses_metal,
    'attacker_losses_crystal', v_attacker_losses_crystal,
    'defender_losses_metal', v_defender_losses_metal,
    'defender_losses_crystal', v_defender_losses_crystal,
    'destroyed_defenses', v_destroyed_defenses,
    'initial_attacker', v_initial_attackers,
    'initial_defender', v_initial_defenders
  );
END;
$$;


--
-- TOC entry 1100 (class 1255 OID 21691)
-- Name: start_alliance_war(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_alliance_war(p_war_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_war alliance_wars%ROWTYPE;
  v_entry_count integer;
BEGIN
  v_admin_id := auth.uid();
  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores');
  END IF;

  SELECT * INTO v_war FROM alliance_wars WHERE id = p_war_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Guerra no encontrada');
  END IF;

  IF v_war.status != 'open' THEN
    RETURN jsonb_build_object('success', false, 'error', 'La guerra no está en estado abierto');
  END IF;

  SELECT COUNT(*) INTO v_entry_count FROM alliance_war_entries WHERE war_id = p_war_id;
  IF v_entry_count < 2 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Se necesitan al menos 2 alianzas para iniciar');
  END IF;

  UPDATE alliance_wars 
  SET status = 'active', 
      start_time = now(), 
      end_time = now() + (v_war.duration_hours || ' hours')::interval
  WHERE id = p_war_id;

  RETURN jsonb_build_object('success', true, 'message', '¡Guerra iniciada!', 'end_time', now() + (v_war.duration_hours || ' hours')::interval);
END;
$$;


--
-- TOC entry 1087 (class 1255 OID 21496)
-- Name: start_hero_expedition(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_hero_expedition(p_user_id uuid, p_expedition_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ship record;
  v_expedition record;
  v_active record;
  v_planet_id uuid;
  v_resources record;
  v_puntos_totales integer;
  v_costo_deuterio bigint;
BEGIN
  PERFORM create_hero_ship(p_user_id);
  SELECT * INTO v_ship FROM user_hero_ships WHERE user_id = p_user_id FOR UPDATE;

  IF v_ship.hp <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tu nave esta daniada. Reparala antes de salir');
  END IF;

  SELECT * INTO v_expedition FROM hero_ship_expeditions WHERE id = p_expedition_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Expedicion no encontrada');
  END IF;

  IF v_ship.level < v_expedition.min_level THEN
    RETURN jsonb_build_object('success', false, 'error', 'Nivel minimo requerido: ' || v_expedition.min_level);
  END IF;

  SELECT * INTO v_active FROM hero_ship_active_expedition WHERE user_id = p_user_id AND claimed = false;
  IF FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya tienes una expedicion en curso');
  END IF;

  v_puntos_totales := COALESCE(v_ship.attack_points, 0) + COALESCE(v_ship.defense_points, 0) + COALESCE(v_ship.shield_points, 0) + COALESCE(v_ship.speed_points, 0);
  v_costo_deuterio := GREATEST(1, CEIL((v_expedition.duration_minutes * (POWER(v_ship.level, 2) * 10 + v_puntos_totales * 3) + 100) * 0.25));

  SELECT id INTO v_planet_id FROM planets WHERE user_id = p_user_id AND is_main_planet = true LIMIT 1;
  IF v_planet_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes un planeta principal');
  END IF;

  SELECT deuterium INTO v_resources FROM planet_resources WHERE planet_id = v_planet_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Recursos del planeta no encontrados');
  END IF;

  IF v_resources.deuterium < v_costo_deuterio THEN
    RETURN jsonb_build_object('success', false, 'error', 'Deuterio insuficiente. Necesitas: ' || v_costo_deuterio || ', tienes: ' || FLOOR(v_resources.deuterium));
  END IF;

  UPDATE planet_resources SET deuterium = deuterium - v_costo_deuterio WHERE planet_id = v_planet_id;

  INSERT INTO hero_ship_active_expedition (user_id, expedition_id, started_at, returns_at)
  VALUES (p_user_id, p_expedition_id, now(), now() + (v_expedition.duration_minutes || ' minutes')::interval)
  ON CONFLICT (user_id) DO UPDATE SET
    expedition_id = EXCLUDED.expedition_id,
    started_at = EXCLUDED.started_at,
    returns_at = EXCLUDED.returns_at,
    claimed = false;

  RETURN jsonb_build_object(
    'success', true,
    'returns_at', (now() + (v_expedition.duration_minutes || ' minutes')::interval)::text,
    'duration_minutes', v_expedition.duration_minutes,
    'deuterium_cost', v_costo_deuterio
  );
END;
$$;


--
-- TOC entry 749 (class 1255 OID 19073)
-- Name: start_research(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_research(p_technology_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_planet RECORD;
  v_tech technology_types%ROWTYPE;
  v_current_level integer;
  v_metal_cost bigint;
  v_crystal_cost bigint;
  v_deut_cost bigint;
  v_research_time integer;
  v_lab_level integer;
  v_existing_research RECORD;
  v_game_speed numeric;
  v_technocrat_bonus numeric := 1.0;
  v_has_technocrat boolean;
  v_total_energy integer;
  v_scaled_energy bigint;
  v_resources RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF EXISTS (SELECT 1 FROM profiles WHERE id = v_user_id AND vacation_mode = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot research while in vacation mode');
  END IF;

  SELECT p.* INTO v_planet
  FROM planets p
  JOIN profiles pr ON pr.current_planet_id = p.id
  WHERE pr.id = v_user_id;

  IF v_planet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No planet selected');
  END IF;

  SELECT * INTO v_tech FROM technology_types WHERE id = p_technology_id;
  IF v_tech IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Technology not found');
  END IF;

  SELECT * INTO v_existing_research
  FROM research_queue
  WHERE user_id = v_user_id AND end_time > NOW();

  IF v_existing_research IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Research already in progress');
  END IF;

  SELECT COALESCE(level, 0) INTO v_current_level
  FROM user_technologies
  WHERE user_id = v_user_id AND technology_type_id = p_technology_id;
  v_current_level := COALESCE(v_current_level, 0);

  IF v_tech.max_level IS NOT NULL AND v_current_level >= v_tech.max_level THEN
    RETURN jsonb_build_object('success', false, 'error', 'Maximum level reached');
  END IF;

  SELECT COALESCE(level, 0) INTO v_lab_level
  FROM planet_buildings pb
  JOIN building_types bt ON pb.building_type_id = bt.id
  WHERE pb.planet_id = v_planet.id AND bt.code = 'research_lab';
  v_lab_level := COALESCE(v_lab_level, 0);

  IF v_lab_level < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Research Lab required');
  END IF;

  IF NOT validate_technology_requirements(v_user_id, p_technology_id, v_planet.id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Requirements not met');
  END IF;

  -- Check energy requirement scaled by level (e.g. Graviton Technology)
  IF v_tech.energy_required > 0 THEN
    SELECT COALESCE(energy_production, 0) - COALESCE(energy_consumption, 0)
    INTO v_total_energy
    FROM planets
    WHERE id = v_planet.id;

    v_scaled_energy := CEIL(v_tech.energy_required * POWER(v_tech.cost_factor, v_current_level));

    IF COALESCE(v_total_energy, 0) < v_scaled_energy THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Insufficient energy production. Required: ' || v_scaled_energy || ', Available: ' || COALESCE(v_total_energy, 0)
      );
    END IF;
  END IF;

  v_metal_cost := CEIL(v_tech.base_metal * POWER(v_tech.cost_factor, v_current_level));
  v_crystal_cost := CEIL(v_tech.base_crystal * POWER(v_tech.cost_factor, v_current_level));
  v_deut_cost := CEIL(v_tech.base_deuterium * POWER(v_tech.cost_factor, v_current_level));

  -- Get resources from planet_resources table
  SELECT * INTO v_resources FROM planet_resources WHERE planet_id = v_planet.id;

  IF v_resources.metal < v_metal_cost OR v_resources.crystal < v_crystal_cost OR v_resources.deuterium < v_deut_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient resources');
  END IF;

  SELECT COALESCE(value::numeric, 1) INTO v_game_speed
  FROM game_settings WHERE key = 'research_speed';
  v_game_speed := COALESCE(v_game_speed, 1);

  SELECT EXISTS (
    SELECT 1 FROM user_officers uo
    JOIN officer_types ot ON uo.officer_type_id = ot.id
    WHERE uo.user_id = v_user_id
    AND ot.code = 'technocrat'
    AND uo.expires_at > NOW()
  ) INTO v_has_technocrat;

  IF v_has_technocrat THEN
    v_technocrat_bonus := 0.75;
  END IF;

  v_research_time := GREATEST(1, CEIL(
    (v_tech.base_time_seconds * POWER(v_tech.cost_factor, v_current_level))
    / (v_lab_level + 1)
    / v_game_speed
    * v_technocrat_bonus
  ));

  -- Deduct resources from planet_resources
  UPDATE planet_resources SET
    metal = metal - v_metal_cost,
    crystal = crystal - v_crystal_cost,
    deuterium = deuterium - v_deut_cost,
    last_update = now()
  WHERE planet_id = v_planet.id;

  -- Auto-cancel market listings that exceed available resources
  PERFORM auto_cancel_insufficient_listings(v_planet.id);

  DELETE FROM research_queue WHERE user_id = v_user_id AND end_time <= NOW();

  INSERT INTO research_queue (user_id, technology_type_id, planet_id, start_time, end_time)
  VALUES (v_user_id, p_technology_id, v_planet.id, NOW(), NOW() + (v_research_time || ' seconds')::interval);

  RETURN jsonb_build_object(
    'success', true,
    'research_time', v_research_time,
    'end_time', NOW() + (v_research_time || ' seconds')::interval
  );
END;
$$;


--
-- TOC entry 770 (class 1255 OID 19273)
-- Name: submit_multiaccounting_report(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_multiaccounting_report(p_reported_user_id uuid, p_suspected_linked_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT ''::text, p_evidence_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_report_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  IF p_reported_user_id = auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot report yourself');
  END IF;
  
  IF p_suspected_linked_user_id = auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot report yourself');
  END IF;
  
  IF EXISTS (
    SELECT 1 FROM multiaccounting_reports
    WHERE reporter_id = auth.uid()
      AND reported_user_id = p_reported_user_id
      AND status = 'pending'
      AND created_at > now() - interval '7 days'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'You already have a pending report for this player');
  END IF;
  
  INSERT INTO multiaccounting_reports (
    reporter_id,
    reported_user_id,
    suspected_linked_user_id,
    reason,
    evidence_description
  ) VALUES (
    auth.uid(),
    p_reported_user_id,
    p_suspected_linked_user_id,
    p_reason,
    p_evidence_description
  )
  RETURNING id INTO v_report_id;
  
  RETURN jsonb_build_object('success', true, 'report_id', v_report_id);
END;
$$;


--
-- TOC entry 955 (class 1255 OID 20553)
-- Name: submit_twitter_action(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_twitter_action(p_mission_id uuid, p_user_tweet_url text, p_action_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_link twitter_links%ROWTYPE;
  v_mission twitter_missions%ROWTYPE;
  v_config twitter_social_config%ROWTYPE;
  v_existing twitter_actions%ROWTYPE;
  v_points integer;
  v_url_duplicate twitter_actions%ROWTYPE;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Check user has linked Twitter
  SELECT * INTO v_link FROM twitter_links WHERE user_id = v_user_id;
  IF v_link IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Twitter account not linked');
  END IF;

  -- Validate action type
  IF p_action_type NOT IN ('quote_tweet', 'comment') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid action type');
  END IF;

  -- Validate URL format (must be twitter.com or x.com status URL)
  IF p_user_tweet_url !~ 'https?://(twitter\.com|x\.com)/\w+/status/\d+' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid Twitter/X URL format');
  END IF;

  -- Check mission exists and is active
  SELECT * INTO v_mission FROM twitter_missions WHERE id = p_mission_id AND is_active = true;
  IF v_mission IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mission not found or inactive');
  END IF;

  -- Check user hasn't already submitted this action type for this mission
  SELECT * INTO v_existing 
  FROM twitter_actions 
  WHERE user_id = v_user_id AND mission_id = p_mission_id AND action_type = p_action_type;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Action already submitted for this mission');
  END IF;

  -- Check this tweet URL hasn't been used by anyone else (anti-fraud)
  SELECT * INTO v_url_duplicate
  FROM twitter_actions
  WHERE user_tweet_url = p_user_tweet_url;
  IF v_url_duplicate IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This tweet URL has already been submitted');
  END IF;

  -- Get config for points
  SELECT * INTO v_config FROM twitter_social_config LIMIT 1;
  
  IF p_action_type = 'quote_tweet' THEN
    v_points := COALESCE(v_config.quote_tweet_points, 10);
  ELSE
    v_points := COALESCE(v_config.comment_points, 5);
  END IF;

  -- Insert the action (pending validation via admin)
  INSERT INTO twitter_actions (user_id, mission_id, user_tweet_url, action_type, points_awarded, validated)
  VALUES (v_user_id, p_mission_id, p_user_tweet_url, p_action_type, v_points, false);

  RETURN jsonb_build_object(
    'success', true,
    'points', v_points,
    'action_type', p_action_type,
    'message', 'Action submitted! Pending admin validation.'
  );
END;
$$;


--
-- TOC entry 789 (class 1255 OID 19315)
-- Name: swap_fxu_to_usdt(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.swap_fxu_to_usdt(p_fxu_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_fxu_balance numeric;
  v_config wallet_config%ROWTYPE;
  v_usdt_amount numeric;
  v_fee_rate numeric;
  v_fee_usdt numeric;
  v_fee_fxu numeric;
  v_usdt_after_fee numeric;
  v_admin_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_config FROM wallet_config WHERE id = 1;

  IF NOT v_config.is_swap_enabled THEN
    RETURN jsonb_build_object('success', false, 'error', 'Swap is currently disabled');
  END IF;

  IF p_fxu_amount < v_config.swap_min_fxu THEN
    RETURN jsonb_build_object('success', false, 'error', 'Minimum swap amount is ' || v_config.swap_min_fxu || ' FXU');
  END IF;

  SELECT fxu_balance INTO v_fxu_balance FROM profiles WHERE id = v_user_id;

  IF v_fxu_balance < p_fxu_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient FXU balance');
  END IF;

  v_fee_rate := COALESCE(v_config.swap_fee_percent, 1.0) / 100;
  v_usdt_amount := p_fxu_amount / v_config.swap_rate_fxu_per_usdt;
  v_fee_usdt := v_usdt_amount * v_fee_rate;
  v_usdt_after_fee := v_usdt_amount - v_fee_usdt;
  v_fee_fxu := v_fee_usdt * v_config.swap_rate_fxu_per_usdt;

  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);

  UPDATE profiles 
  SET fxu_balance = fxu_balance - p_fxu_amount,
      usdt_balance = usdt_balance + v_usdt_after_fee,
      updated_at = now()
  WHERE id = v_user_id;

  SELECT id INTO v_admin_id FROM profiles WHERE is_admin = true ORDER BY created_at ASC LIMIT 1;
  IF v_admin_id IS NOT NULL AND v_fee_fxu > 0 THEN
    UPDATE profiles SET fxu_balance = fxu_balance + v_fee_fxu WHERE id = v_admin_id;
  END IF;

  INSERT INTO admin_revenue (revenue_type, amount, description, related_user_id)
  VALUES (
    'swap_fee',
    v_fee_fxu,
    format('Swap fee: %s FXU -> %s USDT (fee: %s USDT = %s FXU)', 
           p_fxu_amount, round(v_usdt_after_fee, 6), round(v_fee_usdt, 6), round(v_fee_fxu, 2)),
    v_user_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'fxu_spent', p_fxu_amount,
    'usdt_received', round(v_usdt_after_fee, 6),
    'fee_usdt', round(v_fee_usdt, 6),
    'fee_percent', v_fee_rate * 100,
    'rate', v_config.swap_rate_fxu_per_usdt,
    'message', 'Successfully swapped ' || p_fxu_amount || ' FXU for ' || round(v_usdt_after_fee, 6) || ' USDT (fee: ' || round(v_fee_usdt, 6) || ' USDT)'
  );
END;
$$;


