--
-- TOC entry 820 (class 1255 OID 19641)
-- Name: sync_alliance_on_member_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_alliance_on_member_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM update_alliance_points(NEW.alliance_id);
    PERFORM update_all_alliance_rankings();
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM update_alliance_points(OLD.alliance_id);
    PERFORM update_all_alliance_rankings();
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


--
-- TOC entry 819 (class 1255 OID 19639)
-- Name: sync_alliance_points_on_profile_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_alliance_points_on_profile_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_alliance_id uuid;
BEGIN
  -- Only sync alliance when points actually changed
  IF OLD.points_total IS DISTINCT FROM NEW.points_total THEN
    SELECT alliance_id INTO v_alliance_id
    FROM alliance_members
    WHERE user_id = NEW.id;

    IF v_alliance_id IS NOT NULL THEN
      PERFORM update_alliance_points(v_alliance_id);
      -- NOTE: update_all_alliance_rankings() removed - already runs via
      -- pg_cron job 'update_rankings_10m' every 10 minutes
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


