--

CREATE FUNCTION public.sync_android_ai_global() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_enabled boolean;
BEGIN
  SELECT COALESCE((value = 'true'), false) INTO v_enabled FROM game_settings WHERE key = 'global_android_ai_enabled';
  IF v_enabled THEN
    UPDATE planets SET autopilot_role = 'balanced' WHERE is_main_planet = true AND autopilot_role IS NULL AND user_id IN (SELECT id FROM profiles WHERE is_bot = false);
  END IF;
END; $$;


--
-- TOC entry 645 (class 1255 OID 18655)
-- Name: sync_planet_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_planet_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Recalculate fields_used based on actual building levels
  UPDATE planets p
  SET fields_used = COALESCE(
    (SELECT SUM(pb.level) 
     FROM planet_buildings pb 
     WHERE pb.planet_id = p.id AND pb.level > 0),
    0
  )
  WHERE p.id = COALESCE(NEW.planet_id, OLD.planet_id);
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


