--
-- TOC entry 859 (class 1255 OID 20021)
-- Name: transfer_alliance_leadership(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_alliance_leadership(p_new_leader_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_membership record;
  v_new_leader_membership record;
  v_alliance record;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  -- Get user's alliance
  SELECT * INTO v_alliance
  FROM alliances
  WHERE leader_id = v_user_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No eres el lider de ninguna alianza');
  END IF;
  
  -- Get new leader's membership
  SELECT * INTO v_new_leader_membership
  FROM alliance_members
  WHERE user_id = p_new_leader_id AND alliance_id = v_alliance.id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'El jugador no es miembro de tu alianza');
  END IF;
  
  IF p_new_leader_id = v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya eres el lider');
  END IF;
  
  -- Update alliance leader
  UPDATE alliances
  SET leader_id = p_new_leader_id
  WHERE id = v_alliance.id;
  
  -- Promote new leader to max rank
  UPDATE alliance_members
  SET 
    rank_level = 10,
    rank_name = 'Fundador',
    can_invite = true,
    can_kick = true,
    can_edit = true
  WHERE user_id = p_new_leader_id AND alliance_id = v_alliance.id;
  
  -- Demote old leader
  UPDATE alliance_members
  SET 
    rank_level = 8,
    rank_name = 'Presidente'
  WHERE user_id = v_user_id AND alliance_id = v_alliance.id;
  
  -- Send notification to new leader
  INSERT INTO messages (recipient_id, subject, body, message_type)
  VALUES (
    p_new_leader_id,
    'Eres el nuevo lider de ' || v_alliance.name,
    'Has sido nombrado nuevo lider de la alianza [' || v_alliance.tag || '] ' || v_alliance.name || '.',
    'alliance'
  );
  
  RETURN jsonb_build_object('success', true, 'message', 'Liderazgo transferido');
END;
$$;


--
-- TOC entry 915 (class 1255 OID 20336)
-- Name: transfer_tokens(text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_tokens(p_receiver_username text, p_token_type text, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sender_id uuid;
  v_receiver_id uuid;
  v_receiver_username text;
  v_sender_username text;
  v_sender_balance numeric;
  v_fee_percent numeric;
  v_fee_amount numeric;
  v_net_amount numeric;
  v_transfers_enabled text;
  v_admin_id uuid;
  v_transfer_id uuid;
  v_input text;
BEGIN
  v_sender_id := auth.uid();
  IF v_sender_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT value INTO v_transfers_enabled FROM game_settings WHERE key = 'transfers_enabled';
  IF COALESCE(v_transfers_enabled, 'true') != 'true' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transfers are currently disabled');
  END IF;

  IF p_token_type NOT IN ('FXU', 'USDT') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid token type');
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Amount must be greater than 0');
  END IF;

  IF p_amount < 1000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Minimum transfer is 1,000');
  END IF;

  SELECT username INTO v_sender_username FROM profiles WHERE id = v_sender_id;

  v_input := TRIM(p_receiver_username);

  IF v_input LIKE '%@%' THEN
    SELECT id, username INTO v_receiver_id, v_receiver_username
    FROM profiles
    WHERE LOWER(email) = LOWER(v_input);

    IF v_receiver_id IS NULL THEN
      SELECT id, username INTO v_receiver_id, v_receiver_username
      FROM profiles
      WHERE LOWER(username) = LOWER(v_input);
    END IF;
  ELSE
    SELECT id, username INTO v_receiver_id, v_receiver_username
    FROM profiles
    WHERE LOWER(username) = LOWER(v_input);

    IF v_receiver_id IS NULL THEN
      SELECT id, username INTO v_receiver_id, v_receiver_username
      FROM profiles
      WHERE LOWER(email) = LOWER(v_input);
    END IF;
  END IF;

  IF v_receiver_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'User not found. Check the username or email.');
  END IF;

  IF v_receiver_id = v_sender_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot transfer to yourself');
  END IF;

  SELECT value INTO v_fee_percent FROM game_settings WHERE key = 'transfer_fee_percent';
  v_fee_percent := COALESCE(v_fee_percent::numeric, 10);

  v_fee_amount := FLOOR(p_amount * v_fee_percent / 100 * 100000000) / 100000000;
  v_net_amount := p_amount - v_fee_amount;

  IF v_net_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Amount too small after fee');
  END IF;

  IF p_token_type = 'FXU' THEN
    SELECT fxu_balance INTO v_sender_balance FROM profiles WHERE id = v_sender_id;
  ELSE
    SELECT usdt_balance INTO v_sender_balance FROM profiles WHERE id = v_sender_id;
  END IF;

  IF v_sender_balance IS NULL OR v_sender_balance < p_amount THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Insufficient balance',
      'available', COALESCE(v_sender_balance, 0),
      'required', p_amount
    );
  END IF;

  v_admin_id := get_admin_account_id();

  PERFORM set_config('fxu.allow_update_9x7k2m', 'true', true);

  IF p_token_type = 'FXU' THEN
    UPDATE profiles SET fxu_balance = fxu_balance - p_amount WHERE id = v_sender_id;
    UPDATE profiles SET fxu_balance = fxu_balance + v_net_amount WHERE id = v_receiver_id;
    IF v_admin_id IS NOT NULL AND v_fee_amount > 0 THEN
      UPDATE profiles SET fxu_balance = fxu_balance + v_fee_amount WHERE id = v_admin_id;
    END IF;
  ELSE
    UPDATE profiles SET usdt_balance = usdt_balance - p_amount WHERE id = v_sender_id;
    UPDATE profiles SET usdt_balance = usdt_balance + v_net_amount WHERE id = v_receiver_id;
    IF v_admin_id IS NOT NULL AND v_fee_amount > 0 THEN
      UPDATE profiles SET usdt_balance = usdt_balance + v_fee_amount WHERE id = v_admin_id;
    END IF;
  END IF;

  INSERT INTO internal_transfers (sender_id, receiver_id, token_type, gross_amount, fee_amount, net_amount, fee_percent)
  VALUES (v_sender_id, v_receiver_id, p_token_type, p_amount, v_fee_amount, v_net_amount, v_fee_percent)
  RETURNING id INTO v_transfer_id;

  IF v_fee_amount > 0 THEN
    PERFORM public.record_admin_revenue(
      'transfer_fee',
      v_fee_amount,
      'Transfer fee: ' || p_amount || ' ' || p_token_type || ' from ' || v_sender_id::text || ' to ' || v_receiver_username,
      v_sender_id,
      v_transfer_id,
      p_token_type
    );
  END IF;

  INSERT INTO messages (recipient_id, sender_id, subject, body, message_type)
  VALUES (
    v_receiver_id,
    v_sender_id,
    'Transfer received',
    'You received ' || v_net_amount || ' ' || p_token_type || ' from ' || v_sender_username,
    'system'
  );

  RETURN jsonb_build_object(
    'success', true,
    'transfer_id', v_transfer_id,
    'gross_amount', p_amount,
    'fee_amount', v_fee_amount,
    'net_amount', v_net_amount,
    'fee_percent', v_fee_percent,
    'receiver', v_receiver_username,
    'token_type', p_token_type
  );
END;
$$;


--
-- TOC entry 1075 (class 1255 OID 21441)
-- Name: trg_building_completed_daily_mission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_building_completed_daily_mission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  IF NEW.level > OLD.level THEN
    SELECT user_id INTO v_user_id FROM planets WHERE id = NEW.planet_id;
    IF v_user_id IS NOT NULL THEN
      PERFORM update_daily_mission_progress(v_user_id, 'build', NEW.level - OLD.level);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- TOC entry 1074 (class 1255 OID 21439)
-- Name: trg_fleet_completed_daily_mission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_fleet_completed_daily_mission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.is_completed = true AND (OLD.is_completed = false OR OLD.is_completed IS NULL) THEN
    -- Attack missions
    IF NEW.mission_type = 'attack' THEN
      PERFORM update_daily_mission_progress(NEW.user_id, 'attack', 1);
    -- Espionage missions
    ELSIF NEW.mission_type = 'espionage' THEN
      PERFORM update_daily_mission_progress(NEW.user_id, 'spy', 1);
    -- Expedition missions
    ELSIF NEW.mission_type = 'expedition' THEN
      PERFORM update_daily_mission_progress(NEW.user_id, 'expedition', 1);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- TOC entry 1076 (class 1255 OID 21443)
-- Name: trg_research_completed_daily_mission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_research_completed_daily_mission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.level > OLD.level AND NEW.is_researching = false THEN
    PERFORM update_daily_mission_progress(NEW.user_id, 'research', NEW.level - OLD.level);
  END IF;
  RETURN NEW;
END;
$$;


--
-- TOC entry 1077 (class 1255 OID 21445)
-- Name: trg_resource_collect_daily_mission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_resource_collect_daily_mission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_metal_diff numeric;
  v_crystal_diff numeric;
  v_deuterium_diff numeric;
BEGIN
  IF NEW.last_update > OLD.last_update THEN
    SELECT user_id INTO v_user_id FROM planets WHERE id = NEW.planet_id;
    IF v_user_id IS NULL THEN RETURN NEW; END IF;

    v_metal_diff := GREATEST(0, NEW.metal - OLD.metal);
    v_crystal_diff := GREATEST(0, NEW.crystal - OLD.crystal);
    v_deuterium_diff := GREATEST(0, NEW.deuterium - OLD.deuterium);

    IF v_metal_diff > 0 THEN
      PERFORM update_daily_mission_progress(v_user_id, 'collect_metal', v_metal_diff::integer);
    END IF;
    IF v_crystal_diff > 0 THEN
      PERFORM update_daily_mission_progress(v_user_id, 'collect_crystal', v_crystal_diff::integer);
    END IF;
    IF v_deuterium_diff > 0 THEN
      PERFORM update_daily_mission_progress(v_user_id, 'collect_deuterium', v_deuterium_diff::integer);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- TOC entry 1126 (class 1255 OID 21911)
-- Name: trg_return_blueprint_on_listing_cancel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_return_blueprint_on_listing_cancel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_escrow blueprint_market_escrow%ROWTYPE;
BEGIN
  IF NEW.listing_type = 'blueprint'
     AND OLD.status = 'active'
     AND NEW.status = 'cancelled' THEN

    SELECT * INTO v_escrow
    FROM blueprint_market_escrow
    WHERE listing_id = NEW.id
      AND delivered_at IS NULL
      AND returned_at IS NULL
    FOR UPDATE;

    IF FOUND THEN
      INSERT INTO user_ship_blueprints (user_id, blueprint_id, source, metadata)
      VALUES (
        v_escrow.seller_id,
        v_escrow.blueprint_id,
        'admin',
        jsonb_build_object('reason', 'trigger_cancel_return', 'listing_id', NEW.id)
      );

      UPDATE blueprint_market_escrow
      SET returned_at = now()
      WHERE listing_id = NEW.id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 722 (class 1255 OID 18979)
-- Name: trigger_record_withdrawal_fee(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_record_withdrawal_fee() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fee_amount numeric;
  v_admin_share numeric;
  v_has_referrer boolean;
  v_currency text;
BEGIN
  IF NEW.tx_type = 'withdrawal'
     AND NEW.status = 'confirmed'
     AND (OLD.status IS NULL OR OLD.status <> 'confirmed') THEN

    -- Prevent duplicate insertion for the same withdrawal tx
    IF EXISTS (
      SELECT 1
      FROM public.admin_revenue ar
      WHERE ar.related_tx_id = NEW.id
        AND ar.revenue_type = 'withdrawal_fee'
    ) THEN
      RETURN NEW;
    END IF;

    v_fee_amount := COALESCE(NEW.fxu_amount, 0) - COALESCE(NEW.amount, 0);

    IF v_fee_amount > 0 THEN
      SELECT (referred_by IS NOT NULL) INTO v_has_referrer
      FROM public.profiles
      WHERE id = NEW.user_id;

      v_admin_share := GREATEST(
        v_fee_amount - CASE WHEN COALESCE(v_has_referrer, false) THEN COALESCE(NEW.fxu_amount, 0) * 0.05 ELSE 0 END,
        0
      );

      IF v_admin_share > 0 THEN
        v_currency := CASE WHEN NEW.token_type = 'USDT' THEN 'USDT' ELSE 'FXU' END;

        PERFORM public.record_admin_revenue(
          'withdrawal_fee',
          v_admin_share,
          'Comision de retiro (empresa)',
          NEW.user_id,
          NEW.id,
          v_currency
        );
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 611 (class 1255 OID 18421)
-- Name: trigger_update_building_points(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_update_building_points() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    SELECT user_id INTO v_user_id FROM public.planets WHERE id = OLD.planet_id;
  ELSE
    SELECT user_id INTO v_user_id FROM public.planets WHERE id = NEW.planet_id;
  END IF;
  
  IF v_user_id IS NOT NULL THEN
    PERFORM public.update_player_points(v_user_id);
  END IF;
  
  RETURN NULL;
END;
$$;


--
-- TOC entry 614 (class 1255 OID 18424)
-- Name: trigger_update_defense_points(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_update_defense_points() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    SELECT user_id INTO v_user_id FROM public.planets WHERE id = OLD.planet_id;
  ELSE
    SELECT user_id INTO v_user_id FROM public.planets WHERE id = NEW.planet_id;
  END IF;
  
  IF v_user_id IS NOT NULL THEN
    PERFORM public.update_player_points(v_user_id);
  END IF;
  
  RETURN NULL;
END;
$$;


