--
-- TOC entry 1119 (class 1255 OID 21814)
-- Name: unequip_cosmetic(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unequip_cosmetic(p_cosmetic_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  UPDATE user_cosmetics uc
  SET equipped = false
  FROM cosmetic_items ci
  WHERE ci.id = uc.cosmetic_id
    AND uc.user_id = v_user_id
    AND ci.cosmetic_type = p_cosmetic_type
    AND uc.equipped = true;

  IF p_cosmetic_type = 'title' THEN
    UPDATE profiles SET active_title = NULL, active_title_icon = NULL WHERE id = v_user_id;
  ELSIF p_cosmetic_type = 'badge' THEN
    UPDATE profiles SET active_badge = NULL WHERE id = v_user_id;
  ELSIF p_cosmetic_type = 'planet_effect' THEN
    UPDATE profiles SET active_planet_effect = NULL WHERE id = v_user_id;
  ELSIF p_cosmetic_type = 'hero_skin' THEN
    UPDATE profiles SET active_hero_skin = NULL WHERE id = v_user_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'message', 'Desequipado');
END;
$$;


--
-- TOC entry 818 (class 1255 OID 19638)
-- Name: update_all_alliance_points_and_rankings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_all_alliance_points_and_rankings() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Update all alliance points
  UPDATE alliances a
  SET points_total = (
    SELECT COALESCE(SUM(p.points_total), 0)
    FROM alliance_members am
    JOIN profiles p ON p.id = am.user_id
    WHERE am.alliance_id = a.id
  );

  -- Update all rankings
  PERFORM update_all_alliance_rankings();
END;
$$;


--
-- TOC entry 817 (class 1255 OID 19637)
-- Name: update_all_alliance_rankings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_all_alliance_rankings() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  WITH ranked_alliances AS (
    SELECT 
      id,
      ROW_NUMBER() OVER (ORDER BY points_total DESC, created_at ASC) as new_rank
    FROM alliances
  )
  UPDATE alliances a
  SET rank_position = ra.new_rank
  FROM ranked_alliances ra
  WHERE a.id = ra.id;
END;
$$;


--
-- TOC entry 687 (class 1255 OID 18883)
-- Name: update_all_rankings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_all_rankings() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Update total points ranking
  WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY points_total DESC, created_at ASC) as new_rank
    FROM profiles
    WHERE is_admin IS NOT TRUE AND is_hidden IS NOT TRUE
  )
  UPDATE profiles p
  SET rank_position = r.new_rank
  FROM ranked r
  WHERE p.id = r.id;

  -- Update buildings ranking
  WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY points_buildings DESC, created_at ASC) as new_rank
    FROM profiles
    WHERE is_admin IS NOT TRUE AND is_hidden IS NOT TRUE
  )
  UPDATE profiles p
  SET rank_buildings = r.new_rank
  FROM ranked r
  WHERE p.id = r.id;

  -- Update research ranking
  WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY points_research DESC, created_at ASC) as new_rank
    FROM profiles
    WHERE is_admin IS NOT TRUE AND is_hidden IS NOT TRUE
  )
  UPDATE profiles p
  SET rank_research = r.new_rank
  FROM ranked r
  WHERE p.id = r.id;

  -- Update fleet ranking
  WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY points_fleet DESC, created_at ASC) as new_rank
    FROM profiles
    WHERE is_admin IS NOT TRUE AND is_hidden IS NOT TRUE
  )
  UPDATE profiles p
  SET rank_fleet = r.new_rank
  FROM ranked r
  WHERE p.id = r.id;

  -- Update defense ranking
  WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY points_defense DESC, created_at ASC) as new_rank
    FROM profiles
    WHERE is_admin IS NOT TRUE AND is_hidden IS NOT TRUE
  )
  UPDATE profiles p
  SET rank_defense = r.new_rank
  FROM ranked r
  WHERE p.id = r.id;

  -- Update expedition ranking
  WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY points_expedition DESC, created_at ASC) as new_rank
    FROM profiles
    WHERE is_admin IS NOT TRUE AND is_hidden IS NOT TRUE
  )
  UPDATE profiles p
  SET rank_expedition = r.new_rank
  FROM ranked r
  WHERE p.id = r.id;
END;
$$;


--
-- TOC entry 616 (class 1255 OID 18441)
-- Name: update_all_ranks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_all_ranks() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  WITH ranked AS (
    SELECT id,
      ROW_NUMBER() OVER (ORDER BY points_total DESC, created_at ASC) as rank_total,
      ROW_NUMBER() OVER (ORDER BY points_buildings DESC, created_at ASC) as rank_b,
      ROW_NUMBER() OVER (ORDER BY points_research DESC, created_at ASC) as rank_r,
      ROW_NUMBER() OVER (ORDER BY points_fleet DESC, created_at ASC) as rank_f,
      ROW_NUMBER() OVER (ORDER BY points_defense DESC, created_at ASC) as rank_d
    FROM profiles
  )
  UPDATE profiles p
  SET 
    rank_position = r.rank_total,
    rank_buildings = r.rank_b,
    rank_research = r.rank_r,
    rank_fleet = r.rank_f,
    rank_defense = r.rank_d
  FROM ranked r
  WHERE p.id = r.id;
END;
$$;


--
-- TOC entry 816 (class 1255 OID 19636)
-- Name: update_alliance_points(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_alliance_points(p_alliance_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_points bigint;
  v_member_count int;
BEGIN
  SELECT 
    COALESCE(SUM(p.points_total), 0),
    COUNT(*)
  INTO v_total_points, v_member_count
  FROM alliance_members am
  JOIN profiles p ON p.id = am.user_id
  WHERE am.alliance_id = p_alliance_id;

  UPDATE alliances
  SET 
    points_total = v_total_points,
    member_count = v_member_count
  WHERE id = p_alliance_id;
END;
$$;


--
-- TOC entry 1071 (class 1255 OID 21435)
-- Name: update_daily_mission_progress(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_daily_mission_progress(p_user_id uuid, p_mission_type text, p_amount integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE user_daily_missions
  SET progress = LEAST(dm.target_count, progress + p_amount),
      completed = (progress + p_amount >= dm.target_count)
  FROM daily_missions dm
  WHERE user_daily_missions.mission_id = dm.id
    AND user_daily_missions.user_id = p_user_id
    AND dm.mission_type = p_mission_type
    AND user_daily_missions.completed = false
    AND user_daily_missions.claimed = false
    AND user_daily_missions.expires_at > now();
END;
$$;


--
-- TOC entry 808 (class 1255 OID 19515)
-- Name: update_expedition_fee_setting(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_expedition_fee_setting(p_fee numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
  
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;
  
  IF p_fee IS NULL OR p_fee < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'El fee debe ser un numero positivo');
  END IF;
  
  UPDATE game_settings 
  SET value = p_fee::text, updated_at = now()
  WHERE key = 'expedition_extra_fee_fxu';
  
  IF NOT FOUND THEN
    INSERT INTO game_settings (key, value, description)
    VALUES ('expedition_extra_fee_fxu', p_fee::text, 'Costo en FXU por cada expedicion extra simultanea');
  END IF;
  
  RETURN jsonb_build_object('success', true, 'message', 'Fee de expedicion actualizado a ' || p_fee::text || ' FXU');
END;
$$;


--
-- TOC entry 709 (class 1255 OID 18935)
-- Name: update_fee_settings(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_fee_settings(p_market_fee numeric DEFAULT NULL::numeric, p_referral_commission numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
  
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;
  
  -- Validate ranges
  IF p_market_fee IS NOT NULL THEN
    IF p_market_fee < 0 OR p_market_fee > 50 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Fee del mercado debe estar entre 0% y 50%');
    END IF;
    
    UPDATE game_settings 
    SET value = p_market_fee::text, updated_at = now()
    WHERE key = 'market_fee_percent';
  END IF;
  
  IF p_referral_commission IS NOT NULL THEN
    IF p_referral_commission < 0 OR p_referral_commission > 50 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Comision de referidos debe estar entre 0% y 50%');
    END IF;
    
    UPDATE game_settings 
    SET value = p_referral_commission::text, updated_at = now()
    WHERE key = 'referral_commission_percent';
  END IF;
  
  RETURN jsonb_build_object('success', true, 'message', 'Configuracion actualizada');
END;
$$;


--
-- TOC entry 1026 (class 1255 OID 21190)
-- Name: update_fee_settings(numeric, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_fee_settings(p_market_fee numeric DEFAULT NULL::numeric, p_referral_commission numeric DEFAULT NULL::numeric, p_p2p_fee numeric DEFAULT NULL::numeric, p_p2p_fee_admin_share numeric DEFAULT NULL::numeric, p_p2p_fee_referrer_share numeric DEFAULT NULL::numeric, p_p2p_fee_pool_share numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_is_admin boolean;
  v_sum numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;

  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;

  IF p_market_fee IS NOT NULL THEN
    IF p_market_fee < 0 OR p_market_fee > 50 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Fee del mercado debe estar entre 0% y 50%');
    END IF;
    UPDATE game_settings SET value = p_market_fee::text, updated_at = now() WHERE key = 'market_fee_percent';
  END IF;

  IF p_referral_commission IS NOT NULL THEN
    IF p_referral_commission < 0 OR p_referral_commission > 50 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Comision de referidos debe estar entre 0% y 50%');
    END IF;
    UPDATE game_settings SET value = p_referral_commission::text, updated_at = now() WHERE key = 'referral_commission_percent';
  END IF;

  IF p_p2p_fee IS NOT NULL THEN
    IF p_p2p_fee < 0 OR p_p2p_fee > 20 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Fee P2P debe estar entre 0% y 20%');
    END IF;
    UPDATE game_settings SET value = p_p2p_fee::text, updated_at = now() WHERE key = 'p2p_fee_percent';
  END IF;

  -- Validar suma de splits si se pasan
  IF p_p2p_fee_admin_share IS NOT NULL OR p_p2p_fee_referrer_share IS NOT NULL OR p_p2p_fee_pool_share IS NOT NULL THEN
    v_sum := COALESCE(p_p2p_fee_admin_share,
                      (SELECT value::numeric FROM game_settings WHERE key = 'p2p_fee_admin_share'))
           + COALESCE(p_p2p_fee_referrer_share,
                      (SELECT value::numeric FROM game_settings WHERE key = 'p2p_fee_referrer_share'))
           + COALESCE(p_p2p_fee_pool_share,
                      (SELECT value::numeric FROM game_settings WHERE key = 'p2p_fee_pool_share'));

    IF ABS(v_sum - 100) > 0.01 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Los splits del fee P2P deben sumar 100');
    END IF;
  END IF;

  IF p_p2p_fee_admin_share IS NOT NULL THEN
    UPDATE game_settings SET value = p_p2p_fee_admin_share::text, updated_at = now() WHERE key = 'p2p_fee_admin_share';
  END IF;
  IF p_p2p_fee_referrer_share IS NOT NULL THEN
    UPDATE game_settings SET value = p_p2p_fee_referrer_share::text, updated_at = now() WHERE key = 'p2p_fee_referrer_share';
  END IF;
  IF p_p2p_fee_pool_share IS NOT NULL THEN
    UPDATE game_settings SET value = p_p2p_fee_pool_share::text, updated_at = now() WHERE key = 'p2p_fee_pool_share';
  END IF;

  RETURN jsonb_build_object('success', true, 'message', 'Configuracion actualizada');
END;
$$;


--
-- TOC entry 1179 (class 1255 OID 22852)
-- Name: update_fee_settings(numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_fee_settings(p_market_fee numeric DEFAULT NULL::numeric, p_referral_commission numeric DEFAULT NULL::numeric, p_p2p_fee numeric DEFAULT NULL::numeric, p_p2p_fee_admin_share numeric DEFAULT NULL::numeric, p_p2p_fee_referrer_share numeric DEFAULT NULL::numeric, p_p2p_fee_pool_share numeric DEFAULT NULL::numeric, p_market_fee_admin_share numeric DEFAULT NULL::numeric, p_market_fee_pool_share numeric DEFAULT NULL::numeric, p_market_fee_referral_share numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autenticado');
  END IF;
  
  SELECT is_admin INTO v_is_admin FROM profiles WHERE id = v_user_id;
  
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');
  END IF;
  
  -- Validate ranges
  IF p_market_fee IS NOT NULL THEN
    IF p_market_fee < 0 OR p_market_fee > 50 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Fee del mercado debe estar entre 0% y 50%');
    END IF;
    UPDATE game_settings SET value = p_market_fee::text, updated_at = now() WHERE key = 'market_fee_percent';
  END IF;
  
  IF p_referral_commission IS NOT NULL THEN
    IF p_referral_commission < 0 OR p_referral_commission > 50 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Comision de referidos debe estar entre 0% y 50%');
    END IF;
    UPDATE game_settings SET value = p_referral_commission::text, updated_at = now() WHERE key = 'referral_commission_percent';
  END IF;

  -- P2P fee settings
  IF p_p2p_fee IS NOT NULL THEN
    IF p_p2p_fee < 0 OR p_p2p_fee > 20 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Fee P2P invalido');
    END IF;
    UPDATE game_settings SET value = p_p2p_fee::text, updated_at = now() WHERE key = 'p2p_fee_percent';
  END IF;

  IF p_p2p_fee_admin_share IS NOT NULL THEN
    UPDATE game_settings SET value = p_p2p_fee_admin_share::text, updated_at = now() WHERE key = 'p2p_fee_admin_share';
  END IF;

  IF p_p2p_fee_referrer_share IS NOT NULL THEN
    UPDATE game_settings SET value = p_p2p_fee_referrer_share::text, updated_at = now() WHERE key = 'p2p_fee_referrer_share';
  END IF;

  IF p_p2p_fee_pool_share IS NOT NULL THEN
    UPDATE game_settings SET value = p_p2p_fee_pool_share::text, updated_at = now() WHERE key = 'p2p_fee_pool_share';
  END IF;

  -- NEW: 4-3-3 market fee split shares
  IF p_market_fee_admin_share IS NOT NULL THEN
    IF p_market_fee_admin_share < 0 OR p_market_fee_admin_share > 100 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Share de admin debe estar entre 0% y 100%');
    END IF;
    UPDATE game_settings SET value = p_market_fee_admin_share::text, updated_at = now() WHERE key = 'market_fee_admin_share';
  END IF;

  IF p_market_fee_pool_share IS NOT NULL THEN
    IF p_market_fee_pool_share < 0 OR p_market_fee_pool_share > 100 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Share de pool debe estar entre 0% y 100%');
    END IF;
    UPDATE game_settings SET value = p_market_fee_pool_share::text, updated_at = now() WHERE key = 'market_fee_pool_share';
  END IF;

  IF p_market_fee_referral_share IS NOT NULL THEN
    IF p_market_fee_referral_share < 0 OR p_market_fee_referral_share > 100 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Share de referidos debe estar entre 0% y 100%');
    END IF;
    UPDATE game_settings SET value = p_market_fee_referral_share::text, updated_at = now() WHERE key = 'market_fee_referral_share';
  END IF;
  
  RETURN jsonb_build_object('success', true, 'message', 'Configuracion actualizada');
END;
$$;


--
-- TOC entry 737 (class 1255 OID 19058)
-- Name: update_fxu_cost_ratios(numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_fxu_cost_ratios(p_building_ratio numeric, p_research_ratio numeric, p_ships_ratio numeric, p_defense_ratio numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_user_id AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;
  
  IF p_building_ratio < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Building ratio must be at least 1');
  END IF;
  
  IF p_research_ratio < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Research ratio must be at least 1');
  END IF;
  
  IF p_ships_ratio < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ships ratio must be at least 1');
  END IF;
  
  IF p_defense_ratio < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Defense ratio must be at least 1');
  END IF;
  
  INSERT INTO game_settings (key, value, description)
  VALUES ('fxu_cost_ratio_building', p_building_ratio::text, 'Resource value per 1 FXU for buildings')
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
  
  INSERT INTO game_settings (key, value, description)
  VALUES ('fxu_cost_ratio_research', p_research_ratio::text, 'Resource value per 1 FXU for research')
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
  
  INSERT INTO game_settings (key, value, description)
  VALUES ('fxu_cost_ratio_ships', p_ships_ratio::text, 'Resource value per 1 FXU for ships')
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
  
  INSERT INTO game_settings (key, value, description)
  VALUES ('fxu_cost_ratio_defense', p_defense_ratio::text, 'Resource value per 1 FXU for defense')
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
  
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- TOC entry 647 (class 1255 OID 18705)
-- Name: update_game_speeds(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_game_speeds(p_game_speed numeric, p_fleet_speed numeric, p_resource_speed numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
BEGIN
  SELECT is_admin INTO v_is_admin
  FROM profiles
  WHERE id = auth.uid();
  
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;
  
  IF p_game_speed < 1 OR p_game_speed > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Game speed must be between 1 and 100');
  END IF;
  
  IF p_fleet_speed < 1 OR p_fleet_speed > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Fleet speed must be between 1 and 100');
  END IF;
  
  IF p_resource_speed < 1 OR p_resource_speed > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Resource speed must be between 1 and 100');
  END IF;
  
  UPDATE admin_speed_settings
  SET 
    game_speed = p_game_speed,
    fleet_speed = p_fleet_speed,
    resource_speed = p_resource_speed,
    updated_at = now(),
    updated_by = auth.uid()
  WHERE id = 1;
  
  RETURN jsonb_build_object(
    'success', true,
    'game_speed', p_game_speed,
    'fleet_speed', p_fleet_speed,
    'resource_speed', p_resource_speed
  );
END;
$$;


--
-- TOC entry 912 (class 1255 OID 20299)
-- Name: update_game_speeds(numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_game_speeds(p_game_speed numeric, p_fleet_speed numeric, p_resource_speed numeric, p_fleet_debris_ratio numeric DEFAULT NULL::numeric, p_defense_debris_ratio numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
BEGIN
  SELECT is_admin INTO v_is_admin
  FROM profiles
  WHERE id = auth.uid();

  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;

  IF p_game_speed < 1 OR p_game_speed > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Game speed must be between 1 and 100');
  END IF;

  IF p_fleet_speed < 1 OR p_fleet_speed > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Fleet speed must be between 1 and 100');
  END IF;

  IF p_resource_speed < 1 OR p_resource_speed > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Resource speed must be between 1 and 100');
  END IF;

  IF p_fleet_debris_ratio IS NOT NULL AND (p_fleet_debris_ratio < 0 OR p_fleet_debris_ratio > 100) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Fleet debris ratio must be between 0 and 100');
  END IF;

  IF p_defense_debris_ratio IS NOT NULL AND (p_defense_debris_ratio < 0 OR p_defense_debris_ratio > 100) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Defense debris ratio must be between 0 and 100');
  END IF;

  UPDATE admin_speed_settings
  SET
    game_speed = p_game_speed,
    fleet_speed = p_fleet_speed,
    resource_speed = p_resource_speed,
    fleet_debris_ratio = COALESCE(p_fleet_debris_ratio, fleet_debris_ratio),
    defense_debris_ratio = COALESCE(p_defense_debris_ratio, defense_debris_ratio),
    updated_at = now(),
    updated_by = auth.uid()
  WHERE id = 1;

  RETURN jsonb_build_object(
    'success', true,
    'game_speed', p_game_speed,
    'fleet_speed', p_fleet_speed,
    'resource_speed', p_resource_speed,
    'fleet_debris_ratio', COALESCE(p_fleet_debris_ratio, 30),
    'defense_debris_ratio', COALESCE(p_defense_debris_ratio, 0)
  );
END;
$$;


