--
-- TOC entry 1080 (class 1255 OID 21454)
-- Name: use_hero_repair_kit(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.use_hero_repair_kit(p_user_id uuid, p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv record;
  v_item record;
  v_ship record;
BEGIN
  PERFORM create_hero_ship(p_user_id);
  SELECT * INTO v_inv FROM user_hero_ship_inventory WHERE user_id = p_user_id AND item_id = p_item_id FOR UPDATE;
  IF NOT FOUND OR v_inv.quantity <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No tienes ese item');
  END IF;

  SELECT * INTO v_item FROM hero_ship_items WHERE id = p_item_id;
  IF NOT v_item.is_repair_kit THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ese item no es un kit de reparacion');
  END IF;

  SELECT * INTO v_ship FROM user_hero_ships WHERE user_id = p_user_id FOR UPDATE;

  IF EXISTS (SELECT 1 FROM hero_ship_active_expedition WHERE user_id = p_user_id AND claimed = false) THEN
    RETURN jsonb_build_object('success', false, 'error', '🚀 No puedes reparar mientras la nave esta en expedicion');
  END IF;

  IF v_ship.hp >= v_ship.hp_max THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tu nave ya esta al maximo de HP');
  END IF;

  UPDATE user_hero_ships SET hp = LEAST(hp_max, hp + FLOOR(hp_max * v_item.repair_amount / 100)), updated_at = now() WHERE user_id = p_user_id;

  IF v_inv.quantity <= 1 THEN
    DELETE FROM user_hero_ship_inventory WHERE id = v_inv.id;
  ELSE
    UPDATE user_hero_ship_inventory SET quantity = quantity - 1 WHERE id = v_inv.id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'hp_repaired', FLOOR(v_ship.hp_max * v_item.repair_amount / 100),
    'hp_current', LEAST(v_ship.hp_max, v_ship.hp + FLOOR(v_ship.hp_max * v_item.repair_amount / 100))
  );
END;
$$;


--
-- TOC entry 598 (class 1255 OID 18399)
-- Name: use_jump_gate(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.use_jump_gate(p_origin_moon_id uuid, p_target_moon_id uuid, p_ships jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_origin_moon record;
  v_target_moon record;
  v_origin_gate_level integer;
  v_target_gate_level integer;
  v_cooldown_minutes integer;
  v_ship record;
  v_ship_type_id integer;
  v_ship_quantity integer;
  v_available_quantity integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'Not authenticated');
  END IF;

  SELECT p.*, pb.level as gate_level
  INTO v_origin_moon
  FROM planets p
  LEFT JOIN planet_buildings pb ON p.id = pb.planet_id
  LEFT JOIN building_types bt ON pb.building_type_id = bt.id AND bt.code = 'jump_gate'
  WHERE p.id = p_origin_moon_id AND p.planet_type = 'moon' AND p.user_id = auth.uid();

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'Origin moon not found or not owned');
  END IF;

  SELECT p.*, pb.level as gate_level
  INTO v_target_moon
  FROM planets p
  LEFT JOIN planet_buildings pb ON p.id = pb.planet_id
  LEFT JOIN building_types bt ON pb.building_type_id = bt.id AND bt.code = 'jump_gate'
  WHERE p.id = p_target_moon_id AND p.planet_type = 'moon' AND p.user_id = auth.uid();

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'Target moon not found or not owned');
  END IF;

  v_origin_gate_level := COALESCE(v_origin_moon.gate_level, 0);
  v_target_gate_level := COALESCE(v_target_moon.gate_level, 0);

  IF v_origin_gate_level = 0 OR v_target_gate_level = 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'Both moons need a Jump Gate');
  END IF;

  IF v_origin_moon.jump_gate_cooldown IS NOT NULL AND v_origin_moon.jump_gate_cooldown > NOW() THEN
    RETURN jsonb_build_object(
      'success', false, 
      'reason', 'Jump Gate on cooldown',
      'cooldown_ends', v_origin_moon.jump_gate_cooldown
    );
  END IF;

  FOR v_ship IN SELECT * FROM jsonb_array_elements(p_ships)
  LOOP
    v_ship_type_id := (v_ship.value->>'ship_type_id')::integer;
    v_ship_quantity := (v_ship.value->>'quantity')::integer;

    SELECT COALESCE(quantity, 0) INTO v_available_quantity
    FROM planet_ships
    WHERE planet_id = p_origin_moon_id AND ship_type_id = v_ship_type_id;

    IF v_available_quantity < v_ship_quantity THEN
      RETURN jsonb_build_object('success', false, 'reason', 'Insufficient ships');
    END IF;

    UPDATE planet_ships
    SET quantity = quantity - v_ship_quantity
    WHERE planet_id = p_origin_moon_id AND ship_type_id = v_ship_type_id;

    INSERT INTO planet_ships (planet_id, ship_type_id, quantity)
    VALUES (p_target_moon_id, v_ship_type_id, v_ship_quantity)
    ON CONFLICT (planet_id, ship_type_id)
    DO UPDATE SET quantity = planet_ships.quantity + EXCLUDED.quantity;
  END LOOP;

  v_cooldown_minutes := 60;

  UPDATE planets
  SET jump_gate_cooldown = NOW() + (v_cooldown_minutes || ' minutes')::interval
  WHERE id = p_origin_moon_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Fleet teleported successfully',
    'cooldown_minutes', v_cooldown_minutes
  );
END;
$$;


--
-- TOC entry 892 (class 1255 OID 20117)
-- Name: user_can_build_ship(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_can_build_ship(p_user_id uuid, p_ship_type_id integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_requirement record;
  v_user_tech_level integer;
  v_user_building_level integer;
BEGIN
  FOR v_requirement IN
    SELECT sr.required_tech_id, sr.required_tech_level,
           sr.required_building_id, sr.required_building_level
    FROM ship_requirements sr
    WHERE sr.ship_type_id = p_ship_type_id
  LOOP
    IF v_requirement.required_tech_id IS NOT NULL AND COALESCE(v_requirement.required_tech_level, 0) > 0 THEN
      SELECT COALESCE(ut.level, 0) INTO v_user_tech_level
      FROM user_technologies ut
      WHERE ut.user_id = p_user_id
        AND ut.technology_type_id = v_requirement.required_tech_id;

      IF COALESCE(v_user_tech_level, 0) < v_requirement.required_tech_level THEN
        RETURN false;
      END IF;
    END IF;

    IF v_requirement.required_building_id IS NOT NULL AND COALESCE(v_requirement.required_building_level, 0) > 0 THEN
      SELECT COALESCE(MAX(pb.level), 0) INTO v_user_building_level
      FROM planet_buildings pb
      JOIN planets p ON p.id = pb.planet_id
      WHERE p.user_id = p_user_id
        AND pb.building_type_id = v_requirement.required_building_id;

      IF COALESCE(v_user_building_level, 0) < v_requirement.required_building_level THEN
        RETURN false;
      END IF;
    END IF;
  END LOOP;

  RETURN true;
END;
$$;


--
-- TOC entry 644 (class 1255 OID 18654)
-- Name: validate_building_fields(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_building_fields(p_planet_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_planet planets%ROWTYPE;
  v_pending_levels integer;
BEGIN
  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  
  -- Count pending levels in queue (each queued item = 1 future level)
  SELECT COALESCE(COUNT(*), 0) INTO v_pending_levels
  FROM building_queue
  WHERE planet_id = p_planet_id;
  
  -- Check if there's room for one more level
  -- fields_used + pending_levels must be less than fields_max
  RETURN (v_planet.fields_used + v_pending_levels) < v_planet.fields_max;
END;
$$;


--
-- TOC entry 1078 (class 1255 OID 21449)
-- Name: validate_building_queue(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_building_queue(p_planet_id uuid, p_building_type_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_validation jsonb;
  v_building_type RECORD;
  v_current_level integer;
  v_queued_count integer;
  v_cost_metal bigint;
  v_cost_crystal bigint;
  v_cost_deuterium bigint;
BEGIN
  v_validation := validate_building_requirements(p_planet_id, p_building_type_id);
  IF (v_validation->>'valid')::boolean IS DISTINCT FROM true THEN
    RETURN v_validation;
  END IF;

  SELECT * INTO v_building_type FROM building_types WHERE id = p_building_type_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Building type not found');
  END IF;

  SELECT COALESCE(pb.level, 0) INTO v_current_level
  FROM planet_buildings pb
  WHERE pb.planet_id = p_planet_id AND pb.building_type_id = p_building_type_id;

  SELECT COUNT(*) INTO v_queued_count
  FROM building_queue
  WHERE planet_id = p_planet_id AND building_type_id = p_building_type_id;

  v_cost_metal := FLOOR(v_building_type.base_metal * POWER(v_building_type.cost_factor, v_current_level + v_queued_count));
  v_cost_crystal := FLOOR(v_building_type.base_crystal * POWER(v_building_type.cost_factor, v_current_level + v_queued_count));
  v_cost_deuterium := FLOOR(v_building_type.base_deuterium * POWER(v_building_type.cost_factor, v_current_level + v_queued_count));

  RETURN jsonb_build_object(
    'valid', true,
    'cost_metal', v_cost_metal,
    'cost_crystal', v_cost_crystal,
    'cost_deuterium', v_cost_deuterium
  );
END;
$$;


--
-- TOC entry 623 (class 1255 OID 18563)
-- Name: validate_building_requirements(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_building_requirements(p_planet_id uuid, p_building_type_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_requirement RECORD;
  v_current_level integer;
  v_missing_reqs jsonb := '[]'::jsonb;
  v_planet RECORD;
BEGIN
  SELECT * INTO v_planet FROM planets WHERE id = p_planet_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Planet not found');
  END IF;

  FOR v_requirement IN
    SELECT br.*, 
           bt.name as building_name, 
           tt.name as tech_name
    FROM building_requirements br
    LEFT JOIN building_types bt ON bt.id = br.required_building_id
    LEFT JOIN technology_types tt ON tt.id = br.required_tech_id
    WHERE br.building_type_id = p_building_type_id
  LOOP
    IF v_requirement.required_building_id IS NOT NULL THEN
      SELECT COALESCE(pb.level, 0) INTO v_current_level
      FROM planet_buildings pb
      WHERE pb.planet_id = p_planet_id
        AND pb.building_type_id = v_requirement.required_building_id;
      
      IF v_current_level IS NULL THEN v_current_level := 0; END IF;
      
      IF v_current_level < v_requirement.required_building_level THEN
        v_missing_reqs := v_missing_reqs || jsonb_build_object(
          'type', 'building',
          'name', v_requirement.building_name,
          'required', v_requirement.required_building_level,
          'current', v_current_level
        );
      END IF;
    END IF;

    IF v_requirement.required_tech_id IS NOT NULL THEN
      SELECT COALESCE(ut.level, 0) INTO v_current_level
      FROM user_technologies ut
      WHERE ut.user_id = v_planet.user_id
        AND ut.technology_type_id = v_requirement.required_tech_id;
      
      IF v_current_level IS NULL THEN v_current_level := 0; END IF;
      
      IF v_current_level < v_requirement.required_tech_level THEN
        v_missing_reqs := v_missing_reqs || jsonb_build_object(
          'type', 'technology',
          'name', v_requirement.tech_name,
          'required', v_requirement.required_tech_level,
          'current', v_current_level
        );
      END IF;
    END IF;
  END LOOP;

  IF jsonb_array_length(v_missing_reqs) > 0 THEN
    RETURN jsonb_build_object('valid', false, 'missing', v_missing_reqs);
  END IF;

  RETURN jsonb_build_object('valid', true);
END;
$$;


--
-- TOC entry 636 (class 1255 OID 18600)
-- Name: validate_building_requirements(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_building_requirements(p_user_id uuid, p_planet_id uuid, p_building_type_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN validate_building_requirements(p_planet_id, p_building_type_id);
END;
$$;


