-- TOC entry 458 (class 1259 OID 22307)
-- Name: hero_duel_active_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hero_duel_active_view AS
 SELECT hd.id,
    hd.creator_id,
    hd.opponent_id,
    hd.status,
    hd.stake,
    hd.winner_id,
    hd.resolves_at,
    hd.created_at,
    COALESCE(c.username, 'Unknown'::text) AS creator_username,
    COALESCE(o.username, 'Unknown'::text) AS opponent_username,
    hd.creator_level,
    hd.opponent_level,
        CASE
            WHEN (hd.winner_id IS NOT NULL) THEN (hd.stake * 2)
            ELSE NULL::integer
        END AS winner_amount
   FROM ((public.hero_duels hd
     LEFT JOIN public.profiles c ON ((c.id = hd.creator_id)))
     LEFT JOIN public.profiles o ON ((o.id = hd.opponent_id)));


