--
-- TOC entry 461 (class 1259 OID 22322)
-- Name: hero_ship_ranking_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hero_ship_ranking_view AS
 WITH wins AS (
         SELECT hero_duels.winner_id AS user_id,
            count(*) AS cnt
           FROM public.hero_duels
          WHERE (hero_duels.status = 'completed'::text)
          GROUP BY hero_duels.winner_id
        ), losses AS (
         SELECT hero_duels.loser_id AS user_id,
            count(*) AS cnt
           FROM public.hero_duels
          WHERE (hero_duels.status = 'completed'::text)
          GROUP BY hero_duels.loser_id
        ), agg AS (
         SELECT COALESCE(w_1.user_id, l.user_id) AS user_id,
            COALESCE(w_1.cnt, (0)::bigint) AS wins,
            COALESCE(l.cnt, (0)::bigint) AS losses,
            (COALESCE(w_1.cnt, (0)::bigint) + COALESCE(l.cnt, (0)::bigint)) AS total_battles,
                CASE
                    WHEN ((COALESCE(w_1.cnt, (0)::bigint) + COALESCE(l.cnt, (0)::bigint)) > 0) THEN round((((COALESCE(w_1.cnt, (0)::bigint))::numeric / ((COALESCE(w_1.cnt, (0)::bigint) + COALESCE(l.cnt, (0)::bigint)))::numeric) * (100)::numeric), 1)
                    ELSE (0)::numeric
                END AS win_rate
           FROM (wins w_1
             FULL JOIN losses l ON ((l.user_id = w_1.user_id)))
        )
 SELECT (row_number() OVER (ORDER BY a.wins DESC, a.win_rate DESC, a.total_battles DESC))::integer AS rank,
    a.user_id,
    p.username,
    p.avatar_url,
    a.wins,
    a.losses,
    a.total_battles,
    a.win_rate,
    COALESCE(s.level, 1) AS level,
    COALESCE(s.xp, 0) AS xp,
    COALESCE(s.hp, 100) AS hp,
    COALESCE(s.hp_max, 100) AS hp_max,
    s.attack_points,
    s.defense_points,
    s.shield_points,
    s.speed_points,
    w.name AS weapon_name,
    w.rarity AS weapon_rarity,
    sh.name AS shield_name,
    sh.rarity AS shield_rarity,
    m.name AS module_name,
    m.rarity AS module_rarity,
    r.name AS reactor_name,
    r.rarity AS reactor_rarity
   FROM ((((((agg a
     LEFT JOIN public.profiles p ON ((p.id = a.user_id)))
     LEFT JOIN public.user_hero_ships s ON ((s.user_id = a.user_id)))
     LEFT JOIN public.hero_ship_items w ON ((w.id = s.weapon_slot)))
     LEFT JOIN public.hero_ship_items sh ON ((sh.id = s.shield_slot)))
     LEFT JOIN public.hero_ship_items m ON ((m.id = s.module_slot)))
     LEFT JOIN public.hero_ship_items r ON ((r.id = s.reactor_slot)))
  WHERE ((p.is_admin IS NOT TRUE) OR (p.is_admin IS NULL))
  ORDER BY a.wins DESC, a.win_rate DESC, a.total_battles DESC;


